import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IContentReport";

/**
 * Validate that guests cannot create content reports for non-existent posts, enforcing foreign key constraints and proper error messaging.
 *
 * Business Context:
 * Guests should only be able to report actual posts. Reporting a non-existent post could indicate a client bug, user tampering, or abuse attempt. Proper validation secures the moderation pipeline and upholds referential integrity.
 *
 * Steps:
 * 1. Attempt to create a content report as a guest using a random (non-existent) UUID as reported_post_id.
 * 2. Use other fields with valid/random data as required.
 * 3. Expect the API to reject the report with a meaningful error.
 * 4. Validate that the error is indeed thrown, confirming enforcement of the foreign key constraint and server-side validation logic.
 */
export async function test_api_prefix_guest_contentReports_test_create_content_report_as_guest_with_invalid_post_id(connection: api.IConnection) {
  // 1. Generate a random UUID that is guaranteed not to represent a real post.
  const invalid_post_id: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();

  // 2. Assemble report payload with the invalid post ID.
  const payload: IContentReport.ICreate = {
    reported_post_id: invalid_post_id,
    reporter_member_id: null, // Guest report
    reporter_guest_id: typia.random<string & tags.Format<"uuid">>(),
    report_reason: "Inappropriate content",
    status: "pending",
    reported_at: new Date().toISOString(),
    moderator_note: null
  };

  // 3. Attempt to submit the report and expect a foreign key/validation error.
  await TestValidator.error("Should not allow reporting non-existent post")(
    async () => {
      await api.functional.prefix.guest.contentReports.create(connection, { body: payload });
    }
  );
}

