import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * Test the creation of a permanent ban record for a guest via the admin bans creation endpoint.
 *
 * This test ensures that when only a guest-specific field (banned_guest_id) is provided—without member fields—a valid ban is successfully created. It also checks that no member fields exist, compliance with admin assignment, and validates all required fields such as reason and timestamps. The test further asserts that the returned ban record contains the correct guest-based identifiers and no member-based identifiers.
 * 
 * Workflow:
 * 1. Prepare random UUIDs for admin and guest.
 * 2. Call the ban creation API, supplying only banned_guest_id (not banned_member_id).
 * 3. Confirm the returned ban record:
 *      - has the supplied guest_id,
 *      - has null/undefined member_id,
 *      - admin_id matches,
 *      - ban reason and timestamp are correct.
 * 4. Optionally: Confirm output validates the schema and all required fields are present.
 */
export async function test_api_prefix_admin_bans_test_create_ban_for_guest_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Prepare sample admin and guest IDs
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const guestId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  const reason = "Violation of rules (guest test)";

  // 2. Make the ban creation request
  const result = await api.functional.prefix.admin.bans.create(connection, {
    body: {
      banned_guest_id: guestId,
      banned_member_id: null, // Explicit null to ensure guest-only
      admin_id: adminId,
      ban_reason: reason,
      banned_at: now,
      notes: null,
    } satisfies IDiscussionboardBan.ICreate,
  });
  typia.assert(result);

  // 3. Field checks
  TestValidator.equals("banned_guest_id matches")(result.banned_guest_id)(guestId);
  TestValidator.equals("banned_member_id is null")(result.banned_member_id)(null);
  TestValidator.equals("admin_id matches")(result.admin_id)(adminId);
  TestValidator.equals("ban reason matches")(result.ban_reason)(reason);
  TestValidator.equals("banned_at matches")(result.banned_at)(now);
  TestValidator.equals("notes is null")(result.notes)(null);
}

