import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IContentReport";

/**
 * Validate creation of a content report by a guest user with all required fields present.
 *
 * This test ensures that a guest user can successfully file a content report with the schema-compliant payload including: reported_post_id, reporter_guest_id, report_reason, status, and reported_at. It will verify that the returned IContentReport record matches the input, the reporter_guest_id is correctly set (and reporter_member_id is not used), and all business validation rules for guests are enforced (notably, a guest cannot impersonate or pass a reporter_member_id).
 *
 * Steps:
 * 1. Generate a random reported_post_id and guest UUID to simulate a guest reporter and reported post.
 * 2. Submit the content report with all required fields.
 * 3. Assert that the API response matches the sent payload.
 * 4. Assert that reporter_guest_id is set and reporter_member_id is null or undefined.
 * 5. Attempt (and expect failure) to submit a report as a guest with reporter_member_id populated.
 */
export async function test_api_prefix_guest_contentReports_test_create_content_report_as_guest_with_valid_data(connection: api.IConnection) {
  // 1. Prepare input for a valid guest report
  const input: IContentReport.ICreate = {
    reported_post_id: typia.random<string & tags.Format<"uuid">>(),
    reporter_guest_id: typia.random<string & tags.Format<"uuid">>(),
    report_reason: "Inappropriate content detected by guest.",
    status: "pending",
    reported_at: new Date().toISOString(),
  };

  // 2. Submit the report as a guest
  const output: IContentReport = await api.functional.prefix.guest.contentReports.create(connection, { body: input });
  typia.assert(output);

  // 3. Validate response matches the input data
  TestValidator.equals("reported_post_id matches")(output.reported_post_id)(input.reported_post_id);
  TestValidator.equals("reporter_guest_id matches")(output.reporter_guest_id)(input.reporter_guest_id);
  TestValidator.equals("report_reason matches")(output.report_reason)(input.report_reason);
  TestValidator.equals("status matches")(output.status)(input.status);
  TestValidator.equals("reported_at matches")(output.reported_at)(input.reported_at);
  TestValidator.equals("reporter_member_id should not be set for guest")(output.reporter_member_id)(null);

  // 4. Guest should not be able to pass a reporter_member_id (business rule)
  const badInput: IContentReport.ICreate = {
    ...input,
    reporter_member_id: typia.random<string & tags.Format<"uuid">>(),
  };
  await TestValidator.error("guest cannot use reporter_member_id")(async () => {
    await api.functional.prefix.guest.contentReports.create(connection, { body: badInput });
  });
}

