import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCategory";

/**
 * Validate fetching a single discussion board category by id as an admin.
 *
 * This test ensures the admin can retrieve detail information for a created discussion board category via its id.
 * It verifies the detailed endpoint returns correct data and the information matches exactly what was set at creation time (id, section, name, description, order, enabled).
 *
 * Step-by-step process:
 * 1. Create a new discussion board category (with all required data fields, covering string, number, optional property, and boolean)
 * 2. Retrieve this category via GET by id
 * 3. Assert that each returned field matches what was set at creation (including optional description)
 * 4. Confirm the result is not null and is present
 */
export async function test_api_discussionboardCategories_test_get_discussionboard_category_by_id_success(
  connection: api.IConnection,
) {
  // 1. Create a new discussion board category
  const createInput: IDiscussionboardCategory.ICreate = {
    discussionboard_section_id: typia.random<string & tags.Format<"uuid">>(),
    name: "AI Test Category",
    description: "E2E test case for category-by-id detail fetch",
    order: typia.random<number & tags.Type<"int32">>(),
    enabled: true,
  };
  const created: IDiscussionboardCategory = await api.functional.prefix.admin.discussionboardCategories.create(
      connection,
      { body: createInput }
  );
  typia.assert(created);

  // 2. Retrieve the category by id
  const fetched: IDiscussionboardCategory = await api.functional.prefix.admin.discussionboardCategories.at(
    connection,
    { categoryId: created.id }
  );
  typia.assert(fetched);

  // 3. Assert all fields match
  TestValidator.equals("id")(fetched.id)(created.id);
  TestValidator.equals("section id")(fetched.discussionboard_section_id)(createInput.discussionboard_section_id);
  TestValidator.equals("name")(fetched.name)(createInput.name);
  TestValidator.equals("description")(fetched.description)(createInput.description ?? null);
  TestValidator.equals("order")(fetched.order)(createInput.order);
  TestValidator.equals("enabled")(fetched.enabled)(createInput.enabled);

  // 4. Present and type validation
  TestValidator.predicate("category fetched is defined")(!!fetched);
}

