/**
 * Validates that creating a business rule fails when required fields are omitted.
 *
 * This test verifies the backend's validation logic for the business rule creation endpoint (`POST /prefix/admin//policyAudit/businessRules`). Specifically, it ensures that omitting any required field (`rule_code` or `title`) in the request body triggers a validation error. According to the API contract and DTO definitions, both `rule_code` and `title` are mandatory. Submitting a request without either field should result in a rejection and no record should be created.
 *
 * Test process:
 * 1. Attempt to create a business rule omitting only the `rule_code` field, providing valid values for all other required fields.
 *    - Expectation: API should return a validation error, and record must not be created.
 * 2. Attempt to create a business rule omitting only the `title` field, providing valid values for all other required fields.
 *    - Expectation: API should return a validation error, and record must not be created.
 * 3. Attempt to create a business rule omitting both `rule_code` and `title` fields.
 *    - Expectation: API should return a validation error, and record must not be created.
 */
export async function test_api_prefix_admin_policyAudit_businessRules_test_create_business_rule_with_missing_required_fields(connection: api.IConnection) {
  // 1. Omit only `rule_code` field
  await TestValidator.error("missing rule_code triggers validation error")(
    () =>
      api.functional.prefix.admin.policyAudit.businessRules.create(connection, {
        body: {
          // rule_code is omitted intentionally
          title: "Valid Title",
          description: "A test business rule missing rule_code.",
          is_active: true,
        } as any,
      })
  );

  // 2. Omit only `title` field
  await TestValidator.error("missing title triggers validation error")(
    () =>
      api.functional.prefix.admin.policyAudit.businessRules.create(connection, {
        body: {
          rule_code: "RULE_XYZ",
          // title is omitted intentionally
          description: "A test business rule missing title.",
          is_active: false,
        } as any,
      })
  );

  // 3. Omit both `rule_code` and `title`
  await TestValidator.error("missing both rule_code and title triggers validation error")(
    () =>
