 * 3. As an authorized admin, call the create admin assignment API with the generated id and timestamp.
 * 4. Validate that the response contains matching id, created_at, and all schema fields populated.
 * 5. Confirm via type assertion.
 * 6. Attempt to create duplicate assignment for the same UUID; expect error.
 * 7. Generate another random UUID (simulate invalid/non-existent user ID).
 * 8. Attempt to assign admin role using this invalid UUID; expect error (foreign key/business error).
 */
export async function test_api_prefix_admin_actors_admins_create(
  connection: api.IConnection,
) {
  // 1. Generate a random UUID for admin assignment (simulate valid user id).
  const validUserId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
