    async () =>
      api.functional.prefix.admin.actors.admins.create(connection, {
        body: {
          id: validUserId,
          created_at: new Date().toISOString() as string & tags.Format<"date-time">,
        } satisfies IDiscussionboardAdmin.ICreate,
      }),
  );

  // 4. Attempt to assign admin role with invalid UUID (foreign key error expected)
  const invalidUserId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("assignment for invalid user should fail")(
    async () =>
      api.functional.prefix.admin.actors.admins.create(connection, {
        body: {
          id: invalidUserId,
          created_at: new Date().toISOString() as string & tags.Format<"date-time">,
        } satisfies IDiscussionboardAdmin.ICreate,
      }),
  );
