import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBusinessRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBusinessRule";

/**
 * Test successful update of an existing policy audit business rule.
 *
 * This test ensures that a business rule can be created and then updated, with changes correctly persisted.
 *
 * Steps:
 * 1. Create a new business rule for testing using the admin API.
 * 2. Update one or more fields (e.g., title, description, is_active) via the PUT endpoint.
 * 3. Confirm the response reflects the updated data and that the changes have been saved.
 */
export async function test_api_policyAudit_test_update_policy_audit_business_rule_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Create a new business rule
  const createInput: IDiscussionboardBusinessRule.ICreate = {
    rule_code: "RULE_" + RandomGenerator.alphaNumeric(8),
    title: "Initial Test Rule Title",
    description: "Initial test rule description for update scenario.",
    is_active: true,
  };

  const createdRule: IDiscussionboardBusinessRule = await api.functional.prefix.admin.policyAudit.businessRules.create(
    connection,
    { body: createInput },
  );
  typia.assert(createdRule);

  // 2. Prepare update data (change title and is_active)
  const updateInput: IDiscussionboardBusinessRule.IUpdate = {
    title: "Updated Test Rule Title",
    description: "Updated test rule description.",
    is_active: false,
  };

  const updatedRule: IDiscussionboardBusinessRule = await api.functional.prefix.admin.policyAudit.businessRules.update(
    connection,
    {
      businessRuleId: createdRule.id,
      body: updateInput,
    },
  );
  typia.assert(updatedRule);

  // 3. Assert response reflects updates
  TestValidator.equals("updated id matches")(updatedRule.id)(createdRule.id);
  TestValidator.equals("updated title matches")(updatedRule.title)(updateInput.title);
  TestValidator.equals("updated description matches")(updatedRule.description)(updateInput.description);
  TestValidator.equals("updated is_active matches")(updatedRule.is_active)(updateInput.is_active);

  // Ensure unmodified fields remain unchanged
  TestValidator.equals("rule_code unchanged")(updatedRule.rule_code)(createdRule.rule_code);
}

