 * 2. 생성 결과로부터 세션의 id(즉, UUID)를 획득.
 * 3. 동일한 id로 body의 나머지 값을 일부 변경해 다시 세션 생성 API 재시도(즉, PK(UUID) 중복).
 * 4. 두 번째 시도에서는 반드시 오류(409 Conflict 또는 schema validation 등)가 발생해야 함을 검증. (성공 시에는 실패로 간주)
 */
export async function test_api_prefix_auth_sessions_test_create_auth_session_with_duplicate_id(
  connection: api.IConnection,
) {
  // 1. 무작위 세션 body 생성 및 최초 세션 생성
  const body: IDiscussionboardAuthSessions.ICreate = {
    actor_type: "member",
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    issued_at: new Date().toISOString(),
    expires_at: new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(),
    ip_address: "192.168.1.123",
    user_agent: "Mozilla/5.0 (X11; Linux x86_64)"
  };
  const firstSession = await api.functional.prefix.auth.sessions.create(connection, { body });
  typia.assert(firstSession);

  // 2. 동일한 id로 두 번째 body 구성 - 일부 값 변경
  const duplicateBody: IDiscussionboardAuthSessions.ICreate = {
    ...body,
    // actor_type 과 기타 값 변경
    actor_type: "admin",
    ip_address: "192.168.9.100",
    user_agent: "TestAgent/2.0"
  };
  // 3. 중복 id로 세션 생성 시도 -> 오류 발생 기대
  await TestValidator.error("중복된 세션 ID로 생성 시도 시 오류가 발생해야 함")(
