 *
 * This test attempts to delete an incident report as an unauthorized actor (such as a member or guest).
 * It ensures the operation is forbidden, confirming only moderators and admins can perform deletion.
 *
 * Steps:
 * 1. Moderator creates a valid incident report
 * 2. Switch to a non-privileged (guest or member) connection
 * 3. Attempt to delete the report as unauthorized user
 * 4. Operation must be rejected (forbidden error)
 */
export async function test_api_prefix_moderator_policyAudit_incidentReports_test_delete_incident_report_unauthorized_role(
  connection: api.IConnection,
) {
  // 1. Moderator creates an incident report
  // (Assume the connection passed here is authorized as a moderator or admin for setup)
  const incidentReport = await api.functional.prefix.moderator.policyAudit.incidentReports.create(
    connection,
    {
      body: {
        incident_code: "INCIDENT-" + new Date().toISOString().replace(/[-T:.Z]/g, "") + "-001",
        status: "OPEN",
        reporter_id: null,
        description: "Test incident for unauthorized deletion check.",
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      } satisfies IDiscussionboardIncidentReport.ICreate,
    },
  );
  typia.assert(incidentReport);

  // 2. Switch to an unauthorized connection (guest or member)
  // (Simulate unauthorized context by removing/sanitizing authorization header)
  const unauthorizedConnection: api.IConnection = {
    ...connection,
    headers: { ...connection.headers, Authorization: undefined },
  };

