/**
 * 인증 세션 ID로 단일 인증 세션 정보를 조회하여, 반환되는 모든 필드가 스키마 정의와 일치하는지 검증합니다.
 *
 * 실제 ID로 인증 세션을 조회하려면, 테스트 이전에 세션을 직접 생성해야 하므로
 * 다음과 같은 흐름으로 테스트 시나리오를 구성합니다.
 *
 * 1. IDiscussionboardAuthSessions.ICreate 타입의 입력값을 랜덤하게 생성하여 세션을 등록합니다.
 * 2. 반환된 결과에서 id 필드를 추출합니다.
 * 3. 생성된 id로 단일 세션 조회 API를 호출합니다.
 * 4. 조회 결과로 반환된 객체가 IDiscussionboardAuthSessions 타입과 일치하는지 typia.assert로 검증합니다.
 * 5. 모든 필드(id, actor_type, actor_id, issued_at, expires_at, last_activity_at, revoked_at, ip_address, user_agent)가 존재하는지, 값이 동일한지 추가로 TestValidator로 비교 검증을 수행합니다.
 *
 * 이 테스트는 정상적인 ID로 단일 세션 조회시, 실제로 저장된 정보가 모두 올바르게 반환되는지 E2E 관점에서 보증합니다.
 */
export async function test_api_prefix_auth_sessions_test_get_auth_session_by_id_with_valid_id(connection: api.IConnection) {
  // 1. 인증 세션 생성
  const input: IDiscussionboardAuthSessions.ICreate = {
    actor_type: RandomGenerator.alphabets(8),
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    issued_at: new Date().toISOString(),
    expires_at: new Date(Date.now() + 1000 * 60 * 60).toISOString(), // 1시간 후 만료
    // 네트워크 정보는 optional → null also valid
    ip_address: RandomGenerator.alphaNumeric(10),
    user_agent: RandomGenerator.alphabets(6),
  };
  const created = await api.functional.prefix.auth.sessions.create(connection, { body: input });
  typia.assert(created);

  // 2. 반환된 id로 단일 인증 세션 조회
