  TestValidator.equals("issued_at")(found.issued_at)(input.issued_at);
  TestValidator.equals("expires_at")(found.expires_at)(input.expires_at);
  TestValidator.equals("ip_address")(found.ip_address)(input.ip_address);
  TestValidator.equals("user_agent")(found.user_agent)(input.user_agent);

  // optional 필드는 null이거나, DB 시스템에 의해 최신 정보로 업데이트될 수 있으므로 존재성/유형만 확인
