 *
 * This test verifies that an existing incident report can be updated by its ID, with changes limited strictly to permitted schema fields (such as status or description).
 * The test will:
 * 1. Create an incident report (using the dependency endpoint), storing important fields.
 * 2. Update the report's 'status' and 'description' fields (or other permitted fields), using the original id.
 * 3. Verify the API response is a fully formed incident report record with updated values.
 * 4. Validate that the updated report retains unchanged fields where not explicitly overwritten.
 * 5. Confirm values such as 'updated_at' change according to expectations.
 */
export async function test_api_prefix_admin_policyAudit_incidentReports_test_update_incident_report_successfully(connection: api.IConnection) {
  // 1. Create a new incident report as preparation
  const initial: IDiscussionboardIncidentReport = await api.functional.prefix.admin.policyAudit.incidentReports.create(connection, {
    body: {
      incident_code: `INCIDENT-${new Date().toISOString().replace(/[-:TZ.]/g, "").substring(0,15)}`,
      status: "OPEN",
      reporter_id: typia.random<string & tags.Format<"uuid">>(),
      description: "Initial report description for test.",
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    } satisfies IDiscussionboardIncidentReport.ICreate,
  });
  typia.assert(initial);
  // 2. Prepare update payload (modify status, description)
  const newStatus = "IN_REVIEW";
  const newDescription = "Moderator updated the report description.";
  const updatePayload: IDiscussionboardIncidentReport.IUpdate = {
    incident_code: initial.incident_code, // required in update schema
    status: newStatus,
    reporter_id: initial.reporter_id,
    description: newDescription,
    updated_at: new Date(Date.now() + 60000).toISOString(), // simulate updated_at as later
  };
  // 3. Update the incident report by its ID
  const updated: IDiscussionboardIncidentReport = await api.functional.prefix.admin.policyAudit.incidentReports.update(connection, {
    incidentReportId: initial.id,
    body: updatePayload,
  });
  typia.assert(updated);
  // 4. Verify updated fields
  TestValidator.equals("status updated")(updated.status)(newStatus);
  TestValidator.equals("description updated")(updated.description)(newDescription);
  TestValidator.equals("incident code persists")(updated.incident_code)(initial.incident_code);
  TestValidator.equals("reporter_id persists")(updated.reporter_id ?? null)(initial.reporter_id ?? null);
  TestValidator.equals("updated_at changes")(updated.updated_at)(updatePayload.updated_at);
  // 5. Unchanged fields: created_at must remain as before
  TestValidator.equals("created_at unchanged")(updated.created_at)(initial.created_at);
}

