 *
 * This test verifies that after creating a thread tag via the platform's member endpoint,
 * fetching that tag by its unique threadTagId returns the correct and complete set of details.
 * It ensures both the API's basic retrieval function and the integrity of stored tag properties.
 *
 * Test Workflow:
 * 1. Create a thread tag using the member thread tag creation endpoint.
 * 2. Use the returned tag's id as the threadTagId to fetch the tag via the detail endpoint.
 * 3. Assert that every relevant field from the retrieved tag matches the ones from creation response.
 */
export async function test_api_threadTags_test_retrieve_thread_tag_details_when_exists(
  connection: api.IConnection,
) {
  // 1. Create a thread tag for setup
  const createInput: IThreadTag.ICreate = {
    code: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.paragraph()(1),
    is_restricted: Math.random() > 0.5,
    is_hidden: Math.random() > 0.5,
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
