    banned_member_id: banMemberId,
    banned_guest_id: null,
    admin_id: banAdminId,
    ban_reason: "policy violation",
    banned_at: new Date().toISOString(),
    notes: "Initial test ban."
  } satisfies IDiscussionboardBan.ICreate;
  const createdBan = await api.functional.prefix.admin.bans.create(connection, { body: createBanBody });
  typia.assert(createdBan);

  // 2. Query with non-matching banned_member_id
