  // (ensure it's not the same as banMemberId)
  TestValidator.notEquals("random non-matching uuid")(banMemberId)(nonMatchingMemberId);
  const filterBody = {
    banned_member_id: nonMatchingMemberId
  } satisfies IBan.IRequest;
  const listResult = await api.functional.prefix.admin.bans.index(connection, { body: filterBody });
  typia.assert(listResult);

  // 3. Validate no results
  TestValidator.equals("no matched records")(listResult.data.length)(0);
  TestValidator.equals("pagination.records is 0")(listResult.pagination.records)(0);
  TestValidator.equals("pagination.pages is 0")(listResult.pagination.pages)(0);
}

