/**
 * Test that a moderator can update their own suspension log with valid schema-compliant fields.
 *
 * This test confirms that, when authenticated as a moderator, an update to a suspension record they own is correctly applied and reflected in the returned record. The allowed updatable fields include (but may not be limited to) suspension_reason and suspension_ends_at, following the type definition.
 *
 * Step-by-step plan:
 * 1. [Prerequisite] Create a suspension record using moderator privileges (using dependencies), confirming moderator_id matches the connected moderator.
 * 2. Prepare an ISuspension.IUpdate object with new valid values (change at least suspension_reason and/or suspension_ends_at).
 * 3. Call the update API as the owning moderator, targeting the record created in step 1.
 * 4. Assert that the API call is successful and the returned ISuspension record reflects the updated fields, with other immutable fields unchanged.
 */
export async function test_api_prefix_moderator_my_suspensions_test_update_own_suspension_with_valid_data(connection: api.IConnection) {
  // 1. Create a new suspension record for this moderator
  const origSuspension = await api.functional.prefix.moderator.suspensions.create(connection, {
    body: {
      moderator_id: typia.random<string & tags.Format<"uuid">>(),
      suspended_member_id: typia.random<string & tags.Format<"uuid">>(),
      suspension_reason: "Original reason for suspension",
      suspension_started_at: new Date().toISOString(),
      suspension_ends_at: null,
    },
  });
  typia.assert(origSuspension);

  // 2. Prepare a valid IUpdate object (change at least reason and/or ends_at)
  const newReason = "Updated reason for testing";
  const newEndsAt = new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(); // +1 day
  const updateBody: ISuspension.IUpdate = {
    suspension_reason: newReason,
    suspension_ends_at: newEndsAt,
  };

  // 3. Update the suspension via 'my' endpoint
  const updated = await api.functional.prefix.moderator.my.suspensions.update(connection, {
    id: origSuspension.id,
    body: updateBody,
  });
  typia.assert(updated);

  // 4. Validate changes
  TestValidator.equals("suspension_reason updated")(updated.suspension_reason)(newReason);
  TestValidator.equals("suspension_ends_at updated")(updated.suspension_ends_at)(newEndsAt);
  // immutable fields must not change
  TestValidator.equals("moderator_id unchanged")(updated.moderator_id)(origSuspension.moderator_id);
  TestValidator.equals("suspended_member_id unchanged")(updated.suspended_member_id)(origSuspension.suspended_member_id);
  TestValidator.equals("suspension_started_at unchanged")(updated.suspension_started_at)(origSuspension.suspension_started_at);
}

