  const reaction2 = await api.functional.prefix.member.postReactions.create(connection, { body: { discussionboard_post_id: postId1, discussionboard_member_id: memberId2, reaction_type: 'laugh' } });
  const reaction3 = await api.functional.prefix.member.postReactions.create(connection, { body: { discussionboard_post_id: postId2, discussionboard_member_id: memberId1, reaction_type: 'sad' } });
