import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * Validate retrieval of an existing ban record by its ID.
 *
 * This test scenario ensures that when an admin creates a ban record (for either a member or guest), the ban details can subsequently be retrieved correctly by its unique ID. It verifies accurate field mapping between the creation and retrieval APIs.
 *
 * Test Steps:
 * 1. Create a ban record via POST /prefix/admin//bans, supplying all necessary fields (targeting either a member or guest, but not both).
 * 2. Retrieve the ban record just created using GET /prefix/admin//bans/{id} with the ID returned from step 1.
 * 3. Validate that all returned fields from the GET endpoint match those of the created record and satisfy expected schema.
 */
export async function test_api_prefix_admin_bans_test_get_ban_by_id_with_existing_record(
  connection: api.IConnection,
) {
  // 1. Create a ban record (test with member ban, banned_guest_id null)
  const banCreateInput: IDiscussionboardBan.ICreate = {
    banned_member_id: typia.random<string & tags.Format<"uuid">>(),
    banned_guest_id: null,
    admin_id: typia.random<string & tags.Format<"uuid">>(),
    ban_reason: "Violation of forum rules - spam posting",
    banned_at: new Date().toISOString(),
    notes: "First offense, aggressive self-promotion as member."
  };
  const created: IDiscussionboardBan = await api.functional.prefix.admin.bans.create(connection, {
    body: banCreateInput,
  });
  typia.assert(created);

  // 2. Retrieve the ban by its ID
  const retrieved: IBan = await api.functional.prefix.admin.bans.at(connection, {
    id: created.id,
  });
  typia.assert(retrieved);

  // 3. Validate data mapping and correctness
  TestValidator.equals("ban id")(retrieved.id)(created.id);
  TestValidator.equals("admin id")(retrieved.admin_id)(banCreateInput.admin_id);
  TestValidator.equals("banned member")(retrieved.banned_member_id)(banCreateInput.banned_member_id);
  TestValidator.equals("banned guest")(retrieved.banned_guest_id)(banCreateInput.banned_guest_id);
  TestValidator.equals("ban reason")(retrieved.ban_reason)(banCreateInput.ban_reason);
  TestValidator.equals("banned at")(retrieved.banned_at)(banCreateInput.banned_at);
  TestValidator.equals("notes")(retrieved.notes)(banCreateInput.notes);
}

