 *  - If the API strictly validates request schemas: an error or validation failure is triggered when a non-schema property is present (e.g., { search_query: 'foo', __badField: 'oops' }).
 *  - If the API ignores unknown fields: these should have no effect on the filter query or results compared to a "clean" request.
 *
 * Steps:
 * 1. Submit a search history filter request with both valid (e.g., search_query) and an invalid field (non-schema property like '__badField').
 * 2. If the schema validator rejects unknown fields, assert that an error occurs (TestValidator.error).
 * 3. If the service ignores unknown fields, make two requests:
 *    a. One with a valid filter object only
 *    b. Another with the same filter plus the extra invalid field
 *    - Assert that the results (pagination, data) in both cases are equivalent using TestValidator.equals().
 * 4. Confirm that only schema fields affect query behavior, and extra fields do not add filtering or cause side-effects.
 */
export async function test_api_prefix_test_list_search_histories_invalid_filter_field(
  connection: api.IConnection,
) {
  // 1. Build valid filter
  const baseFilter: ISearchHistory.IRequest = { search_query: "unit_test_keyword" };

  // 2. Attempt request with invalid filter field
  const filterWithInvalid = { ...baseFilter, __badField: "should_be_ignored_or_error" };

  // 3. Expect rejection if strict validation, or equivalence otherwise
  let schemaRejected = false;
  try {
    const outputWithExtra = await api.functional.prefix.searchHistories.index(
      connection,
      { body: filterWithInvalid as any } // forcibly sending extra field
    );
    typia.assert(outputWithExtra);
    // 4. If accepted, also fetch using valid filter only
