 * This ensures record traceability while supporting administrative note correctness and refined reasoning.
 *
 * Test process:
 * 1. Create a ban record using the admin ban creation endpoint and capture all original values.
 * 2. Prepare new values for `ban_reason` and `notes`, including variant values (such as null or empty string) for the notes test.
 * 3. Call the ban update endpoint with the new reason and notes for the created ban's ID.
 * 4. Check that the API response includes updated reason and notes and that all the other fields remain identical to the original record.
 * 5. Use strong type assertions and field equality checks for both updated and preserved fields.
 * 6. Test both: updating with a different string and clearing notes to null.
 */
export async function test_api_prefix_test_update_ban_reason_and_notes_successfully(
  connection: api.IConnection,
) {
  // 1. Create a ban record (dependency)
  const original_create: IDiscussionboardBan = await api.functional.prefix.admin.bans.create(connection, {
    body: {
      admin_id: typia.random<string & tags.Format<"uuid">>(),
      ban_reason: "Spam Posting",
      banned_at: new Date().toISOString(),
      notes: "Initial note",
      banned_member_id: typia.random<string & tags.Format<"uuid">>(),
      banned_guest_id: null
    } satisfies IDiscussionboardBan.ICreate
  });
  typia.assert(original_create);

  // 2. Update ban_reason and notes
  const updatedBanReason = "Changed reason for moderation";
  const updatedNotes = "Updated notes on investigation.";

  const updated: IDiscussionboardBan = await api.functional.prefix.admin.my.bans.update(connection, {
    id: original_create.id,
    body: {
      ban_reason: updatedBanReason,
      notes: updatedNotes
    } satisfies IDiscussionboardBan.IUpdate
  });
  typia.assert(updated);

  // 3. Validate updated fields are changed and immutables are preserved
  TestValidator.equals("ban_reason updated")(updated.ban_reason)(updatedBanReason);
  TestValidator.equals("notes updated")(updated.notes)(updatedNotes);
  TestValidator.equals("banned_member_id unchanged")(updated.banned_member_id)(original_create.banned_member_id);
  TestValidator.equals("banned_guest_id unchanged")(updated.banned_guest_id)(original_create.banned_guest_id);
  TestValidator.equals("admin_id unchanged")(updated.admin_id)(original_create.admin_id);
  TestValidator.equals("banned_at unchanged")(updated.banned_at)(original_create.banned_at);

  // 4. Also test clearing notes (set to null)
