    id: original_create.id,
    body: { notes: null } satisfies IDiscussionboardBan.IUpdate
  });
  typia.assert(cleared);
  TestValidator.equals("notes cleared")(cleared.notes)(null);
  TestValidator.equals("ban_reason remains unchanged")(cleared.ban_reason)(updatedBanReason);
  TestValidator.equals("banned_member_id still unchanged")(cleared.banned_member_id)(original_create.banned_member_id);
  TestValidator.equals("banned_guest_id still unchanged")(cleared.banned_guest_id)(original_create.banned_guest_id);
  TestValidator.equals("admin_id still unchanged")(cleared.admin_id)(original_create.admin_id);
  TestValidator.equals("banned_at still unchanged")(cleared.banned_at)(original_create.banned_at);
