import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardConfiguration";

/**
 * Test successful update of a discussion board configuration.
 *
 * This test covers the following workflow:
 * 1. Create a new configuration using POST, providing a unique name, settings_json, and optional description.
 * 2. Update mutable fields (name, settings_json, description) using the PUT endpoint for that configurationId.
 * 3. Verify the response: the returned record reflects the updates, the configurationId matches, and that changed fields are persisted (old and new values are checked).
 * 4. Additionally, check that the name field maintains uniqueness: after update, create another configuration using the new name and confirm it fails (enforces unique name constraint).
 */
export async function test_api_prefix_admin_discussionboardConfigurations_test_update_discussion_board_configuration_successfully(
  connection: api.IConnection,
) {
  // 1. Create a new configuration
  const createInput: IDiscussionboardConfiguration.ICreate = {
    name: `test-unique-config-${RandomGenerator.hash()}`,
    settings_json: JSON.stringify({ postsPerDay: 10, moderation: true }),
    description: "Initial configuration, for update test",
  };
  const created = await api.functional.prefix.admin.discussionboardConfigurations.create(connection, { body: createInput });
  typia.assert(created);

  // 2. Update permissible fields (name, settings_json, description)
  const updateInput: IDiscussionboardConfiguration.IUpdate = {
    name: `${createInput.name}-updated`,
    settings_json: JSON.stringify({ postsPerDay: 20, moderation: false }),
    description: "Updated configuration name, settings, and description.",
  };
  const updated = await api.functional.prefix.admin.discussionboardConfigurations.update(connection, {
    configurationId: created.id,
    body: updateInput,
  });
  typia.assert(updated);

  // 3. Verify changes are persisted and configurationId remains the same
  TestValidator.equals("updated id matches created id")(updated.id)(created.id);
  TestValidator.notEquals("updated name")(updated.name)(createInput.name);
  TestValidator.equals("updated name matches")(updated.name)(updateInput.name);
  TestValidator.equals("updated settings_json matches")(updated.settings_json)(updateInput.settings_json);
  TestValidator.equals("updated description matches")(updated.description)(updateInput.description);

  // 4. Uniqueness check: attempt to reuse the updated name and expect failure
  await TestValidator.error("duplicate configuration name should fail")(
    async () => {
      await api.functional.prefix.admin.discussionboardConfigurations.create(connection, {
        body: {
          name: updateInput.name!, // same as updated name
          settings_json: JSON.stringify({ feature: true }),
          description: "Attempt to use duplicate name.",
        },
      });
    },
  );
}

