import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { discussionboard_alerts } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboard_alerts";

/**
 * Test creating a new alert for the authenticated member with valid data.
 *
 * This test verifies that an authenticated member can successfully create a new alert using valid values for all writable fields (type, severity, title, body, is_active).
 * The test checks that:
 * 1. The created alert is returned as a complete object, containing all schema fields (id, discussionboard_member_id, type, severity, title, body, is_active, created_at, resolved_at).
 * 2. The alert is associated with the authenticated member (i.e., the returned discussionboard_member_id is automatically set by the backend, not by the client input).
 * 3. No extra or non-existent fields are present in the response.
 *
 * Steps:
 * 1. Generate valid random data for all writable fields (type, severity, title, body, is_active).
 * 2. Call the API to create the alert as the authenticated member.
 * 3. Verify the alert response contains exactly the defined schema fields.
 * 4. Verify the returned type, severity, title, body, is_active fields match the input.
 * 5. Verify required system fields (id: uuid, created_at: date-time, discussionboard_member_id: uuid) are set and have correct formats.
 * 6. Confirm no extra/non-schema fields exist on the response object.
 */
export async function test_api_prefix_member_my_discussionboardAlerts_create(
  connection: api.IConnection,
) {
  // 1. Prepare valid request data according to schema
  const input: discussionboard_alerts.ICreate = {
    type: RandomGenerator.pick([
      "suspension_warning", "policy_update", "comment_flagged", "custom_notice"
    ]),
    severity: RandomGenerator.pick(["critical", "warning", "info"]),
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.content()()(1),
    is_active: true,
  };

  // 2. Create alert API request as an authenticated member
  const alert = await api.functional.prefix.member.my.discussionboardAlerts.create(
    connection,
    { body: input },
  );
  typia.assert(alert);

  // 3. Verify all and only schema fields exist in output
  const SCHEMA_KEYS = [
    "id",
    "discussionboard_member_id",
    "type",
    "severity",
    "title",
    "body",
    "is_active",
    "created_at",
    "resolved_at"
  ];
  TestValidator.equals("output fields match schema")(
    Object.keys(alert).sort()
  )(
    SCHEMA_KEYS.sort()
  );

  // 4. Confirm returned fields match the input and are valid
  TestValidator.equals("alert type matches")(alert.type)(input.type);
  TestValidator.equals("alert severity matches")(alert.severity)(input.severity);
  TestValidator.equals("alert title matches")(alert.title)(input.title);
  TestValidator.equals("alert body matches")(alert.body)(input.body);
  TestValidator.equals("alert is_active matches")(alert.is_active)(input.is_active);

  // 5. Validate backend-assigned fields: id, member_id, created_at
  TestValidator.predicate("id is uuid")(typeof alert.id === "string" &&
    /[0-9a-fA-F-]{36}/.test(alert.id));
  TestValidator.predicate("discussionboard_member_id is uuid")(
    typeof alert.discussionboard_member_id === "string" &&
      /[0-9a-fA-F-]{36}/.test(alert.discussionboard_member_id)
  );
  TestValidator.predicate("created_at is ISO8601 date-time")(
    typeof alert.created_at === "string" &&
      !isNaN(Date.parse(alert.created_at))
  );
  // 6. resolved_at is optional: can be null or date-time string
  if (alert.resolved_at !== undefined && alert.resolved_at !== null)
    TestValidator.predicate("resolved_at is date-time")(
      typeof alert.resolved_at === "string" &&
        !isNaN(Date.parse(alert.resolved_at))
    );
}

