/**
 * Test updating a notification for the authenticated member.
 *
 * 1. Register a member (who is the resource owner and will become authenticated)
 * 2. Create a notification for that member (using the API, which associates the new notification to the authenticated user)
 * 3. Update one or more of the notification's updatable fields (title, body, opened, type, url)
 * 4. Verify that the returned updated notification reflects the changes to updated fields
 * 5. Verify that non-updatable fields (id, discussionboard_member_id, created_at, opened_at, deleted_at) did not change except as allowed by business logic
 */
export async function test_api_discussionboard_notifications_test_update_notification_with_valid_fields(connection: api.IConnection) {
  // 1. Register a new member
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const memberCreatedAt = new Date().toISOString();
  const member = await api.functional.prefix.member.actors.members.create(connection, {
    body: {
      id: memberId,
      created_at: memberCreatedAt
    } satisfies IDiscussionboardMembers.ICreate
  });
  typia.assert(member);

  // 2. Create a notification as that member (API associates to current authenticated user)
  const originalNotificationInput: discussionboard_notifications.ICreate = {
    type: "mention",
    title: "Original title",
    body: "Original body",
    url: "/thread/1234",
    opened: false
  };
  const notification = await api.functional.prefix.member.my.discussionboardNotifications.create(connection, {
    body: originalNotificationInput
  });
  typia.assert(notification);

  // 3. Prepare update input with new values for several fields
  const updateInput: discussionboard_notifications.IUpdate = {
    title: "Updated title",
    body: "Updated body",
    opened: true
    // could add type or url as well
  };

  // 4. Update the notification
  const updated = await api.functional.prefix.member.my.discussionboardNotifications.update(connection, {
    notificationId: notification.id,
    body: updateInput
  });
  typia.assert(updated);

  // 5. Validate that fields reflect updates; non-updatable fields stay the same
  TestValidator.equals("id unchanged")(updated.id)(notification.id);
  TestValidator.equals("discussionboard_member_id unchanged")(updated.discussionboard_member_id)(notification.discussionboard_member_id);
  TestValidator.equals("created_at unchanged")(updated.created_at)(notification.created_at);
  TestValidator.equals("title updated")(updated.title)(updateInput.title);
  TestValidator.equals("body updated")(updated.body)(updateInput.body);
  TestValidator.equals("opened updated")(updated.opened)(updateInput.opened);
}

