/**
 * E2E test for updating a member's own saved discussion board filter, valid updates and forbidden conditions.
 *
 * - Creates a filter via POST /prefix/member//my/filters
 * - Updates the filter successfully via PUT /prefix/member//my/filters/{filterId} (update name, definition, is_public)
 * - Verifies the updates are reflected in returned object
 * - Soft-deletes the filter via DELETE, then attempts to update (should fail)
 * - Attempts to update a filter belonging to someone else (should fail with not found/forbidden error)
 * - Attempts to update a non-existent filter id (should fail with not found)
 * - Attempts update with extra fields not in schema (should be rejected)
 */
export async function test_api_prefix_member_my_filters_test_update_own_filter_valid_updates_and_forbidden_conditions(
  connection: api.IConnection,
) {
  // 1. Create a filter for the authenticated user
  const created = await api.functional.prefix.member.my.filters.create(connection, {
    body: {
      name: RandomGenerator.alphaNumeric(12),
      definition: JSON.stringify({ topic: RandomGenerator.alphaNumeric(6) }),
      is_public: false,
    } satisfies IDiscussionboardFilter.ICreate,
  });
  typia.assert(created);

  // 2. Update the filter: change name, definition, and is_public
  const updated = await api.functional.prefix.member.my.filters.update(connection, {
    filterId: created.id,
    body: {
      name: RandomGenerator.alphaNumeric(15),
      definition: JSON.stringify({ topic: RandomGenerator.alphaNumeric(8) }),
      is_public: true,
    } satisfies IDiscussionboardFilter.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("updated id")(updated.id)(created.id);
  TestValidator.equals("updated name")(updated.name)(updated.name);
  TestValidator.equals("updated definition")(updated.definition)(updated.definition);
  TestValidator.equals("is_public now true")(updated.is_public)(true);

  // 3. Soft-delete the filter
  const erased = await api.functional.prefix.member.my.filters.erase(connection, {
    filterId: created.id,
  });
  typia.assert(erased);

  // 4. Attempt to update soft-deleted filter -- should error
  await TestValidator.error("should not update soft-deleted filter")(async () => {
    await api.functional.prefix.member.my.filters.update(connection, {
      filterId: created.id,
      body: { name: "Should not work" },
    });
  });

