  // But since we can only act as one user per connection, we fake a random UUID
  await TestValidator.error("should not update filter not owned by this user")(async () => {
    await api.functional.prefix.member.my.filters.update(connection, {
      filterId: typia.random<string & tags.Format<"uuid">>(),
      body: { name: "No Access" },
    });
  });

  // 6. Attempt to update a non-existent filter id
  await TestValidator.error("should not update non-existent filter")(async () => {
    await api.functional.prefix.member.my.filters.update(connection, {
      filterId: typia.random<string & tags.Format<"uuid">>(),
      body: { definition: "{}" },
    });
  });

  // 7. Attempt to update with extra fields (should be rejected by typia/assert or API)
  await TestValidator.error("should reject update with extra fields")(async () => {
    await api.functional.prefix.member.my.filters.update(connection, {
      filterId: created.id,
      body: { name: "valid", extra_field: "not allowed" } as any, // Passes extra property intentionally
    });
