import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAppeal";
import type { IPageIDiscussionboardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardAppeal";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing and filtering of appeals as a moderator using various filters.
 *
 * This test function will:
 * 1. Create multiple appeal records with varied status, appellant_id, incident_id, and created_at values.
 * 2. Search for appeals using each filter (status, appellant_id, incident_id, created_at range), confirming only matching appeals are returned and unrelated records are excluded.
 * 3. Use pagination (page/limit), confirming correct subset of results is retrieved and pagination metadata is accurate.
 * 4. Use sorting (sort_by/sort_direction) and verify result ordering.
 * 5. Confirm all returned data is permitted for the moderator, and no unfiltered data leaks through.
 *
 * Coverage:
 * - Filtering by status
 * - Filtering by appellant_id
 * - Filtering by incident_id
 * - Filtering with created_after/created_before
 * - Pagination correctness
 * - Sorting by supported fields, with both asc/desc
 * - Data integrity and schema compliance
 */
export async function test_api_prefix_moderator_policyAudit_appeals_test_search_appeals_moderator_role_with_filters(connection: api.IConnection) {
  // 1. Create distinct appeal records for test diversity
  const baseDate = new Date();
  const statusSet = ["PENDING", "IN_REVIEW", "UPHELD", "REJECTED"];
  const appellantIds = [typia.random<string & tags.Format<"uuid">>(), typia.random<string & tags.Format<"uuid">>()];
  const incidentIds = [typia.random<string & tags.Format<"uuid">>(), typia.random<string & tags.Format<"uuid">>()];
  const appeals: IDiscussionboardAppeal[] = [];
  for (let i = 0; i < 6; ++i) {
    const status = statusSet[i % statusSet.length];
    const appellant_id = appellantIds[i % appellantIds.length];
    const incident_id = incidentIds[i % incidentIds.length];
    const created_at = new Date(baseDate.valueOf() - i * 24 * 60 * 60 * 1000).toISOString();
    const body: IDiscussionboardAppeal.ICreate = {
      appeal_code: `APPEAL-20240729-00${i + 1}`,
      status,
      appellant_id,
      incident_id,
      outcome: null,
      created_at,
      updated_at: created_at,
    };
    const created = await api.functional.prefix.moderator.policyAudit.appeals.create(connection, { body });
    typia.assert(created);
    appeals.push(created);
  }

  // 2. Filter by status - ensure only correct status is returned
  const filterStatus = statusSet[2]; // "UPHELD"
  const searchByStatus = await api.functional.prefix.moderator.policyAudit.appeals.index(connection, {
    body: { status: filterStatus },
  });
  typia.assert(searchByStatus);
  TestValidator.predicate("all returned have status UPHELD")(searchByStatus.data.every(a => a.status === filterStatus));

  // 3. Filter by appellant_id
  const filterAppellantId = appellantIds[1];
  const searchByAppellant = await api.functional.prefix.moderator.policyAudit.appeals.index(connection, {
    body: { appellant_id: filterAppellantId },
  });
  typia.assert(searchByAppellant);
  TestValidator.predicate("all returned match appellant_id")(searchByAppellant.data.every(a => a.appellant_id === filterAppellantId));

  // 4. Filter by incident_id
  const filterIncidentId = incidentIds[0];
  const searchByIncident = await api.functional.prefix.moderator.policyAudit.appeals.index(connection, {
    body: { incident_id: filterIncidentId },
  });
  typia.assert(searchByIncident);
  TestValidator.predicate("all returned match incident_id")(searchByIncident.data.every(a => a.incident_id === filterIncidentId));

  // 5. Filter by created_after/created_before
  const windowStart = appeals[2].created_at;
  const windowEnd = appeals[4].created_at;
  const searchByCreatedWindow = await api.functional.prefix.moderator.policyAudit.appeals.index(connection, {
    body: { created_after: windowEnd, created_before: windowStart },
  });
  typia.assert(searchByCreatedWindow);
  TestValidator.predicate("all returned within time window")(searchByCreatedWindow.data.every(a => a.created_at > windowEnd && a.created_at < windowStart));

  // 6. Pagination: limit=2, page=2
  const paged = await api.functional.prefix.moderator.policyAudit.appeals.index(connection, {
    body: { limit: 2, page: 2, sort_by: "created_at", sort_direction: "desc" },
  });
  typia.assert(paged);
  TestValidator.equals("pagination")(paged.pagination.limit)(2);
  TestValidator.equals("pagination page")(paged.pagination.current)(2);
  TestValidator.predicate("paged records <= limit")(paged.data.length <= 2);

  // 7. Sorting by created_at asc
  const sortedAsc = await api.functional.prefix.moderator.policyAudit.appeals.index(connection, {
    body: { sort_by: "created_at", sort_direction: "asc" },
  });
  typia.assert(sortedAsc);
  TestValidator.predicate("sorted ascending")(sortedAsc.data.every((a, i, arr) => i === 0 || a.created_at >= arr[i-1].created_at));

  // 8. Sorting by created_at desc
  const sortedDesc = await api.functional.prefix.moderator.policyAudit.appeals.index(connection, {
    body: { sort_by: "created_at", sort_direction: "desc" },
  });
  typia.assert(sortedDesc);
  TestValidator.predicate("sorted descending")(sortedDesc.data.every((a, i, arr) => i === 0 || a.created_at <= arr[i-1].created_at));

  // 9. All returned fields schema-compliant & only permitted data present
  for (const a of sortedDesc.data) {
    typia.assert(a);
    // Check only known fields present
    const appealKeys = Object.keys(a);
    const allowedKeys = [
      "id",
      "appeal_code",
      "status",
      "appellant_id",
      "incident_id",
      "outcome",
      "created_at",
      "updated_at",
    ];
    for (const key of appealKeys) {
      TestValidator.predicate(`no extra appeal field: ${key}`)(allowedKeys.includes(key));
    }
  }
}

