import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/ISuspension";

/**
 * Validate FAILURE: Admin cannot delete another admin's suspension record via /my/ endpoint.
 *
 * This test ensures that an admin account cannot hard-delete a suspension not owned by their own moderator_id through the ownership-protected /my/suspensions endpoint.
 * The test will:
 * 1. Create a suspension that is "owned" by a different moderator (i.e., not the logged-in admin's moderator_id).
 * 2. Attempt to delete this suspension as the current admin (who does NOT own the suspension).
 * 3. Expect an error due to insufficient ownership/authorization.
 * 
 * Note: The actual ownership model depends on moderator_id; this test will pass if server denies deletion based on moderator_id mismatch.
 */
export async function test_api_prefix_test_admin_fail_to_delete_unowned_suspension(
  connection: api.IConnection,
) {
  // 1. Setup: Create a "foreign" (other admin's) suspension record using a different moderator_id
  // (simulate another admin account by generating a different UUID)
  const otherModeratorId = typia.random<string & tags.Format<"uuid">>();
  const memberToSuspend = typia.random<string & tags.Format<"uuid">>();
  const suspension = await api.functional.prefix.admin.suspensions.create(connection, {
    body: {
      moderator_id: otherModeratorId,
      suspended_member_id: memberToSuspend,
      suspension_reason: "Test: created by other admin to check ownership",
      suspension_started_at: new Date().toISOString(),
      suspension_ends_at: null,
    } satisfies ISuspension.ICreate,
  });
  typia.assert(suspension);

  // 2. Action: Attempt DELETE via /my/suspensions/:id as (current) admin (should fail - not owner's suspension)
  await TestValidator.error("Admin cannot delete a suspension record not owned by them")(
    async () => {
      await api.functional.prefix.admin.my.suspensions.erase(
        connection,
        { id: suspension.id },
      );
    },
  );
}

