/**
 * Test retrieval of platform policies with different filters, sorting, and pagination options as an admin.
 *
 * Ensure that filtering by title, policy_code, is_active, and sorting by published_at/updated_at works correctly.
 *
 * Scenario covers:
 *   (1) default/all records
 *   (2) filter by title substring
 *   (3) filter by is_active=false
 *   (4) sorting by updated_at descending
 *   (5) pagination boundaries (first/last page)
 *   (6) requesting with empty or invalid filter keys
 *
 * Expect only actual schema fields in results, no extra or missing properties.
 * If schema fields do not exist or filters are invalid, backend should ignore or raise a validation error.
 * Only policies accessible by admin role should be returned.
 * No dependency on specific data (rely on at least several policies existing beforehand).
 */
export async function test_api_prefix_admin_policyAudit_platformPolicies_test_list_platform_policies_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a diverse set of platform policy records
  // We want at least three with unique codes, active/inactive status, and different titles/dates
  const now = new Date();
  const past = new Date(now.getTime() - 1000 * 60 * 60 * 24 * 90); // ~90 days ago
  const policies = [
    await api.functional.prefix.admin.policyAudit.platformPolicies.create(connection, {
      body: {
        title: "Alpha Policy",
        policy_code: "ALPHA123",
        policy_text: "Alpha content.",
        is_active: true,
      },
    }),
    await api.functional.prefix.admin.policyAudit.platformPolicies.create(connection, {
      body: {
        title: "Beta Guidelines",
        policy_code: "BETA456",
        policy_text: "Beta content.",
        is_active: true,
      },
    }),
    await api.functional.prefix.admin.policyAudit.platformPolicies.create(connection, {
      body: {
        title: "Inactive Gamma",
        policy_code: "GAMMA789",
        policy_text: "Gamma content.",
        is_active: false,
      },
    }),
  ];
  for (const p of policies) typia.assert(p);

  // (1) Default fetch: no filters, should retrieve all
  const res_all = await api.functional.prefix.admin.policyAudit.platformPolicies.index(connection, {
    body: {},
  });
  typia.assert(res_all);
  TestValidator.predicate("all records present")(policies.every(seed =>
    res_all.data.some(r => r.id === seed.id && r.title === seed.title && r.policy_code === seed.policy_code)
  ));

  // (2) Filter by title substring: "Alpha"
  const res_title = await api.functional.prefix.admin.policyAudit.platformPolicies.index(connection, {
    body: { title: "Alpha" },
  });
  typia.assert(res_title);
  TestValidator.predicate("only alpha policy returned")(res_title.data.every(r => r.title.includes("Alpha")));

  // (3) Filter by is_active: false (should only match the inactive one)
  const res_inactive = await api.functional.prefix.admin.policyAudit.platformPolicies.index(connection, {
    body: { is_active: false },
  });
  typia.assert(res_inactive);
  TestValidator.predicate("only inactive policies")(res_inactive.data.every(r => r.is_active === false));
  TestValidator.predicate("inactive gamma included")(res_inactive.data.some(r => r.id === policies[2].id));

  // (4) Sorting by updated_at descending. (assuming the API supports sorting internally)
  // (Note: API contract does not expose explicit sort param, but we check order for updated_at)
  const res_sorted = await api.functional.prefix.admin.policyAudit.platformPolicies.index(connection, {
    body: {},
