  typia.assert(res_sorted);
  const sortedIds = [...res_sorted.data].sort((a,b) => b.updated_at.localeCompare(a.updated_at)).map(r => r.id);
  TestValidator.equals("API returns descending updated_at order")(res_sorted.data.map(r=>r.id))(sortedIds);

  // (5) Test pagination boundaries (simulate with page-size slicing)
  if (res_all.data.length >= 2) {
    // Simulate paginated fetch using IRequest only, assuming API handles pagination params if present
