  // (6b) Empty filter object should still work
  const res_empty = await api.functional.prefix.admin.policyAudit.platformPolicies.index(connection, {
    body: {},
  });
  typia.assert(res_empty);
  TestValidator.predicate("empty filter succeeds")(res_empty.data.length >= policies.length);

  // Check schema compliance: only expected fields
  for (const {data} of [res_all,res_title,res_inactive,res_sorted,res_empty]) {
    for (const item of data)
      TestValidator.predicate("schema contains only official fields")(
        Object.keys(item).sort().join() === [
          "id","is_active","policy_code","policy_text","published_at","title","updated_at"
        ].sort().join()
      );
  }
}

