import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IWarningLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IWarningLog";

/**
 * 특정 경고 로그(id) 단건 조회 API의
 * 올바른 동작과 정책 준수를 검증한다.
 *
 * 비즈니스 규칙:
 * - 본 API는 모더레이터 또는 관리자라면 특정한 경고 로그의 상세 정보를 id 기반으로 언제든 조회 가능함을 보장한다
 * - 소유권 제약(=발급한 모더레이터와 요청자 동일성)에 제한받지 않으므로, 타 모더레이터가 발급한 경고 로그 조회도 지원해야 한다
 *
 * 테스트 순서:
 * 1. 신규 경고 로그 생성 (테스트 id 획득)
 * 2. 해당 id로 단건 상세 조회 및 모든 필드 정확성 확인 (id, moderator_id, warned_member_id, warning_reason, issued_at)
 * 3. 존재하지 않는 id로 요청 시 404/not found 반환 확인
 * 4. 타 모더레이터가 생성한 로그를 별도 id로 추가 생성 — 이 로그도 별도 id로 정상 조회 가능함을 확인
 */
export async function test_api_prefix_moderator_warningLogs_at(
  connection: api.IConnection,
) {
  // 1. 신규 경고 로그(본 모더레이터) 생성
  const warningLogInput: IWarningLog.ICreate = {
    moderator_id: typia.random<string & tags.Format<'uuid'>>(),
    warned_member_id: typia.random<string & tags.Format<'uuid'>>(),
    warning_reason: '테스트 경고(단건조회)',
    issued_at: new Date().toISOString() as string & tags.Format<'date-time'>,
  };
  const created: IWarningLog = await api.functional.prefix.moderator.warningLogs.create(connection, { body: warningLogInput });
  typia.assert(created);

  // 2. 단건 상세 조회(본 id)
  const fetched: IWarningLog = await api.functional.prefix.moderator.warningLogs.at(connection, { id: created.id });
  typia.assert(fetched);
  TestValidator.equals('id')(fetched.id)(created.id);
  TestValidator.equals('moderator_id')(fetched.moderator_id)(warningLogInput.moderator_id);
  TestValidator.equals('warned_member_id')(fetched.warned_member_id)(warningLogInput.warned_member_id);
  TestValidator.equals('warning_reason')(fetched.warning_reason)(warningLogInput.warning_reason);
  TestValidator.equals('issued_at')(fetched.issued_at)(warningLogInput.issued_at);

  // 3. 존재하지 않는 id 404 응답 검증
  const nonExistentId = typia.random<string & tags.Format<'uuid'>>();
  await TestValidator.error('not found for unknown id')(async () => {
