import type { IDiscussionboardTaggedThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardTaggedThread";

/**
 * 회원이 소유하지 않은 (다른 회원이 만든) thread-tag 연관관계 삭제 금지 검증
 *
 * 본 테스트의 목적은 thread-tag 연관관계 삭제가 반드시 해당 연관관계의 소유 회원에게만 허용됨을 검증하는 것이다. 즉, Member
 * A가 thread, tag, 그리고 association을 모두 생성한 후, Member B가 해당 association을 삭제 시도시
 * 403(forbidden) 또는 404(not found) 등 적절한 권한/존재 오류가 발생해야 한다.
 *
 * [시나리오]
 *
 * 1. (준비) Member A로 thread 생성
 * 2. Member A로 tag 생성
 * 3. Member A로 thread-tag association 생성
 * 4. Member B 계정으로 로그인 (Member B는 association의 소유 회원이 아님)
 * 5. Member B가 association 삭제 시도 → 권한오류/존재오류 발생여부 검증
 *
 * 실제 테스트 환경에서는 connection 객체를 회원별로 생성/전환해 사용할 것
 */
export async function test_api_prefix_member_taggedThreads_test_delete_tagged_thread_non_owner_forbidden(
  connection: api.IConnection,
) {
  // 1. Member A: thread 생성
  const threadCreationTime = new Date().toISOString();
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "MemberA Test Thread",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: threadCreationTime,
        updated_at: threadCreationTime,
      },
    },
  );
  typia.assert(thread);

  // 2. Member A: tag 생성
  const tagCreationTime = new Date().toISOString();
  const tag = await api.functional.prefix.member.threadTags.create(connection, {
    body: {
      code: `membera_tag_${Math.random().toString(36).substring(2, 10)}`,
      display_name: "MemberA Tag",
      description: "Tag for testing deletion access",
      is_restricted: false,
      is_hidden: false,
      created_at: tagCreationTime,
    },
  });
  typia.assert(tag);

  // 3. Member A: thread-tag association 생성
  const associationCreationTime = new Date().toISOString();
  const taggedThread = await api.functional.prefix.member.taggedThreads.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        discussionboard_thread_tag_id: tag.id,
        created_at: associationCreationTime,
      },
    },
  );
  typia.assert(taggedThread);

  // 4. Member B 계정으로 로그인 (여기서는 connection 교체 가정; 실제론 별도 인증 API 필요)
  // 실제 테스트 환경에서는 Member B의 인증토큰을 가진 connection으로 전환해야 함.
  // (본 예시에서는 connection 객체가 이미 Member B로 인증됨을 가정)

  // 5. Member B가 association 삭제 시도 → 권한오류/존재오류 발생 검증
  await TestValidator.error("타 회원 association 삭제 제한")(() =>
    api.functional.prefix.member.taggedThreads.erase(connection, {
      taggedThreadId: taggedThread.id,
    }),
  );
}

