/**
 * 게스트 레코드(익명 방문자 역할)를 멤버가 하드 삭제하는 시나리오의 성공 케이스를 검증합니다.
 *
 * - 특정 멤버가 게스트 역할을 신규 생성하여 관리하다가, 직접 삭제(하드 삭제)하는 전체 플로우를 테스트합니다.
 * - Discussionboard_guests 엔티티는 soft delete 개념 없이, 삭제 시점에 실제로 데이터베이스에서 영구 제거됩니다.
 * - 성공적으로 삭제된 이후에는 해당 id로 더 이상 같은 엔티티 조회/삭제가 불가능해야 하며, 본 테스트에서는 삭제 재요청 시 error(예:
 *   NOT FOUND 등)가 발생함을 통해 검증합니다.
 *
 * [테스트 절차]
 *
 * 1. 멤버 인증 상태에서 guest 역할 레코드를 하나 신규 생성한다.
 * 2. 방금 생성한 id로 DELETE(하드 삭제) 요청을 한다.
 * 3. 동일 id로 다시 DELETE를 요청하여 NOT FOUND(존재하지 않음, 이미 삭제됨 등) 에러가 반환되는지 검증한다.
 *
 * (주: 별도의 GET/검색 API가 정의되지 않아, 삭제 후 재요청을 통해 존재 확인)
 */
export async function test_api_prefix_member_my_actors_guests_test_delete_guest_record_successfully(
  connection: api.IConnection,
) {
  // 1. 멤버 인증 상태에서 guest 역할 신규 생성
  const guest = await api.functional.prefix.member.actors.guests.create(
    connection,
    {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      },
    },
  );
  typia.assert(guest);

  // 2. 방금 생성한 id로 DELETE(하드 삭제)
  await api.functional.prefix.member.my.actors.guests.erase(connection, {
    id: guest.id,
  });

  // 3. 동일 id로 삭제 재요청 시 에러 반환 (레코드가 더 이상 존재하지 않음을 의미)
  await TestValidator.error("이미 삭제된 guest id로 삭제 시도 시 에러 반환함")(
    () =>
      api.functional.prefix.member.my.actors.guests.erase(connection, {
        id: guest.id,
      }),
  );
}

