import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAuthSessions } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAuthSessions";

/**
 * 인증 세션(내 세션)을 스키마에 없는 필드(`deleted_at`)로 업데이트 시도 시 거부되는지 검증하는 테스트입니다.
 *
 * 실제 API 스키마에는 존재하지 않으나, 예를 들어 프론트엔드나 공격자가 임의로 `deleted_at`(또는 그 밖의 허용되지 않은 필드)를 update 요청의 body에 추가하는 경우 서버가 이를 엄격하게 거부(400 혹은 422 등 유효성 오류 반환)하는지 확인합니다.
 *
 * 테스트 개요:
 * 1. 사전 준비: 세션 레코드 생성 (dependencies 활용)
 * 2. 정상 필드만 있는 경우 update가 정상적으로 동작함을 확인
 * 3. 스키마에 정의되지 않은 필드(`deleted_at`)가 body에 포함된 경우 update 시 오류가 발생하는지 확인
 */
export async function test_api_prefix_member_my_auth_sessions_test_update_own_auth_session_with_forbidden_field(connection: api.IConnection) {
  // 1. 사전 준비: 세션 레코드 생성
  const session = await api.functional.prefix.auth.sessions.create(connection, {
    body: typia.random<IDiscussionboardAuthSessions.ICreate>(),
  });
  typia.assert(session);

  // 2. 정상 update: 스키마에 정의된 필드를 이용한 갱신이 성공함을 확인
  const updated = await api.functional.prefix.member.my.auth.sessions.update(connection, {
    id: session.id,
    body: { last_activity_at: new Date().toISOString() } satisfies IDiscussionboardAuthSessions.IUpdate,
  });
  typia.assert(updated);
  // 기본 필드 변경이 적용되는지 확인
  TestValidator.equals("세션 PK 유지됨")(updated.id)(session.id);
  TestValidator.equals("last_activity_at 업데이트됨")(updated.last_activity_at !== session.last_activity_at)(true);

  // 3. 금지 필드(`deleted_at`) 포함시 오류 발생 여부 확인
  // @ts-expect-error: 실제로는 타입 차단됨 -> 런타임에 직접 body를 `as any`로 보내는 상황 가정
  await TestValidator.error("스키마에 없는 필드 update 시도시 오류 반환")(
    async () => {
      // 아웃 오브 스키마 필드를 강제 삽입하여 테스트 (단, 타입 시스템 보호 아래 실제 사용 불가)
      await api.functional.prefix.member.my.auth.sessions.update(connection, {
        id: session.id,
        body: {
          last_activity_at: new Date().toISOString(),
          // @ts-ignore
          deleted_at: new Date().toISOString(),
        } as any,
      });
    },
  );
}

