import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardIncidentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardIncidentReport";
import type { IDiscussionboardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAppeal";
import type { IDiscussionboardAppeals } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAppeals";

/**
 * Test retrieval of an existing appeal by member using its valid id.
 *
 * This test simulates the business scenario where a member attempts to fetch a specific appeal that has been properly created and exists in the system. The purpose is to verify that the endpoint returns all expected fields for the appeal, and that permissions are handled correctly—i.e., only authorized users can view the appeal details. All schema fields are verified for correct population. The test ensures business logic for fetching appeal details is followed.
 *
 * Test Steps:
 * 1. Create a new incident report as a prerequisite (incident must exist for the appeal).
 * 2. Create a new appeal associated with that incident report (admin context).
 * 3. As a member, retrieve the appeal by its id using the 'getByAppealid' endpoint.
 * 4. Validate that the returned appeal matches the one created (fields: id, appeal_code, status, appellant_id, incident_id, outcome, created_at, updated_at).
 * 5. Assert all expected schema fields are correctly populated in the response.
 */
export async function test_api_policyAudit_test_get_existing_appeal_by_valid_id_as_member(
  connection: api.IConnection,
) {
  // 1. Create a new incident report (admin context)
  const incidentCreateInput: IDiscussionboardIncidentReport.ICreate = {
    incident_code: `INCIDENT-${new Date().toISOString().replace(/[-:T.]/g, '').slice(0, 8)}-001`,
    status: "OPEN",
    reporter_id: null,
    description: "Incident for appeal fetch testing.",
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  const incident = await api.functional.prefix.admin.policyAudit.incidentReports.create(connection, { body: incidentCreateInput });
  typia.assert(incident);

  // 2. Create a new appeal linked to the incident (admin context)
  const appealCreateInput: IDiscussionboardAppeal.ICreate = {
    appeal_code: `APPEAL-${new Date().toISOString().replace(/[-:T.]/g, '').slice(0, 8)}-001`,
    status: "PENDING",
    appellant_id: null,
    incident_id: incident.id,
    outcome: null,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  const createdAppeal = await api.functional.prefix.admin.policyAudit.appeals.create(connection, { body: appealCreateInput });
  typia.assert(createdAppeal);
  // Verify the important fields are populated
  TestValidator.equals("linked incident id")(createdAppeal.incident_id)(incident.id);
  TestValidator.equals("appeal_code matches")(createdAppeal.appeal_code)(appealCreateInput.appeal_code);

  // 3. Retrieve the created appeal as a member
  const fetchedAppeal = await api.functional.prefix.member.policyAudit.appeals.at(connection, { appealId: createdAppeal.id });
  typia.assert(fetchedAppeal);

  // 4. Validate all expected schema fields
  TestValidator.equals("appeal ID matches")(fetchedAppeal.id)(createdAppeal.id);
  TestValidator.equals("appeal_code matches")(fetchedAppeal.appeal_code)(createdAppeal.appeal_code);
  TestValidator.equals("status matches")(fetchedAppeal.status)(createdAppeal.status);
  TestValidator.equals("appellant_id matches")(fetchedAppeal.appellant_id)(createdAppeal.appellant_id);
  TestValidator.equals("incident_id matches")(fetchedAppeal.incident_id)(createdAppeal.incident_id);
  TestValidator.equals("outcome matches")(fetchedAppeal.outcome)(createdAppeal.outcome);
  TestValidator.equals("created_at matches")(fetchedAppeal.created_at)(createdAppeal.created_at);
  TestValidator.equals("updated_at matches")(fetchedAppeal.updated_at)(createdAppeal.updated_at);
}

