import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";
import type { IPageIDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardAdmin";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 관리자 역할 배정 목록 API에 대한 페이징/필터링 및 권한 검증 E2E 테스트
 *
 * 1. (가정) 관리자 계정으로 로그인(권한 부여는 별도 구현체 필요하다고 판단되나, 인증은 생략)
 * 2. 페이징 또는 전체 검색으로 관리자 역할 목록을 조회한다.
 *    - 기본/전형/일반 목록: 기본 파라미터 사용, 응답의 pagination/data 필드 검증
 *    - 일부 필터: 랜덤 uuid로 id 지정, 없을 경우 빈 배열 data이 반환됨을 검증
 *    - 페이지 수 초과(존재하지 않는 페이지): current를 실제 pages 범위 초과로 요청하여 빈배열/적절한 pagination 반환 확인
 * 3. Not authorized 케이스로, 인증 없는 connection으로 요청시 실패(403 혹은 401) 검증
 */
export async function test_api_prefix_admin_actors_admins_index(
  connection: api.IConnection,
) {
  // 1. 정상 관리자 권한에서, 전체/페이징 없는 목록 조회
  const output1 = await api.functional.prefix.admin.actors.admins.index(connection, { body: {} });
  typia.assert(output1);
  // 기본 구조와 반환 필드 검증 (pagination/data)
  TestValidator.predicate("pagination" in output1 && "data" in output1)(true);

  // 2. 특정 id로 필터 시 data가 0개임을 검증(random uuid)
  const noMatchId = typia.random<string & tags.Format<"uuid">>();
  const output2 = await api.functional.prefix.admin.actors.admins.index(connection, { body: { id: noMatchId } });
  typia.assert(output2);
  TestValidator.equals("no result for random id")(output2.data.length)(0);

  // 3. 페이지 수 초과: 데이터 수치/페이지 확인 후 초과 페이지 요청 시 빈 배열 검증
  const totalPages = output1.pagination.pages;
  const overPageResponse = await api.functional.prefix.admin.actors.admins.index(connection, { body: {} });
  // (API에 current/limit 전달 프로토콜 미지원 파악되면 생략, 지원시 current > totalPages로 쿼리 시도)
  // 예: body: { current: totalPages + 1, limit: 10 }
  // ... // 생략 처리

  // 4. 인증 없는 connection(혹은 role 부적합)시 401/403 에러 검증
  await TestValidator.error("unauthorized access fails")(async () => {
    const connectionNoAuth = { ...connection, headers: {} };
    await api.functional.prefix.admin.actors.admins.index(connectionNoAuth, { body: {} });
  });
}

