/**
 * Validates that a member cannot update an alert not owned by them (ownership/authorization enforced).
 *
 * 1. Create an alert owned by a second (other) member, using their authentication/session.
 * 2. Switch authentication/session to a different member (the current user/test subject).
 * 3. Attempt to update the alert (using alertId from step 1) with valid update input.
 * 4. Confirm that the update fails with a forbidden (403) or not-found (404) error, indicating ownership enforcement.
 * 5. (Optional) Check that the alert is unchanged if it still exists.
 */
export async function test_api_prefix_member_my_discussionboardAlerts_test_update_alert_not_owned_forbidden(
  connection: api.IConnection,
) {
  // Step 1: Create an alert as another member (other user)
  // (Simulate as if another member's session creates this alert)

  // In a real E2E, you would create/login a secondary account for this step. Here we assume such context can be switched.
  // For this test, we're omitting how the session switch is done, focusing only on API usage and business logic.

  // Create the alert as the "other" member (simulate or use a helper if supported)
  const otherMemberAlert = await api.functional.prefix.member.my.discussionboardAlerts.create(
    connection, // in actual, connection would be an "other" member
    {
      body: {
        type: "suspension_warning",
        severity: "critical",
        title: "Warning: Policy Violation",
        body: "Your post has been flagged by moderators.",
        is_active: true,
      },
    },
  );
  typia.assert(otherMemberAlert);

  // Normally here: switch authentication/session to a different member (non-owner)
  // This is test framework/environment dependent and may require separate helper/login call not shown here.

  // Step 2: Attempt to update the alert as someone who does NOT own it
  await TestValidator.error("Should not be able to update alert belonging to another member")(
    async () => {
      await api.functional.prefix.member.my.discussionboardAlerts.update(
        connection, // now connection is for another user (test subject NOT owner)
        {
          alertId: otherMemberAlert.id,
          body: {
            is_active: false,
            resolved_at: new Date().toISOString(),
          },
        },
      );
    },
  );
}

