  const noMatchRequest: IDiscussionboardAppeal.IRequest = {
    appellant_id: typia.random<string & tags.Format<"uuid">>(),
    status: "NON_EXISTENT_STATUS"
  };

  // 2. Search as admin role
  const output = await api.functional.prefix.admin.policyAudit.appeals.index(connection, {
    body: noMatchRequest,
