import type { IModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationAction";

/**
 * Validate that an admin can successfully update their own moderation action record by id.
 *
 * This test ensures that:
 * 1. An admin can only update allowed fields in their moderation action (action_description, action_type, affected_post_id, affected_member_id, action_timestamp).
 * 2. The changes are successfully persisted in the record.
 * 3. The API response returns the correct, updated data matching the changes sent.
 *
 * Test Steps:
 * 1. Assign admin role to a new user (creating admin privilege context).
 * 2. Have that user create a moderation action (so there is an ownable, updatable moderation action).
 * 3. Update the moderation action using allowed fields (action_description, action_type, affected_post_id, affected_member_id, action_timestamp).
 * 4. Verify the update response contains all the updated fields and remains consistent with update request.
 */
export async function test_api_prefix_admin_my_moderationActions_test_admin_update_own_moderation_action_success(
  connection: api.IConnection,
) {
  // 1. Assign admin role to user
  const adminId = typia.random<string & tags.Format<'uuid'>>();
  const adminAssignment = await api.functional.prefix.admin.actors.admins.create(connection, {
    body: {
      id: adminId,
      created_at: new Date().toISOString(),
    } satisfies IDiscussionboardAdmin.ICreate,
  });
  typia.assert(adminAssignment);

  // 2. Create a moderation action for that admin
  const originalAction = await api.functional.prefix.admin.moderationActions.create(connection, {
    body: {
      moderator_id: adminAssignment.id,
      report_id: null,
      affected_post_id: typia.random<string & tags.Format<'uuid'>>(),
      affected_member_id: typia.random<string & tags.Format<'uuid'>>(),
      action_type: 'warned',
      action_description: 'Inappropriate content -- original',
      action_timestamp: new Date().toISOString(),
    } satisfies IModerationAction.ICreate,
  });
  typia.assert(originalAction);

  // 3. Update the moderation action with new allowed field values
  const newPostId = typia.random<string & tags.Format<'uuid'>>();
  const newMemberId = typia.random<string & tags.Format<'uuid'>>();
  const updateRequest: IModerationAction.IUpdate = {
    affected_post_id: newPostId,
    affected_member_id: newMemberId,
    action_type: 'deleted_post',
    action_description: 'Violation escalated -- post deleted',
    action_timestamp: new Date().toISOString(),
  };
  const updateResult = await api.functional.prefix.admin.my.moderationActions.update(connection, {
    id: originalAction.id,
    body: updateRequest,
  });
  typia.assert(updateResult);
  // 4. Validate all updated fields are persisted (strong field match)
  TestValidator.equals('affected_post_id')(updateResult.affected_post_id)(newPostId);
  TestValidator.equals('affected_member_id')(updateResult.affected_member_id)(newMemberId);
  TestValidator.equals('action_type')(updateResult.action_type)('deleted_post');
  TestValidator.equals('action_description')(updateResult.action_description)('Violation escalated -- post deleted');
  TestValidator.equals('action_timestamp')(updateResult.action_timestamp)(updateRequest.action_timestamp);
  // Confirm that the id has not changed
  TestValidator.equals('moderation_action_id')(updateResult.id)(originalAction.id);
  // Confirm moderator_id remains the same
  TestValidator.equals('moderator_id')(updateResult.moderator_id)(originalAction.moderator_id);
}

