 * as well as attempts to set existing fields to types not allowed by the schema.
 *
 * 1. Create a valid ban record to obtain a real ban id.
 * 2. Attempt to update the ban with an extra non-schema field; expect validation error.
 * 3. Attempt to update the ban with a wrong field type (e.g., notes set to a number); expect validation error.
 * 4. Optionally, attempt valid update to prove valid requests succeed.
 */
export async function test_api_bans_test_update_ban_with_invalid_payload(
  connection: api.IConnection,
) {
  // 1. Create a valid ban (admin, member or guest variant)
  const createInput: IDiscussionboardBan.ICreate = {
    admin_id: typia.random<string & tags.Format<"uuid">>(),
    banned_member_id: typia.random<string & tags.Format<"uuid">>(),
