  TestValidator.error("payload includes extra unknown field should fail")(
    async () => {
      await api.functional.prefix.admin.my.bans.update(connection, {
        id: ban.id,
        body: {
          ban_reason: "Trying extra field",
          notes: "Should not change",
          extra_field_not_in_schema: "should cause error" // Not allowed!
        } as any // as any only to allow incorrect shape TEST. (<-- see critical requirements below)
      });
    }
  );

