        body: {
          ban_reason: "Trying wrong type",
          notes: 12345 // Should be string | null
        } as any
      });
    }
  );

  // 4. Valid update should succeed (positive control)
  const updateResult = await api.functional.prefix.admin.my.bans.update(connection, {
