import type { ISuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/ISuspension";

/**
 * 관리자 권한으로 단일 회원 정지 이력 조회 검증.
 *
 * 관리자가 특정 정지 이력(UUID)을 조회할 수 있는지를 확인하고, 반환되는 데이터가 생성 시 입력한 모든 필드와 정확히 일치하는지
 * 검증합니다.
 *
 * #### 검증 항목:
 *
 * 1. 정상 케이스: 정지 이력을 생성한 후, 해당 UUID로 단건 조회시 전체 필드 일치 확인
 * 2. 존재하지 않는 UUID 사용시 not found(404 등) 오류가 발생하는지 확인
 * 3. (가능할 경우) 인증/권한 없는 접근 시 forbidden/unauthorized 오류 발생 여부 (권한 스위칭 미제공 시 스킵)
 *
 * 단계별 진행 과정:
 *
 * 1. (관리자 권한하에) POST /prefix/admin//suspensions 로 정지 이력 신규 생성
 *
 *    - 필수 필드 모두 임의 UUID/사유/시각 등으로 채움
 * 2. 생성된 이력의 id로 GET /prefix/admin//suspensions/{id} 요청 (관리자 권한)
 *
 *    - 반환 객체가 id, moderator_id, suspended_member_id, suspension_reason,
 *         suspension_started_at, suspension_ends_at (null 포함 가능) 모두 일치하는지 검증
 * 3. 임의의(존재하지 않는) UUID로 GET 요청 시 not found 에러 발생 여부 확인
 * 4. _(권한 스위칭 방법 미제공시 생략):_ 인증 없이/일반 사용자 권한 접근 시 forbidden/unauthorized 오류 검증
 */
export async function test_api_prefix_admin_suspensions_test_retrieve_individual_suspension_by_id_admin(
  connection: api.IConnection,
) {
  // 1. 관리자 권한으로 정지 이력 생성
  const createInput: ISuspension.ICreate = {
    moderator_id: typia.random<string & tags.Format<"uuid">>(),
    suspended_member_id: typia.random<string & tags.Format<"uuid">>(),
    suspension_reason: "E2E테스트: 스팸 게시물 반복",
    suspension_started_at: new Date().toISOString(),
    suspension_ends_at: new Date(
      Date.now() + 1000 * 60 * 60 * 24,
    ).toISOString(),
  };
  const created: ISuspension =
    await api.functional.prefix.admin.suspensions.create(connection, {
      body: createInput,
    });
  typia.assert(created);

  // 2. 관리자가 해당 정지 이력 단건 조회
  const retrieved: ISuspension =
    await api.functional.prefix.admin.suspensions.at(connection, {
      id: created.id,
    });
  typia.assert(retrieved);

  // 모든 필드 단위 별로 완전 일치 검증
  TestValidator.equals("id")(retrieved.id)(created.id);
  TestValidator.equals("moderator_id")(retrieved.moderator_id)(
    created.moderator_id,
  );
  TestValidator.equals("suspended_member_id")(retrieved.suspended_member_id)(
    created.suspended_member_id,
  );
  TestValidator.equals("reason")(retrieved.suspension_reason)(
    created.suspension_reason,
  );
  TestValidator.equals("started_at")(retrieved.suspension_started_at)(
    created.suspension_started_at,
  );
  TestValidator.equals("ends_at (nullable) ")(
    retrieved.suspension_ends_at ?? null,
  )(created.suspension_ends_at ?? null);

  // 3. 존재하지 않는 UUID로 조회 시 not found 오류 검증
  const nonExistentId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  TestValidator.error("존재하지 않는 id 오류")(async () => {
    await api.functional.prefix.admin.suspensions.at(connection, {
      id: nonExistentId,
    });
  });

  // 4. 권한 없는 접근 시 forbidden/unauthorized 검증 (API 인증/권한 스위칭 미지원시 생략)
}

