import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { discussionboard_alerts } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboard_alerts";

/**
 * Validates that an authenticated member can delete one of their own alert records by alertId, and that the record is fully removed (hard delete).
 * 
 * Business context: This verifies that when a member deletes an alert, it is unrecoverable – since there is no soft delete (no deleted_at or similar field), the record should be completely removed. Subsequent accesses to this alert by its ID (including attempted fetches by the owner) must result in not found or error, not return the alert data.
 *
 * Steps:
 * 1. Create an alert record for the authenticated member (prerequisite/dependency).
 * 2. Delete the alert using the alert's id (the owner/membership enforcement).
 * 3. Attempt to retrieve or operate on the deleted alert to confirm it is gone (depending on available API; for example, try to delete again and expect a not found error).
 * 4. Optionally, check any system state or listing APIs (if available) to confirm the alert does not appear for the member.
 */
export async function test_api_prefix_member_my_discussionboardAlerts_test_delete_own_alert_successfully(
  connection: api.IConnection,
) {
  // 1. Create an alert for the current authenticated user
  const createInput: discussionboard_alerts.ICreate = {
    type: "policy_update",
    severity: "info",
    title: "Test Alert",
    body: "This is a test alert for hard delete e2e validation.",
    is_active: true,
  };
  const alert = await api.functional.prefix.member.my.discussionboardAlerts.create(
    connection,
    { body: createInput }
  );
  typia.assert(alert);

  // 2. Delete the alert as owner (hard delete)
  await api.functional.prefix.member.my.discussionboardAlerts.erase(
    connection,
    { alertId: alert.id }
  );
  // No output to assert for void return

  // 3. Attempt to delete the same alert again (expect failure -- already deleted)
  await TestValidator.error("Deleting a non-existent alert should fail")(
    async () => {
      await api.functional.prefix.member.my.discussionboardAlerts.erase(
        connection,
        { alertId: alert.id }
      );
    }
  );

  // 4. (Optional listing check omitted – no GET/list API available in the provided materials)
}

