import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 토론 스레드 리스트의 카테고리 필터 및 페이지네이션 정상 동작을 검증합니다.
 * 
 * 1. 두 개 이상의 서로 다른 discussionboard_category_id(카테고리) 값을 가진 스레드를 각각 생성합니다.
 * 2. 임의의 한 카테고리 discussionboard_category_id만을 조건으로, 목록(list) 엔드포인트에 페이지네이션 정보(예: limit, current)와 함께 요청을 보냅니다.
 * 3. 응답 data에는 해당 카테고리에 속하는 스레드만 포함되어야 하며, 다른 카테고리의 스레드는 어떤 경우에도 리턴 결과에 포함되어선 안 됩니다.
 * 4. 응답의 pagination 정보(current, limit, pages, records) 역시 정상적으로 반환되는지 체크합니다.
 * 
 * 모두 성공한다면, 카테고리 필터 및 페이징 컨트롤이 정상적으로 작동함을 의미합니다.
 */
export async function test_api_threadsPosts_test_list_threads_with_pagination_and_category_filter(
  connection: api.IConnection,
) {
  // 1. 테스트 준비: 두 개의 서로 다른 카테고리에 각각 하나씩 스레드를 생성합니다.
  const categoryA = typia.random<string & tags.Format<"uuid">>();
  const categoryB = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();

  // 카테고리A 스레드 생성
  const threadA = await api.functional.prefix.member.threadsPosts.threads.create(connection, {
    body: {
      discussionboard_category_id: categoryA,
      title: RandomGenerator.paragraph()(8),
      status: "active",
      is_pinned: false,
      is_locked: false,
      archived: false,
      created_at: now,
      updated_at: now,
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(threadA);

  // 카테고리B 스레드 생성
  const threadB = await api.functional.prefix.member.threadsPosts.threads.create(connection, {
    body: {
      discussionboard_category_id: categoryB,
      title: RandomGenerator.paragraph()(8),
      status: "active",
      is_pinned: false,
      is_locked: false,
      archived: false,
      created_at: now,
      updated_at: now,
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(threadB);

  // 2. 카테고리A만 필터로 주고 페이지네이션 요청(예: limit=5, current=1)
  const list = await api.functional.prefix.threadsPosts.threads.index(connection, {
    body: {
      discussionboard_category_id: categoryA,
      status: "active",
    } satisfies IDiscussionboardThreads.IRequest,
  });
  typia.assert(list);

  // 3. 결과: 반환된 데이터가 카테고리A 스레드만 포함하는지, pagination 필드가 정상값인지 점검
  TestValidator.predicate("data only has threads from categoryA")(
    list.data.every((t) => t.discussionboard_category_id === categoryA)
  );
  TestValidator.predicate("threadA는 반드시 존재해야 한다")(
    list.data.some((t) => t.id === threadA.id)
  );
  TestValidator.predicate("threadB는 포함되지 않는다")(
    list.data.every((t) => t.id !== threadB.id)
  );
  TestValidator.equals("pagination 타입 체크")(typeof list.pagination.current)("number");
  TestValidator.equals("pagination limit 타입 체크")(typeof list.pagination.limit)("number");
  TestValidator.equals("반환 데이터 limit은 기본값 10 또는 1 이상")(list.pagination.limit >= 1)(true);
}

