 * 3. For each call, verify:
 *    - No access or permission errors occur (response is successful)
 *    - The response strictly matches the schema for paginated incidents; fields only what is in schema
 *    - Pagination object structure and types are correct
 *    - All filtering appears respected (if filter was applied, all results match the filter condition)
 *
 * 4. Optionally, test edge cases like a filter with no matches and verify that pagination metadata is still valid.
 */
export async function test_api_prefix_moderator_policyAudit_incidentReports_index(
  connection: api.IConnection,
) {
  // 1. Empty filter: Should return all incidents with default pagination
  const allResults = await api.functional.prefix.moderator.policyAudit.incidentReports.index(connection, {
    body: {},
  });
  typia.assert(allResults);
  TestValidator.predicate("pagination shape")(typeof allResults.pagination === "object");

  // 2. By status filter
  const statusResults = await api.functional.prefix.moderator.policyAudit.incidentReports.index(connection, {
    body: { status: "OPEN" },
  });
  typia.assert(statusResults);
  for (const r of statusResults.data)
    TestValidator.equals("status matches filter")(r.status)("OPEN");

  // 3. By incident_code
  if (allResults.data.length > 0) {
    const code = allResults.data[0].incident_code;
    const codeResults = await api.functional.prefix.moderator.policyAudit.incidentReports.index(connection, {
      body: { incident_code: code },
    });
    typia.assert(codeResults);
    for (const r of codeResults.data)
      TestValidator.equals("incident_code matches")(r.incident_code)(code);
  }

  // 4. By reporter_id
  if (allResults.data.length > 0) {
    const reporter_id = allResults.data[0].reporter_id;
    if (reporter_id) {
      const reporterResults = await api.functional.prefix.moderator.policyAudit.incidentReports.index(connection, {
        body: { reporter_id },
      });
      typia.assert(reporterResults);
      for (const r of reporterResults.data)
        TestValidator.equals("reporter_id matches")(r.reporter_id)(reporter_id);
    }
  }

  // 5. By created_at date range (using first/last report's timestamp)
  if (allResults.data.length > 0) {
    const sorted = allResults.data.slice().sort((a, b) => a.created_at.localeCompare(b.created_at));
    const created_from = sorted[0].created_at;
    const created_to = sorted[sorted.length - 1].created_at;
    const rangeResults = await api.functional.prefix.moderator.policyAudit.incidentReports.index(connection, {
      body: { created_from, created_to },
    });
    typia.assert(rangeResults);
    for (const r of rangeResults.data) {
      TestValidator.predicate("within date range")(r.created_at >= created_from && r.created_at <= created_to);
