  }

  // 6. By keyword (using description from a known incident)
  if (allResults.data.length > 0) {
    const keyword = allResults.data[0].description.split(" ")[0];
    const keywordResults = await api.functional.prefix.moderator.policyAudit.incidentReports.index(connection, {
      body: { keyword },
    });
    typia.assert(keywordResults);
    for (const r of keywordResults.data) {
      TestValidator.predicate("keyword match")(r.description.includes(keyword));
    }
  }

  // 7. By custom pagination
  const pagedResults = await api.functional.prefix.moderator.policyAudit.incidentReports.index(connection, {
    body: { page: 2, limit: 1 },
  });
