  TestValidator.equals("pagination page")(pagedResults.pagination.current)(2);
  TestValidator.equals("pagination limit")(pagedResults.pagination.limit)(1);

  // 8. Edge case: No-match filter
  const noMatchResults = await api.functional.prefix.moderator.policyAudit.incidentReports.index(connection, {
    body: { incident_code: "NON-EXISTENT-CODE-XYZ" },
  });
  typia.assert(noMatchResults);
  TestValidator.equals("no results")(noMatchResults.data.length)(0);
}

