import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardConfiguration";

/**
 * Test updating a discussion board configuration with missing or invalid required fields.
 *
 * This test ensures that the API enforces required field validation rules when updating a configuration, specifically:
 *  - Omitting required fields or placing invalid/null values in non-nullable updatable fields
 *  - The API correctly rejects updates that would leave "name" null or missing (since "name" must always be a string and is the unique key)
 *
 * Test Steps:
 * 1. Create a valid configuration using the admin API to obtain a real configuration ID.
 * 2. Attempt to update the configuration, providing null as the "name" (not allowed, should be a string).
 * 3. Attempt to update the configuration, omitting the "name" field entirely (should succeed if no change is meant, but not if combined with an invalid/missing value for non-nullable fields).
 * 4. Attempt to update the configuration with a null or invalid "settings_json" (should be rejected since if provided, it must always be a non-null string).
 * 5. Attempt to update the configuration with only valid nullable fields omitted or set to null (e.g., "description").
 * 6. Validate that the API throws or rejects attempts that violate these constraints using TestValidator.error().
 */
export async function test_api_discussionboardConfigurations_test_update_discussion_board_configuration_with_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Create a valid configuration first to get a configurationId
  const created = await api.functional.prefix.admin.discussionboardConfigurations.create(
    connection,
    {
      body: {
        name: "required-fields-test-" + RandomGenerator.alphaNumeric(8),
        settings_json: "{}",
        description: "Testing required field constraint on update",
      } satisfies IDiscussionboardConfiguration.ICreate,
    },
  );
  typia.assert(created);

  // 2. Attempt to update with name: null (should fail, name is not nullable)
  await TestValidator.error("update: name cannot be set to null")(
    async () => {
      await api.functional.prefix.admin.discussionboardConfigurations.update(
        connection,
        {
          configurationId: created.id,
          body: { name: null } as any, // TypeScript does not allow null, but force at runtime to test backend validation
        },
      );
    },
  );

  // 3. Attempt to update with no "name" (should be fine if not changing name)
  const validPatch = await api.functional.prefix.admin.discussionboardConfigurations.update(
    connection,
    {
      configurationId: created.id,
      body: { description: "No name changed" } satisfies IDiscussionboardConfiguration.IUpdate,
    },
  );
  typia.assert(validPatch);
  TestValidator.equals("unchanged name after patch")(validPatch.name)(created.name);
  TestValidator.equals("unchanged settings_json after patch")(validPatch.settings_json)(created.settings_json);

  // 4. Attempt to update with settings_json: null (should fail, settings_json is not nullable)
  await TestValidator.error("update: settings_json cannot be set to null")(
    async () => {
      await api.functional.prefix.admin.discussionboardConfigurations.update(
        connection,
        {
          configurationId: created.id,
          body: { settings_json: null } as any,
        },
      );
    },
  );

  // 5. Attempt to update with description = null (should succeed, description is nullable)
  const patchNullDesc = await api.functional.prefix.admin.discussionboardConfigurations.update(
    connection,
    {
      configurationId: created.id,
      body: { description: null } satisfies IDiscussionboardConfiguration.IUpdate,
    },
  );
  typia.assert(patchNullDesc);
  TestValidator.equals("description is null")(patchNullDesc.description)(null);
  TestValidator.equals("name unchanged")(patchNullDesc.name)(created.name);
  TestValidator.equals("settings_json unchanged")(patchNullDesc.settings_json)(created.settings_json);
}

