import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";

/**
 * Validate schema enforcement when a moderator attempts to update their own assignment using non-schema (extraneous) fields.
 *
 * This test ensures that the update API strictly rejects any extra properties outside of the allowed schema (id, created_at).
 *
 * **Test Flow:**
 * 1. An admin creates a moderator assignment (prerequisite).
 * 2. The moderator attempts to update their own moderator assignment, but the request body includes an extra, non-schema property (e.g., 'foo').
 * 3. The API should reject the request and return a validation error, not applying any change.
 *
 * **Validation:**
 * The API should NOT permit update when extraneous fields are present. This guarantees schema compliance and prevents accidental or malicious data injection.
 * This test only covers runtime errors, as per guidelines – type system rejection scenarios are not tested.
 */
export async function test_api_prefix_moderator_my_actors_moderators_test_update_own_moderator_assignment_with_invalid_fields_fails(
  connection: api.IConnection,
) {
  // 1. Create moderator assignment as prerequisite (admin)
  const moderator: IDiscussionboardModerator = await api.functional.prefix.admin.actors.moderators.create(
    connection,
    {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString() as string & tags.Format<"date-time">,
      },
    },
  );
  typia.assert(moderator);

  // Assume authentication context switches to the moderator before the update (environment or prior test setup)

  // 2. Attempt to update with valid fields PLUS an extra property 'foo'
  // Note: TypeScript does not allow creation of a request with invalid properties due to type checking,
  // so object is constructed using type cast purely to test runtime rejection.
  // This is allowed because the test only targets runtime (not compile-time) schema violation.

  const invalidUpdateBody = {
    id: moderator.id,
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
    foo: "bar", // extra property not in schema
  } as any;

  // 3. API should reject the request due to schema violation
  await TestValidator.error("update with extra property should fail")(
    async () => {
      await api.functional.prefix.moderator.my.actors.moderators.update(
        connection,
        {
          id: moderator.id,
          body: invalidUpdateBody,
        }
      );
    }
  );
}

