import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBan";

/**
 * Test successful hard deletion of a ban record by its ID.
 *
 * This test verifies the complete lifecycle for permanently deleting a ban record using the DELETE endpoint.
 * The procedure is as follows:
 *
 * 1. Create a ban record using the admin bans POST endpoint.
 * 2. Permanently delete the created ban record by its ID using the admin/my/bans DELETE endpoint.
 * 3. Confirm that the ban record no longer exists and cannot be retrieved (irreversible deletion),
 *    e.g., by attempting to delete it again and expecting an error.
 *
 * Key validations:
 * - Ban record is successfully created and the ID is valid.
 * - Deletion succeeds with no errors for a record that exists.
 * - After deletion, further operations on this ID fail as the resource is permanently removed.
 * - API response types are correctly validated.
 */
export async function test_api_prefix_admin_my_bans_test_delete_ban_by_id_successfully(connection: api.IConnection) {
  // 1. Create a ban record to be deleted
  const banInput: IDiscussionboardBan.ICreate = {
    admin_id: typia.random<string & tags.Format<"uuid">>(),
    banned_member_id: typia.random<string & tags.Format<"uuid">>(),
    banned_guest_id: null,
    ban_reason: "Test ban for deletion",
    banned_at: new Date().toISOString(),
    notes: "Ban record to test deletion lifecycle",
  };
  const ban = await api.functional.prefix.admin.bans.create(connection, { body: banInput });
  typia.assert(ban);

  // 2. Hard delete the ban record by its ID
  await api.functional.prefix.admin.my.bans.erase(connection, { id: ban.id });

  // 3. Attempt to delete again and expect an error (resource should not exist)
  await TestValidator.error("Deleting a non-existent ban record must fail")(async () => {
    await api.functional.prefix.admin.my.bans.erase(connection, { id: ban.id });
  });
}

