import type { IModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationAction";

/**
 * Verify that a guest cannot delete their content report after it has been processed by a moderator.
 *
 * This test covers the following business workflow and integrity rules:
 * - A guest files a new content report for a post.
 * - The report is then processed by a moderator (e.g., status set to 'action_taken' or moderator_note updated), thus marking it as handled.
 * - After moderation, the original guest attempts to delete their own report.
 * - The system should deny the deletion with an error to maintain audit trail and preserve moderator actions, enforcing compliance and record-keeping requirements.
 *
 * Steps:
 * 1. Create a new guest entity for content report submission.
 * 2. Create a sample post to be reported (for test isolation, done as a member, since only members create posts).
 * 3. File a content report as the guest for the target post.
 * 4. Simulate moderation on the report (status update or note addition) via moderator endpoint.
 * 5. Attempt to delete the same report as the guest; expect an error as deletion should now be forbidden by business rules.
 */
export async function test_api_contentReports_test_delete_guest_content_report_after_moderation_forbidden(connection: api.IConnection) {
  // 1. Create guest context
  const guestInput: IDiscussionboardGuests.ICreate = {
    id: typia.random<string & tags.Format<"uuid">>(),
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const guest = await api.functional.prefix.member.actors.guests.create(connection, { body: guestInput });
  typia.assert(guest);

  // 2. Create member post (assuming member auth pre-exists for setup)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const postInput: IDiscussionboardPosts.ICreate = {
    discussionboard_thread_id: threadId,
    body: "Abusive content for moderation test.",
  };
  const post = await api.functional.prefix.member.threadsPosts.posts.create(connection, { body: postInput });
  typia.assert(post);

  // 3. Guest files a content report
  const reportInput: IContentReport.ICreate = {
    reported_post_id: post.id,
    reporter_member_id: null,
    reporter_guest_id: guest.id,
    report_reason: "Abusive language in post.",
    status: "pending",
    reported_at: new Date().toISOString() as string & tags.Format<"date-time">,
    moderator_note: null,
  };
  const contentReport = await api.functional.prefix.guest.contentReports.create(connection, { body: reportInput });
  typia.assert(contentReport);

