import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IWarningLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IWarningLog";

/**
 * Test system rejection of admin warning log update with invalid/non-schema fields, enforcing schema validation.
 *
 * Business context:
 * Admins (moderators) are allowed to update only certain fields of their own issued warning logs. Any attempt to include extra fields or fields not defined in the schema must be rejected to ensure the integrity of log records and prevent accidental or malicious data pollution.
 *
 * Step-by-step process:
 * 1. Admin creates a valid warning log (dependency setup).
 * 2. Admin attempts to update the warning log using a body containing both valid fields (warning_reason, issued_at) and extra non-schema fields (e.g., illegal_field, or additional object properties).
 * 3. Validate that the API returns a validation error and does not perform the update. Original log data should remain unchanged upon retrieval if possible (data immutability check).
 * 4. Repeat with bodies containing only correct fields but invalid values (such as non-string for warning_reason, or date-time malformation), confirming request is rejected by schema validation.
 *
 * Note: Since the API/SDK allows only schema-shaped types at compile time, test runtime schema validation by invoking with correct typing but simulate transmission of invalid/non-schema fields using `as any` or raw payload if possible. For type-system-consistent tests, at minimum, attempt runtime-invalid values within the schema shape.
 */
export async function test_api_prefix_admin_my_warningLogs_test_admin_update_warning_log_with_bad_data_fails(connection: api.IConnection) {
  // 1. Create initial valid warning log
  const validLog = await api.functional.prefix.admin.warningLogs.create(connection, {
    body: {
      moderator_id: typia.random<string & tags.Format<"uuid">>(),
      warned_member_id: typia.random<string & tags.Format<"uuid">>(),
      warning_reason: "Test reason", // valid
      issued_at: new Date().toISOString(),
    },
  });
  typia.assert(validLog);

  // 2. Attempt to update with non-schema property (should be rejected)
  await TestValidator.error("should reject non-schema fields")(
    async () => {
      // Here we force a non-schema field into the body
      await (api.functional.prefix.admin.my.warningLogs.update as any)(connection, {
        id: validLog.id,
        body: {
          warning_reason: "Updated reason",
          issued_at: new Date().toISOString(),
          illegal_field: "bad", // runtime error expected
        },
      });
    }
  );

  // 3. Attempt to update with wrong type value
  await TestValidator.error("should reject invalid field type")(
    async () => {
      await api.functional.prefix.admin.my.warningLogs.update(connection, {
        id: validLog.id,
        body: {
          warning_reason: 1234 as any, // invalid type (should be string)
          issued_at: new Date().toISOString(),
        },
      });
    }
  );

  // 4. Attempt to update with invalid date-time format
  await TestValidator.error("should reject bad date-time format")(
    async () => {
      await api.functional.prefix.admin.my.warningLogs.update(connection, {
        id: validLog.id,
        body: {
          warning_reason: "Valid reason",
          issued_at: "not-a-date-time" as any, // invalid format
        },
      });
    }
  );

  // Optionally: Confirm warning log was not changed with valid fields
  const after = await api.functional.prefix.admin.my.warningLogs.update(connection, {
    id: validLog.id,
    body: {
      warning_reason: validLog.warning_reason,
      issued_at: validLog.issued_at,
    },
  });
  typia.assert(after);
  TestValidator.equals("warning_reason should remain unchanged")(after.warning_reason)(validLog.warning_reason);
  TestValidator.equals("issued_at should remain unchanged")(after.issued_at)(validLog.issued_at);
}

