 * 4. 성공이 아닌 경우, 즉 권한 부족(Forbidden) 혹은 비인가(Unauthorized) 오류가 반드시 발생해야 합니다.
 * 5. catch 블럭 내에서 오류 검증(정상적으로 오류가 던져졌는지)을 수행합니다.
 */
export async function test_api_discussionboard_guests_test_attempt_update_guest_record_by_non_owner_is_forbidden(
  connection: api.IConnection,
) {
