  const guest: IDiscussionboardGuests = await api.functional.prefix.member.actors.guests.create(connection, {
    body: {
      id: typia.random<string & tags.Format<"uuid">>(),
      created_at: new Date().toISOString()
    } satisfies IDiscussionboardGuests.ICreate
  });
  typia.assert(guest);

  // 2. B 회원: 새로운 회원 인증 컨텍스트 생성 (connection 복제 및 임의 Authorization 토큰 제거)
  const anotherConnection: api.IConnection = { ...connection, headers: { ...connection.headers } };
  delete anotherConnection.headers.Authorization;
  // 여기에서 실제 서비스라면 B 회원으로 로그인 등을 구현해야 하나, 본격 api/connection 구조가 상세히 주어지지 않아 단순히 Authorization 제거.
