  await TestValidator.error("타인이 소유한 guest 업데이트 Forbidden/Unauthorized 오류되어야 함")(async () => {
    await api.functional.prefix.member.my.actors.guests.update(anotherConnection, {
      id: guest.id,
      body: {
        id: guest.id,
        created_at: new Date().toISOString()
      } satisfies IDiscussionboardGuests.IUpdate
    });
  });
