 *
 * Steps:
 * 1. Create a new member account.
 * 2. Create a new poll (linked to some discussion thread; generate thread id as UUID randomly).
 * 3. Submit a poll vote as the new member (generate a synthetic option string).
 * 4. Delete the poll vote (by id, using the member's authentication).
 * 5. Confirm that any attempts to retrieve the deleted poll vote record result in not found/error.
 *
 * Omissions:
 * - No GET endpoint for poll vote retrieval is described in this API spec; validation is limited to ensuring
 *   the delete endpoint completes without error. Any further validation must be omitted for technical reasons.
 */
export async function test_api_member_test_delete_own_poll_vote_successfully(
  connection: api.IConnection,
) {
  // 1. Create a member
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const memberCreatedAt = new Date().toISOString();
  const member = await api.functional.prefix.member.actors.members.create(connection, {
    body: {
      id: memberId,
      created_at: memberCreatedAt,
    },
  });
  typia.assert(member);

  // 2. Create a poll
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const prompt = "Which option do you prefer?";
  const option = "optionA";
  const poll = await api.functional.prefix.member.polls.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      prompt,
      allow_multiple_choices: false,
      is_anonymous: false,
    },
  });
  typia.assert(poll);

  // 3. Submit a poll vote
  const vote = await api.functional.prefix.member.pollVotes.create(connection, {
    body: {
      discussionboard_poll_id: poll.id,
      selected_option: option,
    },
  });
  typia.assert(vote);

  // 4. Delete the poll vote as the member
  await api.functional.prefix.member.my.pollVotes.erase(connection, {
    id: vote.id,
  });

  // 5. Unable to check explicit not found on GET due to missing GET endpoint, so only ensure no error on delete
}

