import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardConfiguration";
import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";

/**
 * Test updating a discussion board section, including valid updates and error scenarios.
 *
 * This test covers:
 * 1. Updating an existing section with new properties (name, description, config ref, order, enabled) and verifying persistence.
 * 2. Attempting to update a section to use a duplicate name (should fail with uniqueness violation).
 * 3. Attempting to update a section to reference a non-existent configuration (should fail with foreign key violation).
 * 4. Attempting to update a non-existent section (should fail with 404 not found).
 *
 * Steps:
 * 1. Create two configurations (A and B).
 * 2. Create two sections, S1 (with config A) and S2 (with config B).
 * 3. Update S1 with new valid properties (change all updatable fields, including assignment to config B, and ensure persisted).
 * 4. Try to update S2's name to S1's updated name (should fail: uniqueness).
 * 5. Try to update S2 to use a random config id (should fail: foreign key violation).
 * 6. Try to update a random non-existent sectionId (should fail: 404).
 */
export async function test_api_discussionboardSections_test_update_section_with_valid_data_and_invalid_cases(connection: api.IConnection) {
  // 1. Create configuration A
  const configA = await api.functional.prefix.admin.discussionboardConfigurations.create(connection, {
    body: {
      name: `config-A-${RandomGenerator.alphaNumeric(8)}`,
      settings_json: JSON.stringify({ allowPost: true, moderation: false }),
      description: "Test config A",
    }
  });
  typia.assert(configA);

  // 2. Create configuration B
  const configB = await api.functional.prefix.admin.discussionboardConfigurations.create(connection, {
    body: {
      name: `config-B-${RandomGenerator.alphaNumeric(8)}`,
      settings_json: JSON.stringify({ allowPost: false, moderation: true }),
      description: "Test config B",
    }
  });
  typia.assert(configB);

  // 3. Create two sections: S1 (with configA), S2 (with configB)
  const sectionA = await api.functional.prefix.admin.discussionboardSections.create(connection, {
    body: {
      discussionboard_configuration_id: configA.id,
      name: `section-A-${RandomGenerator.alphaNumeric(8)}`,
      description: "First test board section",
      order: 1,
      enabled: true,
    },
  });
  typia.assert(sectionA);
  const sectionB = await api.functional.prefix.admin.discussionboardSections.create(connection, {
    body: {
      discussionboard_configuration_id: configB.id,
      name: `section-B-${RandomGenerator.alphaNumeric(8)}`,
      description: "Second test board section",
      order: 2,
      enabled: false,
    },
  });
  typia.assert(sectionB);

  // 4. Update sectionA with new all property values
  const newProps = {
    discussionboard_configuration_id: configB.id,
    name: `updated-section-${RandomGenerator.alphaNumeric(8)}`,
    description: "Section A updated description",
    order: 10,
    enabled: false,
  } satisfies IDiscussionboardSection.IUpdate;
  const updatedSectionA = await api.functional.prefix.admin.discussionboardSections.update(connection, {
    sectionId: sectionA.id,
    body: newProps,
  });
  typia.assert(updatedSectionA);
  // Validate update
  TestValidator.equals("updated section config id")(updatedSectionA.discussionboard_configuration_id)(configB.id);
  TestValidator.equals("updated section name")(updatedSectionA.name)(newProps.name);
  TestValidator.equals("updated section description")(updatedSectionA.description)(newProps.description);
  TestValidator.equals("updated section order")(updatedSectionA.order)(newProps.order);
  TestValidator.equals("updated enabled flag")(updatedSectionA.enabled)(newProps.enabled);

  // 5. Try to update section B's name to updatedSectionA's name (should fail: duplicate)
  await TestValidator.error("duplicate section name should fail")(() =>
    api.functional.prefix.admin.discussionboardSections.update(connection, {
      sectionId: sectionB.id,
      body: { name: newProps.name },
    })
  );

  // 6. Try to update section B with a non-existent config ID (should fail: foreign key)
  await TestValidator.error("invalid config FK should fail")(() =>
    api.functional.prefix.admin.discussionboardSections.update(connection, {
      sectionId: sectionB.id,
      body: { discussionboard_configuration_id: typia.random<string & tags.Format<"uuid">>() },
    })
  );

  // 7. Try to update a non-existent sectionId (should fail: 404)
  await TestValidator.error("nonexistent sectionId should fail")(() =>
    api.functional.prefix.admin.discussionboardSections.update(connection, {
      sectionId: typia.random<string & tags.Format<"uuid">>(),
      body: { name: "ghost-section" },
    })
  );
}

