import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISearchHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/ISearchHistory";
import type { IPageISearchHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageISearchHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test fetching a paginated list of search history records
 * with various combinations of search, filter, and pagination options.
 *
 * Confirms that the returned results match applied filters, pagination
 * boundaries (limit/offset), and only include data from actual schema fields.
 * Validates date/time and string filter operations, sort and soft-delete
 * toggling, and verifies result consistency per request options.
 *
 * Steps:
 * 1. Make a basic paginated request with limit/offset and ensure page metadata and data length match
 * 2. Use a search_query string filter (simulate with random string) and verify all results contain this string in search_query
 * 3. Use used_filters filter (simulate with random string) and verify results
 * 4. Use executed_at_from and executed_at_to to bracket result set
 * 5. Combine filters and validate multi-criteria intersection
 * 6. Use include_deleted true and verify deleted_at field is present
 * 7. Use sort option and verify result order by executed_at
 * 8. Try out-of-bounds offset and verify empty or remaining partial result
 */
export async function test_api_prefix_test_list_search_histories_with_pagination_filters(
  connection: api.IConnection,
) {
  // 1. Basic paginated request (limit/offset)
  const baseLimit = 5;
  const baseOffset = 0;
  const resPaginated = await api.functional.prefix.searchHistories.index(connection, {
    body: { limit: baseLimit, offset: baseOffset },
  });
  typia.assert(resPaginated);
  TestValidator.equals('pagination.limit')(resPaginated.pagination.limit)(baseLimit);
  TestValidator.predicate('data length')(resPaginated.data.length <= baseLimit);

  // 2. search_query filter (simulate with random string)
  const searchQuery = 'trend';
  const resQuery = await api.functional.prefix.searchHistories.index(connection, {
    body: { search_query: searchQuery, limit: 10 },
  });
  typia.assert(resQuery);
  for (const row of resQuery.data) {
    TestValidator.predicate('search_query contains substring')(
      row.search_query.includes(searchQuery),
    );
  }

  // 3. used_filters filter
  const filtersStr = 'tag:economics,section:policy';
  const resFilters = await api.functional.prefix.searchHistories.index(connection, {
    body: { used_filters: filtersStr, limit: 10 },
  });
  typia.assert(resFilters);
  for (const row of resFilters.data) {
    TestValidator.equals('used_filters')(row.used_filters ?? '')(filtersStr);
  }

  // 4. executed_at_from / executed_at_to
  const executedFrom = '2024-01-01T00:00:00.000Z';
  const executedTo = '2025-01-01T00:00:00.000Z';
  const resDateRange = await api.functional.prefix.searchHistories.index(connection, {
    body: { executed_at_from: executedFrom, executed_at_to: executedTo },
  });
  typia.assert(resDateRange);
  for (const row of resDateRange.data) {
    TestValidator.predicate('executed_at in range')(
      row.executed_at >= executedFrom && row.executed_at <= executedTo,
    );
  }

  // 5. Multi-filter intersection
  const multiRes = await api.functional.prefix.searchHistories.index(connection, {
    body: {
      search_query: searchQuery,
      used_filters: filtersStr,
      executed_at_from: executedFrom,
      executed_at_to: executedTo,
      limit: 10,
    },
  });
  typia.assert(multiRes);
  for (const row of multiRes.data) {
    TestValidator.predicate('intersection - search_query')(
      row.search_query.includes(searchQuery),
    );
    TestValidator.equals('intersection - used_filters')(row.used_filters ?? '')(filtersStr);
    TestValidator.predicate('intersection - executed_at')(
      row.executed_at >= executedFrom && row.executed_at <= executedTo,
    );
  }

  // 6. include_deleted true
  const resDeleted = await api.functional.prefix.searchHistories.index(connection, {
    body: { include_deleted: true, limit: 10 },
  });
  typia.assert(resDeleted);
  for (const row of resDeleted.data) {
    TestValidator.predicate('deleted_at present or not')(
      typeof row.deleted_at === 'string' || row.deleted_at === null,
    );
  }

  // 7. sort by executed_at desc
  const resSorted = await api.functional.prefix.searchHistories.index(connection, {
    body: { sort: 'executed_at_desc', limit: 10 },
  });
  typia.assert(resSorted);
  let last: string | null = null;
  for (const row of resSorted.data) {
    if (last !== null) {
      TestValidator.predicate('descending order')(row.executed_at <= last);
    }
    last = row.executed_at;
  }

  // 8. Out-of-bounds offset
  const crazyOffset = 9999;
  const resOob = await api.functional.prefix.searchHistories.index(connection, {
    body: { offset: crazyOffset, limit: 10 },
  });
  typia.assert(resOob);
  TestValidator.equals('out-of-bounds')(resOob.data.length)(0);
}

