import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";

/**
 * 관리자가 어떤 설문조사(poll)든 해당 poll의 ID로 상세 정보를 조회할 수 있는지 검증한다.
 *
 * 테스트 커버리지는 아래 모든 요소를 포함해야 한다:
 * - 설문 프롬프트(prompt), 익명 여부(is_anonymous), 복수 선택 허용 여부(allow_multiple_choices), 만료 기한(expires_at) 등 모든 스키마 필드의 정확한 반환 및 값 검증
 * - 여러 다른 회원이 생성한 설문조사 각각을 생성 → 각각의 상세 조회 (서로 다른 생성자, 쓰레드, 상태[만료/진행중])
 * - 만료된 설문조사와 진행중(만료되지 않은) 설문조사 모두 커버
 * - 관리자는 자신의 소유/비소유 또는 어떤 쓰레드의 poll이든 모두 조회 가능해야 함
 * - 존재하지 않는 설문 ID를 조회할 때 404 에러를 응답하는지 검증
 *
 * 테스트 진행 순서:
 * 1. 여러 멤버가 참여하는 가상의 토론 스레드 여러 개 및 멤버 여러 명의 컨텍스트를 구성.
 * 2. 서로 다른 멤버가 각각의 스레드에서 다양한 유형(프롬프트/만료값/익명여부/복수선택 등 조합)으로 설문 poll을 생성.
 * 3. 각 생성된 poll의 id로 관리자로 상세조회를 반복. 반환 값이 생성 시 저장된 값과 정확하게 일치하는지 검증.
 * 4. 종료(만료된) poll과 진행중 poll 모두 커버(만료 필드에 과거/미래값 사용).
 * 5. 소유자가 아닌 poll도 조회 가능한지, 멀티 스레드 환경에서 제한 없는 접근성 확인.
 * 6. 존재하지 않는 임의의 poll id로 조회 요청 시 404 에러 발생 여부 확인.
 */
export async function test_api_prefix_admin_polls_test_view_poll_details_as_admin_access_all_cases(
  connection: api.IConnection,
) {
  // 1. 다양한 thread와 멤버, poll을 셋업한다
  //
  // (이 영역은 API만으로는 토론 스레드 및 멤버 생성이 불가하다고 판단, 가정된 UUID/random 값 활용)
  // 임의 thread와 member id
  const threadIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>()
  ];
  const memberIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>()
  ];

  // 2. 다양한 케이스로 poll 여러 개 생성 (prompt/익명/복수선택/만료 조합)
  // 만료 이미 지난 poll (expired), 앞으로의 poll (active) 각각 1개씩 포함
  const now = new Date();
  const expiredAtPast = new Date(now.getTime() - 1000 * 60 * 60 * 24).toISOString(); // 하루 전
  const expiresAtFuture = new Date(now.getTime() + 1000 * 60 * 60 * 24).toISOString(); // 하루 후

  const pollInputs: api.IPoll.ICreate[] = [
    // 1) active, non-anonymous, single choice
    {
      discussionboard_thread_id: threadIds[0],
      prompt: "진행중 비익명 단일선택 설문",
      allow_multiple_choices: false,
      is_anonymous: false,
      expires_at: expiresAtFuture,
    },
    // 2) expired, anonymous, multi-choice
    {
      discussionboard_thread_id: threadIds[1],
      prompt: "만료됨 익명 복수선택 설문",
      allow_multiple_choices: true,
      is_anonymous: true,
      expires_at: expiredAtPast,
    },
    // 3) no expiration
    {
      discussionboard_thread_id: threadIds[0],
      prompt: "만료기한 없음",
      allow_multiple_choices: false,
      is_anonymous: true,
      expires_at: undefined,
    },
  ];

  // 각각 멤버 컨텍스트(가상의 로그인 세션이 필요하다고 간주, 단 여기서는 member_id만 임의 할당. 실제 상황에서는 세션전환 코드 필요)
  const createdPolls: api.IPoll[] = [];
  for (let i = 0; i < pollInputs.length; i++) {
    // (실제 테스트 환경에서는 로그인/세션 분리 필요하나, 여기서는 API 접근만 가능하니 member_id 임의 주입 가정)
    // poll 생성
    const poll = await api.functional.prefix.member.polls.create(connection, {
      body: pollInputs[i],
    });
    typia.assert(poll);
    createdPolls.push(poll);
  }

  // 3. 각 poll을 admin 권한으로 상세조회 및 값 검증
  for (const poll of createdPolls) {
    const output = await api.functional.prefix.admin.polls.at(connection, {
      id: poll.id,
    });
    typia.assert(output);
    // 각 필드의 일치 여부 검증
    TestValidator.equals("poll.prompt")(output.prompt)(poll.prompt);
    TestValidator.equals("poll.allow_multiple_choices")(output.allow_multiple_choices)(poll.allow_multiple_choices);
    TestValidator.equals("poll.is_anonymous")(output.is_anonymous)(poll.is_anonymous);
    TestValidator.equals("poll.expires_at")(output.expires_at)(poll.expires_at);
    TestValidator.equals("poll.discussionboard_thread_id")(output.discussionboard_thread_id)(poll.discussionboard_thread_id);
  }

  // 4. 존재하지 않는 id로 404 에러 검증
  await TestValidator.error("존재하지 않는 poll id 조회 시 404 반환")(
    async () => {
      await api.functional.prefix.admin.polls.at(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

