import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IThreadArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IThreadArchive";

/**
 * 인증된 멤버가 자신이 소유하지 않은 스레드 아카이브 기록에 접근할 수 없는지 검증합니다.
 *
 * 비즈니스 룰상 소유자만이 아카이브 상세 레코드에 접근할 수 있다면, 이 권한 제한이 올바르게 동작하는지 확인하는 시나리오입니다.
 *
 * 주요 절차:
 * 1. 멤버 A와 멤버 B를 각각 등록합니다.
 * 2. 멤버 A의 인증 컨텍스트(authorization: 멤버 A)에서 스레드를 생성하고, create시 archived: true로 바로 아카이브 처리합니다.
 *    (별도의 코드 흐름으로 soft-delete/아카이브 엔드포인트가 없으므로 생성 시 archived: true 사용)
 * 3. 아카이브된 스레드의 아카이브 id(여기서는 스레드 id와 1:1대응 가정)를 확보합니다.
 * 4. 멤버 B의 인증 컨텍스트로 전환(pointer connection의 authorization을 B회원으로 스위칭)
 * 5. 멤버 B로 아카이브 id로 아카이브 상세조회 시도를 합니다.
 * 6. 예상대로 에러가 발생하거나, 접근이 거부되는지 TestValidator.error()로 확인합니다.
 *    (비즈니스 룰상 B는 접근할 수 없음)
 */
export async function test_api_prefix_test_get_thread_archive_forbidden_for_non_owner(connection: api.IConnection) {
  // 1. 멤버 A 등록
  const memberA_id = typia.random<string & tags.Format<"uuid">>();
  const memberA_createdAt = new Date().toISOString();
  const memberA = await api.functional.prefix.member.actors.members.create(connection, {
    body: {
      id: memberA_id,
      created_at: memberA_createdAt,
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(memberA);

  // 2. 멤버 A 인증으로 스레드 생성(archived: true 지정)
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(connection, {
    body: {
      discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "archived test thread",
      status: "archived",
      is_pinned: false,
      is_locked: false,
      archived: true,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 3. 멤버 B 등록
  const memberB_id = typia.random<string & tags.Format<"uuid">>();
  const memberB_createdAt = new Date().toISOString();
  const memberB = await api.functional.prefix.member.actors.members.create(connection, {
    body: {
      id: memberB_id,
      created_at: memberB_createdAt,
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(memberB);

  // 4. 멤버 B 인증 컨텍스트로 스레드 아카이브 상세조회 시도
  // (실제 시스템에선 connection.headers.Authorization 등 토큰 교체 필요. 여기서는 분리된 컨텍스트가 없으니 동일 connection 활용.)
  await TestValidator.error("non-owner member B access to thread archive must fail")(
    async () => {
      await api.functional.prefix.member.threadsPosts.threadArchives.at(connection, {
        id: thread.id,
      });
    }
  );
}

