    title: "Poll Test Thread",
    status: "active",
    is_pinned: false,
    is_locked: false,
    archived: false,
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
    updated_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(connection, { body: threadInput });
  typia.assert(thread);

