  TestValidator.equals("allow_multiple_choices updated")(updated.allow_multiple_choices)(false);
  TestValidator.equals("is_anonymous updated")(updated.is_anonymous)(true);
  TestValidator.equals("expires_at updated")(updated.expires_at)(updateInput.expires_at);

  TestValidator.equals("ownership enforced after update")(updated.created_by_member_id)(member.id);
