/**
 * Test rejection of warning log update with off-schema (invalid) fields.
 *
 * This test verifies that the API strictly enforces the update schema and does not allow off-schema fields. We attempt to update a warning log using a request body containing properties not defined in IWarningLog.IUpdate (such as invalid or extraneous keys), and expect the system to reject the request with a validation error, confirming strong schema compliance.
 *
 * Steps:
 * 1. Create a test warning log using the create endpoint to establish an owned record.
 * 2. Attempt to update the log by sending a request body that includes both valid fields and at least one invalid field (not present in IWarningLog.IUpdate).
 * 3. Assert that the operation is rejected with a schema validation error (no silent acceptance or unexpected success).
 * 4. Optionally, verify that a valid update with correct fields still succeeds (to show API distinction).
 */
export async function test_api_warningLogs_test_update_warning_log_with_invalid_fields_rejected(
  connection: api.IConnection,
) {
  // 1. Create a warning log for ownership
  const warningLog = await api.functional.prefix.moderator.warningLogs.create(connection, {
    body: {
      moderator_id: typia.random<string & tags.Format<"uuid">>(),
      warned_member_id: typia.random<string & tags.Format<"uuid">>(),
      warning_reason: "Initial warning reason",
      issued_at: new Date().toISOString(),
    },
  });
  typia.assert(warningLog);

  // 2. Attempt update with off-schema/inappropriate field
  const invalidBody = {
    warning_reason: "Updated reason by test",
    issued_at: new Date().toISOString(),
    not_a_real_field: "should cause validation error"
  };
  await TestValidator.error("off-schema field in update should fail")(async () => {
    await api.functional.prefix.moderator.my.warningLogs.update(connection, {
      id: warningLog.id,
      body: invalidBody as any, // Intentionally force off-schema
    });
  });

  // 3. Valid update should still succeed as control
  const validUpdate = await api.functional.prefix.moderator.my.warningLogs.update(connection, {
    id: warningLog.id,
    body: {
      warning_reason: "Updated reason (valid)",
      issued_at: new Date().toISOString(),
    },
  });
  typia.assert(validUpdate);
  TestValidator.equals("update id")(validUpdate.id)(warningLog.id);
  TestValidator.equals("update moderator_id")(validUpdate.moderator_id)(warningLog.moderator_id);
  TestValidator.equals("update warned_member_id")(validUpdate.warned_member_id)(warningLog.warned_member_id);
  TestValidator.equals("updated reason")(validUpdate.warning_reason)("Updated reason (valid)");
}

