    body: {
      moderator_id: moderatorId,
      action_type: "warned",
      action_description: "초기 경고 기록",
      action_timestamp: new Date().toISOString() as string & tags.Format<"date-time">,
      affected_post_id: typia.random<string & tags.Format<"uuid">>(),
