  TestValidator.equals("affected_post_id")(updatedModerationAction.affected_post_id)(updatedFields.affected_post_id);
  TestValidator.equals("affected_member_id")(updatedModerationAction.affected_member_id)(updatedFields.affected_member_id);
  TestValidator.equals("action_timestamp")(updatedModerationAction.action_timestamp)(updatedFields.action_timestamp);

  // 5. 실제로 moderation action의 주요값이 업데이트 되었는지, 변경 전 데이터와 다른지 확인
  TestValidator.notEquals("old and updated action_type")(updatedModerationAction.action_type)(originalModerationAction.action_type);
  TestValidator.notEquals("old and updated action_description")(updatedModerationAction.action_description)(originalModerationAction.action_description);
