 * 2. Filter by configuration ID; assert only matching section returned.
 * 3. Filter by name; assert only matching section returned.
 * 4. Filter by enabled state; assert only enabled/disabled sections returned.
 * 5. Filter by order; assert only correct order is returned.
 * 6. Pagination: set limit=1 and various pages; check output.
 * 7. Test sorting by 'name:desc', 'order:asc', etc.; check sorted output.
 * 8. Edge: non-existent filters (random config/name) => expect empty data.
 * 9. Edge: large offset/page with no results => expect empty data.
 * 10. Edge: invalid sorting (unsupported column) => expect validation error.
 */
export async function test_api_prefix_admin_discussionboardSections_test_list_sections_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Prepare two sections with distinct values
  const configurationId1 = typia.random<string & tags.Format<"uuid">>();
  const configurationId2 = typia.random<string & tags.Format<"uuid">>();
  const baseOrder = typia.random<number & tags.Type<"int32">>();
  const section1 = await api.functional.prefix.admin.discussionboardSections.create(connection, {
    body: {
      discussionboard_configuration_id: configurationId1,
      name: "Alpha Section",
      description: "The main alpha section.",
      order: baseOrder,
      enabled: true,
    },
  });
  typia.assert(section1);
  const section2 = await api.functional.prefix.admin.discussionboardSections.create(connection, {
    body: {
      discussionboard_configuration_id: configurationId2,
      name: "Beta Section",
      description: "The beta secondary section.",
      order: baseOrder + 1,
      enabled: false,
    },
  });
  typia.assert(section2);

  // 2. Filter by configuration ID
  let res = await api.functional.prefix.admin.discussionboardSections.index(connection, {
    body: {
      filters: { discussionboard_configuration_id: configurationId1 },
    },
  });
  typia.assert(res);
  TestValidator.equals("searched by config id")(res.data.length)(1);
  TestValidator.equals("config id match")(res.data[0].discussionboard_configuration_id)(configurationId1);

  // 3. Filter by name
  res = await api.functional.prefix.admin.discussionboardSections.index(connection, {
    body: { filters: { name: "Beta Section" } },
  });
  typia.assert(res);
  TestValidator.equals("searched by name")(res.data.length)(1);
  TestValidator.equals("name match")(res.data[0].name)("Beta Section");

  // 4. Filter by enabled state (true)
  res = await api.functional.prefix.admin.discussionboardSections.index(connection, {
    body: { filters: { enabled: true } },
  });
  typia.assert(res);
  TestValidator.predicate("enabled section included")(res.data.some(s => s.enabled === true));

  // 4b. Filter by enabled state (false)
  res = await api.functional.prefix.admin.discussionboardSections.index(connection, {
    body: { filters: { enabled: false } },
  });
  typia.assert(res);
  TestValidator.predicate("disabled section included")(res.data.some(s => s.enabled === false));

  // 5. Filter by order
  res = await api.functional.prefix.admin.discussionboardSections.index(connection, {
    body: { filters: { order: baseOrder } },
  });
  typia.assert(res);
  TestValidator.equals("filtered by order")(res.data.length)(1);
