  res = await api.functional.prefix.admin.discussionboardSections.index(connection, { body: { limit: 1, page: 1 } });
  typia.assert(res);
  TestValidator.equals("pagination limit")(res.pagination.limit)(1);
  TestValidator.predicate("pagination returns at most one")(res.data.length <= 1);

  // Go to second page
  res = await api.functional.prefix.admin.discussionboardSections.index(connection, { body: { limit: 1, page: 2 } });
  typia.assert(res);
  TestValidator.equals("pagination page 2")(res.pagination.current)(2);
  TestValidator.predicate("pagination second page at most one")(res.data.length <= 1);

  // 7. Sorting by 'name:desc'
  res = await api.functional.prefix.admin.discussionboardSections.index(connection, { body: { sort: ["name:desc"] } });
  typia.assert(res);
  TestValidator.predicate("sorted name descending")(res.data.length === 0 || res.data.every((v,i,a) => i===0 || a[i-1].name >= v.name));

