  // 8. Edge: non-existent filters
  const fakeConfig = typia.random<string & tags.Format<"uuid">>();
  res = await api.functional.prefix.admin.discussionboardSections.index(connection, { body: { filters: { discussionboard_configuration_id: fakeConfig } } });
