  TestValidator.equals("id matches")(res.data[0].id)(section1.id);

  // 3. Filter by name (should yield only section2)
  res = await api.functional.prefix.admin.discussionboardSections.index(
    connection,
    {
      body: { filters: { name: sectionName2 } },
