import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/ISuspension";

/**
 * 테스트 목적: 모더레이터가 회원 정지를 신규로 생성하는 기능을 검증한다.
 * 
 * 이 테스트에서는 정상적인 입력(모든 필수필드 present/포맷 유효)으로 신규 정지 내역을 생성하며,
 * 서버가 요청 데이터를 바르게 반영해 결과 레코드를 반환하는지,
 * 실제로 시스템 내에 데이터가 생성되어 조회로 확인 가능한지까지 검증한다.
 *
 * 또한, 아래와 같은 에러 상황/경계 조건도 검증한다.
 * - 존재하지 않는 member_id를 사용 시 에러가 발생하는지
 * - 필수 필드 누락 상황에서 유효성 에러가 발생하는지
 * - 잘못된 정지 기간(종료 시점이 과거 등) 입력 시 에러
 * - 비인가 역할(비모더레이터)이 호출 시 403/401 등이 발생하는지
 *
 * 구현 가능한 범위 내에서 테스트를 진행하고,
 * 실제 구현체/엔드포인트에서 지원되지 않는 시나리오는 생략한다.
 *
 * 1. 모더레이터 계정으로 정상 suspension 생성 (실제 데이터 검증)
 * 2. 잘못된 member_id를 사용해 생성 시도 후 에러 검증
 * 3. 필수 필드 누락/불완전 데이터로 생성 시도 후 에러 검증
 * 4. 종료 시점이 과거인 suspension 생성 시도 후 에러 검증
 * 5. 비모더레이터(예: 일반 사용자 권한)로 suspension 생성 시도 시 권한 에러 검증
 */
export async function test_api_suspensions_test_create_suspension_with_valid_data_moderator(
  connection: api.IConnection,
) {
  // 1. 정상 케이스: 모더레이터가 suspension 생성
  const now = new Date();
  const startedAt = now.toISOString();
  const endsAt = new Date(now.getTime() + 1000 * 60 * 60 * 24 * 7).toISOString(); // 7일 뒤

  const validInput: ISuspension.ICreate = {
    moderator_id: typia.random<string & tags.Format<"uuid">>(),
    suspended_member_id: typia.random<string & tags.Format<"uuid">>(),
    suspension_reason: "악의적 게시물 반복 등록",
    suspension_started_at: startedAt,
    suspension_ends_at: endsAt
  };
  const created = await api.functional.prefix.moderator.suspensions.create(connection, { body: validInput });
  typia.assert(created);
  TestValidator.equals("moderator_id")(created.moderator_id)(validInput.moderator_id);
  TestValidator.equals("suspended_member_id")(created.suspended_member_id)(validInput.suspended_member_id);
  TestValidator.equals("suspension_reason")(created.suspension_reason)(validInput.suspension_reason);
  TestValidator.equals("suspension_started_at")(created.suspension_started_at)(validInput.suspension_started_at);
  TestValidator.equals("suspension_ends_at")(created.suspension_ends_at)(validInput.suspension_ends_at);

  // 2. 존재하지 않는 member_id로 생성 시 에러
  const invalidInput = { ...validInput, suspended_member_id: typia.random<string & tags.Format<"uuid">>() };
  await TestValidator.error("존재하지 않는 member_id 에러")(() =>
    api.functional.prefix.moderator.suspensions.create(connection, { body: invalidInput }),
  );

  // 3. 필수 필드 누락 케이스: (TypeScript 상, 필수 누락은 컴파일 에러로 걸리므로 E2E에서 건너뜀)

  // 4. 과거 종료 시점 입력: 시작/종료 순서 잘못된 경우
  const endsAtPast = new Date(now.getTime() - 1000 * 60 * 60 * 24).toISOString(); // 1일 전 종료
  const pastEndInput = { ...validInput, suspension_ends_at: endsAtPast };
  await TestValidator.error("종료 시점이 과거일 때 에러")(() =>
    api.functional.prefix.moderator.suspensions.create(connection, { body: pastEndInput }),
  );

  // 5. 비인가자 권한(예: connection.headers.Authorization 미설정) -> 별도의 권한 부여 없이 호출
  const nonModConnection = { ...connection, headers: {} };
  await TestValidator.error("비인가자 권한 에러")(() =>
    api.functional.prefix.moderator.suspensions.create(nonModConnection as api.IConnection, { body: validInput }),
  );
}

