 * 2. Update the member's created_at field to a new timestamp using the PUT endpoint.
 * 3. Validate that the response matches the updated created_at and correct id.
 * 4. If possible, simulate an unauthorized access case and ensure a proper error is thrown.
 */
export async function test_api_member_test_update_member_created_at_valid(connection: api.IConnection) {
  // 1. Register new member
  const initial: IDiscussionboardMembers = await api.functional.prefix.member.actors.members.create(connection, {
    body: {
      id: typia.random<string & tags.Format<"uuid">>(),
      created_at: typia.random<string & tags.Format<"date-time">>(),
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(initial);

