  const newCreatedAt = typia.random<string & tags.Format<"date-time">>();
  const updated: IDiscussionboardMembers = await api.functional.prefix.member.my.actors.members.update(connection, {
    id: initial.id,
    body: {
      id: initial.id,
      created_at: newCreatedAt,
    } satisfies IDiscussionboardMembers.IUpdate,
  });
  typia.assert(updated);

  // 3. Validate the update
  TestValidator.equals("id should remain unchanged")(updated.id)(initial.id);
  TestValidator.equals("created_at should be updated")(updated.created_at)(newCreatedAt);

  // 4. (Optional) Unauthorized test - attempt to update with a fresh connection (no user context)
  await TestValidator.error("cannot update another member w/o ownership")(
    async () => {
      const altConnection = { ...connection };
      // Optionally, drop authentication info if structure supports it
      if (altConnection.headers) delete altConnection.headers["Authorization"];
      await api.functional.prefix.member.my.actors.members.update(altConnection, {
        id: initial.id,
        body: {
          id: initial.id,
          created_at: typia.random<string & tags.Format<"date-time">>(),
        },
      });
    }
  );
}

