import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IThreadTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IThreadTag";

/**
 * Validate hard deletion of a thread tag by an admin.
 *
 * This test ensures that a thread tag can be hard deleted (permanently removed) by an admin user, and that once deleted it cannot be fetched anymore—which means the deletion is irreversible and the record is gone from the database.
 *
 * Process:
 * 1. (Precondition) Ensure an admin is authenticated (assumed by test runner setup / connection context).
 * 2. Create a thread tag—the tag to be deleted in this test—in a manner available to members (creates the record in DB).
 * 3. Perform the hard delete of the just-created tag via the admin DELETE endpoint.
 * 4. Attempt to fetch the tag by ID using the detail endpoint to confirm the deletion; expect a not found error (verifies irrecoverable deletion).
 */
export async function test_api_threadTags_test_delete_thread_tag_successful_hard_delete(
  connection: api.IConnection,
) {
  // 1. Create a thread tag as a member (setup target for deletion)
  const newTag = await api.functional.prefix.member.threadTags.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(8),
      display_name: RandomGenerator.paragraph()(1),
      description: RandomGenerator.paragraph()(2),
      is_restricted: false,
      is_hidden: false,
      created_at: new Date().toISOString() as string & tags.Format<"date-time">,
    } satisfies IThreadTag.ICreate,
  });
  typia.assert(newTag);

  // 2. Hard delete the tag via admin endpoint
  await api.functional.prefix.admin.threadTags.erase(connection, {
    threadTagId: newTag.id,
  });

  // 3. Attempt to fetch the tag to confirm it's not found (irrecoverable)
  await TestValidator.error("Should not find deleted tag")(() =>
    api.functional.prefix.threadTags.at(connection, { threadTagId: newTag.id })
  );
}

