 * - Id, created_at 등은 uuid/date-time 규격으로 랜덤 정상값을 부여합니다.
 * - 권한 switching 또는 인증 mock은 제공된 API 내에서만 처리(외부 확장 불가).
 * - Moderation action의 삭제 검증을 위한 조회 API가 없다면, 별도 테스트 케이스 내 error throw 등 직접 확인
 *   불가함을 명시합니다.
 */
export async function test_api_moderationActions_test_delete_own_moderation_action_success(
  connection: api.IConnection,
) {
  // 1. 관리자가 임의 멤버에게 모더레이터 역할을 부여
  const moderatorId: string = typia.random<string & tags.Format<"uuid">>();
  const moderatorAssignment =
    await api.functional.prefix.admin.actors.moderators.create(connection, {
      body: {
        id: moderatorId,
        created_at: new Date().toISOString(),
      },
    });
