  // 3. moderation action id로 하드 삭제 실행
  await api.functional.prefix.moderator.my.moderationActions.erase(connection, {
    id: moderationAction.id,
  });

  // 4. 실제 삭제되었는지 직접 확인하려면 별도 조회 API 필요.
