import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardGuests } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardGuests";

/**
 * 게스트 역할 기록(created_at)의 갱신을 회원 인증 상태에서 검증한다.
 *
 * 1. (의존성) 게스트 레코드를 생성한다.
 * 2. 생성된 id로 PUT /prefix/member//my/actors/guests/{id}를 호출하면서 created_at 타임스탬프를 새 값으로 갱신한다.
 * 3. 응답값의 id는 변경되지 않고 동일해야 하며, created_at은 요청에 사용된 값으로 업데이트되어야 한다.
 * 4. 허용 필드는 id, created_at뿐이며, id 필드가 바뀌는(불일치) 값으로 PUT 시도 시 오류를 확인한다.
 */
export async function test_api_prefix_member_my_actors_guests_test_update_guest_record_created_at_field_successfully(
  connection: api.IConnection,
) {
  // 1. 테스트용 게스트 세션(레코드) 생성
  const guestCreate: IDiscussionboardGuests = await api.functional.prefix.member.actors.guests.create(connection, {
    body: {
      id: typia.random<string & tags.Format<"uuid">>(),
      created_at: new Date().toISOString(),
    } satisfies IDiscussionboardGuests.ICreate,
  });
  typia.assert(guestCreate);

  // 2. created_at 값을 새 타임스탬프로 업데이트(PUT)
  const updatedCreatedAt = new Date(Date.now() + 1000 * 60 * 60).toISOString();
  const guestUpdated: IDiscussionboardGuests = await api.functional.prefix.member.my.actors.guests.update(connection, {
    id: guestCreate.id,
    body: {
      id: guestCreate.id,
      created_at: updatedCreatedAt,
    } satisfies IDiscussionboardGuests.IUpdate,
  });
  typia.assert(guestUpdated);

  // 3. 응답의 id 불변, created_at 업데이트 반영 확인
  TestValidator.equals("id는 동일해야 함")(guestUpdated.id)(guestCreate.id);
  TestValidator.equals("created_at이 요청값으로 갱신되어야 함")(guestUpdated.created_at)(updatedCreatedAt);

  // 4. id필드가 다른 값으로 PUT 시 오류 확인
  await TestValidator.error("id 불일치 PUT은 오류")(async () =>
    api.functional.prefix.member.my.actors.guests.update(connection, {
      id: guestCreate.id,
      body: {
        id: typia.random<string & tags.Format<"uuid">>(), // 다른 id로 시도
        created_at: updatedCreatedAt,
      } satisfies IDiscussionboardGuests.IUpdate,
    })
  );
}

