import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IMention";
import type { IPageIMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIMention";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { discussionboard_mentions } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboard_mentions";

/**
 * Validate pagination and sorting in the mentions listing API.
 *
 * This test ensures that the mentions list endpoint correctly implements pagination (limit, offset/page) and sorting (by created_at descending). It guarantees that when multiple mentions exist for the same member and post, the correct subset is returned and is sorted as expected.
 *
 * Test Steps:
 * 1. Create a member who will be mentioned
 * 2. Create a discussion thread
 * 3. Create a post in the thread (could create more for further diversity)
 * 4. Create several mention records, each involving the member and the post, at different times (simulate different created_at values by creating sequentially with small delays if possible)
 * 5. Query the mentions listing endpoint with limit and page/offset for pagination — request a subpage (e.g., limit=2, page=2)
 * 6. Validate the response's pagination metadata (current page, limit, total records, correct number of returned items)
 * 7. Validate the mentions in the result are sorted by created_at descending
 * 8. For additional robustness, try requesting with a different limit and check the first/last page's consistency
 */
export async function test_api_mentions_test_mentions_list_pagination_and_sorting(
  connection: api.IConnection,
) {
  // 1. Create the member to be mentioned
  const mentionedMember = await api.functional.prefix.member.actors.members.create(connection, {
    body: {
      id: typia.random<string & tags.Format<'uuid'>>(),
      created_at: new Date().toISOString() as string & tags.Format<'date-time'>,
    },
  });
  typia.assert(mentionedMember);

  // 2. Create a discussion thread (for simplicity, faked category ID)
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(connection, {
    body: {
      discussionboard_category_id: typia.random<string & tags.Format<'uuid'>>(),
      title: 'Pagination Mention Test ' + Date.now(),
      status: 'active',
      is_pinned: false,
      is_locked: false,
      archived: false,
      created_at: new Date().toISOString() as string & tags.Format<'date-time'>,
      updated_at: new Date().toISOString() as string & tags.Format<'date-time'>,
    },
  });
  typia.assert(thread);

  // 3. Create a post to mention the member in
  const post = await api.functional.prefix.member.threadsPosts.posts.create(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      body: 'Test for mention pagination',
    },
  });
  typia.assert(post);

  // 4. Create multiple mention records for the same member/post (simulate at different times)
  const mentionCount = 5;
  const createdMentions: discussionboard_mentions[] = [];
  for (let i = 0; i < mentionCount; ++i) {
    // For sort testing, later mentions have newer created_at
    const mention = await api.functional.prefix.member.mentions.create(connection, {
      body: {
        discussionboard_post_id: post.id,
        mentioned_member_id: mentionedMember.id,
      },
    });
    typia.assert(mention);
    createdMentions.push(mention);
    // Optionally sleep here for a noticeable timestamp difference, if can
  }
  // Locally sort for comparison: newest to oldest
  const localSorted = [...createdMentions].sort(
    (a, b) => (b.created_at as string).localeCompare(a.created_at as string),
  );

  // 5. Query with specific pagination (limit=2, page=2)
  const limit = 2;
  const page = 2;
  const mentionPage = await api.functional.prefix.member.mentions.index(connection, {
    body: {
      mentioned_member_id: mentionedMember.id,
      discussionboard_post_id: post.id,
      limit,
      page,
    },
  });
  typia.assert(mentionPage);

  // 6. Validate pagination metadata
  TestValidator.equals('current page')(mentionPage.pagination.current)(page);
  TestValidator.equals('limit')(mentionPage.pagination.limit)(limit);
  TestValidator.equals('records')(mentionPage.pagination.records)(createdMentions.length);
  // 7. Validate correct mentions returned and are ordered descending
  TestValidator.equals('data length')(mentionPage.data.length)(limit);
  for (let i = 0; i < mentionPage.data.length; ++i) {
    TestValidator.equals(`mention id ${i}`)(mentionPage.data[i].id)(localSorted[(page - 1) * limit + i].id);
    // Sequentially newest at first
  }

  // 8. Request different limit (limit=3, page=1)
  const newLimit = 3;
  const firstPage = await api.functional.prefix.member.mentions.index(connection, {
    body: {
      mentioned_member_id: mentionedMember.id,
      discussionboard_post_id: post.id,
      limit: newLimit,
      page: 1,
    },
  });
  typia.assert(firstPage);
  TestValidator.equals('first page length')(firstPage.data.length)(newLimit);
  for (let i = 0; i < firstPage.data.length; ++i) {
    TestValidator.equals(`first page id ${i}`)(firstPage.data[i].id)(localSorted[i].id);
  }
}

