import type { IPageDiscussionboardNotifications } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardNotifications";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate the retrieval (search/paginated listing) of discussion board notifications for an authenticated member.
 *
 * This test verifies that notifications can be created and retrieved with various filtering and pagination settings, ensuring response correctness, filtering compliance, and strict result ownership (no leakage from unrelated members).
 *
 * Steps:
 * 1. Register/login a test member (simulate or assume authenticated connection).
 * 2. Create multiple distinct notifications for the member using the 'create' API.
 * 3. List notifications with default request (no filters):
 *     - Read out some or all results and verify that only the member's notifications are listed.
 * 4. List with filter: type (e.g., filter for a specific category/type).
 *     - Ensure pagination/data returned matches expected filtered subset.
 * 5. List with opened filter (opened: true and opened: false).
 *     - Ensure opened/unopened filtering works correctly.
 * 6. List with pagination settings (e.g., limit, page):
 *     - Validate page metadata and result slicing.
 * 7. Ensure all notifications returned have discussionboard_member_id of the test member.
 */
export async function test_api_prefix_member_my_discussionboardNotifications_test_list_member_notifications_success(
  connection: api.IConnection,
) {
  // 1. Assume connection is authenticated as test member
  // 2. Create N notifications with various combinations of type/title/body/opened
  const types = [
    "mention",
    "moderator_action",
    "announcement",
    "reply",
  ];
  const notifications: discussionboard_notifications[] = [];
  for (let i = 0; i < 7; ++i) {
    const notif = await api.functional.prefix.member.my.discussionboardNotifications.create(
      connection,
      {
        body: {
          type: types[i % types.length],
          title: `Test Notification ${i + 1}`,
          body: i % 2 === 0 ? `Content body ${i + 1}` : undefined,
          url:
            i % 3 === 0
              ? `/thread/${i}/post/${100 + i}`
              : undefined,
          opened: i % 2 === 0,
        } satisfies discussionboard_notifications.ICreate,
      },
    );
    typia.assert(notif);
    notifications.push(notif);
  }

  // 3. List notifications: no filters
  const resAll = await api.functional.prefix.member.my.discussionboardNotifications.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(resAll);
  // Ensure only correct member's notifications returned
  resAll.data.forEach((n) =>
    TestValidator.equals("ownership")(n.discussionboard_member_id)(notifications[0].discussionboard_member_id),
  );

  // 4. List with filter: type (e.g. "mention")
  const resType = await api.functional.prefix.member.my.discussionboardNotifications.index(
    connection,
    {
      body: { type: "mention" },
    },
  );
  typia.assert(resType);
  resType.data.forEach((n) =>
    TestValidator.equals("type filter")(n.type)("mention"),
  );

  // 5. List with filter: opened = true
  const resOpened = await api.functional.prefix.member.my.discussionboardNotifications.index(
    connection,
    {
      body: { opened: true },
    },
  );
  typia.assert(resOpened);
  resOpened.data.forEach((n) =>
    TestValidator.equals("opened filter")(n.opened)(true),
  );

  // List with filter: opened = false
  const resUnopened = await api.functional.prefix.member.my.discussionboardNotifications.index(
    connection,
    {
      body: { opened: false },
    },
  );
  typia.assert(resUnopened);
  resUnopened.data.forEach((n) =>
    TestValidator.equals("opened filter")(n.opened)(false),
  );

  // 6. List with pagination: limit
  const resPaginated = await api.functional.prefix.member.my.discussionboardNotifications.index(
    connection,
    {
      body: { limit: 3, page: 1 },
    },
  );
  typia.assert(resPaginated);
  TestValidator.equals("page 1 size")(resPaginated.data.length)(Math.min(3, notifications.length));
  TestValidator.equals("pagination meta")(resPaginated.pagination.limit)(3);

  if (notifications.length > 3) {
    // Page 2
    const resPage2 = await api.functional.prefix.member.my.discussionboardNotifications.index(
      connection,
      {
        body: { limit: 3, page: 2 },
      },
    );
    typia.assert(resPage2);
    // Up to 3 notifications, starting from index 3
    // Optionally check the data matches correct notification set by title
    resPage2.data.forEach((n, idx) =>
      TestValidator.equals("correct notification title")(
        n.title,
      )(`Test Notification ${idx + 4}`),
    );
    TestValidator.equals("pagination meta")(resPage2.pagination.limit)(3);
  }
