import type { IModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationAction";

/**
 * Ensure that after a content report has been handled by a moderator, the guest who reported it can no longer update the report.
 *
 * Business context:
 * - Guest users can report posts for moderation by creating a content report specifying the post, reasoning, etc.
 * - Once submitted, a content report is considered under workflow (status: 'pending').
 * - A privileged moderator can process this report (e.g., by updating status to 'action_taken' or 'dismissed'), after which the report should be locked against further edits by the original guest reporter to maintain audit trail and moderator authority.
 * - The guest should NOT be able to update the report after moderator action.
 *
 * Steps:
 * 1. Provision a guest entity for the session (ID, created_at).
 * 2. Create a new post (to serve as the target for reporting) as a member context.
 * 3. Guest files a content report for the created post.
 * 4. Simulate a moderator processing this report by updating moderation action.
 * 5. Guest attempts to update the report; server must reject this with an error (forbidden or validation failure).
 * 6. Test validates that the update attempt fails as required, confirming business logic lockout is effective.
 */
export async function test_api_contentReports_test_update_guest_content_report_after_moderation_forbidden(connection: api.IConnection) {
  // 1. Create guest (assign guest ID and creation date)
  const guestPayload = {
    id: typia.random<string & tags.Format<'uuid'>>(),
    created_at: new Date().toISOString() as string & tags.Format<'date-time'>,
  } satisfies IDiscussionboardGuests.ICreate;
  const guest = await api.functional.prefix.member.actors.guests.create(connection, { body: guestPayload });
  typia.assert(guest);

  // 2. Create a post (as member)
  const postPayload = {
    discussionboard_thread_id: typia.random<string & tags.Format<'uuid'>>(),
    body: 'Post body for moderation test.',
    is_edited: false,
  } satisfies IDiscussionboardPosts.ICreate;
  const post = await api.functional.prefix.member.threadsPosts.posts.create(connection, { body: postPayload });
  typia.assert(post);

  // 3. Guest files a report on the post
  const reportPayload = {
    reported_post_id: post.id,
    reporter_member_id: null,
    reporter_guest_id: guest.id,
    report_reason: 'Offensive content',
    status: 'pending',
    reported_at: new Date().toISOString() as string & tags.Format<'date-time'>,
    moderator_note: null,
  } satisfies IContentReport.ICreate;
  const report = await api.functional.prefix.guest.contentReports.create(connection, { body: reportPayload });
  typia.assert(report);

  // 4. Simulate moderator processes the report by creating or updating a moderation action
  const moderatorActionPayload = {
    report_id: report.id,
    affected_post_id: post.id,
    affected_member_id: null,
    action_type: 'action_taken',
    action_description: 'Moderator reviewed and took action.',
    action_timestamp: new Date().toISOString() as string & tags.Format<'date-time'>,
  } satisfies IModerationAction.IUpdate;
  // For the sake of this test, we use the report ID as moderation action ID stub (real system may link differently)
  await api.functional.prefix.moderator.my.moderationActions.update(connection, {
    id: report.id,
    body: moderatorActionPayload,
  });
  // (response is ignored – we only care that moderator processed the report)

  // 5. Attempt to update the report as guest again; this should be forbidden
  await TestValidator.error('Guest cannot update content report after moderation')(
    async () => {
      await api.functional.prefix.guest.my.contentReports.update(connection, {
        id: report.id,
        body: {
          report_reason: 'Trying to alter after lock',
          status: 'pending',
          moderator_note: null,
        } satisfies IContentReport.IUpdate,
      });
    },
  );
}

