/**
 * Validates listing of search histories for the authenticated member when search records exist.
 *
 * This test creates multiple search history entries for the currently authenticated member, including one with a soft-deleted (deleted_at set) state. It then lists search histories using the PATCH /prefix/member//my/searchHistories endpoint with various pagination and filter parameters. The test asserts that:
 *
 * 1. All non-deleted search records for the authenticated member are returned.
 * 2. The total number and content of records match those that were created and not soft-deleted.
 * 3. Records with deleted_at set are excluded from the results by default.
 * 4. Pagination and search_query filtering works correctly (optional step).
 *
 * Steps:
 * 1. (Setup) Create multiple search histories for the current member using POST /prefix/member//my/searchHistories, supplying explicit search_query and used_filters values, with at least one record having deleted_at set.
 * 2. Call PATCH /prefix/member//my/searchHistories with default filter (no search_query, no include_deleted), ensure it returns only non-deleted records of this member, matching number and data as setup (assert by search_query values).
 * 3. Confirm records with deleted_at set are excluded from default results.
 * 4. (Optionally) Use search_query parameter to filter results; validate only relevant entries are returned.
 * 5. (Optionally) Test pagination (limit/offset) and validate page metadata and subset of records.
 */
export async function test_api_prefix_member_my_searchHistories_test_list_search_histories_for_authenticated_member_with_results(connection: api.IConnection) {
  // 1. Create multiple search history entries for member, with one soft-deleted
  const created1 = await api.functional.prefix.member.my.searchHistories.create(connection, { body: { search_query: "foo bar one", used_filters: "topic:economics", executed_at: new Date().toISOString() } });
  typia.assert(created1);
  const created2 = await api.functional.prefix.member.my.searchHistories.create(connection, { body: { search_query: "search test", used_filters: "topic:science", executed_at: new Date().toISOString() } });
  typia.assert(created2);
  // Create a soft-deleted record
  const createdDeleted = await api.functional.prefix.member.my.searchHistories.create(connection, { body: { search_query: "hidden result", used_filters: "delete", executed_at: new Date().toISOString(), deleted_at: new Date().toISOString() } });
  typia.assert(createdDeleted);

  // 2. List with PATCH, no filters (default - should return only non-deleted records)
  const list = await api.functional.prefix.member.my.searchHistories.index(connection, { body: {} });
  typia.assert(list);
  // Data should contain created1 and created2 (by search_query), not the soft-deleted one
  const searchQueries = list.data.map(x => x.search_query);
  TestValidator.predicate("created1 present")(searchQueries.includes("foo bar one"));
  TestValidator.predicate("created2 present")(searchQueries.includes("search test"));
  TestValidator.predicate("deleted absent")(searchQueries.includes("hidden result") === false);
  TestValidator.equals("total records")(list.data.length)(2);

  // 3. Optionally, verify searching by search_query filter works
  const filterList = await api.functional.prefix.member.my.searchHistories.index(connection, { body: { search_query: "foo bar" } });
  typia.assert(filterList);
  TestValidator.equals("filtered single match")(filterList.data.length)(1);
  TestValidator.equals("filter correct record")(filterList.data[0].search_query)("foo bar one");

  // 4. Optionally, check pagination fields
  TestValidator.predicate("pagination shape")(typeof list.pagination.current === "number" && typeof list.pagination.limit === "number");
}

