/**
 * Test the successful update of a mention entry by its owner.
 *
 * This test verifies that once an authenticated member has a valid mention record,
 * they can update it to refer to another valid discussion post, or to another member, or both.
 * The workflow reflects a scenario where tagged notifications or references may require post-publication adjustment
 * (e.g. moderation, user correction, or system-initiated moves).
 *
 * Steps:
 * 1. Register member1 (the actor) and member2 (another member who can be mentioned)
 * 2. Create two discussionboard posts (postA, postB)
 * 3. Authenticate as member1 and create a mention for member2 in postA
 * 4. Update the mention: change the referenced post to postB, keeping member2
 * 5. Update the mention: change the mentioned_member_id to member1 (i.e. self-mention), keeping the post as postB
 * 6. Validate that updates succeed and returned mention object is correct
 *
 * Schema validation is performed after each update to ensure type correctness and data integrity.
 */
export async function test_api_prefix_member_my_mentions_test_update_mention_success(
  connection: api.IConnection,
) {
  // 1. Register member1 and member2 (assume member registration API exists/standard pattern in test suite)
  // --- for this test, skip actual member creation since registration API is not provided ---

  // Generate UUIDs for two members (simulate registration)
  const member1_id = typia.random<string & tags.Format<"uuid">>();
  const member2_id = typia.random<string & tags.Format<"uuid">>();

  // 2. Create two posts (simulate existing posts with random uuids)
  const postA_id = typia.random<string & tags.Format<"uuid">>();
  const postB_id = typia.random<string & tags.Format<"uuid">>();

  // 3. Create initial mention as member1 (mentioning member2 in postA)
  const mention = await api.functional.prefix.member.mentions.create(connection, {
    body: {
      discussionboard_post_id: postA_id,
      mentioned_member_id: member2_id,
    } satisfies discussionboard_mentions.ICreate,
  });
