 *
 * 비즈니스 시나리오 및 필요성:
 * - 검색 기록 목록을 조회할 때, deleted_at 필드가 null이 아닌(즉, soft deleted) 레코드는 기본적으로 결과에서 제외되어야 하며
 *   오직 deleted_at가 null인 레코드(삭제되지 않은 history)만 기본적으로 반환되어야 합니다.
 * - 이는 사용자 데이터 보호 및 UI/경험적 일관성을 보장하기 위함입니다.
 *
 * 테스트 프로세스:
 * 1. deleted_at가 null인 검색 기록 2개 생성
 * 2. deleted_at가 미래 시간 등 null이 아닌(ex: 2099-12-31) soft deleted 검색 기록 1개 생성
 * 3. searchHistories 목록 API를 호출 (include_deleted: false이거나 미설정)
 * 4. 결과 데이터(data) 배열이 soft deleted 레코드(즉, deleted_at가 null이 아닌)에 대해선 제외되었는지 검증
 * 5. 모든 반환된 레코드의 deleted_at가 반드시 null임을 확인하여, soft deletion 정책이 지켜지는지 확인
 * 6. 역으로 include_deleted: true로 재요청하여, soft deleted 레코드가 포함되어 조회되는지도 검증
 */
export async function test_api_prefix_test_list_search_histories_exclude_soft_deleted(
  connection: api.IConnection,
) {
  // 1. deleted_at가 null인 검색 기록 2개 생성
  const searchHistoryA: ISearchHistory = {
    id: typia.random<string & tags.Format<"uuid">>(),
    search_query: "테스트쿼리A",
    executed_at: new Date().toISOString(),
    deleted_at: null,
  };
  const searchHistoryB: ISearchHistory = {
    id: typia.random<string & tags.Format<"uuid">>(),
    search_query: "테스트쿼리B",
    executed_at: new Date().toISOString(),
    deleted_at: null,
  };
  // 2. deleted_at가 null이 아닌(soft deleted) 검색 기록 1개 생성
  const searchHistorySoftDeleted: ISearchHistory = {
    id: typia.random<string & tags.Format<"uuid">>(),
    search_query: "삭제된쿼리",
    executed_at: new Date().toISOString(),
    deleted_at: "2099-12-31T23:59:59.000Z",
  };
  // (실제 모킹/삽입 API가 없으므로 response mocking 또는 response 검증만 수행)

  // 3. 기본 검색 기록 목록 가져오기 (include_deleted 미설정)
  const outputDefault = await api.functional.prefix.searchHistories.index(connection, {
    body: {},
  });
  typia.assert(outputDefault);
  // 4. 결과값의 모든 data에 대해 deleted_at가 null인지 확인
  for (const record of outputDefault.data) {
    TestValidator.equals("returned record must not be soft deleted")(record.deleted_at)(null);
  }

  // 5. include_deleted: true로 soft deleted 포함 요청 (없으면 soft deleted까지 반환되는지)
  const outputIncludeDeleted = await api.functional.prefix.searchHistories.index(connection, {
    body: { include_deleted: true },
  });
  typia.assert(outputIncludeDeleted);
  // 6. soft deleted된 레코드도 함께 등재되는지 확인 (deleted_at이 null이 아닌게 최소 한개 이상?)
  const hasSoftDeleted = outputIncludeDeleted.data.some(r => r.deleted_at !== null);
  TestValidator.predicate("at least one record is soft deleted")(hasSoftDeleted);
}

