 *
 * Steps:
 * 1. Create a thread tag (member-level, as precondition)
 * 2. As admin, update display_name, description, is_restricted, is_hidden fields using the update API
 * 3. Confirm the returned tag object reflects all updated values (fields match expectations and previous values are changed)
 */
export async function test_api_prefix_admin_threadTags_test_update_thread_tag_by_admin_success(
  connection: api.IConnection,
) {
  // 1. Create a thread tag (as prerequisite, via member API)
  const createInput: IThreadTag.ICreate = {
    code: RandomGenerator.alphabets(8),
    display_name: 'Initial Tag',
    description: 'Original tag description',
    is_restricted: false,
    is_hidden: false,
