  };
  const created: IThreadTag = await api.functional.prefix.member.threadTags.create(connection, { body: createInput });
  typia.assert(created);

  // 2. Prepare update payload (change several fields)
  const updateInput: IDiscussionboardThreadTag.IUpdate = {
    display_name: 'Updated Tag',
    description: 'Updated tag description',
    is_restricted: true,
    is_hidden: true,
    updated_at: new Date().toISOString() as string & tags.Format<'date-time'>,
  };

  // 3. Call admin update API
