  // 4. Validate field updates
  TestValidator.equals('display_name updated')(updated.display_name)('Updated Tag');
  TestValidator.equals('description updated')(updated.description)('Updated tag description');
  TestValidator.equals('is_restricted updated')(updated.is_restricted)(true);
  TestValidator.equals('is_hidden updated')(updated.is_hidden)(true);
  TestValidator.equals('id same')(updated.id)(created.id);
  TestValidator.notEquals('display_name changed')(updated.display_name)(created.display_name);
  TestValidator.notEquals('is_restricted changed')(updated.is_restricted)(created.is_restricted);
  TestValidator.notEquals('is_hidden changed')(updated.is_hidden)(created.is_hidden);
}

