      is_edited: false,
    } satisfies IDiscussionboardPosts.ICreate,
  });
  typia.assert(post);

  // Step 3: Member A edits the post to generate a post history snapshot
  const updatedContent = "Edited post by Member A";
  const updatedPost = await api.functional.prefix.member.my.threadsPosts.posts.update(connection, {
    id: post.id,
    body: {
      body: updatedContent,
      is_edited: true,
      updated_at: new Date().toISOString(),
    } satisfies IDiscussionboardPost.IUpdate,
  });
  typia.assert(updatedPost);

  // Step 4: Register as Member B
  const memberB_email = typia.random<string & tags.Format<"email">>();
  const memberB_password = "TestPassword2!";
  await api.functional.prefix.member.threadsPosts.members.create(connection, {
    body: { email: memberB_email, password: memberB_password }
  });
  await api.functional.prefix.member.threadsPosts.members.authenticate(connection, { body: { email: memberB_email, password: memberB_password } });

