  // For test: We assume updatedPost has a known history snapshot id, here just random for illustration
  const postHistoryId = typia.random<string & tags.Format<"uuid">>(); // ❗️Should really fetch actual, but limited by available APIs

  // Try to update as Member B and expect forbidden/unauthorized error
  await TestValidator.error("Non-owner cannot update post history snapshot")(
    async () => {
      return api.functional.prefix.member.my.threadsPosts.postHistories.update(connection, {
