      body: {
        moderator_id,
        warned_member_id: warned_member_id_in_db,
        warning_reason: warning_reason_in_db,
        issued_at: new Date().toISOString(),
      } satisfies IWarningLog.ICreate,
    },
  );
  typia.assert(warningLog);

  // 3. Try to search for logs with both a member_id and a reason string that are not present
  const no_match_warned_member_id = typia.random<
    string & tags.Format<"uuid">
  >();
  const no_match_reason = "no-matching-reason-string-unique";
  const page = await api.functional.prefix.moderator.warningLogs.index(
    connection,
