    {
      body: {
        warned_member_id: no_match_warned_member_id,
        page: 1,
        limit: 10,
      } satisfies IWarningLog.IRequest,
    },
  );
  typia.assert(page3);
  TestValidator.equals("No results when only warned_member_id is unmatched")(
