import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCategory";

/**
 * 테스트 목적: 카테고리 UPDATE 성공 플로우 검증
 *
 * 관리자가 토론 게시판 카테고리를 신규 생성한 직후, 카테고리 id로 해당 카테고리의 주요 프로퍼티(이름, 설명, 순서, 활성화 상태)를 PUT 메서드로 갱신할 수 있는지 확인한다. 변경사항이 실제 저장·반영되고 응답에 즉시 반영되는지도 검증한다.
 *
 * [테스트 단계]
 * 1. (Prerequisite) 카테고리 신규 생성(후보 데이터: name, description, order, enabled, sectionId)
 * 2. 생성된 카테고리 id를 대상 id로 선택
 * 3. PUT /prefix/admin//discussionboardCategories/{categoryId} 에 아래 내용 갱신 요청
 *     - name: 기존값과 다르게
 *     - description: 새 설명(기존과 다른 값)
 *     - order: 다른 정수값 지정
 *     - enabled: true/false (기존 상태와 반대)
 *     - discussionboard_section_id: 기존과 동일
 * 4. 응답 결과의 각 필드가 요청 body와 일치하는지 검증(갱신 요청값과 완전히 동일해야 함)
 * 5. 타입 단언 및 business 값 유효성 추가 점검
 */
export async function test_api_prefix_admin_discussionboardCategories_test_update_discussionboard_category_success(
  connection: api.IConnection,
) {
  // 1. 카테고리 신규 생성
  const sectionId = typia.random<string & tags.Format<"uuid">>();
  const createBody: IDiscussionboardCategory.ICreate = {
    discussionboard_section_id: sectionId,
    name: "초기이름" + RandomGenerator.alphabets(5),
    description: "초기 설명" + RandomGenerator.paragraph()(1, 2),
    order: typia.random<number & tags.Type<"int32">>(),
    enabled: true,
  };
  const created = await api.functional.prefix.admin.discussionboardCategories.create(
    connection,
    { body: createBody },
  );
  typia.assert(created);
  TestValidator.equals("초기값-name")(created.name)(createBody.name);
  TestValidator.equals("초기값-description")(created.description)(createBody.description);
  TestValidator.equals("초기값-section-id")(created.discussionboard_section_id)(createBody.discussionboard_section_id);
  TestValidator.equals("초기값-order")(created.order)(createBody.order);
  TestValidator.equals("초기값-enabled")(created.enabled)(createBody.enabled);

  // 2. UPDATE용 변경 정보 준비 (모든 필드 변경)
  const updateBody: IDiscussionboardCategory.IUpdate = {
    discussionboard_section_id: created.discussionboard_section_id, // section 변경은 안 함
    name: "수정된이름" + RandomGenerator.alphabets(5),
    description: "(수정) " + RandomGenerator.paragraph()(1, 2),
    order: created.order + 10,
    enabled: !created.enabled,
  };

  // 3. 카테고리 수정 요청
  const updated = await api.functional.prefix.admin.discussionboardCategories.update(
    connection,
    { categoryId: created.id, body: updateBody },
  );
  typia.assert(updated);

  // 4. 응답(수정 결과)의 각 필드가 요청 body 내용과 일치하는지 검증
  TestValidator.equals("id 동일해야 함")(updated.id)(created.id);
  TestValidator.equals("수정된-section-id")(updated.discussionboard_section_id)(updateBody.discussionboard_section_id);
  TestValidator.equals("수정된-name")(updated.name)(updateBody.name);
  TestValidator.equals("수정된-description")(updated.description)(updateBody.description);
  TestValidator.equals("수정된-order")(updated.order)(updateBody.order);
  TestValidator.equals("수정된-enabled")(updated.enabled)(updateBody.enabled);

  // 5. 타입 및 필드 누락 없이 구조 체크
  typia.assert<typeof updated>(updated);
}

