import api from "@ORGANIZATION/PROJECT-api";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";
import type { IPollVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPollVote";

/**
 * Validate moderator retrieval of poll vote details including schema field accessibility and error handling.
 *
 * This test simulates a moderator auditing poll vote records. Moderator should be able to access the detail of any poll vote, regardless of who cast it, for auditing or review. The test validates correct retrieval of all schema fields for a valid poll vote and handles not-found/invalid-id scenarios, as well as demonstrating enforcement of access rules. 
 *
 * Steps:
 * 1. As a member, create a poll within a thread (simulate thread ID).
 * 2. As a member, submit a vote on the poll (using a random/valid option).
 * 3. As a moderator, retrieve the details of this poll vote via moderator endpoint.
 *    - Assert all schema fields (id, discussionboard_poll_id, voting_member_id, selected_option, created_at).
 * 4. Negative Test: Attempt to retrieve a poll vote using a random (non-existent) UUID.
 *    - Expect a not found error.
 * 5. Negative Test: Attempt to retrieve using an invalid UUID format.
 *    - Expect validation error or appropriate failure.
 * (Optional, not directly possible with provided SDK) 6. If able, verify access is forbidden when requesting with insufficient permissions (if the endpoint enforces user authentication/roles).
 */
export async function test_api_pollVotes_test_get_poll_vote_detail_as_moderator_with_audit_and_not_found_cases(
  connection: api.IConnection,
) {
  // 1. As member, create a poll
  const threadId: string & tags.Format<"uuid"> = typia.random<string & tags.Format<"uuid">>();
  const poll = await api.functional.prefix.member.polls.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      prompt: "What is your favorite color?",
      allow_multiple_choices: false,
      is_anonymous: false,
      expires_at: undefined,
    } satisfies IPoll.ICreate,
  });
  typia.assert(poll);

  // 2. As member, submit a poll vote
  const selectedOption = "blue";
  const vote = await api.functional.prefix.member.pollVotes.create(connection, {
    body: {
      discussionboard_poll_id: poll.id,
      selected_option: selectedOption,
    } satisfies IPollVote.ICreate,
  });
  typia.assert(vote);

  // 3. As moderator, retrieve poll vote detail
  const auditVote = await api.functional.prefix.moderator.pollVotes.at(connection, {
    id: vote.id,
  });
  typia.assert(auditVote);
  TestValidator.equals("retrieved poll vote matches vote")(auditVote)(vote);

  // 4. Negative Test: Non-existent vote (random UUID)
  await TestValidator.error("poll vote not found")(() =>
    api.functional.prefix.moderator.pollVotes.at(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    }),
  );

  // 5. Negative Test: Invalid UUID format
  await TestValidator.error("invalid UUID format")(() =>
    api.functional.prefix.moderator.pollVotes.at(connection, {
      id: "not-a-uuid" as string & tags.Format<"uuid">,
    }),
  );
}

