    body: {
      incident_code: `INCIDENT-${new Date().toISOString().slice(0,10).replace(/-/g, '')}-001`,
      status: "OPEN",
      description: "Test policy violation report for appeal linkage.",
      reporter_id: null,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    } satisfies IDiscussionboardIncidentReport.ICreate,
  });
