      created_at: nowIso,
      updated_at: nowIso,
    } satisfies IDiscussionboardAppeal.ICreate,
  });
  typia.assert(newAppeal);

  // 3. Retrieve the appeal by id as admin
  const retrieved = await api.functional.prefix.admin.policyAudit.appeals.at(connection, {
    appealId: newAppeal.id,
  });
  typia.assert(retrieved);

  // 4. Validate all schema fields are present and correct
  TestValidator.equals("appeal id matches")(retrieved.id)(newAppeal.id);
  TestValidator.equals("incident id matches")(retrieved.incident_id)(newIncident.id);
  TestValidator.equals("appeal code matches")(retrieved.appeal_code)(newAppeal.appeal_code);
  TestValidator.equals("status matches")(retrieved.status)(newAppeal.status);
  TestValidator.equals("created_at matches")(retrieved.created_at)(newAppeal.created_at);
  TestValidator.equals("updated_at matches")(retrieved.updated_at)(newAppeal.updated_at);
  TestValidator.equals("appellant_id matches")(retrieved.appellant_id)(newAppeal.appellant_id);
  TestValidator.equals("outcome matches")(retrieved.outcome)(newAppeal.outcome);
}

