import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { IModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationAction";
import type { IPageIModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIModerationAction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 다양한 필터로 모더레이션(중재) 액션 목록을 조회하는 기능을 검증합니다.
 *
 * 1. 여러 명의 모더레이터 계정(권한자, actor)을 생성합니다.
 * 2. 여러 종류의 moderation action (report/affected_post/affected_member/action_type/시간
 *    등 조합)을 생성합니다.
 * 3. 아래 조합별로 PATCH /prefix/moderator//moderationActions API로 목록을 조회하고 결과가 입력 조건과
 *    부합하는지 검증합니다.
 *
 *    - ① 모더레이터 id별 필터
 *    - ② action_type별 필터
 *    - ③ affected_post_id/affected_member_id 별 필터
 *    - ④ action_timestamp 범위 필터
 *    - ⑤ 전체 목록 (페이징 포함) 필터 없이 조회 (목록/페이지네이션 구조 및 카운트 검증)
 *
 * - 각 필터 조합 시, 응답 목록(각 moderation action)의 데이터가 조건을 정확히 반영하며, 부정확한 값이 한 건도 혼입되지
 *   않는지, pagination 구조와 전체 카운트, 페이지 크기, 페이지별 분할이 명확히 동작하는지 TestValidator 기반으로
 *   모두 검증합니다.
 */
export async function test_api_moderationActions_test_list_moderation_actions_with_various_filters(
  connection: api.IConnection,
) {
  // 1. 여러 명의 모더레이터 계정(3명) 생성
  const modCount = 3;
  const moderators: IDiscussionboardModerator[] = [];
  for (let i = 0; i < modCount; ++i) {
    const mod: IDiscussionboardModerator =
      await api.functional.prefix.admin.actors.moderators.create(connection, {
        body: {
          id: typia.random<string & tags.Format<"uuid">>(),
          created_at: new Date(
            Date.now() - (modCount - i) * 60 * 60 * 1000,
          ).toISOString() as string & tags.Format<"date-time">,
        } satisfies IDiscussionboardModerator.ICreate,
      });
    typia.assert(mod);
    moderators.push(mod);
  }

  // 2. moderation actions 다양한 조합으로 여러 개(12개) 생성
  // 일부는 report_id, 일부는 affected_post_id, 일부는 affected_member_id를 다르게 설정
  // action_type/anction_description/action_timestamp도 서로 다르게 분산
  const reports = ArrayUtil.repeat(4)(() =>
    typia.random<string & tags.Format<"uuid">>(),
  );
  const posts = ArrayUtil.repeat(4)(() =>
    typia.random<string & tags.Format<"uuid">>(),
  );
  const members = ArrayUtil.repeat(4)(() =>
    typia.random<string & tags.Format<"uuid">>(),
  );
  const types = ["warned", "deleted_post", "suspended_user", "archived_thread"];
  const now = Date.now();
  const moderationActions: IModerationAction[] = [];
  for (let i = 0; i < 12; ++i) {
    const mod = moderators[i % 3];
    const action_type = types[i % types.length];
    const report_id = i % 2 === 0 ? reports[i % reports.length] : null;
    const affected_post_id = i % 3 === 0 ? posts[i % posts.length] : null;
    const affected_member_id = i % 4 === 0 ? members[i % members.length] : null;
    const action_timestamp = new Date(
      now - i * 30 * 60 * 1000,
    ).toISOString() as string & tags.Format<"date-time">;

    const created: IModerationAction =
      await api.functional.prefix.moderator.moderationActions.create(
        connection,
        {
          body: {
            moderator_id: mod.id,
            report_id,
            affected_post_id,
            affected_member_id,
            action_type,
            action_description: `테스트 중재 액션(${i})`,
            action_timestamp,
          } satisfies IModerationAction.ICreate,
        },
      );
    typia.assert(created);
    moderationActions.push(created);
  }

  // 3-1) 모더레이터 id로 필터
  for (const mod of moderators) {
    const resp = await api.functional.prefix.moderator.moderationActions.index(
      connection,
      {
        body: { moderator_id: mod.id },
      },
    );
    typia.assert(resp);
    for (const m of resp.data) {
      TestValidator.equals("moderator_id 필터")(m.moderator_id)(mod.id);
    }
  }

  // 3-2) action_type별 필터
  for (const action_type of types) {
    const resp = await api.functional.prefix.moderator.moderationActions.index(
      connection,
      {
        body: { action_type },
      },
    );
    typia.assert(resp);
    for (const m of resp.data) {
      TestValidator.equals("action_type 필터")(m.action_type)(action_type);
    }
  }

  // 3-3) affected_post_id, affected_member_id 별
  for (const post_id of posts) {
    const resp = await api.functional.prefix.moderator.moderationActions.index(
      connection,
      {
        body: { affected_post_id: post_id },
      },
    );
    typia.assert(resp);
    for (const m of resp.data) {
      TestValidator.equals("affected_post_id 필터")(m.affected_post_id)(
        post_id,
      );
    }
  }
  for (const member_id of members) {
    const resp = await api.functional.prefix.moderator.moderationActions.index(
      connection,
      {
        body: { affected_member_id: member_id },
      },
    );
    typia.assert(resp);
    for (const m of resp.data) {
      TestValidator.equals("affected_member_id 필터")(m.affected_member_id)(
        member_id,
      );
    }
  }

  // 3-4) action_timestamp 범위 (가장 최근 2시간 내 것만)
  const from = new Date(now - 2 * 60 * 60 * 1000).toISOString() as string &
    tags.Format<"date-time">;
  const to = new Date(now + 3 * 60 * 1000).toISOString() as string &
    tags.Format<"date-time">; // 약간 미래 포함
  const respRange =
    await api.functional.prefix.moderator.moderationActions.index(connection, {
      body: {
        action_timestamp_from: from,
        action_timestamp_to: to,
      },
    });
  typia.assert(respRange);
  for (const m of respRange.data) {
    TestValidator.predicate("action_timestamp 범위 필터")(
      m.action_timestamp >= from && m.action_timestamp <= to,
    );
  }

  // 3-5) 전체 목록 필터 없이 (페이지네이션 포함)
  // limit=5, page=1,2로 나누어 조회
  const respAllPage1 =
    await api.functional.prefix.moderator.moderationActions.index(connection, {
      body: {
        limit: 5 as number &
          tags.Type<"int32"> &
          tags.Minimum<1> &
          tags.Maximum<200>,
        page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
      },
    });
  typia.assert(respAllPage1);

  const respAllPage2 =
    await api.functional.prefix.moderator.moderationActions.index(connection, {
      body: {
        limit: 5 as number &
          tags.Type<"int32"> &
          tags.Minimum<1> &
          tags.Maximum<200>,
        page: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
      },
    });
  typia.assert(respAllPage2);

  // 모든 moderationActions 개수와 일치하는지, 페이지 합계 및 분할 구조 검증
  const totalCount = moderationActions.length;
  const page1Count = respAllPage1.data.length;
  const page2Count = respAllPage2.data.length;
  TestValidator.equals("전체 카운트는 전체 moderationActions 수와 일치")(
    respAllPage1.pagination.records + respAllPage2.pagination.records,
  )(2 * totalCount);
  TestValidator.predicate("페이지별 record 분할 합")(
    page1Count + page2Count <= totalCount,
  );
  TestValidator.equals("limit 설정 적용")(respAllPage1.pagination.limit)(5);
  TestValidator.equals("limit 설정 적용")(respAllPage2.pagination.limit)(5);
  TestValidator.equals("페이지네이션 구조")(respAllPage1.pagination.pages >= 2)(
    true,
  );
}

