import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IContentReport";

/**
 * Test moderator's ability to retrieve a content report by ID.
 *
 * Validates that all schema-defined fields are present and match the values to what was originally created with the member endpoint. Ensures the endpoint properly restricts lookup to known reports and enforces strict schema.
 *
 * Steps:
 * 1. As a member, create a content report and capture the returned report object and ID.
 * 2. As a moderator, retrieve that report by ID and verify that all fields (report_reason, status, moderator_note, reporter info, etc.) match exactly what was created.
 * 3. Confirm that extra/non-schema fields are not present in the response.
 * 4. Attempt to retrieve a non-existent report ID as moderator (expect 404 error).
 * 5. Attempt to retrieve a malformed report ID as moderator (expect error, possibly validation or 404).
 */
export async function test_api_prefix_moderator_contentReports_at(
  connection: api.IConnection,
) {
  // 1. Create a content report as a member to obtain a valid report id.
  const now = new Date();
  const reportInput: IContentReport.ICreate = {
    reported_post_id: typia.random<string & tags.Format<"uuid">>(),
    reporter_member_id: typia.random<string & tags.Format<"uuid">>(),
    reporter_guest_id: null,
    report_reason: "Test E2E report reason",
    status: "pending",
    reported_at: now.toISOString(),
    moderator_note: "Initial note from reporter."
  };
  const created: IContentReport = await api.functional.prefix.member.contentReports.create(connection, { body: reportInput });
  typia.assert(created);

  // 2. Retrieve the report via moderator endpoint by id
  const found: IContentReport = await api.functional.prefix.moderator.contentReports.at(connection, { id: created.id });
  typia.assert(found);
  // 3. Field-by-field validation
  TestValidator.equals("id matches")(found.id)(created.id);
  TestValidator.equals("reported_post_id matches")(found.reported_post_id)(created.reported_post_id);
  TestValidator.equals("reporter_member_id matches")(found.reporter_member_id)(created.reporter_member_id);
  TestValidator.equals("reporter_guest_id matches")(found.reporter_guest_id)(created.reporter_guest_id);
  TestValidator.equals("report_reason matches")(found.report_reason)(created.report_reason);
  TestValidator.equals("status matches")(found.status)(created.status);
  TestValidator.equals("reported_at matches")(found.reported_at)(created.reported_at);
  TestValidator.equals("moderator_note matches")(found.moderator_note)(created.moderator_note);

  // 4. Only schema-allowed keys present in response
  const allowedKeys = [
    "id", "reported_post_id", "reporter_member_id", "reporter_guest_id", "report_reason",
    "status", "reported_at", "moderator_note"
  ];
  for (const key of Object.keys(found)) {
    if (!allowedKeys.includes(key))
      throw new Error(`Unexpected property '${key}' present in IContentReport response`);
  }

  // 5. Non-existent ID should return 404
  await TestValidator.error("404 when report ID does not exist")(
    async () => {
      await api.functional.prefix.moderator.contentReports.at(connection, { id: typia.random<string & tags.Format<"uuid">>() });
    }
  );

  // 6. Malformed ID (not a UUID) should return error
  await TestValidator.error("Malformed report id should error")(
    async () => {
      // @ts-expect-error: Forcibly passing a malformed id as string.
      await api.functional.prefix.moderator.contentReports.at(connection, { id: "not-a-uuid" as any });
    }
  );
}

