import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IPostEditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostEditLog";

/**
 * Validate admin retrieval of post edit log details by id, covering normal and
 * error scenarios.
 *
 * Business context:
 *
 * - Ensures audit and compliance: Admins can look up all post edit logs by id
 *   with full detail.
 * - Security: No leakage of detail for nonexistent ids. Non-admin (member) cannot
 *   access sensitive log details.
 *
 * Steps:
 *
 * 1. As MEMBER: create a post.
 * 2. (If edit endpoint not exposed, set is_edited=true on creation to trigger an
 *    edit log if system supports.)
 * 3. (Assume system automatically creates a post edit log upon edit — if not, this
 *    test will skip further validation.)
 * 4. As ADMIN: attempt to retrieve a valid post edit log by id. Validate
 *    fields/types.
 * 5. As ADMIN: attempt to retrieve a nonexistent id. Expect 404 error.
 * 6. As MEMBER: attempt to retrieve the same log id, expect forbidden/error.
 */
export async function test_api_threadsPosts_test_get_post_edit_log_detail_admin_valid_id(
  connection: api.IConnection,
) {
  // 1. As MEMBER: create a post (simulate a thread and post creation for context)
  const threadId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const createPostBody: IDiscussionboardPosts.ICreate = {
    discussionboard_thread_id: threadId,
    body: "Initial post body " + RandomGenerator.content()()(),
    is_edited: true, // Attempt to flag as edited to ensure an edit log is generated (depending on backend logic)
  };
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: createPostBody,
    },
  );
  typia.assert(post);

  // --- At this point, assume the system creates an edit log with the above post ID ---

  // 2. [PREP] Find an associated edit log id for this post. Since the system's log creation is not exposed, we can't fetch log list directly.
  //    As such, we must use a random UUID for non-existent test, and rely on test API to return edit log if any.
  //    Here, we'll test access by using the post ID as the log id (may fail if system doesn't auto-create a log) —
  //    But for purposes of the test, proceed under assumption.
  //    In real testing environments, an edit endpoint should exist to properly create a log, or a log-fetch function should be available.

  // For illustration, we pretend an edit log with id==post.id exists; in real test, use correct linkage!
  const editLogId: string & tags.Format<"uuid"> = post.id as any; // Replace with actual edit log id if linkage available.

  // 3. As ADMIN: retrieve the post edit log detail
  //    (Assume connection context is switched to ADMIN before this call)
  let log: IPostEditLog | undefined = undefined;
  try {
    log = await api.functional.prefix.admin.threadsPosts.postEditLogs.at(
      connection,
      {
        id: editLogId,
      },
    );
    typia.assert(log);
    // Validate fields
    TestValidator.predicate("log id type valid")(
      typeof log.id === "string" && log.id.length > 0,
    );
    TestValidator.predicate("discussionboard_post_id valid")(
      typeof log.discussionboard_post_id === "string",
    );
    TestValidator.predicate("edit_member_id valid")(
      typeof log.edit_member_id === "string",
    );
    TestValidator.predicate("change_summary present")(!!log.change_summary);
    TestValidator.predicate("change_details present")(!!log.change_details);
    TestValidator.predicate("created_at format valid")(
      typeof log.created_at === "string" && log.created_at.includes("T"),
    );
  } catch (err) {
    throw new Error(
      "Failed to retrieve post edit log detail as admin: " +
        (err as Error)?.message,
    );
