        id: memberAId,
        created_at: memberACreatedAt,
      },
    },
  );
  typia.assert(memberA);

  // 2. 회원 B 등록
  const memberBId = typia.random<string & tags.Format<"uuid">>();
  const memberBCreatedAt = new Date().toISOString() as string &
    tags.Format<"date-time">;
  const memberB = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberBId,
        created_at: memberBCreatedAt,
      },
    },
  );
  typia.assert(memberB);

  // 3. (회원 A 컨텍스트) 토론 스레드 생성
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "테스트 스레드 제목",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
        updated_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      },
    },
  );
  typia.assert(thread);

  // 4. (회원 A 컨텍스트) 게시글(Post) 생성
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        body: "테스트 포스트 내용",
        is_edited: false,
      },
    },
  );
  typia.assert(post);

  // 5. (회원 A 컨텍스트) 게시글 수정(→ edit log 생성)
  const updatedPost =
