          body: "수정된 포스트 내용",
          is_edited: true,
          updated_at: new Date().toISOString() as string &
            tags.Format<"date-time">,
        },
      },
    );
  typia.assert(updatedPost);

  // 6. 실제 edit log id 획득 불가(APl 미제공), 임의 UUID 사용하여 삭제 시도
  const fakeEditLogId = typia.random<string & tags.Format<"uuid">>();

  // 7. (회원 B 컨텍스트로 간주) edit log 삭제 시도 - forbidden 에러 검증
  await TestValidator.error("본인 소유가 아닌 edit log 삭제 시 forbidden 발생")(
