 * 5. Confirming endpoint is admin-only (unauthorized access is denied).
 *
 * Steps:
 *
 * - Default listing (no filters)
 * - Filter by action_type (if available)
 * - Filter by actor_id (if any log has an actor_id)
 * - Filter by created_at range (using one log's created_at, if data present)
 * - Pagination test (page and limit)
 * - Access control test (simulate unauthorized/non-admin request)
 */
export async function test_api_prefix_admin_policyAudit_auditLogs_index(
  connection: api.IConnection,
) {
