  typia.assert(createdThread);

  // 2. 정상 루트 게시글(post) 생성
  const post = await api.functional.prefix.member.threadsPosts.posts.create(connection, {
    body: {
      discussionboard_thread_id: createdThread.id,
      body: "게시글 본문",
    },
