  typia.assert(post);
  TestValidator.equals("스레드 참조 FK 일치")(post.discussionboard_thread_id)(createdThread.id);
  TestValidator.equals("parent_post_id 없음")(post.parent_post_id)(null);

  // 3. 필수값 누락 케이스: thread_id 미작성
