  TestValidator.predicate("past from valid")(past.data instanceof Array);

  // 3. created_to 극미래 (2999-12-31)
  const future = await api.functional.prefix.moderator.policyAudit.incidentReports.index(connection, { body: { created_to: "2999-12-31T23:59:59Z" } });
