import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { IModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationAction";
import type { IPageIModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIModerationAction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test the correct implementation of pagination and sorting in moderation actions listing.
 *
 * This test verifies that when there is a bulk set of moderation actions, the API correctly implements pagination using `limit` and `page` parameters, and that results are returned in a reliable, requested order according to the `action_timestamp` field.
 *
 * Steps:
 * 1. Setup: Create a moderator by directly invoking the appropriate admin endpoint, establishing moderator rights.
 * 2. Bulk creation: Use the moderator context to create a series of moderation actions, each with a unique, ordered `action_timestamp` (e.g., timestamps increasing by 1 minute).
 * 3. Paginate Ascending: List moderation actions using `limit` and `page` parameters, verifying that the returned dataset matches the expected actions for each page, in ascending order by timestamp.
 * 4. Paginate Descending: (If API supports sort dir) - If not supported, sort locally for comparison. Otherwise, list moderation actions with the same settings, expecting the results in reverse order, verifying proper descending pagination.
 * 5. Edge cases: Try boundary conditions (e.g., last page, limit greater than available, etc.) to ensure correct handling.
 *
 * Assertions include verifying order, completeness per page, no overlap/duplication, and total record count consistency across requests.
 */
export async function test_api_moderationActions_test_list_moderation_actions_pagination_and_sorting(
  connection: api.IConnection,
) {
  // 1. Setup moderator
  const moderatorId = typia.random<string & tags.Format<"uuid">>();
  const createdAt = new Date().toISOString();
  const moderator = await api.functional.prefix.admin.actors.moderators.create(connection, {
    body: { id: moderatorId, created_at: createdAt } satisfies IDiscussionboardModerator.ICreate,
  });
  typia.assert(moderator);

  // 2. Bulk create moderation actions
  const baseTime = new Date();
  const moderationActions = [];
  for (let i = 0; i < 17; ++i) {
    const time = new Date(baseTime.getTime() + i * 60000).toISOString();
    const action = await api.functional.prefix.moderator.moderationActions.create(connection, {
      body: {
        moderator_id: moderator.id,
        action_type: `type${i}`,
        action_description: `Moderation action ${i}`,
        action_timestamp: time,
      } satisfies Partial<IModerationAction.ICreate> as IModerationAction.ICreate,
    });
    typia.assert(action);
    moderationActions.push(action);
  }

  // 3. Paginate ascending
  const limit = 5;
  const total = moderationActions.length;
  const totalPages = Math.ceil(total / limit);
  const sortedAsc = moderationActions.slice().sort((a, b) => a.action_timestamp.localeCompare(b.action_timestamp));
  for (let page = 1; page <= totalPages; ++page) {
    const output = await api.functional.prefix.moderator.moderationActions.index(connection, {
      body: {
        moderator_id: moderator.id,
        limit,
        page,
      } satisfies IModerationAction.IRequest,
    });
    typia.assert(output);
    const expected = sortedAsc.slice((page - 1) * limit, page * limit);
    TestValidator.equals(`records ascending page ${page}`)(output.data.map(r => r.id))(expected.map(r => r.id));
    TestValidator.equals(`pagination count`)(output.pagination.records)(total);
    TestValidator.equals(`pagination page`)(output.pagination.current)(page);
    TestValidator.equals(`pagination limit`)(output.pagination.limit)(limit);
  }

  // 4. Paginate descending (emulate by local reverse sort, since no sort param)
  const sortedDesc = moderationActions.slice().sort((a, b) => b.action_timestamp.localeCompare(a.action_timestamp));
  for (let page = 1; page <= totalPages; ++page) {
    const output = await api.functional.prefix.moderator.moderationActions.index(connection, {
      body: {
        moderator_id: moderator.id,
        limit,
        page,
      } satisfies IModerationAction.IRequest,
    });
    typia.assert(output);
    const expected = sortedDesc.slice((page - 1) * limit, page * limit);
