import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { IModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationAction";
import type { IPageIModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIModerationAction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test the correct implementation of pagination and sorting in moderation
 * actions listing.
 *
 * This test verifies API paging for moderation actions: with a deterministic
 * moderator and a bulk set of actions with strictly ascending timestamps, it
 * ensures paginated results are correct by `limit` and `page`, and that result
 * lists are in the requested order by `action_timestamp`.
 *
 * Steps:
 *
 * 1. Setup: Create a moderator (admin context) for whom actions will be generated.
 * 2. Bulk create: Create a sequence of moderation actions for this moderator, each
 *    with a unique, ascending timestamp. All required fields are set, and
 *    nullable ones use `null`.
 * 3. Paginate ascending: Query pages in order, checking the IDs and order of each
 *    result page against our local sequence; verify full record count,
 *    completeness, and no duplication across pages.
 * 4. Descending order: (API does not provide sort param) — explain/test design
 *    with local sort for completeness, noting the limitation.
 * 5. Edge: Fetch the last page and verify length is correct (not always full
 *    page).
 */
export async function test_api_moderationActions_test_list_moderation_actions_pagination_and_sorting(
  connection: api.IConnection,
) {
  // 1. Setup moderator via admin API
  const moderatorId: string = typia.random<string & tags.Format<"uuid">>();
  const moderatorCreatedAt: string = new Date().toISOString();
  const moderator = await api.functional.prefix.admin.actors.moderators.create(
    connection,
    {
      body: {
        id: moderatorId,
        created_at: moderatorCreatedAt,
      },
    },
  );
  typia.assert(moderator);

  // 2. Bulk-create moderation actions at unique timestamps
  const baseTime = new Date();
  const moderationActions: IModerationAction[] = [];
  for (let i = 0; i < 17; ++i) {
    // Ensure unique, monotonic timestamps
    const actionTimestamp = new Date(
      baseTime.getTime() + i * 60000,
    ).toISOString();
    const created =
      await api.functional.prefix.moderator.moderationActions.create(
        connection,
        {
          body: {
            moderator_id: moderator.id,
            report_id: null,
            affected_post_id: null,
            affected_member_id: null,
            action_type: `test_type_${i}`,
            action_description: `Bulk moderation action #${i}`,
            action_timestamp: actionTimestamp,
          },
        },
      );
    typia.assert(created);
    moderationActions.push(created);
  }

  // Sort expected actions ascending by timestamp
  const limit = 5;
  const total = moderationActions.length;
  const totalPages = Math.ceil(total / limit);
  const ascSorted = moderationActions
    .slice()
    .sort((a, b) => a.action_timestamp.localeCompare(b.action_timestamp));
  // To track uniqueness across all returned results
  const seenIds = new Set<string>();
  for (let page = 1; page <= totalPages; ++page) {
    const output =
      await api.functional.prefix.moderator.moderationActions.index(
        connection,
        {
          body: {
            moderator_id: moderator.id,
            limit,
            page,
          },
        },
      );
    typia.assert(output);
    // IDs in API result must match expected for this page
    const expected = ascSorted.slice((page - 1) * limit, page * limit);
    TestValidator.equals(`page ${page} moderation action ids`)(
      output.data.map((x) => x.id),
    )(expected.map((x) => x.id));
    // Pagination fields must be correct
    TestValidator.equals(`pagination record count`)(output.pagination.records)(
      total,
    );
    TestValidator.equals(`pagination page num`)(output.pagination.current)(
      page,
    );
    TestValidator.equals(`pagination page size`)(output.pagination.limit)(
      limit,
    );
    // Check global uniqueness: no overlap
    for (const x of output.data) {
      if (seenIds.has(x.id))
        throw new Error(
          `Duplicate moderation action id in paged results: ${x.id}`,
        );
      seenIds.add(x.id);
    }
  }

  // 4. Descending test (no API sort order param). For design completeness only:
  // If API later adds sort order, could test reverse order here.
  // const descSorted = moderationActions.slice().sort((a, b) => b.action_timestamp.localeCompare(a.action_timestamp));
  // ...

  // 5. Edge: Last page may not be full, check item count
  const lastPage = totalPages;
  const finalPage =
    await api.functional.prefix.moderator.moderationActions.index(connection, {
      body: {
        moderator_id: moderator.id,
        limit,
        page: lastPage,
      },
    });
  typia.assert(finalPage);
  const expectedLast = ascSorted.slice((lastPage - 1) * limit);
  TestValidator.equals(`last page length`)(finalPage.data.length)(
    expectedLast.length,
  );
}

