import type { IPageIPostEditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPostEditLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test retrieving a filtered and paginated list of post edit logs as a member.
 *
 * This test will:
 * 1. Create multiple posts.
 * 2. Edit those posts several times to generate post edit logs for each.
 * 3. Find the member's own id (to use as edit_member_id filter).
 * 4. Query the post edit logs list using the following filters:
 *    - edit_member_id (current user)
 *    - created_at_from and created_at_to (time range)
 * 5. Query with various pagination parameters by changing limit and checking pagination.
 * 6. Validate that all returned log entries match the filters used.
 *
 * Edge cases:
 * - No logs match filter (should return empty result page).
 * - Filtering by time range only covers partial log history.
 * - Pagination: total > limit (multiple pages).
 */
export async function test_api_prefix_member_threadsPosts_postEditLogs_test_list_post_edit_logs_with_filters_and_pagination(connection: api.IConnection) {
  // Step 1: Create a thread/post for testing
  const discussionboard_thread_id = typia.random<string & tags.Format<"uuid">>();

  const post1 = await api.functional.prefix.member.threadsPosts.posts.create(connection, {
    body: {
      discussionboard_thread_id,
      body: "Initial post content 1"
    } satisfies IDiscussionboardPosts.ICreate
  });
  typia.assert(post1);

  const post2 = await api.functional.prefix.member.threadsPosts.posts.create(connection, {
    body: {
      discussionboard_thread_id,
      body: "Initial post content 2"
    } satisfies IDiscussionboardPosts.ICreate
  });
  typia.assert(post2);

  // Step 2: Edit both posts multiple times
  const now = new Date();
  const edits = [];
  for (let i = 0; i < 3; ++i) {
    const updated_at1 = new Date(now.getTime() + 1000 * (i + 1)).toISOString();
    const edit1 = await api.functional.prefix.member.my.threadsPosts.posts.update(connection, {
      id: post1.id,
      body: {
        body: `Edited content 1 - ${i}`,
        is_edited: true,
        updated_at: updated_at1
      } satisfies IDiscussionboardPost.IUpdate
    });
    typia.assert(edit1);
    edits.push({post: post1, updated_at: updated_at1, discussionboard_post_id: post1.id});

    const updated_at2 = new Date(now.getTime() + 10000 + 1000 * (i + 1)).toISOString();
    const edit2 = await api.functional.prefix.member.my.threadsPosts.posts.update(connection, {
      id: post2.id,
      body: {
        body: `Edited content 2 - ${i}`,
        is_edited: true,
        updated_at: updated_at2
      } satisfies IDiscussionboardPost.IUpdate
    });
    typia.assert(edit2);
    edits.push({post: post2, updated_at: updated_at2, discussionboard_post_id: post2.id});
  }

  // Get own member id (from one of the created posts)
  const edit_member_id = post1.discussionboard_member_id;

  // Step 3: Query with no filter (all logs)
  let logs = await api.functional.prefix.member.threadsPosts.postEditLogs.index(connection, {body: {}});
  typia.assert(logs);
  TestValidator.predicate("should return at least as many as we edited")(logs.data.length >= edits.length);

  // Step 4: Query by edit_member_id
  logs = await api.functional.prefix.member.threadsPosts.postEditLogs.index(connection, {body: {edit_member_id}});
  typia.assert(logs);
  for (const log of logs.data) {
    TestValidator.equals("edit_member_id matches")(log.edit_member_id)(edit_member_id);
  }

  // Step 5: Query by created_at time range for first post's edits
  const firstEditTime = edits[0].updated_at;
  const lastEditTime = edits[edits.length-1].updated_at;
  logs = await api.functional.prefix.member.threadsPosts.postEditLogs.index(connection, {body: {
    created_at_from: firstEditTime,
    created_at_to: lastEditTime,
    edit_member_id
  }});
