import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test list and filter of suspensions including pagination for moderator access.
 *
 * This test ensures the following:
 * 1. Multiple suspension records exist, created via dependency.
 * 2. Suspensions can be retrieved using combinations of filters (moderator_id, suspended_member_id, suspension reason, and suspension date window).
 * 3. Pagination parameters are handled correctly.
 * 4. Results reflect accurate filtering, not just all suspensions.
 * 5. Only authorized users (e.g., moderators) can access these endpoints.
 *
 * Steps:
 * 1. Create 4+ suspension records with varying moderator_id, suspended_member_id, and time ranges.
 * 2. Retrieve all suspensions with no filters and capture total count.
 * 3. Filter by 1 moderator_id: result should only include suspensions by that moderator.
 * 4. Filter by suspended_member_id: result should only include suspensions for that member.
 * 5. Use both filters together—AND logic should hold in result.
 * 6. Use suspension window filters to capture partial subsets.
 * 7. Use pagination (limit=2) and check pagination fields and results for page 1 and page 2.
 * 8. Attempt to call as a non-moderator (simulate with a connection having no moderator role), assert access is denied (if RBAC enforced).
 */
export async function test_api_prefix_moderator_suspensions_test_list_suspensions_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // (1) Create multiple diverse suspension records for robust testing
  const suspensionInputs = ArrayUtil.repeat(4)(() => {
    return {
      moderator_id: typia.random<string & tags.Format<"uuid">>(),
      suspended_member_id: typia.random<string & tags.Format<"uuid">>(),
      suspension_reason: RandomGenerator.paragraph()(),
      suspension_started_at: RandomGenerator.pick([
        new Date(Date.now() - 86400000 * 5).toISOString(), // 5 days ago
        new Date(Date.now() - 86400000 * 2).toISOString(), // 2 days ago
        new Date(Date.now()).toISOString(),                // now
      ]),
      suspension_ends_at: RandomGenerator.pick([
        null,
        new Date(Date.now() + 86400000 * 5).toISOString(), // 5 days later
      ]),
    } satisfies ISuspension.ICreate;
  });
  const suspensions: ISuspension[] = [];
  for (const input of suspensionInputs) {
    const suspension = await api.functional.prefix.moderator.suspensions.create(connection, { body: input });
    typia.assert(suspension);
    suspensions.push(suspension);
  }
  // (2) Get all suspensions (no filters)
  const allPage = await api.functional.prefix.moderator.suspensions.index(connection, { body: {} });
  typia.assert(allPage);
  TestValidator.predicate("should return at least all created suspensions")(allPage.data.length >= suspensions.length);

  // (3) Filter by moderator_id
  const byModerator = await api.functional.prefix.moderator.suspensions.index(connection, { body: { moderator_id: suspensions[0].moderator_id } });
  typia.assert(byModerator);
  TestValidator.predicate("all results have moderator_id")(
    byModerator.data.every(r => r.moderator_id === suspensions[0].moderator_id)
  );

  // (4) Filter by suspended_member_id
  const byMember = await api.functional.prefix.moderator.suspensions.index(connection, { body: { suspended_member_id: suspensions[1].suspended_member_id } });
  typia.assert(byMember);
  TestValidator.predicate("all results have suspended_member_id")(
    byMember.data.every(r => r.suspended_member_id === suspensions[1].suspended_member_id)
  );

  // (5) Filter by both moderator_id and suspended_member_id
  const byBoth = await api.functional.prefix.moderator.suspensions.index(connection, { body: { moderator_id: suspensions[2].moderator_id, suspended_member_id: suspensions[2].suspended_member_id } });
  typia.assert(byBoth);
  TestValidator.predicate("all results match both moderator_id and suspended_member_id")(
    byBoth.data.every(r => r.moderator_id === suspensions[2].moderator_id && r.suspended_member_id === suspensions[2].suspended_member_id)
  );

  // (6) Filter by suspension_started_at_from and suspension_started_at_to
  const fromDate = suspensions[0].suspension_started_at;
  const toDate = suspensions[suspensions.length - 1].suspension_started_at;
  const byWindow = await api.functional.prefix.moderator.suspensions.index(connection, { body: { suspension_started_at_from: fromDate, suspension_started_at_to: toDate } });
  typia.assert(byWindow);
  TestValidator.predicate("all within date window")(
    byWindow.data.every(r => r.suspension_started_at >= fromDate && r.suspension_started_at <= toDate)
  );

  // (7) Pagination check: limit=2
  const paged1 = await api.functional.prefix.moderator.suspensions.index(connection, { body: { limit: 2, page: 1 } });
  typia.assert(paged1);
  TestValidator.equals("page 1 limit") (paged1.data.length) (2);
  TestValidator.equals("pagination current page")(paged1.pagination.current)(1);

  const paged2 = await api.functional.prefix.moderator.suspensions.index(connection, { body: { limit: 2, page: 2 } });
  typia.assert(paged2);
  TestValidator.equals("page 2 limit") (paged2.data.length) (2);
  TestValidator.equals("pagination current page")(paged2.pagination.current)(2);

  // (8) RBAC: Try with non-moderator/no auth context
  // This depends on actual implementation: here we simulate by deleting token
  // (connection.headers.Authorization removal). If producing HttpError, assert error is thrown
  const clonedConn: api.IConnection = {
    ...connection,
    headers: { ...connection.headers },
  };
  delete clonedConn.headers.Authorization;
  await TestValidator.error("Should fail for non-moderator")(
    async () => {
      await api.functional.prefix.moderator.suspensions.index(clonedConn, { body: {} });
    }
  );
}

