import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IContentReport";

/**
 * Validates that a member cannot update another user's content report (forbidden operation)
 *
 * This function tests the security mechanism that ensures only the owner of a content report (i.e., the member who filed it) may update it. It covers the business rule that report modification is strictly restricted to the report creator.
 *
 * Steps:
 * 1. Register two separate members (Member A and Member B).
 * 2. Member A creates a discussion thread post.
 * 3. Member A files a content report on the post they created (to own the report as Member A).
 * 4. Member B attempts to update Member A's content report using the /my/contentReports/{id} endpoint.
 * 5. Assert that the operation is forbidden and the API responds with a suitable authorization error (e.g., forbidden/unauthorized).
 */
export async function test_api_prefix_test_update_other_users_content_report_forbidden(
  connection: api.IConnection,
) {
  // Step 1: Register Member A
  const memberAId: string = typia.random<string & tags.Format<"uuid">>();
  const memberA_created_at: string = new Date().toISOString();
  const memberA = await api.functional.prefix.member.actors.members.create(connection, { body: { id: memberAId, created_at: memberA_created_at } });
  typia.assert(memberA);

  // Step 2: Register Member B
  const memberBId: string = typia.random<string & tags.Format<"uuid">>();
  const memberB_created_at: string = new Date().toISOString();
  const memberB = await api.functional.prefix.member.actors.members.create(connection, { body: { id: memberBId, created_at: memberB_created_at } });
  typia.assert(memberB);

  // Step 3: Member A creates a thread post
  // We'll simulate a thread ID for post association
  const threadId: string = typia.random<string & tags.Format<"uuid">>();
  // Switch to Member A context (simulate user switch via headers)
  connection.headers = { ...(connection.headers ?? {}), "x-discussionboard-member-id": memberAId };
  const post = await api.functional.prefix.member.threadsPosts.posts.create(connection, { body: { discussionboard_thread_id: threadId, body: "Reportable test post" } });
  typia.assert(post);

  // Step 4: Member A files a content report
  const now = new Date().toISOString();
  const report = await api.functional.prefix.member.contentReports.create(connection, { body: { reported_post_id: post.id, reporter_member_id: memberAId, report_reason: "Violation", status: "pending", reported_at: now } });
  typia.assert(report);

  // Step 5: Member B attempts to update Member A's report
  // Switch to Member B context
  connection.headers = { ...(connection.headers ?? {}), "x-discussionboard-member-id": memberBId };
  await TestValidator.error("forbidden update by non-owner")(
    async () => {
      await api.functional.prefix.member.my.contentReports.update(connection, { id: report.id, body: { status: "in_review", report_reason: "Trying to update someone else's report" } });
    },
  );
}

