 *
 * This test verifies the successful, end-to-end business flow for fetching an association between a discussion thread and a tag by its unique ID. It ensures that associations, once created, can be retrieved and accurately reflect the details used during association creation, guaranteeing data integrity from creation to retrieval.
 *
 * Workflow:
 * 1. Create a thread to serve as association target.
 * 2. Create a thread tag for assignment.
 * 3. Associate the thread and tag via taggedThreads.
 * 4. Retrieve the taggedThreads record by its ID using GET.
 * 5. Assert all returned fields match the ones from creation.
 */
export async function test_api_prefix_test_get_thread_tag_association_by_id_success(
  connection: api.IConnection,
) {
  // 1. Create a minimal thread
  const threadInput: IDiscussionboardThreads.ICreate = {
    discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(),
    title: RandomGenerator.paragraph()(),
    status: "active",
    is_pinned: false,
    is_locked: false,
    archived: false,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(connection, { body: threadInput });
  typia.assert(thread);

  // 2. Create a thread tag
  const tagInput: IThreadTag.ICreate = {
    code: RandomGenerator.alphaNumeric(8),
    display_name: RandomGenerator.paragraph()(1),
    description: null,
    is_restricted: false,
    is_hidden: false,
    created_at: new Date().toISOString(),
  };
  const tag = await api.functional.prefix.member.threadTags.create(connection, { body: tagInput });
  typia.assert(tag);

  // 3. Create the association (tagged thread)
  const assocInput: IDiscussionboardTaggedThread.ICreate = {
    discussionboard_thread_id: thread.id,
    discussionboard_thread_tag_id: tag.id,
    created_at: new Date().toISOString(),
  };
  const assoc = await api.functional.prefix.member.taggedThreads.create(connection, { body: assocInput });
  typia.assert(assoc);

  // 4. Retrieve the association by ID
  const output = await api.functional.prefix.member.taggedThreads.at(connection, { taggedThreadId: assoc.id });
  typia.assert(output);

  // 5. Assert retrieved data matches what was created
  TestValidator.equals("association id")(output.id)(assoc.id);
  TestValidator.equals("thread id")(output.discussionboard_thread_id)(thread.id);
  TestValidator.equals("tag id")(output.discussionboard_thread_tag_id)(tag.id);
  TestValidator.equals("created_at")(output.created_at)(assoc.created_at);
}

