import type { IContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IContentReport";

/**
 * Validate that a guest user can update their own content report before moderation takes action.
 *
 * This test ensures that a guest, after creating a report, can still amend attributes such as the report reason or status prior to any moderation review. 
 * The flow mimics a realistic scenario where a non-member files a report on a member's post, and then wishes to revise the submission before it enters the moderation process.
 *
 * 1. Create or register a guest user context to represent the reporting guest.
 * 2. As a member, create a new post in the discussion board, providing a target for the content report.
 * 3. As the guest, file a new content report regarding the just-created post. Ensure the created report is linked to the post and the guest.
 * 4. Before moderation occurs, update the filed content report (for example, change the report_reason and status between valid values, e.g. 'pending' to 'in_review').
 * 5. Check that the updated fields are correctly reflected in the content report response and that no error occurs because the report has not yet been processed by a moderator.
 * 6. Optional: attempt an update of a field the guest should not own, expecting an error if the API enforces this (if such ownership logic applies).
 */
export async function test_api_guest_test_update_guest_content_report_before_moderation(
  connection: api.IConnection,
) {
  // 1. Register/obtain guest context
  const guestInput: IDiscussionboardGuests.ICreate = {
    id: typia.random<string & tags.Format<"uuid">>(),
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const guest = await api.functional.prefix.member.actors.guests.create(connection, { body: guestInput });
  typia.assert(guest);

  // 2. Create a reportable post as a member
  const postInput: IDiscussionboardPosts.ICreate = {
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    body: "Content to be reported.",
    is_edited: false,
  };
  const post = await api.functional.prefix.member.threadsPosts.posts.create(connection, { body: postInput });
  typia.assert(post);

  // 3. File a content report as guest
  const contentReportInput: IContentReport.ICreate = {
    reported_post_id: post.id,
    reporter_member_id: null,
    reporter_guest_id: guest.id,
    report_reason: "Initial report reason.",
    status: "pending",
    reported_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const originalReport = await api.functional.prefix.guest.contentReports.create(connection, { body: contentReportInput });
  typia.assert(originalReport);

  // 4. Update the content report (change reason and status before moderation)
  const updatedReason = "Clarified reason after initial submission.";
  const updatedStatus: "pending" | "in_review" = originalReport.status === "pending" ? "in_review" : "pending";
  const updateInput: IContentReport.IUpdate = {
    report_reason: updatedReason,
    status: updatedStatus,
  };
  const updatedReport = await api.functional.prefix.guest.my.contentReports.update(connection, {
    id: originalReport.id,
    body: updateInput,
  });
  typia.assert(updatedReport);
  // 5. Validate that update is applied as expected
  TestValidator.equals("updated report_reason")(updatedReport.report_reason)(updatedReason);
  TestValidator.equals("updated status")(updatedReport.status)(updatedStatus);
  TestValidator.equals("identity unchanged")(updatedReport.id)(originalReport.id);
  TestValidator.equals("report ownership remains")(updatedReport.reporter_guest_id)(guest.id);
}

