  // 실제론 세션/토큰 switching 필요, 여기선 연결 그대로 사용한다고 가정
  const moderationAction = await api.functional.prefix.moderator.moderationActions.create(connection, {
    body: {
      moderator_id: moderatorAId,
      report_id: null,
      affected_post_id: null,
      affected_member_id: null,
      action_type: "warned",
      action_description: "Test moderation by A",
      action_timestamp: new Date().toISOString(),
    } satisfies IModerationAction.ICreate,
  });
  typia.assert(moderationAction);

