import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IWarningLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IWarningLog";

/**
 * Validate that moderators cannot update warning logs created by other moderators (ownership enforcement).
 *
 * This test verifies that the system prohibits a moderator from modifying a warning log they do not own. Specifically, it:
 * 1. Simulates the creation of a warning log using one moderator identity.
 * 2. Attempts to update that warning log using a different moderator account/session.
 * 3. Expects the system to return an authorization error (e.g., forbidden or unauthorized), ensuring no update is performed and ownership is enforced.
 *
 * Rationale: Proper ownership checks are critical for audit integrity, accountability, and to prevent privilege escalation or unauthorized data tampering by other moderators.
 *
 * Steps:
 * 1. Create a warning log as Moderator A via the `warningLogs.create` endpoint.
 * 2. Switch to Moderator B (current session).
 * 3. Attempt to update Moderator A's warning log using the `my.warningLogs.update` endpoint.
 * 4. Validate that an authorization error is thrown and no changes are made.
 */
export async function test_api_prefix_moderator_my_warningLogs_test_update_other_moderators_warning_log_fails(
  connection: api.IConnection,
) {
  // 1. Create a warning log as Moderator A (simulate another moderator)
  const moderatorAId = typia.random<string & tags.Format<"uuid">>();
  const warningLog = await api.functional.prefix.moderator.warningLogs.create(connection, {
    body: {
      moderator_id: moderatorAId,
      warned_member_id: typia.random<string & tags.Format<"uuid">>(),
      warning_reason: "Test reason for ownership enforcement.",
      issued_at: new Date().toISOString(),
    } satisfies IWarningLog.ICreate,
  });
  typia.assert(warningLog);

  // 2. Attempt to update the warning log as a different moderator (current connection is assumed to be Moderator B)
  const updateBody: IWarningLog.IUpdate = {
    warning_reason: "Illegitimate update attempt",
    issued_at: new Date().toISOString(),
  };
  // 3. Expect an authorization error to be thrown (e.g., forbidden)
  await TestValidator.error("forbidden: cannot update another moderator's warning log")(
    async () => {
      await api.functional.prefix.moderator.my.warningLogs.update(connection, {
        id: warningLog.id,
        body: updateBody,
      });
    }
  );
}

