  // Step 1: Moderator A identity/context creation (simulate unique moderator_id)
  const moderatorAId = typia.random<string & tags.Format<"uuid">>();
  const targetMemberId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();

  // Step 2: Moderator A creates a warning log
  const warningLog = await api.functional.prefix.moderator.warningLogs.create(connection, {
