  // Step 4: Moderator B attempts unauthorized deletion
  await TestValidator.error("delete should fail for non-owner moderator")(
    async () => {
      await api.functional.prefix.moderator.my.warningLogs.erase(connection, { id: warningLog.id });
    },
  );
}

