    }
  });
  typia.assert(moderatorB);

  // 2. Create warning logs with variety (issued by A/B, different members, reasons, and timestamps)
  const warnedMembers = ArrayUtil.repeat(3)(() => typia.random<string & tags.Format<"uuid">>());
  const reasons = ["Off-topic", "Spamwords", "Abuse report", "Test search", "Other reason"];
  const logMatrix: Array<{
    log: IWarningLog;
