  const maxTime = now.toISOString();
  const timeResult = await api.functional.prefix.moderator.warningLogs.index(connection, {
    body: { issued_at_from: minTime, issued_at_to: maxTime }
  });
  typia.assert(timeResult);
  TestValidator.predicate("logs issued_at within specified range")(
