 * 1. Create several distinct ban records, some with banned_member_id, some with banned_guest_id, using at least two different admin_id values.
 * 2. Retrieve ban list filtering by banned_member_id and verify only the correct records are returned.
 * 3. Retrieve ban list filtering by banned_guest_id and verify.
 * 4. Retrieve ban list with no filter and verify all created bans are listed.
 * 5. Retrieve ban list with pagination (e.g., limit=2) and verify correct slicing of the records.
 * 6. (Optional edge) Try applying a filter for a member/guest ID not present and expect an empty result.
 * 
 * Each retrieval should assert that results are accurate and all fields in the schema are preserved.
 */
export async function test_api_prefix_admin_bans_test_list_bans_with_filters_and_pagination(connection: api.IConnection) {
