/**
 * Validate that once a member's content report has been reviewed or acted upon by a moderator,
 * the reporting member is forbidden from deleting the report.
 *
 * Scenario process:
 * 1. Register a new member (simulate authenticated context)
 * 2. Create a new discussion post (target for the content report)
 * 3. File a content report as the member on the created post (status: 'pending')
 * 4. Simulate a moderator 'action' (e.g., set status/action via an update using a moderation action record)
 * 5. Have the original member attempt to delete their own content report (should be forbidden)
 * 6. Assert that deletion is rejected with error (runtime error thrown)
 *
 * Rationale:
 * Compliance/audit policy demands that reports with moderator actions are preserved.
 */
export async function test_api_contentReports_test_delete_content_report_after_moderator_action_forbidden(
  connection: api.IConnection,
) {
