  const memberId = typia.random<string & tags.Format<"uuid">>();
  const memberCreatedAt = new Date().toISOString();
  const member = await api.functional.prefix.member.actors.members.create(connection, {
    body: {
      id: memberId,
      created_at: memberCreatedAt,
    } satisfies IDiscussionboardMembers.ICreate,
  });
  typia.assert(member);

  // 2. Create a post (the content that will be reported)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.prefix.member.threadsPosts.posts.create(connection, {
    body: {
      discussionboard_thread_id: threadId,
      parent_post_id: null,
      body: "Reported post body " + RandomGenerator.content()()(),
      is_edited: false,
    } satisfies IDiscussionboardPosts.ICreate,
  });
  typia.assert(post);

  // 3. Member files a content report (status: 'pending')
  const contentReport = await api.functional.prefix.member.contentReports.create(connection, {
    body: {
      reported_post_id: post.id,
      reporter_member_id: memberId,
      reporter_guest_id: null,
      report_reason: "Spam or inappropriate content",
      status: "pending",
      reported_at: new Date().toISOString(),
      moderator_note: null,
    } satisfies IContentReport.ICreate,
  });
  typia.assert(contentReport);

  // 4. Simulate moderator updates (create a moderation action record to lock report)
  //   - For this test, we just need an IModerationAction.IUpdate and a dummy moderationActionId.
  //   - The link is report_id === contentReport.id
  const moderationActionId = typia.random<string & tags.Format<"uuid">>();
  const actionTimestamp = new Date().toISOString();
  const moderationAction = await api.functional.prefix.moderator.my.moderationActions.update(connection, {
    id: moderationActionId,
    body: {
      report_id: contentReport.id,
      affected_post_id: post.id,
      affected_member_id: memberId,
      action_type: "action_taken",
      action_description: "Moderator acted upon report (locking it)",
      action_timestamp: actionTimestamp,
    } satisfies IModerationAction.IUpdate,
  });
  typia.assert(moderationAction);

  // 5. Member attempts to delete the now-locked report (must fail)
  await TestValidator.error("delete forbidden after moderator action")(
    async () => {
      await api.functional.prefix.member.my.contentReports.erase(
        connection,
        {
          id: contentReport.id,
        },
      );
    },
  );
}

