import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardFilter } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFilter";

/**
 * 테스트: 인증된 회원이 새로운 필터를 생성하는 기능을 검증한다.
 *
 * 1. 최소 필수 필드(name, definition, is_public)만 제공하여 필터 생성이 성공하는지 확인한다.
 *    - 반환되는 필터 객체에서 본인 계정이 소유자인지(discussionboard_member_id) 및 각 필드 값이 일치하는지 조회하여 검증한다.
 * 2. 오류 케이스
 *    a) 필수 필드 중 하나라도 누락한 body로 요청하면 생성이 거부되어야 한다.
 *    b) schema에 존재하지 않는, 즉 API가 허용하지 않는 필드를 body에 포함할 경우 에러가 발생해야 한다.
 *    c) discussionboard_member_id를 임의의 다른 유저(난수 uuid)로 지정하여 생성 요청 시, 무시되거나 본인 소유로만 지정되어야 하며, 타인 소유로는 성공할 수 없어야 한다.
 *
 * [절차]
 * 1. 올바른 데이터로 필터 생성 후 반환값(소유자, 입력 필드 일치) 검증
 * 2. name 누락하여 생성 시도 → 실패 검증
 * 3. definition 누락하여 생성 시도 → 실패 검증
 * 4. is_public 누락하여 생성 시도 → 실패 검증
 * 5. schema에 정의되지 않은 인위적인 필드(ex. not_exist: "test") 포함하여 생성 시도 → 실패 검증
 * 6. discussionboard_member_id에 임의의 다른 회원 uuid를 넣어 생성 시도 → 반환값의 discussionboard_member_id가 본인만 허용되고, 타인 id가 입력되어도 무시됨 또는 에러 발생 확인
 */
export async function test_api_prefix_member_my_filters_create(
  connection: api.IConnection,
) {
  // 1. 정상 시나리오: 필수 필드만으로 성공 생성 & 검증
  const reqBody = {
    name: RandomGenerator.alphabets(10),
    definition: JSON.stringify({ tags: ["api", "e2e"], time: Date.now() }),
    is_public: true,
  } satisfies IDiscussionboardFilter.ICreate;
  const created = await api.functional.prefix.member.my.filters.create(connection, { body: reqBody });
  typia.assert(created);
  TestValidator.equals("name")(created.name)(reqBody.name);
  TestValidator.equals("definition")(created.definition)(reqBody.definition);
  TestValidator.equals("is_public")(created.is_public)(reqBody.is_public);
  TestValidator.predicate("filter는 소유자 ID가 있어야 함")(!!created.discussionboard_member_id);

  // 2.a. 필수 필드 누락 케이스 (name 누락)
  await TestValidator.error("name 누락시 생성 거부")(
    async () => {
      const body = {
        definition: reqBody.definition,
        is_public: reqBody.is_public,
      } as any as IDiscussionboardFilter.ICreate;
      await api.functional.prefix.member.my.filters.create(connection, { body });
    },
  );
  // 2.b. 필수 필드 누락 케이스 (definition 누락)
  await TestValidator.error("definition 누락시 생성 거부")(
    async () => {
      const body = {
        name: reqBody.name,
        is_public: reqBody.is_public,
      } as any as IDiscussionboardFilter.ICreate;
      await api.functional.prefix.member.my.filters.create(connection, { body });
    },
  );
  // 2.c. 필수 필드 누락 케이스 (is_public 누락)
  await TestValidator.error("is_public 누락시 생성 거부")(
    async () => {
      const body = {
        name: reqBody.name,
        definition: reqBody.definition,
      } as any as IDiscussionboardFilter.ICreate;
      await api.functional.prefix.member.my.filters.create(connection, { body });
    },
  );
  // 2.d. schema에 없는 인위적 필드 포함(should fail)
  await TestValidator.error("비정상 필드 포함시 생성 거부")(
    async () => {
      const body = {
        ...reqBody,
        not_exist: "test",
      } as any as IDiscussionboardFilter.ICreate;
      await api.functional.prefix.member.my.filters.create(connection, { body });
    },
  );
  // 2.e. discussionboard_member_id에 임의의 다른 회원 uuid를 넣어 생성 시도 → 본인 소유로만 등록되는지
  const fakeMemberId = typia.random<string & tags.Format<"uuid">>();
  const inputWithId = { ...reqBody, discussionboard_member_id: fakeMemberId } satisfies IDiscussionboardFilter.ICreate;
  const createdWithFakeId = await api.functional.prefix.member.my.filters.create(connection, { body: inputWithId });
  typia.assert(createdWithFakeId);
  // discussionboard_member_id가 본인(세션/토큰상 auth된 유저)로만 할당되고, 주입값은 무시되거나 에러 발생
  TestValidator.predicate("다른 회원 id로 생성시 실제 소유자는 본인이어야 함")(
    !!createdWithFakeId.discussionboard_member_id &&
    createdWithFakeId.discussionboard_member_id !== fakeMemberId,
  );
}

