import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardFilter } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFilter";

/**
 * Test updating fields of a saved discussion board filter configuration a
 * member owns, and handling soft-deleted/forbidden/nonexistent cases.
 *
 * This test validates both positive and negative behaviors for updating
 * IDiscussionboardFilter via the update endpoint:
 *
 * 1. Create a filter as the current member (obtain filterId).
 * 2. Update individual fields (name, definition, is_public, updated_at).
 * 3. Update multiple fields in combination.
 * 4. Ensure changes persist and ownership (discussionboard_member_id) cannot be
 *    changed by update.
 * 5. Soft-delete the filter, then verify that subsequent update fails.
 * 6. Attempt update with random (nonexistent) filterId (expect error).
 * 7. (If possible) Attempt to update a filter owned by another member (expect
 *    error).
 * 8. Attempt to update using extraneous/invalid fields (ensure type error is
 *    present at compile time and update cannot proceed; in runtime only valid
 *    props can be tested).
 *
 * Negative test cases only check that an error occurs, not specific error text.
 */
export async function test_api_prefix_member_filters_test_update_saved_filter_fields_and_handle_soft_deleted_filter(
  connection: api.IConnection,
) {
  // 1. Create filter as current member
  const baseFilterInput = {
    name: `BaseFilter_${RandomGenerator.alphaNumeric(6)}`,
    definition: JSON.stringify({ q: RandomGenerator.alphaNumeric(4) }),
    is_public: false,
  } satisfies IDiscussionboardFilter.ICreate;
  const created = await api.functional.prefix.member.filters.create(
    connection,
    { body: baseFilterInput },
  );
  typia.assert(created);

  // 2. Update each field individually and check changed values & owner
  // (a) name
  const newName = `UpdatedName_${RandomGenerator.alphaNumeric(6)}`;
  let updated = await api.functional.prefix.member.filters.update(connection, {
    filterId: created.id,
    body: { name: newName },
  });
  typia.assert(updated);
  TestValidator.equals("name updated")(updated.name)(newName);
  TestValidator.equals("ownership unchanged")(
    updated.discussionboard_member_id,
  )(created.discussionboard_member_id ?? null);

  // (b) definition
  const newDefinition = JSON.stringify({
    keyword: RandomGenerator.alphaNumeric(8),
  });
  updated = await api.functional.prefix.member.filters.update(connection, {
    filterId: created.id,
    body: { definition: newDefinition },
  });
  typia.assert(updated);
  TestValidator.equals("definition updated")(updated.definition)(newDefinition);

  // (c) is_public
  updated = await api.functional.prefix.member.filters.update(connection, {
    filterId: created.id,
    body: { is_public: true },
  });
  typia.assert(updated);
  TestValidator.equals("is_public updated")(updated.is_public)(true);

  // (d) updated_at
  const newUpdateTime = new Date().toISOString();
  updated = await api.functional.prefix.member.filters.update(connection, {
    filterId: created.id,
