 * data always reflect the query. Also ensures empty result handling works (no
 * matching records).
 *
 * Steps:
 *
 * 1. Create several business rules with distinct rule_code, title and is_active
 *    values
 * 2. List all business rules (no filter), expecting all created to be present
 * 3. Filter by rule_code: Only correct record(s) return
 * 4. Partial title match: Search with a substring and expect matching subset
 * 5. Filter by is_active: Test both true/false status for correct subsets
 * 6. Pagination: Supply limit/offset and verify correct slicing and meta
 * 7. Filter with no matches: Expect empty data array and correct pagination meta
 */
export async function test_api_prefix_admin_policyAudit_businessRules_test_list_policy_audit_business_rules_with_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create business rules with varied values for coverage
  const rules = [
    await api.functional.prefix.admin.policyAudit.businessRules.create(
      connection,
      {
        body: {
          rule_code: "RULE_ALPHA",
          title: "Alpha Policy",
          description: "Description for Alpha Policy.",
          is_active: true,
        },
      },
    ),
    await api.functional.prefix.admin.policyAudit.businessRules.create(
      connection,
      {
        body: {
          rule_code: "RULE_BETA",
          title: "Beta Policy",
          description: "Description for Beta Policy.",
          is_active: false,
        },
      },
    ),
    await api.functional.prefix.admin.policyAudit.businessRules.create(
      connection,
      {
        body: {
          rule_code: "RULE_GAMMA",
          title: "Gamma Process",
          description: "Gamma process compliance details.",
          is_active: true,
        },
      },
    ),
    await api.functional.prefix.admin.policyAudit.businessRules.create(
      connection,
      {
        body: {
          rule_code: "RULE_DELTA",
          title: "Delta Security",
          description: "Policy for Delta security flows.",
          is_active: false,
        },
      },
    ),
  ];
  rules.forEach(typia.assert);

  // 2. List all rules (no filter)
  const allList =
    await api.functional.prefix.admin.policyAudit.businessRules.index(
      connection,
      { body: {} },
    );
  typia.assert(allList);
  TestValidator.predicate("all rules present")(
    rules.every((rule) => allList.data.find((r) => r.id === rule.id)),
  );

  // 3. Filter by rule_code (should return exactly one)
  const codeList =
    await api.functional.prefix.admin.policyAudit.businessRules.index(
      connection,
      { body: { rule_code: "RULE_BETA" } },
    );
  typia.assert(codeList);
  TestValidator.equals("one matching code")(codeList.data.length)(1);
  TestValidator.equals("correct id for code")(codeList.data[0].id)(rules[1].id);

  // 4. Partial title match (substring 'Policy' yields Alpha/Beta)
  const partialTitleList =
    await api.functional.prefix.admin.policyAudit.businessRules.index(
      connection,
      { body: { title: "Policy" } },
    );
  typia.assert(partialTitleList);
  TestValidator.equals("subset with partial title match")(
    partialTitleList.data.length,
  )(2);
  const policyTitles = rules
    .filter((r) => r.title.includes("Policy"))
    .map((r) => r.id)
    .sort();
  const resultTitles = partialTitleList.data.map((r) => r.id).sort();
  TestValidator.equals("IDs for partial title match")(resultTitles)(
    policyTitles,
  );

  // 5. Filter by is_active (true)
  const activeList =
    await api.functional.prefix.admin.policyAudit.businessRules.index(
      connection,
      { body: { is_active: true } },
    );
  typia.assert(activeList);
  const activeIds = rules
    .filter((r) => r.is_active)
    .map((r) => r.id)
    .sort();
  const resultActiveIds = activeList.data.map((r) => r.id).sort();
  TestValidator.equals("IDs for is_active=true")(resultActiveIds)(activeIds);

  // 5b. Filter by is_active (false)
  const inactiveList =
    await api.functional.prefix.admin.policyAudit.businessRules.index(
      connection,
      { body: { is_active: false } },
    );
