/**
 * 테스트 목적: 멤버가 자신이 멘션된 내역을 게시글(post) 기준, 멤버 기준으로 필터링하여 조회할 수 있음을 검증한다.
 *
 * 시나리오:
 * 1. 두 명의 멤버를 생성한다 (언급하는 멤버, 언급당하는 멤버)
 * 2. 임의의 카테고리 id를 사용해 스레드를 하나 생성한다
 * 3. 생성된 스레드에 언급하는 멤버가 게시글(post)을 작성한다
 * 4. 그 게시글에서 언급당하는 멤버를 멘션으로 추가한다 (mentions 생성)
 * 5. mentions 조회 API (PATCH /prefix/member//mentions)에서 해당 post id로 필터하여 생성한 mention이 포함되어 있는지 확인한다
 * 6. mentions 조회 API에서 mentioned_member_id로 필터하여 생성한 mention이 포함되어 있는지 확인한다
 */
export async function test_api_prefix_member_mentions_test_list_mentions_with_post_and_member_filters(connection: api.IConnection) {
  // 1. 두 명의 멤버 생성
  const mentioner: IDiscussionboardMembers = await api.functional.prefix.member.actors.members.create(connection, { body: { id: typia.random<string & tags.Format<"uuid">>(), created_at: new Date().toISOString() } });
