  // 2. 스레드 생성 (카테고리 id는 랜덤)
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(connection, { body: { discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(), title: "테스트 스레드", status: "active", is_pinned: false, is_locked: false, archived: false, created_at: new Date().toISOString(), updated_at: new Date().toISOString() } });
  typia.assert(thread);

  // 3. 게시글(post) 작성 (언급하는 멤버가 작성)
