import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IContentReport";
import type { IPageIContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIContentReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate moderator content report listing with comprehensive filter, search,
 * and pagination behaviors.
 *
 * The test creates a post, then creates several content reports with different
 * `status`, `report_reason`, and reporter identity (member). After setup, it
 * exercises the moderator's report listing API with:
 *
 * - Filter by status (e.g., only 'pending', only 'in_review', etc.)
 * - Filter by report_reason (search for a specific reason keyword)
 * - Filter by reporter_member_id (limit to a specific user)
 * - Combined search and pagination (limit, page) The test validates the API
 *   returns exactly and only the expected reports for each case (matching count
 *   and content). It also attempts to use an unsupported filter field to ensure
 *   the API correctly rejects or ignores it (error or empty/no-op behavior).
 *   Steps:
 *
 * 1. Create a discussion thread post that can be reported
 * 2. Create several content reports for that post, with at least 2 different
 *    member reporters, various reasons, and each status ('pending',
 *    'in_review', 'action_taken', 'dismissed')
 * 3. As moderator, call the contentReports.index API with: a) Filter by status =
 *    'pending' → only 'pending' status reports returned b) Filter by a specific
 *    report_reason value c) Filter by a reporter_member_id, confirm only their
 *    reports returned d) Paginate results (e.g. limit=2, page=2), check correct
 *    slicing/order e) Combine multiple filters
 * 4. Negative test: supply a non-existent filter property (e.g.,
 *    {not_a_real_filter: 1}) and confirm proper rejection or no filtering
 * 5. Validate response types, pagination info, and correct business behavior at
 *    each step
 */
export async function test_api_moderator_test_list_content_reports_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a new post that can be reported
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post1 = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: threadId,
        body: "This is the post to be reported",
        is_edited: false,
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(post1);

  // 2. Use two different reporter members
  const reporter_member1 = typia.random<string & tags.Format<"uuid">>();
  const reporter_member2 = typia.random<string & tags.Format<"uuid">>();
  // Timestamps for variety
  const report_times = [
    new Date(Date.now() - 3600 * 1000 * 4).toISOString(), // 4h ago
    new Date(Date.now() - 3600 * 1000 * 3).toISOString(),
    new Date(Date.now() - 3600 * 1000 * 2).toISOString(),
    new Date(Date.now() - 3600 * 1000 * 1).toISOString(),
  ];
  // Distinct reasons and statuses
  const reportData = [
    {
      reporter: reporter_member1,
      reason: "spam",
      status: "pending",
      at: report_times[0],
    },
    {
      reporter: reporter_member2,
      reason: "harassment",
      status: "in_review",
      at: report_times[1],
    },
    {
      reporter: reporter_member1,
      reason: "offtopic",
      status: "action_taken",
      at: report_times[2],
    },
    {
      reporter: reporter_member2,
      reason: "other",
      status: "dismissed",
      at: report_times[3],
    },
  ];
  const createdReports: IContentReport[] = [];
  for (const { reporter, reason, status, at } of reportData) {
    const report = await api.functional.prefix.member.contentReports.create(
      connection,
      {
        body: {
          reported_post_id: post1.id,
          reporter_member_id: reporter,
          report_reason: reason,
          status: status as
            | "pending"
            | "in_review"
            | "action_taken"
            | "dismissed",
          reported_at: at,
        } satisfies IContentReport.ICreate,
      },
    );
    typia.assert(report);
    createdReports.push(report);
  }

  // 3a) Filter by status
  let output = await api.functional.prefix.moderator.contentReports.index(
    connection,
    {
      body: {
        status: "pending",
      } satisfies IContentReport.IRequest,
    },
  );
  typia.assert(output);
  TestValidator.equals("reports with status 'pending'")(
    output.data.map((r) => r.status).every((s) => s === "pending"),
  )(true);

  // 3b) Filter by report_reason
  output = await api.functional.prefix.moderator.contentReports.index(
    connection,
    {
      body: {
        report_reason: "spam",
      } satisfies IContentReport.IRequest,
    },
  );
  typia.assert(output);
  TestValidator.equals("reports with reason 'spam'")(
    output.data.every((r) => r.report_reason === "spam"),
  )(true);

  // 3c) Filter by reporter_member_id
  output = await api.functional.prefix.moderator.contentReports.index(
    connection,
    {
      body: {
        reporter_member_id: reporter_member1,
      } satisfies IContentReport.IRequest,
    },
  );
  typia.assert(output);
  TestValidator.equals("reports by reporter_member1")(
    output.data.every((r) => r.reporter_member_id === reporter_member1),
  )(true);

  // 3d) Pagination
  output = await api.functional.prefix.moderator.contentReports.index(
    connection,
    {
      body: {
        limit: 2,
        page: 2,
      } satisfies IContentReport.IRequest,
    },
  );
  typia.assert(output);
  TestValidator.equals("pagination limit==2")(output.pagination.limit)(2);
  TestValidator.equals("pagination page==2")(output.pagination.current)(2);

  // 3e) Combined filters
  output = await api.functional.prefix.moderator.contentReports.index(
    connection,
    {
      body: {
        status: "action_taken",
        report_reason: "offtopic",
        reporter_member_id: reporter_member1,
      } satisfies IContentReport.IRequest,
    },
  );
  typia.assert(output);
  TestValidator.equals("combined filter result")(output.data.length)(
    createdReports.filter(
      (r) =>
        r.status === "action_taken" &&
        r.report_reason === "offtopic" &&
        r.reporter_member_id === reporter_member1,
    ).length,
  );

  // 4. Negative: unsupported filter field
  await TestValidator.error(
    "unsupported filter field should throw or be ignored",
  )(async () => {
    // This should throw, or return everything (no filter), but must not apply unknown field for filtering
    await api.functional.prefix.moderator.contentReports.index(connection, {
      body: {
        // @ts-expect-error: purposely using unsupported field
        not_a_real_filter: 1,
      } as any, // as any due to negative test, field not allowed by schema
    });
  });
}

