 *
 * Validates that:
 * - Only filters belonging to the authenticated member are returned
 * - Can search/filter own filters by name and is_public
 * - Soft-deleted filters (deleted_at != null) are excluded unless explicit
 * - Pagination and sorting work (current, limit, total count match expectations)
 * - Filters from other users are never included (privacy protection)
 *
 * Steps:
 * 1. Create several filters for this user (some private, some public, with unique names)
 * 2. Update one filter's name/is_public value
 * 3. Soft-delete one filter
 * 4. List all filters: verify only active (deleted_at=null), all are own filters
 * 5. Search/public filter: search for filters by name, filter with is_public, confirm correct set
 * 6. List soft-deleted filters (by explicitly filtering on deleted_at), confirm only deleted ones show
 * 7. Pagination: create sufficient filters, then test paginated responses
 * 8. Confirm no filters from other users leak into the result
 */
export async function test_api_prefix_member_my_filters_test_list_own_saved_filters_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Create filters: several public/private with unique names
  const filterCount = 5;
  const uniqueBase = RandomGenerator.alphabets(8) + Date.now();
  const createdFilters: IDiscussionboardFilter[] = [];
  for (let i = 0; i < filterCount; ++i) {
    const filter = await api.functional.prefix.member.my.filters.create(connection, {
      body: {
        name: `${uniqueBase}_name_${i}`,
        definition: JSON.stringify({ q: i }),
        is_public: i % 2 === 0,
      } satisfies IDiscussionboardFilter.ICreate,
    });
    typia.assert(filter);
    createdFilters.push(filter);
  }

  // 2. Update one filter's name and is_public
  const updatedFilterId = createdFilters[0].id;
  const updatedName = `${uniqueBase}_updated_name`;
  const updatedIsPublic = false;
  const updatedFilter = await api.functional.prefix.member.my.filters.update(connection, {
    filterId: updatedFilterId,
    body: {
      name: updatedName,
      is_public: updatedIsPublic,
    } satisfies IDiscussionboardFilter.IUpdate,
  });
  typia.assert(updatedFilter);
  TestValidator.equals("name updated")(updatedFilter.name)(updatedName);
  TestValidator.equals("is_public updated")(updatedFilter.is_public)(updatedIsPublic);

