import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";
import type { IPollVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPollVote";
import type { IPageIPollVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPollVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing poll votes with filter and pagination.
 *
 * Scenario:
 * 1. Register several members to represent voters.
 * 2. Create a discussion thread for associating polls.
 * 3. Create a poll related to the thread.
 * 4. Each member casts a poll vote (potentially with different selected_option values).
 * 5. Retrieve poll votes with different filter scenarios:
 *    a. Filter by poll ID (should return only votes for that poll).
 *    b. Filter by voting_member_id (should return only that member's vote).
 *    c. Filter by both (should return only the expected vote if exists).
 *    d. Without filters (should return all votes, paginated).
 * 6. Assert returned results conform to schema and filters, validate pagination meta.
 *
 * Notes:
 * - The only filterable/searchable fields are: discussionboard_poll_id, voting_member_id, selected_option.
 * - Pagination validation covers at least two pages if enough votes exist.
 * - All operations use only documented DTOs and API endpoints.
 */
export async function test_api_pollVotes_test_list_poll_votes_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Register multiple members
  const memberCount = 5;
  const members = await ArrayUtil.asyncRepeat(memberCount)(async () => {
    const member = await api.functional.prefix.member.actors.members.create(connection, {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString() as string & tags.Format<"date-time">,
      }
    });
    typia.assert(member);
    return member;
  });

  // 2. Create thread (associate with first member)
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(connection, {
    body: {
      discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(10),
      status: "active",
      is_pinned: false,
      is_locked: false,
      archived: false,
      created_at: new Date().toISOString() as string & tags.Format<"date-time">,
      updated_at: new Date().toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(thread);

  // 3. Create poll (by first member, for thread)
  const poll = await api.functional.prefix.member.polls.create(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      prompt: "Which option do you prefer?",
      allow_multiple_choices: false,
      is_anonymous: false,
      expires_at: undefined, // optional
    },
  });
  typia.assert(poll);

  // 4. Each member votes on poll
  const options = ["A", "B", "C"];
  const votes = [];
  for (const member of members) {
    // Normally, the session would be swapped for each member; in this simulation, we make the request serially
    const option = RandomGenerator.pick(options);
    const vote = await api.functional.prefix.member.pollVotes.create(connection, {
      body: {
        discussionboard_poll_id: poll.id,
        selected_option: option,
      },
    });
    typia.assert(vote);
    votes.push(vote);
  }

  // 5a. Retrieve all votes for that poll (by poll ID)
  const resByPoll = await api.functional.prefix.member.pollVotes.index(connection, {
    body: {
      discussionboard_poll_id: poll.id,
    },
  });
  typia.assert(resByPoll);
  TestValidator.predicate("all votes belong to poll")(
    resByPoll.data.every(v => v.discussionboard_poll_id === poll.id),
  );

  // 5b. Retrieve vote for a specific member
  const firstVote = votes[0];
  const resByMember = await api.functional.prefix.member.pollVotes.index(connection, {
    body: {
      voting_member_id: firstVote.voting_member_id,
    },
  });
  typia.assert(resByMember);
  TestValidator.predicate("all votes belong to member")(
    resByMember.data.every(v => v.voting_member_id === firstVote.voting_member_id),
  );

  // 5c. Filter by both poll ID and member ID (should yield zero or one)
  const resByBoth = await api.functional.prefix.member.pollVotes.index(connection, {
    body: {
      discussionboard_poll_id: poll.id,
      voting_member_id: firstVote.voting_member_id,
    },
  });
  typia.assert(resByBoth);
  TestValidator.predicate("at most 1 vote for poll+member")(resByBoth.data.length <= 1);
  if (resByBoth.data.length === 1) {
    const vote = resByBoth.data[0];
    TestValidator.equals("poll id")(vote.discussionboard_poll_id)(poll.id);
    TestValidator.equals("member id")(vote.voting_member_id)(firstVote.voting_member_id);
  }

  // 5d. No filters (should see all votes)
  const resAll = await api.functional.prefix.member.pollVotes.index(connection, {
    body: {},
  });
  typia.assert(resAll);
  TestValidator.predicate("all test votes are present")(
    votes.every(vote => resAll.data.some(d => d.id === vote.id)),
  );

  // 6. Pagination: Simulate a page limit smaller than total votes
  const lim = 2;
  const resPage1 = await api.functional.prefix.member.pollVotes.index(connection, {
    body: { discussionboard_poll_id: poll.id },
  });
  typia.assert(resPage1);
  TestValidator.predicate("limit >= number of votes")(
    resPage1.data.length <= lim || resPage1.data.length === memberCount,
  );
  // Note: Real page/limit support not in schema, so we can only check what backend returns
}

