import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IMention";
import type { IPageIMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIMention";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { discussionboard_mentions } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboard_mentions";

/**
 * 테스트 목적: 대규모 멘션 데이터를 효율적으로 필터링/검색/페이징/정렬로 검토할 수 있는지 검증합니다.
 *
 * 비즈니스 컨텍스트: Moderator가 시스템 내 discussionboard_mentions 기록을 다량 검토할 때, 날짜, 멤버, 게시글 등 조건별로 페이징/조건검색/정렬 기능이 정확히 동작해야 하며 권한(Moderator만 접근가능)도 제대로 적용돼야 합니다.
 *
 * 테스트 시나리오:
 * 1. Mentions에 참여할 여러 회원(Member)을 생성한다.
 * 2. 각 멤버들이 참여할 스레드(Threads)를 1개 이상 생성한다.
 * 3. 생성된 스레드 내에 다수의 게시글(Posts)을 작성한다.
 * 4. 랜덤하게 각 멤버들을 여러 게시글에서 멘션(discussionboard_mentions)한다.
 * 5. 멘션이 충분히 누적된 뒤, moderator API로 페이징, limit, 멤버, 게시글, 기간(created_at), 등 다양한 조합으로 검색한다.
 * 6. 응답 데이터의 pagination, data 개수, 각 멘션이 입력조건과 일관되는지 검증한다.
 * 7. 에지케이스(검색결과 없음, 마지막 페이지, page number, limit 등)도 확인한다.
 * 8. (접근 권한 테스트는 별도 계정 권한 시나리오에서 수행) 
 */
export async function test_api_moderator_test_moderator_mentions_pagination_and_search(
  connection: api.IConnection,
) {
  // 1. 멤버 여러 명 생성
  const memberCount = 5;
  const members = await ArrayUtil.asyncRepeat(memberCount)(async () => {
    const input = {
      id: typia.random<string & tags.Format<"uuid">>(),
      created_at: new Date().toISOString() as string & tags.Format<"date-time">,
    } satisfies IDiscussionboardMembers.ICreate;
    const member = await api.functional.prefix.member.actors.members.create(connection, { body: input });
    typia.assert(member);
    return member;
  });

  // 2. 스레드 여러 개 생성 (1명당 1개씩)
  const threads = await ArrayUtil.asyncMap(members)(async (member) => {
    const input = {
      discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      status: "active",
      is_pinned: false,
      is_locked: false,
      archived: false,
      created_at: new Date().toISOString() as string & tags.Format<"date-time">,
      updated_at: new Date().toISOString() as string & tags.Format<"date-time">,
    } satisfies IDiscussionboardThreads.ICreate;
    const thread = await api.functional.prefix.member.threadsPosts.threads.create(connection, { body: input });
    typia.assert(thread);
    return thread;
  });

  // 3. 각 스레드당 다수의 게시글 작성 (N x M 구조)
  const postCountPerThread = 5;
  let allPosts: IDiscussionboardPosts[] = [];
  for (const thread of threads) {
    const posts = await ArrayUtil.asyncRepeat(postCountPerThread)(async () => {
      const input = {
        discussionboard_thread_id: thread.id,
        body: RandomGenerator.content()(1, 2),
        is_edited: false,
      } satisfies IDiscussionboardPosts.ICreate;
      const post = await api.functional.prefix.member.threadsPosts.posts.create(connection, { body: input });
      typia.assert(post);
      return post;
    });
    allPosts.push(...posts);
  }

  // 4. 게시글 여러 개에 랜덤하게 멤버들을 멘션
  const mentionCount = 20;
  const mentions = await ArrayUtil.asyncRepeat(mentionCount)(async () => {
    const randomPost = RandomGenerator.pick(allPosts);
    const randomMember = RandomGenerator.pick(members);
    const input = {
      discussionboard_post_id: randomPost.id,
      mentioned_member_id: randomMember.id,
    } satisfies discussionboard_mentions.ICreate;
    const mention = await api.functional.prefix.member.mentions.create(connection, { body: input });
    typia.assert(mention);
    return mention;
  });

  // 5. 페이징+필터 API에 다양한 파라미터 조합으로 검색
  // (1) limit, page 기본값
  let response = await api.functional.prefix.moderator.mentions.index(connection, {
    body: {
      limit: 5,
      page: 1,
    },
  });
  typia.assert(response);
  TestValidator.equals("limit test")(response.pagination.limit)(5);
  TestValidator.equals("current page")(response.pagination.current)(1);
  TestValidator.predicate("최대 5건 이하 반환됨")(response.data.length <= 5);

  // (2) 특정 멤버로 필터
  response = await api.functional.prefix.moderator.mentions.index(connection, {
    body: {
      mentioned_member_id: members[0].id,
    },
  });
  typia.assert(response);
  TestValidator.predicate("필터된 멘션들은 모두 해당 멤버임")(response.data.every((item) => item.mentioned_member_id === members[0].id));

  // (3) 특정 게시글로 필터
  response = await api.functional.prefix.moderator.mentions.index(connection, {
    body: {
      discussionboard_post_id: allPosts[0].id,
    },
  });
  typia.assert(response);
  TestValidator.predicate("모든 아이템이 대상 post id")(response.data.every((item) => item.discussionboard_post_id === allPosts[0].id));

  // (4) created_at 기간 필터
  const now = new Date();
  const hourAgo = new Date(now.getTime() - 3600 * 1000);
  response = await api.functional.prefix.moderator.mentions.index(connection, {
    body: {
      created_at_from: hourAgo.toISOString() as string & tags.Format<"date-time">,
      created_at_to: now.toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(response);
  TestValidator.predicate("모든 created_at 값이 검색범위 내")(response.data.every((item) => {
    const created = new Date(item.created_at).getTime();
    return created >= hourAgo.getTime() && created <= now.getTime();
  }));

  // (5) 에지케이스 - 매우 높은 page number
  response = await api.functional.prefix.moderator.mentions.index(connection, {
    body: {
      limit: 5,
      page: 999,
    },
  });
  typia.assert(response);
  TestValidator.equals("마지막 페이지 or empty")(response.data.length)(0);
}

