 *
 * 비즈니스 시나리오:
 * - 여러 개의 스레드(토론글)를 생성하고, 각각을 서로 다른 archive_reason(아카이브 사유) 값으로 soft-archive(아카이브) 처리한다.
 * - 이후, 타겟 archive_reason 조건에 딱 맞는 아카이브 데이터만 필터링 조회한다.
 *
 * 1. 관리자 역할을 가진 테스트 유저를 생성한다. (실제 회원/유저 생성 경로가 없는 경우, 관리자는 테이블 내 UUID만 필요)
 * 2. 여러 개의 스레드를 순차적으로 생성한다 (동일 회원, 각기 다른 제목/카테고리 등 랜덤 값 적용, 최소 2개 이상)
 * 3. 각 스레드별로 archive_reason이 서로 다르게(예: "정책위반", "작성자요청", "기타사유" 등) soft-archive 처리 (DELETE 호출로 archived 처리)
 * 4. admin archive 목록 API에서 target archive_reason(예: "정책위반") 으로 필터링해서, 해당 reason으로 아카이브된 스레드 아카이브만 조회되는지 확인한다.
 * 5. Validation: data 배열 내 archive_reason, 총 갯수, (해당 reason 이외 값의 미출현) 여부 확인
 *
 * 성공경로 외 사양/실패케이스:
 * - 존재하지 않는 archive_reason 검색 시, 빈 배열 응답
 */
export async function test_api_admin_test_admin_filter_thread_archives_by_reason(
  connection: api.IConnection,
) {
  // 1. 테스트 admin 역할 계정(회원 UUID) 생성 및 관리자 할당
  const adminId: string = typia.random<string & tags.Format<"uuid">>();
  const admin: IDiscussionboardAdmin = await api.functional.prefix.admin.actors.admins.create(
    connection,
    {
      body: {
        id: adminId,
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardAdmin.ICreate,
    },
  );
  typia.assert(admin);

  // 2. 스레드 2개 이상 생성 (예: 3개, 서로 다른 제목/카테고리)
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();
  const threads: IDiscussionboardThreads[] = await ArrayUtil.asyncRepeat(3)(async (idx) => {
    return api.functional.prefix.member.threadsPosts.threads.create(
      connection,
      {
        body: {
          discussionboard_category_id: categoryId,
          title: `테스트 스레드 ${idx + 1}`,
          status: "active",
          is_pinned: false,
          is_locked: false,
          archived: false,
          created_at: new Date(now.getTime() + idx * 5000).toISOString(),
          updated_at: new Date(now.getTime() + idx * 5000).toISOString(),
        } satisfies IDiscussionboardThreads.ICreate,
      },
    );
  });
  threads.forEach(typia.assert);

  // 3. 각기 다른 archive_reason(예시: '정책위반', '작성자요청', '기타사유')으로 thread들을 archive (소프트삭제)
  // 삭제 API 별도 archive_reason 형태 지원이 없으므로, 실제로는 사유 직접 셋팅 불가 (시나리오상 모두 동일 방식 처리가정)
  await ArrayUtil.asyncMap(threads)(async (thread) => {
    await api.functional.prefix.member.my.threadsPosts.threads.erase(
      connection,
      { id: thread.id },
    );
  });

  // 4. archive 목록에서 target archive_reason 필터 적용해 조회 (예시로 첫번째 사유 사용 가능)
  const targetReason = "정책위반";
  const page: IPageIThreadArchive = await api.functional.prefix.admin.threadsPosts.threadArchives.index(
    connection,
    {
      body: { archive_reason: targetReason },
    },
  );
  typia.assert(page);

  // 5. 검증: 응답 data 배열의 각 archive_reason이 target 과 정확히 일치하는지만 확인
  page.data.forEach((archive) => {
    TestValidator.equals("archive reason match")(archive.archive_reason)(targetReason);
  });

  // 6. 실패/빈케이스 검증 : 존재하지 않는 archive_reason으로 요청
  const emptyResult = await api.functional.prefix.admin.threadsPosts.threadArchives.index(
    connection,
    { body: { archive_reason: "존재하지않는사유" } },
  );
  typia.assert(emptyResult);
  TestValidator.equals("no archives for unknown reason")(emptyResult.data.length)(0);
}

