  TestValidator.equals("page1 limit")(resPage1.pagination.limit)(limit);

  // 7. Pagination: limit=2, offset=2 (should return next 2 results)
  const resPage2 =
    await api.functional.prefix.member.my.discussionboardAlerts.index(
      connection,
      { body: { limit, offset: 2, sort: "created_at_asc" } },
    );
  typia.assert(resPage2);
  TestValidator.equals("page2 count")(resPage2.data.length)(
    createdAlerts.length > 2 ? Math.min(limit, createdAlerts.length - 2) : 0,
  );
  TestValidator.equals("page2 current page")(resPage2.pagination.current)(2);

  // 8. Each listed alert matches filter criteria and schema
  for (const alert of resType.data) {
    typia.assert(alert);
    TestValidator.equals("type filter is correct")(alert.type)("policy_update");
  }
  for (const alert of resSevAct.data) {
    typia.assert(alert);
    TestValidator.equals("severity filter is correct")(alert.severity)(
      "critical",
    );
    TestValidator.equals("is_active filter is correct")(alert.is_active)(true);
  }

  // 9. Edge case: filtering with impossible condition yields zero results
  const resNone =
    await api.functional.prefix.member.my.discussionboardAlerts.index(
      connection,
      { body: { type: "no_such_type" } },
    );
  typia.assert(resNone);
  TestValidator.equals("zero results for non-existent type")(
    resNone.data.length,
  )(0);
  TestValidator.predicate("empty result data")(
    Array.isArray(resNone.data) && resNone.data.length === 0,
  );
}

