import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";
import type { IPollVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPollVote";
import type { IPageIPollVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPollVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing/searching poll votes as an admin, covers:
 * - Filtering by poll id, voting member id, selected option (schema only)
 * - Pagination & ordering
 * - Only valid fields are accepted as filter
 * - Edge case: no votes for poll or nonexistent poll id filter returns empty
 * - Permissions: only admins can access, fail for regular member
 * - Failures for invalid filter keys/types
 */
export async function test_api_prefix_admin_pollVotes_test_list_poll_votes_with_various_filters_and_permissions(
  connection: api.IConnection,
) {
  // Setup: create poll (as member)
  const poll = await api.functional.prefix.member.polls.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      prompt: "Best color?",
      allow_multiple_choices: false,
      is_anonymous: false,
      expires_at: null,
    },
  });
  typia.assert(poll);

  // Add a vote (as member)
  const vote = await api.functional.prefix.member.pollVotes.create(connection, {
    body: {
      discussionboard_poll_id: poll.id,
      selected_option: "blue",
    },
  });
  typia.assert(vote);

  // As ADMIN: list all votes
  // (Assume test infra can elevate connection perms, or swap connection to admin)
  const votesAll = await api.functional.prefix.admin.pollVotes.index(connection, {
    body: {}, // No filter = all
  });
  typia.assert(votesAll);
  TestValidator.predicate("at least 1 vote")(votesAll.data.length >= 1);

  // Filter: by poll id
  const votesByPoll = await api.functional.prefix.admin.pollVotes.index(connection, {
    body: { discussionboard_poll_id: poll.id },
  });
  typia.assert(votesByPoll);
  TestValidator.predicate("only the filtered poll's votes")(
    votesByPoll.data.every(row => row.discussionboard_poll_id === poll.id),
  );

  // Filter: by member id
  TestValidator.predicate("at least one vote has correct voter id")(
    votesByPoll.data.some(row => row.voting_member_id === vote.voting_member_id),
  );

  // Filter: option
  const votesByOpt = await api.functional.prefix.admin.pollVotes.index(connection, {
    body: { selected_option: "blue" },
  });
  typia.assert(votesByOpt);
  TestValidator.predicate("at least one vote with option blue")(
    votesByOpt.data.some(row => row.selected_option === "blue"),
  );

  // Filter: nonexistent poll id
  const votesByFake = await api.functional.prefix.admin.pollVotes.index(connection, {
    body: { discussionboard_poll_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(votesByFake);
  TestValidator.equals("empty for nonexistent poll")(votesByFake.data.length)(0);

  // Edge: filter by all criteria (vote must match all, else empty)
  const votesByAll = await api.functional.prefix.admin.pollVotes.index(connection, {
    body: {
      discussionboard_poll_id: poll.id,
      voting_member_id: vote.voting_member_id,
      selected_option: "blue",
    },
  });
  typia.assert(votesByAll);
  TestValidator.predicate("exact match with all filters")(
    votesByAll.data.every(row =>
      row.discussionboard_poll_id === poll.id &&
      row.voting_member_id === vote.voting_member_id &&
      row.selected_option === "blue"
    ),
  );

  // Pagination: make at least one more vote and check paging
  const vote2 = await api.functional.prefix.member.pollVotes.create(connection, {
    body: {
      discussionboard_poll_id: poll.id,
      selected_option: "red",
    },
  });
  typia.assert(vote2);

  const votesPaged = await api.functional.prefix.admin.pollVotes.index(connection, {
    body: { discussionboard_poll_id: poll.id },
  });
  typia.assert(votesPaged);
  TestValidator.predicate("paging meta present")(
    typeof votesPaged.pagination?.current === "number" &&
      typeof votesPaged.pagination?.limit === "number",
  );

  // Permissions: member should not access (simulate with member-level connection)
  await TestValidator.error("fail for member-level non-admin")(() =>
    api.functional.prefix.admin.pollVotes.index(connection, {
      body: {},
    })
  );

  // Failure: extra field in filter (invalid)
  await TestValidator.error("fail on non-schema filter field")(() =>
    api.functional.prefix.admin.pollVotes.index(connection, {
      body: { fake_field: 123 },
    })
  );

  // Failure: wrong type for filter
  await TestValidator.error("fail on invalid type in filter")(() =>
    api.functional.prefix.admin.pollVotes.index(connection, {
      body: { discussionboard_poll_id: 123 as any },
    })
  );
}

