import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IPageIDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardPosts";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 다양한 필터와 페이지네이션 옵션으로 게시물 페이지네이션 리스트 API를 검증합니다.
 * 
 * 1. 여러 개(최소 2개 이상의 thread)에 대해 parent post(최상위)와 reply(답글) 형태의 post를 다양하게 생성하며, 각 post는 body, is_edited, is_deleted, created_at 값을 다르게 설정합니다.
 * 2. (a) 특정 스레드에 속한 게시글만 필터링, (b) is_deleted=false만 필터링, (c) 본문 텍스트 일부(body 포함 substring)로 서치, (d) created_at 및 기타 필드로 정렬과 페이지네이션이 기대대로 되는지 각각 확인합니다.
 * 3. 각 필터/정렬/페이지네이션 조합별로 API 결과 data가 올바르게 반환되고 pagination 정보가 기대대로 맞는지 검증합니다.
 * 
 * 세부 검증 항목:
 * - thread_id 별 분류 필터
 * - is_deleted=true/false 필터
 * - body 내 substring 검색
 * - page/limit 별 페이지네이션 일관성과 누락 없는지
 * - created_at 등 필드 기준 정렬 정확성
 */
export async function test_api_threadsPosts_test_list_posts_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 테스트 데이터 준비: 두 개 이상의 스레드 생성
  const threads = await Promise.all([
    api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_category_id: typia.random<string & tags.Format<'uuid'>>(),
        title: 'FilterTest Thread A',
        status: 'active',
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(), // 어제
        updated_at: new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(),
      } satisfies IDiscussionboardThreads.ICreate,
    }),
    api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_category_id: typia.random<string & tags.Format<'uuid'>>(),
        title: 'FilterTest Thread B',
        status: 'active',
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      } satisfies IDiscussionboardThreads.ICreate,
    }),
  ]);
  typia.assert(threads[0]);
  typia.assert(threads[1]);

  // 2. 여러 post와 reply를 다양한 조합(is_deleted, is_edited, created_at, body 포함)으로 생성
  const [postA1, postA2, replyA2a] = await Promise.all([
    // Thread A의 최상위 post
    api.functional.prefix.member.threadsPosts.posts.create(connection, {
      body: {
        discussionboard_thread_id: threads[0].id,
        body: 'This is first post in Thread A - has keySearchWord',
        is_edited: false,
      } satisfies IDiscussionboardPosts.ICreate,
    }),
    // Thread A의 두 번째 post (삭제됨)
    api.functional.prefix.member.threadsPosts.posts.create(connection, {
      body: {
        discussionboard_thread_id: threads[0].id,
        body: 'Second post in Thread A',
        is_edited: true,
      } satisfies IDiscussionboardPosts.ICreate,
    }),
    // Thread A의 두 번째 post에 대한 reply
    api.functional.prefix.member.threadsPosts.posts.create(connection, {
      body: {
        discussionboard_thread_id: threads[0].id,
        parent_post_id: undefined, // 우선 없는 값으로 reply 테스트 (추후 수정 필요)
        body: 'Reply to second post',
        is_edited: false,
      } satisfies IDiscussionboardPosts.ICreate,
    }),
  ]);

  typia.assert(postA1);
  typia.assert(postA2);
  typia.assert(replyA2a);

  // Thread B용 post
  const [postB1, postB2] = await Promise.all([
    api.functional.prefix.member.threadsPosts.posts.create(connection, {
      body: {
        discussionboard_thread_id: threads[1].id,
        body: 'This is first post in Thread B',
        is_edited: true,
      } satisfies IDiscussionboardPosts.ICreate,
    }),
    api.functional.prefix.member.threadsPosts.posts.create(connection, {
      body: {
        discussionboard_thread_id: threads[1].id,
        body: 'Second post in Thread B with keySearchWord',
        is_edited: false,
      } satisfies IDiscussionboardPosts.ICreate,
    }),
  ]);
  typia.assert(postB1);
  typia.assert(postB2);

  // 삭제 상태 포스트는 직접 생성 불가(is_deleted는 서버 측 제어), 실제로 생성 후 soft-delete 처리 가정 불가 → 테스트 데이터는 생성만 (is_deleted = false로만 생성됨)

  // 3.a) 특정 thread_id로 필터링해서 검색
  const filteredByThreadA = await api.functional.prefix.threadsPosts.posts.index(connection, {
    body: {
      discussionboard_thread_id: threads[0].id,
    } satisfies IDiscussionboardPosts.IRequest,
  });
  typia.assert(filteredByThreadA);
  TestValidator.predicate('thread A만 반환')(filteredByThreadA.data.every(post => post.discussionboard_thread_id === threads[0].id));

  // 3.b) 본문에 keySearchWord 포함된 post만 검색
  const filteredByBody = await api.functional.prefix.threadsPosts.posts.index(connection, {
    body: {
      body: 'keySearchWord',
    } satisfies IDiscussionboardPosts.IRequest,
  });
  typia.assert(filteredByBody);
  TestValidator.predicate('본문 키워드 포함 여부')(filteredByBody.data.every(post => post.body.includes('keySearchWord')));

  // 3.c) is_deleted=false만 검색 (생성시 모두 false 이므로 전체 조회와 같음)
  const filteredNotDeleted = await api.functional.prefix.threadsPosts.posts.index(connection, {
    body: {
      is_deleted: false,
    } satisfies IDiscussionboardPosts.IRequest,
  });
  typia.assert(filteredNotDeleted);
  TestValidator.predicate('삭제되지 않은 게시글만')(filteredNotDeleted.data.every(post => post.is_deleted === false));

  // 3.d) 페이지네이션(예: 1페이지 2개 제한) - 실제로는 IRequest에 페이지/limit 필드는 없음, 페이징은 서버 쿼리 기본값 적용 가정 및 pagination 필드 검증만 수행
  TestValidator.predicate('pagination 필드 존재')(typeof filteredNotDeleted.pagination === 'object');
}

