import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IWarningLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IWarningLog";
import type { IPageIWarningLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIWarningLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Retrieve moderator warning logs with diverse filters and pagination.
 *
 * This test exercises the search and listing endpoint for moderator-issued
 * warning logs using a broad range of filter and pagination options. It seeds
 * multiple warning log records with different moderator_ids, warned_member_ids,
 * warning reasons, and issued_at timestamps. The test then issues queries to:
 *
 * - Filter logs by single moderator
 * - Filter logs by warned member
 * - Perform reason text keyword search
 * - Filter logs by date range
 * - Apply combinations of filters
 * - Test pagination by varying page/limit
 * - Confirm sorting by issued_at ascending and descending (asc/desc search not
 *   directly present in API filter, so omitted)
 * - Validate edge case: filter using non-existent member/reason should yield
 *   empty result At each step, the test asserts output matches correct schema,
 *   that results correspond to the input filters, and verifies no extraneous
 *   records are present.
 *
 * Steps:
 *
 * 1. Seed at least three warning log records, varying moderator_id,
 *    warned_member_id, warning_reason and issued_at (covering different dates
 *    and keywords).
 * 2. For each filter/search scenario (moderator, warned_member, warning_reason
 *    text search, date range, combinations):
 *
 *    - Call the list endpoint with relevant IWarningLog.IRequest filters.
 *    - Assert only matching records are returned, in correct order.
 *    - Confirm page/limit/pagination worked as expected.
 *    - For non-hit edge case (random reason/member), assert results are empty.
 * 3. For all list results, assert the returned value matches IPageIWarningLog and
 *    contains no records other than warning logs matching the filters.
 */
export async function test_api_prefix_admin_warningLogs_test_list_warning_logs_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Prepare test data: create warning logs with varying fields
  const moderatorIds = ArrayUtil.repeat(2)(() =>
    typia.random<string & tags.Format<"uuid">>(),
  );
  const memberIds = ArrayUtil.repeat(3)(() =>
    typia.random<string & tags.Format<"uuid">>(),
  );
  const reasons = [
    "Spam advertisement detected",
    "Harassment report",
    "Inappropriate language in forum",
  ];
  const issuedAts = [
    new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString(), // 1 week ago
    new Date().toISOString(),
    new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(), // 1 day ago
  ];
  const testLogs: IWarningLog[] = [];
  for (let i = 0; i < 3; ++i) {
    const log = await api.functional.prefix.moderator.warningLogs.create(
      connection,
      {
        body: {
          moderator_id: moderatorIds[i % moderatorIds.length],
          warned_member_id: memberIds[i % memberIds.length],
          warning_reason: reasons[i],
          issued_at: issuedAts[i],
        } satisfies IWarningLog.ICreate,
      },
    );
    typia.assert(log);
    testLogs.push(log);
  }

  // 2. Filter by moderator_id
  for (const modId of moderatorIds) {
    const output = await api.functional.prefix.admin.warningLogs.index(
      connection,
      {
        body: { moderator_id: modId } satisfies IWarningLog.IRequest,
      },
    );
    typia.assert(output);
    for (const wl of output.data)
      TestValidator.equals("moderator_id matches")(wl.moderator_id)(modId);
  }

  // 3. Filter by warned_member_id
  for (const memId of memberIds) {
    const output = await api.functional.prefix.admin.warningLogs.index(
      connection,
      {
        body: { warned_member_id: memId } satisfies IWarningLog.IRequest,
      },
    );
    typia.assert(output);
    for (const wl of output.data)
      TestValidator.equals("warned_member_id matches")(wl.warned_member_id)(
        memId,
      );
  }

  // 4. Filter by warning_reason keyword search
  for (const keyword of ["Spam", "Harassment", "forum"]) {
    const output = await api.functional.prefix.admin.warningLogs.index(
      connection,
      {
        body: { warning_reason: keyword } satisfies IWarningLog.IRequest,
      },
    );
    typia.assert(output);
    for (const wl of output.data)
      TestValidator.predicate(`reason includes '${keyword}'`)(
        wl.warning_reason.includes(keyword),
      );
  }

  // 5. Filter by issued_at_from (find logs issued since yesterday)
  const fromDate = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
  const outputFrom = await api.functional.prefix.admin.warningLogs.index(
    connection,
    {
      body: { issued_at_from: fromDate } satisfies IWarningLog.IRequest,
    },
  );
  typia.assert(outputFrom);
  for (const wl of outputFrom.data)
    TestValidator.predicate("issued_at >= fromDate")(wl.issued_at >= fromDate);

  // 6. Filter by issued_at_to (find logs before now - 1 day)
  const beforeDate = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
  const outputTo = await api.functional.prefix.admin.warningLogs.index(
    connection,
    {
      body: { issued_at_to: beforeDate } satisfies IWarningLog.IRequest,
    },
  );
  typia.assert(outputTo);
  for (const wl of outputTo.data)
    TestValidator.predicate("issued_at <= beforeDate")(
      wl.issued_at <= beforeDate,
    );

  // 7. Combination filter: moderator + member + reason + date range
  const combo = {
    moderator_id: moderatorIds[0],
    warned_member_id: memberIds[0],
    warning_reason: reasons[0].split(" ")[0], // partial word from reason
    issued_at_from: issuedAts[0],
    issued_at_to: issuedAts[0],
  } satisfies IWarningLog.IRequest;
  const comboOut = await api.functional.prefix.admin.warningLogs.index(
    connection,
    { body: combo },
  );
  typia.assert(comboOut);
  for (const wl of comboOut.data) {
    TestValidator.equals("moderator_id matches")(wl.moderator_id)(
      combo.moderator_id,
    );
    TestValidator.equals("warned_member_id matches")(wl.warned_member_id)(
      combo.warned_member_id,
    );
    TestValidator.predicate("warning_reason includes combo keyword")(
      wl.warning_reason.includes(combo.warning_reason!),
    );
    TestValidator.equals("issued_at matches")(wl.issued_at)(
      combo.issued_at_from,
    );
  }

  // 8. Pagination and limit: limit=2, page=1
  const paged = await api.functional.prefix.admin.warningLogs.index(
    connection,
    {
      body: { limit: 2, page: 1 } satisfies IWarningLog.IRequest,
    },
  );
  typia.assert(paged);
  TestValidator.equals("max results")(paged.data.length)(2);

  // 9. Pagination page 2
  if (paged.pagination.pages > 1) {
    const paged2 = await api.functional.prefix.admin.warningLogs.index(
      connection,
      {
        body: { limit: 2, page: 2 } satisfies IWarningLog.IRequest,
      },
    );
    typia.assert(paged2);
    TestValidator.equals("page number")(paged2.pagination.current)(2);
  }

  // 10. Edge case: filter by non-existent reason
  const noneReason = await api.functional.prefix.admin.warningLogs.index(
    connection,
    {
      body: {
        warning_reason: "NoSuchReason12345",
      } satisfies IWarningLog.IRequest,
    },
  );
  typia.assert(noneReason);
  TestValidator.equals("empty result for non-existent reason")(
    noneReason.data.length,
  )(0);

  // 11. Edge case: filter by non-existent member
  const noneMember = await api.functional.prefix.admin.warningLogs.index(
    connection,
    {
      body: {
        warned_member_id: typia.random<string & tags.Format<"uuid">>(),
      } satisfies IWarningLog.IRequest,
    },
  );
  typia.assert(noneMember);
  TestValidator.equals("empty result for non-existent member")(
    noneMember.data.length,
  )(0);
}

