    body: {
      code: `code_${Date.now()}`,
      display_name: "Initial Tag",
      description: "Tag for update test.",
      is_restricted: false,
      is_hidden: false,
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(tag1);

  // Step 3: Create initial taggedThread association between thread1 and tag1
  const taggedThread = await api.functional.prefix.member.taggedThreads.create(connection, {
    body: {
