import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IContentReport";
import type { IPageIContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIContentReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test administrative retrieval of content reports using various filters and
 * pagination options.
 *
 * 이 테스트는 admin content report 검색 기능이 다양한 필터와 페이지네이션 옵션을 올바르게 지원하는지 검증합니다. 아래와
 * 같은 워크플로우를 따릅니다:
 *
 * 1. 멤버 권한으로 여러 개(최소 2개 이상) content report를 생성하여 테스트용 데이터를 준비합니다.
 * 2. Admin 권한으로 status/신고사유/리포터/신고기간/페이지네이션 등 여러 필터로 검색합니다.
 *
 *    - Status
 *    - Report_reason
 *    - Reporter_member_id
 *    - Reported_at range
 *    - 페이지/limit 조합
 *    - 조합 필터 (status + report_reason)
 *    - 결과가 없는 검색
 *    - 최대 page size
 *    - 잘못된(음수) 페이지 요청 등 에지케이스
 * 3. 각각의 검색 결과에 대해:
 *
 *    - 필터 입력 기준과 결과 데이터가 일치하는지
 *    - Pagination 정보가 정확한지
 *    - 빈 결과인 경우에도 pagination 구조가 유지되는지
 *    - 잘못된 입력은 명확한 error로 graceful 하게 처리되는지 검증합니다.
 *    - 모든 응답은 타입 명세와 일치하는지 typia.assert로 점검
 */
export async function test_api_prefix_admin_contentReports_index_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 테스트용 content report 2건 준비 (멤버 권한 가정)
  const now = new Date();
  const reportReasonA = "Spam/advertising";
  const reportReasonB = "Offensive language";
  const postIdA = typia.random<string & tags.Format<"uuid">>();
  const postIdB = typia.random<string & tags.Format<"uuid">>();
  const reporterMemberId = typia.random<string & tags.Format<"uuid">>();

  // 신고1: status 'pending', 특정 reportReasonA
  const reportA = await api.functional.prefix.member.contentReports.create(
    connection,
    {
      body: {
        reported_post_id: postIdA,
        reporter_member_id: reporterMemberId,
        report_reason: reportReasonA,
        status: "pending",
        reported_at: now.toISOString(),
        moderator_note: null,
      },
    },
  );
  typia.assert(reportA);

  // 신고2: status 'in_review', 다른 reportReasonB, 시간 다름, note 있음
  const reportB = await api.functional.prefix.member.contentReports.create(
    connection,
    {
      body: {
        reported_post_id: postIdB,
        reporter_member_id: reporterMemberId,
        report_reason: reportReasonB,
        status: "in_review",
        reported_at: new Date(now.getTime() + 1000).toISOString(),
        moderator_note: "Needs urgent review",
      },
    },
  );
  typia.assert(reportB);

  // 2-1. status별 검색
  const byStatus = await api.functional.prefix.admin.contentReports.index(
    connection,
    {
      body: { status: "pending" },
    },
  );
  typia.assert(byStatus);
  TestValidator.predicate("status filter: 모두 'pending'")(
    byStatus.data.every((r) => r.status === "pending"),
  );

  // 2-2. report_reason별 검색
  const byReason = await api.functional.prefix.admin.contentReports.index(
    connection,
    {
      body: { report_reason: reportReasonA },
    },
  );
  typia.assert(byReason);
  TestValidator.predicate("report_reason filter: 모두 일치")(
    byReason.data.every((r) => r.report_reason === reportReasonA),
  );

  // 2-3. reporter_member_id로 검색
  const byReporter = await api.functional.prefix.admin.contentReports.index(
    connection,
    {
      body: { reporter_member_id: reporterMemberId },
    },
  );
  typia.assert(byReporter);
  TestValidator.predicate("reporter_member_id filter: 모두 동일")(
    byReporter.data.every((r) => r.reporter_member_id === reporterMemberId),
  );

  // 2-4. 신고일 기준 범위 검색
  const start = now.toISOString();
  const end = new Date(now.getTime() + 2000).toISOString();
  const byDateRange = await api.functional.prefix.admin.contentReports.index(
    connection,
    {
      body: { reported_from: start, reported_to: end },
    },
  );
  typia.assert(byDateRange);
  TestValidator.predicate("reported_at 범위 필터")(
    byDateRange.data.every(
      (r) => r.reported_at >= start && r.reported_at <= end,
    ),
  );

  // 2-5. 페이지네이션: page 1, limit 1
  const paged = await api.functional.prefix.admin.contentReports.index(
    connection,
    {
      body: { page: 1, limit: 1 },
    },
  );
  typia.assert(paged);
  TestValidator.equals("page limit 1, 최대 1건")(paged.data.length)(
    Math.min(1, paged.pagination.records),
  );
  TestValidator.predicate("pagination 정보 일치")(
    paged.pagination.limit === 1 && paged.pagination.current === 1,
  );

  // 2-6. 조합: status + report_reason
  const combo = await api.functional.prefix.admin.contentReports.index(
    connection,
    {
      body: { status: "pending", report_reason: reportReasonA },
    },
  );
  typia.assert(combo);
  TestValidator.predicate("조합 필터: 모두 조건 만족")(
    combo.data.every(
      (r) => r.status === "pending" && r.report_reason === reportReasonA,
    ),
  );

  // 2-7. 결과 없음 필터
  const none = await api.functional.prefix.admin.contentReports.index(
    connection,
    {
      body: { report_reason: "DefinitelyNotAReason" },
    },
  );
  typia.assert(none);
  TestValidator.equals("결과 없으면 array 길이=0")(none.data.length)(0);

  // 2-8. 최대 page size(limit) 허용: 200
  const maxLimit = await api.functional.prefix.admin.contentReports.index(
    connection,
    {
      body: { limit: 200 },
    },
  );
  typia.assert(maxLimit);
  TestValidator.predicate("최대 200건 이하 반환")(maxLimit.data.length <= 200);

  // 2-9. 비정상 입력(page 음수): graceful error 확인
  await TestValidator.error("invalid page must fail")(async () => {
    await api.functional.prefix.admin.contentReports.index(connection, {
      body: { page: -1 },
    });
  });
}

