import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/ISuspension";
import type { IPageISuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageISuspension";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing suspensions with various filters, search, pagination, and error handling as admin.
 *
 * This scenario first creates two suspension records using the moderator API, each with distinct moderator_id, suspended_member_id, and suspension_reason. Then, it validates the admin endpoint by listing suspensions with:
 * 1. No filters (fetch all),
 * 2. Filtering by each field separately,
 * 3. Filtering by partial suspension_reason (search),
 * 4. Filtering by temporal (start/end) bounds,
 * 5. Pagination (page, limit),
 * 6. Sorting (if ordering is by created_at implicit),
 * 7. Invalid filter values (e.g., non-UUID in moderator_id),
 * 8. Unsupported filter field (should raise error or be ignored).
 *
 * Also validates that only admin/moderator roles can access, and that unauthorized tries (like regular user) receive forbidden errors.
 *
 * Steps:
 * 1. Moderator creates two suspension records with unique fields.
 * 2. Admin lists all suspensions, checks for both records.
 * 3. Filter by moderator_id, confirm only matching.
 * 4. Filter by suspended_member_id, confirm only matching.
 * 5. Search by partial suspension_reason text.
 * 6. Filter by suspension_started_at_from/to and suspension_ends_at_from/to.
 * 7. Use pagination (limit=1, page=2), check only one result per page and correct counts.
 * 8. Supply invalid value for moderator_id (fail case, error expected).
 * 9. Supply unsupported filter (fail case, error expected).
 * 10. Attempt as unauthorized user (fail case, error expected).
 */
export async function test_api_suspensions_test_list_suspensions_with_various_filters_pagination_and_search(connection: api.IConnection) {
  // Step 1: Moderator creates two suspension records
  const modId1 = typia.random<string & tags.Format<"uuid">>();
  const modId2 = typia.random<string & tags.Format<"uuid">>();
  const memberId1 = typia.random<string & tags.Format<"uuid">>();
  const memberId2 = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();
  const yesterday = new Date(now.getTime() - 86400000).toISOString();
  const tomorrow = new Date(now.getTime() + 86400000).toISOString();

  const suspension1 = await api.functional.prefix.moderator.suspensions.create(connection, {
    body: {
      moderator_id: modId1,
      suspended_member_id: memberId1,
      suspension_reason: "inappropriate content",
      suspension_started_at: yesterday,
      suspension_ends_at: tomorrow,
    }
  });
  typia.assert(suspension1);

  const suspension2 = await api.functional.prefix.moderator.suspensions.create(connection, {
    body: {
      moderator_id: modId2,
      suspended_member_id: memberId2,
      suspension_reason: "spam violation",
      suspension_started_at: now.toISOString(),
      suspension_ends_at: null,
    }
  });
  typia.assert(suspension2);

  // Step 2: Admin lists all suspensions
  const resAll = await api.functional.prefix.admin.suspensions.index(connection, { body: {} });
  typia.assert(resAll);
  TestValidator.predicate("contains both suspensions")(resAll.data.some(x => x.id === suspension1.id))
  TestValidator.predicate("contains both suspensions")(resAll.data.some(x => x.id === suspension2.id));

  // Step 3: Filter by moderator_id
  const resMod1 = await api.functional.prefix.admin.suspensions.index(connection, { body: { moderator_id: modId1 } });
  typia.assert(resMod1);
  TestValidator.predicate("filtered only by mod1")(resMod1.data.length >= 1 && resMod1.data.every(x => x.moderator_id === modId1));

  // Step 4: Filter by suspended_member_id
  const resMem2 = await api.functional.prefix.admin.suspensions.index(connection, { body: { suspended_member_id: memberId2 } });
  typia.assert(resMem2);
  TestValidator.predicate("filtered only by member2")(resMem2.data.length >= 1 && resMem2.data.every(x => x.suspended_member_id === memberId2));

  // Step 5: Search by partial suspension_reason
  const resSpam = await api.functional.prefix.admin.suspensions.index(connection, { body: { suspension_reason: "spam" } });
  typia.assert(resSpam);
  TestValidator.predicate("partial reason matches")(resSpam.data.some(x => x.suspension_reason.includes("spam")));

  // Step 6: Filter by started_at/ends_at bounds
  const resStartFrom = await api.functional.prefix.admin.suspensions.index(connection, { body: { suspension_started_at_from: yesterday } });
  typia.assert(resStartFrom);
  TestValidator.predicate("range filter matches")(resStartFrom.data.some(x => x.suspension_started_at >= yesterday));

  const resEndTo = await api.functional.prefix.admin.suspensions.index(connection, { body: { suspension_ends_at_to: tomorrow } });
  typia.assert(resEndTo);
  TestValidator.predicate("endAt to matches")(resEndTo.data.some(x => x.suspension_ends_at && x.suspension_ends_at <= tomorrow));

  // Step 7: Pagination limit=1, page=2
  const resPage2 = await api.functional.prefix.admin.suspensions.index(connection, { body: { limit: 1, page: 2 } });
  typia.assert(resPage2);
  TestValidator.equals("pagination per page")(resPage2.data.length)(1);
  TestValidator.predicate("pagination total")(resPage2.pagination.records >= 2);

  // Step 8: Invalid moderator_id fails
  await TestValidator.error("invalid uuid fails")(async () => {
    await api.functional.prefix.admin.suspensions.index(connection, { body: { moderator_id: "INVALID-UUID" } });
  });

  // Step 9: Unsupported filter field causes error or is ignored
  await TestValidator.error("unsupported filter")(async () => {
    await api.functional.prefix.admin.suspensions.index(connection, { body: { not_a_field: "abc" } as any });
  });

  // Step 10: Unauthorized user access fails (simulate by removing admin token if possible)
  // This part is placeholder as actual role switching logic depends on auth API, which is not available in current DTOs/functions.
}

