import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IMention";
import type { IPageIMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIMention";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { discussionboard_mentions } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboard_mentions";

/**
 * 관리자(운영자)가 멘션(언급) 내역 목록을 다양한 필터 조합(포스트, 멤버 별, 또는 기간별)로 조회할 수 있는지 확인합니다.
 *
 * [시나리오 개요 및 필요성]
 * - 여러 명의 멤버와 여러 개의 스레드 및 포스트를 미리 생성합니다.
 * - 각기 다른 멤버가 서로 다른 포스트에서 언급되도록 멘션 엔트리를 다수 생성합니다.
 * - 관리자는 다음과 같은 방식으로 멘션 목록을 필터/검색해야 합니다.
 *    1) 전체 멘션 목록(제한 없음) 검색
 *    2) 특정 포스트에서 발생한 멘션만 필터링
 *    3) 특정 멤버가 언급된 멘션만 필터링
 *    4) 특정 날짜 구간(예: 현재 시각 기준 ±1일) 안의 멘션만 필터링
 *    5) 위 조건들을 AND 연산자로 조합한 복합필터 검색
 *
 * [세부 단계]
 * 1. 테스트용 멤버 3명 생성
 * 2. 테스트용 스레드 2개 생성(동일 카테고리로)
 * 3. 각 스레드에 포스트 2~3개씩 작성(총 4~6개)
 * 4. 임의 조합으로 서로 다른 멤버가 엇갈리게 여러 포스트에서 언급되도록 멘션 생성
 * 5. 멘션 전체 목록 조회 후 생성된 엔트리들이 모두 존재하는지 확인
 * 6. 임의의 포스트 ID로 멘션 필터, 해당 포스트 ID만 등장하는지 확인
 * 7. 임의의 멤버 ID로 멘션 필터, 해당 멤버가 언급된 멘션만 추출되는지 확인
 * 8. 기간필터(예: 멘션 생성 직후 ±5초)로 조회, 일부 엔트리만 필터되는지 확인
 * 9. 포스트ID+멤버ID+기간 복합필터로 1개 엔트리만 얻어지는지 검증
 */
export async function test_api_mentions_test_admin_mentions_list_with_various_filters(
  connection: api.IConnection,
) {
  // 1. 테스트용 멤버 3명 생성
  const member1 = await api.functional.prefix.member.actors.members.create(connection, { body: { id: typia.random<string & tags.Format<"uuid">>(), created_at: new Date().toISOString() } });
  typia.assert(member1);
  const member2 = await api.functional.prefix.member.actors.members.create(connection, { body: { id: typia.random<string & tags.Format<"uuid">>(), created_at: new Date().toISOString() } });
  typia.assert(member2);
  const member3 = await api.functional.prefix.member.actors.members.create(connection, { body: { id: typia.random<string & tags.Format<"uuid">>(), created_at: new Date().toISOString() } });
  typia.assert(member3);

  // 2. 테스트용 스레드 2개 (동일 임의 카테고리로)
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();
  const thread1 = await api.functional.prefix.member.threadsPosts.threads.create(connection, { body: { discussionboard_category_id: categoryId, title: "E2E Thread 1", status: "active", is_pinned: false, is_locked: false, archived: false, created_at: now.toISOString(), updated_at: now.toISOString() } });
  typia.assert(thread1);
  const thread2 = await api.functional.prefix.member.threadsPosts.threads.create(connection, { body: { discussionboard_category_id: categoryId, title: "E2E Thread 2", status: "active", is_pinned: false, is_locked: false, archived: false, created_at: now.toISOString(), updated_at: now.toISOString() } });
  typia.assert(thread2);

  // 3. 각 스레드에 포스트 2개씩 작성
  const post1 = await api.functional.prefix.member.threadsPosts.posts.create(connection, { body: { discussionboard_thread_id: thread1.id, body: "Post 1 in Thread 1", is_edited: false } });
  typia.assert(post1);
  const post2 = await api.functional.prefix.member.threadsPosts.posts.create(connection, { body: { discussionboard_thread_id: thread1.id, body: "Post 2 in Thread 1", is_edited: false } });
  typia.assert(post2);
  const post3 = await api.functional.prefix.member.threadsPosts.posts.create(connection, { body: { discussionboard_thread_id: thread2.id, body: "Post 1 in Thread 2", is_edited: false } });
  typia.assert(post3);
  const post4 = await api.functional.prefix.member.threadsPosts.posts.create(connection, { body: { discussionboard_thread_id: thread2.id, body: "Post 2 in Thread 2", is_edited: false } });
  typia.assert(post4);

  // 4. 멤버-포스트 조합으로 다양한 멘션 생성
  const mention1 = await api.functional.prefix.member.mentions.create(connection, { body: { discussionboard_post_id: post1.id, mentioned_member_id: member2.id } });
  typia.assert(mention1);
  const mention2 = await api.functional.prefix.member.mentions.create(connection, { body: { discussionboard_post_id: post1.id, mentioned_member_id: member3.id } });
  typia.assert(mention2);
  const mention3 = await api.functional.prefix.member.mentions.create(connection, { body: { discussionboard_post_id: post2.id, mentioned_member_id: member1.id } });
  typia.assert(mention3);
  const mention4 = await api.functional.prefix.member.mentions.create(connection, { body: { discussionboard_post_id: post3.id, mentioned_member_id: member3.id } });
  typia.assert(mention4);
  const mention5 = await api.functional.prefix.member.mentions.create(connection, { body: { discussionboard_post_id: post4.id, mentioned_member_id: member1.id } });
  typia.assert(mention5);

  // 5. 전체 멘션 목록 (필터 없음)
  const resultAll = await api.functional.prefix.admin.mentions.index(connection, { body: { } });
  typia.assert(resultAll);
  const ids = [mention1.id, mention2.id, mention3.id, mention4.id, mention5.id];
  ids.forEach((id) => {
    const found = resultAll.data.find((m) => m.id === id);
    TestValidator.predicate(`전체 멘션 목록에 mention ${id} 존재 여부`)(!!found);
