import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostHistory";
import type { IPageIPostHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPostHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Verify that a moderator can access, audit, and filter post edit history for moderation purposes.
 *
 * This test covers the following business workflow:
 * 1. Register two users as members: one to create/edit posts, one to serve as moderator.
 * 2. As a member, create a new discussion thread (with minimal valid data).
 * 3. As the same member, create a post in the thread.
 * 4. Edit the post to produce at least one history snapshot.
 * 5. As a moderator, search for and list post edit histories using filter criteria:
 *    a. Filter by post_id (should yield all relevant edit records for that post)
 *    b. Filter by edit_member_id (should yield only records edited by the given member)
 *    c. Filter by edit_type (e.g., 'edit' action)
 *    d. Filter by created_at time window (should scope results appropriately)
 * 6. Assert that results contain the correct set, contain all required schema fields, and match expectations (including that edit bodies and reasons appear as appropriate for moderation workflows).
 */
export async function test_api_moderator_test_moderator_list_post_histories_for_audit_and_moderation(connection: api.IConnection) {
  // 1. Register a member (will be the post author/editor)
  const memberId: string = typia.random<string & tags.Format<"uuid">>();
  const memberCreatedAt: string = new Date().toISOString();
  const member = await api.functional.prefix.member.actors.members.create(connection, {
    body: {
      id: memberId,
      created_at: memberCreatedAt
    }
  });
  typia.assert(member);

  // Register a moderator (for search; assumes mod can login or connection context can switch)
  const moderatorId: string = typia.random<string & tags.Format<"uuid">>();
  const moderatorCreatedAt: string = new Date().toISOString();
  const moderator = await api.functional.prefix.member.actors.members.create(connection, {
    body: {
      id: moderatorId,
      created_at: moderatorCreatedAt
    }
  });
  typia.assert(moderator);

  // 2. As the member user, create a discussion thread
  const threadCategoryId: string = typia.random<string & tags.Format<"uuid">>();
  const threadTitle: string = RandomGenerator.paragraph()(1);
  const threadStatus = "active";
  const now = new Date().toISOString();
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(connection, {
    body: {
      // discussionboard_member_id should be ignored by API if set
      discussionboard_category_id: threadCategoryId,
      title: threadTitle,
      status: threadStatus,
      is_pinned: false,
      is_locked: false,
      archived: false,
      created_at: now,
      updated_at: now,
    },
  });
  typia.assert(thread);

  // 3. As member, create a post in the new thread
  const postBody = RandomGenerator.paragraph()(2);
  const post = await api.functional.prefix.member.threadsPosts.posts.create(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      body: postBody,
    },
  });
  typia.assert(post);

  // 4. Edit the post as member (flags edit and uses a new body, triggers a history snapshot)
  const editedBody = RandomGenerator.paragraph()(3);
  const editTime = new Date(new Date().getTime() + 1000).toISOString();
  const postUpdate = await api.functional.prefix.member.my.threadsPosts.posts.update(connection, {
    id: post.id,
    body: {
      body: editedBody,
      is_edited: true,
      updated_at: editTime,
    },
  });
  typia.assert(postUpdate);
  TestValidator.predicate("is_edited should be true")(postUpdate.is_edited === true);
  TestValidator.notEquals("postBody updated")(postUpdate.body)(post.body);

  // 5. As moderator, search for edit histories (simulate mod context)
  // a. By discussionboard_post_id
  const pageByPostId = await api.functional.prefix.moderator.threadsPosts.postHistories.index(connection, {
    body: {
      discussionboard_post_id: post.id,
    },
  });
  typia.assert(pageByPostId);
  TestValidator.predicate("Histories for post exist")(pageByPostId.data.length > 0);
  TestValidator.equals("All returned belong to post")(
    pageByPostId.data.every(hist => hist.discussionboard_post_id === post.id)
  )(true);

  // b. By edit_member_id (the member who edited, should match only relevant entries)
  const pageByEditor = await api.functional.prefix.moderator.threadsPosts.postHistories.index(connection, {
    body: {
      edit_member_id: member.id,
    },
  });
  typia.assert(pageByEditor);
  TestValidator.predicate("All found edited by member")(
    pageByEditor.data.every(hist => hist.edit_member_id === member.id)
  );
  // c. By edit_type; we expect at least one entry with 'edit'
  const pageByEditType = await api.functional.prefix.moderator.threadsPosts.postHistories.index(connection, {
    body: {
      edit_type: "edit"
    },
  });
  typia.assert(pageByEditType);
  TestValidator.predicate("Some with edit_type=edit")(
    pageByEditType.data.some(hist => hist.edit_type === "edit")
  );
  // d. By created_at window (very tight window for this test)
  const from = memberCreatedAt;
  const to = new Date(new Date(editTime).getTime() + 1000).toISOString();
  const pageByTime = await api.functional.prefix.moderator.threadsPosts.postHistories.index(connection, {
    body: {
      created_at_from: from,
      created_at_to: to,
    },
  });
  typia.assert(pageByTime);
  TestValidator.predicate("Histories within window")(
    pageByTime.data.every(hist => hist.created_at >= from && hist.created_at <= to)
  );
  // 6. Assert all expected fields returned
  for (const page of [pageByPostId, pageByEditor, pageByEditType, pageByTime]) {
    for (const hist of page.data) {
      TestValidator.predicate("Valid post history id")(typeof hist.id === "string" && hist.id.length > 0);
      TestValidator.equals("edit_member_id correct type")(typeof hist.edit_member_id)("string");
      TestValidator.predicate("created_at format")(!!Date.parse(hist.created_at));
      // edit_type field present
      TestValidator.equals("edit_type is present")(typeof hist.edit_type)("string");
    }
  }
}

