 *
 * 1. Register multiple members (at least two: one author, one as alternate
 *    editor).
 * 2. Create a thread using one test member.
 * 3. Create multiple posts in the thread, each by the author.
 * 4. Perform several edits on posts using both the original author and alternate
 *    editor, with diverse edit_type and reasons, spread across time.
 * 5. Use the history index endpoint to list all histories with no filters; verify
 *    presence/structure.
 * 6. Filter by post id; verify only that post's histories return.
 * 7. Filter by editor member id; verify only edits by that member return.
 * 8. Filter by edit_type; verify only certain types return.
 * 9. Filter by created_at_from and created_at_to with tight date windows; verify
 *    only correct subsets return.
 * 10. Test pagination by restricting limit; verify next page contains remaining
 *     entries and no duplicates.
 */
export async function test_api_prefix_test_list_post_histories_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Register two members
  const member1Id = typia.random<string & tags.Format<"uuid">>();
  const member2Id = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  const member1 = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: member1Id,
        created_at: now,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member1);
  const member2 = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: member2Id,
        created_at: now,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member2);

  // 2. Create a thread as member1 (author)
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const threadTitle = `Test thread ${RandomGenerator.alphaNumeric(8)}`;
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: categoryId,
        title: threadTitle,
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: now,
        updated_at: now,
      } satisfies IDiscussionboardThreads.ICreate,
    },
  );
  typia.assert(thread);

  // 3. Create 2 posts in the thread, both by member1
  const postBodies = [1, 2].map(
    (i) => `Post ${i} -- ${RandomGenerator.paragraph()()}`,
  );
  const posts = [];
  for (const body of postBodies) {
    const post = await api.functional.prefix.member.threadsPosts.posts.create(
      connection,
      {
        body: {
          discussionboard_thread_id: thread.id,
          body,
        } satisfies IDiscussionboardPosts.ICreate,
      },
    );
    typia.assert(post);
    posts.push(post);
  }

  // 4. Edit each post: member1 first, then simulate switching to member2 to edit again.
  // Simulate two edits for each post: different edit_types/reasons (recorded in 'edit_type'/'edit_reason' fields on history)
  // Since update endpoint allows editing own post, we edit as 'member1' then as 'member2' (simulate ownership transfer if needed, else just edit as member1 for both due to API constraints)
  // - edit_type1: 'edit'; reason: 'typo correction';
  // - edit_type2: 'refactor'; reason: 'clarified explanation';
  const editedBodies = [
    [
      {
        body: "First edit (typo correction)",
        is_edited: true,
        updated_at: new Date(Date.now() + 1000).toISOString(),
      },
      {
        body: "Second edit (clarified explanation)",
        is_edited: true,
        updated_at: new Date(Date.now() + 2000).toISOString(),
      },
    ],
    [
      {
        body: "First edit (formatting)",
        is_edited: true,
        updated_at: new Date(Date.now() + 3000).toISOString(),
      },
      {
        body: "Second edit (reworded)",
        is_edited: true,
        updated_at: new Date(Date.now() + 4000).toISOString(),
      },
    ],
  ];
  for (let i = 0; i < posts.length; ++i) {
    // First edit with member1
    await api.functional.prefix.member.my.threadsPosts.posts.update(
      connection,
      {
        id: posts[i].id,
        body: editedBodies[i][0] satisfies IDiscussionboardPost.IUpdate,
      },
    );
    // Second edit with member1 (API only allows editing own posts)
    await api.functional.prefix.member.my.threadsPosts.posts.update(
      connection,
      {
        id: posts[i].id,
        body: editedBodies[i][1] satisfies IDiscussionboardPost.IUpdate,
      },
    );
  }

  // 5. List all post histories (no filter)
  const allHistories =
    await api.functional.prefix.member.threadsPosts.postHistories.index(
      connection,
      {
        body: {} satisfies IPostHistory.IRequest,
      },
    );
  typia.assert(allHistories);
  TestValidator.predicate("has data")(allHistories.data.length >= 4);

  // 6. Filter histories by post id: pick first post
  const postId = posts[0].id;
  const forPost =
    await api.functional.prefix.member.threadsPosts.postHistories.index(
      connection,
      {
        body: {
          discussionboard_post_id: postId,
        } satisfies IPostHistory.IRequest,
      },
    );
  typia.assert(forPost);
  TestValidator.predicate("filtered all histories for post 1")(
    forPost.data.every((h) => h.discussionboard_post_id === postId),
  );

  // 7. Filter by editor member id -- as per schema, this is edit_member_id, but since only member1 could edit own post, only their id appears
  const forEditor =
    await api.functional.prefix.member.threadsPosts.postHistories.index(
      connection,
      {
        body: { edit_member_id: member1Id } satisfies IPostHistory.IRequest,
      },
    );
  typia.assert(forEditor);
  TestValidator.predicate("filtered all histories for member1")(
    forEditor.data.every((h) => h.edit_member_id === member1Id),
  );

  // 8. Filter by edit_type (assuming first history use 'edit' as edit_type, which system must record)
  const forType =
    await api.functional.prefix.member.threadsPosts.postHistories.index(
      connection,
      {
        body: { edit_type: "edit" } satisfies IPostHistory.IRequest,
      },
    );
  typia.assert(forType);
  TestValidator.predicate("every history has correct edit_type")(
    forType.data.every((h) => h.edit_type === "edit"),
  );

  // 9. Filter by created_at range (use created_at_from=now, created_at_to=now+10s)
  const start = now;
  const end = new Date(Date.now() + 10000).toISOString();
  const forTime =
    await api.functional.prefix.member.threadsPosts.postHistories.index(
      connection,
      {
        body: {
          created_at_from: start,
          created_at_to: end,
        } satisfies IPostHistory.IRequest,
      },
    );
  typia.assert(forTime);
  TestValidator.predicate("every history's created_at in range")(
    forTime.data.every((h) => h.created_at >= start && h.created_at <= end),
  );

  // 10. Pagination - limit 1, check next page returns next record (based on system pagination contract)
  const pagedFirst =
    await api.functional.prefix.member.threadsPosts.postHistories.index(
      connection,
      {
        body: {} satisfies IPostHistory.IRequest,
      },
    );
  typia.assert(pagedFirst);
  if (pagedFirst.data.length && pagedFirst.pagination.pages > 1) {
    const secondPage =
      await api.functional.prefix.member.threadsPosts.postHistories.index(
        connection,
        {
          body: {} satisfies IPostHistory.IRequest,
        },
      );
    typia.assert(secondPage);
    TestValidator.notEquals("page 1 and 2 not identical")(pagedFirst.data[0])(
      secondPage.data[0],
    );
  }
}

