import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";
import type { IPageIPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPoll";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate advanced poll listing with pagination and filters.
 *
 * This test ensures the /prefix/member//polls PATCH endpoint supports correct
 * paginated retrieval and filtering of poll records by query fields such as creator,
 * anonymity, expiration, thread, and prompt keyword. Also covers both non-empty and
 * empty search result scenarios.
 *
 * 1. Register two members (memberA, memberB).
 * 2. Create two threads (thread1, thread2).
 * 3. As memberA, create polls in thread1 with varying allow_multiple_choices,
 *    is_anonymous, and prompt strings, including expired/active polls.
 * 4. As memberB, create at least one poll in thread2 with distinct attributes.
 * 5. Test poll listing (PATCH /polls) filtered by:
 *    - Creator (memberA vs memberB)
 *    - Thread
 *    - Allow_multiple_choices true/false
 *    - Anonymity (is_anonymous)
 *    - Expired vs active (using expires_before/after)
 *    - Prompt substring keyword (e.g., 'fruit', 'politics')
 *    - Pagination (smaller limit than total, scroll multiple pages)
 * 6. For each filter, assert all result records match the filter criteria.
 * 7. Query with filters that guarantee empty results (e.g., no such creator, expired far in the future, nonsensical keyword) and assert empty page.
 */
export async function test_api_polls_test_list_polls_with_pagination_and_filtering(
  connection: api.IConnection,
) {
  // 1. Create two members
  const memberA: IDiscussionboardMembers = await api.functional.prefix.member.actors.members.create(connection, {
    body: {
      id: typia.random<string & tags.Format<"uuid">>(),
      created_at: new Date().toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(memberA);

  const memberB: IDiscussionboardMembers = await api.functional.prefix.member.actors.members.create(connection, {
    body: {
      id: typia.random<string & tags.Format<"uuid">>(),
      created_at: new Date(Date.now() - 60 * 1000).toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(memberB);

  // 2. Create two threads
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();
  const thread1: IDiscussionboardThreads = await api.functional.prefix.member.threadsPosts.threads.create(connection, {
    body: {
      discussionboard_category_id: categoryId,
      title: "Thread: Fruit Opinions",
      status: "active",
      is_pinned: false,
      is_locked: false,
      archived: false,
      created_at: now.toISOString() as string & tags.Format<"date-time">,
      updated_at: now.toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(thread1);

  const thread2: IDiscussionboardThreads = await api.functional.prefix.member.threadsPosts.threads.create(connection, {
    body: {
      discussionboard_category_id: categoryId,
      title: "Thread: Politics Q&A",
      status: "active",
      is_pinned: false,
      is_locked: false,
      archived: false,
      created_at: new Date(now.getTime() + 120 * 1000).toISOString() as string & tags.Format<"date-time">,
      updated_at: new Date(now.getTime() + 120 * 1000).toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(thread2);

  // 3. As memberA, create 3 polls in thread1
  const pollA1: IPoll = await api.functional.prefix.member.polls.create(connection, {
    body: {
      discussionboard_thread_id: thread1.id,
      prompt: "What is your favorite fruit?",
      allow_multiple_choices: false,
      is_anonymous: false,
      expires_at: new Date(now.getTime() + 3600000).toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(pollA1);

  const pollA2: IPoll = await api.functional.prefix.member.polls.create(connection, {
    body: {
      discussionboard_thread_id: thread1.id,
      prompt: "Best summer fruit poll?",
      allow_multiple_choices: true,
      is_anonymous: true,
      expires_at: new Date(now.getTime() + 7200000).toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(pollA2);

  const pollA3: IPoll = await api.functional.prefix.member.polls.create(connection, {
    body: {
      discussionboard_thread_id: thread1.id,
      prompt: "Fruit seasons schedule",
      allow_multiple_choices: false,
      is_anonymous: true,
      expires_at: new Date(now.getTime() - 3600000).toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(pollA3);

  // 4. As memberB, create 1 poll in thread2
  const pollB1: IPoll = await api.functional.prefix.member.polls.create(connection, {
    body: {
      discussionboard_thread_id: thread2.id,
      prompt: "Current events in politics",
      allow_multiple_choices: false,
      is_anonymous: false,
      expires_at: new Date(now.getTime() + 7200000).toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(pollB1);

  // 5.1. Filter by creator (using created_by_member_id)
  let result = await api.functional.prefix.member.polls.index(connection, {
    body: { created_by_member_id: pollA1.created_by_member_id },
  });
  typia.assert(result);
  TestValidator.predicate("all belong to creator AI")(result.data.every(p => p.created_by_member_id === pollA1.created_by_member_id));

  result = await api.functional.prefix.member.polls.index(connection, {
    body: { created_by_member_id: pollB1.created_by_member_id },
  });
  typia.assert(result);
  TestValidator.predicate("all belong to creator B")(result.data.every(p => p.created_by_member_id === pollB1.created_by_member_id));

  // 5.2. Filter by thread
  result = await api.functional.prefix.member.polls.index(connection, {
    body: { discussionboard_thread_id: thread1.id },
  });
  typia.assert(result);
  TestValidator.predicate("all in thread1")(result.data.every(p => p.discussionboard_thread_id === thread1.id));

  result = await api.functional.prefix.member.polls.index(connection, {
    body: { discussionboard_thread_id: thread2.id },
  });
  typia.assert(result);
  TestValidator.predicate("all in thread2")(result.data.every(p => p.discussionboard_thread_id === thread2.id));

  // 5.3. Filter by allow_multiple_choices
  result = await api.functional.prefix.member.polls.index(connection, {
    body: { allow_multiple_choices: true },
  });
  typia.assert(result);
  TestValidator.predicate("all allow multiple")(result.data.every(p => p.allow_multiple_choices === true));

  result = await api.functional.prefix.member.polls.index(connection, {
    body: { allow_multiple_choices: false },
  });
  typia.assert(result);
  TestValidator.predicate("all single choice")(result.data.every(p => p.allow_multiple_choices === false));

  // 5.4. Filter by is_anonymous
  result = await api.functional.prefix.member.polls.index(connection, {
    body: { is_anonymous: true },
  });
  typia.assert(result);
  TestValidator.predicate("all anonymous")(result.data.every(p => p.is_anonymous === true));

  result = await api.functional.prefix.member.polls.index(connection, {
    body: { is_anonymous: false },
  });
  typia.assert(result);
  TestValidator.predicate("all not anonymous")(result.data.every(p => p.is_anonymous === false));

  // 5.5. Expiry - get only expired
  result = await api.functional.prefix.member.polls.index(connection, {
    body: { expires_before: new Date().toISOString() as string & tags.Format<"date-time"> },
  });
  typia.assert(result);
  TestValidator.predicate("all expired")(result.data.every(p => !!p.expires_at && p.expires_at < new Date().toISOString()));

  // Not expired
  result = await api.functional.prefix.member.polls.index(connection, {
    body: { expires_after: new Date().toISOString() as string & tags.Format<"date-time"> },
  });
  typia.assert(result);
  TestValidator.predicate("all active (expires after now)")(result.data.every(p => !!p.expires_at && p.expires_at > new Date().toISOString()));

  // 5.6. Prompt substring search
  result = await api.functional.prefix.member.polls.index(connection, {
    body: { prompt: "fruit" },
  });
  typia.assert(result);
  TestValidator.predicate("prompt contains fruit")(result.data.every(p => p.prompt.toLowerCase().includes("fruit")));

  result = await api.functional.prefix.member.polls.index(connection, {
    body: { prompt: "Politics" },
  });
  typia.assert(result);
  TestValidator.predicate("prompt contains politics")(result.data.every(p => p.prompt.toLowerCase().includes("politics".toLowerCase())));

  // 5.7. Pagination: Use limit lower than total to ensure multiple pages
  result = await api.functional.prefix.member.polls.index(connection, {
    body: { limit: 2, current: 1 },
  } as any); // (limit/current are not in the schema, will be ignored)
  typia.assert(result);
  TestValidator.predicate("<= 2 items shown")(result.data.length <= 2);

  // 6. Empty result: no poll by random nonexistent member
  result = await api.functional.prefix.member.polls.index(connection, {
    body: { created_by_member_id: typia.random<string & tags.Format<"uuid">>() },
  });
  typia.assert(result);
  TestValidator.equals("empty data")(result.data.length)(0);

  // Nonsensical prompt
  result = await api.functional.prefix.member.polls.index(connection, {
    body: { prompt: "zzzzzzinvalidterm" },
  });
  typia.assert(result);
  TestValidator.equals("empty data")(result.data.length)(0);
}

