/**
 * Validate efficient pagination and sorting over large mention datasets as viewed by admin.
 *
 * This test simulates the following real-world admin workflow:
 *
 * 1. Generate a large volume of mention data (e.g., 35 mentions) by repeatedly creating members, threads, posts, and mentions.
 * 2. As admin, use the mentions listing API to implement and check pagination with limit and page (offset) parameters.
 * 3. Validate correct result ordering by created_at ascending and descending, ensure no duplicates, missing, or out-of-order mentions, and total count math across all pages.
 * 4. Check data integrity across page boundaries (last item of one page = first of next).
 * 5. Cover edge cases: first page, middle pages, and last page with fewer items than limit.
 *
 * Steps:
 * 1. Create members (at least 5 unique members)
 * 2. Create threads (at least 2 unique threads, using valid category UUIDs with randoms if not constrained)
 * 3. Create posts for those threads with valid member authors
 * 4. For a subset of the posts, create mentions tagging other members
 * 5. Accumulate all created mentions into an array for later validation
 * 6. As admin, use the mentions PATCH API to request with limit, page, and no filters, and check results. Repeat for multiple pages (e.g., limit=10 with 4 pages for 35 mentions)
 * 7. Compare each page's data to the accumulated original mentions array, in both ascending and descending order by created_at
 * 8. Verify that pagination metadata is correct
 * 9. Check integrity: No duplicates, missing, or out-of-order entries. The union of all page data should match all created mentions. (Check by id)
 */
export async function test_api_admin_test_admin_mentions_pagination_and_sorting_large_result_sets(
  connection: api.IConnection,
) {
  // 1. Generate members
  const memberCount = 5;
  const members: IDiscussionboardMembers[] = [];
  for (let i = 0; i < memberCount; ++i) {
    const memberCreate = {
      id: typia.random<string & tags.Format<"uuid">>(),
      created_at: new Date(Date.now() + i * 1000).toISOString(),
    } satisfies IDiscussionboardMembers.ICreate;
    const member = await api.functional.prefix.member.actors.members.create(connection, { body: memberCreate });
    typia.assert(member);
    members.push(member);
  }

  // 2. Generate threads (simulate 2 categories)
  const threadCount = 2;
  const threads: IDiscussionboardThreads[] = [];
  const categories = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>()
  ];
  for (let i = 0; i < threadCount; ++i) {
    const threadCreate = {
      discussionboard_category_id: categories[i],
      title: `Discussion Thread ${i + 1}`,
      status: "active",
      is_pinned: false,
      is_locked: false,
      archived: false,
      created_at: new Date(Date.now() + i * 1000 + 3333).toISOString(),
      updated_at: new Date(Date.now() + i * 1000 + 3333).toISOString(),
    } satisfies IDiscussionboardThreads.ICreate;
    const thread = await api.functional.prefix.member.threadsPosts.threads.create(connection, { body: threadCreate });
    typia.assert(thread);
    threads.push(thread);
  }

  // 3. Generate posts
  const postCount = 7;
  const posts: IDiscussionboardPosts[] = [];
  for (let i = 0; i < postCount; ++i) {
    const postCreate = {
      discussionboard_thread_id: threads[i % threads.length].id,
      body: `Post body ${i + 1}`,
      is_edited: false,
    } satisfies IDiscussionboardPosts.ICreate;
    // member selection (cycle authors)
    // note: discussionboard_member_id not client-supplied (server-attached)
    const post = await api.functional.prefix.member.threadsPosts.posts.create(connection, { body: postCreate });
    typia.assert(post);
    posts.push(post);
  }

  // 4. Generate mentions. Create MANY (e.g., 35) over the posts and members (excluding self-mention).
  const mentionCount = 35;
  const mentions: discussionboard_mentions[] = [];
  let idx = 0;
  for (let i = 0; i < mentionCount; ++i) {
    // pick a post (spread across posts)
    const post = posts[i % posts.length];
    // pick a member mentioned (cycle, but not the author)
    let member = members[(i + 1) % members.length];
    const mentionCreate = {
      discussionboard_post_id: post.id,
      mentioned_member_id: member.id,
    } satisfies discussionboard_mentions.ICreate;
    const mention = await api.functional.prefix.member.mentions.create(connection, { body: mentionCreate });
    typia.assert(mention);
    mentions.push(mention);
  }

  // 5. Try admin pagination with various limits/pages (test for 10 per page)
  const limit = 10;
  const totalPages = Math.ceil(mentionCount / limit);
  // Default ascending by created_at (simulate)
  let allPageItems: discussionboard_mentions[] = [];
  for (let page = 1; page <= totalPages; ++page) {
    const query = {
      page,
      limit,
    } satisfies IMention.IRequest;
    const res = await api.functional.prefix.admin.mentions.index(connection, { body: query });
    typia.assert(res);
    const { pagination, data } = res;
    // Validate pagination
    TestValidator.equals(`page ${page} - current`)(pagination.current)(page);
    TestValidator.equals(`page ${page} - limit`)(pagination.limit)(limit);
    TestValidator.equals(`page ${page} - total records`)(pagination.records)(mentionCount);
    // Validate page size
    if (page < totalPages)
      TestValidator.equals(`page ${page} - count`)(data.length)(limit);
    else
      TestValidator.equals(`page ${page} - count`)(data.length)(mentionCount - limit * (totalPages - 1));
    allPageItems = allPageItems.concat(data);
  }
  // 6. Check no missing/duplicate mentions and all info matches what was created
  const originalIds = mentions.map(m => m.id).sort();
  const pagedIds = allPageItems.map(m => m.id).sort();
  TestValidator.equals("paged union equals original mention set")(pagedIds)(originalIds);
