import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostHistory";
import type { IPageIPostHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPostHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate admin post history listing for compliance/audit workflows with advanced filters and pagination.
 *
 * This test simulates a realistic scenario where an admin needs to audit post histories:
 * - Multiple members are created to author and edit several posts across multiple threads.
 * - Each post is edited (one or more times) to generate a variety of history records, simulating real-world edit behavior by different users.
 * - As an admin, advanced search/filters for histories are exercised:
 *   1. Filter by post (discussionboard_post_id)
 *   2. Filter by editing member (edit_member_id)
 *   3. Filter by edit_type (e.g., 'edit')
 *   4. Filter by date range
 *   5. Test pagination in result sets
 * - For each filter or filter combination, assert that all returned IPostHistory records:
 *   - Match the requested filter(s)
 *   - Correctly fit the IPostHistory schema
 *   - Are within the expected paginated window
 *   - The total records/pagination information is consistent
 * - Business context: Platform compliance requires reliable and filterable post history for moderation, dispute resolution, and audit logging.
 */
export async function test_api_threadsPosts_test_admin_list_post_histories_with_compliance_filters(connection: api.IConnection) {
  // 1. Register multiple members
  const memberCount = 3;
  const members: IDiscussionboardMembers[] = [];
  for (let i = 0; i < memberCount; ++i) {
    const member = await api.functional.prefix.member.actors.members.create(connection, {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardMembers.ICreate,
    });
    typia.assert(member);
    members.push(member);
  }

  // 2. Create a thread (assign to first member for simplicity; category must be a UUID - random for test)
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(connection, {
    body: {
      discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: "Compliance & Audit Test Thread",
      status: "active",
      is_pinned: false,
      is_locked: false,
      archived: false,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    } satisfies IDiscussionboardThreads.ICreate,
  });
  typia.assert(thread);

  // 3. Seed several posts by different members
  const postCount = 6;
  const posts: IDiscussionboardPosts[] = [];
  for (let i = 0; i < postCount; ++i) {
    // Simulate posting as each member (cycling through)
    const currMember = members[i % members.length];
    const post = await api.functional.prefix.member.threadsPosts.posts.create(connection, {
      body: {
        discussionboard_thread_id: thread.id,
        body: `Test post ${i + 1} by member ${currMember.id}`,
        is_edited: false,
      } satisfies IDiscussionboardPosts.ICreate,
    });
    typia.assert(post);
    posts.push(post);
  }

  // 4. Perform multiple edits to generate diverse history records
  const editTypes = ["edit", "edit", "edit", "edit", "edit", "edit"];
  const editTimeStamps: string[] = [];
  for (let i = 0; i < posts.length; ++i) {
    // Each post gets at least one edit
    const updatedBody = `Edited body v2 for post ${posts[i].id}`;
    const editTime = new Date(Date.now() + i * 1000).toISOString();
    const updated = await api.functional.prefix.member.my.threadsPosts.posts.update(connection, {
      id: posts[i].id,
      body: {
        body: updatedBody,
        is_edited: true,
        updated_at: editTime,
      } satisfies IDiscussionboardPost.IUpdate,
    });
    typia.assert(updated);
    editTimeStamps.push(editTime);
  }

  // ---- Now admin: exercise post history search ----
  // 5.1 Filter by post
  const samplePost = posts[0];
  const byPostRes = await api.functional.prefix.admin.threadsPosts.postHistories.index(connection, {
    body: {
      discussionboard_post_id: samplePost.id,
    } satisfies IPostHistory.IRequest,
  });
  typia.assert(byPostRes);
  for (const hist of byPostRes.data) {
    TestValidator.equals("Filter by post ID")(hist.discussionboard_post_id)(samplePost.id);
  }
  // 5.2 Filter by member
  const sampleMember = members[1];
  const byMemberRes = await api.functional.prefix.admin.threadsPosts.postHistories.index(connection, {
    body: {
      edit_member_id: sampleMember.id,
    } satisfies IPostHistory.IRequest,
  });
  typia.assert(byMemberRes);
  for (const hist of byMemberRes.data) {
    TestValidator.equals("Filter by edit_member_id")(hist.edit_member_id)(sampleMember.id);
  }
  // 5.3 Filter by edit_type
  const byEditTypeRes = await api.functional.prefix.admin.threadsPosts.postHistories.index(connection, {
    body: {
      edit_type: "edit",
    } satisfies IPostHistory.IRequest,
  });
  typia.assert(byEditTypeRes);
  for (const hist of byEditTypeRes.data) {
    TestValidator.equals("Filter by edit_type")(hist.edit_type)("edit");
  }
  // 5.4 Date range filter
  // Use the earliest and latest editTime recorded
  const created_at_from = editTimeStamps[0];
  const created_at_to = editTimeStamps[editTimeStamps.length - 1];
  const byDateRes = await api.functional.prefix.admin.threadsPosts.postHistories.index(connection, {
    body: {
      created_at_from,
      created_at_to,
    } satisfies IPostHistory.IRequest,
  });
  typia.assert(byDateRes);
  for (const hist of byDateRes.data) {
    TestValidator.predicate("created_at between range")(hist.created_at >= created_at_from && hist.created_at <= created_at_to);
  }
  // 5.5 Pagination - request small limit for wide set
  const paginatedRes = await api.functional.prefix.admin.threadsPosts.postHistories.index(connection, {
    body: {
      // Request with no filter (all histories), but small limit for pagination
      // Assume API uses default current=1 and limit=2 if not supplied
    } satisfies IPostHistory.IRequest,
  });
  typia.assert(paginatedRes);
  const page = paginatedRes.pagination;
  TestValidator.predicate("pagination has expected structure")(typeof page.current === "number" && typeof page.limit === "number" && typeof page.records === "number" && typeof page.pages === "number");
  TestValidator.predicate("data length ≤ limit")(paginatedRes.data.length <= page.limit);
}

