import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";
import type { IDiscussionboardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCategory";

/**
 * Validate required field enforcement for discussion board category creation
 * (admin API).
 *
 * Ensures that omitting any required field (such as 'name',
 * 'discussionboard_section_id', 'order', or 'enabled') from the category
 * creation request causes the API to respond with a validation error and
 * prevents the creation of the record. All required field constraints are
 * verified.
 *
 * Steps:
 *
 * 1. Create a valid section to obtain a working section ID for use in the category
 *    payload (dependency).
 * 2. Attempt to create a discussion board category missing the 'name' field –
 *    should fail.
 * 3. Attempt to create a discussion board category missing the
 *    'discussionboard_section_id' field – should fail.
 * 4. Attempt to create a category missing both 'name' and
 *    'discussionboard_section_id' fields – should fail.
 * 5. Attempt to create a category missing 'order' – should fail.
 * 6. Attempt to create a category missing 'enabled' – should fail.
 */
export async function test_api_discussionboardCategories_test_create_discussionboard_category_with_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Create a valid section to use as the parent for categories
  const section =
    await api.functional.prefix.admin.discussionboardSections.create(
      connection,
      {
        body: {
          discussionboard_configuration_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          name: "Section for Category Field Validation",
          order: 10,
          enabled: true,
          description: "Section for negative tests",
        } satisfies IDiscussionboardSection.ICreate,
      },
    );
  typia.assert(section);

  // Prepare a fully valid category creation body for reference
  const validCategoryBody = {
    discussionboard_section_id: section.id,
    name: "Validation Category",
    order: 1,
    enabled: true,
    description: "Testing missing field behavior",
  } satisfies IDiscussionboardCategory.ICreate;

  // Utility to safely omit fields from a valid body
  const omit = <T extends object>(src: T, ...keys: (keyof T)[]) => {
    const copy = { ...src };
    for (const key of keys) delete copy[key];
    return copy;
  };

  // 2. Attempt: missing 'name'
  await TestValidator.error("missing name should fail")(
    async () =>
      await api.functional.prefix.admin.discussionboardCategories.create(
        connection,
        {
          // @ts-expect-error intentionally omitting required property; type checker will flag this
          body: omit(validCategoryBody, "name"),
        },
      ),
  );

  // 3. Attempt: missing 'discussionboard_section_id'
  await TestValidator.error("missing section ID should fail")(
    async () =>
      await api.functional.prefix.admin.discussionboardCategories.create(
        connection,
        {
          // @ts-expect-error purposely omit required field
          body: omit(validCategoryBody, "discussionboard_section_id"),
        },
      ),
  );

  // 4. Attempt: missing both 'name' and 'discussionboard_section_id'
  await TestValidator.error("missing both required fields should fail")(
    async () =>
      await api.functional.prefix.admin.discussionboardCategories.create(
        connection,
        {
          // @ts-expect-error purposely omit required fields
          body: omit(validCategoryBody, "name", "discussionboard_section_id"),
        },
      ),
  );

  // 5. Attempt: missing 'order' (required int)
  await TestValidator.error("missing order should fail")(
    async () =>
      await api.functional.prefix.admin.discussionboardCategories.create(
        connection,
        {
          // @ts-expect-error purposely omit required field
          body: omit(validCategoryBody, "order"),
        },
      ),
  );

  // 6. Attempt: missing 'enabled' (required boolean)
  await TestValidator.error("missing enabled should fail")(
    async () =>
      await api.functional.prefix.admin.discussionboardCategories.create(
        connection,
        {
          // @ts-expect-error purposely omit required field
          body: omit(validCategoryBody, "enabled"),
        },
      ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardGuests } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardGuests";
import type { IPageIDiscussionboardGuests } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardGuests";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * (회원 인증) discussionboard_guests 목록조회(PATCH) - 페이징, ID/타임스탬프 필터, 경계 및 실패 케이스 검증
 *
 * 1. 다양한 created_at, id 값을 가진 게스트 데이터 여러 개 생성
 * 2. 전체 목록을 페이징(limit/page) 옵션으로 조회, 반환 목록·페이징 정보 정확성 검증
 * 3. 임의 id, created_at 값 기반 필터 검색, 단일/none 결과 반환 정상 확인
 * 4. 페이지 개수만큼 limit==데이터수, limit>데이터수, limit<데이터수 상황 체크
 * 5. 빈 구간(존재하지 않는 id/created_at으로 요청) → 빈셋 반환
 * 6. 결과 스키마가 오직 id, created_at만 반환되는지 typia.assert로 확인
 * 7. 권한 없는 사용자로 목록조회 요청시 TestValidator.error로 거부 검증
 */
export async function test_api_prefix_member_actors_guests_test_list_guest_records_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // ----- Step 1: 다양한 created_at 및 id로 guest 데이터 여러개 생성 -----
  const GUEST_CNT = 6;
  const guests: IDiscussionboardGuests[] = [];
  const timestamps: string[] = [];
  for (let i = 0; i < GUEST_CNT; ++i) {
    // created_at 타임스탬프 분산: 최근 순서로 1분씩 차등
    const isoTimestamp = new Date(Date.now() - i * 60000).toISOString();
    const guest: IDiscussionboardGuests =
      await api.functional.prefix.member.actors.guests.create(connection, {
        body: {
          id: typia.random<string & tags.Format<"uuid">>(),
          created_at: isoTimestamp,
        } satisfies IDiscussionboardGuests.ICreate,
      });
    guests.push(guest);
    timestamps.push(isoTimestamp);
    typia.assert(guest);
  }
  // created_at 내림차순 정렬(최신~과거)
  guests.sort((a, b) => b.created_at.localeCompare(a.created_at));

  // ----- Step 2: 전체 목록 페이징 조회 (limit=3, page=1) -----
  const wholeListPage1 = await api.functional.prefix.member.actors.guests.index(
    connection,
    {
      body: {
        limit: 3 as number & tags.Type<"int32"> & tags.Minimum<1>,
        page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
      } satisfies IDiscussionboardGuests.IRequest,
    },
  );
  typia.assert(wholeListPage1);
  TestValidator.equals("page 1 count")(wholeListPage1.data.length)(3);
  // 최신순 정렬 가정: 첫 데이터가 방금 전 생성된 것인지 확인
  TestValidator.equals("first guest id matches latest")(
    wholeListPage1.data[0].id,
  )(guests[0].id);

  // ----- Step 3: 단일 ID 기준 검색 -----
  const targetId = guests[1].id;
  const singleIdRes = await api.functional.prefix.member.actors.guests.index(
    connection,
    {
      body: {
        id: targetId,
      },
    },
  );
  typia.assert(singleIdRes);
  TestValidator.equals("id 검색시 한명")(singleIdRes.data.length)(1);
  TestValidator.equals("id 일치")(singleIdRes.data[0].id)(targetId);

  // ----- Step 4: created_at 구간 검색 (가장 나중값~그보다 1분 전) -----
  const fromCreatedAt = guests[2].created_at;
  const atTimeRes = await api.functional.prefix.member.actors.guests.index(
    connection,
    {
      body: {
        created_at: fromCreatedAt,
      },
    },
  );
  typia.assert(atTimeRes);
  // created_at 정확 매치만 가능 (기간 탐색 X)
  TestValidator.equals("created_at 검색 건수")(
    atTimeRes.data.filter((d) => d.created_at === fromCreatedAt).length,
  )(atTimeRes.data.length);

  // ----- Step 5: 페이지 limit 경계 (limit=GUEST_CNT, limit>GUEST_CNT, limit=2) -----
  // limit = 전체 guest 갯수
  const allRangeRes = await api.functional.prefix.member.actors.guests.index(
    connection,
    {
      body: {
        limit: GUEST_CNT as number & tags.Type<"int32"> & tags.Minimum<1>,
        page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
      },
    },
  );
  typia.assert(allRangeRes);
  TestValidator.equals("all guests returned")(allRangeRes.data.length)(
    GUEST_CNT,
  );

  // limit > 전체 guest 갯수
  const overRangeRes = await api.functional.prefix.member.actors.guests.index(
    connection,
    {
      body: {
        limit: (GUEST_CNT + 5) as number & tags.Type<"int32"> & tags.Minimum<1>,
        page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
      },
    },
  );
  typia.assert(overRangeRes);
  TestValidator.equals("over limit still returns all")(
    overRangeRes.data.length,
  )(GUEST_CNT);

  // limit < 전체 guest
  const underRangeRes = await api.functional.prefix.member.actors.guests.index(
    connection,
    {
      body: {
        limit: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
        page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
      },
    },
  );
  typia.assert(underRangeRes);
  TestValidator.equals("under limit count")(underRangeRes.data.length)(2);

  // ----- Step 6: 빈 구간/조건 (존재하지 않는 id/created_at로 요청) -----
  const emptyIdRes = await api.functional.prefix.member.actors.guests.index(
    connection,
    {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
      },
    },
  );
  typia.assert(emptyIdRes);
  TestValidator.equals("no guest for random id")(emptyIdRes.data.length)(0);

  const emptyCreatedAtRes =
    await api.functional.prefix.member.actors.guests.index(connection, {
      body: {
        created_at: "2100-01-01T00:00:00.000Z" as string &
          tags.Format<"date-time">,
      },
    });
  typia.assert(emptyCreatedAtRes);
  TestValidator.equals("no guest for future created_at")(
    emptyCreatedAtRes.data.length,
  )(0);

  // ----- Step 7: 비인가자/게스트로 접근 시 거부되는지 확인 (권한체크) -----
  // 비회원 객체 context 사용(실제 테스트 환경 내 별도 connection 또는 연결 해제필요)
  // 여기서는 예시로, 실제로는 인증 해제/게스트 토큰 context 넘겨야 함
  const guestConn = {
    ...connection,
    headers: { ...connection.headers, Authorization: undefined },
  };
  await TestValidator.error("비회원 접근시 거부됨")(async () => {
    await api.functional.prefix.member.actors.guests.index(guestConn, {
      body: {},
    });
  });
  // 결과 반환 필드 체크 (id+created_at만 존재)
  const validateSchema = (guest: IDiscussionboardGuests) => {
    typia.assert(guest);
    if (
      Object.keys(guest).length !== 2 ||
      !("id" in guest) ||
      !("created_at" in guest)
    )
      throw new Error("반환 guest 스키마(id/created_at)만 존재해야 함");
  };
  guests.forEach(validateSchema);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardGuests } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardGuests";

/**
 * 다른 사용자가 소유하지 않은 guest(비회원 역할 추적) 레코드를 업데이트할 수 없는지 검증합니다.
 *
 * 1. A 회원 인증 상태에서 게스트 역할(guest record)을 생성합니다.
 * 2. B 회원(혹은 인증 없는 컨텍스트)으로 전환합니다.
 * 3. B 회원(또는 인증 없는 상태)에서 1단계에서 생성한 guest id로 업데이트 시도를 합니다.
 * 4. 이 시도는 반드시 권한 부족(Forbidden) 또는 비인가(Unauthorized) 오류로 실패해야 합니다.
 */
export async function test_api_discussionboard_guests_test_attempt_update_guest_record_by_non_owner_is_forbidden(
  connection: api.IConnection,
) {
  // 1. (A 회원) 게스트 레코드 생성
  const guest = await api.functional.prefix.member.actors.guests.create(
    connection,
    {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardGuests.ICreate,
    },
  );
  typia.assert(guest);

  // 2. (B 회원 또는 인증 없는 컨텍스트) 새 connection 객체 생성, 임의로 Authorization 제거 (실제 환경에선 별도 회원 인증 필요)
  const otherConnection: api.IConnection = {
    ...connection,
    headers: { ...connection.headers },
  };
  delete otherConnection.headers.Authorization;

  // 3. B 회원(혹은 인증 없는 상태)에서 타인 guest 업데이트 시도 → 무조건 오류 발생해야 함
  await TestValidator.error(
    "타인이 소유한 guest 레코드 업데이트 Forbidden/Unauthorized 되어야 함",
  )(async () => {
    await api.functional.prefix.member.my.actors.guests.update(
      otherConnection,
      {
        id: guest.id,
        body: {
          id: guest.id,
          created_at: new Date().toISOString(),
        } satisfies IDiscussionboardGuests.IUpdate,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";

/**
 * 토론 스레드 생성 API의 필수 필드 누락 시 유효성 검증 에러 발생을 확인합니다.
 *
 * - 'title'나 'discussionboard_category_id' 등 필수 필드를 일부 제거한 상태로 요청을 보내어, 서버가 올바른
 *   validation error를 반환하는지 검증합니다.
 * - 각 case별로 적절한 누락 field가 에러에 명시되는지를 확인합니다.
 *
 * 테스트 시나리오
 *
 * 1. 필수 필드 중 'title'을 누락하여 생성 시도 (category id, status, 등은 제공)
 * 2. 필수 필드 중 'discussionboard_category_id'를 누락하여 생성 시도 (title, status 등은 제공)
 * 3. 모든 필수 필드를 누락한(비어있는 body) 경우 생성 시도
 *
 * 각 경우별로 서버가 validation 에러(400 등)를 반환하며, 누락된 필드명이 에러 응답에 포함됨을 검증합니다.
 */
export async function test_api_prefix_member_threadsPosts_threads_test_create_thread_without_required_fields(
  connection: api.IConnection,
) {
  // 1. 'title' 필드 누락
  const bodyWithoutTitle = {
    discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(),
    status: "active",
    is_pinned: false,
    is_locked: false,
    archived: false,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  await TestValidator.error("title 없는 신규 스레드 생성 실패")(async () => {
    // @ts-expect-error 테스트 목적상 필드 누락 intentional
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: bodyWithoutTitle,
    });
  });

  // 2. 'discussionboard_category_id' 필드 누락
  const bodyWithoutCategory = {
    title: "테스트용 제목",
    status: "active",
    is_pinned: false,
    is_locked: false,
    archived: false,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
