import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";
import type { IPollVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPollVote";
import type { IPageIPollVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPollVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing/searching poll votes as an admin, covering filter, pagination,
 * and permission scenarios.
 *
 * This test verifies:
 *
 * 1. Filtering poll votes by valid schema fields (discussionboard_poll_id,
 *    voting_member_id, selected_option)
 * 2. Filtering with nonexistent poll id and multiple simultaneous criteria
 * 3. That only filter fields present in the schema are accepted (others rejected)
 * 4. Pagination and meta information presence
 * 5. Permissions: only admins can access, fail for member-level user
 * 6. Failures for invalid filter keys/types
 *
 * Steps performed:
 *
 * - Create a poll as a member
 * - Vote on the poll as a member
 * - List/search poll votes by various filters as admin
 * - Pagination and meta checks
 * - Various failure scenarios
 */
export async function test_api_prefix_admin_pollVotes_test_list_poll_votes_with_various_filters_and_permissions(
  connection: api.IConnection,
) {
  // 1. Create a poll (prerequisite)
  const poll = await api.functional.prefix.member.polls.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      prompt: "Best programming language?",
      allow_multiple_choices: false,
      is_anonymous: false,
      // Optionally test with and without expiration
      expires_at: null,
    },
  });
  typia.assert(poll);

  // 2. Add a vote (member)
  const vote = await api.functional.prefix.member.pollVotes.create(connection, {
    body: {
      discussionboard_poll_id: poll.id,
      selected_option: "TypeScript",
    },
  });
  typia.assert(vote);

  // 3. List all votes as admin (unfiltered)
  const votesAll = await api.functional.prefix.admin.pollVotes.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(votesAll);
  TestValidator.predicate("at least 1 poll vote present")(
    votesAll.data.length >= 1,
  );

  // 4. Filter by poll id
  const votesByPoll = await api.functional.prefix.admin.pollVotes.index(
    connection,
    {
      body: {
        discussionboard_poll_id: poll.id,
      },
    },
  );
  typia.assert(votesByPoll);
  TestValidator.predicate("all poll votes for expected poll id")(
    votesByPoll.data.every((d) => d.discussionboard_poll_id === poll.id),
  );

  // 5. Filter by voting_member_id
  const memberId = vote.voting_member_id;
  const votesByMember = await api.functional.prefix.admin.pollVotes.index(
    connection,
    {
      body: {
        voting_member_id: memberId,
      },
    },
  );
  typia.assert(votesByMember);
  TestValidator.predicate("at least one by correct voter id")(
    votesByMember.data.some((d) => d.voting_member_id === memberId),
  );

  // 6. Filter by selected_option
  const votesByOption = await api.functional.prefix.admin.pollVotes.index(
    connection,
    {
      body: {
        selected_option: "TypeScript",
      },
    },
  );
  typia.assert(votesByOption);
  TestValidator.predicate("at least one with selected_option")(
    votesByOption.data.some((d) => d.selected_option === "TypeScript"),
  );

  // 7. Filter by nonexistent poll id (should return empty)
  const votesByFakePoll = await api.functional.prefix.admin.pollVotes.index(
    connection,
    {
      body: {
        discussionboard_poll_id: typia.random<string & tags.Format<"uuid">>(),
      },
    },
  );
  typia.assert(votesByFakePoll);
  TestValidator.equals("empty data for nonexistent poll id")(
    votesByFakePoll.data.length,
  )(0);

  // 8. Filter by all fields (should match only the expected vote)
  const votesByAll = await api.functional.prefix.admin.pollVotes.index(
    connection,
    {
      body: {
        discussionboard_poll_id: poll.id,
        voting_member_id: memberId,
        selected_option: "TypeScript",
      },
    },
  );
  typia.assert(votesByAll);
  TestValidator.predicate("data exactly matches all filters")(
    votesByAll.data.every(
      (d) =>
        d.discussionboard_poll_id === poll.id &&
        d.voting_member_id === memberId &&
        d.selected_option === "TypeScript",
    ),
  );

  // 9. Pagination meta check (add another vote and check meta)
  await api.functional.prefix.member.pollVotes.create(connection, {
    body: {
      discussionboard_poll_id: poll.id,
      selected_option: "JavaScript",
    },
  });
  const votesPaged = await api.functional.prefix.admin.pollVotes.index(
    connection,
    {
      body: {
        discussionboard_poll_id: poll.id,
      },
    },
  );
  typia.assert(votesPaged);
  TestValidator.predicate("pagination meta present")(
    typeof votesPaged.pagination?.current === "number" &&
      typeof votesPaged.pagination?.limit === "number",
  );

  // 10. Permissions: should fail for member user (simulate if possible, else skip with comment)
  await TestValidator.error("fail for member-level (non-admin) user")(() =>
    api.functional.prefix.admin.pollVotes.index(connection, {
      body: {},
    }),
  );

  // 11. Failure: extra field in filter (should fail)
  await TestValidator.error("fail on invalid filter key")(() =>
    api.functional.prefix.admin.pollVotes.index(connection, {
      // @ts-expect-error: purposely invalid field
      body: { fake_key: 123 },
    }),
  );

  // 12. Failure: wrong type for filter value (should fail)
  await TestValidator.error("fail on wrong ftype")(() =>
    api.functional.prefix.admin.pollVotes.index(connection, {
      // @ts-expect-error: purposely invalid type
      body: { discussionboard_poll_id: 123 },
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";
import type { IPollVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPollVote";

/**
 * E2E test for creating a poll vote as an authenticated member, verifying
 * business and schema rules, error conditions, and proper authentication.
 *
 * Validates the poll voting workflow and error scenarios:
 *
 * 1. Create an active poll (dependency)
 * 2. Vote on the poll as authenticated member (success)
 * 3. Attempt to vote again (duplicate error)
 * 4. Vote on an expired poll (error)
 * 5. Vote on a nonexistent poll (error)
 * 6. Vote with invalid option (error)
 * 7. Attempt vote while unauthenticated (error)
 *
 * Due to API/DTO limitations, poll options are assumed as open input; in
 * production, these would be managed via additional domain/model logic.
 */
export async function test_api_prefix_member_pollvotes_test_create_poll_vote_with_valid_and_invalid_conditions(
  connection: api.IConnection,
) {
  // 1. Create active poll as dependency
  const pollCreateInput: IPoll.ICreate = {
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    prompt: "Sample prompt for poll",
    allow_multiple_choices: false,
    is_anonymous: false,
    expires_at: new Date(Date.now() + 86400000).toISOString(), // expires in 1 day
  };
  const poll = await api.functional.prefix.member.polls.create(connection, {
    body: pollCreateInput,
  });
  typia.assert(poll);

  // 2. Vote on the poll (success)
  const selected_option = "Option A";
  const voteInput = {
    discussionboard_poll_id: poll.id,
    selected_option,
  } satisfies IPollVote.ICreate;
  const vote = await api.functional.prefix.member.pollVotes.create(connection, {
    body: voteInput,
  });
  typia.assert(vote);
  TestValidator.equals("poll id matches")(vote.discussionboard_poll_id)(
    poll.id,
  );
  TestValidator.equals("selected_option matches")(vote.selected_option)(
    selected_option,
  );

  // 3. Attempt duplicate vote (should fail)
  await TestValidator.error("duplicate vote fails")(async () => {
    await api.functional.prefix.member.pollVotes.create(connection, {
      body: voteInput,
    });
  });

  // 4. Create a closed poll (expires in past)
  const closedPollInput: IPoll.ICreate = {
    ...pollCreateInput,
    prompt: "Closed poll for error test",
    expires_at: new Date(Date.now() - 3600000).toISOString(), // expired 1h ago
  };
  const closedPoll = await api.functional.prefix.member.polls.create(
    connection,
    {
      body: closedPollInput,
    },
  );
  typia.assert(closedPoll);
  await TestValidator.error("vote fails on closed/expired poll")(async () => {
    await api.functional.prefix.member.pollVotes.create(connection, {
      body: {
        discussionboard_poll_id: closedPoll.id,
        selected_option,
      } satisfies IPollVote.ICreate,
    });
  });

  // 5. Attempt to vote on a random invalid poll id
  await TestValidator.error("vote fails for nonexistent poll id")(async () => {
    await api.functional.prefix.member.pollVotes.create(connection, {
      body: {
        discussionboard_poll_id: typia.random<string & tags.Format<"uuid">>(),
        selected_option,
      } satisfies IPollVote.ICreate,
    });
  });

  // 6. Attempt to vote with invalid option
  await TestValidator.error("invalid selected_option fails")(async () => {
    await api.functional.prefix.member.pollVotes.create(connection, {
      body: {
        discussionboard_poll_id: poll.id,
        selected_option: "INVALID_OPTION_DOES_NOT_EXIST",
      } satisfies IPollVote.ICreate,
    });
  });

  // 7. Attempt unauthenticated vote (simulate by removing Authorization header)
  const unauthConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      Authorization: undefined,
    },
  };
  await TestValidator.error("unauthenticated vote fails")(async () => {
    await api.functional.prefix.member.pollVotes.create(unauthConnection, {
      body: voteInput,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";

/**
 * 관리자가 어떤 설문조사(poll)든 해당 poll의 ID로 상세 정보를 조회할 수 있는지 검증한다.
 *
 * 테스트 커버리지는 아래 모든 요소를 포함해야 한다:
 *
 * - 설문 프롬프트(prompt), 익명 여부(is_anonymous), 복수 선택 허용 여부(allow_multiple_choices), 만료
 *   기한(expires_at) 등 모든 스키마 필드의 정확한 반환 및 값 검증
 * - 여러 다른 회원이 생성한 설문조사 각각을 생성 → 각각의 상세 조회 (서로 다른 생성자, 쓰레드, 상태[만료/진행중])
 * - 만료된 설문조사와 진행중(만료되지 않은) 설문조사 모두 커버
 * - 관리자는 자신의 소유/비소유 또는 어떤 쓰레드의 poll이든 모두 조회 가능해야 함
 * - 존재하지 않는 설문 ID를 조회할 때 404 에러를 응답하는지 검증
 *
 * 테스트 진행 순서:
 *
 * 1. 여러 멤버가 참여하는 가상의 토론 스레드 여러 개 및 멤버 여러 명의 컨텍스트를 구성.
 * 2. 서로 다른 멤버가 각각의 스레드에서 다양한 유형(프롬프트/만료값/익명여부/복수선택 등 조합)으로 설문 poll을 생성.
 * 3. 각 생성된 poll의 id로 관리자로 상세조회를 반복. 반환 값이 생성 시 저장된 값과 정확하게 일치하는지 검증.
 * 4. 종료(만료된) poll과 진행중 poll 모두 커버(만료 필드에 과거/미래값 사용).
 * 5. 소유자가 아닌 poll도 조회 가능한지, 멀티 스레드 환경에서 제한 없는 접근성 확인.
 * 6. 존재하지 않는 임의의 poll id로 조회 요청 시 404 에러 발생 여부 확인.
 */
export async function test_api_prefix_admin_polls_test_view_poll_details_as_admin_access_all_cases(
  connection: api.IConnection,
) {
  // 1. 다양한 thread와 멤버, poll을 셋업한다
  //
  // (이 영역은 API만으로는 토론 스레드 및 멤버 생성이 불가하다고 판단, 가정된 UUID/random 값 활용)
  // 임의 thread와 member id
  const threadIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const memberIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];

  // 2. 다양한 케이스로 poll 여러 개 생성 (prompt/익명/복수선택/만료 조합)
  // 만료 이미 지난 poll (expired), 앞으로의 poll (active) 각각 1개씩 포함
  const now = new Date();
  const expiredAtPast = new Date(
    now.getTime() - 1000 * 60 * 60 * 24,
  ).toISOString(); // 하루 전
  const expiresAtFuture = new Date(
    now.getTime() + 1000 * 60 * 60 * 24,
  ).toISOString(); // 하루 후

  const pollInputs: api.IPoll.ICreate[] = [
    // 1) active, non-anonymous, single choice
    {
      discussionboard_thread_id: threadIds[0],
      prompt: "진행중 비익명 단일선택 설문",
      allow_multiple_choices: false,
      is_anonymous: false,
      expires_at: expiresAtFuture,
    },
    // 2) expired, anonymous, multi-choice
    {
      discussionboard_thread_id: threadIds[1],
      prompt: "만료됨 익명 복수선택 설문",
      allow_multiple_choices: true,
      is_anonymous: true,
      expires_at: expiredAtPast,
    },
    // 3) no expiration
    {
      discussionboard_thread_id: threadIds[0],
      prompt: "만료기한 없음",
      allow_multiple_choices: false,
      is_anonymous: true,
      expires_at: undefined,
    },
  ];

  // 각각 멤버 컨텍스트(가상의 로그인 세션이 필요하다고 간주, 단 여기서는 member_id만 임의 할당. 실제 상황에서는 세션전환 코드 필요)
  const createdPolls: api.IPoll[] = [];
  for (let i = 0; i < pollInputs.length; i++) {
    // (실제 테스트 환경에서는 로그인/세션 분리 필요하나, 여기서는 API 접근만 가능하니 member_id 임의 주입 가정)
    // poll 생성
    const poll = await api.functional.prefix.member.polls.create(connection, {
      body: pollInputs[i],
    });
    typia.assert(poll);
    createdPolls.push(poll);
  }

  // 3. 각 poll을 admin 권한으로 상세조회 및 값 검증
  for (const poll of createdPolls) {
    const output = await api.functional.prefix.admin.polls.at(connection, {
      id: poll.id,
    });
    typia.assert(output);
    // 각 필드의 일치 여부 검증
    TestValidator.equals("poll.prompt")(output.prompt)(poll.prompt);
    TestValidator.equals("poll.allow_multiple_choices")(
      output.allow_multiple_choices,
    )(poll.allow_multiple_choices);
    TestValidator.equals("poll.is_anonymous")(output.is_anonymous)(
      poll.is_anonymous,
    );
    TestValidator.equals("poll.expires_at")(output.expires_at)(poll.expires_at);
    TestValidator.equals("poll.discussionboard_thread_id")(
      output.discussionboard_thread_id,
    )(poll.discussionboard_thread_id);
  }

  // 4. 존재하지 않는 id로 404 에러 검증
  await TestValidator.error("존재하지 않는 poll id 조회 시 404 반환")(
    async () => {
      await api.functional.prefix.admin.polls.at(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

