  // 5. 빈 객체 전달(스키마 상 허용, 실제 비즈니스 로직 동작에 따라 결과 달라질 수 있음)
  // validation error가 반드시 발생하지 않을 수 있음(필터 없는 전체검색 허용 시)
  // 에러가 나면 확인, 에러가 안나면 허용되는 정책으로 간주
  try {
    await api.functional.prefix.member.postReactions.index(connection, {
      body: {},
    });
  } catch {
    // 에러 발생시 정상
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationAction";
import type { IPageIModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIModerationAction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 어드민/관리자가 다양한 필터 및 페이지네이션 조건으로 moderation action 목록을 검색하고, 각 필터 조건/페이징 적용 결과의
 * 일관성, 권한 제한이 제대로 동작하는지 검증합니다.
 *
 * 검증 시나리오:
 *
 * 1. 관리자 권한으로 moderation action 전체 목록 요청(기본 페이지)
 * 2. 존재하는 moderator_id, report_id, action_type, affected_post_id,
 *    affected_member_id 등을 필터링하여 결과 key 값이 일치하는지 개별 검증
 * 3. 임의 비존재 키(uuid) 등으로 빈 결과 정상 처리 확인
 * 4. 타임스탬프 범위(action_timestamp_from/to) 필터 테스트
 * 5. 페이지네이션(page/limit 조절) - 다수 페이지 반복 요청 간 중복 없는지, 수량·페이지 수 일치 확인
 * 6. 과도한 page 번호·최대 limit 등 엣지 케이스
 * 7. (권한 케이스) 비인증/비어드민 context로 접근 시 접근거부(403 등) 처리 확인
 */
export async function test_api_moderationActions_test_list_moderation_actions_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 어드민 기본 전체 목록 요청 (기본값)
  const allActions = await api.functional.prefix.admin.moderationActions.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(allActions);
  TestValidator.predicate("page 1 result count")(
    allActions.data.length <= allActions.pagination.limit,
  );

  // 2. 필터별로 1개씩 집어서 상세 필터 검증 (최초 응답에서 id값 pick)
  if (allActions.data.length) {
    const sample = allActions.data[0];
    // moderator_id 필터
    const byModerator =
      await api.functional.prefix.admin.moderationActions.index(connection, {
        body: { moderator_id: sample.moderator_id },
      });
    typia.assert(byModerator);
    TestValidator.predicate("filtered by moderator id correct")(
      byModerator.data.every((v) => v.moderator_id === sample.moderator_id),
    );

    // report_id
    if (sample.report_id) {
      const byReport =
        await api.functional.prefix.admin.moderationActions.index(connection, {
          body: { report_id: sample.report_id },
        });
      typia.assert(byReport);
      TestValidator.predicate("filtered by report id correct")(
        byReport.data.every((v) => v.report_id === sample.report_id),
      );
    }

    // action_type
    const byType = await api.functional.prefix.admin.moderationActions.index(
      connection,
      {
        body: { action_type: sample.action_type },
      },
    );
    typia.assert(byType);
    TestValidator.predicate("filtered by action type correct")(
      byType.data.every((v) => v.action_type === sample.action_type),
    );

    // affected_post_id
    if (sample.affected_post_id) {
      const byPost = await api.functional.prefix.admin.moderationActions.index(
        connection,
        {
          body: { affected_post_id: sample.affected_post_id },
        },
      );
      typia.assert(byPost);
      TestValidator.predicate("filtered by affected post id correct")(
        byPost.data.every(
          (v) => v.affected_post_id === sample.affected_post_id,
        ),
      );
    }

    // affected_member_id
    if (sample.affected_member_id) {
      const byMember =
        await api.functional.prefix.admin.moderationActions.index(connection, {
          body: { affected_member_id: sample.affected_member_id },
        });
      typia.assert(byMember);
      TestValidator.predicate("filtered by affected member id correct")(
        byMember.data.every(
          (v) => v.affected_member_id === sample.affected_member_id,
        ),
      );
    }

    // action_timestamp 범위 (단일 값 기준 window +/-1min)
    const ts = sample.action_timestamp;
    const from = new Date(new Date(ts).getTime() - 60_000).toISOString();
    const to = new Date(new Date(ts).getTime() + 60_000).toISOString();
    const byTs = await api.functional.prefix.admin.moderationActions.index(
      connection,
      {
        body: {
          action_timestamp_from: from,
          action_timestamp_to: to,
        },
      },
    );
    typia.assert(byTs);
    // filtering: result내 모든 timestamp가 범위 내에 있는지 체크
    TestValidator.predicate("filtered by timestamp range correct")(
      byTs.data.every(
        (v) => v.action_timestamp >= from && v.action_timestamp <= to,
      ),
    );
  }

  // 3. 임의 무작위 uuid (존재하지 않을 만한 값)로 빈 목록 나오는지 확인
  const randomUuid = typia.random<string & tags.Format<"uuid">>();
  // moderator_id
  const none1 = await api.functional.prefix.admin.moderationActions.index(
    connection,
    {
      body: { moderator_id: randomUuid },
    },
  );
  typia.assert(none1);
  TestValidator.equals("empty with random moderator_id")(none1.data.length)(0);
  // report_id
  const none2 = await api.functional.prefix.admin.moderationActions.index(
    connection,
    {
      body: { report_id: randomUuid },
    },
  );
  typia.assert(none2);
  TestValidator.equals("empty with random report_id")(none2.data.length)(0);

  // 4. 페이지네이션: 페이지 수/limit 조합, 데이터 중복 없는지 확인
  if (allActions.pagination.pages > 1) {
    const limit = 2;
    const page1 = await api.functional.prefix.admin.moderationActions.index(
      connection,
      {
        body: {
          page: 1,
          limit,
        },
      },
    );
    const page2 = await api.functional.prefix.admin.moderationActions.index(
      connection,
      {
        body: {
          page: 2,
          limit,
        },
      },
    );
    typia.assert(page1);
    typia.assert(page2);
    // 두 페이지가 중복된 데이터 id를 갖지 않아야 한다
    const idsPage1 = page1.data.map((a) => a.id);
    const idsPage2 = page2.data.map((a) => a.id);
    TestValidator.predicate("no overlap between pages")(
      idsPage1.every((id) => !idsPage2.includes(id)),
    );
  }

  // 5. 과도한/최대 page, limit 테스트 (limit 200, page: 큰 수)
  const outOfBoundPage =
    await api.functional.prefix.admin.moderationActions.index(connection, {
      body: {
        page: 9999,
        limit: 200,
      },
    });
  typia.assert(outOfBoundPage);
  TestValidator.equals("empty for high page")(outOfBoundPage.data.length)(0);

  // 6. (권한 거부) 관리자 권한 없는 connection/context에서는 403 등 에러 발생해야 함
  // 실제로는 connection을 로그인/권한별로 분리해서 테스트(여기선 가정/자동화환경 대응)
  if (typeof globalThis.createNonAdminConnection === "function") {
    const nonAdminConn: api.IConnection =
      await globalThis.createNonAdminConnection();
    await TestValidator.error("non-admin should be forbidden")(async () => {
      await api.functional.prefix.admin.moderationActions.index(nonAdminConn, {
        body: {},
      });
    });
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardIncidentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardIncidentReport";

/**
 * Validate API rejects creation of an incident report when required fields are
 * missing.
 *
 * This test ensures the server enforces validation for all mandatory fields
 * when admin attempts to create an incident report.
 *
 * Steps:
 *
 * 1. For each required field (incident_code, status, description, created_at,
 *    updated_at):
 *
 *    - Attempt to create an incident report while omitting that field.
 *    - Assert that the API responds with a validation error and does not create the
 *         resource.
 * 2. Additionally, verify that omitting the optional field (reporter_id) does NOT
 *    produce an error.
 */
export async function test_api_prefix_admin_policyAudit_incidentReports_test_fail_to_create_incident_report_with_missing_required_field(
  connection: api.IConnection,
) {
  // List of required fields for creation
  const REQUIRED_FIELDS = [
    "incident_code",
    "status",
    "description",
    "created_at",
    "updated_at",
  ];

  // Construct a valid incident report creation payload
  const validInput = {
    incident_code: "INCIDENT-20240729-001",
    status: "OPEN",
    description: "Negative test for required field validation",
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };

  // For each required field, omit it and expect validation error from API
  for (const missingField of REQUIRED_FIELDS) {
    const invalidInput = { ...validInput };
    delete invalidInput[missingField];
    await TestValidator.error(`missing required field: ${missingField}`)(
      async () => {
        await api.functional.prefix.admin.policyAudit.incidentReports.create(
          connection,
          {
            // It's safe for negative-path validation to cast as any.
            body: invalidInput as any,
          },
        );
      },
    );
  }

  // Edge case: reporter_id is optional, so omitting it should succeed
  const noReporterIdInput = { ...validInput };
  // Intentionally do NOT include reporter_id field
  const result =
    await api.functional.prefix.admin.policyAudit.incidentReports.create(
      connection,
      { body: noReporterIdInput },
    );
  typia.assert(result);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";
import type { IModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationAction";

/**
 * Test that attempting to update a moderation action with invalid or
 * undocumented fields is rejected.
 *
 * This ensures that the admin update endpoint at PUT
 * /prefix/admin//my/moderationActions/{id} strictly enforces its schema by
 * rejecting:
 *
 * 1. Extraneous fields not present in the update DTO
 * 2. Forbidden attempts (e.g., trying to update the 'id' field) and leaves the
 *    record unchanged after failed attempts.
 *
 * Steps:
 *
 * 1. Assign admin privileges to a test user so we can use the admin API.
 * 2. As an admin, create a valid moderation action.
 * 3. Attempt a valid update of the moderation action (should succeed to confirm
 *    baseline behavior).
 * 4. Attempt to update the moderation action with an extra, undocumented property
 *    (should fail with validation error).
 * 5. Attempt to update the moderation action by including a forbidden schema
 *    property (e.g., id).
 * 6. After failed attempts, confirm the moderation action state is unchanged (as
 *    far as possible via test invariants).
 */
export async function test_api_prefix_test_admin_update_moderation_action_with_invalid_fields_rejected(
  connection: api.IConnection,
) {
  // 1. Assign admin privileges to a test user
  const adminId = typia.random<string & tags.Format<"uuid">>();
  const adminAssign = await api.functional.prefix.admin.actors.admins.create(
    connection,
    {
      body: {
        id: adminId,
        created_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(adminAssign);

  // 2. As admin, create a moderation action to update
  const moderationAction =
    await api.functional.prefix.admin.moderationActions.create(connection, {
      body: {
        moderator_id: adminId,
        action_type: "warned",
        action_description: "Initial moderation action.",
        action_timestamp: new Date().toISOString(),
      },
    });
  typia.assert(moderationAction);

  // 3. Valid update should succeed
  const validUpdate: IModerationAction.IUpdate = {
    action_type: "warned",
    action_description: "Updated moderation action.",
    action_timestamp: new Date().toISOString(),
    affected_post_id: moderationAction.affected_post_id ?? null,
    affected_member_id: moderationAction.affected_member_id ?? null,
    report_id: moderationAction.report_id ?? null,
  };
  const updated = await api.functional.prefix.admin.my.moderationActions.update(
    connection,
    {
      id: moderationAction.id,
      body: validUpdate,
    },
  );
  typia.assert(updated);
  TestValidator.equals("action_type updated")(updated.action_type)(
    validUpdate.action_type,
  );
  TestValidator.equals("action_description updated")(
    updated.action_description,
  )(validUpdate.action_description);

  // 4. Update with undocumented extra property should fail
  await TestValidator.error("update fails with undocumented field")(
    // @ts-expect-error - extra property added on purpose for test
    () =>
      api.functional.prefix.admin.my.moderationActions.update(connection, {
        id: moderationAction.id,
        body: {
          ...validUpdate,
          not_in_schema: "illegal field",
        },
      }),
  );

  // 5. Update with forbidden/id property should fail
  await TestValidator.error("update fails with forbidden id property")(
    // @ts-expect-error - id is forbidden in update schema
    () =>
      api.functional.prefix.admin.my.moderationActions.update(connection, {
        id: moderationAction.id,
        body: {
          ...validUpdate,
          id: "00000000-0000-0000-0000-000000000000",
        },
      }),
  );
  // 6. No GET endpoint available, so we rely on the last known-good state from prior assertions
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
