import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAuditLog";
import type { IPageIDiscussionboardAuditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardAuditLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test: Admin audit log listing (pagination, filtering, and authorization).
 *
 * This test covers:
 *
 * 1. Retrieving paginated audit log list with default and filtered options.
 * 2. Verifying all returned data strictly matches schema fields.
 * 3. Testing filters for action_type, actor_id, and created_at.
 * 4. Testing pagination parameters (page/limit) in request and response.
 * 5. Confirming endpoint is admin-only (unauthorized access is denied).
 *
 * Steps:
 *
 * - Default listing (no filters)
 * - Filter by action_type (if available)
 * - Filter by actor_id (if any log has an actor_id)
 * - Filter by created_at range (using one log's created_at, if data present)
 * - Pagination test (page and limit)
 * - Access control test (simulate unauthorized/non-admin request)
 */
export async function test_api_prefix_admin_policyAudit_auditLogs_index(
  connection: api.IConnection,
) {
  // 1. Admin retrieves audit logs: default paginated list, no filters
  const responseDefault =
    await api.functional.prefix.admin.policyAudit.auditLogs.index(connection, {
      body: {},
    });
  typia.assert(responseDefault);
  // Validate page info (should default to page 1)
  TestValidator.equals("pagination current is 1")(
    responseDefault.pagination.current,
  )(1);
  TestValidator.predicate("audit log list is array")(
    Array.isArray(responseDefault.data),
  );
  // Check fields of returned audit log records
  if (responseDefault.data.length > 0) {
    for (const log of responseDefault.data) {
      TestValidator.predicate("audit log id is uuid-like")(
        typeof log.id === "string" && /[0-9a-fA-F-]{36}/.test(log.id),
      );
      TestValidator.predicate("action_type is present and string")(
        typeof log.action_type === "string",
      );
      TestValidator.predicate("description is present and string")(
        typeof log.description === "string",
      );
      TestValidator.predicate("created_at is date-time string")(
        typeof log.created_at === "string" && /T/.test(log.created_at),
      );
      TestValidator.predicate("actor_id and target_id fields optional or null")(
        !("actor_id" in log) ||
          log.actor_id === null ||
          typeof log.actor_id === "string",
      );
      TestValidator.predicate("actor_id and target_id fields optional or null")(
        !("target_id" in log) ||
          log.target_id === null ||
          typeof log.target_id === "string",
      );
    }
  }

  // 2. Filter by action_type if any present
  if (responseDefault.data.length > 0) {
    const typeToFilter = responseDefault.data[0].action_type;
    const filteredByType =
      await api.functional.prefix.admin.policyAudit.auditLogs.index(
        connection,
        {
          body: { action_type: typeToFilter },
        },
      );
    typia.assert(filteredByType);
    for (const log of filteredByType.data) {
      TestValidator.equals("action_type matches filter")(log.action_type)(
        typeToFilter,
      );
    }
  }

  // 3. Filter by actor_id (only if log with actor_id present)
  const logWithActor = responseDefault.data.find((l) => l.actor_id);
  if (logWithActor && logWithActor.actor_id) {
    const filteredByActor =
      await api.functional.prefix.admin.policyAudit.auditLogs.index(
        connection,
        {
          body: { actor_id: logWithActor.actor_id },
        },
      );
    typia.assert(filteredByActor);
    for (const log of filteredByActor.data) {
      TestValidator.equals("actor_id matches filter")(log.actor_id)(
        logWithActor.actor_id,
      );
    }
  }

  // 4. Filter by created_at range (of one log)
  if (responseDefault.data.length > 0) {
    const log = responseDefault.data[0];
    const createdAt = log.created_at;
    const filteredByCreated =
      await api.functional.prefix.admin.policyAudit.auditLogs.index(
        connection,
        {
          body: { created_from: createdAt, created_to: createdAt },
        },
      );
    typia.assert(filteredByCreated);
    for (const item of filteredByCreated.data) {
      TestValidator.equals("created_at matches filter")(item.created_at)(
        createdAt,
      );
    }
  }

  // 5. Pagination check: page 2 with limit 1
  const responsePage2 =
    await api.functional.prefix.admin.policyAudit.auditLogs.index(connection, {
      body: { page: 2, limit: 1 },
    });
  typia.assert(responsePage2);
  TestValidator.equals("pagination page is 2")(
    responsePage2.pagination.current,
  )(2);
  TestValidator.equals("pagination limit is 1")(responsePage2.pagination.limit)(
    1,
  );

  // 6. Access control: Unauthorized user is denied
  const unauthConnection = {
    ...connection,
    headers: { ...connection.headers, Authorization: undefined },
  };
  await TestValidator.error("should not allow access without admin token")(
    async () => {
      await api.functional.prefix.admin.policyAudit.auditLogs.index(
        unauthConnection,
        { body: {} },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
