import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardIncidentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardIncidentReport";

/**
 * Validate incident report deletion permissions: unauthorized role.
 *
 * This test attempts to delete an incident report as an unauthorized actor
 * (such as a member or guest). It ensures the operation is forbidden,
 * confirming only moderators and admins can perform deletion.
 *
 * Steps:
 *
 * 1. Moderator creates a valid incident report
 * 2. Switch to a non-privileged (guest or member) connection
 * 3. Attempt to delete the report as unauthorized user
 * 4. Operation must be rejected (forbidden error)
 */
export async function test_api_prefix_moderator_policyAudit_incidentReports_test_delete_incident_report_unauthorized_role(
  connection: api.IConnection,
) {
  // 1. Moderator creates an incident report
  // (Assume the connection passed here is authorized as a moderator or admin for setup)
  const incidentReport =
    await api.functional.prefix.moderator.policyAudit.incidentReports.create(
