import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPlatformPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPlatformPolicy";
import type { IPageIDiscussionboardPlatformPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardPlatformPolicy";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test retrieval of platform policies with various filters, sorting, and
 * pagination as admin.
 *
 * This test covers listing platform policy documents using the admin endpoint
 * with a range of filter scenarios:
 *
 * 1. Fetch all without filters (default fetch), confirming all test-created items
 *    appear
 * 2. Filter by title substring (partial match)
 * 3. Filter by is_active=false (fetch inactives only)
 * 4. Validate API returns results in updated_at descending order (implicit sort
 *    check)
 * 5. Verify pagination boundaries by checking first and last policy presence
 * 6. Try invalid filter key (should error)
 * 7. Confirm empty filter object returns all
 *
 * Every response is validated for only official schema fields, with no extras
 * or omissions. The test creates three diverse policies for robust assertion
 * conditions and ensures that schema and business requirements (such as
 * admin-only access and correct filtering behavior) are enforced. Pagination
 * checks are limited to available DTO features.
 */
export async function test_api_prefix_admin_policyAudit_platformPolicies_test_list_platform_policies_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a diverse set of platform policy records (3 test cases)
  const now = new Date();
  const policies = [
    // Policy 1: Active, "Alpha Policy"
    await api.functional.prefix.admin.policyAudit.platformPolicies.create(
      connection,
      {
        body: {
          policy_code: "ALPHA123",
          title: "Alpha Policy",
          policy_text: "Alpha content.",
          is_active: true,
        },
      },
    ),
    // Policy 2: Active, "Beta Guidelines"
    await api.functional.prefix.admin.policyAudit.platformPolicies.create(
      connection,
      {
        body: {
          policy_code: "BETA456",
          title: "Beta Guidelines",
          policy_text: "Beta content.",
          is_active: true,
        },
      },
    ),
    // Policy 3: Inactive, "Inactive Gamma"
    await api.functional.prefix.admin.policyAudit.platformPolicies.create(
      connection,
      {
        body: {
          policy_code: "GAMMA789",
          title: "Inactive Gamma",
          policy_text: "Gamma content.",
          is_active: false,
        },
      },
    ),
  ];
  for (const p of policies) typia.assert(p);

  // (1) Default fetch: no filters, retrieve all
  const res_all =
    await api.functional.prefix.admin.policyAudit.platformPolicies.index(
      connection,
      { body: {} },
    );
  typia.assert(res_all);
  TestValidator.predicate("all created records are present")(
    policies.every((seed) =>
      res_all.data.some(
        (r) =>
          r.id === seed.id &&
          r.title === seed.title &&
          r.policy_code === seed.policy_code,
      ),
    ),
  );

  // (2) Filter by title substring: "Alpha" (matches Policy 1 only)
  const res_title =
    await api.functional.prefix.admin.policyAudit.platformPolicies.index(
      connection,
      {
        body: { title: "Alpha" },
      },
    );
  typia.assert(res_title);
  TestValidator.predicate("only 'Alpha Policy' is returned")(
    res_title.data.every((r) => r.title.includes("Alpha")) &&
      res_title.data.length === 1,
  );

  // (3) Filter by is_active: false
  const res_inactive =
    await api.functional.prefix.admin.policyAudit.platformPolicies.index(
      connection,
      {
        body: { is_active: false },
      },
    );
  typia.assert(res_inactive);
  TestValidator.predicate("all results have is_active=false")(
    res_inactive.data.every((r) => r.is_active === false),
  );
  TestValidator.predicate("Inactive Gamma is present")(
    res_inactive.data.some((r) => r.id === policies[2].id),
  );

  // (4) Sorting by updated_at descending (implicit check, since no explicit sort param exposed)
  const res_sorted =
    await api.functional.prefix.admin.policyAudit.platformPolicies.index(
      connection,
      { body: {} },
    );
  typia.assert(res_sorted);
  const apiSortedIds = res_sorted.data.map((r) => r.id);
  const localSortedIds = [...res_sorted.data]
    .sort((a, b) => b.updated_at.localeCompare(a.updated_at))
    .map((r) => r.id);
  TestValidator.equals("descending updated_at order")(apiSortedIds)(
    localSortedIds,
  );

  // (5) Pagination boundaries – check first and last record match test seeds
  if (res_all.data.length >= 2) {
    TestValidator.equals("first record matches first policy")(
      res_all.data[0].id,
    )(policies[0].id);
    TestValidator.equals("last record matches last policy")(
      res_all.data[res_all.data.length - 1].id,
    )(policies[policies.length - 1].id);
  }

  // (6) Invalid filter key (should error)
  await TestValidator.error("unexpected filter key is rejected")(async () => {
    // @ts-expect-error intentionally wrong filter property; compile-time block
    // is required to silence type error for this test line only
    await api.functional.prefix.admin.policyAudit.platformPolicies.index(
      connection,
      {
        body: { made_up_key: "not allowed" },
      },
    );
  });

  // (7) Empty filter object should return all
  const res_empty =
    await api.functional.prefix.admin.policyAudit.platformPolicies.index(
      connection,
      { body: {} },
    );
  typia.assert(res_empty);
  TestValidator.predicate("empty filter returns all")(
    res_empty.data.length >= policies.length,
  );

  // Schema property compliance: items must have only official defined fields
  const expectedFields = [
    "id",
    "policy_code",
    "title",
    "policy_text",
    "is_active",
    "published_at",
    "updated_at",
  ];
  for (const result of [
    res_all,
    res_title,
    res_inactive,
    res_sorted,
    res_empty,
  ]) {
    for (const item of result.data) {
      TestValidator.predicate("item has only official schema fields")(
        Object.keys(item).sort().join() === expectedFields.sort().join(),
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { discussionboard_notifications } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboard_notifications";

/**
 * Validate that updating a notification which does not exist or is not owned by
 * the member correctly results in an error.
 *
 * This test covers two critical error scenarios:
 *
 * 1. The notificationId does not exist (random UUID): The system should return a
 *    not found error.
 * 2. The notificationId exists but is owned by a different member: The system
 *    should return a forbidden (or not found) error.
 *
 * Test steps:
 *
 * 1. Register two members (member1, member2) for permission boundary validation.
 * 2. As member1, create a notification.
 * 3. As member2: a. Attempt to update a notification with a random UUID (not
 *    exist). Confirm error. b. Attempt to update member1's notification (should
 *    fail, not owned by member2). Confirm error.
 *
 * Note: Member context-switching is simulated via header mutation
 * ('x-discussionboard-member-id'), because explicit authentication endpoints
 * are not present in this API set. This approach is used for test isolation and
 * simulating real-world user contexts. After test, restores original connection
 * headers to ensure other tests are not impacted.
 */
export async function test_api_prefix_member_my_discussionboardNotifications_test_update_notification_for_nonexistent_or_unowned_notification(
  connection: api.IConnection,
) {
  // -- Store original headers to restore later for test isolation
  const prevHeaders = { ...connection.headers };
  try {
    // 1. Register two members
    const memberId1: string & tags.Format<"uuid"> = typia.random<
      string & tags.Format<"uuid">
    >();
    const member1 = await api.functional.prefix.member.actors.members.create(
      connection,
      {
        body: {
          id: memberId1,
          created_at: new Date().toISOString() as string &
            tags.Format<"date-time">,
        },
      },
    );
    typia.assert(member1);

    const memberId2: string & tags.Format<"uuid"> = typia.random<
      string & tags.Format<"uuid">
    >();
    const member2 = await api.functional.prefix.member.actors.members.create(
      connection,
      {
        body: {
          id: memberId2,
          created_at: new Date().toISOString() as string &
            tags.Format<"date-time">,
        },
      },
    );
    typia.assert(member2);

    // 2. As member1, create a notification (simulate login context as member1)
    Object.assign(connection.headers, {
      "x-discussionboard-member-id": memberId1,
    });
    const notification =
      await api.functional.prefix.member.my.discussionboardNotifications.create(
        connection,
        {
          body: {
            type: "mention",
            title: "Test notification",
            body: "This notification is for member1.",
            url: "/thread/123",
            opened: false,
          },
        },
      );
    typia.assert(notification);

    // 3. Pretend to become member2 (simulate login context switch)
    Object.assign(connection.headers, {
      "x-discussionboard-member-id": memberId2,
    });

    // 3.a. Attempt to update notification with a random UUID (does not exist)
    await TestValidator.error("updating nonexistent notification throws error")(
      () =>
        api.functional.prefix.member.my.discussionboardNotifications.update(
          connection,
          {
            notificationId: typia.random<string & tags.Format<"uuid">>(),
            body: {
              title: "Attempt update",
            },
          },
        ),
    );

    // 3.b. Attempt to update member1's notification as member2 (should fail)
    await TestValidator.error("cannot update another member's notification")(
      () =>
        api.functional.prefix.member.my.discussionboardNotifications.update(
          connection,
          {
            notificationId: notification.id,
            body: {
              title: "Hacked update by member2",
            },
          },
        ),
    );
  } finally {
    // Restore headers to keep test environment clean
    Object.assign(connection.headers, prevHeaders);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/ISuspension";
import type { IPageISuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageISuspension";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test list and filter of suspensions including pagination for moderator
 * access.
 *
 * This test ensures the following:
 *
 * 1. Multiple suspension records exist, created via dependency.
 * 2. Suspensions can be retrieved using combinations of filters (moderator_id,
 *    suspended_member_id, suspension reason, and suspension date window).
 * 3. Pagination parameters are handled correctly.
 * 4. Results reflect accurate filtering, not just all suspensions.
 * 5. Only authorized users (e.g., moderators) can access these endpoints.
 *
 * Steps:
 *
 * 1. Create 4+ suspension records with varying moderator_id, suspended_member_id,
 *    and time ranges.
 * 2. Retrieve all suspensions with no filters and capture total count.
 * 3. Filter by 1 moderator_id: result should only include suspensions by that
 *    moderator.
 * 4. Filter by suspended_member_id: result should only include suspensions for
 *    that member.
 * 5. Use both filters together—AND logic should hold in result.
 * 6. Use suspension window filters to capture partial subsets.
 * 7. Use pagination (limit=2) and check pagination fields and results for page 1
 *    and page 2.
 * 8. Attempt to call as a non-moderator (simulate with a connection having no
 *    moderator role), assert access is denied (if RBAC enforced).
 */
export async function test_api_prefix_moderator_suspensions_test_list_suspensions_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // (1) Create multiple diverse suspension records for robust testing
  const suspensionInputs = ArrayUtil.repeat(4)(() => {
    return {
      moderator_id: typia.random<string & tags.Format<"uuid">>(),
      suspended_member_id: typia.random<string & tags.Format<"uuid">>(),
      suspension_reason: RandomGenerator.paragraph()(),
      suspension_started_at: RandomGenerator.pick([
        new Date(Date.now() - 86400000 * 5).toISOString(), // 5 days ago
        new Date(Date.now() - 86400000 * 2).toISOString(), // 2 days ago
        new Date(Date.now()).toISOString(), // now
      ]),
      suspension_ends_at: RandomGenerator.pick([
        null,
        new Date(Date.now() + 86400000 * 5).toISOString(), // 5 days later
      ]),
    } satisfies ISuspension.ICreate;
  });
  const suspensions: ISuspension[] = [];
  for (const input of suspensionInputs) {
    const suspension = await api.functional.prefix.moderator.suspensions.create(
      connection,
      { body: input },
    );
    typia.assert(suspension);
    suspensions.push(suspension);
  }
  // (2) Get all suspensions (no filters)
  const allPage = await api.functional.prefix.moderator.suspensions.index(
    connection,
    { body: {} },
  );
  typia.assert(allPage);
  TestValidator.predicate("should return at least all created suspensions")(
    allPage.data.length >= suspensions.length,
  );

  // (3) Filter by moderator_id
  const byModerator = await api.functional.prefix.moderator.suspensions.index(
    connection,
    { body: { moderator_id: suspensions[0].moderator_id } },
  );
  typia.assert(byModerator);
  TestValidator.predicate("all results have moderator_id")(
    byModerator.data.every(
      (r) => r.moderator_id === suspensions[0].moderator_id,
    ),
  );

  // (4) Filter by suspended_member_id
  const byMember = await api.functional.prefix.moderator.suspensions.index(
    connection,
    { body: { suspended_member_id: suspensions[1].suspended_member_id } },
  );
  typia.assert(byMember);
  TestValidator.predicate("all results have suspended_member_id")(
    byMember.data.every(
      (r) => r.suspended_member_id === suspensions[1].suspended_member_id,
    ),
  );

  // (5) Filter by both moderator_id and suspended_member_id
  const byBoth = await api.functional.prefix.moderator.suspensions.index(
    connection,
    {
      body: {
        moderator_id: suspensions[2].moderator_id,
        suspended_member_id: suspensions[2].suspended_member_id,
      },
    },
  );
  typia.assert(byBoth);
  TestValidator.predicate(
    "all results match both moderator_id and suspended_member_id",
  )(
    byBoth.data.every(
      (r) =>
        r.moderator_id === suspensions[2].moderator_id &&
        r.suspended_member_id === suspensions[2].suspended_member_id,
    ),
  );

  // (6) Filter by suspension_started_at_from and suspension_started_at_to
  const dates = suspensions.map((s) => s.suspension_started_at).sort();
  const fromDate = dates[0];
  const toDate = dates[dates.length - 1];
  const byWindow = await api.functional.prefix.moderator.suspensions.index(
    connection,
    {
      body: {
        suspension_started_at_from: fromDate,
        suspension_started_at_to: toDate,
      },
    },
  );
  typia.assert(byWindow);
  TestValidator.predicate("all within date window")(
    byWindow.data.every(
      (r) =>
        r.suspension_started_at >= fromDate &&
        r.suspension_started_at <= toDate,
    ),
  );

  // (7) Pagination check: limit=2
  const paged1 = await api.functional.prefix.moderator.suspensions.index(
    connection,
    { body: { limit: 2, page: 1 } },
  );
  typia.assert(paged1);
  TestValidator.equals("page 1 limit")(paged1.data.length)(2);
  TestValidator.equals("pagination current page")(paged1.pagination.current)(1);

  const paged2 = await api.functional.prefix.moderator.suspensions.index(
    connection,
    { body: { limit: 2, page: 2 } },
  );
  typia.assert(paged2);
  TestValidator.equals("page 2 limit")(paged2.data.length)(2);
  TestValidator.equals("pagination current page")(paged2.pagination.current)(2);

  // (8) RBAC: Try with non-moderator/no auth context
  // This depends on actual implementation: here we simulate by deleting token
  // (connection.headers.Authorization removal). If producing HttpError, assert error is thrown
  const clonedConn: api.IConnection = {
    ...connection,
    headers: { ...connection.headers },
  };
  delete clonedConn.headers.Authorization;
  await TestValidator.error("Should fail for non-moderator")(async () => {
    await api.functional.prefix.moderator.suspensions.index(clonedConn, {
      body: {},
    });
  });
}

