  const createBody = {
    appeal_code: `APPEAL-${now.replace(/[-:.TZ]/g, "")}-001`,
    status: "PENDING",
    appellant_id: testMemberId,
    incident_id: null,
    outcome: null,
    created_at: now,
    updated_at: now,
