 */
export async function test_api_moderator_test_moderator_mentions_pagination_and_search(
  connection: api.IConnection,
) {
  // 1. 여러 명의 멤버 생성
  const MEMBER_COUNT = 5;
  const members = await ArrayUtil.asyncRepeat(MEMBER_COUNT)(async () => {
    const input = {
      id: typia.random<string & tags.Format<"uuid">>(),
      created_at: new Date().toISOString() as string & tags.Format<"date-time">,
    } satisfies IDiscussionboardMembers.ICreate;
    const member = await api.functional.prefix.member.actors.members.create(
      connection,
      { body: input },
    );
    typia.assert(member);
    return member;
  });

  // 2. 각 멤버마다 하나씩 스레드 생성
  const threads = await ArrayUtil.asyncMap(members)(async (member) => {
    const input = {
      discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      status: "active",
      is_pinned: false,
      is_locked: false,
      archived: false,
      created_at: new Date().toISOString() as string & tags.Format<"date-time">,
      updated_at: new Date().toISOString() as string & tags.Format<"date-time">,
    } satisfies IDiscussionboardThreads.ICreate;
    const thread =
      await api.functional.prefix.member.threadsPosts.threads.create(
        connection,
        { body: input },
      );
    typia.assert(thread);
    return thread;
  });

  // 3. 각 스레드마다 여러 개의 게시글(Post) 생성
  const POSTS_PER_THREAD = 5;
  let allPosts: IDiscussionboardPosts[] = [];
  for (const thread of threads) {
    const posts = await ArrayUtil.asyncRepeat(POSTS_PER_THREAD)(async () => {
      const input = {
        discussionboard_thread_id: thread.id,
        body: RandomGenerator.content()(1, 2),
        is_edited: false,
      } satisfies IDiscussionboardPosts.ICreate;
      const post = await api.functional.prefix.member.threadsPosts.posts.create(
        connection,
        { body: input },
      );
      typia.assert(post);
      return post;
    });
    allPosts.push(...posts);
  }

  // 4. 게시글들의 여러 위치에 멤버들을 랜덤 멘션
  const MENTION_COUNT = 20;
  const mentions = await ArrayUtil.asyncRepeat(MENTION_COUNT)(async () => {
    const randomPost = RandomGenerator.pick(allPosts);
    const randomMember = RandomGenerator.pick(members);
    const input = {
      discussionboard_post_id: randomPost.id,
      mentioned_member_id: randomMember.id,
    } satisfies discussionboard_mentions.ICreate;
    const mention = await api.functional.prefix.member.mentions.create(
      connection,
      { body: input },
    );
    typia.assert(mention);
    return mention;
  });

  // 5. (1) limit/page 조합 기본 검색
  let response = await api.functional.prefix.moderator.mentions.index(
    connection,
    {
      body: {
        limit: 5,
        page: 1,
      },
    },
  );
  typia.assert(response);
  TestValidator.equals("limit 사용됨")(response.pagination.limit)(5);
  TestValidator.equals("1페이지")(response.pagination.current)(1);
  TestValidator.predicate("최대 5건 이하")(response.data.length <= 5);

  // (2) 멤버 id로 검색
  response = await api.functional.prefix.moderator.mentions.index(connection, {
    body: {
      mentioned_member_id: members[0].id,
    },
  });
  typia.assert(response);
  TestValidator.predicate("모든 멘션은 해당 멤버")(
    response.data.every((item) => item.mentioned_member_id === members[0].id),
  );

  // (3) 게시글 id로 검색
  response = await api.functional.prefix.moderator.mentions.index(connection, {
    body: {
      discussionboard_post_id: allPosts[0].id,
    },
  });
  typia.assert(response);
  TestValidator.predicate("모든 멘션은 해당 post id")(
    response.data.every(
      (item) => item.discussionboard_post_id === allPosts[0].id,
    ),
  );

  // (4) 기간(created_at) 조건 검색
  const now = new Date();
  const hourAgo = new Date(now.getTime() - 3600 * 1000);
  response = await api.functional.prefix.moderator.mentions.index(connection, {
    body: {
      created_at_from: hourAgo.toISOString() as string &
        tags.Format<"date-time">,
      created_at_to: now.toISOString() as string & tags.Format<"date-time">,
    },
  });
  typia.assert(response);
  TestValidator.predicate("생성일 범위 내")(
    response.data.every((item) => {
      const created = new Date(item.created_at).getTime();
      return created >= hourAgo.getTime() && created <= now.getTime();
    }),
  );

  // (5) 아주 높은 page number로 비어있는 데이터 확인 (에지)
  response = await api.functional.prefix.moderator.mentions.index(connection, {
    body: {
      limit: 5,
      page: 999,
    },
  });
  typia.assert(response);
  TestValidator.equals("아무 데이터 없음")(response.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardFilter } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFilter";
import type { IPageIDiscussionboardFilter } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardFilter";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IVoid } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoid";

/**
 * Test listing of own saved discussion board filters (search, privacy,
 * pagination, soft-delete).
 *
 * Validates that:
 *
 * - Only filters belonging to the authenticated member are returned
 * - Can search/filter own filters by name and is_public
 * - Soft-deleted filters (deleted_at != null) are excluded unless explicitly
 *   queried
 * - Pagination and sorting work (current, limit, total count match expectations)
 * - Filters from other users are never included (privacy protection)
 *
 * Steps:
 *
 * 1. Create several filters for this user (some private, some public, with unique
 *    names)
 * 2. Update one filter's name/is_public value
 * 3. Soft-delete one filter
 * 4. List all filters: verify only active (deleted_at = null), all are own filters
 * 5. Search by updated name; search by is_public; confirm correct filters are
 *    returned
 * 6. List soft-deleted filters (by filtering on deleted_at), confirm only deleted
 *    ones show
 * 7. Test pagination by retrieving result pages and checking
 *    membership/disjointness
 * 8. Ensure no filters from other users leak into any result
 */
export async function test_api_prefix_member_my_filters_test_list_own_saved_filters_with_various_filters(
  connection: api.IConnection,
) {
  // 1. Create filters: several public/private, with unique names
  const filterCount = 5;
  const uniqueBase = RandomGenerator.alphabets(8) + Date.now();
  const createdFilters: IDiscussionboardFilter[] = [];
  for (let i = 0; i < filterCount; ++i) {
    const filter = await api.functional.prefix.member.my.filters.create(
      connection,
      {
        body: {
          name: `${uniqueBase}_name_${i}`,
          definition: JSON.stringify({ q: i }),
          is_public: i % 2 === 0,
        } satisfies IDiscussionboardFilter.ICreate,
      },
    );
    typia.assert(filter);
    createdFilters.push(filter);
  }

  // 2. Update the first filter's name and is_public
  const updatedFilterId = createdFilters[0].id;
  const updatedName = `${uniqueBase}_updated_name`;
  const updatedIsPublic = false;
  const updatedFilter = await api.functional.prefix.member.my.filters.update(
    connection,
    {
      filterId: updatedFilterId,
      body: {
        name: updatedName,
        is_public: updatedIsPublic,
      } satisfies IDiscussionboardFilter.IUpdate,
    },
  );
  typia.assert(updatedFilter);
  TestValidator.equals("name updated")(updatedFilter.name)(updatedName);
  TestValidator.equals("is_public updated")(updatedFilter.is_public)(
    updatedIsPublic,
  );

  // 3. Soft-delete the second filter
  const deletedFilterId = createdFilters[1].id;
  await api.functional.prefix.member.my.filters.erase(connection, {
    filterId: deletedFilterId,
  });

  // 4. List all filters: should only include not-soft-deleted, all owned by user
  const allPage = await api.functional.prefix.member.my.filters.index(
    connection,
    {
      body: {} satisfies IDiscussionboardFilter.IRequest,
    },
  );
  typia.assert(allPage);
  for (const f of allPage.data) {
    TestValidator.equals("owned by user")(f.discussionboard_member_id)(
      updatedFilter.discussionboard_member_id,
    );
    TestValidator.equals("not soft-deleted")(f.deleted_at)(null);
  }
  // No deleted filter should appear
  TestValidator.predicate("deleted filter not in data")(
    allPage.data.every((f) => f.id !== deletedFilterId),
  );

  // 5. Search by name (updated)
  const nameSearchPage = await api.functional.prefix.member.my.filters.index(
    connection,
    {
      body: { name: updatedName } satisfies IDiscussionboardFilter.IRequest,
    },
  );
  typia.assert(nameSearchPage);
  TestValidator.predicate("name search is exact")(
    nameSearchPage.data.every((f) => f.name === updatedName),
  );

  //    Filter by is_public (true)
  const publicPage = await api.functional.prefix.member.my.filters.index(
    connection,
    {
      body: { is_public: true } satisfies IDiscussionboardFilter.IRequest,
    },
  );
  typia.assert(publicPage);
  TestValidator.predicate("all are public")(
    publicPage.data.every((f) => f.is_public === true),
  );

  // 6. List only soft-deleted filters (by filtering on deleted_at)
  // To get the deleted_at timestamp, fetch all filtered-out (soft-deleted) by id if possible
  let deletedTimestamp: string | null = null;
  {
    // Try to find the deleted filter directly (with a broad query)
    const allFiltersIncDeleted =
      await api.functional.prefix.member.my.filters.index(connection, {
        body: { id: deletedFilterId } satisfies IDiscussionboardFilter.IRequest,
      });
    if (
      allFiltersIncDeleted.data.length &&
      allFiltersIncDeleted.data[0].deleted_at
    ) {
      deletedTimestamp = allFiltersIncDeleted.data[0].deleted_at;
    }
  }
  if (deletedTimestamp) {
    const deletedOnlyPage = await api.functional.prefix.member.my.filters.index(
      connection,
      {
        body: {
          deleted_at: deletedTimestamp,
        } satisfies IDiscussionboardFilter.IRequest,
      },
    );
    typia.assert(deletedOnlyPage);
    TestValidator.predicate("contains only deleted entries")(
      deletedOnlyPage.data.every((f) => f.deleted_at === deletedTimestamp),
    );
  }

  // 7. Pagination: get two pages of data with a small limit, check page contents differ
  const pageSize = 2 as number & tags.Type<"int32">;
  const page1 = await api.functional.prefix.member.my.filters.index(
    connection,
    {
      body: {
        limit: pageSize,
        current: 1,
      } satisfies IDiscussionboardFilter.IRequest,
    },
  );
  typia.assert(page1);
  TestValidator.equals("page1 limit matches")(page1.data.length)(pageSize);
  const page2 = await api.functional.prefix.member.my.filters.index(
    connection,
    {
      body: {
        limit: pageSize,
        current: 2,
      } satisfies IDiscussionboardFilter.IRequest,
    },
  );
  typia.assert(page2);
  TestValidator.equals("page2 limit matches")(page2.data.length)(pageSize);
  // Pages are disjoint by ids
  const ids1 = page1.data.map((f) => f.id);
  const ids2 = page2.data.map((f) => f.id);
  TestValidator.predicate("pages are disjoint")(
    ids1.every((id) => !ids2.includes(id)),
  );
  // 8. Sanity: no leaked foreign filters
  TestValidator.predicate("no foreign filters")(
    [...page1.data, ...page2.data].every(
      (f) =>
        f.discussionboard_member_id === updatedFilter.discussionboard_member_id,
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";

/**
 * Test that the authenticated poll creator can successfully hard-delete their
 * own poll.
 *
 * Business context:
 *
 * - Only the poll creator may perform a hard delete of their own poll. There is
 *   no soft delete or archived flag; the action is irreversible and permanently
 *   removes the poll from the system.
 * - All necessary setup must be performed (member registration, thread and poll
 *   creation) before deletion.
 * - After deletion, the system should guarantee the poll is not found in listings
 *   or detail retrieval.
 *
 * Test steps:
 *
 * 1. Register a new member (assign unique id and creation timestamp)
 * 2. Create a new thread, associated with a category and using the member as
 *    creator
 * 3. Create a poll attached to that thread (authenticated as the member)
 * 4. Hard-delete the poll via the erase endpoint (/my/polls/{id}) as the original
 *    creator
 * 5. Attempt to retrieve (list/detail) the poll after deletion – should receive
 *    not-found or error
 * 6. Assert that the poll has been permanently erased and cannot be restored or
 *    accessed
 */
export async function test_api_member_test_delete_own_poll_successful(
  connection: api.IConnection,
) {
  // 1. Register member (for poll ownership)
  const memberId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const memberCreatedAt: string & tags.Format<"date-time"> =
    new Date().toISOString() as any;
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId,
        created_at: memberCreatedAt,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a new thread for poll attachment
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        // discussionboard_member_id is ignored on input per DTO – server assigns by context, so do not supply
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "Test Poll Thread",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString() as any,
        updated_at: new Date().toISOString() as any,
      } satisfies IDiscussionboardThreads.ICreate,
    },
  );
  typia.assert(thread);

  // 3. Create a poll attached to the thread
  const poll = await api.functional.prefix.member.polls.create(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      prompt: "Should E2E tests delete polls irreversibly?",
      allow_multiple_choices: false,
      is_anonymous: false,
      expires_at: null,
    } satisfies IPoll.ICreate,
  });
  typia.assert(poll);

  // 4. Delete the poll as its owner
  await api.functional.prefix.member.my.polls.erase(connection, {
    id: poll.id,
  });

  // 5. Verification step: The API set does not expose direct list or get-by-id endpoints post-deletion for erased polls,
  // so we can only confirm that deleting again throws an error (poll is gone)
  await TestValidator.error("cannot delete nonexistent poll")(() =>
    api.functional.prefix.member.my.polls.erase(connection, { id: poll.id }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardBusinessRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardBusinessRule";
import type { IPageIDiscussionboardBusinessRule } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardBusinessRule";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E tests for listing and filtering business rules with pagination.
 *
 * This test verifies that business rules can be filtered and paginated
 * correctly, including by exact and partial matches on rule_code/title, by
 * is_active status, and that the pagination meta and returned business rule
 * data always reflect the query. Also ensures empty result handling works (no
 * matching records).
 *
 * Steps:
 *
 * 1. Create several business rules with distinct rule_code, title and is_active
 *    values
 * 2. List all business rules (no filter), expecting all created to be present
 * 3. Filter by rule_code: Only correct record(s) return
 * 4. Partial title match: Search with a substring and expect matching subset
 * 5. Filter by is_active: Test both true/false status for correct subsets
 * 6. Pagination: Supply limit/offset and verify correct slicing and meta
 * 7. Filter with no matches: Expect empty data array and correct pagination meta
 */
export async function test_api_prefix_admin_policyAudit_businessRules_test_list_policy_audit_business_rules_with_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create business rules with varied values for coverage
  const rules = [
    await api.functional.prefix.admin.policyAudit.businessRules.create(
      connection,
      {
        body: {
          rule_code: "RULE_ALPHA",
          title: "Alpha Policy",
          description: "Description for Alpha Policy.",
          is_active: true,
        },
      },
    ),
    await api.functional.prefix.admin.policyAudit.businessRules.create(
      connection,
      {
        body: {
          rule_code: "RULE_BETA",
          title: "Beta Policy",
          description: "Description for Beta Policy.",
          is_active: false,
        },
      },
    ),
    await api.functional.prefix.admin.policyAudit.businessRules.create(
      connection,
      {
        body: {
          rule_code: "RULE_GAMMA",
          title: "Gamma Process",
          description: "Gamma process compliance details.",
          is_active: true,
        },
      },
    ),
    await api.functional.prefix.admin.policyAudit.businessRules.create(
      connection,
      {
        body: {
          rule_code: "RULE_DELTA",
          title: "Delta Security",
          description: "Policy for Delta security flows.",
          is_active: false,
        },
      },
    ),
  ];
  rules.forEach(typia.assert);

  // 2. List all rules (no filter)
  const allList =
    await api.functional.prefix.admin.policyAudit.businessRules.index(
      connection,
      { body: {} },
    );
  typia.assert(allList);
  TestValidator.predicate("all rules present")(
    rules.every((rule) => allList.data.find((r) => r.id === rule.id)),
  );

  // 3. Filter by rule_code (should return exactly one)
  const codeList =
    await api.functional.prefix.admin.policyAudit.businessRules.index(
      connection,
      { body: { rule_code: "RULE_BETA" } },
    );
  typia.assert(codeList);
  TestValidator.equals("one matching code")(codeList.data.length)(1);
  TestValidator.equals("correct id for code")(codeList.data[0].id)(rules[1].id);

  // 4. Partial title match (substring 'Policy' yields Alpha/Beta)
  const partialTitleList =
    await api.functional.prefix.admin.policyAudit.businessRules.index(
      connection,
      { body: { title: "Policy" } },
    );
  typia.assert(partialTitleList);
  TestValidator.equals("subset with partial title match")(
    partialTitleList.data.length,
  )(2);
  const policyTitles = rules
    .filter((r) => r.title.includes("Policy"))
    .map((r) => r.id)
    .sort();
  const resultTitles = partialTitleList.data.map((r) => r.id).sort();
  TestValidator.equals("IDs for partial title match")(resultTitles)(
    policyTitles,
  );

  // 5. Filter by is_active (true)
  const activeList =
    await api.functional.prefix.admin.policyAudit.businessRules.index(
      connection,
      { body: { is_active: true } },
    );
  typia.assert(activeList);
  const activeIds = rules
    .filter((r) => r.is_active)
    .map((r) => r.id)
    .sort();
  const resultActiveIds = activeList.data.map((r) => r.id).sort();
  TestValidator.equals("IDs for is_active=true")(resultActiveIds)(activeIds);

  // 5b. Filter by is_active (false)
  const inactiveList =
    await api.functional.prefix.admin.policyAudit.businessRules.index(
      connection,
      { body: { is_active: false } },
    );
  typia.assert(inactiveList);
  const inactiveIds = rules
    .filter((r) => !r.is_active)
    .map((r) => r.id)
    .sort();
  const resultInactiveIds = inactiveList.data.map((r) => r.id).sort();
  TestValidator.equals("IDs for is_active=false")(resultInactiveIds)(
    inactiveIds,
  );

  // 6. Pagination: limit/offset
  // Limit: 2, expect 2 items
  const page1 =
    await api.functional.prefix.admin.policyAudit.businessRules.index(
      connection,
      { body: {} },
    );
  typia.assert(page1);
  const pageSize = 2;
  const pageLimitList =
    await api.functional.prefix.admin.policyAudit.businessRules.index(
      connection,
      { body: {} },
    );
  typia.assert(pageLimitList);
  // If backend supports custom paging, you might specify limit/offset in IRequest or IPage - here not present, so just document placeholder
  // In this contract, the pagination meta should reflect returned items
  TestValidator.equals("pagination limit")(pageLimitList.pagination.limit)(
    page1.pagination.limit,
  );

  // 7. No-match filter
  const emptyList =
    await api.functional.prefix.admin.policyAudit.businessRules.index(
      connection,
      { body: { rule_code: "NO_SUCH_CODE" } },
    );
  typia.assert(emptyList);
  TestValidator.equals("data empty on impossible filter")(
    emptyList.data.length,
  )(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardGuests } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardGuests";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IContentReport";

/**
 * 게스트 B가 게스트 A가 작성한 콘텐츠 신고를 수정할 수 없는지 검증하는 테스트입니다.
 *
 * 본 테스트는 방문자(게스트) 소유권 검증 정책이 올바르게 적용되는지 확인합니다.
 *
 * Step-by-step 프로세스:
 *
 * 1. 게스트 A와 게스트 B 두 개의 익명 게스트 세션을 생성합니다.
 * 2. 신고 대상이 될 게시글(포스트)을 만듭니다.
 * 3. 게스트 A 세션으로 해당 게시글에 대해 콘텐츠 신고를 제출합니다.
 * 4. 게스트 B 세션으로 게스트 A가 생성한 신고의 ID를 조회해 동일 신고를 수정 시도합니다.
 * 5. 이때 게스트 B의 수정 요청은 반드시 권한 오류(Authorization Error)로 거절되어야 하며, 서버는 콘텐츠 신고 소유자인
 *    게스트 A만 해당 신고를 수정 가능함을 보장해야 합니다.
 */
export async function test_api_guest_test_guest_cannot_update_other_guests_report(
