/**
 * Validate admin search and pagination for discussionboard post edit logs.
 *
 * Confirms that the admin post edit log list endpoint supports real-world use
 * cases with schema-based filters, pagination, and sortability. Validates both
 * positive scenarios (with results) and edge/error handling scenarios (overly
 * restrictive filter, empty filter).
 *
 * Steps:
 *
 * 1. Create a member post so edit logs can be generated using the dependency
 *    endpoint.
 * 2. Assume that an edit to the post is made and an edit log exists (edit
 *    simulation is skipped due to SDK limitations).
 * 3. Test getting a paginated list with no filters (should list at least one log
 *    for the post if present).
 * 4. Test getting logs filtered by discussionboard_post_id (should return log(s)
 *    just for that post).
 * 5. Test a restrictive filter (e.g., random non-matching discussionboard_post_id)
 *    and expect empty result.
 * 6. (Sorting can't be directly tested as the DTO/request doesn’t support a sort
 *    parameter—note this edge case).
 * 7. Test using an unauthorized field in filter body—confirm it is ignored (since
 *    schema validation would fail if not allowed). Only permitted fields are
 *    accepted.
 * 8. Test with minimal/empty filter and default pagination parameters to check
 *    retrieval of all logs admin is entitled to view.
 */
export async function test_api_prefix_admin_threadsPosts_postEditLogs_test_list_post_edit_logs_with_complex_filter_sort_and_pagination_admin(
  connection: api.IConnection,
) {
  // 1. Create post as member (dependency)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const createPostBody = {
    discussionboard_thread_id: threadId,
    body: "Initial post for edit log tests.",
  } satisfies IDiscussionboardPosts.ICreate;
  const createdPost =
    await api.functional.prefix.member.threadsPosts.posts.create(connection, {
      body: createPostBody,
    });
  typia.assert(createdPost);

  // 2. (Edit simulation and log generation is omitted; assume at least one exists.)

  // 3. Empty filter — Retrieve all logs (should get paginated result)
  const logsAll =
    await api.functional.prefix.admin.threadsPosts.postEditLogs.index(
      connection,
      { body: {} },
    );
  typia.assert(logsAll);
  TestValidator.predicate("logs all returns pagination")(
    typeof logsAll.pagination.current === "number",
  );

  // 4. Filter by discussionboard_post_id (should only return logs for this post)
  const logsForPost =
    await api.functional.prefix.admin.threadsPosts.postEditLogs.index(
      connection,
      { body: { discussionboard_post_id: createdPost.id } },
    );
  typia.assert(logsForPost);
  for (const log of logsForPost.data) {
    TestValidator.equals("filtered log post id")(log.discussionboard_post_id)(
