  }

  // 5. Use restrictive (nonexistent) post id — should return empty
  const noMatchPostId = typia.random<string & tags.Format<"uuid">>();
  const logsNone =
    await api.functional.prefix.admin.threadsPosts.postEditLogs.index(
      connection,
      { body: { discussionboard_post_id: noMatchPostId } },
    );
  typia.assert(logsNone);
  TestValidator.equals("no match records")(logsNone.data.length)(0);

  // 6. Sorting unsupported by schema - can't test directly

  // 7. Test unauthorized (non-schema) filter field, expect schema validation error
  await TestValidator.error("unknown filter field triggers error")(async () => {
    // @ts-expect-error: intentional schema violation
    await api.functional.prefix.admin.threadsPosts.postEditLogs.index(
      connection,
      { body: { not_a_real_field: "forbidden" } },
    );
  });

  // 8. Again, retrieve with empty filter: should paginate all logs
  const allLogsAgain =
    await api.functional.prefix.admin.threadsPosts.postEditLogs.index(
      connection,
      { body: {} },
    );
  typia.assert(allLogsAgain);
  TestValidator.predicate("logs all again returns pagination")(
