import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IPostEditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostEditLog";

/**
 * 게시글 수정 로그 변경 API의 정상 동작과 각종 오류(권한, schema 위반) 케이스를 검증합니다.
 *
 * - 멤버가 자신이 소유한 post edit log(change_summary, change_details만 수정 가능)를 정상적으로 업데이트할
 *   수 있음
 * - 소유하지 않은 로그, 스키마에 맞지 않는 요청(body 누락/허용 외 필드 포함 등) 보내면 정확히 에러 처리됨
 * - 모든 동작에서 타입, business rule, schema 적합성 보장
 *
 * 구현 상 한계로 edit log 생성은 typia.random으로 대체(실제로는 post 수정 후 log id 추출 필요)
 *
 * 1. 토론 게시글 작성(멤버 본인)
 * 2. (실제라면 글 수정 → postEditLog 생성 필요, 샘플에선 무작위 생성)
 * 3. 정상: 본인 소유 edit log에 허용 필드만으로 update → 내용 변경 여부 확인
 * 4. 본인 소유 아님: 타인 edit log id로 update 시도 → 에러
 * 5. 요청 body 없이 update 시도 → 에러
 * 6. 허용 안된 필드(body 내 id 등) 포함 update 시도 → schema validation 에러
 */
export async function test_api_prefix_member_my_threadsPosts_postEditLogs_test_update_post_edit_log_member_owned_valid_and_invalid(
  connection: api.IConnection,
) {
  // 1. 게시글 생성 (멤버 본인)
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
        body: "테스트 본문",
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(post);

  // 2. edit log record 생성 (실전은 글 수정 후, 샘플은 typia.random 대체)
  const myEditLog = typia.random<IPostEditLog>();

  // 3. 정상 시나리오: 허용 필드만으로 update 수행
  const updated =
    await api.functional.prefix.member.my.threadsPosts.postEditLogs.update(
      connection,
      {
        id: myEditLog.id,
        body: {
          change_summary: "수정: 첫번째 변경",
          change_details: "from '\u003c초안\u003e' to '\u003c수정본\u003e'",
        } satisfies IPostEditLog.IUpdate,
      },
    );
  typia.assert(updated);
  TestValidator.equals("id 동일")(updated.id)(myEditLog.id);
  TestValidator.equals("change_summary 반영")(updated.change_summary)(
    "수정: 첫번째 변경",
  );
  TestValidator.equals("change_details 반영")(updated.change_details)(
    "from '\u003c초안\u003e' to '\u003c수정본\u003e'",
  );

  // 4. 소유하지 않은 edit log id로 update 시도 → 에러
  await TestValidator.error("타인 edit log update 차단")(async () => {
    await api.functional.prefix.member.my.threadsPosts.postEditLogs.update(
      connection,
      {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: {
          change_summary: "해킹 시도",
          change_details: "should fail",
        },
      },
    );
  });

  // 5. update 요청 body 없이 시도 → 에러
  await TestValidator.error("update body 누락시 에러")(async () => {
    // @ts-expect-error intentionally omitted body
    await api.functional.prefix.member.my.threadsPosts.postEditLogs.update(
      connection,
      {
        id: myEditLog.id,
      } as any,
    );
  });

  // 6. 스키마 허용되지 않은 필드 포함 update 시도 → 에러
  await TestValidator.error("허용 외 필드 update 거부")(async () => {
    // @ts-expect-error forbidden fields in body
    await api.functional.prefix.member.my.threadsPosts.postEditLogs.update(
      connection,
      {
        id: myEditLog.id,
        body: {
          change_summary: "fail",
          change_details: "fail",
          id: "forbidden",
          discussionboard_post_id: "not-allowed",
          edit_member_id: "not-allowed",
          created_at: new Date().toISOString(),
        },
      } as any,
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardConfiguration";
import type { IPageIDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardConfiguration";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test admin paginated and filtered retrieval of discussion board
 * configurations
 *
 * This test ensures that an admin can successfully retrieve a paginated and
 * filtered list of discussion board configurations. It verifies that filtering
 * by key fields works, that pagination and sorting behave as expected, and that
 * the response matches the configurations actually created.
 *
 * Process:
 *
 * 1. Create several discussion board configurations with distinct names and
 *    descriptions.
 * 2. Use the PATCH endpoint to request a page of configurations filtered by name
 *    (containing 'config'), sorted ascending, with page=1 and limit=2.
 * 3. Check that only the correct configurations are returned in the correct order,
 *    with pagination metadata accurate.
 * 4. Assert that every returned configuration in the response exactly matches the
 *    created data.
 */
export async function test_api_discussionboardconfiguration_test_list_configurations_with_pagination_and_filters(
  connection: api.IConnection,
) {
  // 1. Create three configurations with unique names/descriptions
  const configs = await Promise.all([
    api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      {
        body: {
          name: "alpha-config",
          settings_json: JSON.stringify({ polls: true, mod: "A" }),
          description: "For alpha module tests.",
        } satisfies IDiscussionboardConfiguration.ICreate,
      },
    ),
    api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      {
        body: {
          name: "beta-config",
          settings_json: JSON.stringify({ polls: false, mod: "B" }),
          description: "Beta features section.",
        } satisfies IDiscussionboardConfiguration.ICreate,
      },
    ),
    api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      {
        body: {
          name: "gamma-policy",
          settings_json: JSON.stringify({ polls: true, mod: "C" }),
          description: "Experimental gamma policies.",
        } satisfies IDiscussionboardConfiguration.ICreate,
      },
    ),
  ]);
  configs.forEach(typia.assert);

  // 2. Query with name filter, pagination = page 1, limit 2, and sorting by name ascending
  const page =
    await api.functional.prefix.admin.discussionboardConfigurations.index(
      connection,
      {
        body: {
          filters: { name: { contains: "config" } },
          sort: ["name:asc"],
          page: 1,
          limit: 2,
        } satisfies IDiscussionboardConfiguration.IRequest,
      },
    );
  typia.assert(page);

  // 3. Validate the response: only configs with 'config' in the name and correct sort
  TestValidator.equals("page current")(page.pagination.current)(1);
  TestValidator.equals("page limit")(page.pagination.limit)(2);
  TestValidator.predicate("all config names contain 'config'")(
    page.data.every((row) => row.name.includes("config")),
  );
  TestValidator.equals("configs returned in order")(
    page.data.map((row) => row.name),
  )(["alpha-config", "beta-config"]);

  // 4. Each config should match those originally created
  for (const config of page.data) {
    const orig = configs.find((c) => c.id === config.id);
    TestValidator.equals("id")(config.id)(orig?.id);
    TestValidator.equals("name")(config.name)(orig?.name);
    TestValidator.equals("settings_json")(config.settings_json)(
      orig?.settings_json,
    );
    TestValidator.equals("description")(config.description)(orig?.description);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardConfiguration";

/**
 * Test successful update of a discussion board configuration.
 *
 * Validates the full admin workflow for updating configuration records via API:
 *
 * 1. Creates a new configuration (unique name, valid JSON settings, description)
 * 2. Updates the configuration's mutable fields (name, settings_json, description)
 * 3. Verifies that changes are persisted—ID unchanged, updated fields reflected
 * 4. Ensures that the configuration name uniqueness constraint is enforced by
 *    attempting to create a new configuration with the updated (now taken) name
 *    (expects failure)
 *
 * This test guarantees that admin editing of configurations yields correct,
 * persistent changes and helps prevent name duplication bugs.
 */
export async function test_api_prefix_admin_discussionboardConfigurations_test_update_discussion_board_configuration_successfully(
  connection: api.IConnection,
) {
  // 1. Create a new discussion board configuration with a unique name
  const createInput: IDiscussionboardConfiguration.ICreate = {
    name: `test-config-unique-${RandomGenerator.hash()}`,
    settings_json: JSON.stringify({ postsPerDay: 10, moderation: true }),
    description: "Initial config for update success test",
  };
  const created =
    await api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      { body: createInput },
    );
  typia.assert(created);

  // 2. Update mutable fields (name, settings_json, description)
  const updateInput: IDiscussionboardConfiguration.IUpdate = {
    name: `${createInput.name}-updated`,
    settings_json: JSON.stringify({ postsPerDay: 42, moderation: false }),
    description: "Config updated for persistence and uniqueness validation.",
  };
  const updated =
    await api.functional.prefix.admin.discussionboardConfigurations.update(
      connection,
      {
        configurationId: created.id,
        body: updateInput,
      },
    );
  typia.assert(updated);

  // 3. Assert that the update mutated the correct record and changes are reflected
  TestValidator.equals("update: id unchanged")(updated.id)(created.id);
  TestValidator.notEquals("update: name changed")(updated.name)(
    createInput.name,
  );
  TestValidator.equals("update: new name")(updated.name)(updateInput.name);
  TestValidator.equals("update: settings_json")(updated.settings_json)(
    updateInput.settings_json,
  );
  TestValidator.equals("update: description")(updated.description)(
    updateInput.description,
  );

  // 4. Attempt to create another configuration with the updated (now-taken) name; expect error for uniqueness constraint
  await TestValidator.error("creation with non-unique name fails")(async () => {
    await api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      {
        body: {
          name: updateInput.name!,
          settings_json: JSON.stringify({ dummy: true }),
          description: "Should fail due to non-unique name",
        },
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IContentReport";
import type { IPageIContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIContentReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate moderator content report listing with comprehensive filter, search,
 * and pagination behaviors.
 *
 * The test creates a post, then creates several content reports with different
 * `status`, `report_reason`, and reporter identity (member). After setup, it
 * exercises the moderator's report listing API with:
 *
 * - Filter by status (e.g., only 'pending', only 'in_review', etc.)
 * - Filter by report_reason (search for a specific reason keyword)
 * - Filter by reporter_member_id (limit to a specific user)
 * - Combined search and pagination (limit, page) The test validates the API
 *   returns exactly and only the expected reports for each case (matching count
 *   and content). It also attempts to use an unsupported filter field to ensure
 *   the API correctly rejects or ignores it (error or empty/no-op behavior).
 *   Steps:
 *
 * 1. Create a discussion thread post that can be reported
 * 2. Create several content reports for that post, with at least 2 different
 *    member reporters, various reasons, and each status ('pending',
 *    'in_review', 'action_taken', 'dismissed')
 * 3. As moderator, call the contentReports.index API with: a) Filter by status =
 *    'pending' → only 'pending' status reports returned b) Filter by a specific
 *    report_reason value c) Filter by a reporter_member_id, confirm only their
 *    reports returned d) Paginate results (e.g. limit=2, page=2), check correct
 *    slicing/order e) Combine multiple filters
 * 4. Negative test: supply a non-existent filter property (e.g.,
 *    {not_a_real_filter: 1}) and confirm proper rejection or no filtering
 * 5. Validate response types, pagination info, and correct business behavior at
 *    each step
 */
export async function test_api_moderator_test_list_content_reports_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a new post that can be reported
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post1 = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: threadId,
        body: "This is the post to be reported",
        is_edited: false,
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(post1);

  // 2. Use two different reporter members
  const reporter_member1 = typia.random<string & tags.Format<"uuid">>();
  const reporter_member2 = typia.random<string & tags.Format<"uuid">>();
  // Timestamps for variety
  const report_times = [
    new Date(Date.now() - 3600 * 1000 * 4).toISOString(), // 4h ago
    new Date(Date.now() - 3600 * 1000 * 3).toISOString(),
    new Date(Date.now() - 3600 * 1000 * 2).toISOString(),
    new Date(Date.now() - 3600 * 1000 * 1).toISOString(),
  ];
  // Distinct reasons and statuses
  const reportData = [
    {
      reporter: reporter_member1,
      reason: "spam",
      status: "pending",
      at: report_times[0],
    },
    {
      reporter: reporter_member2,
      reason: "harassment",
      status: "in_review",
      at: report_times[1],
    },
    {
      reporter: reporter_member1,
      reason: "offtopic",
      status: "action_taken",
      at: report_times[2],
    },
    {
      reporter: reporter_member2,
      reason: "other",
      status: "dismissed",
      at: report_times[3],
    },
  ];
  const createdReports: IContentReport[] = [];
  for (const { reporter, reason, status, at } of reportData) {
    const report = await api.functional.prefix.member.contentReports.create(
      connection,
      {
        body: {
          reported_post_id: post1.id,
          reporter_member_id: reporter,
          report_reason: reason,
          status: status as
            | "pending"
            | "in_review"
            | "action_taken"
            | "dismissed",
          reported_at: at,
        } satisfies IContentReport.ICreate,
      },
    );
    typia.assert(report);
    createdReports.push(report);
  }

  // 3a) Filter by status
  let output = await api.functional.prefix.moderator.contentReports.index(
    connection,
    {
      body: {
        status: "pending",
      } satisfies IContentReport.IRequest,
    },
  );
  typia.assert(output);
  TestValidator.equals("reports with status 'pending'")(
    output.data.map((r) => r.status).every((s) => s === "pending"),
  )(true);

  // 3b) Filter by report_reason
  output = await api.functional.prefix.moderator.contentReports.index(
    connection,
    {
      body: {
        report_reason: "spam",
      } satisfies IContentReport.IRequest,
    },
  );
  typia.assert(output);
  TestValidator.equals("reports with reason 'spam'")(
    output.data.every((r) => r.report_reason === "spam"),
  )(true);

  // 3c) Filter by reporter_member_id
  output = await api.functional.prefix.moderator.contentReports.index(
    connection,
    {
      body: {
        reporter_member_id: reporter_member1,
      } satisfies IContentReport.IRequest,
    },
  );
  typia.assert(output);
  TestValidator.equals("reports by reporter_member1")(
    output.data.every((r) => r.reporter_member_id === reporter_member1),
  )(true);

  // 3d) Pagination
