import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAppeal";
import type { null } from "@ORGANIZATION/PROJECT-api/lib/structures/null";

/**
 * Test forbidden deletion of another user's appeal by a member user.
 *
 * This test verifies that a member cannot delete an appeal they do not own. It follows these steps:
 * 1. As a privileged user (admin/moderator), create a new appeal and record its id.
 * 2. Ensure the test connection is authenticated as a normal member who is not the owner of that appeal.
 * 3. Attempt to delete the appeal by calling the member DELETE endpoint with the appeal id.
 * 4. Assert that the operation fails with a forbidden error (authorization error), and that the appeal is not deleted from the system.
 *
 * Business context: appeals should only be removable by their creator or an admin; cross-user access must be prevented.
 * This ensures role-based access control for destructive operations is enforced.
 */
export async function test_api_prefix_member_policyAudit_appeals_test_delete_other_users_appeal_is_forbidden(
  connection: api.IConnection,
) {
  // 1. Create an appeal as a separate (admin/moderator) user
  const otherAppeal: IDiscussionboardAppeal = await api.functional.prefix.admin.policyAudit.appeals.create(connection, {
    body: {
      appeal_code: `APPEAL-${new Date().toISOString().slice(0, 10).replace(/-/g, '')}-001`,
      status: 'PENDING',
      appellant_id: typia.random<string & tags.Format<'uuid'>>(),
      incident_id: null,
      outcome: null,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    } satisfies IDiscussionboardAppeal.ICreate,
  });
  typia.assert(otherAppeal);

  // 2. Attempt to delete the appeal as a member (who does not own the appeal)
  await TestValidator.error("deleting another user's appeal should be forbidden")(async () => {
    await api.functional.prefix.member.policyAudit.appeals.erase(connection, {
      appealId: otherAppeal.id,
    });
  });

  // Note: Cannot verify persistence/removal directly because there is no API to GET appeals in this scope.
}

