import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";
import type { IDiscussionboardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCategory";

/**
 * Validate required field enforcement for discussion board category creation
 * (admin API).
 *
 * Ensures that omitting any required field (such as 'name',
 * 'discussionboard_section_id', 'order', or 'enabled') from the category
 * creation request causes the API to respond with a validation error and
 * prevents the creation of the record. All required field constraints are
 * verified.
 *
 * Steps:
 *
 * 1. Create a valid section to obtain a working section ID for use in the category
 *    payload (dependency).
 * 2. Attempt to create a discussion board category missing the 'name' field –
 *    should fail.
 * 3. Attempt to create a discussion board category missing the
 *    'discussionboard_section_id' field – should fail.
 * 4. Attempt to create a category missing both 'name' and
 *    'discussionboard_section_id' fields – should fail.
 * 5. Attempt to create a category missing 'order' – should fail.
 * 6. Attempt to create a category missing 'enabled' – should fail.
 */
export async function test_api_discussionboardCategories_test_create_discussionboard_category_with_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. Create a valid section to use as the parent for categories
  const section =
    await api.functional.prefix.admin.discussionboardSections.create(
      connection,
      {
        body: {
          discussionboard_configuration_id: typia.random<
            string & tags.Format<"uuid">
          >(),
          name: "Section for Category Field Validation",
          order: 10,
          enabled: true,
          description: "Section for negative tests",
        } satisfies IDiscussionboardSection.ICreate,
      },
    );
  typia.assert(section);

  // Prepare a fully valid category creation body for reference
  const validCategoryBody = {
    discussionboard_section_id: section.id,
    name: "Validation Category",
    order: 1,
    enabled: true,
    description: "Testing missing field behavior",
  } satisfies IDiscussionboardCategory.ICreate;

  // Utility to safely omit fields from a valid body
  const omit = <T extends object>(src: T, ...keys: (keyof T)[]) => {
    const copy = { ...src };
    for (const key of keys) delete copy[key];
    return copy;
  };

  // 2. Attempt: missing 'name'
  await TestValidator.error("missing name should fail")(
    async () =>
      await api.functional.prefix.admin.discussionboardCategories.create(
        connection,
        {
          // @ts-expect-error intentionally omitting required property; type checker will flag this
          body: omit(validCategoryBody, "name"),
        },
      ),
  );

  // 3. Attempt: missing 'discussionboard_section_id'
  await TestValidator.error("missing section ID should fail")(
    async () =>
      await api.functional.prefix.admin.discussionboardCategories.create(
        connection,
        {
          // @ts-expect-error purposely omit required field
          body: omit(validCategoryBody, "discussionboard_section_id"),
        },
      ),
  );

  // 4. Attempt: missing both 'name' and 'discussionboard_section_id'
  await TestValidator.error("missing both required fields should fail")(
    async () =>
      await api.functional.prefix.admin.discussionboardCategories.create(
        connection,
        {
          // @ts-expect-error purposely omit required fields
          body: omit(validCategoryBody, "name", "discussionboard_section_id"),
        },
      ),
  );

  // 5. Attempt: missing 'order' (required int)
  await TestValidator.error("missing order should fail")(
    async () =>
      await api.functional.prefix.admin.discussionboardCategories.create(
        connection,
        {
          // @ts-expect-error purposely omit required field
          body: omit(validCategoryBody, "order"),
        },
      ),
  );

  // 6. Attempt: missing 'enabled' (required boolean)
  await TestValidator.error("missing enabled should fail")(
    async () =>
      await api.functional.prefix.admin.discussionboardCategories.create(
        connection,
        {
          // @ts-expect-error purposely omit required field
          body: omit(validCategoryBody, "enabled"),
        },
      ),
  );
}

