import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";
import type { IDiscussionboardCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardCategory";

/**
 * Test admin-side discussion board category required property enforcement.
 *
 * This test demonstrates that at the TypeScript SDK/E2E level, it is not
 * possible to construct API requests missing required fields, because the SDK
 * and DTO statically enforce presence of required properties at compile-time.
 * As such, actual negative testing of omitting required fields must be
 * performed via lower- level raw HTTP requests, schema validation tests, or at
 * the OpenAPI level, not within type-safe E2E tests.
 *
 * The only positive path to check here is creation of a valid section (as a FK
 * dependency), as all negative-case missing-field requests would violate
