import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPostReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostReaction";
import type { IPageIDiscussionboardPostReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardPostReaction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 게시글 반응 목록 조회: 일치하는 레코드가 없을 때 빈 결과 반영 검증
 *
 * 게시글 반응 목록 API에 실제 존재하지 않는 post_id, member_id, reaction_type, 미래 날짜 범위 필터로 검색을
 * 시도하면, 에러 없이 빈 배열과 정상 pagination 정보가 반환되어야 한다. 이로써 '조회 0건'에 대한 서버 정상 동작을
 * 보장한다.
 *
 * ■ 시나리오 개요
 *
 * 1. 현실적으로 존재할 수 없는 값들(무작위 UUID 값, 매우 특이한 reaction_type, 먼 미래의 created_at 범위) 조합으로
 *    필터 생성
 * 2. Post reaction 목록 조회 API를 호출
 * 3. 반환 결과의 data가 빈 배열([]), pagination.records가 0, pages/limit/current 양수 여부를 체크하여
 *    빈 결과 및 페이지네이션 정보의 정상 동작을 검증한다.
 */
export async function test_api_prefix_member_postReactions_test_list_post_reactions_with_no_matching_records(
  connection: api.IConnection,
) {
  // 1. 절대 매칭될 수 없는 필터 파라미터 생성
  const impossibleFilters: api.IDiscussionboardPostReaction.IRequest = {
    discussionboard_post_id: typia.random<string & tags.Format<"uuid">>(),
    discussionboard_member_id: typia.random<string & tags.Format<"uuid">>(),
    reaction_type: "🚀_totally_unique_reaction_type_never_used",
    created_at_from: "2100-01-01T00:00:00.000Z",
    created_at_to: "2100-12-31T23:59:59.999Z",
  };

  // 2. post reaction 목록 API 호출
  const output = await api.functional.prefix.member.postReactions.index(
    connection,
    { body: impossibleFilters },
  );
  typia.assert(output);

  // 3. 반환 검증: 빈 배열 및 pagination 정보 확인
  TestValidator.equals("empty post reaction list")(output.data)([]);
  TestValidator.equals("records is zero")(output.pagination.records)(0);
  TestValidator.predicate("pages is at least 1")(output.pagination.pages >= 1);
  TestValidator.predicate("limit is positive")(output.pagination.limit > 0);
  TestValidator.predicate("current page is valid")(
    output.pagination.current >= 1,
  );
}

