import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { null } from "@ORGANIZATION/PROJECT-api/lib/structures/null";

/**
 * Test admin behavior when deleting a non-existent appeal record.
 *
 * This test verifies that, when an admin attempts to hard delete an appeal record (by ID)
 * that does not exist in the `discussionboard_appeals` table, the system returns a 'not found' error
 * and does not affect other data. The endpoint performs a HARD delete – there is no soft deletion or archiving,
 * and non-existent IDs should not lead to successful deletion.
 *
 * Steps:
 * 1. Generate a random (unused) appealId.
 * 2. As a (simulated/admin) user, send DELETE /prefix/admin//policyAudit/appeals/{appealId}
 * 3. Confirm that the API responds with an error (ideally a 404 not found) indicating that the resource does not exist.
 * 4. Optionally, verify that a second call with the same ID also fails, confirming idempotence and data safety.
 */
export async function test_api_prefix_admin_policyAudit_appeals_eraseByAppealid_nonexistent(
  connection: api.IConnection,
) {
  // 1. Generate a random, presumably non-existent, appealId (UUID format)
  const randomAppealId = typia.random<string & tags.Format<"uuid">>();

  // 2. Attempt to delete the (non-existent) appeal as admin
  await TestValidator.error("should return not found for nonexistent appeal")(
    async () => {
      await api.functional.prefix.admin.policyAudit.appeals.erase(connection, {
        appealId: randomAppealId,
      });
    },
  );

  // 3. (Optional) Try again to confirm repeated failure (idempotence, data not created)
  await TestValidator.error("should still return not found for repeated attempt")(
    async () => {
      await api.functional.prefix.admin.policyAudit.appeals.erase(connection, {
        appealId: randomAppealId,
      });
    },
  );
}

