import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/ISuspension";
import type { IPageISuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageISuspension";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 스키마 기반 필터/정렬 정책 강제여부를 검증하는 정지이력 목록 테스트
 *
 * 이 테스트는 prefix/moderator//suspensions 엔드포인트가 허용되지 않은 필터/정렬 키 전달 시, 스키마 레벨의 검증
 * 오류를 정상적으로 반환하는지 확인합니다.
 *
 * 1. 정상 스키마로 요청시 성공적으로 결과를 조회할 수 있어야 합니다.
 * 2. ISuspension.IRequest에 명시되지 않은 키(nonexistent_field, sort_by 등)를 body에 담아 요청시,
 *    스키마 validation 에러가 발생하는지 TestValidator.error로 검증합니다.
 */
export async function test_api_suspensions_test_list_suspensions_schema_enforcement(
  connection: api.IConnection,
) {
  // 1. 정상 요청: 올바른 필드로 페이징 호출
  const okOutput = await api.functional.prefix.moderator.suspensions.index(
    connection,
    {
      body: {
        page: 1,
        limit: 1,
      },
    },
  );
  typia.assert(okOutput);

  // 2. 존재하지 않는 필터 필드 전달: nonexistent_field
  await TestValidator.error(
    "off-schema filter field triggers validation error",
  )(async () => {
    // @ts-expect-error 일부러 off-schema 필드 포함
    await api.functional.prefix.moderator.suspensions.index(connection, {
      body: {
        page: 1,
        limit: 1,
        nonexistent_field: "bad", // 스키마에 없는 필드
      },
    });
  });

  // 3. 잘못된 정렬 키 전달: sort_by
  await TestValidator.error("invalid sort key triggers validation error")(
    async () => {
      // @ts-expect-error 일부러 잘못된 sort_by 필드 포함
      await api.functional.prefix.moderator.suspensions.index(connection, {
        body: {
          page: 1,
          limit: 1,
          sort_by: "created_at", // 존재하지 않는 필드
        },
      });
    },
  );
}

