import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPostReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostReaction";
import type { IPageIDiscussionboardPostReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardPostReaction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 게시글 반응 목록 조회 API의 필터 파라미터 유효성 검증
 *
 * 잘못된(존재하지 않는 필드, 지원되지 않는 타입, 허용되지 않은 값) 필터 파라미터가 전달되었을 때, 시스템이 적절히 validation
 * error를 반환하고 쿼리를 시도하지 않아야 함을 검증합니다.
 *
 * 테스트 시나리오:
 *
 * 1. 스키마에 없는 필드를 포함한 요청 (out-of-schema key)
 * 2. UUID 타입 필드에 숫자 등 잘못된 타입 전달
 * 3. UUID 타입 필드에 형식이 맞지 않는 문자열 전달
 * 4. Date-time 타입에 잘못된 형식의 문자열 전달
 * 5. 빈 객체로 요청 본문 전달 (business 상 허용 가능성 있음) 각 케이스별로 TestValidator.error를 통해
 *    validation 에러 발생 여부를 확인합니다.
 */
export async function test_api_prefix_member_postReactions_test_list_post_reactions_with_invalid_filters(
  connection: api.IConnection,
) {
  // 1. Out-of-schema key(스키마에 정의되지 않은 필드 포함)
  await TestValidator.error("out-of-schema key")(() =>
    api.functional.prefix.member.postReactions.index(connection, {
      // @ts-expect-error: purposely use undeclared property
      body: {
        unknownField: "some value",
      },
    }),
  );

  // 2. 잘못된 타입(숫자 등 uuid 대신)
  await TestValidator.error("unsupported type for uuid field")(() =>
    api.functional.prefix.member.postReactions.index(connection, {
      // @ts-expect-error: purposely assign number to string(uuid) field
      body: {
        discussionboard_post_id: 12345,
      },
    }),
  );

  // 3. 올바르지 않은 uuid 형식
  await TestValidator.error("invalid uuid format for post id")(() =>
    api.functional.prefix.member.postReactions.index(connection, {
      body: {
        discussionboard_post_id: "not_a_uuid",
      },
    }),
  );

  // 4. 잘못된 date-time 형식 전달
  await TestValidator.error("invalid date-time format for created_at_from")(
    () =>
      api.functional.prefix.member.postReactions.index(connection, {
        body: {
          created_at_from: "20210799abcdef",
        },
      }),
  );

  // 5. 빈 객체 전달(스키마 상 허용, 실제 비즈니스 로직 동작에 따라 결과 달라질 수 있음)
  // validation error가 반드시 발생하지 않을 수 있음(필터 없는 전체검색 허용 시)
  // 에러가 나면 확인, 에러가 안나면 허용되는 정책으로 간주
  try {
    await api.functional.prefix.member.postReactions.index(connection, {
      body: {},
    });
  } catch {
    // 에러 발생시 정상
  }
}

