import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";

/**
 * 토론 스레드 생성 API의 필수 필드 누락 시 유효성 검증 에러 발생을 확인합니다.
 *
 * - 'title'나 'discussionboard_category_id' 등 필수 필드를 일부 제거한 상태로 요청을 보내어, 서버가 올바른
 *   validation error를 반환하는지 검증합니다.
 * - 각 case별로 적절한 누락 field가 에러에 명시되는지를 확인합니다.
 *
 * 테스트 시나리오
 *
 * 1. 필수 필드 중 'title'을 누락하여 생성 시도 (category id, status, 등은 제공)
 * 2. 필수 필드 중 'discussionboard_category_id'를 누락하여 생성 시도 (title, status 등은 제공)
 * 3. 모든 필수 필드를 누락한(비어있는 body) 경우 생성 시도
 *
 * 각 경우별로 서버가 validation 에러(400 등)를 반환하며, 누락된 필드명이 에러 응답에 포함됨을 검증합니다.
 */
export async function test_api_prefix_member_threadsPosts_threads_test_create_thread_without_required_fields(
  connection: api.IConnection,
) {
  // 1. 'title' 필드 누락
  const bodyWithoutTitle = {
    discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(),
    status: "active",
    is_pinned: false,
    is_locked: false,
    archived: false,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  await TestValidator.error("title 없는 신규 스레드 생성 실패")(async () => {
    // @ts-expect-error 테스트 목적상 필드 누락 intentional
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: bodyWithoutTitle,
    });
  });

  // 2. 'discussionboard_category_id' 필드 누락
  const bodyWithoutCategory = {
    title: "테스트용 제목",
    status: "active",
    is_pinned: false,
    is_locked: false,
    archived: false,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  await TestValidator.error("카테고리 없는 신규 스레드 생성 실패")(async () => {
    // @ts-expect-error 테스트 목적상 필드 누락 intentional
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: bodyWithoutCategory,
    });
  });

  // 3. 모든 필수 필드 누락 (완전 빈 body)
  const emptyBody = {};
  await TestValidator.error("모든 필수 필드 없는 신규 스레드 생성 실패")(
    async () => {
      // @ts-expect-error 테스트 목적상 필드 누락 intentional
      await api.functional.prefix.member.threadsPosts.threads.create(
        connection,
        {
          body: emptyBody,
        },
      );
    },
  );
}

