import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAppeal";
import type { IDiscussionboardAppeals } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAppeals";

/**
 * Validate ability of an authenticated member to update their own appeal
 * record.
 *
 * This test ensures that a member can:
 *
 * 1. Create a new appeal (via the admin/create endpoint for simplicity in test
 *    setup and required ownership).
 * 2. Update schema-allowed fields (like status and outcome) using the member
 *    update endpoint.
 * 3. Cannot update with out-of-schema (nonexistent) properties.
 * 4. Sees updated changes and updated_at timestamp advance after update.
 *
 * Steps:
 *
 * 1. Create a new appeal record via POST (as admin for setup), capturing its id
 *    and all returned fields.
 * 2. As the owning member, invoke the update endpoint with valid schema changes
 *    (e.g., change status, supply a new outcome).
 * 3. Verify that only allowed fields are updated, and the updated_at timestamp
 *    differs from the original.
 * 4. Attempt to supply a non-schema property in the update; confirm backend
 *    validation.
 */
export async function test_api_policyAudit_test_update_own_appeal_with_valid_changes(
  connection: api.IConnection,
) {
  // 1. Create an appeal record. Only schema fields included.
  const now = new Date().toISOString();
  const baseAppeal =
    await api.functional.prefix.admin.policyAudit.appeals.create(connection, {
      body: {
        appeal_code: `APPEAL-${now.slice(0, 10).replace(/-/g, "")}-001`,
        status: "PENDING",
        appellant_id: typia.random<string & tags.Format<"uuid">>(),
        incident_id: typia.random<string & tags.Format<"uuid">>(),
        outcome: null,
        created_at: now,
        updated_at: now,
      },
    });
  typia.assert(baseAppeal);

  // 2. Update the appeal as the member. Change status and outcome.
  const newStatus = "UPHELD";
  const newOutcome = "Ban lifted after review.";
  const updatedAppeal =
    await api.functional.prefix.member.policyAudit.appeals.update(connection, {
      appealId: baseAppeal.id,
      body: {
        status: newStatus,
        outcome: newOutcome,
      },
    });
  typia.assert(updatedAppeal);
  TestValidator.equals("Appeal status updated")(updatedAppeal.status)(
    newStatus,
  );
  TestValidator.equals("Outcome updated")(updatedAppeal.outcome)(newOutcome);
  TestValidator.notEquals("Updated at timestamp has changed")(
    updatedAppeal.updated_at,
  )(baseAppeal.updated_at);

  // 3. Try to update with a non-schema field; expect an error.
  await TestValidator.error("Non-schema field update should fail")(async () => {
    // @ts-expect-error: This simulates passing an invalid property.
    await api.functional.prefix.member.policyAudit.appeals.update(connection, {
      appealId: baseAppeal.id,
      body: {
        status: "REJECTED",
        non_existent_field: "illegal", // should be rejected by backend
      },
    });
  });
}

