import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { discussionboard_alerts } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboard_alerts";

/**
 * Validate forbidden deletion of discussion board alerts not owned by the
 * authenticated member.
 *
 * This test checks that a member cannot delete (hard remove) a discussion board
 * alert belonging to another user. Specifically, it creates an alert as a
 * different user and then attempts to delete that alert with the test user. The
 * API must reject the attempt (403 forbidden or 404 not found), and the alert
 * must still exist for the original owner.
 *
 * Step-by-step process:
 *
 * 1. Create an alert as user B (secondary session), recording the alert ID.
 * 2. Switch to user A (the calling connection) and attempt deletion using user B's
 *    alert ID — expect error (no type bypass).
 * 3. (Optionally) Try to delete again as user B and expect success (verifies alert
 *    still exists and only owner can delete).
 *
 * Note: Assumes session authentication is handled at the test framework level.
 * The test manipulates user sessions only through API login endpoints if
 * available. If no login function is provided, run this as two separate
 * physical test runs with different users via the underlying framework.
 */
export async function test_api_prefix_member_my_discussionboardAlerts_test_delete_alert_not_owned_forbidden(
  connection: api.IConnection,
) {
  // STEP 1: Create an alert as user B (secondary session)
  // For this test, we simulate a secondary user session ("user B").
  // It is assumed that the framework can provide a fresh connection for another user (user B). Replace 'getSecondaryUserConnection' with actual auth flow if available.
  const secondaryConnection: api.IConnection =
    await getSecondaryUserConnection();
  const alertB =
    await api.functional.prefix.member.my.discussionboardAlerts.create(
      secondaryConnection,
      {
        body: {
          type: "policy_update",
          severity: "warning",
          title: "This is a test alert for unauthorized delete test.",
          body: "Do not delete this alert unless you own it!",
          is_active: true,
        },
      },
    );
  typia.assert(alertB);

  // STEP 2: On main connection (user A), attempt forbidden delete
  await TestValidator.error("should reject delete by non-owner")(async () => {
    await api.functional.prefix.member.my.discussionboardAlerts.erase(
      connection,
      { alertId: alertB.id },
    );
  });

  // (OPTIONAL) STEP 3: As user B, delete alert and expect success
  await api.functional.prefix.member.my.discussionboardAlerts.erase(
    secondaryConnection,
    { alertId: alertB.id },
  );
}

