import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPlatformPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPlatformPolicy";
import type { IPageIDiscussionboardPlatformPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardPlatformPolicy";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test retrieval of platform policies with various filters, sorting, and
 * pagination as admin.
 *
 * This test covers listing platform policy documents using the admin endpoint
 * with a range of filter scenarios:
 *
 * 1. Fetch all without filters (default fetch), confirming all test-created items
 *    appear
 * 2. Filter by title substring (partial match)
 * 3. Filter by is_active=false (fetch inactives only)
 * 4. Validate API returns results in updated_at descending order (implicit sort
 *    check)
 * 5. Verify pagination boundaries by checking first and last policy presence
 * 6. Try invalid filter key (should error)
 * 7. Confirm empty filter object returns all
 *
 * Every response is validated for only official schema fields, with no extras
 * or omissions. The test creates three diverse policies for robust assertion
 * conditions and ensures that schema and business requirements (such as
 * admin-only access and correct filtering behavior) are enforced. Pagination
 * checks are limited to available DTO features.
 */
export async function test_api_prefix_admin_policyAudit_platformPolicies_test_list_platform_policies_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a diverse set of platform policy records (3 test cases)
  const now = new Date();
  const policies = [
    // Policy 1: Active, "Alpha Policy"
    await api.functional.prefix.admin.policyAudit.platformPolicies.create(
      connection,
      {
        body: {
          policy_code: "ALPHA123",
          title: "Alpha Policy",
          policy_text: "Alpha content.",
          is_active: true,
        },
      },
    ),
    // Policy 2: Active, "Beta Guidelines"
    await api.functional.prefix.admin.policyAudit.platformPolicies.create(
      connection,
      {
        body: {
          policy_code: "BETA456",
          title: "Beta Guidelines",
          policy_text: "Beta content.",
          is_active: true,
        },
      },
    ),
    // Policy 3: Inactive, "Inactive Gamma"
    await api.functional.prefix.admin.policyAudit.platformPolicies.create(
      connection,
      {
        body: {
          policy_code: "GAMMA789",
          title: "Inactive Gamma",
          policy_text: "Gamma content.",
          is_active: false,
        },
      },
    ),
  ];
  for (const p of policies) typia.assert(p);

  // (1) Default fetch: no filters, retrieve all
  const res_all =
    await api.functional.prefix.admin.policyAudit.platformPolicies.index(
      connection,
      { body: {} },
    );
  typia.assert(res_all);
  TestValidator.predicate("all created records are present")(
    policies.every((seed) =>
      res_all.data.some(
        (r) =>
          r.id === seed.id &&
          r.title === seed.title &&
          r.policy_code === seed.policy_code,
      ),
    ),
  );

  // (2) Filter by title substring: "Alpha" (matches Policy 1 only)
  const res_title =
    await api.functional.prefix.admin.policyAudit.platformPolicies.index(
      connection,
      {
        body: { title: "Alpha" },
      },
    );
  typia.assert(res_title);
  TestValidator.predicate("only 'Alpha Policy' is returned")(
    res_title.data.every((r) => r.title.includes("Alpha")) &&
      res_title.data.length === 1,
  );

  // (3) Filter by is_active: false
  const res_inactive =
    await api.functional.prefix.admin.policyAudit.platformPolicies.index(
      connection,
      {
        body: { is_active: false },
      },
    );
  typia.assert(res_inactive);
  TestValidator.predicate("all results have is_active=false")(
    res_inactive.data.every((r) => r.is_active === false),
  );
  TestValidator.predicate("Inactive Gamma is present")(
    res_inactive.data.some((r) => r.id === policies[2].id),
  );

  // (4) Sorting by updated_at descending (implicit check, since no explicit sort param exposed)
  const res_sorted =
    await api.functional.prefix.admin.policyAudit.platformPolicies.index(
      connection,
      { body: {} },
    );
  typia.assert(res_sorted);
  const apiSortedIds = res_sorted.data.map((r) => r.id);
  const localSortedIds = [...res_sorted.data]
    .sort((a, b) => b.updated_at.localeCompare(a.updated_at))
    .map((r) => r.id);
  TestValidator.equals("descending updated_at order")(apiSortedIds)(
    localSortedIds,
  );

  // (5) Pagination boundaries – check first and last record match test seeds
  if (res_all.data.length >= 2) {
    TestValidator.equals("first record matches first policy")(
      res_all.data[0].id,
    )(policies[0].id);
    TestValidator.equals("last record matches last policy")(
      res_all.data[res_all.data.length - 1].id,
    )(policies[policies.length - 1].id);
  }

  // (6) Invalid filter key (should error)
  await TestValidator.error("unexpected filter key is rejected")(async () => {
    // @ts-expect-error intentionally wrong filter property; compile-time block
    // is required to silence type error for this test line only
    await api.functional.prefix.admin.policyAudit.platformPolicies.index(
      connection,
      {
        body: { made_up_key: "not allowed" },
      },
    );
  });

  // (7) Empty filter object should return all
  const res_empty =
    await api.functional.prefix.admin.policyAudit.platformPolicies.index(
      connection,
      { body: {} },
    );
  typia.assert(res_empty);
  TestValidator.predicate("empty filter returns all")(
    res_empty.data.length >= policies.length,
  );

  // Schema property compliance: items must have only official defined fields
  const expectedFields = [
    "id",
    "policy_code",
    "title",
    "policy_text",
    "is_active",
    "published_at",
    "updated_at",
  ];
  for (const result of [
    res_all,
    res_title,
    res_inactive,
    res_sorted,
    res_empty,
  ]) {
    for (const item of result.data) {
      TestValidator.predicate("item has only official schema fields")(
        Object.keys(item).sort().join() === expectedFields.sort().join(),
      );
    }
  }
}

