import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardIncidentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardIncidentReport";

/**
 * Validate API rejects creation of an incident report when required fields are
 * missing.
 *
 * This test ensures the server enforces validation for all mandatory fields
 * when admin attempts to create an incident report.
 *
 * Steps:
 *
 * 1. Attempt to create an incident report while omitting each required field:
 *    - incident_code
 *    - status
 *    - description
 *    - created_at
 *    - updated_at
 *    For each omission, assert the API responds with a validation error and does not create the resource.
 * 2. Additionally, verify that omitting the optional field (reporter_id) does NOT
 *    produce an error.
 */
export async function test_api_prefix_admin_policyAudit_incidentReports_test_fail_to_create_incident_report_with_missing_required_field(
  connection: api.IConnection,
) {
  // Prepare a valid creation payload
  const validInput: IDiscussionboardIncidentReport.ICreate = {
    incident_code: "INCIDENT-20240729-001",
    status: "OPEN",
    description: "Negative test for required field validation",
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
    reporter_id: null,
  };

  // Omitting required field: incident_code
  await TestValidator.error("missing incident_code")(
    async () => {
      const { incident_code, ...input } = validInput;
      await api.functional.prefix.admin.policyAudit.incidentReports.create(
        connection,
        { body: input as any },
      );
    }
  );

  // Omitting required field: status
  await TestValidator.error("missing status")(
    async () => {
      const { status, ...input } = validInput;
      await api.functional.prefix.admin.policyAudit.incidentReports.create(
        connection,
        { body: input as any },
      );
    }
  );

  // Omitting required field: description
  await TestValidator.error("missing description")(
    async () => {
      const { description, ...input } = validInput;
      await api.functional.prefix.admin.policyAudit.incidentReports.create(
        connection,
        { body: input as any },
      );
    }
  );

  // Omitting required field: created_at
  await TestValidator.error("missing created_at")(
    async () => {
      const { created_at, ...input } = validInput;
      await api.functional.prefix.admin.policyAudit.incidentReports.create(
        connection,
        { body: input as any },
      );
    }
  );

  // Omitting required field: updated_at
  await TestValidator.error("missing updated_at")(
    async () => {
      const { updated_at, ...input } = validInput;
      await api.functional.prefix.admin.policyAudit.incidentReports.create(
        connection,
        { body: input as any },
      );
    }
  );

  // Omitting the optional reporter_id - should succeed
  const { reporter_id, ...inputWithoutReporter } = validInput;
  const output = await api.functional.prefix.admin.policyAudit.incidentReports.create(
    connection,
    { body: inputWithoutReporter as IDiscussionboardIncidentReport.ICreate },
  );
  typia.assert(output);
}

