import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardConfiguration";

/**
 * Test successful update of a discussion board configuration.
 *
 * Validates the full admin workflow for updating configuration records via API:
 *
 * 1. Creates a new configuration (unique name, valid JSON settings, description)
 * 2. Updates the configuration's mutable fields (name, settings_json, description)
 * 3. Verifies that changes are persisted—ID unchanged, updated fields reflected
 * 4. Ensures that the configuration name uniqueness constraint is enforced by
 *    attempting to create a new configuration with the updated (now taken) name
 *    (expects failure)
 *
 * This test guarantees that admin editing of configurations yields correct,
 * persistent changes and helps prevent name duplication bugs.
 */
export async function test_api_prefix_admin_discussionboardConfigurations_test_update_discussion_board_configuration_successfully(
  connection: api.IConnection,
) {
  // 1. Create a new discussion board configuration with a unique name
  const createInput: IDiscussionboardConfiguration.ICreate = {
    name: `test-config-unique-${RandomGenerator.hash()}`,
    settings_json: JSON.stringify({ postsPerDay: 10, moderation: true }),
    description: "Initial config for update success test",
  };
  const created =
    await api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      { body: createInput },
    );
  typia.assert(created);

  // 2. Update mutable fields (name, settings_json, description)
  const updateInput: IDiscussionboardConfiguration.IUpdate = {
    name: `${createInput.name}-updated`,
    settings_json: JSON.stringify({ postsPerDay: 42, moderation: false }),
    description: "Config updated for persistence and uniqueness validation.",
  };
  const updated =
    await api.functional.prefix.admin.discussionboardConfigurations.update(
      connection,
      {
        configurationId: created.id,
        body: updateInput,
      },
    );
  typia.assert(updated);

  // 3. Assert that the update mutated the correct record and changes are reflected
  TestValidator.equals("update: id unchanged")(updated.id)(created.id);
  TestValidator.notEquals("update: name changed")(updated.name)(
    createInput.name,
  );
  TestValidator.equals("update: new name")(updated.name)(updateInput.name);
  TestValidator.equals("update: settings_json")(updated.settings_json)(
    updateInput.settings_json,
  );
  TestValidator.equals("update: description")(updated.description)(
    updateInput.description,
  );

  // 4. Attempt to create another configuration with the updated (now-taken) name; expect error for uniqueness constraint
  await TestValidator.error("creation with non-unique name fails")(async () => {
    await api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      {
        body: {
          name: updateInput.name!,
          settings_json: JSON.stringify({ dummy: true }),
          description: "Should fail due to non-unique name",
        },
      },
    );
  });
}

