import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAppeal";
import type { null } from "@ORGANIZATION/PROJECT-api/lib/structures/null";

/**
 * 테스트 회원이 자신의 어필(appeal) 레코드를 하드 삭제(hard delete)할 수 있는지 검증합니다.
 *
 * 본 테스트는 회원이 직접 자신이 소유한 어필 데이터를 완전히 삭제할 수 있음을 시나리오로 검증합니다.
 * 먼저 테스트 회원이 자신이 소유한 어필 레코드를 관리자로 생성하고,
 * 이후 회원 API를 통해 해당 appealId로 DELETE를 수행합니다.
 * 삭제 성공 응답(null)을 체크한 후, 같은 id로 다시 조회를 시도하면(실제 Get-by-id API는 부재)
 * 더 이상 해당 레코드가 존재하지 않음을 에러로 검증합니다.
 *
 * [검증 단계]
 * 1. 테스트 회원 소유의 어필 레코드 생성(admin API)
 * 2. 회원 API로 해당 appeal 하드 삭제
 * 3. 삭제 후 null 응답 확인
 * 4. 동일 id로 조회 시 not found(에러) 발생 확인 (Get API 미제공이므로 불가, 에러 시나리오로 대체)
 */
export async function test_api_policyAudit_test_delete_own_appeal_success(
  connection: api.IConnection,
) {
  // 1. 테스트 회원 UUID와 현재 시각 준비
  const testMemberId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  // 1. 테스트 회원 소유의 어필 레코드 생성 (admin API 사용)
  const createBody = {
    appeal_code: `APPEAL-${now.replace(/[-:.TZ]/g, "")}-001`,
    status: "PENDING",
    appellant_id: testMemberId,
    incident_id: null,
    outcome: null,
    created_at: now,
    updated_at: now,
  } satisfies IDiscussionboardAppeal.ICreate;
  const appeal = await api.functional.prefix.admin.policyAudit.appeals.create(
    connection,
    { body: createBody },
  );
  typia.assert(appeal);
  TestValidator.equals("생성된 레코드의 회원 일치")(appeal.appellant_id)(testMemberId);

  // 2. 회원 API로 해당 appeal 하드 삭제
  const delResult = await api.functional.prefix.member.policyAudit.appeals.erase(
    connection,
    { appealId: appeal.id },
  );
  typia.assert(delResult);
  TestValidator.equals("삭제 응답 null 확인")(delResult)(null);

  // 3. 삭제 후 동일 id로 조회 시 not found(에러) 발생 확인
  // 실제 Get-by-id API는 제공되지 않으므로, 해당 id 재생성 시 에러로 대체 검증
  await TestValidator.error("이미 삭제된 appeal id로 재생성 시 에러")(async () => {
    await api.functional.prefix.member.policyAudit.appeals.erase(
      connection,
      { appealId: appeal.id },
    );
  });
}

