import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAppeal } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAppeal";
import type { IDiscussionboardAppeals } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAppeals";

/**
 * Validate that an admin can update any appeal, regardless of its creator.
 *
 * This test ensures:
 * 1. An appeal is created (with simulated member ownership), and then updated as admin for status and outcome fields.
 * 2. Admin privilege applies: admin can update any eligible field regardless of origin.
 * 3. All updates respect schema: only fields present in update DTO are changeable and constraints are enforced.
 * 4. No unintended fields are changed in the process; all system constraints hold.
 *
 * Steps:
 * 1. Create a unique appeal (must include a unique code, reasonable status, owner id, and timestamp fields).
 * 2. As admin, update the appeal's status and outcome fields with new, valid values.
 * 3. Validate response: ensure only status/outcome updated; other properties are unchanged; ID remains, timestamps are properly handled.
 *
 * This confirms privilege and schema-constraint mechanics for the appeals update admin endpoint.
 */
export async function test_api_prefix_admin_policyAudit_appeals_test_admin_update_any_appeals_status_and_outcome(
  connection: api.IConnection
) {
  // 1. Create a new appeal entry as setup (simulated as "member" for business logic; API only exposes admin endpoint).
  const uniqueAppealCode = `APPEAL-${new Date().toISOString().slice(0,10).replace(/-/g, "")}-${typia.random<number & tags.Type<'uint32'> & tags.Minimum<1> & tags.Maximum<999>>>().toString().padStart(3, "0")}`;
  const baseAppeal = await api.functional.prefix.admin.policyAudit.appeals.create(connection, {
    body: {
      appeal_code: uniqueAppealCode,
      status: "PENDING",
      outcome: null,
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
      // Simulate a member creator by supplying a random UUID for "appellant_id"
      appellant_id: typia.random<string & tags.Format<"uuid">>(),
      incident_id: null
    } satisfies IDiscussionboardAppeal.ICreate
  });
  typia.assert(baseAppeal);

  // 2. As admin, update status and outcome fields via admin endpoint
  const updatedStatus = "UPHELD";
  const updatedOutcome = "Ban lifted after review";
  const updated = await api.functional.prefix.admin.policyAudit.appeals.update(connection, {
    appealId: baseAppeal.id,
    body: {
      status: updatedStatus,
      outcome: updatedOutcome
    } satisfies IDiscussionboardAppeals.IUpdate
  });
  typia.assert(updated);

  // 3. Validate updated vs unchanged fields
  TestValidator.equals("appeal id unchanged")(updated.id)(baseAppeal.id);
  TestValidator.equals("appeal code unchanged")(updated.appeal_code)(baseAppeal.appeal_code);
  TestValidator.equals("status updated")(updated.status)(updatedStatus);
  TestValidator.equals("outcome updated")(updated.outcome)(updatedOutcome);
  TestValidator.equals("appellant unchanged")(updated.appellant_id)(baseAppeal.appellant_id);
  TestValidator.equals("incident unchanged")(updated.incident_id)(baseAppeal.incident_id);
  TestValidator.predicate("updated_at must reflect change")(
    new Date(updated.updated_at).getTime() >= new Date(baseAppeal.updated_at).getTime()
  );
  TestValidator.equals("created_at unchanged")(updated.created_at)(baseAppeal.created_at);
}

