import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";

/**
 * Test that the authenticated poll creator can successfully hard-delete their
 * own poll.
 *
 * Business context:
 *
 * - Only the poll creator may perform a hard delete of their own poll. There is
 *   no soft delete or archived flag; the action is irreversible and permanently
 *   removes the poll from the system.
 * - All necessary setup must be performed (member registration, thread and poll
 *   creation) before deletion.
 * - After deletion, the system should guarantee the poll is not found in listings
 *   or detail retrieval.
 *
 * Test steps:
 *
 * 1. Register a new member (assign unique id and creation timestamp)
 * 2. Create a new thread, associated with a category and using the member as
 *    creator
 * 3. Create a poll attached to that thread (authenticated as the member)
 * 4. Hard-delete the poll via the erase endpoint (/my/polls/{id}) as the original
 *    creator
 * 5. Attempt to retrieve (list/detail) the poll after deletion – should receive
 *    not-found or error
 * 6. Assert that the poll has been permanently erased and cannot be restored or
 *    accessed
 */
export async function test_api_member_test_delete_own_poll_successful(
  connection: api.IConnection,
) {
  // 1. Register member (for poll ownership)
  const memberId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const memberCreatedAt: string & tags.Format<"date-time"> =
    new Date().toISOString() as any;
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId,
        created_at: memberCreatedAt,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a new thread for poll attachment
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        // discussionboard_member_id is ignored on input per DTO – server assigns by context, so do not supply
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "Test Poll Thread",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString() as any,
