  TestValidator.equals("empty with random moderator_id")(none1.data.length)(0);
  // report_id
  const none2 = await api.functional.prefix.admin.moderationActions.index(
    connection,
    {
      body: { report_id: randomUuid },
    },
  );
  typia.assert(none2);
  TestValidator.equals("empty with random report_id")(none2.data.length)(0);

  // 4. 페이지네이션: 페이지 수/limit 조합, 데이터 중복 없는지 확인
  if (allActions.pagination.pages > 1) {
    const limit = 2;
    const page1 = await api.functional.prefix.admin.moderationActions.index(
      connection,
      {
        body: {
          page: 1,
          limit,
        },
      },
    );
    const page2 = await api.functional.prefix.admin.moderationActions.index(
      connection,
      {
        body: {
          page: 2,
          limit,
        },
      },
    );
    typia.assert(page1);
    typia.assert(page2);
    // 두 페이지가 중복된 데이터 id를 갖지 않아야 한다
    const idsPage1 = page1.data.map((a) => a.id);
    const idsPage2 = page2.data.map((a) => a.id);
    TestValidator.predicate("no overlap between pages")(
      idsPage1.every((id) => !idsPage2.includes(id)),
    );
  }

  // 5. 과도한/최대 page, limit 테스트 (limit 200, page: 큰 수)
  const outOfBoundPage =
    await api.functional.prefix.admin.moderationActions.index(connection, {
      body: {
        page: 9999,
        limit: 200,
      },
    });
  typia.assert(outOfBoundPage);
  TestValidator.equals("empty for high page")(outOfBoundPage.data.length)(0);

  // 6. (권한 거부) 관리자 권한 없는 connection/context에서는 403 등 에러 발생해야 함
  // 실제로는 connection을 로그인/권한별로 분리해서 테스트(여기선 가정/자동화환경 대응)
  if (typeof globalThis.createNonAdminConnection === "function") {
    const nonAdminConn = (await globalThis.createNonAdminConnection()) as api.IConnection;
    await TestValidator.error("non-admin should be forbidden")(async () => {
      await api.functional.prefix.admin.moderationActions.index(nonAdminConn, {
        body: {},
      });
    });
  }
}

