          created_at: new Date().toISOString() as string &
            tags.Format<"date-time">,
        },
      },
    );
    typia.assert(member1);

    const memberId2: string & tags.Format<"uuid"> = typia.random<
      string & tags.Format<"uuid">
    >();
    const member2 = await api.functional.prefix.member.actors.members.create(
      connection,
      {
        body: {
          id: memberId2,
          created_at: new Date().toISOString() as string &
            tags.Format<"date-time">,
        },
      },
    );
    typia.assert(member2);

    // 2. As member1, create a notification (simulate login context as member1)
