    });
    const notification =
      await api.functional.prefix.member.my.discussionboardNotifications.create(
        connection,
        {
          body: {
            type: "mention",
            title: "Test notification",
            body: "This notification is for member1.",
            url: "/thread/123",
            opened: false,
          },
        },
