    await TestValidator.error("updating nonexistent notification throws error")(
      () =>
        api.functional.prefix.member.my.discussionboardNotifications.update(
          connection,
          {
            notificationId: typia.random<string & tags.Format<"uuid">>(),
            body: {
              title: "Attempt update",
            },
          },
        ),
    );

    // 3.b. Attempt to update member1's notification as member2 (should fail)
    await TestValidator.error("cannot update another member's notification")(
      () =>
        api.functional.prefix.member.my.discussionboardNotifications.update(
          connection,
          {
            notificationId: notification.id,
            body: {
              title: "Hacked update by member2",
            },
          },
        ),
    );
  } finally {
    // Restore headers to keep test environment clean
    Object.assign(connection.headers, prevHeaders);
  }
}

