import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/ISuspension";
import type { IPageISuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageISuspension";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test list and filter of suspensions including pagination for moderator
 * access.
 *
 * This test ensures the following:
 *
 * 1. Multiple suspension records exist, created via dependency.
 * 2. Suspensions can be retrieved using combinations of filters (moderator_id,
 *    suspended_member_id, suspension reason, and suspension date window).
 * 3. Pagination parameters are handled correctly.
 * 4. Results reflect accurate filtering, not just all suspensions.
 * 5. Only authorized users (e.g., moderators) can access these endpoints.
 *
 * Steps:
 *
 * 1. Create 4+ suspension records with varying moderator_id, suspended_member_id,
 *    and time ranges.
 * 2. Retrieve all suspensions with no filters and capture total count.
 * 3. Filter by 1 moderator_id: result should only include suspensions by that
 *    moderator.
 * 4. Filter by suspended_member_id: result should only include suspensions for
 *    that member.
 * 5. Use both filters together—AND logic should hold in result.
 * 6. Use suspension window filters to capture partial subsets.
 * 7. Use pagination (limit=2) and check pagination fields and results for page 1
 *    and page 2.
 * 8. Attempt to call as a non-moderator (simulate with a connection having no
 *    moderator role), assert access is denied (if RBAC enforced).
 */
export async function test_api_prefix_moderator_suspensions_test_list_suspensions_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // (1) Create multiple diverse suspension records for robust testing
  const suspensionInputs = ArrayUtil.repeat(4)(() => {
    return {
      moderator_id: typia.random<string & tags.Format<"uuid">>(),
      suspended_member_id: typia.random<string & tags.Format<"uuid">>(),
      suspension_reason: RandomGenerator.paragraph()(),
      suspension_started_at: RandomGenerator.pick([
        new Date(Date.now() - 86400000 * 5).toISOString(), // 5 days ago
        new Date(Date.now() - 86400000 * 2).toISOString(), // 2 days ago
        new Date(Date.now()).toISOString(), // now
      ]),
      suspension_ends_at: RandomGenerator.pick([
        null,
        new Date(Date.now() + 86400000 * 5).toISOString(), // 5 days later
      ]),
    } satisfies ISuspension.ICreate;
  });
  const suspensions: ISuspension[] = [];
  for (const input of suspensionInputs) {
    const suspension = await api.functional.prefix.moderator.suspensions.create(
      connection,
      { body: input },
    );
    typia.assert(suspension);
    suspensions.push(suspension);
  }
  // (2) Get all suspensions (no filters)
  const allPage = await api.functional.prefix.moderator.suspensions.index(
    connection,
    { body: {} },
  );
  typia.assert(allPage);
