import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IPostEditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostEditLog";

/**
 * 게시글 수정 로그 변경 API의 정상 동작과 각종 오류(권한, schema 위반) 케이스를 검증합니다.
 *
 * - 멤버가 자신이 소유한 post edit log(change_summary, change_details만 수정 가능)를 정상적으로 업데이트할
 *   수 있음
 * - 소유하지 않은 로그, 스키마에 맞지 않는 요청(body 누락/허용 외 필드 포함 등) 보내면 정확히 에러 처리됨
 * - 모든 동작에서 타입, business rule, schema 적합성 보장
 *
 * 구현 상 한계로 edit log 생성은 typia.random으로 대체(실제로는 post 수정 후 log id 추출 필요)
 *
 * 1. 토론 게시글 작성(멤버 본인)
 * 2. (실제라면 글 수정 → postEditLog 생성 필요, 샘플에선 무작위 생성)
 * 3. 정상: 본인 소유 edit log에 허용 필드만으로 update → 내용 변경 여부 확인
 * 4. 본인 소유 아님: 타인 edit log id로 update 시도 → 에러
 * 5. 요청 body 없이 update 시도 → 에러
 * 6. 허용 안된 필드(body 내 id 등) 포함 update 시도 → schema validation 에러
 */
export async function test_api_prefix_member_my_threadsPosts_postEditLogs_test_update_post_edit_log_member_owned_valid_and_invalid(
  connection: api.IConnection,
) {
  // 1. 게시글 생성 (멤버 본인)
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
        body: "테스트 본문",
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(post);

  // 2. edit log record 생성 (실전은 글 수정 후, 샘플은 typia.random 대체)
  const myEditLog = typia.random<IPostEditLog>();

  // 3. 정상 시나리오: 허용 필드만으로 update 수행
  const updated =
    await api.functional.prefix.member.my.threadsPosts.postEditLogs.update(
      connection,
      {
        id: myEditLog.id,
        body: {
          change_summary: "수정: 첫번째 변경",
          change_details: "from '\u003c초안\u003e' to '\u003c수정본\u003e'",
        } satisfies IPostEditLog.IUpdate,
      },
    );
  typia.assert(updated);
  TestValidator.equals("id 동일")(updated.id)(myEditLog.id);
  TestValidator.equals("change_summary 반영")(updated.change_summary)(
    "수정: 첫번째 변경",
  );
  TestValidator.equals("change_details 반영")(updated.change_details)(
    "from '\u003c초안\u003e' to '\u003c수정본\u003e'",
  );

  // 4. 소유하지 않은 edit log id로 update 시도 → 에러
  await TestValidator.error("타인 edit log update 차단")(async () => {
    await api.functional.prefix.member.my.threadsPosts.postEditLogs.update(
      connection,
      {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: {
          change_summary: "해킹 시도",
          change_details: "should fail",
        },
      },
    );
  });

  // 5. update 요청 body 없이 시도 → 에러
  await TestValidator.error("update body 누락시 에러")(async () => {
    // @ts-expect-error intentionally omitted body
    await api.functional.prefix.member.my.threadsPosts.postEditLogs.update(
      connection,
      {
        id: myEditLog.id,
      } as any,
    );
  });

  // 6. 스키마 허용되지 않은 필드 포함 update 시도 → 에러
  await TestValidator.error("허용 외 필드 update 거부")(async () => {
    // @ts-expect-error forbidden fields in body
    await api.functional.prefix.member.my.threadsPosts.postEditLogs.update(
      connection,
      {
        id: myEditLog.id,
        body: {
          change_summary: "fail",
          change_details: "fail",
          id: "forbidden",
          discussionboard_post_id: "not-allowed",
          edit_member_id: "not-allowed",
          created_at: new Date().toISOString(),
        },
      } as any,
    );
  });
}

