import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";

/**
 * Validate retrieval of a single discussion board section by sectionId.
 *
 * This test covers both successful fetching with a valid sectionId and error
 * handling for a non-existent ID:
 *
 * 1. Create a new section using the admin API, persist its key fields for
 *    verification.
 * 2. Retrieve the section by its newly assigned sectionId—verify all returned
 *    fields (id, configuration ref, name, description, order, enabled) match
 *    the originally created data (within business rules for auto-generated ids,
 *    nullable fields, etc).
 * 3. Attempt to retrieve a section with a random UUID that does not belong to any
 *    section (simulate a missing or unauthorized access)—expect a 404 'Not
 *    Found' error.
 * 4. This validates both normal operation and proper error response for invalid
 *    sectionId access.
 */
export async function test_api_discussionboardSections_test_get_section_details_by_id_with_valid_and_invalid_ids(
  connection: api.IConnection,
) {
  // 1. Create a new section for a known valid ID
  const createInput: IDiscussionboardSection.ICreate = {
    discussionboard_configuration_id: typia.random<
      string & tags.Format<"uuid">
    >(),
    name: RandomGenerator.alphabets(12),
    description: RandomGenerator.paragraph()(),
    order: typia.random<number & tags.Type<"int32">>(),
    enabled: true,
  };
  const createdSection =
    await api.functional.prefix.admin.discussionboardSections.create(
      connection,
      { body: createInput },
    );
  typia.assert(createdSection);

  // 2. Retrieve the section by its assigned sectionId
  const fetchedSection =
    await api.functional.prefix.admin.discussionboardSections.at(connection, {
      sectionId: createdSection.id,
    });
  typia.assert(fetchedSection);

  // 3. Check all relevant fields match the created data
  TestValidator.equals("discussionboard_configuration_id")(
    fetchedSection.discussionboard_configuration_id,
  )(createInput.discussionboard_configuration_id);
  TestValidator.equals("name")(fetchedSection.name)(createInput.name);
  TestValidator.equals("description")(fetchedSection.description)(
    createInput.description,
  );
  TestValidator.equals("order")(fetchedSection.order)(createInput.order);
  TestValidator.equals("enabled")(fetchedSection.enabled)(createInput.enabled);

  // 4. Negative test: use a new random UUID guaranteed not to match the created section
  let invalidSectionId = typia.random<string & tags.Format<"uuid">>();
  // Simple guarantee we don't match the real ID (low collision probability)
  while (invalidSectionId === createdSection.id) {
    invalidSectionId = typia.random<string & tags.Format<"uuid">>();
  }
  await TestValidator.error("404 Not Found for random UUID")(async () => {
    await api.functional.prefix.admin.discussionboardSections.at(connection, {
      sectionId: invalidSectionId,
    });
  });
}

