import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardConfiguration";
import type { IDiscussionboardSection } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardSection";

/**
 * Test the creation and validation of discussion board section creation API.
 *
 * 1. Create a valid discussion board configuration (dependency) and use its id for
 *    section creation.
 * 2. Create a section: use valid properties (configuration id, unique name,
 *    description, order, enabled). Validate the section is created and fields
 *    match input values.
 * 3. Create a second section with the SAME name for EITHER the same config or a
 *    different one. Validate that a uniqueness constraint error is thrown (name
 *    is unique-per-table, not just per-config).
 * 4. Try creating a section with an invalid discussionboard_configuration_id:
 *    expect FK violation.
 * 5. Edge case validation - create with each required field missing (one at a
 *    time): should trigger validation errors.
 */
export async function test_api_prefix_admin_discussionboardSections_test_create_section_with_valid_and_duplicate_data(
  connection: api.IConnection,
) {
  // 1. Create a valid discussion board configuration
  const configurationInput: IDiscussionboardConfiguration.ICreate = {
    name: `cfg_${RandomGenerator.alphaNumeric(8)}`,
    settings_json: JSON.stringify({ allowPosts: true, moderation: "admin" }),
    description: "Test configuration for section tests",
  };
  const configuration =
    await api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      { body: configurationInput },
    );
  typia.assert(configuration);

  // 2. Create a new section with valid properties
  const sectionInput: IDiscussionboardSection.ICreate = {
    discussionboard_configuration_id: configuration.id,
    name: `section_${RandomGenerator.alphaNumeric(8)}`,
    description: "Test section description",
    order: typia.random<number & tags.Type<"int32">>(),
    enabled: true,
  };
  const section =
    await api.functional.prefix.admin.discussionboardSections.create(
      connection,
      { body: sectionInput },
    );
  typia.assert(section);
  TestValidator.equals("configuration id")(
    section.discussionboard_configuration_id,
  )(sectionInput.discussionboard_configuration_id);
  TestValidator.equals("name")(section.name)(sectionInput.name);
  TestValidator.equals("order")(section.order)(sectionInput.order);
  TestValidator.equals("enabled")(section.enabled)(sectionInput.enabled);
  TestValidator.equals("description")(section.description)(
    sectionInput.description,
  );

  // 3. Attempt to create with duplicate name (should fail on uniqueness)
  // Optionally, use a new config for even stronger validation
  const secondConfigInput: IDiscussionboardConfiguration.ICreate = {
    name: `cfg_${RandomGenerator.alphaNumeric(8)}`,
    settings_json: JSON.stringify({ allowPosts: false, moderation: "user" }),
    description: "Second config for duplicate name edge check",
  };
  const secondConfig =
    await api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      { body: secondConfigInput },
    );
  typia.assert(secondConfig);
  // Try duplicate name on the new (or same) config
  const duplicateInput: IDiscussionboardSection.ICreate = {
    ...sectionInput,
    discussionboard_configuration_id: secondConfig.id,
    order: sectionInput.order + 1,
    // use the EXACT same name to trigger global constraint
  };
  await TestValidator.error("duplicate section name should fail")(async () => {
    await api.functional.prefix.admin.discussionboardSections.create(
      connection,
      { body: duplicateInput },
    );
  });

  // 4. Attempt creation with invalid configuration id
  const invalidFkInput: IDiscussionboardSection.ICreate = {
    ...sectionInput,
    name: `section_${RandomGenerator.alphaNumeric(8)}`,
    discussionboard_configuration_id: typia.random<
      string & tags.Format<"uuid">
    >(), // random uuid likely non-existent
  };
  await TestValidator.error("invalid FK should fail")(async () => {
    await api.functional.prefix.admin.discussionboardSections.create(
      connection,
      { body: invalidFkInput },
    );
  });

  // 5. Edge cases: Omit each required field and expect validation errors
  // Required fields: discussionboard_configuration_id, name, order, enabled
  // (description is optional)
  const basePartial: Omit<
    IDiscussionboardSection.ICreate,
    "discussionboard_configuration_id" | "name" | "order" | "enabled"
  > = {
    description: "Partial for field omission cases",
  };
  const omitFieldCases: Array<Partial<IDiscussionboardSection.ICreate>> = [
    // Omitting configuration id
    {
      ...basePartial,
      name: `miss_cfg_${RandomGenerator.alphaNumeric(6)}`,
      order: typia.random<number & tags.Type<"int32">>(),
      enabled: true,
    },
    // Omitting name
    {
      ...basePartial,
      discussionboard_configuration_id: configuration.id,
      order: typia.random<number & tags.Type<"int32">>(),
      enabled: true,
    },
    // Omitting order
    {
      ...basePartial,
      discussionboard_configuration_id: configuration.id,
      name: `miss_order_${RandomGenerator.alphaNumeric(6)}`,
      enabled: true,
    },
    // Omitting enabled
    {
      ...basePartial,
      discussionboard_configuration_id: configuration.id,
      name: `miss_enabled_${RandomGenerator.alphaNumeric(6)}`,
      order: typia.random<number & tags.Type<"int32">>(),
    },
  ];
  for (const partialInput of omitFieldCases) {
    await TestValidator.error("missing required field validation error")(
      async () => {
        await api.functional.prefix.admin.discussionboardSections.create(
          connection,
          { body: partialInput as any },
        );
      },
    );
  }
}

