 *
 * Steps:
 *
 * 1. Call the /prefix/admin//discussionboardCategories endpoint with an empty
 *    filter object.
 * 2. Assert that the API outputs a valid IPageIDiscussionboardCategory structure:
 *    both data and pagination fields are present with the correct types.
 * 3. Validate the 'pagination' fields: current, limit, records, and pages are
 *    present and in valid int32 ranges.
 * 4. Ensure 'data' is an array (which may be empty or populated). For each item,
 *    confirm it is a valid IDiscussionboardCategory and that 'enabled' is
 *    true.
 * 5. The test should pass regardless of data being empty or not, but pagination
 *    structure must always be valid.
 */
export async function test_api_discussionboardCategories_test_list_discussionboard_categories_with_default_pagination_and_no_filters(
  connection: api.IConnection,
) {
  // 1. Call the endpoint with an empty filter (no fields specified)
  const output =
    await api.functional.prefix.admin.discussionboardCategories.index(
      connection,
