      output.pagination.current >= 1,
  );
  TestValidator.predicate("pagination limit is positive int32")(
    Number.isInteger(output.pagination.limit) && output.pagination.limit >= 1,
  );
  TestValidator.predicate("pagination records is int32 >= 0")(
