 *
 * 1. Create an admin assignment for the authenticated user (dependency)
 * 2. Attempt an allowed update (modify created_at)
 * 3. Confirm the response reflects the correct changes (created_at updated, id
 *    unchanged)
 * 4. (Negative, runtime only) Attempt updating with a mismatched id (path vs body)
 *    and confirm error if allowed by SDK and schema
 */
export async function test_api_prefix_admin_my_actors_admins_test_update_own_admin_assignment_metadata_success(
