import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IWarningLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IWarningLog";

/**
 * Validate that an admin can fetch any moderator-issued warning log by its
 * UUID.
 *
 * Ensures admin access is not restricted by log issuer or recipient, and
 * verifies full log detail is returned.
 *
 * Steps:
 *
 * 1. Create multiple warning logs using moderator endpoint, with varying
 *    moderator_id and warned_member_id.
 * 2. For each created log, use the admin 'get by id' endpoint to fetch by PK.
 * 3. Assert that the fetched log matches all fields (id, moderator_id,
 *    warned_member_id, warning_reason, issued_at) of the original.
 * 4. Attempt to fetch a non-existent id and confirm that error is thrown (e.g.,
 *    404 error).
 * 5. Validate no difference in admin retrieval whether the creator/recipient is
 *    the same or different.
 *
 * Note: Admin authentication is assumed to be present via the connection
 * context, since explicit admin login endpoints are not provided in the API
 * set.
 */
export async function test_api_warningLogs_test_get_warning_log_by_id_with_admin_role(
  connection: api.IConnection,
) {
  // 1. Create multiple warning logs as different moderators and warned members
  const moderator1 = typia.random<string & tags.Format<"uuid">>();
  const moderator2 = typia.random<string & tags.Format<"uuid">>();
  const warned_member1 = typia.random<string & tags.Format<"uuid">>();
  const warned_member2 = typia.random<string & tags.Format<"uuid">>();
  const createdLogs: IWarningLog[] = [];

  for (const [moderator_id, warned_member_id] of [
    [moderator1, warned_member1],
    [moderator1, warned_member2],
    [moderator2, warned_member1],
    [moderator2, warned_member2],
  ]) {
    const warning_reason = `Test warning from ${moderator_id} to ${warned_member_id}`;
    const issued_at = new Date().toISOString();
    const log = await api.functional.prefix.moderator.warningLogs.create(
      connection,
      {
        body: {
          moderator_id,
          warned_member_id,
          warning_reason,
          issued_at,
        } satisfies IWarningLog.ICreate,
      },
    );
    typia.assert(log);
    createdLogs.push(log);
    // Field-by-field check
    TestValidator.equals("moderator_id matches")(log.moderator_id)(
      moderator_id,
    );
    TestValidator.equals("warned_member_id matches")(log.warned_member_id)(
      warned_member_id,
    );
    TestValidator.equals("warning_reason matches")(log.warning_reason)(
      warning_reason,
    );
    TestValidator.equals("issued_at matches")(log.issued_at)(issued_at);
  }

  // 2. For each log, retrieve as admin by id and check for fidelity
  for (const log of createdLogs) {
    const result = await api.functional.prefix.admin.warningLogs.at(
      connection,
      {
        id: log.id,
      },
    );
    typia.assert(result);
    TestValidator.equals("id matches")(result.id)(log.id);
    TestValidator.equals("moderator_id matches")(result.moderator_id)(
      log.moderator_id,
    );
    TestValidator.equals("warned_member_id matches")(result.warned_member_id)(
      log.warned_member_id,
    );
    TestValidator.equals("warning_reason matches")(result.warning_reason)(
      log.warning_reason,
    );
    TestValidator.equals("issued_at matches")(result.issued_at)(log.issued_at);
  }

  // 3. Attempt to fetch a non-existent warning log id (should throw error)
  await TestValidator.error("fetching non-existent id throws error")(
    async () => {
      await api.functional.prefix.admin.warningLogs.at(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

