import api from "@ORGANIZATION/PROJECT-api";
import type { IWarningLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IWarningLog";

/**
 * Test the successful and unsuccessful creation of a moderator warning log.
 *
 * This test ensures that a moderator can correctly create a warning log for a
 * member, and that business rules, schema constraints, and validation logic are
 * enforced.
 *
 * 1. Prepare all required properties: moderator_id, warned_member_id,
 *    warning_reason, issued_at (ensure valid UUIDs and date-time format).
 * 2. Call the API to create a warning log (POST /prefix/moderator//warningLogs).
 * 3. Assert that the API response includes all schema fields, that a unique UUID
 *    PK is generated, and that values match those provided.
 * 4. Attempt to create a warning log while omitting a required property (e.g.,
 *    warning_reason) and verify that the API returns a validation error.
 */
export async function test_api_warningLogs_test_create_warning_log_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Prepare valid warning log input.
  const moderatorId = typia.random<string & tags.Format<"uuid">>();
  const warnedMemberId = typia.random<string & tags.Format<"uuid">>();
  const input: IWarningLog.ICreate = {
    moderator_id: moderatorId,
    warned_member_id: warnedMemberId,
    warning_reason: "Test violation of community guidelines.",
    issued_at: new Date().toISOString(),
  };

  // 2. Call the API to create a warning log.
  const output = await api.functional.prefix.moderator.warningLogs.create(
    connection,
    { body: input },
  );
  typia.assert(output);

  // 3. Assert all fields in the response are correct and present.
  TestValidator.equals("moderator_id matches")(output.moderator_id)(
    moderatorId,
  );
  TestValidator.equals("warned_member_id matches")(output.warned_member_id)(
    warnedMemberId,
  );
  TestValidator.equals("reason matches")(output.warning_reason)(
    input.warning_reason,
  );
  TestValidator.equals("issued_at matches")(output.issued_at)(input.issued_at);
  TestValidator.predicate("valid uuid for PK")(
    !!output.id && output.id.length > 0,
  );

  // 4. Negative test: omit required field and expect a validation error.
  await TestValidator.error("Missing required warning_reason should fail")(
    async () => {
      const incompleteInput = {
        moderator_id: typia.random<string & tags.Format<"uuid">>(),
        warned_member_id: typia.random<string & tags.Format<"uuid">>(),
        issued_at: new Date().toISOString(),
        // warning_reason intentionally omitted
      } as IWarningLog.ICreate;
      await api.functional.prefix.moderator.warningLogs.create(connection, {
        body: incompleteInput,
      });
    },
  );
}

