 * Validates that a member can create a content report with all required schema
 * fields, and the returned object reflects the input plus a new generated ID.
 * Also tests that the API enforces correct references (e.g., post must exist)
 * and produces an error for foreign key constraint violation.
 *
 * Steps:
 *
 * 1. Prepare valid report fields (simulate member and post UUIDs, text, required
 *    enums/dates).
 * 2. Submit as member and verify output fields, including a generated id.
 * 3. Attempt to create a report for non-existent post, expect error.
 */
export async function test_api_contentReports_test_create_content_report_as_member_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Prepare member and post UUIDs (simulate as if they exist)
  const reported_post_id: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const reporter_member_id: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const report_reason = "Spam or inappropriate content";
  const status: "pending" = "pending";
  const reported_at: string & tags.Format<"date-time"> =
    new Date().toISOString() as string & tags.Format<"date-time">;

  // 2. Create a content report (happy path)
  const input: IContentReport.ICreate = {
    reported_post_id,
    reporter_member_id,
    report_reason,
    status,
    reported_at,
  };
  const output = await api.functional.prefix.member.contentReports.create(
    connection,
    { body: input },
  );
  typia.assert(output);
  TestValidator.equals("report.post")(output.reported_post_id)(
    input.reported_post_id,
  );
  TestValidator.equals("report.member")(output.reporter_member_id)(
    input.reporter_member_id,
  );
  TestValidator.equals("report.reason")(output.report_reason)(
    input.report_reason,
  );
  TestValidator.equals("report.status")(output.status)(input.status);
  TestValidator.equals("report.reported_at")(output.reported_at)(
    input.reported_at,
  );
  TestValidator.predicate("report.id present & uuid")(
    !!output.id && typeof output.id === "string",
  );

  // 3. Create a report for a non-existent post (should error)
  const nonExistentPostId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const errorInput: IContentReport.ICreate = {
    ...input,
    reported_post_id: nonExistentPostId,
  };
  await TestValidator.error("non-existent post foreign key error")(async () => {
    await api.functional.prefix.member.contentReports.create(connection, {
      body: errorInput,
    });
  });
}

