import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/ISuspension";
import type { IPageISuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageISuspension";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 테스트: 관리자가 다양한 필터, 검색어, 페이지네이션 조건으로 정지 이력 목록을 조회한다.
 *
 * 이 시나리오에서는 모더레이터 권한으로 2건의 서로 다른 모더레이터, 정지 대상, 사유를 가진 회원 정지 이력을 우선 생성한다. 이후 관리자
 * 권한(E2E컨텍스트)에서 정지 이력 목록을 아래와 같은 다양한 조건으로 조회한다. 주요 검증 포인트:
 *
 * - 각 필터(모더레이터/대상/사유)별 정상 반환 여부
 * - 이유(사유)의 부분검색(검색엔진 동작 확인)
 * - 시작일/종료일 범위 필터링
 * - Pagination(1페이지 1건 등) 및 전체 건수/개수 검증
 * - 잘못된 uuid, 지원하지 않는 필드 등 에러 케이스 확인
 * - (인증/권한 테스트는 제공 API 제한으로 구현 불가)
 *
 * [테스트 흐름]
 *
 * 1. 모더레이터가 서로 다른 2건의 회원 정지 이력을 생성한다.
 * 2. 관리자가 전체 목록 조회시 두 건 모두 반환됨을 확인한다.
 * 3. 모더레이터ID별, 정지회원ID별, 사유(검색), 시작/종료일자(between) 등 각 필터 조합을 검증한다.
 * 4. 1건당 1페이지(2페이지 요청 포함) 등 페이지네이션 동작 및 전체카운트 검증
 * 5. 각종 에러(잘못된 uuid, 지원X필드) 발생 케이스 검증
 * 6. (권한/계정전환: 실제 구현 불가로 스킵)
 */
export async function test_api_suspensions_test_list_suspensions_with_various_filters_pagination_and_search(
  connection: api.IConnection,
) {
  // ========== 1. 모더레이터가 사전 정지 객체 2건 생성 ========== //
  const modId1 = typia.random<string & tags.Format<"uuid">>();
  const modId2 = typia.random<string & tags.Format<"uuid">>();
  const memberId1 = typia.random<string & tags.Format<"uuid">>();
  const memberId2 = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();
  const yesterday = new Date(now.getTime() - 86400000).toISOString();
  const tomorrow = new Date(now.getTime() + 86400000).toISOString();

  // 첫 번째 정지 이력 (modId1, memberId1)
  const suspension1 = await api.functional.prefix.moderator.suspensions.create(
    connection,
    {
      body: {
        moderator_id: modId1,
        suspended_member_id: memberId1,
        suspension_reason: "inappropriate content",
        suspension_started_at: yesterday,
        suspension_ends_at: tomorrow,
      },
    },
  );
  typia.assert(suspension1);

  // 두 번째 정지 이력 (modId2, memberId2)
  const suspension2 = await api.functional.prefix.moderator.suspensions.create(
    connection,
    {
      body: {
        moderator_id: modId2,
        suspended_member_id: memberId2,
        suspension_reason: "spam violation",
        suspension_started_at: now.toISOString(),
        suspension_ends_at: null,
      },
    },
  );
  typia.assert(suspension2);

  // ========== 2. 관리자 권한으로 전체 목록 조회: 두 건 모두 있어야 함 ========== //
  const resAll = await api.functional.prefix.admin.suspensions.index(
    connection,
    { body: {} },
  );
  typia.assert(resAll);
  TestValidator.predicate("모든 정지 이력이 포함됨")(
    resAll.data.some((x) => x.id === suspension1.id),
  );
  TestValidator.predicate("모든 정지 이력이 포함됨")(
    resAll.data.some((x) => x.id === suspension2.id),
  );

  // ========== 3. 각각 필드별 필터 동작 검증 ========== //
  // (A) 모더레이터ID 기준
  const resMod1 = await api.functional.prefix.admin.suspensions.index(
    connection,
    { body: { moderator_id: modId1 } },
  );
  typia.assert(resMod1);
  TestValidator.predicate("모더레이터ID로 필터시 일치만 반환됨")(
    resMod1.data.length >= 1 &&
      resMod1.data.every((x) => x.moderator_id === modId1),
  );

  // (B) 정지대상회원ID 기준
  const resMem2 = await api.functional.prefix.admin.suspensions.index(
    connection,
    { body: { suspended_member_id: memberId2 } },
  );
  typia.assert(resMem2);
  TestValidator.predicate("정지회원ID로 필터시 일치만 반환됨")(
    resMem2.data.length >= 1 &&
      resMem2.data.every((x) => x.suspended_member_id === memberId2),
  );

  // (C) 사유(partial검색)
  const resSpam = await api.functional.prefix.admin.suspensions.index(
    connection,
    { body: { suspension_reason: "spam" } },
  );
  typia.assert(resSpam);
  TestValidator.predicate("사유부분검색 결과 존재")(
    resSpam.data.some((x) => x.suspension_reason.includes("spam")),
  );

  // (D) 기간 필터(시작일 이후)
  const resStartFrom = await api.functional.prefix.admin.suspensions.index(
    connection,
    { body: { suspension_started_at_from: yesterday } },
  );
  typia.assert(resStartFrom);
  TestValidator.predicate("시작일from 이상 포함")(
    resStartFrom.data.some((x) => x.suspension_started_at >= yesterday),
  );

  // (E) 종료일 to
  const resEndTo = await api.functional.prefix.admin.suspensions.index(
    connection,
    { body: { suspension_ends_at_to: tomorrow } },
  );
  typia.assert(resEndTo);
  TestValidator.predicate("종료일to 이하 존재")(
    resEndTo.data.some(
      (x) => x.suspension_ends_at && x.suspension_ends_at <= tomorrow,
    ),
  );

  // ========== 4. pagination 조합(limit=1, page=2) 및 전체건수 검증 ========== //
  const resPage2 = await api.functional.prefix.admin.suspensions.index(
    connection,
    { body: { limit: 1, page: 2 } },
  );
  typia.assert(resPage2);
  TestValidator.equals("1page 1건")(resPage2.data.length)(1);
  TestValidator.predicate("전체카운트는 2이상")(
    resPage2.pagination.records >= 2,
  );

  // ========== 5. 잘못된 입력/지원되지 않는 필드 등 에러 케이스 검증 ========== //
  // (A) uuid 포맷 오류
  await TestValidator.error("uuid아닌 값으로 요청시 에러")(
    async () =>
      await api.functional.prefix.admin.suspensions.index(connection, {
        body: { moderator_id: "INVALID-UUID" } as any,
      }),
  );

  // (B) 미정의필드 요청
  await TestValidator.error("정의불가 필드 요청시 에러")(
    async () =>
      await api.functional.prefix.admin.suspensions.index(connection, {
        body: { not_a_field: "abc" } as any,
      }),
  );

  // ========== 6. 관리자가 아닌 경우(권한부족) 호출 불가 (API 미제공으로 실제 테스트 불가) ========== //
}

