/**
 * Test retrieving a single suspension record by its id (UUID) via the moderator
 * endpoint.
 *
 * This test validates both the correct retrieval of an existing suspension with
 * all expected fields, as well as error scenarios for invalid and unauthorized
 * access attempts. It includes these steps:
 *
 * 1. Create a valid suspension record through the moderator POST endpoint and
 *    capture the returned id.
 * 2. Retrieve that record using the GET endpoint by id, and assert all details
 *    (moderator_id, suspended_member_id, suspension_reason,
 *    suspension_started_at, suspension_ends_at) match what was set at
 *    creation.
 * 3. Attempt to retrieve a suspension using a random (non-existent) id and confirm
 *    a not found error occurs.
 * 4. Simulate access with insufficient permissions and ensure an authorization
 *    error occurs when accessing the GET endpoint (skipped if not supported by
 *    provided APIs).
 */
export async function test_api_prefix_moderator_suspensions_test_retrieve_individual_suspension_by_id_moderator(
  connection: api.IConnection,
) {
  // 1. Create a valid suspension record to use in the retrieval test.
  const createInput: ISuspension.ICreate = {
    moderator_id: typia.random<string & tags.Format<"uuid">>(),
    suspended_member_id: typia.random<string & tags.Format<"uuid">>(),
    suspension_reason: "Violation of rules - spamming",
    suspension_started_at: new Date().toISOString(),
    suspension_ends_at: new Date(
      Date.now() + 24 * 60 * 60 * 1000,
    ).toISOString(), // +1 day
  };
  const created: ISuspension =
    await api.functional.prefix.moderator.suspensions.create(connection, {
      body: createInput,
    });
  typia.assert(created);

  // 2. Retrieve the suspension by id and validate all details match those at creation.
  const retrieved: ISuspension =
    await api.functional.prefix.moderator.suspensions.at(connection, {
      id: created.id,
    });
  typia.assert(retrieved);
  TestValidator.equals("id matches")(retrieved.id)(created.id);
  TestValidator.equals("moderator_id matches")(retrieved.moderator_id)(
    createInput.moderator_id,
  );
  TestValidator.equals("suspended_member_id matches")(
    retrieved.suspended_member_id,
  )(createInput.suspended_member_id);
  TestValidator.equals("reason matches")(retrieved.suspension_reason)(
    createInput.suspension_reason,
  );
  TestValidator.equals("start at matches")(retrieved.suspension_started_at)(
    createInput.suspension_started_at,
  );
  TestValidator.equals("end at matches")(retrieved.suspension_ends_at)(
    createInput.suspension_ends_at,
  );

  // 3. Attempt to retrieve a non-existent id (should error - not found)
