import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";

/**
 * Validate error handling when fetching a member with an invalid/non-existent
 * id.
 *
 * This test ensures the system returns an error when trying to fetch a member
 * entry using a UUID that does not correspond to any registered member, by
 * performing the following steps:
 *
 * 1. Register a new discussionboard_member (to establish the correct system state
 *    and verify normal registration works).
 * 2. Attempt to retrieve a member by a random UUID that is NOT the id of the
 *    created member nor present in the system.
 * 3. Confirm that the system returns an appropriate error (e.g., 404 Not Found or
 *    access/authorization error if the API logic is restrictive).
 * 4. Cross-check: fetch the valid member using its real id and confirm that this
 *    succeeds, ensuring the system is operating as expected.
 */
export async function test_api_member_test_get_member_by_invalid_id_returns_error(
  connection: api.IConnection,
) {
  // 1. Register a new member with valid id/created_at
  const createInput: IDiscussionboardMembers.ICreate = {
    id: typia.random<string & tags.Format<"uuid">>(),
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: createInput,
    },
  );
  typia.assert(member);

  // 2. Attempt to fetch a member with a non-existent UUID
  let invalidId: string & tags.Format<"uuid">;
  do {
    invalidId = typia.random<string & tags.Format<"uuid">>();
  } while (invalidId === member.id);

  await TestValidator.error("fetching non-existent member should error")(
    async () => {
      await api.functional.prefix.member.actors.members.at(connection, {
        id: invalidId,
      });
    },
  );

  // 3. Cross-check: fetch valid member by id to confirm positive case
  const found = await api.functional.prefix.member.actors.members.at(
    connection,
    {
      id: member.id,
    },
  );
  typia.assert(found);
  TestValidator.equals("Returned id matches member id")(found.id)(member.id);
}

