/**
 * Validate update of a discussion board member's 'created_at' field for
 * maintenance or correction.
 *
 * This test ensures:
 *
 * 1. A new member can be registered, which returns the correct id and created_at.
 * 2. The member's 'created_at' property can be updated (e.g., to fix inconsistent
 *    timestamps) using the PUT endpoint.
 * 3. The update endpoint returns the member with the new correct timestamp and
 *    unchanged id.
 * 4. Only the member (self, via my/actors/members/{id}) can update their own
 *    record; verify unauthorized errors are thrown if other users try this
 *    operation.
 *
 * Steps:
 *
 * 1. Register a new member using the registration API and keep the id and initial
 *    created_at.
 * 2. Update the member's created_at field to a new timestamp using the PUT
 *    endpoint.
 * 3. Validate that the response matches the updated created_at and correct id.
 * 4. Simulate an unauthorized access case and ensure a proper error is thrown.
 */
export async function test_api_member_test_update_member_created_at_valid(
  connection: api.IConnection,
) {
  // 1. Register new member
  const initial: IDiscussionboardMembers =
    await api.functional.prefix.member.actors.members.create(connection, {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: typia.random<string & tags.Format<"date-time">>(),
      } satisfies IDiscussionboardMembers.ICreate,
    });
  typia.assert(initial);

  // 2. Update the created_at field
  const newCreatedAt = typia.random<string & tags.Format<"date-time">>();
  const updated: IDiscussionboardMembers =
    await api.functional.prefix.member.my.actors.members.update(connection, {
      id: initial.id,
      body: {
        id: initial.id,
        created_at: newCreatedAt,
      } satisfies IDiscussionboardMembers.IUpdate,
    });
  typia.assert(updated);

  // 3. Validate the update
  TestValidator.equals("id should remain unchanged")(updated.id)(initial.id);
  TestValidator.equals("created_at should be updated")(updated.created_at)(
    newCreatedAt,
  );

  // 4. Unauthorized test - attempt to update with a fresh connection (no user context)
  await TestValidator.error("cannot update another member w/o ownership")(
    async () => {
      const altConnection = { ...connection };
      if (altConnection.headers) delete altConnection.headers["Authorization"];
      await api.functional.prefix.member.my.actors.members.update(
        altConnection,
        {
          id: initial.id,
          body: {
            id: initial.id,
            created_at: typia.random<string & tags.Format<"date-time">>(),
          },
        },
      );
    },
  );
}

