import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { IPageIDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardModerator";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate paginated, filtered, and admin-only retrieval of moderator
 * assignments.
 *
 * Ensures that the admin can retrieve a list of discussion board moderator
 * assignments (discussionboard_moderators) with correct pagination and
 * filter-by-id behavior. This function verifies:
 *
 * 1. Moderator assignment creation (so a known record exists for filtering)
 * 2. List retrieval (admin-only) with no filter returns the new record among the
 *    data
 * 3. List retrieval with id filter returns exactly that record
 * 4. Output pagination structure is present and valid
 * 5. Strictly complies with allowed DTO properties; does not invent unsupported
 *    features or filters
 *
 * Edge cases:
 *
 * - Filtering by non-existent id returns 0 results (optional, can be extended)
 * - Pagination/limit settings cannot be tested as input since not exposed in
 *   IRequest, but output is validated
 * - Non-admin access cannot be tested with available API
 */
export async function test_api_prefix_admin_actors_moderators_test_list_moderator_roles_with_pagination_and_filtering(
  connection: api.IConnection,
) {
  // Step 1: Create a moderator assignment to guarantee at least one known record
  const created: IDiscussionboardModerator =
    await api.functional.prefix.admin.actors.moderators.create(connection, {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      } satisfies IDiscussionboardModerator.ICreate,
    });
  typia.assert(created);

  // Step 2: Retrieve moderator assignments list (no filters)
  const pageAll = await api.functional.prefix.admin.actors.moderators.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(pageAll);
  TestValidator.predicate("should include created moderator")(
    pageAll.data.some((item) => item.id === created.id),
  );
  TestValidator.predicate("all ids are uuid")(
    pageAll.data.every(
      (item) => typeof item.id === "string" && item.id.length > 0,
    ),
  );
  TestValidator.predicate("pagination info valid")(
    typeof pageAll.pagination.current === "number" &&
      typeof pageAll.pagination.limit === "number" &&
      typeof pageAll.pagination.records === "number" &&
      typeof pageAll.pagination.pages === "number",
  );

  // Step 3: Retrieve list filtered by the created id
  const filtered = await api.functional.prefix.admin.actors.moderators.index(
    connection,
    {
      body: { id: created.id },
    },
  );
  typia.assert(filtered);
  TestValidator.equals("filtered: should have exactly one record")(
    filtered.data.length,
  )(1);
  TestValidator.equals("filtered id matches created")(filtered.data[0].id)(
    created.id,
  );
}

