/**
 * Verify that retrieving the moderator assignment list fails when admin
 * authentication is absent or invalid.
 *
 * This test attempts to call the admin-only moderator list API without proper
 * admin authentication. It confirms that:
 *
 * - An unauthenticated (no token) user cannot access the list (should receive an
 *   error)
 * - A user with an invalid or expired admin token cannot access the list (should
 *   receive an error) The error should indicate lack of permission, covering
 *   all unauthorized scenarios. (Non-admin user scenario omitted: no API for
 *   role switching is provided.)
 *
 * Steps:
 *
 * 1. Attempt to retrieve moderator assignments with no authentication
 * 2. Attempt to retrieve moderator assignments with a clearly invalid/bogus token
 * 3. Confirm that all attempts result in an authorization or permission error
 */
export async function test_api_prefix_admin_actors_moderators_test_list_moderator_roles_with_invalid_admin_authentication(
