import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";

/**
 * 본인 모더레이터 역할 배정 정보를 스키마가 허용하는 필드만으로 정상적으로 갱신(update)되는지 검증합니다.
 *
 * [비즈니스 목적 및 테스트 필요성] 이 테스트는 discussionboard_moderators 내에서 본인(/my/)만이 자신의 역할
 * assignment를 수정할 수 있어야 하며, 허용된 필드(id, created_at)만 변경해야 함을 검증합니다.
 *
 * - 관리자가 새로운 모더레이터 권한을 부여하면(assignment 생성),
 * - 해당 멤버(모더레이터)는 /my/actors/moderators/{id}를 통해 assignment의 소유자로서만 갱신이 가능해야 하며,
 * - 요청에는 오직 schema에 명시된 필드(id, created_at)만 포함되어야 한다는 점을 보장합니다.
 * - 요청 성공 시 즉시 갱신/반영된 전체 assignment 정보가 반환되어야 함도 확인합니다.
 * - 또한, 잘못된 id(소유자가 아니라거나 존재하지 않음)로 갱신을 시도할 경우에는 반드시 실패(에러)해야 합니다.
 *
 * [테스트 시나리오]
 *
 * 1. 관리자가 신규 모더레이터 역할을 지정하여 assignment를 만든다.
 * 2. (본인 인증/테스트 환경 가정)
 * 3. /my/actors/moderators/{id} 엔드포인트로 id, created_at을 수정한다.
 * 4. 반환된 객체가 전체 스키마와 일치함을 typia.assert로 검증한다.
 * 5. Id, created_at이 수정 요청값과 정확히 일치하는지 TestValidator.equals로 확인한다.
 * 6. (음수) 무관 id(타인/임의 UUID 등)로 요청 시 반드시 에러가 발생하는지 확인한다.
 */
export async function test_api_prefix_moderator_my_actors_moderators_test_update_own_moderator_assignment_with_valid_fields(
  connection: api.IConnection,
) {
  // 1. 관리자가 신규 모더레이터 역할 assignment를 만든다.
  const assignment = await api.functional.prefix.admin.actors.moderators.create(
    connection,
    {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardModerator.ICreate,
    },
  );
  typia.assert(assignment);

  // 2. (본인 인증은 테스트 환경이나 이 컨텍스트에선 가정)

  // 3. /my/actors/moderators/{id}로 id, created_at만 수정 요청
  const updated_at = new Date(Date.now() + 1000000).toISOString();
  const updated =
    await api.functional.prefix.moderator.my.actors.moderators.update(
      connection,
      {
        id: assignment.id,
        body: {
          id: assignment.id,
          created_at: updated_at,
        } satisfies IDiscussionboardModerator.IUpdate,
      },
    );
  typia.assert(updated);

  // 4. 반환 객체 구조 전체 검증
  // 5. id, created_at 값이 요청대로 정확히 반영됨을 검사
  TestValidator.equals("id must match")(updated.id)(assignment.id);
  TestValidator.equals("created_at must match")(updated.created_at)(updated_at);

  // 6. 잘못된 id(임의/타인)로 update 시도 시 반드시 실패해야 함
  await TestValidator.error("wrong id denies update")(() =>
    api.functional.prefix.moderator.my.actors.moderators.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardModerator.IUpdate,
    }),
  );
}

