 * **Validation:** The API should NOT permit update when extraneous fields are
 * present. This guarantees schema compliance and prevents accidental or
 * malicious data injection. This test only covers runtime errors, as per
 * guidelines – type system rejection scenarios are not tested.
 */
export async function test_api_prefix_moderator_my_actors_moderators_test_update_own_moderator_assignment_with_invalid_fields_fails(
  connection: api.IConnection,
) {
