  TestValidator.equals("created_at 반환값 일치")(output.created_at)(created_at);

  // 2. schema에 없는 임의 필드 포함시 에러 발생 확인
  const payloadWithExtra = { ...payload, transientField: "ignored" };
  await TestValidator.error("schema 불일치 - 임의 필드 포함시 거부됨")(
    async () => {
