/**
 * 게스트 역할 레코드의 created_at 필드 갱신을 회원 인증 상태에서 검증
 *
 * - Discussionboard_guests 엔티티에서 회원이 본인 소유의 게스트(id) 레코드의 session 등록
 *   시각(created_at)을 갱신할 수 있는지 테스트합니다.
 * - 반드시 인증된 상태(Member 권한)에서만 가능하며, 허용 필드는 id, created_at 뿐임을 확인합니다.
 *
 * 1. 테스트용 게스트 레코드(세션) 생성 (의존성 선행)
 * 2. 생성된 id로 PUT /prefix/member//my/actors/guests/{id} 요청 후 created_at 타임스탬프 변경
 * 3. 응답의 id는 불변, created_at은 업데이트 값 반영 여부 확인
 * 4. Id 필드가 불일치하는 값으로 PUT 시도 시 오류 반환 확인 (id 불변성/스키마 엄격)
 */
export async function test_api_prefix_member_my_actors_guests_test_update_guest_record_created_at_field_successfully(
  connection: api.IConnection,
) {
  // 1. 의존성: 테스트 게스트 레코드 생성
  const guest: IDiscussionboardGuests =
    await api.functional.prefix.member.actors.guests.create(connection, {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardGuests.ICreate,
    });
  typia.assert(guest);

  // 2. created_at 필드 갱신 (PUT)
  const newCreatedAt = new Date(Date.now() + 60 * 60 * 1000).toISOString();
  const updated: IDiscussionboardGuests =
    await api.functional.prefix.member.my.actors.guests.update(connection, {
      id: guest.id,
      body: {
        id: guest.id,
        created_at: newCreatedAt,
      } satisfies IDiscussionboardGuests.IUpdate,
    });
  typia.assert(updated);

  // 3. id 불변 확인, created_at이 요청값으로 갱신 확인
  TestValidator.equals("id unchanged")(updated.id)(guest.id);
  TestValidator.equals("created_at field updated")(updated.created_at)(
    newCreatedAt,
  );

  // 4. id 불일치 PUT 시도 시 오류
  await TestValidator.error("id mismatch should fail")(async () =>
    api.functional.prefix.member.my.actors.guests.update(connection, {
      id: guest.id,
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: newCreatedAt,
      } satisfies IDiscussionboardGuests.IUpdate,
    }),
  );
}

