 * 타인이 소유한 guest 레코드 삭제를 금지하는 권한(authorization) 검증 테스트.
 *
 * 본 테스트는 멤버 세션 A로 guest를 먼저 생성한 후, 서로 다른 멤버 세션 B로 전환하여 해당 guest 레코드를 삭제 시도함. 정상
 * 동작 시 API는 권한 없음(Forbidden/Not authorized) 에러를 반환해야 하며, guest 레코드는 삭제되지 않아야 함을
 * 검증한다.
 *
 * [테스트 플로우]
 *
 * 1. 멤버 A로 로그인 후 guest를 생성한다.
 * 2. 멤버 B로 로그인(세션 전환; 실제 시스템 환경에 따라 connection 인증 정보 갱신 필요)
 * 3. 멤버 B가 A가 만든 guest를 삭제 시도한다 - 권한 없음 에러(Forbidden/Not authorized)를 기대
 * 4. (read/list API가 있으면) 해당 guest 레코드가 여전히 존재함을 확인한다.
 *
 * - 본 시나리오에서는 read/list API 미제공으로 4번 생략
 */
export async function test_api_prefix_member_my_actors_guests_test_attempt_delete_guest_record_by_non_owner_is_forbidden(
  connection: api.IConnection,
) {
  // 1. 멤버 A로(현 connection 사용) guest 생성
  const guestCreateInput: IDiscussionboardGuests.ICreate = {
    id: typia.random<string & tags.Format<"uuid">>(),
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const guest = await api.functional.prefix.member.actors.guests.create(
    connection,
    {
      body: guestCreateInput,
    },
  );
  typia.assert(guest);

  // 2. 멤버 B로 로그인(인증/connection 객체 전환)
  // 실제 테스트 환경에선 connection의 인증정보 교체 필요(여기선 주석)
  // 예시: await api.functional.members.authenticate.login(connection, ...)

  // 3. 멤버 B가 A의 guest 삭제 시도 -> 권한 오류 발생
  await TestValidator.error("비소유 멤버의 guest 삭제 forbidden")(async () => {
    await api.functional.prefix.member.my.actors.guests.erase(connection, {
      id: guest.id,
    });
  });

  // 4. (read/list API 없으므로 생략) guest 레코드가 남아 있는지 재확인 불가
}

