import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * Validate that a discussion board member can update their own post's mutable
 * fields, and cannot update posts they do not own or immutable fields.
 *
 * This test covers the following business flows:
 *
 * 1. Member creation (the owner of the post)
 * 2. Thread creation for associating the post
 * 3. Post creation by the member
 * 4. Member updates their own post (happy path): edit 'body', 'is_edited',
 *    'updated_at', and confirm update is reflected in the returned object
 * 5. Attempt to update immutable fields (e.g. 'id', 'discussionboard_thread_id',
 *    'discussionboard_member_id', 'created_at', 'is_deleted'), or
 *    extra/out-of-schema fields, and verify API validation-level rejection
 *    (expect error)
 * 6. Create a second member, and attempt to update the original member's post as
 *    this new member: expect an authorization failure (not allowed to update
 *    others' posts)
 * 7. Attempt to update a non-existent post (random UUID): expect not found or
 *    error
 */
export async function test_api_threadsPosts_test_update_own_post_happy_path_and_authorization(
  connection: api.IConnection,
) {
  // 1. Create first member (owner)
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const createdAt1 = new Date().toISOString() as string &
    tags.Format<"date-time">;
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId,
        created_at: createdAt1,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a thread
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: categoryId,
        title: "Sample Thread Title",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: createdAt1,
        updated_at: createdAt1,
      } satisfies IDiscussionboardThreads.ICreate,
    },
  );
  typia.assert(thread);

  // 3. Create a post by member
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        body: "Initial post body.",
        is_edited: false,
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(post);

  // 4. Update own post (valid)
  const updateBody = {
    body: "Updated post body!",
    is_edited: true,
    updated_at: new Date(Date.now() + 60000).toISOString() as string &
      tags.Format<"date-time">,
  } satisfies IDiscussionboardPost.IUpdate;
  const updatedPost =
    await api.functional.prefix.member.my.threadsPosts.posts.update(
      connection,
      {
        id: post.id,
        body: updateBody,
      },
    );
  typia.assert(updatedPost);
  TestValidator.predicate("post is updated")(
    updatedPost.body === "Updated post body!" &&
      updatedPost.is_edited === true &&
      updatedPost.updated_at === updateBody.updated_at,
  );

  // 5. Attempt to update immutable or out-of-schema fields -- Should be rejected
  await TestValidator.error("should reject immutable field update async")(() =>
    api.functional.prefix.member.my.threadsPosts.posts.update(connection, {
      id: post.id,
      body: { id: typia.random<string & tags.Format<"uuid">>() } as any,
    }),
  );
  await TestValidator.error("should reject out-of-schema field async")(() =>
    api.functional.prefix.member.my.threadsPosts.posts.update(connection, {
      id: post.id,
      body: { random_field: "illegal!" } as any,
    }),
  );

  // 6. Create 2nd member; test unauthorized update attempt
  const memberId2 = typia.random<string & tags.Format<"uuid">>();
  const createdAt2 = new Date(Date.now() + 1000).toISOString() as string &
    tags.Format<"date-time">;
  const member2 = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId2,
        created_at: createdAt2,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member2);
  // (Assume context-swap to member2 is done via auth, but since we cannot change connection context, just attempt as is.)
  await TestValidator.error("not owner cannot update post")(() =>
    api.functional.prefix.member.my.threadsPosts.posts.update(connection, {
      id: post.id,
      body: {
        body: "Should not update!",
      } satisfies IDiscussionboardPost.IUpdate,
    }),
  );

  // 7. Attempt to update non-existent post id
  await TestValidator.error("update non-existent post")(() =>
    api.functional.prefix.member.my.threadsPosts.posts.update(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
      body: { body: "Does not exist." } satisfies IDiscussionboardPost.IUpdate,
    }),
  );
}

