import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IPageIDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardThreads";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 토론 스레드를 제목 키워드로 검색하는 기능 검증
 *
 * 이 테스트는 사용자가 입력한 고유 키워드를 포함한 제목으로 스레드를 생성한 후, 해당 키워드로 검색 옵션을 적용하여 목록을 페이징 조회했을
 * 때:
 *
 * 1. 생성한 스레드가 반드시 포함되어야 하며,
 * 2. 관련 없는 스레드는 포함되지 않아야 하며,
 * 3. 페이지네이션 정보(페이지 번호, 한 페이지당 개수, 전체 개수, 전체 페이지)가 정상적으로 포함되어야 함을 검증한다.
 *
 * 단계별 테스트 흐름:
 *
 * 1. 식별 가능한(충분히 희귀한) 키워드로 Thread 제목을 지정하여 스레드 생성(POST)
 * 2. 동일한 카테고리 또는 다른 카테고리에 연관 없는(키워드 없는) 스레드 1~2개를 추가 생성(잡음 데이터)
 * 3. PATCH /prefix//threadsPosts/threads API를 통해 body.title에 키워드 세팅 후 페이징 검색
 *
 *    - 반환 데이터(data 배열) 내에 1번에서 생성한 스레드가 반드시 등장
 *    - 잡음 데이터(키워드가 제목에 미포함된 타 스레드)는 등장하지 않아야 함(TestValidator 활용)
 *    - Pagination 오브젝트도 정상 반환되어야 함
 */
export async function test_api_threadsPosts_test_search_threads_by_title_keyword(
  connection: api.IConnection,
) {
  // 1. 고유 키워드 지정
  const uniqueKeyword = `keyword_${RandomGenerator.alphaNumeric(10)}`;

  // 2. 스레드 생성(검색 키워드 포함 제목)
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const createdThread =
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_category_id: categoryId,
        title: `테스트 스레드 ${uniqueKeyword}`,
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      } satisfies IDiscussionboardThreads.ICreate,
    });
  typia.assert(createdThread);

  // 3. 잡음 데이터 1~2건 생성(키워드 미포함)
  const noiseThreads = await ArrayUtil.asyncRepeat(2)(async () => {
    return await api.functional.prefix.member.threadsPosts.threads.create(
      connection,
      {
        body: {
          discussionboard_category_id: categoryId,
          title: RandomGenerator.paragraph()(1),
          status: "active",
          is_pinned: false,
          is_locked: false,
          archived: false,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        } satisfies IDiscussionboardThreads.ICreate,
      },
    );
  });
  noiseThreads.forEach((thread) => typia.assert(thread));

  // 4. 키워드로 검색
  const page = await api.functional.prefix.threadsPosts.threads.index(
    connection,
    {
      body: {
        title: uniqueKeyword,
      },
    },
  );
  typia.assert(page);

  // 5. 결과 검증: 1) 키워드 포함 스레드만 등장 2) 잡음 데이터 없음 3) 페이지네이션 객체 정상
  TestValidator.predicate("리스트 내에 생성한 스레드가 반드시 포함됨")(
    page.data.some((t) => t.id === createdThread.id),
  );
  noiseThreads.forEach((noise) => {
    TestValidator.predicate("잡음 스레드는 등장 X")(
      !page.data.some((t) => t.id === noise.id),
    );
  });
  TestValidator.equals("pagination에 필수 필드 존재 확인")(
    Object.keys(page.pagination).sort(),
  )(["current", "limit", "pages", "records"].sort());
}

