 * 1. 토론 스레드(threads)를 하나 생성한다.
 * 2. 해당 스레드의 id를 활용하여 상세조회 API(/prefix//threadsPosts/threads/{id})를 호출한다.
 * 3. 응답 데이터가 스레드 생성 시 입력했던 값들과 (id, 소속 카테고리 id, 제목, 상태, pinn 여부, locked 여부,
 *    archived, 생성/수정일시 등) 정확히 일치하는가를 assert한다.
 *
 * 스키마 정의에 맞게 디테일 매칭 여부, 특히 uuid 및 날짜-포맷 필드의 정확성까지 검증한다.
 */
export async function test_api_threadsPosts_test_get_thread_details_success(
  connection: api.IConnection,
) {
  // 1. 신규 토론 스레드 생성
  const threadInput: IDiscussionboardThreads.ICreate = {
    discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(),
    title: "스레드 조회 테스트: 단일 상세 케이스",
    status: "active",
    is_pinned: false,
    is_locked: false,
    archived: false,
    created_at: new Date().toISOString(),
