      body: threadInput,
    });
  typia.assert(created);

  // 2. 방금 생성한 스레드 id로 상세조회
  const fetched: IDiscussionboardThreads =
    await api.functional.prefix.threadsPosts.threads.at(connection, {
      id: created.id,
    });
  typia.assert(fetched);

  // 3. 입력·생성값과 상세조회값 정확히 일치하는지 검증 (스칼라 필드 기반 직접 대조)
  TestValidator.equals("id")(fetched.id)(created.id);
  TestValidator.equals("카테고리")(fetched.discussionboard_category_id)(
    created.discussionboard_category_id,
  );
  TestValidator.equals("제목")(fetched.title)(created.title);
  TestValidator.equals("상태")(fetched.status)(created.status);
  TestValidator.equals("핀 여부")(fetched.is_pinned)(created.is_pinned);
  TestValidator.equals("잠금 여부")(fetched.is_locked)(created.is_locked);
  TestValidator.equals("archived 여부")(fetched.archived)(created.archived);
  TestValidator.equals("생성일시")(fetched.created_at)(created.created_at);
  TestValidator.equals("수정일시")(fetched.updated_at)(created.updated_at);
  TestValidator.equals("작성자")(fetched.discussionboard_member_id)(
