  // 2. 필수 updated_at 포함, 최소 유효 구조로 업데이트 요청 본문 준비
  const updateBody: IDiscussionboardThreads.IUpdate = {
    title: "잘못된 id 테스트",
    updated_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };

  // 3. 에러(404/403 등) 발생여부 체크
  await TestValidator.error(
    "존재하지 않거나 권한 없는 스레드 id로 update 시 에러 발생 확인",
  )(async () => {
    await api.functional.prefix.member.my.threadsPosts.threads.update(
      connection,
      {
        id: invalidThreadId,
        body: updateBody,
      },
    );
  });
}

