import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";

/**
 * 테스트: 허용되지 않은 필드(id, created_at 등 불변 및 스키마 바깥 필드)로 토론 스레드 수정 시 실패 검증
 *
 * 이 테스트는, 스레드 업데이트 API(본인 게시글 수정)가 요청 스키마에 정의되지 않은 불변 필드(id, created_at 등)를
 * 업데이트 요청 본문(body)에 포함시켰을 때 서버가 이를 검증하여 거부(에러 발생)하는지 확인합니다. 실제 TypeScript용 SDK
 * 함수 및 DTO 구조 상, 현 타입 시스템이 out-of-schema 필드 포함이 불가능할 경우 해당 시나리오를 직접 재현할 수 없음을
 * 코드 및 주석에 명시합니다.
 *
 * [진행 흐름]
 *
 * 1. 정상적인 필드(스키마 허용 필드)로 토론 스레드 생성
 * 2. 생성된 스레드의 id, created_at 등 불변필드를 포함해(불법적으로) 업데이트 API를 호출 시도
 * 3. 시스템이 잘못된 필드 포함 요청에 대해 validation error(예: 400 Bad Request) 반환을 보장하는지
 *    TestValidator.error로 검증
 *
 * [주의] TypeScript DTO 타입 제한 및 SDK 함수 시그니처 특성상, 의도적으로 스키마를 위반하는 요청을 전송 불가할 수 있음.
 * → 이 경우 명확한 주석과 함께 생략 및 테스트 한계를 기록함.
 */
export async function test_api_threadsPosts_test_update_thread_with_restricted_field(
  connection: api.IConnection,
) {
  // 1. 정상 필드로 토론 스레드 생성
  const now = new Date().toISOString();
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "테스트용 스레드",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: now,
        updated_at: now,
      } satisfies IDiscussionboardThreads.ICreate,
    },
  );
  typia.assert(thread);

  // 2. 불변/스키마 외 필드를 포함하여 업데이트 시도 (id, created_at 등)
  // TypeScript의 엄격한 DTO 제한으로 인해 불법 필드(id, created_at)를 body에 추가하여 보낼 방법이 없음
  // 만약 SDK 또는 fetcher가 any, as any 등의 타입 우회 없이 실제로 전달 가능하다면 아래와 같이 시도할 수 있지만,
  // 현 구조에선 불가하므로 아래를 주석으로 남김
  /*
  // 예시: (비권장, 실제로는 타입 오류 혹은 빌드 실패, 따라서 실제 실행 불가)
  await TestValidator.error("불변 필드(id, created_at)를 포함할 경우 에러 반환")(async () => {
    await api.functional.prefix.member.my.threadsPosts.threads.update(connection, {
      id: thread.id,
      body: {
        ...변경필드
        id: thread.id,
        created_at: now,
        ...
      } as any,  // 비-타입 안전 접근, 실제 현장에선 금지
    });
  });
  */
