/**
 * 인증 회원이 올바른 필터와 페이지네이션 옵션으로 자신의 활성 인증 세션을 조회하는 테스트입니다.
 *
 * - `issued_at` 시점 이후, `actor_type`이 "member" 인 본인 세션만 필터링 적용
 * - 목록 데이터 모두가 본인(회원 계정)에 대한 세션인지, 타인의 세션이 포함되어 있지 않은지 검증
 * - 반환 pagination 정보의 일관성을 체크
 * - 타입 위반/허용되지 않은 필드 케이스 등은 런타임 테스트에서 제외(타입시스템 단에서 차단)
 */
export async function test_api_prefix_member_auth_sessions_index(
  connection: api.IConnection,
) {
  // 1. 현재 로그인 회원 계정 상태에서 테스트 실행(별도의 회원가입/로그인 플로우가 없는 것으로 가정)

  // 2. issued_at 기준 내림차순 정렬 및 role-based 필터로 세션 목록 조회
  const now = new Date().toISOString();
  const filters = {
    issued_at: now,
    actor_type: "member",
  } satisfies IDiscussionboardAuthSessions.IRequest;

  const output = await api.functional.prefix.member.auth.sessions.index(
    connection,
    {
      body: filters,
    },
  );
  typia.assert(output);

  // 3. 반환 세션 데이터가 모두 "member" 타입, pagination이 정상적으로 세팅됐는지 확인
  output.data.forEach((session) => {
    TestValidator.equals("모든 세션 타입이 member")(session.actor_type)(
      "member",
    );
    // 추가적으로 session.actor_id === 본인 UUID 검증은 connection 내 정보 연동 시 활용 가능
  });

  TestValidator.predicate("페이지네이션 값 일관성")(
    output.pagination.current >= 1 &&
      output.pagination.limit > 0 &&
      output.pagination.pages >= 1,
  );
}

