import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAuthSessions } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAuthSessions";
import type { IPageIDiscussionboardAuthSessions } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardAuthSessions";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 인증 세션 조회 시 본인 소유 세션만 반환되는지 철저히 검증합니다.
 *
 * - 회원B(타인) 식별자/세션 생성
 * - 회원A(본인) 식별자/세션 생성
 * - 회원A로 세션 목록 조회(index) 시 타인(B) 세션이 전혀 포함되지 않아야 함
 * - 목록 내 모든 세션의 actor_id가 회원A와 일치하는지, 회원A 자신의 세션이 반드시 포함되는지 확인
 *
 * 실제 환경에선 인증 토큰·계정 기반 테스트가 필요하지만, 본 시나리오에서는 직접 actor_id 파라미터 지정으로 격리성 테스트를
 * 완수합니다.
 */
export async function test_api_prefix_member_auth_sessions_test_list_auth_sessions_for_member_shows_only_own_sessions(
  connection: api.IConnection,
) {
  // 1. 타 회원(B) 세션 사전 생성
  const actorB_id: string = typia.random<string & tags.Format<"uuid">>();
  const actorB_session = await api.functional.prefix.auth.sessions.create(
    connection,
    {
      body: {
        actor_type: "member",
        actor_id: actorB_id,
        issued_at: new Date().toISOString(),
        expires_at: new Date(Date.now() + 24 * 3600 * 1000).toISOString(),
        ip_address: "203.0.113.11",
        user_agent: "Mozilla/5.0 (TestRunner/B)",
      } satisfies IDiscussionboardAuthSessions.ICreate,
    },
  );
  typia.assert(actorB_session);

  // 2. 테스트 대상 회원(A) 세션 생성
  const actorA_id: string = typia.random<string & tags.Format<"uuid">>();
  const actorA_session = await api.functional.prefix.auth.sessions.create(
    connection,
    {
      body: {
        actor_type: "member",
        actor_id: actorA_id,
        issued_at: new Date().toISOString(),
        expires_at: new Date(Date.now() + 24 * 3600 * 1000).toISOString(),
        ip_address: "198.51.100.21",
        user_agent: "Mozilla/5.0 (TestRunner/A)",
      } satisfies IDiscussionboardAuthSessions.ICreate,
    },
  );
  typia.assert(actorA_session);

  // 3. 회원A로 세션 목록 조회
  const result = await api.functional.prefix.member.auth.sessions.index(
    connection,
    {
      body: {
        actor_id: actorA_id,
        actor_type: "member",
      } satisfies IDiscussionboardAuthSessions.IRequest,
    },
  );
  typia.assert(result);

  // 4. 반환된 모든 세션이 actorA 소유인지 확인
  TestValidator.predicate("세션 목록: 본인만 포함")(
    result.data.every((session) => session.actor_id === actorA_id),
  );
  // 5. 본인 세션 반드시 반환
  TestValidator.predicate("세션 목록: 본인 세션 존재")(
    result.data.some((session) => session.id === actorA_session.id),
  );
}

