/**
 * 인증 세션의 UUID로 존재하지 않는 세션을 조회했을 때 Not Found(404) 에러가 반환되는지 검증한다.
 *
 * 이 테스트는 유효하지 않은 세션 id(존재하지 않는 uuid)를 이용해 인증 세션의 상세 조회 API를 호출하며, 시스템이 없는 리소스에
 * 대해 올바르게 예외를 반환하는지 확인한다.
 *
 * 1. 임의의(uuid 포맷)로 생성한 존재하지 않는 id를 준비한다.
 * 2. 위 id로 인증 세션 조회 API( GET /prefix//auth/sessions/{id})를 호출한다.
 * 3. 404 Not Found 에러가 발생하는지 TestValidator.error()를 이용해 검증한다.
 */
export async function test_api_prefix_auth_sessions_test_get_auth_session_by_id_with_invalid_id(
  connection: api.IConnection,
) {
