import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAuthSessions } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAuthSessions";

/**
 * 인증 세션 생성 API 필수 필드 누락 검증 테스트
 *
 * 인증 세션(로그인) 생성 시 'actor_type', 'actor_id', 'issued_at', 'expires_at' 필드 중 하나라도
 * 누락되면 API가 반드시 유효성 오류(400 Bad Request 등)를 반환해야 함을 확인합니다.
 *
 * 1. 모든 필수 필드를 포함한 경우 정상적으로 세션이 생성되는지 확인합니다.
 * 2. 각 필수 필드별(actor_type, actor_id, issued_at, expires_at) 누락 케이스를 각각 만들어 네 번
 *    테스트합니다.
 * 3. 각 케이스별로 반드시 오류가 발생함을 TestValidator.error()로 검증합니다.
 *
 * (참고: TypeScript 컴파일 타입 상 required 필드를 아예 뺄 수는 없으므로, 런타임 검증을 위해 `as unknown as
 * ICreate`로 꼼수 타입 캐스팅을 사용.)
 */
export async function test_api_prefix_auth_sessions_test_create_auth_session_missing_required_fields(
  connection: api.IConnection,
) {
  // 1. 정상: 모든 필수 필드 포함 시 정상 생성됨
  const validPayload = {
    actor_type: RandomGenerator.alphabets(8),
    actor_id: typia.random<string & tags.Format<"uuid">>(),
    issued_at: new Date().toISOString(),
    expires_at: new Date(Date.now() + 3600_000).toISOString(),
    ip_address: "192.168.0.1",
    user_agent: "unit-test-agent",
  } satisfies IDiscussionboardAuthSessions.ICreate;
  const session = await api.functional.prefix.auth.sessions.create(connection, {
    body: validPayload,
  });
  typia.assert(session);

  // 2-1. actor_type 누락 케이스
  await TestValidator.error("actor_type missing")(() =>
    api.functional.prefix.auth.sessions.create(connection, {
      body: {
        // actor_type: 누락 intentionally omitted
        actor_id: validPayload.actor_id,
        issued_at: validPayload.issued_at,
        expires_at: validPayload.expires_at,
        ip_address: validPayload.ip_address,
        user_agent: validPayload.user_agent,
      } as unknown as IDiscussionboardAuthSessions.ICreate,
    }),
  );

  // 2-2. actor_id 누락 케이스
  await TestValidator.error("actor_id missing")(() =>
    api.functional.prefix.auth.sessions.create(connection, {
      body: {
        actor_type: validPayload.actor_type,
        // actor_id: 누락 intentionally omitted
        issued_at: validPayload.issued_at,
        expires_at: validPayload.expires_at,
        ip_address: validPayload.ip_address,
        user_agent: validPayload.user_agent,
      } as unknown as IDiscussionboardAuthSessions.ICreate,
    }),
  );

  // 2-3. issued_at 누락 케이스
  await TestValidator.error("issued_at missing")(() =>
    api.functional.prefix.auth.sessions.create(connection, {
      body: {
        actor_type: validPayload.actor_type,
        actor_id: validPayload.actor_id,
        // issued_at: 누락 intentionally omitted
        expires_at: validPayload.expires_at,
        ip_address: validPayload.ip_address,
        user_agent: validPayload.user_agent,
      } as unknown as IDiscussionboardAuthSessions.ICreate,
    }),
  );

  // 2-4. expires_at 누락 케이스
  await TestValidator.error("expires_at missing")(() =>
    api.functional.prefix.auth.sessions.create(connection, {
      body: {
        actor_type: validPayload.actor_type,
        actor_id: validPayload.actor_id,
        issued_at: validPayload.issued_at,
        // expires_at: 누락 intentionally omitted
        ip_address: validPayload.ip_address,
        user_agent: validPayload.user_agent,
      } as unknown as IDiscussionboardAuthSessions.ICreate,
    }),
  );
}

