import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAuthSessions } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAuthSessions";

/**
 * Validate authenticated member updating their own session record with
 * updatable fields.
 *
 * This test verifies that an authenticated user can update their auth session
 * record (last_activity_at, revoked_at, expires_at, ip_address, user_agent)
 * using only schema-allowed fields, and confirms that the changes are correctly
 * reflected in the returned response object.
 *
 * 1. Create an auth session (simulate user login/session start scenario). This
 *    provides a session ID used for the update.
 * 2. Update the session by providing valid values for updatable fields.
 * 3. Check the response: ensure all the updated fields are reflected accordingly,
 *    and non-updated/immutable fields remain unchanged.
 * 4. Try updating with only a subset of fields (e.g. only last_activity_at) and
 *    verify correct partial update.
 */
export async function test_api_prefix_member_my_auth_sessions_test_update_own_auth_session_with_valid_fields(
  connection: api.IConnection,
) {
  // 1. Create an auth session for the user (simulate user login)
  const session = await api.functional.prefix.auth.sessions.create(connection, {
    body: {
      actor_type: "member",
      actor_id: typia.random<string & tags.Format<"uuid">>(),
      issued_at: new Date().toISOString(),
      expires_at: new Date(Date.now() + 3600000).toISOString(),
      ip_address: "192.168.1.100",
      user_agent: "Mozilla/5.0 ChromeTest",
    } satisfies IDiscussionboardAuthSessions.ICreate,
  });
  typia.assert(session);

  // 2. Prepare valid update data for the session
  const newLastActivity = new Date(Date.now() + 10000).toISOString();
  const newExpiresAt = new Date(Date.now() + 7200000).toISOString();
  const newRevokedAt = null; // Not revoking now
  const newIpAddress = "10.0.0.123";
  const newUserAgent = "TestAgent/1.0";

  // 3. Update the session using the authenticated user's API
  const updatedSession =
    await api.functional.prefix.member.my.auth.sessions.update(connection, {
      id: session.id,
      body: {
        last_activity_at: newLastActivity,
        expires_at: newExpiresAt,
        revoked_at: newRevokedAt,
        ip_address: newIpAddress,
        user_agent: newUserAgent,
      } satisfies IDiscussionboardAuthSessions.IUpdate,
    });
  typia.assert(updatedSession);

  // 4. Check that updated fields match
  TestValidator.equals("last_activity_at updated")(
    updatedSession.last_activity_at,
  )(newLastActivity);
  TestValidator.equals("expires_at updated")(updatedSession.expires_at)(
    newExpiresAt,
  );
  TestValidator.equals("revoked_at remains")(updatedSession.revoked_at)(
    newRevokedAt,
  );
  TestValidator.equals("ip_address updated")(updatedSession.ip_address)(
    newIpAddress,
  );
  TestValidator.equals("user_agent updated")(updatedSession.user_agent)(
    newUserAgent,
  );

  // 5. Check immutable fields didn't change
  TestValidator.equals("id remains")(updatedSession.id)(session.id);
  TestValidator.equals("actor_id remains")(updatedSession.actor_id)(
    session.actor_id,
  );
  TestValidator.equals("actor_type remains")(updatedSession.actor_type)(
    session.actor_type,
  );
  TestValidator.equals("issued_at remains")(updatedSession.issued_at)(
    session.issued_at,
  );

  // 6. Try updating only one field (e.g., just last_activity_at)
  const anotherLastActivity = new Date(Date.now() + 20000).toISOString();
  const partiallyUpdated =
    await api.functional.prefix.member.my.auth.sessions.update(connection, {
      id: session.id,
      body: {
        last_activity_at: anotherLastActivity,
      } satisfies IDiscussionboardAuthSessions.IUpdate,
    });
  typia.assert(partiallyUpdated);
  TestValidator.equals("partial update last_activity_at")(
    partiallyUpdated.last_activity_at,
  )(anotherLastActivity);
  TestValidator.equals("other fields untouched after partial update")(
    partiallyUpdated.expires_at,
  )(newExpiresAt);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAuthSessions } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAuthSessions";

/**
 * 인증 세션(내 세션)을 스키마에 없는 필드(`deleted_at`)로 업데이트 시도 시 거부되는지 검증하는 테스트입니다.
 *
 * 실제 API 스키마에는 존재하지 않으나, 예를 들어 프론트엔드나 공격자가 임의로 `deleted_at`(또는 그 밖의 허용되지 않은
 * 필드)를 update 요청의 body에 추가하는 경우 서버가 이를 엄격하게 거부(400 혹은 422 등 유효성 오류 반환)하는지
 * 확인합니다.
 *
 * 테스트 개요:
 *
 * 1. 사전 준비: 세션 레코드 생성
 * 2. 정상 필드만 있는 경우 update가 정상적으로 동작함을 확인
 * 3. 스키마에 정의되지 않은 필드(`deleted_at`)가 body에 포함된 경우 update 시 오류가 발생하는지 확인
 */
export async function test_api_prefix_member_my_auth_sessions_test_update_own_auth_session_with_forbidden_field(
  connection: api.IConnection,
) {
  // 1. 사전 준비: 세션 레코드 생성
  const session = await api.functional.prefix.auth.sessions.create(connection, {
    body: typia.random<IDiscussionboardAuthSessions.ICreate>(),
  });
  typia.assert(session);

  // 2. 정상 update: 스키마에 정의된 필드를 이용한 갱신이 성공함을 확인
  const updated = await api.functional.prefix.member.my.auth.sessions.update(
    connection,
    {
      id: session.id,
      body: {
        last_activity_at: new Date().toISOString(),
      } satisfies IDiscussionboardAuthSessions.IUpdate,
    },
  );
  typia.assert(updated);
  TestValidator.equals("세션 PK 유지됨")(updated.id)(session.id);
  TestValidator.equals("last_activity_at 업데이트됨")(
    updated.last_activity_at !== session.last_activity_at,
  )(true);

  // 3. 금지 필드(`deleted_at`) 포함시 오류 발생 여부 확인
  // 타입 시스템 상 직접 forbidden field를 담을 수 없으므로, 실제로 공격자가 임의 JSON body를 보낸 상황(replay/직접 CURL 등)과 비슷하게 any 캐스팅으로 호출
  await TestValidator.error("스키마에 없는 필드 update 시도시 오류 반환")(
    async () => {
      await api.functional.prefix.member.my.auth.sessions.update(connection, {
        id: session.id,
        body: {
          last_activity_at: new Date().toISOString(),
          deleted_at: new Date().toISOString(), // 스키마에 없는 필드
        } as any, // 타입 강제 우회
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
