 *
 * 1. 테스트용 '타 회원' 세션(actod_id == 본인 X)을 선행 생성
 * 2. 현재 인증된 회원 connection으로 해당 세션 id에 대해 update 요청 시도
 * 3. Update DTO는 정상 구조로 구성(last_activity_at/ip_address/user_agent) - 실제 오류 핵심은 소유
 *    불일치임
 * 4. Update 시 Forbidden(403), Not Found(404) 유형의 error가 반드시 발생해야 정상
 * 5. 정상 업데이트(2xx) 발생 시 정책 위반 또는 시스템 오류로 간주
 */
export async function test_api_prefix_member_my_auth_sessions_test_update_auth_session_not_owned_by_member(
  connection: api.IConnection,
) {
  // 1. 타 회원 세션 생성 (본인 connection과 actor_id 불일치)
  const otherMemberId: string = typia.random<string & tags.Format<"uuid">>();
  const session = await api.functional.prefix.auth.sessions.create(connection, {
    body: {
      actor_type: "member",
      actor_id: otherMemberId,
      issued_at: new Date(Date.now() - 20_000).toISOString(),
      expires_at: new Date(Date.now() + 60 * 60 * 1000).toISOString(),
      ip_address: "203.0.113.112",
      user_agent: "Mozilla/5.0 (test not-owned-session)",
    } satisfies IDiscussionboardAuthSessions.ICreate,
  });
  typia.assert(session);

  // 2. 본인 connection으로 타 회원 세션 update 시도 → error 반드시 발생
  await TestValidator.error("타 회원 세션 update 거부")(async () => {
    await api.functional.prefix.member.my.auth.sessions.update(connection, {
