import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";
import type { IPollVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPollVote";
import type { IPageIPollVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPollVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test listing/searching poll votes as an admin, covering filter, pagination,
 * and permission scenarios.
 *
 * This test verifies:
 *
 * 1. Filtering poll votes by valid schema fields (discussionboard_poll_id,
 *    voting_member_id, selected_option)
 * 2. Filtering with nonexistent poll id and multiple simultaneous criteria
 * 3. That only filter fields present in the schema are accepted (others rejected)
 * 4. Pagination and meta information presence
 * 5. Permissions: only admins can access, fail for member-level user
 * 6. Failures for invalid filter keys/types
 *
 * Steps performed:
 *
 * - Create a poll as a member
 * - Vote on the poll as a member
 * - List/search poll votes by various filters as admin
 * - Pagination and meta checks
 * - Various failure scenarios
 */
export async function test_api_prefix_admin_pollVotes_test_list_poll_votes_with_various_filters_and_permissions(
  connection: api.IConnection,
) {
  // 1. Create a poll (prerequisite)
  const poll = await api.functional.prefix.member.polls.create(connection, {
    body: {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      prompt: "Best programming language?",
      allow_multiple_choices: false,
      is_anonymous: false,
      // 'expires_at' omitted per DTO definition (undefined means never expires)
    },
  });
  typia.assert(poll);

  // 2. Add a vote (member)
  const vote = await api.functional.prefix.member.pollVotes.create(connection, {
    body: {
      discussionboard_poll_id: poll.id,
      selected_option: "TypeScript",
    },
  });
  typia.assert(vote);

  // 3. List all votes as admin (unfiltered)
  const votesAll = await api.functional.prefix.admin.pollVotes.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(votesAll);
  TestValidator.predicate("at least 1 poll vote present")(
    votesAll.data.length >= 1,
  );

  // 4. Filter by poll id
  const votesByPoll = await api.functional.prefix.admin.pollVotes.index(
    connection,
    {
      body: {
        discussionboard_poll_id: poll.id,
      },
    },
  );
  typia.assert(votesByPoll);
  TestValidator.predicate("all poll votes for expected poll id")(
    votesByPoll.data.every((d) => d.discussionboard_poll_id === poll.id),
  );

  // 5. Filter by voting_member_id
  const memberId = vote.voting_member_id;
  const votesByMember = await api.functional.prefix.admin.pollVotes.index(
    connection,
    {
      body: {
        voting_member_id: memberId,
      },
    },
  );
  typia.assert(votesByMember);
  TestValidator.predicate("at least one by correct voter id")(
    votesByMember.data.some((d) => d.voting_member_id === memberId),
  );

  // 6. Filter by selected_option
  const votesByOption = await api.functional.prefix.admin.pollVotes.index(
    connection,
    {
      body: {
        selected_option: "TypeScript",
      },
    },
  );
  typia.assert(votesByOption);
  TestValidator.predicate("at least one with selected_option")(
    votesByOption.data.some((d) => d.selected_option === "TypeScript"),
  );

  // 7. Filter by nonexistent poll id (should return empty)
  const votesByFakePoll = await api.functional.prefix.admin.pollVotes.index(
    connection,
    {
      body: {
        discussionboard_poll_id: typia.random<string & tags.Format<"uuid">>(),
      },
    },
  );
  typia.assert(votesByFakePoll);
  TestValidator.equals("empty data for nonexistent poll id")(
    votesByFakePoll.data.length,
  )(0);

  // 8. Filter by all fields (should match only the expected vote)
  const votesByAll = await api.functional.prefix.admin.pollVotes.index(
    connection,
    {
      body: {
        discussionboard_poll_id: poll.id,
        voting_member_id: memberId,
        selected_option: "TypeScript",
      },
    },
  );
  typia.assert(votesByAll);
  TestValidator.predicate("data exactly matches all filters")(
    votesByAll.data.every(
      (d) =>
        d.discussionboard_poll_id === poll.id &&
        d.voting_member_id === memberId &&
        d.selected_option === "TypeScript",
    ),
  );

  // 9. Pagination meta check (add another vote and check meta)
  await api.functional.prefix.member.pollVotes.create(connection, {
    body: {
      discussionboard_poll_id: poll.id,
      selected_option: "JavaScript",
    },
  });
  const votesPaged = await api.functional.prefix.admin.pollVotes.index(
    connection,
    {
      body: {
        discussionboard_poll_id: poll.id,
      },
    },
  );
  typia.assert(votesPaged);
  TestValidator.predicate("pagination meta present")(
    typeof votesPaged.pagination?.current === "number" &&
      typeof votesPaged.pagination?.limit === "number",
  );

  // 10. Permissions: should fail for member-level (non-admin) user
  await TestValidator.error("fail for member-level (non-admin) user")(() =>
    api.functional.prefix.admin.pollVotes.index(connection, {
      body: {},
    }),
  );

  // 11. Failure: extra field in filter (should fail)
  await TestValidator.error("fail on invalid filter key")(() =>
    api.functional.prefix.admin.pollVotes.index(connection, {
      // purposely invalid field, would fail at runtime
      body: { fake_key: 123 } as any,
    }),
  );

  // 12. Failure: wrong type for filter value (should fail)
  await TestValidator.error("fail on wrong ftype")(() =>
    api.functional.prefix.admin.pollVotes.index(connection, {
      // purposely invalid type, would fail at runtime
      body: { discussionboard_poll_id: 123 as any },
    }),
  );
}

