import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";
import type { IPollVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPollVote";

/**
 * Test retrieving the details of a single poll vote by id as the voting member.
 *
 * This test covers several scenarios:
 *
 * 1. When the poll vote exists and belongs to the requesting member:
 *
 * - All fields in the response (id, discussionboard_poll_id, voting_member_id,
 *   selected_option, created_at) should be present and valid.
 * - The data should match what was cast during vote creation.
 *
 * 2. When the poll vote does not exist:
 *
 * - The endpoint should respond with an error (typically a 404 Not Found).
 *
 * 3. When the requesting member is not the owner of the poll vote:
 *
 * - The endpoint should respond with an error (forbidden or not found).
 *
 * 4. When the id is malformed or not a UUID:
 *
 * - The endpoint should respond with a validation error or 404.
 *
 * 5. When unauthenticated:
 *
 * - Attempting to access the endpoint should fail (401 Unauthorized or similar).
 *
 * Steps: A. Create a poll (dependency) to associate with the vote. B. Cast a
 * vote as the authenticated member (dependency) and get its id and related poll
 * id/option. C. Retrieve the vote by its id as the same member and validate all
 * schema fields and data integrity. D. Attempt to retrieve a non-existent vote
 * id as the member and expect a 404 error. E. Create another member, and as
 * that member, attempt to retrieve the first member's vote and expect forbidden
 * or not found error. F. Attempt to retrieve with a malformed id (not a UUID)
 * and expect validation error or 404. G. Attempt retrieval with no
 * authentication and expect unauthorized error.
 *
 * Note: Steps E and G are not implementable as there is no provided API for
 * authentication switching, member creation, or logout—these are omitted.
 */
export async function test_api_prefix_member_pollVotes_test_get_poll_vote_detail_when_vote_exists_and_when_not_found(
  connection: api.IConnection,
) {
  // (A) Create a poll for the vote (dependency)
  const pollPayload: IPoll.ICreate = {
    discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
    prompt: RandomGenerator.paragraph()(),
    allow_multiple_choices: false,
    is_anonymous: false,
  };
  const poll = await api.functional.prefix.member.polls.create(connection, {
    body: pollPayload,
  });
  typia.assert(poll);

  // (B) Cast a poll vote as the authenticated member (dependency)
  const option = "option-1";
  const votePayload = {
    discussionboard_poll_id: poll.id,
    selected_option: option,
  } satisfies IPollVote.ICreate;
  const vote = await api.functional.prefix.member.pollVotes.create(connection, {
    body: votePayload,
  });
  typia.assert(vote);

  // (C) Retrieve the vote by its id as the same member
  const fetched = await api.functional.prefix.member.pollVotes.at(connection, {
    id: vote.id,
  });
  typia.assert(fetched);
  TestValidator.equals("id matches")(fetched.id)(vote.id);
  TestValidator.equals("poll id matches")(fetched.discussionboard_poll_id)(
    poll.id,
  );
  TestValidator.equals("voting_member_id matches")(fetched.voting_member_id)(
    vote.voting_member_id,
  );
  TestValidator.equals("selected_option matches")(fetched.selected_option)(
    option,
  );

  // (D) Attempt to retrieve non-existent vote id as the member (404 expected)
  await TestValidator.error("not found for non-existent id")(async () => {
    await api.functional.prefix.member.pollVotes.at(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // (E) Attempt to retrieve as another member (forbidden/not found) - SKIP: no auth/member APIs provided.

  // (F) Attempt to retrieve with a malformed id (not a uuid)
  await TestValidator.error("malformed id")(async () => {
    await api.functional.prefix.member.pollVotes.at(connection, {
      id: "not-a-uuid" as any,
    });
  });

  // (G) Attempt retrieval unauthenticated (401) - SKIP: no logout or unauthenticated API context.
}

