import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostHistory";

/**
 * Ensures the API rejects attempts to update immutable or non-existent fields
 * on a post history snapshot.
 *
 * This test verifies that the API does not allow invalid updates on the post
 * history snapshot by attempting to update only allowed fields and expecting a
 * failure if business rules prevent unauthorized mutations.
 *
 * Steps:
 *
 * 1. Create a discussion board post as a member (prerequisite to generate a post
 *    eligible for editing).
 * 2. Update the post to create at least one post history snapshot.
 * 3. Attempt to update a post history snapshot with only allowed fields.
 *
 *    - Since the DTO and SDK prevent setting non-existent or immutable fields, this
 *         test validates API behavior with a simulated invalid update case
 *         using legal fields only (e.g., potentially using an invalid ID).
 *    - The API must reject the update if the business rules prohibit the action
 *         (e.g., editing a non-existent or unauthorized post history
 *         snapshot).
 *
 * The test passes if the API returns an error and does not permit the update.
 */
export async function test_api_postHistories_test_update_post_history_snapshot_with_invalid_fields(
  connection: api.IConnection,
) {
  // 1. Create a post as a member (prerequisite)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const createdPost =
    await api.functional.prefix.member.threadsPosts.posts.create(connection, {
      body: {
        discussionboard_thread_id: threadId,
        body: "Initial validation post body.",
      } satisfies IDiscussionboardPosts.ICreate,
    });
  typia.assert(createdPost);

  // 2. Edit the post to ensure a post history snapshot is generated
  const updatedPost =
    await api.functional.prefix.member.my.threadsPosts.posts.update(
      connection,
      {
        id: createdPost.id,
        body: {
          body: "Edited body for history.",
          is_edited: true,
        } satisfies IDiscussionboardPost.IUpdate,
      },
    );
  typia.assert(updatedPost);

  // 3. Attempt to perform an invalid post history update: use a random invalid history ID
  //    The DTO and SDK prevent us from sending forbidden/non-existent fields, so
  //    we simulate invalid by targeting a likely-unauthorized or non-existent resource
  await TestValidator.error(
    "should not allow update on non-existent or unauthorized post history snapshot",
  )(async () => {
    await api.functional.prefix.member.my.threadsPosts.postHistories.update(
      connection,
      {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: {
          edit_type: "correction",
          edit_reason: "Attempt to mutate invalid history.",
          new_body: "Trying to change immutable fields via valid DTO.",
        } satisfies IPostHistory.IUpdate,
      },
    );
  });
