  const fakeSnapshotId = typia.random<string & tags.Format<"uuid">>();
  await api.functional.prefix.member.my.threadsPosts.postHistories.erase(
    connection,
    {
      id: fakeSnapshotId,
    },
  );

  // 4. No further validation possible (API does not expose post-history read endpoint).
}

