import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";

/**
 * Validate that a member cannot delete another member's post history snapshot.
 *
 * This test ensures that DELETE
 * /prefix/member//my/threadsPosts/postHistories/:id only allows the owner
 * (snapshot's member) to delete their own post history snapshot. Any attempt by
 * another member must be forbidden/unauthorized.
 *
 * Steps:
 *
 * 1. As Member A, create a post in a thread (producing a post for which A owns any
 *    post history snapshot).
 * 2. As Member B, create another post to ensure B is a valid member in the system.
 * 3. As Member B, attempt to delete the post history (using postA.id as a proxy
 *    for a snapshot id not otherwise enumerable by the API).
 * 4. Confirm an authorization error is thrown (forbidden/unauthorized).
 *
 * Notes:
 *
 * - Since the post history snapshot id API/SDK is not exposed, we use the created
 *   postID as a test proxy.
 * - In a complete system, test would use the actual snapshot id from an edit.
 * - All steps use only the available SDK and DTOs.
 */
export async function test_api_prefix_member_my_threadsPosts_postHistories_erase_not_owner_forbidden(
  connection: api.IConnection,
) {
  // --- Step 1: Member A creates a post (simulating Member A context) ---
  const threadIdA = typia.random<string & tags.Format<"uuid">>();
  const postA = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: threadIdA,
        body: "Post by member A for cross-user delete test",
        is_edited: false,
      },
    },
  );
  typia.assert(postA);

  // --- Step 2: Member B creates a post (simulates separate account context) ---
  // In a real E2E harness, now switch connection to represent Member B
  // Here: assumes test harness swaps connection to B before next call
  const threadIdB = typia.random<string & tags.Format<"uuid">>();
  const postB = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: threadIdB,
        body: "Post by member B (ensures B is system member)",
        is_edited: false,
      },
    },
  );
  typia.assert(postB);

  // --- Step 3: Member B attempts to delete Member A's post history snapshot (proxy by using postA.id as snapshot id) ---
  await TestValidator.error(
    "forbidden: cannot delete another user's post history snapshot",
  )(async () => {
    await api.functional.prefix.member.my.threadsPosts.postHistories.erase(
      connection,
      {
        id: postA.id,
      },
    );
  });
}

