import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostEditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostEditLog";
import type { IPageIPostEditLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPostEditLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that a moderator can list post edit logs with search and pagination.
 *
 * Moderators need to audit editing activity within the discussion board. This
 * test ensures that post edit logs can be searched and paginated with various
 * filters, and the result set matches the search criteria. The moderator role's
 * permissions must be enforced: only authenticated moderators can access this
 * endpoint.
 *
 * Steps:
 *
 * 1. Create several posts in a thread as a member.
 * 2. Edit a subset of those posts individually (by the member) to generate edit
 *    logs for them.
 * 3. Switch to moderator role/login session (not explicitly modeled in API,
 *    assumed to be handled as part of the connection context or test harness).
 * 4. As moderator, call the postEditLogs index (PATCH) endpoint with:
 *
 *    - Filter by discussionboard_post_id for one of the edited posts, expect to
 *         receive only corresponding logs.
 *    - Filter by edit_member_id, expect to receive logs associated with the member
 *         edits.
 *    - No filters to fetch all logs (ensuring paginated response structure is valid
 *         and contains the created edited posts).
 *    - Optionally: test pagination (e.g. limit results per page).
 * 5. Assert that:
 *
 *    - Edit logs correspond to filters.
 *    - Pagination info is correct and present.
 *    - Output matches IPageIPostEditLog/IPostEditLog types.
 */
export async function test_api_moderator_test_moderator_lists_post_edit_logs_with_search_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a thread id to group posts
  const threadId = typia.random<string & tags.Format<"uuid">>();

  // 2. Create several posts in that thread as a member
  const memberPosts: IDiscussionboardPosts[] = [];
  for (let i = 0; i < 4; ++i) {
    const created =
      await api.functional.prefix.member.threadsPosts.posts.create(connection, {
        body: {
          discussionboard_thread_id: threadId,
          body: `Original post ${i + 1}`,
        } satisfies IDiscussionboardPosts.ICreate,
      });
    typia.assert(created);
    memberPosts.push(created);
  }

  // 3. Edit two of those posts to generate edit logs
  const now = new Date().toISOString();
  for (let i = 0; i < 2; ++i) {
    const edit =
      await api.functional.prefix.member.my.threadsPosts.posts.update(
        connection,
        {
          id: memberPosts[i].id,
          body: {
            body: `Edited content for post ${i + 1}`,
            is_edited: true,
            updated_at: now,
          } satisfies IDiscussionboardPost.IUpdate,
        },
      );
    typia.assert(edit);
    memberPosts[i] = {
      ...memberPosts[i],
      body: edit.body,
      is_edited: true,
      updated_at: edit.updated_at,
    };
  }

  // 4. (Assume moderator role) Retrieve post edit logs filtered by post id (first edited post)
  const postIdToSearch = memberPosts[0].id;
  const logsByPostId =
    await api.functional.prefix.moderator.threadsPosts.postEditLogs.index(
      connection,
      {
        body: { discussionboard_post_id: postIdToSearch },
      },
    );
  typia.assert(logsByPostId);
  TestValidator.predicate("all logs are for the specific post")(
    Array.isArray(logsByPostId.data) &&
      logsByPostId.data.every(
        (log) => log.discussionboard_post_id === postIdToSearch,
      ),
  );

  // 5. Filter by edit_member_id (author of posts)
  const memberId = memberPosts[0].discussionboard_member_id;
  const logsByMember =
    await api.functional.prefix.moderator.threadsPosts.postEditLogs.index(
      connection,
      {
        body: { edit_member_id: memberId },
      },
    );
  typia.assert(logsByMember);
  TestValidator.predicate("all logs are for the requested member")(
    Array.isArray(logsByMember.data) &&
      logsByMember.data.every((log) => log.edit_member_id === memberId),
  );

  // 6. No filters: fetch all edit logs (paginated structure)
  const logsAll =
    await api.functional.prefix.moderator.threadsPosts.postEditLogs.index(
      connection,
      {
        body: {},
      },
    );
  typia.assert(logsAll);
  TestValidator.predicate("logsAll data and pagination have correct types")(
    Array.isArray(logsAll.data) &&
      typeof logsAll.pagination === "object" &&
      typeof logsAll.pagination.current === "number",
  );

  // 7. Simple pagination check if enough logs exist (useful if underlying implementation returns > 1 edit log)
  if (logsAll.data.length >= 2) {
    const paged =
      await api.functional.prefix.moderator.threadsPosts.postEditLogs.index(
        connection,
        {
          body: {},
        },
      );
    typia.assert(paged);
    TestValidator.predicate("pagination pages >= 1")(
      paged.pagination.pages >= 1,
    );
  }
}

