import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";
import type { IPostHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPostHistory";

/**
 * Verify that a moderator can access the full audit snapshot of any post by its
 * history id.
 *
 * This test simulates a moderation scenario:
 *
 * 1. Register two users (member, moderator) as separate members.
 * 2. The member creates a thread.
 * 3. The member creates a post in the thread.
 * 4. The member edits the post to generate an edit history record.
 * 5. The moderator attempts to fetch a post-edit history detail by id for review.
 *
 * This validates:
 *
 * - Field-level access for moderators to post history entries.
 * - End-to-end post/audit traceability.
 * - Presence of all audit and content fields in the post history model.
 *
 * Note: Since there is no API for listing all histories or directly retrieving
 * a post history id generated by an edit for this test, we simulate with a
 * randomly-generated id (in actual integrated tests the id would be captured
 * from post edit response or a history list API).
 */
export async function test_api_moderator_test_moderator_get_any_post_history_by_id_for_review(
  connection: api.IConnection,
) {
  // 1. Register two users: regular member and moderator (both as members, since no schema role distinction)
  const memberId: string = typia.random<string & tags.Format<"uuid">>();
  const moderatorId: string = typia.random<string & tags.Format<"uuid">>();
  const now: string = new Date().toISOString();

  // Register member
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId,
        created_at: now,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member);

  // Register moderator (as member record for test purposes)
  const moderator = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: moderatorId,
        created_at: now,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(moderator);

  // 2. Member creates a thread
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_member_id: memberId,
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "Test thread for moderation scenario",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: now,
        updated_at: now,
      } satisfies IDiscussionboardThreads.ICreate,
    },
  );
  typia.assert(thread);

  // 3. Member creates a post in the thread
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        body: "Original post content.",
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(post);

  // 4. Member edits the post to generate a new history record
  const updatedContent = "Edited post content.";
  const updateTime = new Date(Date.now() + 60000).toISOString(); // +1min
  const updatedPost =
    await api.functional.prefix.member.my.threadsPosts.posts.update(
      connection,
      {
        id: post.id,
        body: {
          body: updatedContent,
          is_edited: true,
          updated_at: updateTime,
        } satisfies IDiscussionboardPost.IUpdate,
      },
    );
  typia.assert(updatedPost);

  // 5. Moderator fetches a post history by id.
  // NOTE: Because there is no list/history-id-from-post API, we simulate an id.
  // In integration, this would use a returned/captured id from post edit or post history list.
  const arbitraryHistoryId: string = typia.random<
    string & tags.Format<"uuid">
  >();
  const history =
    await api.functional.prefix.moderator.threadsPosts.postHistories.at(
      connection,
      {
        id: arbitraryHistoryId,
      },
    );
  typia.assert(history);
}

