import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";
import type { IPageIPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPoll";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate admin poll listing, filtering, and pagination across all members and
 * threads
 *
 * This test ensures that an admin can:
 *
 * - Retrieve all polls regardless of the creator or thread context
 * - Filter for expired (non-active) and active polls based on expires_at value
 * - Search by prompt substring
 * - Paginate over large result sets
 *
 * Steps:
 *
 * 1. Prepare a pool of polls, created by simulated different members, spanning
 *    multiple threads, with varied
 *    prompt/expiration/allow_multiple_choices/is_anonymous
 * 2. As admin, fetch all polls without filters and check all created polls are
 *    included; check pagination metadata
 * 3. Filter by expired (expires_at < now), verify only those are returned
 * 4. Filter by active (expires_at > now or expires_at is null), verify only those
 *    are returned
 * 5. Filter by prompt substring (match known substring)
 * 6. Paginate with high limit per page (performance)
 */
export async function test_api_polls_test_list_polls_with_admin_privileges_and_filters(
  connection: api.IConnection,
) {
  // 1. Data preparation: Create test polls for 3 fake members and 2 threads with varied attributes
  const now = new Date();
  const threads = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];
  const memberIds = [
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
    typia.random<string & tags.Format<"uuid">>(),
  ];

  // Helper to create polls with varying properties
  const createdPolls: IPoll[] = [];
  // Diverse prompts for substring test
  const prompts = [
    "Special Event Poll",
    "Annual Survey",
    "Special Offer Vote",
    "Feedback Poll",
    "Announcement QnA",
    "Bug Bash Poll",
    "Release Vote",
    "Roadmap Poll",
    "Testers Survey",
    "Special Beta Survey",
  ];

  for (let i = 0; i < prompts.length; ++i) {
    // Distribute thread and member associations
    const thread_id = threads[i % threads.length];
    const member_id = memberIds[i % memberIds.length];
    // Vary allow_multiple_choices and is_anonymous
    const allow_multiple_choices = i % 2 === 0;
    const is_anonymous = i % 3 === 0;
    // Alternate expiration: some expired, some active, some perpetual
    let expires_at: string | undefined = undefined;
    if (i % 3 === 0)
      expires_at = new Date(now.getTime() - 24 * 3600 * 1000).toISOString(); // expired
    else if (i % 3 === 1)
      expires_at = new Date(now.getTime() + 7 * 24 * 3600 * 1000).toISOString(); // future
    // i%3 === 2 → perpetual (expires_at omitted)

    // ---
    // Switch to 'member_id' context as needed (simulate login if test infra allows)
    // Here we'll assume the connection uses correct member when posting the poll
    // ---
    const poll = await api.functional.prefix.member.polls.create(connection, {
      body: {
        discussionboard_thread_id: thread_id,
        prompt: prompts[i],
        allow_multiple_choices,
        is_anonymous,
        ...(expires_at ? { expires_at } : {}),
      } satisfies IPoll.ICreate,
    });
    typia.assert(poll);
    createdPolls.push(poll);
  }
  // For downstream checks
  const allPollIds = new Set(createdPolls.map((p) => p.id));

  // 2. As admin: fetch all polls, no filters
  const page_all = await api.functional.prefix.admin.polls.index(connection, {
    body: {},
  });
  typia.assert(page_all);
  // Confirm all created polls are included in results
  const returnedIds = page_all.data.map((p) => p.id);
  for (const pollId of allPollIds) {
    TestValidator.predicate("admin can see poll: " + pollId)(
      returnedIds.includes(pollId),
    );
  }
  // Check pagination metadata (page structure, not deep assert here)
  TestValidator.predicate("pagination info present")(
    typeof page_all.pagination.current === "number" &&
      typeof page_all.pagination.limit === "number",
  );

  // 3. Filter: expired (expires_at < now)
  const expiredPage = await api.functional.prefix.admin.polls.index(
    connection,
    {
      body: {
        expires_before: now.toISOString(),
      },
    },
  );
  typia.assert(expiredPage);
  for (const poll of expiredPage.data) {
    TestValidator.predicate("poll expired")(
      !!poll.expires_at && poll.expires_at < now.toISOString(),
    );
  }

  // 4. Filter: active (expires_after: now)
  const activePage = await api.functional.prefix.admin.polls.index(connection, {
    body: {
      expires_after: now.toISOString(),
    },
  });
  typia.assert(activePage);
  for (const poll of activePage.data) {
    TestValidator.predicate("poll active")(
      !poll.expires_at || poll.expires_at > now.toISOString(),
    );
  }

  // 5. Filter by prompt substring
  const promptFilter = "Special";
  const promptPage = await api.functional.prefix.admin.polls.index(connection, {
    body: {
      prompt: promptFilter,
    },
  });
  typia.assert(promptPage);
  for (const poll of promptPage.data) {
    TestValidator.predicate("prompt contains substring")(
      poll.prompt.toLowerCase().includes(promptFilter.toLowerCase()),
    );
  }

  // 6. Pagination test with high page size
  const largeLimit = 100;
  const pagedResult = await api.functional.prefix.admin.polls.index(
    connection,
    {
      body: {
        // No filter, just ask for big page size if supported
        // Field names match IPoll.IRequest (no limit param in DTO but if supported add here)
        // Because DTO does not have explicit pagination fields, we validate at least default paging returns >= allPollIds
      },
    },
  );
  typia.assert(pagedResult);
  // All created polls should be found in combined page(s)
