import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";

/**
 * Validate moderator's ability to view poll details for polls with diverse
 * visibility and creators, including error scenarios.
 *
 * This test ensures that a moderator can retrieve any poll's full details
 * (prompt, anonymity, expiration, voting configuration, and creator) regardless
 * of which member originally created the poll. It validates access breadth,
 * correct data exposure, and proper error handling for invalid IDs. The test
 * covers both normal retrieval and attempting to access a non-existent poll
 * (404 scenario).
 *
 * Steps:
 *
 * 1. Create several polls (at least two), each with different configuration for
 *    prompt, allow_multiple_choices, is_anonymous, and expiration.
 * 2. As moderator, retrieve each poll using the moderator poll details endpoint,
 *    and assert all fields match expectations.
 * 3. Attempt to retrieve a poll by a random/non-existent UUID as id, expecting an
 *    error (e.g. 404) is thrown.
 */
export async function test_api_polls_test_view_poll_details_as_moderator_various_visibility(
  connection: api.IConnection,
) {
  // 1. Create diverse polls via the member API
  const createdPolls: IPoll[] = [];
  for (let i = 0; i < 2; ++i) {
    const createBody: IPoll.ICreate = {
      discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
      prompt: `Prompt ${i} - ${RandomGenerator.paragraph()()}`,
      allow_multiple_choices: i % 2 === 0,
      is_anonymous: i % 2 === 1,
      expires_at:
        i === 0
          ? (new Date(Date.now() + 86400000).toISOString() as string &
              tags.Format<"date-time">)
          : undefined,
    };
    const poll = await api.functional.prefix.member.polls.create(connection, {
      body: createBody,
    });
    typia.assert(poll);
    createdPolls.push(poll);
  }

  // 2. As moderator, retrieve each created poll by id
  for (const poll of createdPolls) {
    const retrieved = await api.functional.prefix.moderator.polls.at(
      connection,
      { id: poll.id },
    );
    typia.assert(retrieved);
    // 3. Validate all major fields
    TestValidator.equals("poll id")(retrieved.id)(poll.id);
    TestValidator.equals("discussionboard_thread_id")(
      retrieved.discussionboard_thread_id,
    )(poll.discussionboard_thread_id);
    TestValidator.equals("created_by_member_id")(
      retrieved.created_by_member_id,
    )(poll.created_by_member_id);
    TestValidator.equals("prompt")(retrieved.prompt)(poll.prompt);
    TestValidator.equals("allow_multiple_choices")(
      retrieved.allow_multiple_choices,
    )(poll.allow_multiple_choices);
    TestValidator.equals("is_anonymous")(retrieved.is_anonymous)(
      poll.is_anonymous,
    );
    TestValidator.equals("expires_at")(retrieved.expires_at ?? null)(
      poll.expires_at ?? null,
    );
    TestValidator.equals("created_at")(retrieved.created_at)(poll.created_at);
  }

  // 4. Error scenario: Retrieve non-existent poll id
  await TestValidator.error(
    "moderator should receive error for non-existent poll",
  )(async () => {
    await api.functional.prefix.moderator.polls.at(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

