/**
 * Test: Prevent creating duplicate bans for the same member
 *
 * This test validates that the system prevents the creation of a duplicate ban
 * for a member who is already banned.
 *
 * Business context: Banning the same member multiple times should not be
 * allowed unless previous bans have been lifted. This constraint is enforced to
 * prevent administrative errors and inconsistent state.
 *
 * Workflow:
 *
 * 1. Prepare a unique admin_id and banned_member_id.
 * 2. Successfully create a ban for the chosen member by the admin.
 * 3. Attempt to create another ban for the same member (with a different
 *    ban_reason and banned_at).
 * 4. Confirm the system throws an error for the duplicate ban.
 */
export async function test_api_prefix_admin_bans_test_create_duplicate_ban_for_same_member(
  connection: api.IConnection,
) {
  // Step 1: Prepare required IDs
  const admin_id: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const banned_member_id: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const initial_banned_at: string = new Date().toISOString();
  const later_banned_at: string = new Date(Date.now() + 60000).toISOString();

  // Step 2: Issue the first ban (should succeed)
  const firstBan = await api.functional.prefix.admin.bans.create(connection, {
    body: {
      banned_member_id,
      banned_guest_id: null,
      admin_id,
