import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPostReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostReaction";
import type { IPageIDiscussionboardPostReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardPostReaction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test reaction listing and permission boundary enforcement for post reactions
 * API.
 *
 * This test verifies that a member can only retrieve reactions to posts
 * according to their permissions. It simulates three members (A, B, C) and a
 * single post (X). Two members (A and B) create distinct reactions on Post X.
 * Each member then queries the reactions – as owner/creator, as unrelated
 * member, and with explicit filtering – to ensure:
 *
 * - Members only see their own reactions (unless broader permissions apply)
 * - No data leaks occur across account boundaries
 * - Filtering by member ID yields only the expected member’s reactions
 *
 * Steps:
 *
 * 1. Generate three member UUIDs (A, B, C) and one post UUID (X).
 * 2. Member A creates a reaction to Post X.
 * 3. Member B creates a different reaction to Post X.
 * 4. As Member A, fetch all reactions for Post X; verify only A’s reaction is
 *    visible.
 * 5. As Member B, fetch all reactions for Post X; verify only B’s reaction is
 *    visible.
 * 6. As unrelated Member C, fetch all reactions for Post X; verify none (or only
 *    C’s if any exist).
 * 7. Filtering by member ID returns only the expected records.
 */
export async function test_api_prefix_member_postReactions_test_list_post_reactions_with_member_permissions(
  connection: api.IConnection,
) {
  // 1. Simulate three members and one post
  const memberAId = typia.random<string & tags.Format<"uuid">>();
  const memberBId = typia.random<string & tags.Format<"uuid">>();
  const memberCId = typia.random<string & tags.Format<"uuid">>();
  const postXId = typia.random<string & tags.Format<"uuid">>();

  // 2. Member A creates a 'heart' reaction to Post X
  const reactionA = await api.functional.prefix.member.postReactions.create(
    connection,
    {
      body: {
        discussionboard_post_id: postXId,
        discussionboard_member_id: memberAId,
        reaction_type: "heart",
      } satisfies IDiscussionboardPostReaction.ICreate,
    },
  );
  typia.assert(reactionA);

  // 3. Member B creates a 'laugh' reaction to Post X
  const reactionB = await api.functional.prefix.member.postReactions.create(
    connection,
    {
      body: {
        discussionboard_post_id: postXId,
        discussionboard_member_id: memberBId,
        reaction_type: "laugh",
      } satisfies IDiscussionboardPostReaction.ICreate,
    },
  );
  typia.assert(reactionB);

  // 4. As Member A: list all reactions for Post X
  // (Assume connection for Member A authentication; real-world test would require user switching.)
  const respA = await api.functional.prefix.member.postReactions.index(
    connection,
    {
      body: {
        discussionboard_post_id: postXId,
      } satisfies IDiscussionboardPostReaction.IRequest,
    },
  );
  typia.assert(respA);
  TestValidator.predicate("Member A sees own reaction")(
    respA.data.some((r) => r.discussionboard_member_id === memberAId),
  );
  TestValidator.predicate(
    "Member A does not see Member B's reaction unless permitted",
  )(!respA.data.some((r) => r.discussionboard_member_id === memberBId));

  // 5. As Member B: list all reactions for Post X
  // (Assume connection for Member B authentication)
  const respB = await api.functional.prefix.member.postReactions.index(
    connection,
    {
      body: {
        discussionboard_post_id: postXId,
      } satisfies IDiscussionboardPostReaction.IRequest,
    },
  );
  typia.assert(respB);
  TestValidator.predicate("Member B sees own reaction")(
    respB.data.some((r) => r.discussionboard_member_id === memberBId),
  );
  TestValidator.predicate(
    "Member B does not see Member A's reaction unless permitted",
  )(!respB.data.some((r) => r.discussionboard_member_id === memberAId));

  // 6. As unrelated Member C: list all reactions for Post X
  const respC = await api.functional.prefix.member.postReactions.index(
    connection,
    {
      body: {
        discussionboard_post_id: postXId,
      } satisfies IDiscussionboardPostReaction.IRequest,
    },
  );
  typia.assert(respC);
  TestValidator.equals("Member C reaction list is empty for Post X")(
    respC.data.length,
  )(0);

  // 7. Explicit filtering by member—should return only the correct member’s reactions
  const respAFiltered = await api.functional.prefix.member.postReactions.index(
    connection,
    {
      body: {
        discussionboard_post_id: postXId,
        discussionboard_member_id: memberAId,
      } satisfies IDiscussionboardPostReaction.IRequest,
    },
  );
  typia.assert(respAFiltered);
  TestValidator.predicate("Filtered A: only Member A's reactions")(
    respAFiltered.data.every((r) => r.discussionboard_member_id === memberAId),
  );

  const respBFiltered = await api.functional.prefix.member.postReactions.index(
    connection,
    {
      body: {
        discussionboard_post_id: postXId,
        discussionboard_member_id: memberBId,
      } satisfies IDiscussionboardPostReaction.IRequest,
    },
  );
  typia.assert(respBFiltered);
  TestValidator.predicate("Filtered B: only Member B's reactions")(
    respBFiltered.data.every((r) => r.discussionboard_member_id === memberBId),
  );

  const respCFiltered = await api.functional.prefix.member.postReactions.index(
    connection,
    {
      body: {
        discussionboard_post_id: postXId,
        discussionboard_member_id: memberCId,
      } satisfies IDiscussionboardPostReaction.IRequest,
    },
  );
  typia.assert(respCFiltered);
  TestValidator.equals("Filtered C: reaction list is empty")(
    respCFiltered.data.length,
  )(0);
}

