/**
 * Validate successful creation of a moderation action by a moderator.
 *
 * This test ensures that when all necessary fields—including moderator_id,
 * report_id, affected_post_id, affected_member_id, action_type,
 * action_description, and action_timestamp—are provided, the API correctly
 * records a moderation action and returns the created entry as expected.
 *
 * Steps:
 *
 * 1. Prepare well-formed moderation action input with all schema-required fields.
 * 2. Call the create moderation action API as a moderator (using hypothetical or
 *    random moderator_id).
 * 3. Assert that the API returns a moderation action object matching the input
 *    data (except for server-generated properties like id).
 * 4. Validate all properties of the returned moderation action entity, including
 *    correct data structure and value integrity (except for id).
 */
export async function test_api_prefix_moderator_moderationActions_create(
  connection: api.IConnection,
) {
  // 1. Prepare complete and valid input data for a moderation action
  const input: IModerationAction.ICreate = {
    moderator_id: typia.random<string & tags.Format<"uuid">>(),
    report_id: typia.random<string & tags.Format<"uuid">>(),
    affected_post_id: typia.random<string & tags.Format<"uuid">>(),
