    action_type: "warned",
    action_description: "User sent spam links and has been warned.",
    action_timestamp: new Date().toISOString(),
  };

  // 2. Call the API to create the moderation action
  const created =
    await api.functional.prefix.moderator.moderationActions.create(connection, {
      body: input,
    });
