import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationAction";

/**
 * 중재/모더레이션 액션을 생성할 때 잘못된(존재하지 않는) 외래키를 입력한 경우 오류가 발생함을 검증합니다.
 *
 * Referential integrity(참조 무결성)를 보장하도록, 다음 외래키 필드 중 아무거나 잘못되면 API가 거부해야 합니다.
 *
 * - Moderator_id
 * - Affected_post_id
 * - Affected_member_id
 * - Report_id
 *
 * 테스트는 다음의 케이스로 이루어집니다:
 *
 * 1. 네 개의 FK 모두 무작위 UUID(존재하지 않을 확률이 매우 높음)로 입력 → 반드시 실패해야 함
 * 2. 각 FK별로 하나씩만 무작위(UUID)로 설정, 나머진 null 혹은 무시 → 각 경우별로 실패해야 함
 *
 * 이 검증은 데이터 무결성 보장과 연관 데이터의 신뢰성 유지에 필수적입니다.
 */
export async function test_api_prefix_moderator_moderationActions_test_create_moderation_action_with_invalid_foreign_keys_fails(
  connection: api.IConnection,
) {
  // 1. 모든 FK 필드를 무작위 UUID(존재하지 않는 값)로 채워: 반드시 referential integrity 오류를 반환해야 함
  const randomModeratorId = typia.random<string & tags.Format<"uuid">>();
  const randomAffectedPostId = typia.random<string & tags.Format<"uuid">>();
  const randomAffectedMemberId = typia.random<string & tags.Format<"uuid">>();
  const randomReportId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();

  await TestValidator.error("모든 FK가 잘못되었을 때 실패해야 함")(async () => {
    await api.functional.prefix.moderator.moderationActions.create(connection, {
      body: {
        moderator_id: randomModeratorId,
        affected_post_id: randomAffectedPostId,
        affected_member_id: randomAffectedMemberId,
        report_id: randomReportId,
        action_type: "warned",
        action_description: "모든 외래키가 잘못된 케이스.",
        action_timestamp: now,
      } satisfies IModerationAction.ICreate,
    });
  });

  // 2. 각각의 FK 필드만 무작위 UUID로 주입, 나머지는 null (또는 최소값) 처리하여 각 FK 독립 검증
  const fkFields: Array<keyof IModerationAction.ICreate> = [
    "moderator_id",
    "affected_post_id",
    "affected_member_id",
    "report_id",
  ];
  for (const field of fkFields) {
    const input: IModerationAction.ICreate = {
      moderator_id:
        field === "moderator_id"
          ? randomModeratorId
          : typia.random<string & tags.Format<"uuid">>(),
      affected_post_id:
        field === "affected_post_id" ? randomAffectedPostId : null,
      affected_member_id:
        field === "affected_member_id" ? randomAffectedMemberId : null,
      report_id: field === "report_id" ? randomReportId : null,
      action_type: "deleted_post",
      action_description: `${field}만 잘못된 FK로 설정된 케이스`,
      action_timestamp: now,
    };
    await TestValidator.error(`${field}만 잘못된 경우 실패해야 함`)(
      async () => {
        await api.functional.prefix.moderator.moderationActions.create(
          connection,
          {
            body: input,
          },
        );
      },
    );
  }
}

