 * 1. Prepare a valid IModerationAction.ICreate object with all required and some
 *    optional fields, using realistic UUIDs, timestamps, and types.
 * 2. Invoke the moderation action creation endpoint as admin.
 * 3. Assert that the response conforms to IModerationAction schema and all values
 *    match (moderator_id, action_type, action_description, etc).
 */
export async function test_api_prefix_admin_moderationActions_create(
  connection: api.IConnection,
) {
  // 1. Prepare data for moderation action creation
  const now: string & tags.Format<"date-time"> =
    new Date().toISOString() as string & tags.Format<"date-time">;
  const data: IModerationAction.ICreate = {
    moderator_id: typia.random<string & tags.Format<"uuid">>(),
    report_id: typia.random<string & tags.Format<"uuid">>(),
    affected_post_id: typia.random<string & tags.Format<"uuid">>(),
    affected_member_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "warned",
    action_description:
      "Auto-moderation: excessive spam detected by admin bot.",
    action_timestamp: now,
  };

  // 2. Call moderation action create API
  const action = await api.functional.prefix.admin.moderationActions.create(
    connection,
    { body: data },
  );
  typia.assert(action);

  // 3. Ensure key fields match request (except id, which is new and type-generated)
  TestValidator.equals("moderator_id")(action.moderator_id)(data.moderator_id);
  TestValidator.equals("report_id")(action.report_id)(data.report_id);
  TestValidator.equals("affected_post_id")(action.affected_post_id)(
