  );
  TestValidator.equals("action_type")(action.action_type)(data.action_type);
  TestValidator.equals("action_description")(action.action_description)(
    data.action_description,
  );
  TestValidator.equals("action_timestamp")(action.action_timestamp)(
    data.action_timestamp,
  );
  // id (uuid) must exist and conform to type
  TestValidator.predicate("id is uuid format")(
