/**
 * Test creation of a moderation action with missing required fields is NOT
 * possible at runtime (TypeScript will catch errors), but omitting
 * optional/nullable fields (such as report_id) is allowed and should not result
 * in an error.
 *
 * This function verifies that the creation API only succeeds when all required
 * fields are present, and that omitting optional fields is accepted. According
 * to the guidelines, attempts to create a moderation action missing required
 * fields (like action_type or action_description) cannot be performed at
 * runtime because TypeScript enforces their presence. Therefore, only the
 * omission of optional (nullable) fields is tested, and it should not throw an
 * error.
 *
 * Steps:
 *
 * 1. Prepare a fully valid moderation action body and create successfully.
 * 2. Prepare a body omitting the optional report_id field and assert the call
 *    succeeds.
 * 3. Prepare a body where report_id is explicitly null and assert the call
 *    succeeds.
 */
export async function test_api_prefix_admin_moderationActions_create_with_missing_optional_fields(
  connection: api.IConnection,
) {
  // 1. Fully valid moderation action
  const validBody: IModerationAction.ICreate = {
    moderator_id: typia.random<string & tags.Format<"uuid">>(),
    action_type: "warned",
    action_description: "Test moderation action.",
    action_timestamp: new Date().toISOString(),
    report_id: typia.random<string & tags.Format<"uuid">>(),
    affected_post_id: typia.random<string & tags.Format<"uuid">>(),
    affected_member_id: typia.random<string & tags.Format<"uuid">>(),
  };
  const output = await api.functional.prefix.admin.moderationActions.create(
    connection,
    {
      body: validBody,
    },
  );
  typia.assert(output);

  // 2. Body omitting optional report_id (should succeed)
  const withoutReportId: IModerationAction.ICreate = {
    ...validBody,
  };
  delete (withoutReportId as any).report_id; // TypeScript won't allow as required, only type assertion workaround for test code generation
  await api.functional.prefix.admin.moderationActions.create(connection, {
    body: withoutReportId,
  });

  // 3. Body with report_id explicitly set to null (should succeed)
  const withNullReportId: IModerationAction.ICreate = {
    ...validBody,
    report_id: null,
  };
  await api.functional.prefix.admin.moderationActions.create(connection, {
    body: withNullReportId,
  });
}

