import api from "@ORGANIZATION/PROJECT-api";
import type { ISuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/ISuspension";

/**
 * Test that a moderator can update their own suspension log with valid
 * schema-compliant fields.
 *
 * This test confirms that, when authenticated as a moderator, an update to a
 * suspension record they own is correctly applied and reflected in the returned
 * record. The allowed updatable fields include (but may not be limited to)
 * suspension_reason and suspension_ends_at, following the type definition.
 *
 * Step-by-step process:
 *
 * 1. [Prerequisite] Create a suspension record using moderator privileges
 *    (ensuring moderator_id matches the authenticated moderator)
 * 2. Prepare an ISuspension.IUpdate with valid new values (change at least
 *    suspension_reason and/or suspension_ends_at)
 * 3. Call the update API as the owning moderator, targeting the record from step 1
 * 4. Assert the API call is successful and only allowed fields change, while
 *    immutable fields remain unchanged
 */
export async function test_api_prefix_moderator_my_suspensions_test_update_own_suspension_with_valid_data(
  connection: api.IConnection,
) {
  // 1. [Prerequisite] Create a suspension record as this moderator
  const origSuspension =
    await api.functional.prefix.moderator.suspensions.create(connection, {
      body: {
        moderator_id: typia.random<string & tags.Format<"uuid">>(),
        suspended_member_id: typia.random<string & tags.Format<"uuid">>(),
        suspension_reason: "Original reason for suspension",
        suspension_started_at: new Date().toISOString(),
        suspension_ends_at: null,
      },
    });
  typia.assert(origSuspension);

  // 2. Prepare a valid update for allowed fields
  const updatedReason = "Updated suspension reason - test";
  const updatedEndsAt = new Date(
    Date.now() + 1000 * 60 * 60 * 24,
  ).toISOString(); // +1 day
  const updateBody = {
    suspension_reason: updatedReason,
    suspension_ends_at: updatedEndsAt,
  } satisfies ISuspension.IUpdate;

  // 3. Call the update API (must own this record)
  const updated = await api.functional.prefix.moderator.my.suspensions.update(
    connection,
    {
      id: origSuspension.id,
      body: updateBody,
    },
  );
  typia.assert(updated);

  // 4. Validate that updates are reflected and immutable fields unchanged
  TestValidator.equals("suspension_reason updated")(updated.suspension_reason)(
    updatedReason,
  );
  TestValidator.equals("suspension_ends_at updated")(
    updated.suspension_ends_at,
  )(updatedEndsAt);
  // Immutable fields stay the same
  TestValidator.equals("moderator_id unchanged")(updated.moderator_id)(
    origSuspension.moderator_id,
  );
  TestValidator.equals("suspended_member_id unchanged")(
    updated.suspended_member_id,
  )(origSuspension.suspended_member_id);
  TestValidator.equals("suspension_started_at unchanged")(
    updated.suspension_started_at,
  )(origSuspension.suspension_started_at);
}

