/**
 * Validate that an admin user can update their own suspension record via the
 * /my/ endpoint.
 *
 * This E2E test verifies the functional correctness and schema conformance of
 * the /prefix/admin//my/suspensions/{id} PUT endpoint by executing the
 * real-world business flow:
 *
 * 1. Prerequisite: Create a suspension record with the current admin as the
 *    moderator (using the create API), representing an existing restriction
 *    that the admin wishes to modify.
 * 2. Using the /my/suspensions/{id} update API, change allowed fields
 *    (suspension_reason and suspension_ends_at) to simulate administrative
 *    correction/extension.
 * 3. Confirm that the updated record still belongs to the admin (moderator_id
 *    remains unchanged).
 * 4. Assert that the update was correctly applied to schema fields, and that other
 *    properties remain unaffected (field-level validation).
 *
 * No non-schema fields exist, so the test focuses on DTO-defined properties
 * exclusively.
 */
export async function test_api_prefix_admin_my_suspensions_test_update_own_suspension_as_admin(
  connection: api.IConnection,
) {
  // 1. Create a suspension where moderator is the current admin
  const createInput: ISuspension.ICreate = {
    moderator_id: typia.random<string & tags.Format<"uuid">>(),
    suspended_member_id: typia.random<string & tags.Format<"uuid">>(),
    suspension_reason: "Initial reason",
    suspension_started_at: new Date().toISOString(),
    suspension_ends_at: null,
  };
  const original: ISuspension =
    await api.functional.prefix.admin.suspensions.create(connection, {
      body: createInput,
    });
  typia.assert(original);

  // 2. Update allowed fields via /my/suspensions/{id}
  const updateInput: ISuspension.IUpdate = {
    suspension_reason: "Updated reason",
    suspension_ends_at: new Date(Date.now() + 7 * 86400 * 1000).toISOString(), // 7 days later
  };
  const updated: ISuspension =
    await api.functional.prefix.admin.my.suspensions.update(connection, {
      id: original.id,
      body: updateInput,
    });
  typia.assert(updated);

  // 3. Confirm moderator_id has not changed (and still reflects admin ownership)
  TestValidator.equals("moderator unchanged")(updated.moderator_id)(
    original.moderator_id,
  );

  // 4. Confirm allowed fields are updated as requested
  TestValidator.equals("suspension_reason updated")(updated.suspension_reason)(
    updateInput.suspension_reason,
  );
