import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/ISuspension";

/**
 * Validate that updating a suspension log with prohibited or undefined fields
 * is properly rejected by the schema validation logic.
 *
 * This test confirms that only explicitly defined schema properties are
 * permitted in suspension record updates, and any attempt to include non-schema
 * properties (e.g., extra meta fields) triggers a validation error.
 *
 * Business context:
 *
 * - An admin (moderator) manages suspension logs via /my/suspensions/:id
 * - Updates may only include whitelisted, schema-defined properties (see
 *   ISuspension.IUpdate)
 *
 * Test steps:
 *
 * 1. Precondition: Create a valid suspension record as an admin using the provided
 *    API, keeping its id
 * 2. Attempt to update this suspension using a body that contains only
 *    schema-compliant properties (should succeed)
 * 3. Attempt to update this suspension including a non-existent/undefined meta
 *    property (e.g., body: {..., meta: {...}}), expecting a validation error
 * 4. Repeat with various types of illegal extra fields (e.g., "foo": 123, or
 *    "notes": "string") to confirm robust schema enforcement
 * 5. Confirm the API permits only updates with valid fields, and all attempts with
 *    unexpected properties (not in ISuspension.IUpdate) are strictly rejected.
 */
export async function test_api_prefix_admin_my_suspensions_test_update_suspension_as_admin_with_invalid_field(
  connection: api.IConnection,
) {
  // 1. Create a valid suspension (precondition)
  const createInput: ISuspension.ICreate = {
    moderator_id: typia.random<string & tags.Format<"uuid">>(),
    suspended_member_id: typia.random<string & tags.Format<"uuid">>(),
    suspension_reason: "Test reason for schema validation",
    suspension_started_at: new Date().toISOString(),
    suspension_ends_at: null,
  };
  const suspension = await api.functional.prefix.admin.suspensions.create(
    connection,
    { body: createInput },
  );
  typia.assert(suspension);

  // 2. Valid update: only schema properties
  const validUpdate: ISuspension.IUpdate = {
    suspension_reason: "Updated (valid) suspension reason",
    suspension_ends_at: new Date(Date.now() + 86400000).toISOString(),
  };
  const updated = await api.functional.prefix.admin.my.suspensions.update(
    connection,
    {
      id: suspension.id,
      body: validUpdate,
    },
  );
  typia.assert(updated);

  // 3. Invalid update: inject a non-schema property (e.g., meta)
  await TestValidator.error("should reject update with extra meta property")(
    async () => {
      await api.functional.prefix.admin.my.suspensions.update(connection, {
        id: suspension.id,
        body: {
          ...validUpdate,
          meta: { foo: "bar" }, // NOT allowed
        } as any,
      });
    },
  );

  // 4. Invalid update: inject other wrong/extra fields
  await TestValidator.error(
    "should reject update with arbitrary extra field (foo)",
  )(async () => {
    await api.functional.prefix.admin.my.suspensions.update(connection, {
      id: suspension.id,
      body: {
        ...validUpdate,
        foo: 123, // NOT allowed
      } as any,
    });
  });

  await TestValidator.error("should reject update with arbitrary notes field")(
    async () => {
      await api.functional.prefix.admin.my.suspensions.update(connection, {
        id: suspension.id,
        body: {
          ...validUpdate,
          notes: "Not a schema field", // NOT allowed
        } as any,
      });
    },
  );
}

