import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISuspension } from "@ORGANIZATION/PROJECT-api/lib/structures/ISuspension";

/**
 * Verify that a moderator can successfully perform a hard delete of their own
 * suspension record.
 *
 * Business context: Moderators can issue suspensions to members, and might
 * sometimes need to hard-delete (permanently remove) their own issued
 * suspension records. This test verifies that a moderator can delete a
 * suspension record they own (created by themselves) using the /my/ path, and
 * that the record is truly gone post-deletion (not just soft-deleted).
 *
 * Step-by-step process:
 *
 * 1. Create a suspension entry as the current moderator (using POST
 *    /prefix/moderator//suspensions).
 * 2. Perform a hard delete request via DELETE
 *    /prefix/moderator//my/suspensions/{id} for the suspension created in step
 *    1.
 * 3. Assert that the deletion request succeeds (does not throw error).
 * 4. Attempt to delete the already deleted suspension, and expect an error (since
 *    the record should no longer exist).
 *
 * Note: Since there is no provided endpoint for directly retrieving a
 * suspension by id, post-deletion confirmation is performed by observing an
 * error on repeat delete attempts.
 */
export async function test_api_prefix_test_delete_own_suspension_success(
  connection: api.IConnection,
) {
  // 1. Create a suspension as the current moderator
  const suspension = await api.functional.prefix.moderator.suspensions.create(
    connection,
    {
      body: {
        moderator_id: typia.random<string & tags.Format<"uuid">>(),
        suspended_member_id: typia.random<string & tags.Format<"uuid">>(),
        suspension_reason: "Violation of community standards",
        suspension_started_at: new Date().toISOString(),
        suspension_ends_at: null,
      } satisfies ISuspension.ICreate,
    },
  );
  typia.assert(suspension);

  // 2. Perform a hard delete of the suspension just created
  await api.functional.prefix.moderator.my.suspensions.erase(connection, {
    id: suspension.id,
  });

  // 3. Attempt to delete the already deleted suspension again; should throw error
  await TestValidator.error("suspension should not be found after deletion")(
    () =>
      api.functional.prefix.moderator.my.suspensions.erase(connection, {
        id: suspension.id,
      }),
  );
}

