  const updatePayload: IDiscussionboardIncidentReport.IUpdate = {
    incident_code: initial.incident_code, // required in update schema
    status: newStatus,
    reporter_id: initial.reporter_id,
    description: newDescription,
    updated_at: new Date(Date.now() + 60000).toISOString(), // simulate updated_at as later
  };

  // 3. Update the incident report by its ID
  const updated: IDiscussionboardIncidentReport =
    await api.functional.prefix.admin.policyAudit.incidentReports.update(
      connection,
      {
        incidentReportId: initial.id,
        body: updatePayload,
      },
    );
  typia.assert(updated);

  // 4. Verify updated fields
  TestValidator.equals("status updated")(updated.status)(newStatus);
  TestValidator.equals("description updated")(updated.description)(
    newDescription,
  );
  TestValidator.equals("incident code persists")(updated.incident_code)(
    initial.incident_code,
  );
  TestValidator.equals("reporter_id persists")(updated.reporter_id ?? null)(
    initial.reporter_id ?? null,
  );
  TestValidator.equals("updated_at changes")(updated.updated_at)(
    updatePayload.updated_at,
  );

  // 5. Unchanged fields: created_at must remain as before
  TestValidator.equals("created_at unchanged")(updated.created_at)(
    initial.created_at,
  );
}

