    await api.functional.prefix.admin.policyAudit.incidentReports.create(
      connection,
      {
        body: {
          incident_code: `INCIDENT-${new Date().toISOString().replace(/\D/g, "").slice(0, 12)}`,
          status: "OPEN",
          description: "Full description of incident.",
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        } satisfies IDiscussionboardIncidentReport.ICreate,
      },
    );
