  // 2. Attempt to update with a missing required field (e.g. omit 'description')
  await TestValidator.error(
    "Should fail when updating with missing required fields",
  )(async () => {
    // Construct partial (invalid) update payload
    const partialUpdate = {
      incident_code: report.incident_code,
      status: "IN_REVIEW",
      updated_at: new Date().toISOString(),
      // description omitted intentionally
      // reporter_id is optional
    } as unknown as IDiscussionboardIncidentReport.IUpdate; // intentional type hack for test

    await api.functional.prefix.admin.policyAudit.incidentReports.update(
      connection,
      {
        incidentReportId: report.id,
        body: partialUpdate,
      },
    );
  });
