  const read = await api.functional.prefix.member.postReactions.at(connection, {
    id: reaction.id,
  });
  typia.assert(read);

  // 5. 필드 값 검증
  TestValidator.equals("reaction.id")(read.id)(reaction.id);
  TestValidator.equals("reaction.post")(read.discussionboard_post_id)(post.id);
  TestValidator.equals("reaction.member")(read.discussionboard_member_id)(
    memberId,
  );
  TestValidator.equals("reaction.reaction_type")(read.reaction_type)("heart");
}

