import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostReaction";

/**
 * 성공적으로 자신의 게시글 반응을 갱신하는 시나리오 검증
 *
 * 인증된 멤버가 직접 작성한 토론글(포스트)에 대해 기존에 남긴 반응을 다른 타입(예: 'like'→'love')으로 변경할 수 있는지
 * 검증합니다. 테스트를 위해 토론 스레드 생성, 멤버 작성 포스트, 최초 반응 생성 후, 동일 멤버로 반응타입을 수정합니다. 실제 수정 이후
 * 반영된 reaction_type을 확인하여 정상적으로 갱신되었는지 검증합니다.
 *
 * 주요 단계:
 *
 * 1. 새로운 토론 스레드 생성 (discussionboard_threads)
 * 2. 방금 생성한 스레드에 포스트(게시글) 등록 (discussionboard_posts)
 * 3. 해당 포스트에 멤버가 첫 반응(예: 'like') 생성 (discussionboard_post_reactions)
 * 4. 첫 반응 레코드 id를 활용하여 reaction_type을 변경 (예: 'love' 등)
 * 5. API 응답의 reaction_type이 변경 요청값과 일치하는지 검증
 */
export async function test_api_prefix_member_my_postReactions_test_update_own_post_reaction_success(
  connection: api.IConnection,
) {
  // 1. 새로운 토론 스레드 생성
  const threadCategoryId = typia.random<string & tags.Format<"uuid">>();
  const threadNow = new Date().toISOString();
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: threadCategoryId,
        title: RandomGenerator.alphabets(12),
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: threadNow,
        updated_at: threadNow,
      } satisfies IDiscussionboardThreads.ICreate,
    },
  );
  typia.assert(thread);

  // 2. 해당 스레드에 포스트(게시글) 등록
  const postBodyText = RandomGenerator.content()()();
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        body: postBodyText,
        is_edited: false,
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(post);

  // 3. 해당 포스트에 멤버가 첫 반응 생성 (예: like)
  const initialReactionType = "like";
  const reaction = await api.functional.prefix.member.postReactions.create(
    connection,
    {
      body: {
        discussionboard_post_id: post.id,
        discussionboard_member_id: post.discussionboard_member_id,
        reaction_type: initialReactionType,
      } satisfies IDiscussionboardPostReaction.ICreate,
    },
  );
  typia.assert(reaction);

  // 4. 생성된 반응의 id로 reaction_type을 변경 (like → love)
  const updatedReactionType = "love";
  const updated = await api.functional.prefix.member.my.postReactions.update(
    connection,
    {
      id: reaction.id,
      body: {
        reaction_type: updatedReactionType,
      } satisfies IDiscussionboardPostReaction.IUpdate,
    },
  );
  typia.assert(updated);

  // 5. API 응답의 reaction_type이 요청한 값과 일치하는지, 그리고 불변 필드는 동일한지 확인
  TestValidator.equals("reaction_type 변경됨")(updated.reaction_type)(
    updatedReactionType,
  );
  TestValidator.equals("reaction id 동일")(updated.id)(reaction.id);
  TestValidator.equals("수정 후에도 member id 동일")(
    updated.discussionboard_member_id,
  )(reaction.discussionboard_member_id);
  TestValidator.equals("포스트 id 불변")(updated.discussionboard_post_id)(
    reaction.discussionboard_post_id,
  );
}

