import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostReaction } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostReaction";

/**
 * Validate that post reaction updates are restricted to reaction owners.
 *
 * This test ensures that only the member who created a post reaction can update
 * it.
 *
 * Steps:
 *
 * 1. Create and register an owner member.
 * 2. Create a thread as the owner.
 * 3. Create a post in that thread as the owner.
 * 4. Create a reaction for that post as the owner.
 * 5. Create and register a non-owner member.
 * 6. Attempt to update the reaction (created by the owner) as the non-owner.
 * 7. Assert that the update attempt fails due to lack of ownership
 *    (forbidden/unauthorized).
 */
export async function test_api_prefix_test_update_post_reaction_forbidden_for_non_owner(
  connection: api.IConnection,
) {
  // 1. Create and register owner member
  const ownerMemberId = typia.random<string & tags.Format<"uuid">>();
  const ownerCreate = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: ownerMemberId,
        created_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(ownerCreate);

  // 2. Create a thread as owner (assume connection context is that of owner)
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "E2E test thread",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(thread);

  // 3. Create a post within that thread as owner
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        body: "This is a test post for reaction update auth scenario.",
      },
    },
  );
  typia.assert(post);

  // 4. Create a post reaction as owner
  const reaction = await api.functional.prefix.member.postReactions.create(
    connection,
    {
      body: {
        discussionboard_post_id: post.id,
        discussionboard_member_id: ownerMemberId,
        reaction_type: "heart",
      },
    },
  );
  typia.assert(reaction);

  // 5. Create and register a non-owner member
  const nonOwnerMemberId = typia.random<string & tags.Format<"uuid">>();
  const nonOwnerCreate =
    await api.functional.prefix.member.actors.members.create(connection, {
      body: {
        id: nonOwnerMemberId,
        created_at: new Date().toISOString(),
      },
    });
  typia.assert(nonOwnerCreate);

  // 6. Switch authentication context to non-owner (simulate non-owner is now authenticated)
  // In a real E2E environment, this requires appropriate connection/token context management.
  // For this test code, assume 'connection' now represents the non-owner.

  // 7. Attempt to update the reaction as the non-owner
  const updateDto = {
    reaction_type: "laugh",
  } satisfies IDiscussionboardPostReaction.IUpdate;
  await TestValidator.error("non-owner cannot update post reaction")(
    async () => {
      await api.functional.prefix.member.my.postReactions.update(connection, {
        id: reaction.id,
        body: updateDto,
      });
    },
  );
}

