/**
 * Validate that a member cannot delete a post reaction they do not own.
 *
 * This test ensures that post reaction deletion is strictly restricted to the
 * reaction's creator. A reaction is created with memberA, and memberB (a
 * different user) attempts deletion, which must fail.
 *
 * Test steps:
 *
 * 1. Register memberA (the reaction creator), obtaining a unique id
 * 2. Register memberB (who will attempt unauthorized deletion)
 * 3. Create a thread as memberA
 * 4. Create a post in the thread as memberA
 * 5. Create a reaction for the post as memberA
 * 6. Simulate acting as memberB (by swapping the member id in connection headers)
 * 7. Attempt reaction deletion as memberB
 * 8. Assert that a forbidden (or appropriate) error results
 */
export async function test_api_prefix_test_delete_post_reaction_forbidden_for_non_owner(
  connection: api.IConnection,
) {
  // 1. Register memberA (the reaction creator)
  const memberAId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const memberA = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberAId,
        created_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      },
    },
  );
  typia.assert(memberA);

  // 2. Register memberB (forbidden actor)
  const memberBId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const memberB = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberBId,
        created_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      },
    },
  );
  typia.assert(memberB);

  // 3. Create a thread as memberA
  const categoryId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_member_id: memberAId,
        discussionboard_category_id: categoryId,
        title: "Test forbidden reaction delete",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
        updated_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      },
    },
  );
  typia.assert(thread);

  // 4. Create a post in the thread as memberA
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        body: "post for forbidden reaction test",
        is_edited: false,
      },
    },
  );
  typia.assert(post);

  // 5. Create a reaction for the post as memberA
  const reaction = await api.functional.prefix.member.postReactions.create(
    connection,
    {
      body: {
        discussionboard_post_id: post.id,
        discussionboard_member_id: memberAId,
        reaction_type: "heart",
      },
    },
