  // 6. Simulate acting as memberB (swap memberId in headers)
  connection.headers = {
    ...(connection.headers ?? {}),
    "x-discussionboard-member-id": memberBId,
  };

  // 7. Attempt to delete the reaction as memberB
  await TestValidator.error("forbidden deletion by non-owner")(async () => {
    await api.functional.prefix.member.my.postReactions.erase(connection, {
      id: reaction.id,
    });
  });
}

