import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostLike";
import type { IPageIDiscussionboardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardPostLike";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validates that the post likes list can be retrieved with proper filtering and
 * pagination.
 *
 * - Ensures setup of threads and posts, and establishes test data where distinct
 *   posts receive likes from possibly different members
 * - Assert that retrieval with various filters returns only the expected likes
 * - Also test pagination (limit, offset) as available fields
 *
 * Steps:
 *
 * 1. Create a thread to host posts
 * 2. Create multiple posts in that thread (at least 2)
 * 3. Create post likes for those posts (multiple likes, using available member
 *    information)
 * 4. Call postLikes index (list) endpoint with filters: a. Filter by post ID:
 *    Results must only include likes for that post b. Filter by member ID:
 *    Results must only include likes by that member c. No filter: Results must
 *    include all likes d. Pagination: if present in response, ensure pagination
 *    is a valid object e. Combination of filters (post ID + member ID)
 * 5. Assert the returned data matches criteria in each query
 */
export async function test_api_postLikes_test_list_post_likes_with_valid_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a thread
  const now = new Date().toISOString();
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: `Test thread - ${now}`,
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: now,
        updated_at: now,
      },
    },
  );
  typia.assert(thread);

  // 2. Create multiple posts in this thread
  const post1 = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        body: "This is the first post.",
      },
    },
  );
  typia.assert(post1);
  const post2 = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        body: "This is the second post.",
      },
    },
  );
  typia.assert(post2);

  // 3. Like the posts (with the current member identity)
  const like1 = await api.functional.prefix.member.postLikes.create(
    connection,
    {
      body: {
        discussionboard_post_id: post1.id,
        discussionboard_member_id: post1.discussionboard_member_id,
      },
    },
  );
  typia.assert(like1);
  const like2 = await api.functional.prefix.member.postLikes.create(
    connection,
    {
      body: {
        discussionboard_post_id: post2.id,
        discussionboard_member_id: post2.discussionboard_member_id,
      },
    },
  );
  typia.assert(like2);

  // 4a. Filter by post ID
  const resByPost = await api.functional.prefix.member.postLikes.index(
    connection,
    {
      body: {
        discussionboard_post_id: post1.id,
      },
    },
  );
  typia.assert(resByPost);
  TestValidator.predicate(
    "likes filtered by post ID only include likes for that post",
  )(resByPost.data.every((like) => like.discussionboard_post_id === post1.id));

  // 4b. Filter by member ID
  const resByMember = await api.functional.prefix.member.postLikes.index(
    connection,
    {
      body: {
        discussionboard_member_id: post1.discussionboard_member_id,
      },
    },
  );
  typia.assert(resByMember);
  TestValidator.predicate(
    "likes filtered by member ID only include likes by that member",
  )(
    resByMember.data.every(
      (like) =>
        like.discussionboard_member_id === post1.discussionboard_member_id,
    ),
  );

  // 4c. No filter (should include both likes)
  const resAll = await api.functional.prefix.member.postLikes.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(resAll);
  TestValidator.predicate("likes without filter include all test likes")(
    [like1.id, like2.id].every((id) =>
      resAll.data.some((like) => like.id === id),
    ),
  );

  // 4d. Pagination info
  const resPaginate = await api.functional.prefix.member.postLikes.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(resPaginate);
  TestValidator.predicate(
    "pagination info must be present for postLikes index",
  )(typeof resPaginate.pagination === "object");

  // 4e. Combination filter (post ID + member ID)
  const resCombo = await api.functional.prefix.member.postLikes.index(
    connection,
    {
      body: {
        discussionboard_post_id: post2.id,
        discussionboard_member_id: post2.discussionboard_member_id,
      },
    },
  );
  typia.assert(resCombo);
  TestValidator.predicate(
    "likes filter by post and member id returns only the like for that post and member",
  )(
    resCombo.data.length === 1 &&
      resCombo.data[0].discussionboard_post_id === post2.id &&
      resCombo.data[0].discussionboard_member_id ===
        post2.discussionboard_member_id,
  );
}

