import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { IModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationAction";

/**
 * Validate that attempting to update a moderation action with forbidden
 * (non-schema) fields is rejected, and that no data corruption occurs.
 *
 * Scenario:
 *
 * - First, assign the current session a moderator role (prerequisite for owning
 *   moderation actions).
 * - Then, create a valid moderation action using only allowed schema fields (as
 *   preparation for the update).
 * - Try updating this moderation action using the update endpoint, but with extra
 *   forbidden fields (such as a made-up property, or an attempt to change the
 *   id).
 *
 * Test Steps:
 *
 * 1. Assign moderator role (so this session can own moderation actions).
 * 2. Create and store a moderation action (using only allowed schema fields so
 *    it's valid).
 * 3. Attempt to update this moderation action, but deliberately add
 *    forbidden/non-schema fields (e.g., a fake property not in
 *    IModerationAction.IUpdate, or a top-level 'id' property to try changing
 *    id).
 * 4. Assert that the update is rejected with a schema validation error, and no
 *    data or id change occurred.
 * 5. Optionally, ensure the moderation action remains unchanged (e.g., by
 *    attempting to retrieve it if a relevant retrieve endpoint exists; omit if
 *    not possible).
 *
 * Edge Cases:
 *
 * - Trying to update immutable fields (such as id, moderator_id) must be rejected
 *   as well.
 * - Test with both obviously invalid (nonsense) fields and attempts to change
 *   protected/immutable ones.
 * - Prerequisite endpoints: POST /prefix/admin//actors/moderators (assign
 *   moderator), POST /prefix/moderator//moderationActions (create moderation
 *   action).
 * - Test endpoint: PUT /prefix/moderator//my/moderationActions/{id}
 *   (IModerationAction.IUpdate only fields allowed!)
 */
export async function test_api_prefix_moderator_my_moderationActions_test_update_own_moderation_action_with_forbidden_fields(
  connection: api.IConnection,
) {
  // 1. Assign moderator role
  const moderatorId = typia.random<string & tags.Format<"uuid">>();
  const created_at = new Date().toISOString();
  const moderator = await api.functional.prefix.admin.actors.moderators.create(
    connection,
    { body: { id: moderatorId, created_at } },
  );
  typia.assert(moderator);

  // 2. Create a valid moderation action
  const moderationAction =
    await api.functional.prefix.moderator.moderationActions.create(connection, {
      body: {
        moderator_id: moderatorId,
        action_type: "warned",
        action_description:
          "Initial moderation action for forbidden field test.",
        action_timestamp: new Date().toISOString(),
      },
    });
  typia.assert(moderationAction);

  // 3. Attempt to update this action with forbidden fields (e.g., trying to set 'id' directly, or adding a junk field)
  // Only IModerationAction.IUpdate shape is allowed.
  const invalidUpdateBody = {
    action_type: "warned",
    action_description: "This update should fail due to forbidden fields.",
    action_timestamp: new Date().toISOString(),
    id: typia.random<string & tags.Format<"uuid">>(), // forbidden
    junk_field: "disallowed value", // forbidden
    moderator_id: typia.random<string & tags.Format<"uuid">>(), // forbidden
  } as any;

  await TestValidator.error("Update with forbidden fields is rejected")(
    async () => {
      await api.functional.prefix.moderator.my.moderationActions.update(
        connection,
        {
          id: moderationAction.id,
          body: invalidUpdateBody, // deliberately send forbidden fields
        },
      );
    },
  );

  // 4. Optionally: Could try to re-fetch action to prove it remained unchanged (no safe 'get' endpoint provided, so skip).
}

