import type { IModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationAction";

/**
 * Verify that updating a moderation action not owned by the authenticated
 * moderator is rejected (permission enforcement).
 *
 * Business context: Moderation actions are restricted entities and must only be
 * mutable by the moderator (actor) who originally created them. Other
 * moderators must not be able to update these records, even though they possess
 * similar privileges. This test ensures strict data privacy and actor-based
 * permissions are enforced at the moderation action level.
 *
 * Workflow:
 *
 * 1. As an admin, assign two members as moderators (mod1 and mod2), each with a
 *    distinct id.
 * 2. As mod1, create a new moderation action (recording its id and mod1's
 *    moderator_id).
 * 3. As mod2, attempt to update the moderation action created by mod1 by calling
 *    the update endpoint with mod2's authentication context.
 * 4. The update request should be rejected (forbidden or not-authorized), and must
 *    not succeed. The test passes if access is correctly denied.
 */
export async function test_api_moderationActions_test_update_non_owned_moderation_action_rejected(
  connection: api.IConnection,
) {
  // 1. As admin, assign two moderators
  const mod1Id: string = typia.random<string & tags.Format<"uuid">>();
  const mod2Id: string = typia.random<string & tags.Format<"uuid">>();
  const mod1Assignment =
    await api.functional.prefix.admin.actors.moderators.create(connection, {
      body: {
        id: mod1Id,
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardModerator.ICreate,
    });
  typia.assert(mod1Assignment);

  const mod2Assignment =
    await api.functional.prefix.admin.actors.moderators.create(connection, {
      body: {
        id: mod2Id,
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardModerator.ICreate,
    });
  typia.assert(mod2Assignment);

  // 2. As moderator 1, create a moderation action
  // (Assume switching context to mod1 here; framework will manage connection token appropriately)
  // simulate login as mod1
  // (Implement context switch if API supports, skip actual login if none provided)
  const modAction =
    await api.functional.prefix.moderator.moderationActions.create(connection, {
      body: {
        moderator_id: mod1Id,
        report_id: null,
        affected_post_id: null,
        affected_member_id: null,
        action_type: "warned",
        action_description: "Test action by mod1.",
        action_timestamp: new Date().toISOString(),
      } satisfies IModerationAction.ICreate,
    });
  typia.assert(modAction);

  // 3. As moderator 2, attempt to update mod1's moderation action
  // (Again, simulate context switch to mod2)
  await TestValidator.error(
    "should forbid updating non-owned moderation action",
  )(async () => {
    await api.functional.prefix.moderator.my.moderationActions.update(
      connection,
      {
        id: modAction.id,
        body: {
          action_type: "deleted_post",
          action_description: "Malicious update attempt by mod2.",
          action_timestamp: new Date().toISOString(),
        } satisfies IModerationAction.IUpdate,
      },
    );
  });
}

