 *    different user.
 * 2. Using adminA, create a moderation action. Capture the created action's id and
 *    associate it with adminA's id.
 * 3. Simulate acting as adminB (switch context to adminB by supplying a different
 *    admin id when updating).
 * 4. Attempt to update the moderation action created in step 2 using adminB's
 *    context (i.e., not the owner).
 * 5. Confirm that the API returns a forbidden or unauthorized error. Use
 *    TestValidator.error().
 *
 * Preconditions:
 *
 * - Assumes admin creation through direct admin assignment (no user join/login
 *   APIs are exposed)
 * - AdminA and adminB must have unique ids (UUIDs)
 * - Update attempts a realistic change to an editable field (description,
 *   timestamp, etc)
 *
 * This test does not handle cases where the moderation action is created by a
 * moderator who is not an admin, as only admin assignment APIs are available
 * here.
 */
export async function test_api_prefix_admin_my_moderationActions_test_admin_update_non_owned_moderation_action_fails(
  connection: api.IConnection,
) {
