  const adminB = await api.functional.prefix.admin.actors.admins.create(
    connection,
    {
      body: {
        id: adminBId,
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardAdmin.ICreate,
    },
  );
  typia.assert(adminB);

  // 3. Using adminA, create a moderation action owned by adminA
  // (Role context is simulated by setting moderator_id; authentication switching is not in API)
  const moderationAction =
    await api.functional.prefix.admin.moderationActions.create(connection, {
      body: {
        moderator_id: adminAId,
        report_id: null,
        affected_post_id: null,
        affected_member_id: null,
        action_type: "warned",
        action_description: "Initial warning issued.",
        action_timestamp: new Date().toISOString(),
      } satisfies IModerationAction.ICreate,
    });
