import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { IModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationAction";

/**
 * 모더레이터의 자신의 moderation action을 정상적으로 하드 삭제할 수 있는지 검증하는 E2E 테스트입니다.
 *
 * [비즈니스 목적 및 맥락]
 *
 * - 이 테스트는 모더레이터가 본인이 수행한 moderation action(예: 경고, 삭제, 스레드 잠금 등)을 성공적으로 완전 삭제(하드
 *   삭제)할 수 있음을 검증합니다.
 * - 하드 삭제란 DB에서 moderation action 레코드가 완전히 제거되어 복구 불가함을 의미합니다.
 * - 삭제 시나리오는 반드시 본인 action만 대상으로 하며, delete 이후 동일 id 기준 action 조회 시 실패/미존재로 확인되어야
 *   합니다(단, 조회 API 부재 시 검증 생략 가능).
 *
 * [테스트 순서]
 *
 * 1. (선행 작업) 관리자로 임의 멤버에게 모더레이터 역할 부여
 * 2. (선행 작업) 해당 모더레이터가 moderation action 기록 1건 생성
 * 3. Moderation action id 기준으로 하드 삭제 API 호출
 * 4. (추가 검증) 삭제 후 action 데이터가 사라졌는지 간접 확인(조회 API 제공 시 활용, 없을 경우 생략)
 *
 * [구현주의 사항]
 *
 * - Id, created_at 등은 uuid/date-time 규격으로 랜덤 정상값을 부여합니다.
 * - 권한 switching 또는 인증 mock은 제공된 API 내에서만 처리(외부 확장 불가).
 * - Moderation action의 삭제 검증을 위한 조회 API가 없다면, 별도 테스트 케이스 내 error throw 등 직접 확인
 *   불가함을 명시합니다.
 */
export async function test_api_moderationActions_test_delete_own_moderation_action_success(
  connection: api.IConnection,
) {
  // 1. 관리자가 임의 멤버에게 모더레이터 역할을 부여
  const moderatorId: string = typia.random<string & tags.Format<"uuid">>();
  const moderatorAssignment =
    await api.functional.prefix.admin.actors.moderators.create(connection, {
      body: {
        id: moderatorId,
        created_at: new Date().toISOString(),
      },
    });
  typia.assert(moderatorAssignment);

  // 2. 해당 모더레이터로 moderation action을 1개 생성
  const now = new Date().toISOString();
  const moderationAction =
    await api.functional.prefix.moderator.moderationActions.create(connection, {
      body: {
        moderator_id: moderatorId,
        report_id: null,
        affected_post_id: null,
        affected_member_id: null,
        action_type: "warned",
        action_description: "테스트용 moderation action (삭제 대상)",
        action_timestamp: now,
      },
    });
  typia.assert(moderationAction);

  // 3. moderation action id로 하드 삭제 실행
  await api.functional.prefix.moderator.my.moderationActions.erase(connection, {
    id: moderationAction.id,
  });

  // 4. 실제 삭제되었는지 직접 확인하려면 별도 조회 API 필요.
  //    명세상 조회 API가 없는 관계로, 완전 삭제 검증은 생략(비고:
  //    실제 시스템에서 제공 시 error 테스트 활용 권장)
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { IModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationAction";

/**
 * 다른 모더레이터가 생성한 중재 액션을, 본인 계정이 삭제 시도할 때 권한 오류(Forbidden/Not-Authorized)가 발생해야
 * 함을 검증합니다.
 *
 * 이 테스트는 데이터 소유성, 역할 기반 접근제어의 무결성을 보장하는 주요 시나리오입니다.
 *
 * [테스트 진행 절차]
 *
 * 1. 관리자 권한을 이용해 모더레이터 사용자 두 명을 등록합니다.
 * 2. 모더레이터 A(첫 번째 사용자)로 moderation action을 1건 생성합니다.
 * 3. 모더레이터 B(두 번째 사용자)로 moderation action의 삭제를 시도합니다.
 * 4. B가 A가 생성한 moderation action을 삭제하려 할 때 Forbidden/Not-Authorized 오류가 발생하는지
 *    검증합니다. (권한 오류 발생이 성공 조건)
 *
 * 실제 환경에선 계정 간 인증/세션 스위칭 등 별도 절차가 구현되어 있어야 하며, 이 코드는 연결 정보가 역할/계정별로 관리된다고
 * 가정합니다.
 */
export async function test_api_moderationActions_test_delete_non_owned_moderation_action_forbidden(
  connection: api.IConnection,
) {
  // 1. 관리자 권한으로 모더레이터 두 명(A, B) 등록
  const moderatorAId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const created_atA: string & tags.Format<"date-time"> =
    new Date().toISOString();
  const moderatorA = await api.functional.prefix.admin.actors.moderators.create(
    connection,
    {
      body: {
        id: moderatorAId,
        created_at: created_atA,
      } satisfies IDiscussionboardModerator.ICreate,
    },
  );
  typia.assert(moderatorA);

  const moderatorBId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const created_atB: string & tags.Format<"date-time"> =
    new Date().toISOString();
  const moderatorB = await api.functional.prefix.admin.actors.moderators.create(
    connection,
    {
      body: {
        id: moderatorBId,
        created_at: created_atB,
      } satisfies IDiscussionboardModerator.ICreate,
    },
  );
  typia.assert(moderatorB);

  // 2. 모더레이터 A로 moderation action 1건 생성 (moderator_id = moderatorAId)
  const moderationAction =
    await api.functional.prefix.moderator.moderationActions.create(connection, {
      body: {
        moderator_id: moderatorAId,
        report_id: null,
        affected_post_id: null,
        affected_member_id: null,
        action_type: "warned",
        action_description: "A created moderation action (ownership test)",
        action_timestamp: new Date().toISOString(),
      } satisfies IModerationAction.ICreate,
    });
  typia.assert(moderationAction);

  // 3. 모더레이터 B로 moderationAction 정상 삭제 시도(데이터 소유자 아님)
  //    → 권한오류(Forbidden/Not-Authorized) 발생해야 성공
  await TestValidator.error(
    "타인이 생성한 moderation action 삭제는 금지되어야 함",
  )(async () => {
    await api.functional.prefix.moderator.my.moderationActions.erase(
      connection,
      {
        id: moderationAction.id,
      },
    );
  });
}

