files.test/features/api/prefix/test_list_warni:
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { IWarningLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IWarningLog";
import type { IPageIWarningLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIWarningLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate the paginated and filtered retrieval of moderator-issued warning
 * logs.
 *
 * This test ensures that the warning log list endpoint returns only records
 * matching various filters and implements pagination correctly. Steps:
 *
 * 1. Assign moderator roles to two mock users (moderatorA, moderatorB)
 * 2. Create several warning log entries: some by each moderator, with diverse
 *    member/reason/timestamp fields
 * 3. Query the warning log list endpoint using: a. moderator_id (filter) b.
 *    warned_member_id (filter) c. warning_reason substring (partial search) d.
 *    issued_at range e. page/limit f. compound filter (moderator_id +
 *    substring)
 * 4. For each filter, validate results and pagination
 * 5. Query with a filter guaranteed to yield zero results and confirm
 */
export async function test_api_prefix_test_list_warning_logs_with_filter_and_pagination(
  connection: api.IConnection,
) {
  // 1. Assign moderator roles to two users (moderatorA, moderatorB)
  const moderatorAId = typia.random<string & tags.Format<"uuid">>();
  const moderatorBId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();

  const moderatorA = await api.functional.prefix.admin.actors.moderators.create(
    connection,
    {
      body: {
        id: moderatorAId,
        created_at: new Date(now.getTime() - 1000 * 60 * 60 * 10).toISOString(),
      },
    },
  );
  typia.assert(moderatorA);

  const moderatorB = await api.functional.prefix.admin.actors.moderators.create(
    connection,
    {
      body: {
        id: moderatorBId,
        created_at: new Date(now.getTime() - 1000 * 60 * 60 * 8).toISOString(),
      },
    },
  );
  typia.assert(moderatorB);

  // 2. Create warning logs with variation: issued by A/B, for random members, with distinctive reasons & timestamps
  const warnedMembers = ArrayUtil.repeat(3)(() =>
    typia.random<string & tags.Format<"uuid">>(),
  );
  const reasons = [
    "Off-topic",
    "Spamwords",
    "Abuse report",
    "Test search",
    "Other reason",
  ];
  const createdLogs: IWarningLog[] = [];
  for (let i = 0; i < 6; ++i) {
    const mod = i % 2 === 0 ? moderatorAId : moderatorBId;
    const member = warnedMembers[i % warnedMembers.length];
    const reason = reasons[i % reasons.length] + (i === 3 ? " substring" : ""); // make one string easily substring-searchable
    const issued = new Date(now.getTime() - 1000 * 60 * 30 * i).toISOString();
    const log = await api.functional.prefix.moderator.warningLogs.create(
      connection,
      {
        body: {
          moderator_id: mod,
          warned_member_id: member,
          warning_reason: reason,
          issued_at: issued,
        },
      },
    );
    typia.assert(log);
    createdLogs.push(log);
  }

  // 3.a. Filter by moderator_id (should only yield logs by moderatorA)
  const moderatorAResult =
    await api.functional.prefix.moderator.warningLogs.index(connection, {
      body: { moderator_id: moderatorAId },
    });
  typia.assert(moderatorAResult);
  TestValidator.predicate("all logs should have moderator_id === moderatorAId")(
    moderatorAResult.data.every((log) => log.moderator_id === moderatorAId),
  );

  // 3.b. Filter by warned_member_id
  const testWarnedMember = warnedMembers[1];
  const memberResult = await api.functional.prefix.moderator.warningLogs.index(
    connection,
    {
      body: { warned_member_id: testWarnedMember },
    },
  );
  typia.assert(memberResult);
  TestValidator.predicate(
    "all logs should have warned_member_id === testWarnedMember",
  )(
    memberResult.data.every((log) => log.warned_member_id === testWarnedMember),
  );

  // 3.c. Substring filter on warning_reason
  const partial = "sub";
  const substringResult =
    await api.functional.prefix.moderator.warningLogs.index(connection, {
      body: { warning_reason: partial },
    });
  typia.assert(substringResult);
  TestValidator.predicate("all logs should contain substring in reason")(
    substringResult.data.every((log) => log.warning_reason.includes(partial)),
  );

  // 3.d. issued_at_from/issued_at_to (should return logs in that time window)
  const minTime = new Date(now.getTime() - 1000 * 60 * 90).toISOString();
  const maxTime = now.toISOString();
  const timeResult = await api.functional.prefix.moderator.warningLogs.index(
    connection,
    {
      body: { issued_at_from: minTime, issued_at_to: maxTime },
    },
  );
  typia.assert(timeResult);
  TestValidator.predicate("logs in range")(
    timeResult.data.every(
      (log) => log.issued_at >= minTime && log.issued_at <= maxTime,
    ),
  );

  // 3.e. Pagination (limit=2)
  const pageResult = await api.functional.prefix.moderator.warningLogs.index(
    connection,
    {
      body: { page: 1, limit: 2 },
    },
  );
  typia.assert(pageResult);
  TestValidator.equals("pagination limit")(pageResult.pagination.limit)(2);
  TestValidator.equals("page is 1")(pageResult.pagination.current)(1);
  TestValidator.predicate("result <= 2 logs")(pageResult.data.length <= 2);

  // 3.f. Compound filter (moderator_id + partial warning_reason)
  const compoundResult =
    await api.functional.prefix.moderator.warningLogs.index(connection, {
      body: { moderator_id: moderatorAId, warning_reason: "Off" },
    });
  typia.assert(compoundResult);
  TestValidator.predicate("compound filter: all logs match both conditions")(
    compoundResult.data.every(
      (log) =>
        log.moderator_id === moderatorAId && log.warning_reason.includes("Off"),
    ),
  );

  // 4. Edge: filter for reason string that cannot exist
  const noResults = await api.functional.prefix.moderator.warningLogs.index(
    connection,
    {
      body: { warning_reason: "[no such reason string here]" },
    },
  );
  typia.assert(noResults);
  TestValidator.equals("should return no results")(noResults.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { IWarningLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IWarningLog";
import type { IPageIWarningLog } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIWarningLog";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Verify the warning log filtering returns empty results on no matches.
 *
 * This test ensures that when a search is performed on the warning log listing
 * endpoint with filter criteria that do not match any database records (such as
 * a non-existent warned_member_id and a warning_reason string absent in all
 * entries), the API responds correctly with an empty data set (not an error).
 * This is important for user experience, robustness, and API predictability.
 *
 * Step-by-step process:
 *
 * 1. Assign a moderator role using the admin endpoint, simulating giving a
 *    moderator permission to a random member UUID.
 * 2. Create at least one warning log with a "realistic" reason and
 *    warned_member_id so the table is non-empty.
 * 3. Search/list warning logs filtering with a nonsense warned_member_id and a
 *    unique warning_reason string not present in any entry.
 *
