import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPlatformPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPlatformPolicy";

/**
 * Test that an administrator can successfully hard-delete a platform policy by
 * its ID and that the resource is truly removed.
 *
 * This test covers the following business workflow:
 *
 * 1. Create a new platform policy document (as an admin)
 * 2. Fetch the created policy to confirm its existence
 * 3. Hard-delete the policy by its id (as an admin)
 * 4. Attempt to re-fetch the deleted policy, expecting a not found error
 *
 * Validates that:
 *
 * - Creation of new policy is possible
 * - Policy can be retrieved after creation
 * - Deletion endpoint returns success and erases the record
 * - After deletion, retrieval fails with a 404 error
 */
export async function test_api_prefix_admin_policyAudit_platformPolicies_test_delete_platform_policy_with_valid_id(
  connection: api.IConnection,
) {
  // 1. Create a new platform policy
  const createBody: IDiscussionboardPlatformPolicy.ICreate = {
    policy_code: RandomGenerator.alphaNumeric(8),
    title: RandomGenerator.paragraph()(),
    policy_text: RandomGenerator.content()()(),
    is_active: true,
  };
  const created: IDiscussionboardPlatformPolicy =
    await api.functional.prefix.admin.policyAudit.platformPolicies.create(
      connection,
      { body: createBody },
    );
  typia.assert(created);

  // 2. Confirm the policy exists
  const fetched: IDiscussionboardPlatformPolicy =
    await api.functional.prefix.admin.policyAudit.platformPolicies.at(
      connection,
      { platformPolicyId: created.id },
    );
  typia.assert(fetched);
  TestValidator.equals("policy created and fetched have same ID")(fetched.id)(
    created.id,
  );

  // 3. Delete the platform policy
  await api.functional.prefix.admin.policyAudit.platformPolicies.erase(
    connection,
    { platformPolicyId: created.id },
  );

  // 4. Attempt to fetch the deleted policy (expect error)
  await TestValidator.error(
    "deleted platform policy should not be retrievable",
  )(() =>
    api.functional.prefix.admin.policyAudit.platformPolicies.at(connection, {
      platformPolicyId: created.id,
    }),
  );
}

