/**
 * 정책/컴플라이언스 인시던트 리포트 조회의 엣지케이스(극한필터) 내구성/유효성 테스트
 *
 * 본 테스트는 운영진/모더레이터가 policyAudit incident report API에서 정상/비정상/극단 필터 조합에 대한
 *
 * 1. API 서버의 크래시 없고 정상 동작,
 * 2. 반환값의 스키마 일관성,
 * 3. 페이지네이션/빈 결과/대량 데이터 등 다양한 상황의 내구성
 * 4. 비정상 필터(비존재 status, 과도한 pagesize, 음수 page 등) 일 때 validation 오류 반환 을 집중적으로
 *    검증합니다.
 *
 * 절차
 *
 * 1. 아무 필터 없이 전체 조회 (기본: empty object)
 * 2. Created_from을 극과거(1900-01-01T00:00:00Z)로 조회
 * 3. Created_to에 극미래(2999-12-31T23:59:59Z) 적용 조회
 * 4. 비정상 status 값 (ex: 'INVALID_STATUS') 전달
 * 5. Limit=10000처럼 매우 큰 페이지 크기 요청
 * 6. Page=0, page=-5 등 비정상 page 입력 → validation 오류 확인
 */
export async function test_api_prefix_moderator_policyAudit_incidentReports_test_list_incident_reports_with_edge_case_filters(
  connection: api.IConnection,
) {
  // 1. 기본: 전체 조회(빈 필터)
  const result_basic =
    await api.functional.prefix.moderator.policyAudit.incidentReports.index(
      connection,
      { body: {} },
    );
  typia.assert(result_basic);
  TestValidator.predicate("pagination info valid")(
    result_basic.pagination.current > 0 &&
      result_basic.pagination.limit > 0 &&
      result_basic.pagination.pages >= 0 &&
      result_basic.pagination.records >= 0,
  );
  TestValidator.predicate("data is array")(Array.isArray(result_basic.data));

  // 2. created_from 극과거
  const result_past =
    await api.functional.prefix.moderator.policyAudit.incidentReports.index(
      connection,
      {
        body: {
          created_from: "1900-01-01T00:00:00Z",
        },
      },
    );
  typia.assert(result_past);
  TestValidator.predicate("past query array")(Array.isArray(result_past.data));

  // 3. created_to 극미래
  const result_future =
    await api.functional.prefix.moderator.policyAudit.incidentReports.index(
      connection,
      {
        body: {
          created_to: "2999-12-31T23:59:59Z",
        },
      },
    );
  typia.assert(result_future);
  TestValidator.predicate("future query array")(
    Array.isArray(result_future.data),
  );

  // 4. status에 비정상 값
  const result_invalid_status =
    await api.functional.prefix.moderator.policyAudit.incidentReports.index(
      connection,
      {
        body: {
          status: "INVALID_STATUS",
        },
      },
    );
  typia.assert(result_invalid_status);
  TestValidator.predicate("invalid status handled")(
    Array.isArray(result_invalid_status.data),
  );

  // 5. limit 매우 큼 (대량 rows 요청)
  const result_large_limit =
    await api.functional.prefix.moderator.policyAudit.incidentReports.index(
      connection,
      {
        body: {
          limit: 10000,
        },
      },
    );
  typia.assert(result_large_limit);
  TestValidator.predicate("large limit handled")(
    result_large_limit.data.length >= 0,
  );

  // 6. page: 0 (비정상)
  await TestValidator.error("page 0 must trigger validation")(() =>
    api.functional.prefix.moderator.policyAudit.incidentReports.index(
      connection,
      {
        body: {
          page: 0,
        },
      },
    ),
  );

  // 7. page: 음수
  await TestValidator.error("negative page must trigger validation")(() =>
    api.functional.prefix.moderator.policyAudit.incidentReports.index(
      connection,
      {
        body: {
          page: -5,
        },
      },
    ),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
