/**
 * Test the successful hard deletion of an incident report by an admin.
 *
 * This test verifies the business rule that authorized admin users can
 * permanently remove an incident report record from the system. As there is no
 * soft-delete field, the deletion is completely irreversible and should make
 * the report inaccessible post-operation. The test also implicitly checks for
 * correct permission enforcement on this critical workflow.
 *
 * Steps:
 *
 * 1. Create a new incident report as an admin using the API.
 * 2. Delete the just-created incident report using the admin route (hard delete).
 * 3. Attempt to delete the same incident report again, expecting a 404 error
 *    indicating it is gone.
 *
 * Validations:
 *
 * - Deletion should be successful for valid, existing records with appropriate
 *   admin privilege.
 * - Deleted records must not be retrievable or deletable again (404 on second
 *   attempt).
 */
export async function test_api_prefix_admin_policyAudit_incidentReports_test_delete_incident_report_success_by_admin(
  connection: api.IConnection,
) {
  // 1. Create a new incident report as admin
  const createInput: IDiscussionboardIncidentReport.ICreate = {
    incident_code:
      "INCIDENT-" +
      new Date().toISOString().slice(0, 10).replace(/-/g, "") +
      "-" +
      typia.random<number & tags.Type<"uint32">>(),
    status: "OPEN",
    reporter_id: null,
    description: RandomGenerator.paragraph()(),
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  } satisfies IDiscussionboardIncidentReport.ICreate;
  const incident: IDiscussionboardIncidentReport =
    await api.functional.prefix.admin.policyAudit.incidentReports.create(
