/**
 * Test searching for appeals as a moderator, with criteria that do not match
 * any entries.
 *
 * This test validates that when a moderator performs an advanced search for
 * appeals with filters guaranteed not to match any records (e.g., using a
 * non-existent status, appellant_id, or incident_id), the system should return
 * an empty list and appropriate pagination metadata (page 1, 0 records, 0
 * pages).
 *
 * This ensures that:
 *
 * 1. The search endpoint can correctly handle zero-result cases without error.
 * 2. No unexpected or spurious results are included in an empty query.
 * 3. Pagination info is always provided (even when there are no matches).
 *
 * Steps:
 *
 * 1. As a moderator, send a search query for appeals with a filter value that does
 *    not match anything in the underlying data (e.g., an obviously invalid
 *    status or a new random UUID for appellant_id).
 * 2. Assert that the returned "data" array is empty.
 * 3. Assert that the pagination object exists, and records == 0, pages == 0, and
 *    current == 1 (for first page request).
 */
export async function test_api_prefix_moderator_policyAudit_appeals_index_no_matches(
  connection: api.IConnection,
) {
  // Create a request with random, guaranteed-to-not-match filters (e.g., invalid status and random appellant_id)
  const request: IDiscussionboardAppeal.IRequest = {
    status: "NON_EXISTENT_STATUS", // status that should not match anything
    appellant_id: typia.random<string & tags.Format<"uuid">>(), // random UUID unlikely to match any entry
    incident_id: typia.random<string & tags.Format<"uuid">>(), // random incident id, also unlikely to match
    page: 1,
    limit: 10,
    created_after: null,
    created_before: null,
    sort_by: null,
    sort_direction: null,
  };
  const output =
    await api.functional.prefix.moderator.policyAudit.appeals.index(
      connection,
      { body: request },
    );
  typia.assert(output);

  // Assert "data" is empty
  TestValidator.equals("appeals returned should be empty")(output.data)([]);

  // Assert pagination metadata
  TestValidator.equals("pagination.current page is 1")(
    output.pagination.current,
  )(1);
  TestValidator.equals("pagination.limit matches")(output.pagination.limit)(10);
  TestValidator.equals("pagination.records is 0")(output.pagination.records)(0);
  TestValidator.equals("pagination.pages is 0")(output.pagination.pages)(0);
}

