/**
 * Test that an authenticated member can retrieve a mention record by its unique
 * id, matching what was created.
 *
 * Business context:
 *
 * - Members may be tagged (mentioned) in posts. To notify and track these, a
 *   mention record is created.
 * - The ability to view one's own mention by ID is core for notification detail
 *   and analytics flows.
 *
 * Process:
 *
 * 1. (Setup) Simulate member and post creation (APIs not present; use random
 *    UUIDs)
 * 2. (Setup) Create a mention pointing to this member and post
 * 3. (Action) Retrieve the mention record by id via the API
 * 4. (Assert) All major properties (id, post id, mentioned member id) match
 *    exactly, and the schema is validated
 */
export async function test_api_prefix_member_mentions_test_get_mention_by_id_success(
  connection: api.IConnection,
) {
  // 1. Simulate creation of a member to be mentioned
  const mentioned_member_id = typia.random<string & tags.Format<"uuid">>();
  // 2. Simulate creation of a post
  const discussionboard_post_id = typia.random<string & tags.Format<"uuid">>();

  // 3. Create the mention
  const created = await api.functional.prefix.member.mentions.create(
    connection,
    {
      body: {
        discussionboard_post_id,
        mentioned_member_id,
      } satisfies discussionboard_mentions.ICreate,
    },
  );
  typia.assert(created);

  // 4. Fetch the mention by id
  const fetched = await api.functional.prefix.member.mentions.at(connection, {
    id: created.id,
  });
  typia.assert(fetched);

  // 5. Assert field-level correctness
  TestValidator.equals("id matches")(fetched.id)(created.id);
  TestValidator.equals("discussionboard_post_id matches")(
    fetched.discussionboard_post_id,
  )(discussionboard_post_id);
  TestValidator.equals("mentioned_member_id matches")(
    fetched.mentioned_member_id,
  )(mentioned_member_id);
  // (created_at presence and format is schema-validated via typia.assert)
}

