import api from "@ORGANIZATION/PROJECT-api";
import type { discussionboard_mentions } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboard_mentions";

/**
 * Test the successful update of a mention entry by its owner.
 *
 * This test verifies that once an authenticated member has a valid mention
 * record, they can update it to refer to another valid discussion post, or to
 * another member, or both. The workflow reflects a scenario where tagged
 * notifications or references may require post-publication adjustment (e.g.
 * moderation, user correction, or system-initiated moves).
 *
 * Steps:
 *
 * 1. Register member1 (the actor) and member2 (another member who can be
 *    mentioned)
 * 2. Create two discussionboard posts (postA, postB)
 * 3. Authenticate as member1 and create a mention for member2 in postA
 * 4. Update the mention: change the referenced post to postB, keeping member2
 * 5. Update the mention: change the mentioned_member_id to member1 (i.e.
 *    self-mention), keeping the post as postB
 * 6. Validate that updates succeed and returned mention object is correct
 *
 * Schema validation is performed after each update to ensure type correctness
 * and data integrity.
 */
export async function test_api_prefix_member_my_mentions_test_update_mention_success(
  connection: api.IConnection,
) {
  // 1. Register member1 and member2 (simulated IDs as actual member creation API is unavailable)
  const member1_id = typia.random<string & tags.Format<"uuid">>();
  const member2_id = typia.random<string & tags.Format<"uuid">>();

  // 2. Create two posts (simulated IDs for existing posts)
  const postA_id = typia.random<string & tags.Format<"uuid">>();
  const postB_id = typia.random<string & tags.Format<"uuid">>();

  // 3. Create initial mention as member1 (mentioning member2 in postA)
  const mention = await api.functional.prefix.member.mentions.create(
    connection,
    {
      body: {
        discussionboard_post_id: postA_id,
        mentioned_member_id: member2_id,
      } satisfies discussionboard_mentions.ICreate,
    },
  );
  typia.assert(mention);

  // 4. Update the mention: change referenced post to postB (still mentioning member2)
  const updatedMention1 = await api.functional.prefix.member.my.mentions.update(
    connection,
    {
      id: mention.id,
      body: {
        discussionboard_post_id: postB_id,
      } satisfies discussionboard_mentions.IUpdate,
    },
  );
  typia.assert(updatedMention1);
  TestValidator.equals("mention post id updated")(
    updatedMention1.discussionboard_post_id,
  )(postB_id);
  TestValidator.equals("mentioned_member_id remains")(
    updatedMention1.mentioned_member_id,
  )(member2_id);

  // 5. Update the mention: change to mention member1 themselves (self-mention), keep post as B
  const updatedMention2 = await api.functional.prefix.member.my.mentions.update(
    connection,
    {
      id: mention.id,
      body: {
        mentioned_member_id: member1_id,
      } satisfies discussionboard_mentions.IUpdate,
    },
  );
  typia.assert(updatedMention2);
  TestValidator.equals("mention post remains")(
    updatedMention2.discussionboard_post_id,
  )(postB_id);
  TestValidator.equals("mentioned_member_id updated")(
    updatedMention2.mentioned_member_id,
  )(member1_id);
}

