  TestValidator.equals(`[page=1][meta:limit]`)(resPag1.pagination.limit)(limit);
  resPag1.data.forEach((n, idx) => {
    TestValidator.equals(`[page=1][ownership][notification #${idx}]`)(
      n.discussionboard_member_id,
