import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPlatformPolicy } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPlatformPolicy";

/**
 * Validate successful creation of a discussion board platform policy (admin).
 *
 * This E2E test verifies that an admin can create a new platform policy
 * document by providing all required fields, and that the resulting created
 * record is schema-complete and audit-compliant.
 *
 * Steps validated:
 *
 * 1. Prepare valid, unique platform policy input (policy_code, title, policy_text,
 *    is_active).
 * 2. Call the POST /prefix/admin//policyAudit/platformPolicies API to create the
 *    new policy.
 * 3. Check the response for:
 *
 *    - All schema fields present
 *    - Policy_code, title, policy_text, is_active match the input
 *    - Id is a valid UUID
 *    - Published_at and updated_at are ISO 8601 date-time strings managed by the
 *         server
 * 4. Negative/error test not included, as business validation errors (e.g.,
 *    duplicate code) require prior record knowledge.
 */
export async function test_api_policyAudit_test_create_platform_policy_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Prepare valid, unique policy input
  const uniqueCode = `TEST_POLICY_${Date.now()}_${Math.floor(Math.random() * 10000)}`;
  const input: IDiscussionboardPlatformPolicy.ICreate = {
    policy_code: uniqueCode,
    title: "Test Platform Policy E2E",
    policy_text:
      "This is the body of a test policy for E2E verification. Legal and audit term text goes here.",
    is_active: true,
  };

  // 2. Call the API to create a new policy
  const created =
    await api.functional.prefix.admin.policyAudit.platformPolicies.create(
      connection,
      { body: input },
    );
  typia.assert(created);

  // 3. Field and format validation
  TestValidator.equals("policy_code matches")(created.policy_code)(uniqueCode);
  TestValidator.equals("title matches")(created.title)(input.title);
  TestValidator.equals("policy_text matches")(created.policy_text)(
    input.policy_text,
  );
  TestValidator.equals("is_active matches")(created.is_active)(input.is_active);
  // id is a UUID (RFC 4122 basic check)
  if (!/^[0-9a-fA-F-]{36}$/.test(created.id)) {
    throw new Error(`id not valid UUID: ${created.id}`);
  }
  // published_at and updated_at are ISO 8601 date-time
  if (isNaN(Date.parse(created.published_at))) {
    throw new Error(`published_at not ISO 8601: ${created.published_at}`);
  }
  if (isNaN(Date.parse(created.updated_at))) {
    throw new Error(`updated_at not ISO 8601: ${created.updated_at}`);
  }
}

