 * ensures the API denies creation of a duplicate `policy_code` and responds
 * appropriately.
 *
 * Workflow:
 *
 * 1. Successfully create a platform policy with a unique `policy_code`.
 * 2. Attempt to create a second platform policy with the EXACT same `policy_code`
 *    but a different title and content. This serves as the duplicate case.
 * 3. Expect the system to throw a conflict or validation error (runtime, not
 *    TypeScript). Assert that the error occurs for duplicate policy code.
 * 4. (Edge case) Optionally, create a third policy with a different `policy_code`
 *    to ensure the API still works for unique codes (confirm we didn't lock out
 *    the endpoint after error).
 */
export async function test_api_platformPolicies_test_fail_to_create_duplicate_policy_code(
  connection: api.IConnection,
) {
  // 1. Create the initial platform policy
  const policy_code = RandomGenerator.alphaNumeric(10);
  const firstPolicy =
    await api.functional.prefix.admin.policyAudit.platformPolicies.create(
      connection,
      {
        body: {
          policy_code,
          title: "Platform Policy One",
          policy_text: RandomGenerator.paragraph()(),
          is_active: true,
