    api.functional.prefix.admin.policyAudit.platformPolicies.create(
      connection,
      {
        body: {
          policy_code,
          title: "Platform Policy Duplicate",
          policy_text: RandomGenerator.paragraph()(),
          is_active: false,
        } satisfies IDiscussionboardPlatformPolicy.ICreate,
      },
