import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { discussionboard_notifications } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboard_notifications";

/**
 * Test error handling for deleting notifications not owned by the authenticated
 * user or with a non-existent notificationId.
 *
 * This test covers negative scenarios for soft-deletion of discussion board
 * notifications:
 *
 * 1. A member (User A) creates a notification via the normal flow.
 * 2. Another member (User B) attempts to delete the notification created by User
 *    A. Expectation: forbidden error.
 * 3. User A attempts to delete a notification that does not exist. Expectation:
 *    not found error.
 *
 * Steps:
 *
 * 1. Register two members (User A and User B) with distinct UUIDs and timestamps.
 * 2. (Assume) Authenticate as User A, create a notification as User A.
 * 3. (Assume) Switch context to User B. Attempt to delete User A's notification as
 *    User B (should error: forbidden).
 * 4. (Assume) Switch back to User A. Attempt to delete a random notificationId
 *    (should error: not found).
 *
 * Note: Authentication context-switching must be handled by the test infra or
 * outer helper (not covered here).
 */
export async function test_api_discussionboardnotifications_test_soft_delete_notification_not_owned_or_nonexistent(
  connectionA: api.IConnection,
  connectionB: api.IConnection,
) {
  // 1. Register User A
  const userAId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const userA: IDiscussionboardMembers =
    await api.functional.prefix.member.actors.members.create(connectionA, {
      body: {
        id: userAId,
        created_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      },
    });
  typia.assert(userA);

  // 2. Register User B
  const userBId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const userB: IDiscussionboardMembers =
    await api.functional.prefix.member.actors.members.create(connectionB, {
      body: {
        id: userBId,
        created_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      },
    });
  typia.assert(userB);

  // 3. Create a notification for User A (must be authenticated as User A)
  const notification: discussionboard_notifications =
    await api.functional.prefix.member.my.discussionboardNotifications.create(
      connectionA,
      {
        body: {
          type: "mention",
          title: "Ownership Test Notification",
          body: "Notification for negative test.",
          url: "/thread/ownership-test",
          opened: false,
        } satisfies discussionboard_notifications.ICreate,
      },
    );
  typia.assert(notification);

  // 4. Attempt to delete User A's notification as User B (should fail: forbidden)
  TestValidator.error(
    "forbidden: cannot delete notification owned by another user",
  )(async () => {
    await api.functional.prefix.member.my.discussionboardNotifications.erase(
      connectionB,
      { notificationId: notification.id },
    );
  });

  // 5. Attempt to delete a non-existent notification as User A (should fail: not found)
  const fakeNotificationId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  TestValidator.error("not found: cannot delete a non-existent notification")(
    async () => {
      await api.functional.prefix.member.my.discussionboardNotifications.erase(
        connectionA,
        { notificationId: fakeNotificationId },
      );
    },
  );
}

