import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { discussionboard_alerts } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboard_alerts";
import type { IPageDiscussionboardAlerts } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageDiscussionboardAlerts";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate filtered and paginated alert listing for a member.
 *
 * This test ensures that an authenticated member can retrieve alerts from the
 * system, with robust support for filtering on type, severity, is_active, and
 * for pagination (limit/offset). Steps:
 *
 * 1. Register a new member using the members creation endpoint.
 * 2. Create several alerts for that member, with a spread of types, severities,
 *    and is_active states (e.g.: 2 with type="policy_update", 1 with
 *    type="suspension_warning", mixing critical/warning/info and true/false
 *    is_active).
 * 3. Invoke the alerts listing endpoint (PATCH) with NO filters, check that ALL
 *    created alerts appear.
 * 4. Filter on type (e.g., type="policy_update"), check only those records appear.
 * 5. Filter on severity (e.g., severity="critical") and is_active=true, check only
 *    matching alerts appear.
 * 6. Test pagination: limit=2, offset=0 returns only first 2, limit=2, offset=2
 *    returns next 2, etc.
 * 7. Ensure all listed alert objects match schema and filter criteria, and
 *    pagination info is accurate.
 * 8. Additionally, test an edge case where filters yield zero results.
 */
export async function test_api_prefix_member_my_discussionboardAlerts_test_list_alerts_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Register a member (using a unique id for test isolation)
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const createdAt = new Date().toISOString() as string &
    tags.Format<"date-time">;
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId,
        created_at: createdAt,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create multiple alerts for the member with varying combinations
  const alertInputs: discussionboard_alerts.ICreate[] = [
    {
      type: "policy_update",
      severity: "info",
      title: "Policy Updated",
      body: "We have updated our policy.",
      is_active: true,
    },
    {
      type: "policy_update",
      severity: "critical",
      title: "Critical Policy Update",
      body: "Urgent: Policy changes require action.",
      is_active: true,
    },
    {
      type: "suspension_warning",
      severity: "warning",
      title: "Suspension Warning",
      body: "Warning: Your account is at risk.",
      is_active: true,
    },
    {
      type: "important_announcement",
      severity: "info",
      title: "Announcement",
      body: "General announcement for all members.",
      is_active: false,
    },
    {
      type: "policy_update",
      severity: "info",
      title: "Old Policy Update",
      body: "This is an outdated policy update.",
      is_active: false,
    },
  ];

  const createdAlerts: discussionboard_alerts[] = [];
  for (const input of alertInputs) {
    const alert =
      await api.functional.prefix.member.my.discussionboardAlerts.create(
        connection,
        { body: input },
      );
    typia.assert(alert);
    createdAlerts.push(alert);
  }

  // 3. List all alerts for the member (no filters)
  const resAll =
    await api.functional.prefix.member.my.discussionboardAlerts.index(
      connection,
      { body: {} },
    );
  typia.assert(resAll);
  TestValidator.equals("all alerts count")(resAll.data.length)(
    createdAlerts.length,
  );
  TestValidator.equals("pagination records matches")(resAll.pagination.records)(
    createdAlerts.length,
  );

  // 4. Filter by type: 'policy_update'
  const resType =
    await api.functional.prefix.member.my.discussionboardAlerts.index(
      connection,
      { body: { type: "policy_update" } },
    );
  typia.assert(resType);
  const expectedTypeCount = createdAlerts.filter(
    (a) => a.type === "policy_update",
  ).length;
  TestValidator.equals("policy_update count")(resType.data.length)(
    expectedTypeCount,
  );
  TestValidator.predicate("type filter")(
    resType.data.every((a) => a.type === "policy_update"),
  );

  // 5. Filter by severity and is_active
  const resSevAct =
    await api.functional.prefix.member.my.discussionboardAlerts.index(
      connection,
      { body: { severity: "critical", is_active: true } },
    );
  typia.assert(resSevAct);
  const expectedSevActCount = createdAlerts.filter(
    (a) => a.severity === "critical" && a.is_active === true,
  ).length;
  TestValidator.equals("critical & active count")(resSevAct.data.length)(
    expectedSevActCount,
  );
  TestValidator.predicate("severity critical, active true")(
    resSevAct.data.every(
      (a) => a.severity === "critical" && a.is_active === true,
    ),
  );

  // 6. Pagination: limit=2, offset=0 (should return first 2 results)
  const limit = 2;
  const offset = 0;
  const resPage1 =
    await api.functional.prefix.member.my.discussionboardAlerts.index(
      connection,
      { body: { limit, offset, sort: "created_at_asc" } },
    );
  typia.assert(resPage1);
  TestValidator.equals("page1 count")(resPage1.data.length)(
    Math.min(limit, createdAlerts.length),
  );
  TestValidator.equals("page1 current page")(resPage1.pagination.current)(1); // pages start at 1
  TestValidator.equals("page1 limit")(resPage1.pagination.limit)(limit);

  // 7. Pagination: limit=2, offset=2 (should return next 2 results)
  const resPage2 =
    await api.functional.prefix.member.my.discussionboardAlerts.index(
      connection,
      { body: { limit, offset: 2, sort: "created_at_asc" } },
    );
  typia.assert(resPage2);
  TestValidator.equals("page2 count")(resPage2.data.length)(
    createdAlerts.length > 2 ? Math.min(limit, createdAlerts.length - 2) : 0,
  );
  TestValidator.equals("page2 current page")(resPage2.pagination.current)(2);

  // 8. Each listed alert matches filter criteria and schema
  for (const alert of resType.data) {
    typia.assert(alert);
    TestValidator.equals("type filter is correct")(alert.type)("policy_update");
  }
  for (const alert of resSevAct.data) {
    typia.assert(alert);
    TestValidator.equals("severity filter is correct")(alert.severity)(
      "critical",
    );
    TestValidator.equals("is_active filter is correct")(alert.is_active)(true);
  }

  // 9. Edge case: filtering with impossible condition yields zero results
  const resNone =
    await api.functional.prefix.member.my.discussionboardAlerts.index(
      connection,
      { body: { type: "no_such_type" } },
    );
  typia.assert(resNone);
  TestValidator.equals("zero results for non-existent type")(
    resNone.data.length,
  )(0);
  TestValidator.predicate("empty result data")(
    Array.isArray(resNone.data) && resNone.data.length === 0,
  );
}

