/**
 * Validate schema strictness for admin warning log update endpoint.
 *
 * This test ensures the update API for /prefix/admin//my/warningLogs/:id
 * strictly rejects requests where:
 *
 * - The request body includes extra/non-schema fields (no pollution allowed)
 * - A schema-valid field uses an invalid type (should fail)
 * - Schema-valid field value breaks format (bad date-time string)
 *
 * This is critical to preserve integrity of warning log records and enforce
 * strict validation on the admin-facing endpoint.
 *
 * Steps:
 *
 * 1. Admin creates a valid warning log to have a real id.
 * 2. Attempt an update with a request body including an extra property not in
 *    IWarningLog.IUpdate (violating schema).
 * 3. Attempt an update with a field present in schema but with the wrong type
 *    (number instead of string).
 * 4. Attempt an update with a field present but the wrong date-time format (should
 *    be ISO 8601 string).
 * 5. Issue a valid update with the original data to show the warning log is
 *    unchanged -- confirm immutability when invalid updates fail.
 */
export async function test_api_prefix_admin_my_warningLogs_test_admin_update_warning_log_with_bad_data_fails(
  connection: api.IConnection,
) {
  // 1. Create a valid warning log as base test subject
  const validLog = await api.functional.prefix.admin.warningLogs.create(
    connection,
    {
      body: {
        moderator_id: typia.random<string & tags.Format<"uuid">>(),
        warned_member_id: typia.random<string & tags.Format<"uuid">>(),
        warning_reason: "Test reason",
        issued_at: new Date().toISOString(),
      } satisfies IWarningLog.ICreate,
    },
  );
  typia.assert(validLog);

  // 2. Should be rejected: attempt to update with extra/prohibited field using `as any` to simulate a non-schema property.
  await TestValidator.error("should reject body with non-schema/extra fields")(
    async () => {
      await (api.functional.prefix.admin.my.warningLogs.update as any)(
        connection,
        {
          id: validLog.id,
          body: {
            warning_reason: "New reason",
            issued_at: new Date().toISOString(),
            illegal_field: "not allowed", // non-schema property
          },
        },
      );
    },
  );

  // 3. Should be rejected: attempt to update using wrong value type for a schema field
  await TestValidator.error(
    "should reject body with wrong type for warning_reason",
  )(async () => {
    await api.functional.prefix.admin.my.warningLogs.update(connection, {
      id: validLog.id,
      body: {
        warning_reason: 12345 as any, // should be string, not number
        issued_at: new Date().toISOString(),
      },
    });
  });

  // 4. Should be rejected: attempt to update with an invalid date-time format
  await TestValidator.error(
    "should reject body with invalid date-time for issued_at",
  )(async () => {
    await api.functional.prefix.admin.my.warningLogs.update(connection, {
      id: validLog.id,
      body: {
        warning_reason: "Still valid reason",
        issued_at: "not-a-date-time" as any, // should be ISO 8601
      },
    });
  });

  // 5. Confirm log was not (meaningfully) changed: valid update with original data
  const after = await api.functional.prefix.admin.my.warningLogs.update(
    connection,
    {
      id: validLog.id,
      body: {
        warning_reason: validLog.warning_reason,
        issued_at: validLog.issued_at,
      } satisfies IWarningLog.IUpdate,
    },
  );
  typia.assert(after);
  TestValidator.equals("warning_reason remains")(after.warning_reason)(
    validLog.warning_reason,
  );
  TestValidator.equals("issued_at remains")(after.issued_at)(
    validLog.issued_at,
  );
}

