/**
 * Test admin appeal creation with valid reference and fields (compliance
 * workflow).
 *
 * This test validates end-to-end creation of an appeal by an admin, ensuring
 * full compliance with the schema and business process. It simulates the
 * correct workflow by first creating an incident report (to serve as the valid
 * incident reference), and then submitting an appeal with all required and
 * optional fields supplied. This test checks that when all schema properties
 * are strictly matched and provided, the API returns an appeal object whose
 * properties match the input.
 *
 * Steps:
 *
 * 1. Create an incident report (serves as target for incident_id reference)
 * 2. Submit an appeal as admin with strictly matching schema fields, including
 *    reference to created incident
 * 3. Assert response fields strictly match input values and are round-trippable
 * 4. Covers referential integrity and schema field validation for appeal creation
 */
export async function test_api_policyAudit_test_create_appeal_with_valid_data_as_admin(
  connection: api.IConnection,
) {
  // 1. Create an incident report to reference
  const now = new Date().toISOString();
  const incidentCode = `INCIDENT-${now.slice(0, 10).replace(/-/g, "")}-001`;
  const incidentInput: IDiscussionboardIncidentReport.ICreate = {
    incident_code: incidentCode,
    status: "OPEN",
    reporter_id: null, // simulate anonymous report; nullable field
    description: "Simulated policy violation for admin appeal workflow test.",
    created_at: now,
    updated_at: now,
  };
  const incident =
    await api.functional.prefix.admin.policyAudit.incidentReports.create(
      connection,
      { body: incidentInput },
    );
  typia.assert(incident);

  // 2. Prepare appeal creation data referencing the incident
  const appealCode = `APPEAL-${now.slice(0, 10).replace(/-/g, "")}-001`;
  const appealInput: IDiscussionboardAppeal.ICreate = {
    appeal_code: appealCode,
    status: "PENDING",
    appellant_id: null, // for this scenario, simulate system/anon case
    incident_id: incident.id, // required reference
    outcome: "Test appeal successfully registered.",
    created_at: now,
    updated_at: now,
  };
  const appeal = await api.functional.prefix.admin.policyAudit.appeals.create(
    connection,
    { body: appealInput },
  );
  typia.assert(appeal);

  // 3. Validate returned object echoes all main schema fields
  TestValidator.equals("appeal_code strictly matches")(appeal.appeal_code)(
    appealCode,
  );
  TestValidator.equals("status strictly matches")(appeal.status)("PENDING");
  TestValidator.equals("incident_id correctly references recorded incident")(
    appeal.incident_id,
  )(incident.id);
  TestValidator.equals("created_at matches")(appeal.created_at)(now);
  TestValidator.equals("updated_at matches")(appeal.updated_at)(now);
  TestValidator.equals("outcome matches")(appeal.outcome || undefined)(
    appealInput.outcome,
  );
  TestValidator.equals("nullable appellant_id matches")(
    appeal.appellant_id || null,
  )(null);
}

