import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPost";

/**
 * Tests that a member can successfully hard-delete their own post edit log, and
 * that after deletion the log is no longer accessible.
 *
 * Business context:
 *
 * - A member (discussionboard_members) should be able to erase their personal
 *   post edit log adjusting their own forum content history.
 * - Before deletion, a post edit log must exist (requires creation of member,
 *   thread, post, and an edit event on the post).
 * - After deletion, confirm that the resource is no longer accessible.
 * - Ownership should be enforced: only the log owner may hard-delete their own
 *   edit logs.
 *
 * Steps:
 *
 * 1. Register a new member (to serve as the edit log owner)
 * 2. Create a new thread as that member
 * 3. Create a new post by that member into the thread
 * 4. Edit the post via the member's endpoint (this will generate a post edit log
 *    entry)
 * 5. Delete the edit log entry as its owner
 *
 * Note: There is no SDK or documented API to retrieve post edit log ids after
 * creation or check existence after deletion. Thus, validation of log
 * nonexistence after deletion is omitted for lack of implementable APIs.
 */
export async function test_api_prefix_test_delete_post_edit_log_owned_successfully(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const createdAt = new Date().toISOString();
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId,
        created_at: createdAt,
      },
    },
  );
  typia.assert(member);

  // 2. Create a new thread associated with a random test category
  const threadCategoryId = typia.random<string & tags.Format<"uuid">>();
  const threadTimestamp = new Date().toISOString();
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: threadCategoryId,
        title: `Test thread for post edit log deletion`,
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: threadTimestamp,
        updated_at: threadTimestamp,
      },
    },
  );
  typia.assert(thread);

  // 3. Create the post as the member
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        parent_post_id: null,
        body: "This is the original post body.",
      },
    },
  );
  typia.assert(post);

  // 4. Edit the post to create an edit log entry.
  const editedBodyText = "This is the edited post body.";
  const editOutput =
    await api.functional.prefix.member.my.threadsPosts.posts.update(
      connection,
      {
        id: post.id,
        body: {
          body: editedBodyText,
          is_edited: true,
          updated_at: new Date().toISOString(),
        },
      },
    );
  typia.assert(editOutput);

  // 5. Delete the edit log entry.
  //    (edit log id is unavailable, so using post.id as a placeholder for the log id,
  //    as the API and DTO do not expose real edit log entities or identifiers.)
  await api.functional.prefix.member.my.threadsPosts.postEditLogs.erase(
    connection,
    {
      id: post.id as string & tags.Format<"uuid">,
    },
  );

  // No verifiable API exists to check if the log was deleted; skip that assertion.
}

