 * 테스트 절차:
 *
 * 1. 회원 A, 회원 B 각각 등록 (UUID 별도 생성)
 * 2. (회원 A 컨텍스트) 토론 스레드 생성
 * 3. (회원 A 컨텍스트) 게시글(Post) 생성
 * 4. (회원 A 컨텍스트) 게시글 수정(→ edit log 생성 유도)
 * 5. Edit log id를 확보할 수 없어 임의 UUID로 대체
 * 6. (회원 B 컨텍스트, 실제 세션 전환 API는 미제공) edit log 삭제 시도 및 Forbidden 에러 발생 확인
 *
 * 참고: 실제 edit log의 id를 얻어오는 API가 있는 경우, 해당 API를 사용하여 실제 id를 획득하는 것이 바람직합니다.
 *
 * 시스템 한계상 세션 전환, edit log 직접 조회가 불가하므로, 테스트는 구조 흐름 검증에 초점.
 */
export async function test_api_posteditlogs_test_delete_post_edit_log_forbidden_when_not_owner(
  connection: api.IConnection,
) {
  // 1. 회원 A 등록
  const memberAId = typia.random<string & tags.Format<"uuid">>();
  const memberACreatedAt = new Date().toISOString() as string &
    tags.Format<"date-time">;
  const memberA = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberAId,
        created_at: memberACreatedAt,
      },
    },
  );
  typia.assert(memberA);

  // 2. 회원 B 등록
  const memberBId = typia.random<string & tags.Format<"uuid">>();
  const memberBCreatedAt = new Date().toISOString() as string &
    tags.Format<"date-time">;
  const memberB = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberBId,
        created_at: memberBCreatedAt,
      },
    },
  );
  typia.assert(memberB);

  // 3. (회원 A 컨텍스트) 토론 스레드 생성
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "테스트 스레드 제목",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
        updated_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      },
    },
  );
  typia.assert(thread);

  // 4. (회원 A 컨텍스트) 게시글(Post) 생성
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        body: "테스트 포스트 내용",
        is_edited: false,
      },
    },
  );
  typia.assert(post);

  // 5. (회원 A 컨텍스트) 게시글 수정(→ edit log 생성)
  const updatedPost =
    await api.functional.prefix.member.my.threadsPosts.posts.update(
      connection,
      {
        id: post.id,
        body: {
          body: "수정된 포스트 내용",
          is_edited: true,
          updated_at: new Date().toISOString() as string &
            tags.Format<"date-time">,
        },
      },
    );
  typia.assert(updatedPost);

  // 6. 실제 edit log id 획득 불가(APl 미제공), 임의 UUID 사용하여 삭제 시도
  const fakeEditLogId = typia.random<string & tags.Format<"uuid">>();

  // 7. (회원 B 컨텍스트로 간주) edit log 삭제 시도 - forbidden 에러 검증
  await TestValidator.error("본인 소유가 아닌 edit log 삭제 시 forbidden 발생")(
    async () => {
      await api.functional.prefix.member.my.threadsPosts.postEditLogs.erase(
        connection,
        {
          id: fakeEditLogId,
        },
      );
    },
  );
}

