import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IThreadArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IThreadArchive";
import type { IPageIThreadArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIThreadArchive";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Retrieve a filtered and paginated list of thread archive records for a
 * member.
 *
 * This test validates that when a member archives one or more threads, the
 * thread archive listing API returns the archived threads when filtering and
 * paginating. The process includes:
 *
 * 1. Register a new member (the archiver)
 * 2. Create two new threads using this member
 * 3. Soft-archive (delete) both threads as the member, so archive records are
 *    generated
 * 4. Retrieve the thread archive list with filters applied (such as member id or
 *    thread id), and with explicit pagination
 * 5. Validate that the output contains correct archive records for the threads,
 *    with appropriate pagination meta-data
 * 6. Validate that filtering (by thread id and member id) works as expected
 */
export async function test_api_prefix_test_list_thread_archives_with_basic_pagination_and_filtering(
  connection: api.IConnection,
) {
  // 1. Register a new member (archiver)
  const memberId: string = typia.random<string & tags.Format<"uuid">>();
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId,
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create two threads as this member
  const categoryId: string = typia.random<string & tags.Format<"uuid">>();
  const thread1 =
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_member_id: memberId,
        discussionboard_category_id: categoryId,
        title: `Test thread 1 ${Math.random()}`,
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      } satisfies IDiscussionboardThreads.ICreate,
    });
  typia.assert(thread1);
  const thread2 =
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_member_id: memberId,
        discussionboard_category_id: categoryId,
        title: `Test thread 2 ${Math.random()}`,
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      } satisfies IDiscussionboardThreads.ICreate,
    });
  typia.assert(thread2);

  // 3. Archive (soft-delete) both threads as the member
  await api.functional.prefix.member.my.threadsPosts.threads.erase(connection, {
    id: thread1.id,
  });
  await api.functional.prefix.member.my.threadsPosts.threads.erase(connection, {
    id: thread2.id,
  });

  // 4. Fetch archived threads, filtered by member id, with pagination (limit 1 per page)
  const archivesPage1 =
    await api.functional.prefix.member.threadsPosts.threadArchives.index(
      connection,
      {
        body: {
          archived_by_member_id: memberId,
          page: 1,
          limit: 1,
        } satisfies IThreadArchive.IRequest,
      },
    );
  typia.assert(archivesPage1);

  // 5. Check that data is present and pagination meta looks correct
  TestValidator.predicate("archive results on page 1")(
    archivesPage1.data.length === 1,
  );
  TestValidator.equals("pagination current page")(
    archivesPage1.pagination.current,
  )(1);
  TestValidator.equals("pagination limit")(archivesPage1.pagination.limit)(1);
  TestValidator.predicate("total pages >= 2")(
    archivesPage1.pagination.pages >= 2,
  );

  // 6. Fetch second page to check for the next record
  const archivesPage2 =
    await api.functional.prefix.member.threadsPosts.threadArchives.index(
      connection,
      {
        body: {
          archived_by_member_id: memberId,
          page: 2,
          limit: 1,
        } satisfies IThreadArchive.IRequest,
      },
    );
  typia.assert(archivesPage2);
  TestValidator.predicate("archive results on page 2")(
    archivesPage2.data.length === 1,
  );

  // 7. Fetch archive for only thread1 (should be one record for that thread)
  const archiveThread1 =
    await api.functional.prefix.member.threadsPosts.threadArchives.index(
      connection,
      {
        body: {
          thread_id: thread1.id,
          page: 1,
          limit: 10,
        } satisfies IThreadArchive.IRequest,
      },
    );
  typia.assert(archiveThread1);
  TestValidator.predicate("archive result for thread1")(
    archiveThread1.data.some(
      (it) => it.discussionboard_thread_id === thread1.id,
    ),
  );
}

