import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate retrieval of thread archive records when there are no archives
 * present.
 *
 * Business context: This test ensures that when there are no archived threads
 * in the system, a "list archives" request returns a correct empty result set
 * and proper pagination object instead of errors or unexpected data. This is
 * important to guarantee that pagination and filtering logic work even in
 * empty-state conditions.
 *
 * Steps:
 *
 * 1. Ensure no thread archive records exist (assume clean DB or initial state with
 *    zero records).
 * 2. Call the thread archive list API with an empty/default filter (i.e., no
 *    filters applied).
 * 3. Validate that the API returns:
 *
 *    - A valid pagination object (with current/limit/records/pages all being correct
 *         for zero results)
 *    - An empty data array
 *    - Type safety for response according to expected DTO structure
 */
export async function test_api_threadarchive_test_thread_archives_no_results_when_none_exist(
  connection: api.IConnection,
) {
  // 1. Call the list thread archives endpoint with no filters (default request)
  const result =
    await api.functional.prefix.member.threadsPosts.threadArchives.index(
      connection,
      { body: {} satisfies IThreadArchive.IRequest },
    );
  typia.assert(result);

  // 2. Validate that the data array is empty (no archives present)
  TestValidator.equals("no archived thread records")(result.data)([]);

  // 3. Validate pagination metadata is correct (zero records, pages, etc.)
  TestValidator.equals("page current is 1")(result.pagination.current)(1);
  TestValidator.equals("page limit is default or 100")(result.pagination.limit)(
    100,
  );
  TestValidator.equals("total records is zero")(result.pagination.records)(0);
  TestValidator.equals("total pages is zero")(result.pagination.pages)(0);
}

