  // 3. Filter thread archives by memberA's ID
  const archivePage =
    await api.functional.prefix.member.threadsPosts.threadArchives.index(
      connection,
      {
        body: {
          archived_by_member_id: memberA.id,
        },
      },
    );
  typia.assert(archivePage);

  // 4. Validate that all returned archives were archived by memberA and not memberB
  for (const archive of archivePage.data) {
    TestValidator.equals("archive archived_by_member_id")(
      archive.archived_by_member_id,
    )(memberA.id);
  }
}

