import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IThreadArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IThreadArchive";
import type { IPageIThreadArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIThreadArchive";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 토론 스레드 아카이브(soft-delete) 기록을 모더레이터 권한으로 상세 필터 및 페이지네이션 조회한다.
 *
 * 1. 테스트용 멤버 유저로 토론 스레드 2개를 생성
 * 2. 한 스레드를 soft-delete(아카이브)하여 archive 기록를 생성
 * 3. 어드민 권한으로 해당 멤버에게 모더레이터 권한을 할당
 * 4. 모더레이터로, thread_id / archived_by_member_id / archive_reason / page, limit으로
 *    다양한 조건 필터링 조회
 * 5. 각 조회 결과가 입력한 원본 스레드ID, 아카이브자, 사유, 페이징 조건과 정확히 일치하는지 검증
 * 6. 실패 및 권한 예외 케이스(모더레이터 권한 없이 접근시, 존재하지 않는 조건 등)도 커버
 */
export async function test_api_prefix_test_list_thread_archives_as_moderator_with_advanced_filters(
  connection: api.IConnection,
) {
  // (1) 테스트용 멤버 로그인/권한 (e2e 환경에 맞춰 인증/권한 부여 생략 또는 별도 처리 필요)
  // (2) 토론 스레드 2개 등록
  const now = new Date().toISOString();
  const categoryId = typia.random<string & tags.Format<"uuid">>();

  // 첫 스레드 생성
  const thread1 =
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_category_id: categoryId,
        title: "e2e 아카이브 필터용 스레드1",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: now,
        updated_at: now,
      },
    });
  typia.assert(thread1);

  // 두 번째 스레드 생성
  const thread2 =
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_category_id: categoryId,
        title: "e2e 아카이브 필터용 스레드2",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: now,
        updated_at: now,
      },
    });
  typia.assert(thread2);

  // (3) thread1을 soft-delete → archive 기록 생성 기대
  await api.functional.prefix.member.my.threadsPosts.threads.erase(connection, {
    id: thread1.id,
  });

  // (4) 어드민 권한으로 thread1.creator에게 모더레이터 권한 부여 (디폴트 mock 환경에선 직접 부여)
  const moderatorAssign =
    await api.functional.prefix.admin.actors.moderators.create(connection, {
      body: {
        id: thread1.discussionboard_member_id,
        created_at: new Date().toISOString(),
      },
    });
  typia.assert(moderatorAssign);

  // (5) 모더레이터로 아카이브 레코드 고급 필터 조회 및 검증
  // 5-1. thread_id 필터
  const resByThreadId =
    await api.functional.prefix.moderator.threadsPosts.threadArchives.index(
      connection,
      {
        body: {
          thread_id: thread1.id,
          page: 1,
          limit: 10,
        },
      },
    );
  typia.assert(resByThreadId);
  for (const archive of resByThreadId.data) {
    TestValidator.equals("thread_id 필터 일치")(
      archive.discussionboard_thread_id,
    )(thread1.id);
  }

  // 5-2. archived_by_member_id 필터
  const resByMemberId =
    await api.functional.prefix.moderator.threadsPosts.threadArchives.index(
      connection,
      {
        body: {
          archived_by_member_id: thread1.discussionboard_member_id,
          page: 1,
          limit: 10,
        },
      },
    );
  typia.assert(resByMemberId);
  for (const archive of resByMemberId.data) {
    TestValidator.equals("archived_by_member_id 필터 일치")(
      archive.archived_by_member_id,
    )(thread1.discussionboard_member_id);
  }

  // 5-3. archive_reason(간단 문자열 입력) 키워드 필터 (테스트 환경에서 실제 필드 입력/저장 동작 여부에 따라 조정)
  // - 아카이브 기록 생성 시 실제 사유를 입력하는 API가 없으므로, archive_reason 필드 값 확인만 로직상 검증(실사용 환경 따라 skip/구현).
  const resWithReason =
    await api.functional.prefix.moderator.threadsPosts.threadArchives.index(
      connection,
      {
        body: {
          archive_reason: "",
          page: 1,
          limit: 10,
        },
      },
    );
  typia.assert(resWithReason);
  // (optional 검증: archive_reason이 검색 가능한 환경/사유 입력 방식시 여기에 assertion 추가)

  // 5-4. page, limit - 페이지네이션 동작 확인
  const resPaged =
