import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardAdmin";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IThreadArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IThreadArchive";
import type { IPageIThreadArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIThreadArchive";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E: archive_reason 필터로 관리자 스레드 아카이브 목록 필터링
 *
 * - 여러 개 스레드 각각을 soft-archive 처리한 뒤, archive_reason 필드로 필터링 조회 동작을 검증한다
 * - 비즈니스상 아카이브 사유는 직접 입력 불가(erase API 제한) → 실제 시스템에서는 동일한 사유 값으로만 아카이브가 생성될 수 있음
 * - 테스트는 API의 제약 내에서 archive_reason 필터 동작과 빈 결과 리턴 처리까지 검증한다
 *
 * 1. 관리자로 사용할 테스트 UUID를 생성하고, 관리자로 role 할당을 수행
 * 2. 3개 이상의 스레드를 순차 생성(같은 카테고리 사용, 각 스레드는 unarchived로 시작)
 * 3. 각 스레드별로 erase API로 soft-archive 수행 (사유값은 직접 제어 불가)
 * 4. 관리자는 archive_reason으로 아카이브 목록을 필터링하여 조회 (존재하는 값/없는 값)
 * 5. 각 케이스에 대한 반환 데이터의 archive_reason, 개수 등 검증
 */
export async function test_api_admin_test_admin_filter_thread_archives_by_reason(
  connection: api.IConnection,
) {
  // 1. 테스트용 관리자 UUID 생성 & 관리자 역할 할당
  const adminId: string = typia.random<string & tags.Format<"uuid">>();
  const admin: IDiscussionboardAdmin =
    await api.functional.prefix.admin.actors.admins.create(connection, {
      body: {
        id: adminId,
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardAdmin.ICreate,
    });
  typia.assert(admin);

  // 2. 동일 카테고리로 3개 스레드 생성
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();
  const threads: IDiscussionboardThreads[] = await ArrayUtil.asyncRepeat(3)(
    async (idx) => {
      return api.functional.prefix.member.threadsPosts.threads.create(
        connection,
        {
          body: {
            discussionboard_category_id: categoryId,
            title: `테스트 스레드 ${idx + 1}`,
            status: "active",
            is_pinned: false,
            is_locked: false,
            archived: false,
            created_at: new Date(now.getTime() + idx * 5000).toISOString(),
            updated_at: new Date(now.getTime() + idx * 5000).toISOString(),
          } satisfies IDiscussionboardThreads.ICreate,
        },
      );
    },
  );
  threads.forEach((thread) => typia.assert(thread));

  // 3. 각 스레드별로 soft-archive 처리 (erase는 직접 사유 지정 불가)
  await ArrayUtil.asyncMap(threads)(async (thread) => {
    await api.functional.prefix.member.my.threadsPosts.threads.erase(
      connection,
      { id: thread.id },
    );
  });

  // 4-1. 존재하는 archive_reason (시스템 기본 사유, 예시로 '정책위반')로 필터링
  const targetReason = "정책위반";
  const page: IPageIThreadArchive =
    await api.functional.prefix.admin.threadsPosts.threadArchives.index(
      connection,
      {
        body: { archive_reason: targetReason },
      },
    );
  typia.assert(page);
  page.data.forEach((archive) => {
    TestValidator.equals("archive reason match")(archive.archive_reason)(
      targetReason,
    );
  });

  // 4-2. 존재하지 않는 archive_reason으로 필터링 시 빈 데이터
  const emptyResult =
    await api.functional.prefix.admin.threadsPosts.threadArchives.index(
      connection,
      { body: { archive_reason: "존재하지않는사유" } },
    );
  typia.assert(emptyResult);
  TestValidator.equals("no archives for unknown reason")(
    emptyResult.data.length,
  )(0);
}

