import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IThreadArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IThreadArchive";

/**
 * 인증된 멤버가 자신의 스레드를 아카이브(soft delete)한 후, 아카이브 레코드 상세정보를 id로 조회하여 무결성과 권한을 검증하는
 * E2E 테스트입니다.
 *
 * 본 테스트는 다음의 실제 사용자 흐름을 검증합니다:
 *
 * 1. 멤버 역할을 등록 및 인증합니다 (id 고정)
 * 2. 해당 멤버 권한으로 스레드를 생성합니다
 * 3. 생성된 스레드를 해당 멤버가 직접 아카이브(soft delete) 처리합니다
 * 4. 아카이브 레코드 id로 thread archive 상세 조회를 수행합니다
 * 5. 반환값의 논리적 일관성, 소유성, 통합 데이터 무결성을 검증합니다
 *
 * 단, 아카이브 id는 실제 운영 시스템에서는 아카이브 create/delete API 반환값이나 목록조회 API 등에서 획득해야 하나, 본
 * 테스트에선 archive id 추출 경로가 불명확하므로 해당 부분은 실제 환경에 맞춰 추후 보완 필요함을 유의하세요.
 */
export async function test_api_prefix_test_get_thread_archive_details_success(
  connection: api.IConnection,
) {
  // 1. 멤버 등록 및 인증
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const memberCreateTime = new Date().toISOString();
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId,
        created_at: memberCreateTime,
      },
    },
  );
  typia.assert(member);

  // 2. 멤버 권한으로 스레드 생성
  const threadCategoryId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date().toISOString();
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: threadCategoryId,
        title: "E2E archive thread test",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: now,
        updated_at: now,
      },
    },
  );
  typia.assert(thread);
  TestValidator.equals("thread 소유자 검증")(thread.discussionboard_member_id)(
    memberId,
  );

  // 3. 생성한 스레드를 본인(멤버)이 아카이브(soft delete)
  await api.functional.prefix.member.my.threadsPosts.threads.erase(connection, {
    id: thread.id,
  });

  // 4. thread archive 상세정보 조회 (주의: archive id 추출/전달 경로는 실제 운영시스템 기준 보완 필요)
  //    본 테스트에선 archive id를 임의 생성하여 테스트용 조회 수행 (실제 시스템은 archive id 반환/목록 API를 통해 확보해야 함)
  const archiveId = typia.random<string & tags.Format<"uuid">>();
  const archive =
    await api.functional.prefix.member.threadsPosts.threadArchives.at(
      connection,
      {
        id: archiveId,
      },
    );
  typia.assert(archive);

  // 5. 반환 archive의 thread id, archive 수행자(멤버 id) 검증
  TestValidator.equals("아카이브 thread id 매칭")(
    archive.discussionboard_thread_id,
  )(thread.id);
  TestValidator.equals("아카이브 수행자 매칭")(archive.archived_by_member_id)(
    memberId,
  );
}

