/**
 * Test that requesting details for a non-existent thread archive id returns a
 * not found error.
 *
 * This test validates that the API returns the proper error when attempting to
 * retrieve a thread archive event that does not exist (invalid or non-existent
 * id). This is important to prevent leakage of information, avoid inappropriate
 * success responses, and ensure proper error propagation and auditing for
 * client applications.
 *
 * Steps:
 *
 * 1. Generate a random UUID that should not correspond to any existing thread
 *    archive record.
 * 2. Attempt to retrieve the thread archive using the API endpoint `GET
 *    /prefix/member//threadsPosts/threadArchives/{id}`
 * 3. Assert that a not found error is thrown (HttpError with 404 status), and no
 *    data is returned.
 *
 * This confirms proper error handling for requests with invalid thread archive
 * ids.
 */
export async function test_api_threadArchives_test_get_thread_archive_not_found(
  connection: api.IConnection,
) {
  // 1. Generate a random UUID
  const nonExistingArchiveId = typia.random<string & tags.Format<"uuid">>();

  // 2. Try to get the non-existent thread archive (should fail with not found)
  await TestValidator.error("not found error for non-existent thread archive")(
    async () => {
      await api.functional.prefix.member.threadsPosts.threadArchives.at(
        connection,
        {
          id: nonExistingArchiveId,
        },
      );
    },
  );
}

