import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IThreadArchive } from "@ORGANIZATION/PROJECT-api/lib/structures/IThreadArchive";

/**
 * 인증된 멤버가 자신이 소유하지 않은 스레드 아카이브 기록에 접근할 수 없는지 검증합니다.
 *
 * 비즈니스 룰에 따라, 소유자가 아닌 멤버(또는 관리자 권한 없는 멤버)는 타인의 thread archive 상세 정보에 접근하면 안
 * 됩니다. 즉, 본인이 생성하지 않은 (혹은 서버 권한상 비인가된) thread archive id 접근시 접근 거부(에러)가 발생하는지
 * 검증합니다.
 *
 * [테스트 프로세스]
 *
 * 1. 멤버 A와 멤버 B를 각각 등록합니다.
 * 2. 멤버 A(소유자) 컨텍스트에서 archived 상태의 thread를 생성합니다. (생성시 archived: true 지정)
 * 3. 멤버 B의 인증 컨텍스트로 전환 후, 해당 thread의 archive id로 상세 조회를 시도합니다.
 * 4. TestValidator.error()로 비소유자 접근 시 에러 발생(403 Forbidden 등)을 검증합니다.
 *
 * 테스트 환경에 따라 실제 멤버 인증 컨텍스트 분리/전환(connection 인스턴스 분리 또는 헤더 Authorization 갱신 등)을
 * 구현해야 할 수 있습니다. 이 예제 코드에서는 동일 connection 내에서 ID만 분리해 동작하지만, 실제론 회원별 인증 토큰 환경
 * 차단까지 개발 필요성을 감안하세요.
 */
export async function test_api_prefix_test_get_thread_archive_forbidden_for_non_owner(
  connection: api.IConnection,
) {
  // 1. 멤버 A 등록
  const memberA_id = typia.random<string & tags.Format<"uuid">>();
  const memberA_createdAt = new Date().toISOString();
  const memberA = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberA_id,
        created_at: memberA_createdAt,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(memberA);

  // 2. 멤버 A 인증 컨텍스트에서 archived 상태 thread 생성
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "archived thread access forbidden test",
        status: "archived",
        is_pinned: false,
        is_locked: false,
        archived: true,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      } satisfies IDiscussionboardThreads.ICreate,
    },
  );
  typia.assert(thread);

  // 3. 멤버 B 등록
  const memberB_id = typia.random<string & tags.Format<"uuid">>();
  const memberB_createdAt = new Date().toISOString();
  const memberB = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberB_id,
        created_at: memberB_createdAt,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(memberB);

  // 4. 멤버 B 인증(컨텍스트 전환) 후, thread archive id 상세 조회(비소유자)
  await TestValidator.error(
    "타인 아카이브 접근시 접근 거부(권한 에러) 발생해야 함",
  )(async () => {
    await api.functional.prefix.member.threadsPosts.threadArchives.at(
      connection,
      {
        id: thread.id,
      },
    );
  });
}

