 *
 * 비즈니스 시나리오:
 *
 * 1. 인증된 사용자가 Discussion Board 알림 생성 API를 사용하여 자신의 알림을 만듭니다.
 * 2. 생성된 알림의 id(alertId)로 알림 단건 조회 API를 호출합니다.
 * 3. 응답 결과로 반환되는 모든 필드(id, discussionboard_member_id, type, severity, title, body,
 *    is_active, created_at, resolved_at)를 스키마 정의와 일치하게 검증합니다.
 * 4. 조회된 알림이 본인(세션 유저)에게 소유된 데이터임을 확인하고, 타인의 알림이 노출되지 않음을 소유자 id로 검증합니다.
 *
 * 단계별 검증 흐름:
 *
 * 1. 알림 생성
 * 2. 생성된 알림 id(alertId)로 단건 조회
 * 3. 반환 필드 및 소유자 일치성 검증
 * 4. (실패 케이스: 타인의 알림 접근/조회는 본 테스트 목적 외로 제외)
 */
export async function test_api_discussionboardAlerts_test_retrieve_own_alert_with_valid_id(
  connection: api.IConnection,
) {
  // 1. 인증된 멤버로 알림 생성
  const creationInput: discussionboard_alerts.ICreate = {
    type: "suspension_warning",
    severity: "warning",
    title: "Policy Violation Warning",
    body: "You have violated the discussion board policy. Please review the policies to avoid suspension.",
    is_active: true,
  };
  const created: discussionboard_alerts =
    await api.functional.prefix.member.my.discussionboardAlerts.create(
      connection,
      {
        body: creationInput,
      },
    );
  typia.assert(created);

  // 2. 생성된 알림의 id(alertId)로 단건 조회
  const retrieved: discussionboard_alerts =
    await api.functional.prefix.member.my.discussionboardAlerts.at(connection, {
      alertId: created.id,
    });
