  // 3. 반환 필드 및 값 검증
  TestValidator.equals("id")(retrieved.id)(created.id);
  TestValidator.equals("discussionboard_member_id")(
    retrieved.discussionboard_member_id,
  )(created.discussionboard_member_id);
  TestValidator.equals("type")(retrieved.type)(creationInput.type);
  TestValidator.equals("severity")(retrieved.severity)(creationInput.severity);
  TestValidator.equals("title")(retrieved.title)(creationInput.title);
  TestValidator.equals("body")(retrieved.body)(creationInput.body);
  TestValidator.equals("is_active")(retrieved.is_active)(
    creationInput.is_active,
  );
  TestValidator.predicate("created_at이 정의되어 있고 ISO 형식임")(
    typeof retrieved.created_at === "string" &&
      !isNaN(Date.parse(retrieved.created_at)),
  );
  TestValidator.equals("resolved_at 값 비교")(
    "resolved_at" in created ? (created.resolved_at ?? null) : null,
  )("resolved_at" in retrieved ? (retrieved.resolved_at ?? null) : null);
}

