/**
 * Verify that an authenticated member can update their own discussion board
 * alert record.
 *
 * This test ensures:
 *
 * 1. The member creates an alert for themselves (prerequisite).
 * 2. The member updates the alert using the correct alertId and only permitted
 *    schema-defined fields (is_active, resolved_at).
 * 3. The update operation enforces ownership and does not allow over-posting or
 *    changing other fields.
 * 4. The response returns the updated alert record with only the allowed fields
 *    changed, all others remaining the same.
 */
export async function test_api_discussionboardAlerts_test_update_own_alert_successfully(
  connection: api.IConnection,
) {
  // 1. Create an alert as the authenticated member (prerequisite)
  const alert =
    await api.functional.prefix.member.my.discussionboardAlerts.create(
      connection,
      {
        body: {
          type: "policy_update",
          severity: "info",
          title: RandomGenerator.alphabets(10),
          body: RandomGenerator.paragraph()(),
          is_active: true,
        },
      },
    );
  typia.assert(alert);

  // 2. Prepare update: toggle is_active, set resolved_at
  const updatePayload = {
    is_active: false,
    resolved_at: new Date().toISOString(),
  } satisfies IDiscussionboardAlert.IUpdate;

  // 3. Perform the update
  const updatedAlert =
    await api.functional.prefix.member.my.discussionboardAlerts.update(
      connection,
      {
        alertId: alert.id,
        body: updatePayload,
      },
    );
  typia.assert(updatedAlert);

  // 4. Validate changes vs original record
  TestValidator.equals("is_active updated")(updatedAlert.is_active)(
    updatePayload.is_active,
  );
  TestValidator.equals("resolved_at updated")(updatedAlert.resolved_at)(
    updatePayload.resolved_at,
  );
  // Ensure all other fields remain unchanged
  TestValidator.equals("id unchanged")(updatedAlert.id)(alert.id);
  TestValidator.equals("member id unchanged")(
    updatedAlert.discussionboard_member_id,
  )(alert.discussionboard_member_id);
  TestValidator.equals("type unchanged")(updatedAlert.type)(alert.type);
  TestValidator.equals("severity unchanged")(updatedAlert.severity)(
    alert.severity,
  );
  TestValidator.equals("title unchanged")(updatedAlert.title)(alert.title);
  TestValidator.equals("body unchanged")(updatedAlert.body)(alert.body);
  TestValidator.equals("created_at unchanged")(updatedAlert.created_at)(
    alert.created_at,
  );
}

