/**
 * Validates that a member cannot update an alert not owned by them (i.e.,
 * ownership/authorization enforcement).
 *
 * Business context: This test ensures that members can only update alerts that
 * belong to themselves. If a member attempts to update an alert (by alertId)
 * that is owned by a different member, the API must reject this operation with
 * a forbidden (403) or not-found (404) error.
 *
 * Step-by-step process:
 *
 * 1. Create an alert as another member (simulate as if session/context is from a
 *    different user).
 * 2. Switch the session/context to a separate member (the test subject; does NOT
 *    own the alert).
 * 3. Attempt to update the alert with valid input (is_active, resolved_at).
 * 4. Verify update fails due to forbidden/not-owned error (ownership test).
 */
export async function test_api_prefix_member_my_discussionboardAlerts_test_update_alert_not_owned_forbidden(
  connection: api.IConnection,
) {
  // 1. Create an alert as another member ("other user")
  // (In E2E, session would be set so this alert is NOT owned by test user)
  const otherMemberAlert =
    await api.functional.prefix.member.my.discussionboardAlerts.create(
      connection, // This connection must represent the OTHER member (not the test subject)
      {
        body: {
          type: "suspension_warning",
          severity: "critical",
          title: "Warning: Policy Violation",
          body: "Your post has been flagged by moderators.",
          is_active: true,
        },
      },
    );
  typia.assert(otherMemberAlert);

  // 2. Switch to the test subject's session (not the alert's owner)
  // (Session/user switching omitted—assume connection is now that of a different, non-owner member)

  // 3. Attempt update; expect forbidden/not-found error
  await TestValidator.error(
    "Should not be able to update alert belonging to another member",
  )(async () => {
    await api.functional.prefix.member.my.discussionboardAlerts.update(
      connection, // Connection is now the test subject (not the alert's owner)
      {
        alertId: otherMemberAlert.id,
        body: {
          is_active: false,
          resolved_at: new Date().toISOString(),
        },
      },
    );
  });
}

