import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISearchHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/ISearchHistory";
import type { IPageISearchHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageISearchHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test fetching a paginated list of search history records with filtering and
 * pagination options.
 *
 * This test covers combinations of:
 *
 * - Basic pagination (limit/offset)
 * - Field-specific filtering (search_query, used_filters)
 * - Date/time range filtering (executed_at_from, executed_at_to)
 * - Inclusion of soft-deleted rows (include_deleted)
 * - Sort option
 * - Multi-filter intersection
 * - Edge case: out-of-bounds offset
 *
 * Steps:
 *
 * 1. Make a basic paginated request with limit/offset; check data/page meta
 * 2. Use search_query filter and verify returned rows match the query
 * 3. Use used_filters filter and verify correct filtered data
 * 4. Use date range (executed_at_from, executed_at_to)
 * 5. Combine filters for intersection test
 * 6. Set include_deleted: true and check for soft-deleted results
 * 7. Sort by executed_at descending and verify order
 * 8. Use a very large offset to check empty response
 */
export async function test_api_prefix_test_list_search_histories_with_pagination_filters(
  connection: api.IConnection,
) {
  // 1. Basic paginated request (limit/offset)
  const baseLimit = 5;
  const baseOffset = 0;
  const resPaginated = await api.functional.prefix.searchHistories.index(
    connection,
    {
      body: { limit: baseLimit, offset: baseOffset },
    },
  );
  typia.assert(resPaginated);
  TestValidator.equals("pagination.limit")(resPaginated.pagination.limit)(
    baseLimit,
  );
  TestValidator.predicate("results <= limit")(
    resPaginated.data.length <= baseLimit,
  );

  // 2. search_query filter (simulated value)
  const searchQuery = "trend";
  const resQuery = await api.functional.prefix.searchHistories.index(
    connection,
    {
      body: { search_query: searchQuery, limit: 10 },
    },
  );
  typia.assert(resQuery);
  for (const row of resQuery.data) {
    TestValidator.predicate("search_query filter")(
      row.search_query.includes(searchQuery),
    );
  }

  // 3. used_filters filter
  const filtersStr = "tag:economics,section:policy";
  const resFilters = await api.functional.prefix.searchHistories.index(
    connection,
    {
      body: { used_filters: filtersStr, limit: 10 },
    },
  );
  typia.assert(resFilters);
  for (const row of resFilters.data) {
    TestValidator.equals("used_filters")(row.used_filters ?? "")(filtersStr);
  }

  // 4. executed_at_from / executed_at_to (date range)
  const executedFrom = "2024-01-01T00:00:00.000Z";
  const executedTo = "2025-01-01T00:00:00.000Z";
  const resDateRange = await api.functional.prefix.searchHistories.index(
    connection,
    {
      body: {
        executed_at_from: executedFrom,
        executed_at_to: executedTo,
        limit: 10,
      },
    },
  );
  typia.assert(resDateRange);
  for (const row of resDateRange.data) {
    TestValidator.predicate("executed_at in range")(
      row.executed_at >= executedFrom && row.executed_at <= executedTo,
    );
  }

  // 5. Multi-filter intersection
  const resMulti = await api.functional.prefix.searchHistories.index(
    connection,
    {
      body: {
        search_query: searchQuery,
        used_filters: filtersStr,
        executed_at_from: executedFrom,
        executed_at_to: executedTo,
        limit: 10,
      },
    },
  );
  typia.assert(resMulti);
  for (const row of resMulti.data) {
    TestValidator.predicate("intersection: search_query")(
      row.search_query.includes(searchQuery),
    );
    TestValidator.equals("intersection: used_filters")(row.used_filters ?? "")(
      filtersStr,
    );
    TestValidator.predicate("intersection: executed_at")(
      row.executed_at >= executedFrom && row.executed_at <= executedTo,
    );
  }

  // 6. include_deleted true
  const resDeleted = await api.functional.prefix.searchHistories.index(
    connection,
    {
      body: { include_deleted: true, limit: 10 },
    },
  );
  typia.assert(resDeleted);
  for (const row of resDeleted.data) {
    TestValidator.predicate("deleted_at present or null")(
      typeof row.deleted_at === "string" || row.deleted_at === null,
    );
  }

  // 7. sort by executed_at desc
  const resSorted = await api.functional.prefix.searchHistories.index(
    connection,
    {
      body: { sort: "executed_at_desc", limit: 10 },
    },
  );
  typia.assert(resSorted);
  let last: string | null = null;
  for (const row of resSorted.data) {
    if (last !== null) {
      TestValidator.predicate("sorted descending")(row.executed_at <= last);
    }
    last = row.executed_at;
  }

  // 8. Out-of-bounds offset yields no data
  const bigOffset = 9999;
  const resOob = await api.functional.prefix.searchHistories.index(connection, {
    body: { offset: bigOffset, limit: 10 },
  });
  typia.assert(resOob);
  TestValidator.equals("out-of-bounds data")(resOob.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { ISearchHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/ISearchHistory";
import type { IPageISearchHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageISearchHistory";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Soft deletion 정책이 searchHistories 목록 조회에 올바르게 적용되는지 확인한다.
 *
 * [비즈니스 시나리오]
 *
 * - Deleted_at가 null이 아닌(soft deleted) 레코드는 기본 목록 응답에 제외되어야 하며, deleted_at가
 *   null인(미삭제) 레코드만 반환되는 것이 원칙이다.
 * - Soft deletion이 적용된 데이터는 기본 조회에선 빠지고, include_deleted: true 파라미터로만 확인 가능해야 한다.
 *
 * [테스트 절차]
 *
 * 1. (실제 데이터 mock 없이) 목록 API 기본 호출 → 모든 data.deleted_at이 null임을 검증
 * 2. Include_deleted: true로 목록 API 재호출 → soft deleted (deleted_at != null) 엔트리가
 *    반환되는지 확인
 */
export async function test_api_prefix_test_list_search_histories_exclude_soft_deleted(
  connection: api.IConnection,
) {
  // 1. 기본 검색 기록 목록(soft deleted 미포함) 호출
  const outputDefault = await api.functional.prefix.searchHistories.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(outputDefault);
  for (const record of outputDefault.data) {
    // 반환된 모든 기록은 미삭제(soft deleted 아님)여야 함
    TestValidator.equals("returned record is not soft deleted")(
      record.deleted_at,
    )(null);
  }

  // 2. soft deleted 포함 파라미터 지정 후 목록 호출
  const outputIncludeDeleted =
    await api.functional.prefix.searchHistories.index(connection, {
      body: { include_deleted: true },
    });
  typia.assert(outputIncludeDeleted);
  // soft deleted(=deleted_at != null) 데이터가 1건 이상이라면 반드시 함께 반환됨
  const hasSoftDeleted = outputIncludeDeleted.data.some(
    (r) => r.deleted_at !== null,
  );
  TestValidator.predicate("soft deleted record should be included if exists")(
    hasSoftDeleted,
  );
}

