import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IDiscussionboardPostLike } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPostLike";

/**
 * 인증된 회원이 본인이 소유한 게시글 좋아요(post like) 상세 정보를 정상적으로 조회할 수 있는지 검증합니다.
 *
 * - 회원이 먼저 가입하여 member 역할을 부여받고
 * - 토론 스레드를 생성한 후, 해당 스레드에 본인이 게시글을 작성하고
 * - 직접 방금 등록한 게시글에 좋아요(post like)를 수행한 뒤
 * - 생성된 좋아요 기록의 id로 상세 조회 API를 호출합니다.
 *
 * 기대값:
 *
 * 1. 조회 응답에는 discussionboard_post_likes 스키마의 필수 정보(id, post id, member id,
 *    created_at 등)가 모두 포함됩니다.
 * 2. 좋아요 소유자인 member id와, 클라이언트 인증 정보의 member id가 반드시 일치해야 합니다.
 *
 * 주요 테스트 목적은 본인 소유의 like 단건 상세 내역을 정확히 반환하고, 감사/히스토리 기록 UX의 기본 신뢰성을 점검하는 것입니다.
 *
 * 단계:
 *
 * 1. 멤버 등록 (id: uuid, created_at: now)
 * 2. 토론스레드 생성(등록 멤버 id를 작성자 FK, 카테고리는 무작위 uuid)
 * 3. 게시글 등록(위에서 만든 스레드 id와 멤버 id 사용, 본문 random)
 * 4. 게시글에 본인(member)으로 post like 등록(post id & member id)
 * 5. Post like id로 상세 정보 조회
 * 6. 반환되는 모든 속성(특히 discussionboard_member_id)이 member와 정확히 일치하는지, 전체 스키마 준수하는지 확인
 */
export async function test_api_prefix_test_get_post_like_when_like_exists_and_member_is_owner(
  connection: api.IConnection,
) {
  // 1. 멤버 생성 (인증된 테스트용 멤버 추가)
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const memberCreatedAt = new Date().toISOString();
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId,
        created_at: memberCreatedAt,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member);

  // 2. 토론 스레드 생성 (카테고리 uuid 임시 random값)
  const threadCategoryId = typia.random<string & tags.Format<"uuid">>();
  const threadCreatedAt = new Date().toISOString();
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_member_id: memberId,
        discussionboard_category_id: threadCategoryId,
        title: "Test thread title",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: threadCreatedAt,
        updated_at: threadCreatedAt,
      } satisfies IDiscussionboardThreads.ICreate,
    },
  );
  typia.assert(thread);

  // 3. 게시글 등록 (방금 생성한 thread 이용, parent_post_id 없음, 본문 랜덤)
  const postBody = "Test post body - " + typia.random<string>();
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        body: postBody,
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(post);

  // 4. 게시글에 like 등록 (본인 member로, 해당 post)
  const like = await api.functional.prefix.member.postLikes.create(connection, {
    body: {
      discussionboard_post_id: post.id,
      discussionboard_member_id: memberId,
    } satisfies IDiscussionboardPostLike.ICreate,
  });
  typia.assert(like);

  // 5. 생성된 like id로 상세 조회
  const likeDetail = await api.functional.prefix.member.postLikes.at(
    connection,
    {
      id: like.id,
    },
  );
  typia.assert(likeDetail);

  // 6. 반환 값 소유자, 타겟 post 등 확인
  TestValidator.equals("like id matches")(likeDetail.id)(like.id);
  TestValidator.equals("like post id matches")(
    likeDetail.discussionboard_post_id,
  )(post.id);
  TestValidator.equals("like member matches")(
    likeDetail.discussionboard_member_id,
  )(memberId);
  TestValidator.predicate("likeDetail created_at valid")(
    typeof likeDetail.created_at === "string" &&
      likeDetail.created_at.length > 0,
  );
}

