 * 4. 회원1 인증 상태로 스레드에 게시글을 작성한다
 * 5. 회원1 인증 상태로 해당 게시글에 좋아요(postLike)를 단다
 * 6. 인증을 회원2로 전환한다
 * 7. 회원2 인증 상태에서 회원1의 좋아요(postLike) id로 삭제 시도
 * 8. 삭제는 반드시 실패(권한 오류 등)해야 하며, 성공 시 테스트는 오류
 */
export async function test_api_prefix_member_my_postLikes_test_delete_post_like_not_owned_by_member_should_return_forbidden(
  connection: api.IConnection,
) {
  // 1. 회원1 등록
  const member1Id = typia.random<string & tags.Format<"uuid">>();
  await api.functional.prefix.member.actors.members.create(connection, {
    body: {
      id: member1Id,
      created_at: new Date().toISOString(),
    },
  });

  // 2. 회원2 등록
  const member2Id = typia.random<string & tags.Format<"uuid">>();
  await api.functional.prefix.member.actors.members.create(connection, {
    body: {
      id: member2Id,
      created_at: new Date().toISOString(),
    },
  });

  // 3. 회원1 인증 상태로 스레드 생성
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: categoryId,
        title: "소유권 테스트 스레드",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(thread);

  // 4. 회원1 인증 상태로 스레드에 게시글 작성
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        body: "소유권 테스트 게시글",
        is_edited: false,
      },
