import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { discussionboard_mentions } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboard_mentions";

/**
 * 멤버 멘션 필터 검색 E2E 검증
 *
 * 1. 두 멤버를 각각 생성 (멘션 생성자와 멘션 대상자)
 * 2. 랜덤 카테고리 id로 스레드를 하나 생성
 * 3. 생성 스레드에 멘션 생성자가 포스트를 작성
 * 4. 생성된 포스트에 멘션 대상자를 멘션으로 등록
 * 5. Post id로 Mentions 검색해 방금 삽입된 mention이 결과에 포함되는지 확인
 * 6. Mentioned_member_id로 Mentions 검색해 방금 삽입된 mention이 결과에 포함되는지 확인
 */
export async function test_api_prefix_member_mentions_test_list_mentions_with_post_and_member_filters(
  connection: api.IConnection,
) {
  // 1. 두 명의 멤버 생성 (id 및 가입일은 랜덤)
  const creator: IDiscussionboardMembers =
    await api.functional.prefix.member.actors.members.create(connection, {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      },
    });
  typia.assert(creator);

  const mentioned: IDiscussionboardMembers =
    await api.functional.prefix.member.actors.members.create(connection, {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      },
    });
  typia.assert(mentioned);

  // 2. 스레드 생성 (카테고리 id 랜덤)
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "mention e2e 테스트 스레드",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(thread);

  // 3. 포스트 생성 (discussionboard_thread_id만 지정, 작성자 인증 컨텍스트)
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        body: "@테스트 멤버님을 멘션합니다.",
        is_edited: false,
      },
    },
  );
  typia.assert(post);

  // 4. 포스트에 멘션 생성
  const mention = await api.functional.prefix.member.mentions.create(
    connection,
    {
      body: {
        discussionboard_post_id: post.id,
        mentioned_member_id: mentioned.id,
      },
    },
  );
  typia.assert(mention);

  // 5. discussionboard_post_id 기준 Mentions 조회 및 방금 생성된 mention 포함여부 확인
  const mentionsByPost = await api.functional.prefix.member.mentions.index(
    connection,
    {
      body: { discussionboard_post_id: post.id },
    },
  );
  typia.assert(mentionsByPost);
  const existsByPost = mentionsByPost.data.some((m) => m.id === mention.id);
  TestValidator.predicate("discussionboard_post_id로 조회 시 생성된 멘션 포함")(
    existsByPost,
  );

  // 6. mentioned_member_id 기준 Mentions 조회 및 방금 생성된 mention 포함여부 확인
  const mentionsByMember = await api.functional.prefix.member.mentions.index(
    connection,
    {
      body: { mentioned_member_id: mentioned.id },
    },
  );
  typia.assert(mentionsByMember);
  const existsByMember = mentionsByMember.data.some((m) => m.id === mention.id);
  TestValidator.predicate("mentioned_member_id로 조회 시 생성된 멘션 포함")(
    existsByMember,
  );
}

