import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IMention";
import type { IPageIMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIMention";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { discussionboard_mentions } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboard_mentions";

/**
 * 멘션 리스트 API의 페이징 및 정렬 기능을 검증합니다.
 *
 * 실제 회원-포스트에 여러 mention을 추가한 후, 페이징(limit/page)과 정렬(created_at desc)이 제대로 적용돼
 * 반환되는지 검증합니다.
 *
 * 실무에서 대규모 멘션 트래킹/알림 용도에 필수적인 기능입니다.
 *
 * [테스트 플로우]
 *
 * 1. 멘션 대상 회원 생성
 * 2. 임의 토론 스레드 생성
 * 3. 해당 스레드에 포스트 생성
 * 4. 동일 회원·포스트에 mention 여러 건 생성 (예: 5회)
 * 5. Limit/page 조합으로 리스트 API 호출 (limit=2, page=2)
 * 6. 응답 pagination 필드(current/limit/records 등), data 길이 등 assert
 * 7. 실제 생성 mention 기록을 최신순으로 정렬해 반환 데이터 id와 일치 검증
 * 8. 다른 limit 조합(limit=3, page=1)도 추가로 리스트 API에 요청해 응답 일관성 확인
 */
export async function test_api_mentions_test_mentions_list_pagination_and_sorting(
  connection: api.IConnection,
) {
  // 1. 멘션 대상 회원 생성
  const mentionedMember =
    await api.functional.prefix.member.actors.members.create(connection, {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      },
    });
  typia.assert(mentionedMember);

  // 2. 임의 토론 스레드 생성
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: "Pagination Mention Test " + Date.now(),
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
        updated_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      },
    },
  );
  typia.assert(thread);

  // 3. 해당 스레드에 포스트 생성
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        body: "Test for mention pagination",
      },
    },
  );
  typia.assert(post);

  // 4. 동일 회원·포스트에 mention 여러 건 생성
  const mentionCount = 5;
  const createdMentions: discussionboard_mentions[] = [];
  for (let i = 0; i < mentionCount; ++i) {
    const mention = await api.functional.prefix.member.mentions.create(
      connection,
      {
        body: {
          discussionboard_post_id: post.id,
          mentioned_member_id: mentionedMember.id,
        },
      },
    );
    typia.assert(mention);
    createdMentions.push(mention);
  }
  // 로컬 최신순 정렬 (created_at desc)
  const localSorted = [...createdMentions].sort((a, b) =>
    (b.created_at as string).localeCompare(a.created_at as string),
  );

  // 5. 페이징(limit=2, page=2) 조합으로 리스트 요청
  const limit = 2;
  const page = 2;
  const mentionPage = await api.functional.prefix.member.mentions.index(
    connection,
    {
      body: {
        mentioned_member_id: mentionedMember.id,
        discussionboard_post_id: post.id,
        limit,
        page,
      },
    },
  );
  typia.assert(mentionPage);

  // 6. 페이징 메타데이터 검증
  TestValidator.equals("current page")(mentionPage.pagination.current)(page);
  TestValidator.equals("limit")(mentionPage.pagination.limit)(limit);
  TestValidator.equals("records")(mentionPage.pagination.records)(
    createdMentions.length,
  );

  // 7. 반환 mention들 최신(created_at desc) 순서 및 수량 검증
  TestValidator.equals("data length")(mentionPage.data.length)(limit);
  for (let i = 0; i < mentionPage.data.length; ++i) {
    TestValidator.equals(`mention id ${i}`)(mentionPage.data[i].id)(
      localSorted[(page - 1) * limit + i].id,
    );
  }

  // 8. 다른 limit(3, page=1) 조합 재요청 및 첫페이지 데이터 일관성 체크
  const newLimit = 3;
  const firstPage = await api.functional.prefix.member.mentions.index(
    connection,
    {
      body: {
        mentioned_member_id: mentionedMember.id,
        discussionboard_post_id: post.id,
        limit: newLimit,
        page: 1,
      },
    },
  );
  typia.assert(firstPage);
  TestValidator.equals("first page length")(firstPage.data.length)(newLimit);
  for (let i = 0; i < firstPage.data.length; ++i) {
    TestValidator.equals(`first page id ${i}`)(firstPage.data[i].id)(
      localSorted[i].id,
    );
  }
}

