import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IMention";
import type { IPageIMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIMention";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { discussionboard_mentions } from "@ORGANIZATION/PROJECT-api/lib/structures/discussionboard_mentions";

/**
 * Validate that a moderator can retrieve all mention records for a specific
 * member.
 *
 * This test ensures that once a member is mentioned in various posts, those
 * mentions are correctly retrievable via the moderator's mention-listing API,
 * using filters such as mentioned_member_id. This scenario is relevant for
 * moderation workflows requiring review of member tagging history and proper
 * filtering in the mentions listing.
 *
 * Step-by-step process:
 *
 * 1. Create a target member that will be mentioned by others
 *    (discussionboard_members.create).
 * 2. Create two threads to host separate mentionable posts
 *    (discussionboard_threads.create).
 * 3. In each thread, create a post intended to mention the created member
 *    (discussionboard_posts.create).
 * 4. For both posts, create mention records pointing to the target member
 *    (discussionboard_mentions.create).
 * 5. As a moderator, retrieve all mentions for the target member using the
 *    mentions listing endpoint, filtered by mentioned_member_id
 *    (moderator.mentions.index).
 * 6. Verify that all created mention records are returned and correctly reference
 *    the target member.
 */
export async function test_api_moderator_test_moderator_can_list_mentions_by_member(
  connection: api.IConnection,
) {
  // 1. Create a member to be mentioned
  const mentioned_member_id = typia.random<string & tags.Format<"uuid">>();
  const createdMember =
    await api.functional.prefix.member.actors.members.create(connection, {
      body: {
        id: mentioned_member_id,
        created_at: new Date().toISOString(),
      },
    });
  typia.assert(createdMember);

  // 2. Create two threads for different contexts
  const category_id_1 = typia.random<string & tags.Format<"uuid">>();
  const category_id_2 = typia.random<string & tags.Format<"uuid">>();
  const thread1 =
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_category_id: category_id_1,
        title: "Thread 1 - for mention test",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      },
    });
  typia.assert(thread1);
  const thread2 =
    await api.functional.prefix.member.threadsPosts.threads.create(connection, {
      body: {
        discussionboard_category_id: category_id_2,
        title: "Thread 2 - for mention test",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      },
    });
  typia.assert(thread2);

  // 3. Create two posts in the threads
  const post1 = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread1.id,
        body: "Hello @member1 - first mention",
      },
    },
  );
  typia.assert(post1);
  const post2 = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread2.id,
        body: "Hi @member1 - another mention",
      },
    },
  );
  typia.assert(post2);

  // 4. Create mentions in each post for the target member
  const mention1 = await api.functional.prefix.member.mentions.create(
    connection,
    {
      body: {
        discussionboard_post_id: post1.id,
        mentioned_member_id: mentioned_member_id,
      },
    },
  );
  typia.assert(mention1);
  const mention2 = await api.functional.prefix.member.mentions.create(
    connection,
    {
      body: {
        discussionboard_post_id: post2.id,
        mentioned_member_id: mentioned_member_id,
      },
    },
  );
  typia.assert(mention2);

  // 5. Retrieve all mentions for the target member as a moderator
  const result = await api.functional.prefix.moderator.mentions.index(
    connection,
    {
      body: { mentioned_member_id },
    },
  );
  typia.assert(result);

  // 6. Verify the output includes both created mention records for this member
  const mention_ids = result.data.map((m) => m.id);
  TestValidator.predicate("all created mentions are present")(
    mention_ids.includes(mention1.id) && mention_ids.includes(mention2.id),
  );
  // Also check that all returned mentions are for the correct member
  TestValidator.predicate("all mentions reference the correct member")(
    result.data.every((m) => m.mentioned_member_id === mentioned_member_id),
  );
}

