 *    `created_at_to`. Should fail validation.
 * 4. Attempt to search using negative page and limit values. Should fail
 *    validation.
 * 5. For all, ensure TestValidator.error is triggered, confirming validation
 *    failure.
 */
export async function test_api_prefix_test_moderator_mentions_search_invalid_input_fails(
