  // 4. Soft-delete this search history
  await api.functional.prefix.member.my.searchHistories.erase(connection, {
    searchHistoryId: searchHistory.id,
  });
  // Cannot verify after deletion because SDK exposes no get/list.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
