/**
 * 인증된 사용자가 자신이 소유하지 않은 검색 기록을 소프트 삭제하려고 할 때 금지(forbidden) 오류가 발생하는지 검증합니다.
 *
 * 본 테스트는 소유권 강제 정책을 검증합니다.
 *
 * 절차:
 *
 * 1. Member A를 등록한다.
 * 2. Member B를 등록한다.
 * 3. Member B 계정 세션으로 검색 기록을 1건 생성한다.
 * 4. Member A 계정 세션으로 Member B의 검색 기록 소프트 삭제 API를 호출한다.
 *
 *    - 이때 금지(forbidden) 오류가 발생해야 한다.
 */
export async function test_api_prefix_member_my_searchHistories_test_soft_delete_search_history_record_not_owned_forbidden(
  connection: api.IConnection,
) {
  // 1. Member A 생성
  const memberAId = typia.random<string & tags.Format<"uuid">>();
  const memberA: IDiscussionboardMembers =
    await api.functional.prefix.member.actors.members.create(connection, {
      body: {
        id: memberAId,
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardMembers.ICreate,
    });
  typia.assert(memberA);

  // 2. Member B 생성
  const memberBId = typia.random<string & tags.Format<"uuid">>();
  const memberB: IDiscussionboardMembers =
    await api.functional.prefix.member.actors.members.create(connection, {
      body: {
        id: memberBId,
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardMembers.ICreate,
    });
  typia.assert(memberB);

  // 3. Member B로 검색 기록 1건 생성
  const bConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      "x-discussionboard-member-id": memberBId,
    },
  };
  const searchHistory: ISearchHistory =
    await api.functional.prefix.member.my.searchHistories.create(bConnection, {
      body: {
        discussionboard_member_id: memberBId,
        search_query: RandomGenerator.paragraph()(),
        used_filters: null,
        executed_at: new Date().toISOString(),
        deleted_at: null,
      } satisfies ISearchHistory.ICreate,
    });
  typia.assert(searchHistory);

  // 4. Member A로 Member B의 검색기록 소프트 삭제 시도 & forbidden 오류 검증
  const aConnection = {
    ...connection,
    headers: {
      ...connection.headers,
      "x-discussionboard-member-id": memberAId,
    },
  };
  await TestValidator.error("타인의 검색 기록 소프트 삭제는 금지되어야 함")(
    async () => {
      await api.functional.prefix.member.my.searchHistories.erase(aConnection, {
        searchHistoryId: searchHistory.id,
      });
    },
  );
}

