import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IThreadTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IThreadTag";

/**
 * Validate retrieval of detailed thread tag information by threadTagId.
 *
 * This test verifies that after creating a thread tag via the platform's member
 * endpoint, fetching that tag by its unique threadTagId returns the correct and
 * complete set of details. It ensures both the API's basic retrieval function
 * and the integrity of stored tag properties.
 *
 * Test Workflow:
 *
 * 1. Create a thread tag using the member thread tag creation endpoint.
 * 2. Use the returned tag's id as the threadTagId to fetch the tag via the detail
 *    endpoint.
 * 3. Assert that every relevant field from the retrieved tag matches the ones from
 *    creation response.
 */
export async function test_api_threadTags_test_retrieve_thread_tag_details_when_exists(
  connection: api.IConnection,
) {
  // 1. Create a thread tag for setup
  const createInput: IThreadTag.ICreate = {
    code: RandomGenerator.alphaNumeric(12),
    display_name: RandomGenerator.paragraph()(1),
    description: RandomGenerator.paragraph()(1),
    is_restricted: Math.random() > 0.5,
    is_hidden: Math.random() > 0.5,
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const created: IThreadTag =
    await api.functional.prefix.member.threadTags.create(connection, {
      body: createInput,
    });
  typia.assert(created);

  // 2. Retrieve the newly created tag by its ID
  const retrieved: IThreadTag = await api.functional.prefix.threadTags.at(
    connection,
    { threadTagId: created.id },
  );
  typia.assert(retrieved);

  // 3. Assert all relevant fields match
  TestValidator.equals("code matches")(retrieved.code)(created.code);
  TestValidator.equals("display_name matches")(retrieved.display_name)(
    created.display_name,
  );
  TestValidator.equals("description matches")(retrieved.description ?? null)(
    created.description ?? null,
  );
  TestValidator.equals("is_restricted matches")(retrieved.is_restricted)(
    created.is_restricted,
  );
  TestValidator.equals("is_hidden matches")(retrieved.is_hidden)(
    created.is_hidden,
  );

  // 4. Assert meta fields (created_at and possibly updated_at)
  TestValidator.equals("created_at matches")(retrieved.created_at)(
    created.created_at,
  );
  TestValidator.equals("updated_at is initially null or matches")(
    retrieved.updated_at ?? null,
  )(created.updated_at ?? null);
}

