/**
 * Validate successful creation of a thread tag with full field coverage.
 *
 * Ensures that a new thread tag can be created when all required and optional
 * fields are provided, adhering to the IThreadTag.ICreate schema:
 *
 * - Code (string): Unique, canonical tag code (lowercase, alphanumeric or
 *   underscore).
 * - Display_name (string): User-facing label for the tag.
 * - Description (string|null|undefined): Optional description of the tag.
 * - Is_restricted (boolean): Whether tag assignment is restricted to
 *   admin/moderator.
 * - Is_hidden (boolean): Whether tag is only visible to admin/moderator.
 * - Created_at (string, date-time): ISO8601 creation timestamp.
 *
 * The test does the following:
 *
 * 1. Generate valid, realistic values for all fields, including explicit null for
 *    description and an explicit created_at date.
 * 2. Calls the thread tag creation API with all fields set, including optional
 *    ones.
 * 3. Verifies that the API response includes all provided values, and that they
 *    match those sent (except system-generated fields like id, updated_at).
 * 4. If updated_at is included in the response as null or undefined, accept both
 *    options since it's optional.
 */
export async function test_api_prefix_member_threadTags_create_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Prepare tag creation payload with required and optional fields
  const payload: IThreadTag.ICreate = {
    code: `e2e_tag_${RandomGenerator.alphaNumeric(8)}`.toLowerCase(),
    display_name: `E2E Tag Test ${RandomGenerator.alphabets(4)}`,
    description: RandomGenerator.paragraph()(),
    is_restricted: false,
    is_hidden: false,
    created_at: new Date().toISOString(),
  };

  // 2. Create the thread tag using the API
  const output = await api.functional.prefix.member.threadTags.create(
    connection,
    { body: payload },
  );
  typia.assert(output);

  // 3. Assert all returned values match input (except generated 'id' and possibly 'updated_at')
  TestValidator.equals("code")(output.code)(payload.code);
  TestValidator.equals("display_name")(output.display_name)(
    payload.display_name,
  );
  TestValidator.equals("description")(output.description)(payload.description);
  TestValidator.equals("is_restricted")(output.is_restricted)(
    payload.is_restricted,
  );
  TestValidator.equals("is_hidden")(output.is_hidden)(payload.is_hidden);
  TestValidator.equals("created_at")(output.created_at)(payload.created_at);

