    await api.functional.prefix.member.threadTags.create(connection, {
      body: {
        code: "validcode",
        display_name: null,
        is_restricted: false,
        is_hidden: false,
        created_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      } as any,
    });
  });

  // 5. Missing both code and display_name
  await TestValidator.error("missing code and display_name should fail")(
    async () => {
      await api.functional.prefix.member.threadTags.create(connection, {
        body: {
          // code: missing
          // display_name: missing
          is_restricted: false,
          is_hidden: false,
          created_at: new Date().toISOString() as string &
            tags.Format<"date-time">,
        } as any,
      });
    },
  );

  // 6. Missing is_restricted
  await TestValidator.error("missing is_restricted should fail")(async () => {
    await api.functional.prefix.member.threadTags.create(connection, {
      body: {
        code: "testmissingrest",
