/**
 * Verify that an admin can successfully update an existing thread tag's
 * properties.
 *
 * Business Context: Admins need to manage thread tags (used for categorizing
 * threads). This test ensures that after creating a tag (as setup), an admin
 * can edit properties such as display name, description, restriction, and
 * hidden status. After update, the changed fields must match the update
 * request.
 *
 * Steps:
 *
 * 1. Create a thread tag (member-level, as precondition)
 * 2. As admin, update display_name, description, is_restricted, is_hidden fields
 *    using the update API
 * 3. Confirm the returned tag object reflects all updated values (fields match
 *    expectations and previous values are changed)
 */
export async function test_api_prefix_admin_threadTags_test_update_thread_tag_by_admin_success(
  connection: api.IConnection,
) {
  // 1. Create a thread tag (as prerequisite, via member API)
  const createInput: IThreadTag.ICreate = {
    code: RandomGenerator.alphabets(8),
    display_name: "Initial Tag",
    description: "Original tag description",
    is_restricted: false,
    is_hidden: false,
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const created: IThreadTag =
    await api.functional.prefix.member.threadTags.create(connection, {
      body: createInput,
    });
  typia.assert(created);

  // 2. Prepare update payload (change several fields)
  const updateInput: IDiscussionboardThreadTag.IUpdate = {
    display_name: "Updated Tag",
    description: "Updated tag description",
    is_restricted: true,
    is_hidden: true,
    updated_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };

  // 3. Call admin update API
  const updated: IDiscussionboardThreadTag =
    await api.functional.prefix.admin.threadTags.update(connection, {
      threadTagId: created.id,
      body: updateInput,
    });
  typia.assert(updated);

  // 4. Validate field updates
  TestValidator.equals("display_name updated")(updated.display_name)(
    "Updated Tag",
  );
  TestValidator.equals("description updated")(updated.description)(
    "Updated tag description",
  );
  TestValidator.equals("is_restricted updated")(updated.is_restricted)(true);
  TestValidator.equals("is_hidden updated")(updated.is_hidden)(true);
  TestValidator.equals("id same")(updated.id)(created.id);
  TestValidator.notEquals("display_name changed")(updated.display_name)(
    created.display_name,
  );
  TestValidator.notEquals("is_restricted changed")(updated.is_restricted)(
    created.is_restricted,
  );
  TestValidator.notEquals("is_hidden changed")(updated.is_hidden)(
    created.is_hidden,
  );
}

