/**
 * Validate failure scenarios for invalid thread tag updates (admin).
 *
 * Tests that attempts to update a thread tag with illegal or business-invalid
 * values (like empty code or null for non-nullable fields) result in validation
 * errors. Also ensures positive control (valid update) still works. This
 * verifies both server-side business validation and proper admin-only access
 * control.
 *
 * Step-by-step process:
 *
 * 1. Create a thread tag as a member for the initial resource.
 * 2. Attempt to update with an empty code string (should fail: code must not be
 *    empty).
 * 3. Attempt to update with null code (should succeed: update means no change, but
 *    for explicit null, if API rejects, this will fail validation).
 * 4. Attempt to update with null for is_restricted (should succeed: means do not
 *    update this field).
 * 5. Attempt to update with an empty string for display_name (optional, business
 *    may require non-empty; if yes, should fail).
 * 6. Attempt a valid update to verify successful path (positive control).
 */
export async function test_api_threadTags_test_update_thread_tag_with_invalid_fields_failure(
  connection: api.IConnection,
) {
  // 1. Create a thread tag as member
  const tag = await api.functional.prefix.member.threadTags.create(connection, {
    body: {
      code: `tag_${RandomGenerator.alphaNumeric(8)}`,
      display_name: "Test Tag",
      description: "Test description",
      is_restricted: false,
      is_hidden: false,
      created_at: new Date().toISOString(),
    },
  });
  typia.assert(tag);

  // 2. Attempt update as admin with empty code string (should fail)
  await TestValidator.error("empty code should fail validation")(() =>
    api.functional.prefix.admin.threadTags.update(connection, {
      threadTagId: tag.id,
      body: { code: "" },
    }),
  );

  // 3. Attempt update with null code (should not update code -- null means skip update)
  const noChange = await api.functional.prefix.admin.threadTags.update(
    connection,
    {
      threadTagId: tag.id,
      body: { code: null },
    },
  );
  typia.assert(noChange);
  TestValidator.equals("code unchanged after null code update")(noChange.code)(
    tag.code,
  );

  // 4. Attempt update with null is_restricted (should succeed: skip update)
  const isRestrictedUnchanged =
    await api.functional.prefix.admin.threadTags.update(connection, {
      threadTagId: tag.id,
      body: { is_restricted: null },
    });
  typia.assert(isRestrictedUnchanged);
  TestValidator.equals("is_restricted unchanged after null update")(
    isRestrictedUnchanged.is_restricted,
  )(tag.is_restricted);

  // 5. Attempt update with empty string display_name (should fail if business rules reject empty)
  await TestValidator.error("empty display_name should fail validation")(() =>
    api.functional.prefix.admin.threadTags.update(connection, {
      threadTagId: tag.id,
      body: { display_name: "" },
    }),
  );

  // 6. Positive control: valid update
  const updated = await api.functional.prefix.admin.threadTags.update(
    connection,
    {
      threadTagId: tag.id,
      body: {
        code: `tag_${RandomGenerator.alphaNumeric(6)}`,
        display_name: "Updated Test Tag",
        description: "Updated description",
        is_restricted: true,
        is_hidden: true,
        updated_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(updated);
  TestValidator.equals("code updated")(updated.code)(
    `tag_${RandomGenerator.alphaNumeric(6)}`,
  );
  TestValidator.equals("display_name updated")(updated.display_name)(
    "Updated Test Tag",
  );
  TestValidator.equals("description updated")(updated.description)(
    "Updated description",
  );
  TestValidator.equals("is_restricted updated")(updated.is_restricted)(true);
  TestValidator.equals("is_hidden updated")(updated.is_hidden)(true);
}

