import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardFilter } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFilter";

/**
 * 인증 회원의 Saved Filter(검색/필터 설정) 생성 API 테스트
 *
 * [목적/비즈니스 문맥]
 *
 * - 인증 토큰이 부여된 회원이 자신의 Saved Filter를 생성하는 정상 동작을 검증한다.
 * - 필수 필드(name, definition, is_public)를 제공할 때는 성공적으로 생성 및 본인 소유로 저장되는지,
 * - 필수 필드 누락, schema 미정의 필드 포함, 및 타인 소유 지정(disucssionboard_member_id 강제주입)과 같은 오류
 *   및 보안 위협을 차단하는지도 검증한다.
 *
 * [검증절차]
 *
 * 1. 정상 케이스: 필수 필드만 넣고 생성 → 생성 결과, 입력값 정합·소유자 본인 확인
 * 2. Name 누락 → 생성 거부(Error)
 * 3. Definition 누락 → 생성 거부(Error)
 * 4. Is_public 누락 → 생성 거부(Error)
 * 5. Schema에 없는 필드(not_exist 등) 포함 → 생성 거부(Error)
 * 6. Discussionboard_member_id에 타인 uuid 직접 넣어 생성 시도 → 본인 소유로만 생성되어야 함을 실제 결과로 확인
 */
export async function test_api_prefix_member_my_filters_create(
  connection: api.IConnection,
) {
  // 1. 정상 케이스: 필수 필드만으로 생성
  const reqBody = {
    name: RandomGenerator.alphabets(10),
    definition: JSON.stringify({ tags: ["api", "e2e"], time: Date.now() }),
    is_public: true,
  } satisfies IDiscussionboardFilter.ICreate;
  const created = await api.functional.prefix.member.my.filters.create(
    connection,
    { body: reqBody },
  );
  typia.assert(created);
  TestValidator.equals("name")(created.name)(reqBody.name);
  TestValidator.equals("definition")(created.definition)(reqBody.definition);
  TestValidator.equals("is_public")(created.is_public)(reqBody.is_public);
  TestValidator.predicate("소유자 ID 존재해야 함")(
    !!created.discussionboard_member_id,
  );

  // 2. name 누락 → 생성 거부
  await TestValidator.error("name 누락 오류")(async () => {
    const body = {
      definition: reqBody.definition,
      is_public: reqBody.is_public,
    } as any as IDiscussionboardFilter.ICreate;
    await api.functional.prefix.member.my.filters.create(connection, { body });
  });
  // 3. definition 누락 → 생성 거부
  await TestValidator.error("definition 누락 오류")(async () => {
    const body = {
      name: reqBody.name,
      is_public: reqBody.is_public,
    } as any as IDiscussionboardFilter.ICreate;
    await api.functional.prefix.member.my.filters.create(connection, { body });
  });
  // 4. is_public 누락 → 생성 거부
  await TestValidator.error("is_public 누락 오류")(async () => {
    const body = {
      name: reqBody.name,
      definition: reqBody.definition,
    } as any as IDiscussionboardFilter.ICreate;
    await api.functional.prefix.member.my.filters.create(connection, { body });
  });
  // 5. schema에 없는 필드 포함 → 생성 거부
  await TestValidator.error("미정의 필드 포함 오류")(async () => {
    const body = {
      ...reqBody,
      not_exist: "test",
    } as any as IDiscussionboardFilter.ICreate;
    await api.functional.prefix.member.my.filters.create(connection, { body });
  });
  // 6. discussionboard_member_id에 타인 uuid를 직접 넣어 생성 시도 → 결과의 소유자가 본인인지 확인
  const fakeMemberId = typia.random<string & tags.Format<"uuid">>();
  const inputWithFakeId = {
    ...reqBody,
    discussionboard_member_id: fakeMemberId,
  } satisfies IDiscussionboardFilter.ICreate;
  const createdWithFakeId =
    await api.functional.prefix.member.my.filters.create(connection, {
      body: inputWithFakeId,
    });
  typia.assert(createdWithFakeId);
  TestValidator.predicate("타인 id 주입 시 실제 소유자는 본인이어야 함")(
    !!createdWithFakeId.discussionboard_member_id &&
      createdWithFakeId.discussionboard_member_id !== fakeMemberId,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardFilter } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFilter";
import type { IVoid } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoid";

/**
 * E2E test for updating a member's own saved discussion board filter, including
 * valid updates and forbidden/error conditions.
 *
 * - Creates a filter via POST /prefix/member//my/filters
 * - Updates the filter successfully via PUT /prefix/member//my/filters/{filterId}
 *   (tests: change name, definition, is_public)
 * - Verifies the updates are reflected in the returned object
 * - Soft-deletes the filter, then attempts update (should fail)
 * - Attempts to update a filter not owned by the user (should fail)
 * - Attempts to update a non-existent filter id (should fail)
 * - Attempts to update with extra fields not in schema (should be rejected)
 */
export async function test_api_prefix_member_my_filters_test_update_own_filter_valid_updates_and_forbidden_conditions(
  connection: api.IConnection,
) {
  // 1. Create a filter for the authenticated user
  const created = await api.functional.prefix.member.my.filters.create(
    connection,
    {
      body: {
        name: RandomGenerator.alphaNumeric(12),
        definition: JSON.stringify({ topic: RandomGenerator.alphaNumeric(6) }),
        is_public: false,
      } satisfies IDiscussionboardFilter.ICreate,
    },
  );
  typia.assert(created);

  // 2. Update the filter: change name, definition, and is_public
  const newName = RandomGenerator.alphaNumeric(15);
  const newDefinition = JSON.stringify({
    topic: RandomGenerator.alphaNumeric(8),
  });
  const updated = await api.functional.prefix.member.my.filters.update(
    connection,
    {
      filterId: created.id,
      body: {
        name: newName,
        definition: newDefinition,
        is_public: true,
      } satisfies IDiscussionboardFilter.IUpdate,
    },
  );
  typia.assert(updated);
  TestValidator.equals("filter id unchanged")(updated.id)(created.id);
  TestValidator.equals("updated name")(updated.name)(newName);
  TestValidator.equals("updated definition")(updated.definition)(newDefinition);
  TestValidator.equals("is_public now true")(updated.is_public)(true);

  // 3. Soft-delete the filter
  const erased = await api.functional.prefix.member.my.filters.erase(
    connection,
    {
      filterId: created.id,
    },
  );
  typia.assert(erased);

  // 4. Attempt to update soft-deleted filter -- should error
  await TestValidator.error("cannot update soft-deleted filter")(async () => {
    await api.functional.prefix.member.my.filters.update(connection, {
      filterId: created.id,
      body: { name: "Should not work" },
    });
  });

  // 5. Attempt to update a filter not owned by the user
  await TestValidator.error("cannot update a filter not owned by user")(
    async () => {
      await api.functional.prefix.member.my.filters.update(connection, {
        filterId: typia.random<string & tags.Format<"uuid">>(),
        body: { name: "No Access" },
      });
    },
  );

  // 6. Attempt to update a non-existent filter id
  await TestValidator.error("cannot update non-existent filter")(async () => {
    await api.functional.prefix.member.my.filters.update(connection, {
      filterId: typia.random<string & tags.Format<"uuid">>(),
      body: { definition: "{}" },
    });
  });

  // 7. Attempt to update with extra fields (should be rejected by API or typia.assert)
  await TestValidator.error("should reject update with extra fields")(
    async () => {
      await api.functional.prefix.member.my.filters.update(connection, {
        filterId: created.id,
        body: { name: "valid", extra_field: "not allowed" } as any,
        // Intentionally using any to include extra property for this negative test
      });
    },
  );
}

