/**
 * E2E Test for soft-deleting a filter and verifying permission and state
 * errors.
 *
 * Validates that a user can soft-delete their own saved filter (by setting
 * deleted_at), and that after deletion the filter is excluded from normal
 * reads. Attempts to soft-delete non-existent, already deleted, or non-owned
 * filters must return errors (not-found/forbidden).
 *
 * Steps:
 *
 * 1. Create a saved filter as the authenticated user.
 * 2. Ensure the filter exists and is not soft-deleted.
 * 3. Soft-delete the filter using DELETE.
 * 4. Confirm that subsequent reads for the filter fail.
 * 5. Ensure repeated soft-deletes on the same filter fail.
 * 6. Attempt to soft-delete a non-existent filter (random UUID) and expect error.
 * 7. (If test infra allows, try deleting someone else's filter; if not possible
 *    via public API, skip.)
 */
export async function test_api_prefix_member_filters_test_soft_delete_own_filter_and_error_on_non_owned_or_already_deleted(
  connection: api.IConnection,
) {
  // 1. Create a new filter for the authenticated user
  const filterInput = {
    name: RandomGenerator.alphabets(8),
    definition: JSON.stringify({ query: RandomGenerator.paragraph()() }),
    is_public: false,
  } satisfies IDiscussionboardFilter.ICreate;
  const filter = await api.functional.prefix.member.my.filters.create(
    connection,
    { body: filterInput },
  );
  typia.assert(filter);

  // 2. Read the filter and confirm it exists and is not soft-deleted
  const ownedFilter = await api.functional.prefix.member.my.filters.at(
    connection,
    { filterId: filter.id },
  );
  typia.assert(ownedFilter);
  TestValidator.equals("filter exists and is not deleted")(
    ownedFilter.deleted_at,
  )(null);
  TestValidator.equals("filter owner matches")(
    ownedFilter.discussionboard_member_id,
  )(filter.discussionboard_member_id);

  // 3. Soft-delete the filter (sets deleted_at)
  await api.functional.prefix.member.filters.erase(connection, {
    filterId: filter.id,
  });

  // 4. Subsequent reads should fail (filter is now soft-deleted)
  await TestValidator.error("cannot read soft-deleted filter")(async () => {
    await api.functional.prefix.member.my.filters.at(connection, {
      filterId: filter.id,
    });
  });

  // 5. Second attempt to soft-delete should error (already soft-deleted)
  await TestValidator.error("cannot soft-delete already deleted filter")(
    async () => {
      await api.functional.prefix.member.filters.erase(connection, {
        filterId: filter.id,
      });
    },
  );

  // 6. Attempt to soft-delete a non-existent filter (random UUID)
  await TestValidator.error("cannot delete non-existent filter")(async () => {
    await api.functional.prefix.member.filters.erase(connection, {
      filterId: typia.random<string & tags.Format<"uuid">>(),
    });
  });

  // 7. Optional: Delete filter belonging to another user
  // Not possible without user/role switching APIs or further setup, so skipped as per instructions
}

