 * reflect the details used during association creation, guaranteeing data
 * integrity from creation to retrieval.
 *
 * Workflow:
 *
 * 1. Create a thread to serve as association target.
 * 2. Create a thread tag for assignment.
 * 3. Associate the thread and tag via taggedThreads.
 * 4. Retrieve the taggedThreads record by its ID using GET.
 * 5. Assert all returned fields match the ones from creation.
 */
export async function test_api_prefix_test_get_thread_tag_association_by_id_success(
  connection: api.IConnection,
