        description: "Second tag for update.",
        is_restricted: false,
        is_hidden: false,
        created_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(tag2);

  // Step 5: Update the association to point to the second thread (can also switch tags)
  const updatedTaggedThread =
    await api.functional.prefix.member.taggedThreads.update(connection, {
      taggedThreadId: taggedThread.id,
