import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardFilter } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFilter";
import type { IPageIDiscussionboardFilter } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardFilter";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching, filtering, pagination, and exclusion of soft deleted
 * filters for the member's saved filter configurations.
 *
 * This test verifies:
 *
 * - Only the authenticated member's filters are returned (no other users/guests).
 * - Filters can be searched by partial name, and by is_public status.
 * - Pagination and creation timestamps are respected in results and pagination
 *   meta.
 * - Soft-deleted filters (deleted_at !== null) are never returned in searches.
 *
 * Steps:
 *
 * 1. Create multiple filters for the test member, mixing names ("Alpha", "Beta",
 *    "GammaPublic", "DeltaPrivate"), is_public true/false, and different
 *    created_at.
 * 2. Soft-delete one of the filters.
 * 3. Test unfiltered retrieval: All active filters for the test member (minus
 *    soft-deleted).
 * 4. Filter by partial name: e.g., name = "Alpha" retrieves only the matching
 *    filter.
 * 5. Filter by is_public=true: retrieves only public filters for the member.
 * 6. Pagination: create at least 10 filters and query with limit=5; validate
 *    correct meta/result count.
 * 7. Edge case: Search by a non-existent name, expect empty result.
 * 8. Edge case: Request a page size (limit) larger than result count, ensure all
 *    available are returned.
 * 9. Invalid filter combination: name and is_public mismatch, expect empty array.
 */
export async function test_api_prefix_member_filters_test_list_saved_filters_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // Helper for creating new unique names/definitions for testing
  const now = new Date();
  function makeFilterParams(
    name: string,
    isPublic: boolean,
    createdAt: string,
  ) {
    return {
      name,
      definition: JSON.stringify({ search: name, created: createdAt }),
      is_public: isPublic,
      created_at: createdAt,
    } satisfies IDiscussionboardFilter.ICreate;
  }

  // 1. Create a diverse set of filters
  const createdFilters: IDiscussionboardFilter[] = [];
  const filterNames = [
    "AlphaTest", // will search for "Alpha"
    "BetaCase",
    "GammaPublic",
    "DeltaPrivate",
    "Epsilon",
    "Zeta",
    "Eta",
    "ThetaPublic",
    "IotaPrivate",
    "Kappa",
    "Lambda",
  ];
  const isPublicFlags = [
    true,
    false,
    true,
    false,
    false,
    true,
    false,
    true,
    false,
    true,
    true,
  ];
  for (let i = 0; i < filterNames.length; ++i) {
    const dt = new Date(now.getTime() + i * 60000).toISOString(); // incremental timestamps
    const filter = await api.functional.prefix.member.filters.create(
      connection,
      {
        body: makeFilterParams(filterNames[i], isPublicFlags[i], dt),
      },
    );
    typia.assert(filter);
    createdFilters.push(filter);
  }
  // Save special filter IDs for testing
  const filterAlpha = createdFilters[0];
  const filterGamma = createdFilters[2];
  const filterDelta = createdFilters[3];
  const filterZeta = createdFilters[5];

  // 2. Soft-delete one (DeltaPrivate)
  await api.functional.prefix.member.filters.erase(connection, {
    filterId: filterDelta.id,
  });
  // 3. Test unfiltered retrieval: should not include DeltaPrivate
  {
    const result = await api.functional.prefix.member.filters.index(
      connection,
      {
        body: {},
      },
    );
    typia.assert(result);
    // None should have deleted_at
    TestValidator.predicate("no soft-deleted filter in full list")(
      result.data.every((f) => f.deleted_at == null),
    );
    TestValidator.predicate("no other member filters")(
      result.data.every(
        (f) =>
          !f.discussionboard_member_id ||
          f.discussionboard_member_id === filterAlpha.discussionboard_member_id,
      ),
    );
    TestValidator.equals("no DeltaPrivate present")(false)(
      result.data.some((x) => x.id === filterDelta.id),
    );
  }

  // 4. Partial name filtering: should get only filterAlpha
  {
    const result = await api.functional.prefix.member.filters.index(
      connection,
      {
        body: { name: "Alpha" },
      },
    );
    typia.assert(result);
    TestValidator.equals("alpha search only gets AlphaTest")(1)(
      result.data.length,
    );
    TestValidator.equals("alpha search result is correct")(filterAlpha.id)(
      result.data[0]?.id,
    );
  }

  // 5. is_public filter: true
  {
    const result = await api.functional.prefix.member.filters.index(
      connection,
      {
        body: { is_public: true },
      },
    );
    typia.assert(result);
    TestValidator.predicate("all are public")(
      result.data.every((f) => f.is_public),
    );
  }

  // 6. Pagination (limit = 5)
  {
    const result = await api.functional.prefix.member.filters.index(
      connection,
      {
        body: {},
      },
    );
    typia.assert(result);
    // If total filters >= 10 (after soft-delete), test paging
    if (result.data.length >= 10) {
      const paged = await api.functional.prefix.member.filters.index(
        connection,
        {
          body: {},
        },
      );
      typia.assert(paged);
      // Default paging in result.pagination (validate presence)
      TestValidator.predicate("pagination meta exists")(
        !!paged.pagination && typeof paged.pagination.current === "number",
      );
      TestValidator.predicate("page 1 has <= 10 records")(
        paged.data.length <= 10,
      );
    }
  }

  // 7. Edge: search for non-existent name
  {
    const result = await api.functional.prefix.member.filters.index(
      connection,
      {
        body: { name: "___NO_MATCH___" },
      },
    );
    typia.assert(result);
    TestValidator.equals("no result for no-match name")(0)(result.data.length);
  }

  // 8. Edge: large page size
  {
    const result = await api.functional.prefix.member.filters.index(
      connection,
      {
        body: {},
      },
    );
    typia.assert(result);
    // Just assert we get all available filters if real count < big limit
    TestValidator.predicate("data length matches count")(
      result.data.length <= result.pagination.limit,
    );
  }

  // 9. Invalid: name+is_public mismatch
  {
    const result = await api.functional.prefix.member.filters.index(
      connection,
      {
        body: { name: "___NO_MATCH___", is_public: false },
      },
    );
    typia.assert(result);
    TestValidator.equals("invalid filter gets none")(0)(result.data.length);
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardFilter } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFilter";

/**
 * Validates retrieval of a user's own saved filter details.
 *
 * Verifies basic success and all major failure conditions for filter detail
 * lookup by filterId.
 *
 * Steps:
 *
 * 1. Create a new filter (POST /prefix/member//filters) as a member user and save
 *    the returned ID and body values.
 * 2. Retrieve it back with GET /prefix/member//filters/{filterId} and check all
 *    properties and values match precisely.
 * 3. Attempt to fetch a filterId that does not exist and verify error (not found).
 * 4. (Skipped: Permission check for cross-user access, as user switching/auth not
 *    available.)
 * 5. Soft-delete a filter (by passing deleted_at in creation) then attempt to
 *    fetch and confirm it is not found or is marked deleted as expected.
 *
 * Validates API authorization, ownership, and visibility rules and proper
 * adherence to the detailed schema.
 */
export async function test_api_prefix_member_filters_test_get_own_saved_filter_details_success_and_not_found(
  connection: api.IConnection,
) {
  // 1. Create a filter as the member user
  const createBody: IDiscussionboardFilter.ICreate = {
    name: RandomGenerator.alphabets(8),
    definition: JSON.stringify({ query: RandomGenerator.alphabets(8) }),
    is_public: false,
  };
  const created: IDiscussionboardFilter =
    await api.functional.prefix.member.filters.create(connection, {
      body: createBody,
    });
  typia.assert(created);

  // 2. Retrieve it by ID and check that all fields match supplied values and schema
  const fetched: IDiscussionboardFilter =
    await api.functional.prefix.member.filters.at(connection, {
      filterId: created.id,
    });
  typia.assert(fetched);
  TestValidator.equals("retrieved filter matches created")(fetched.name)(
    createBody.name,
  );
  TestValidator.equals("retrieved filter matches created")(fetched.definition)(
    createBody.definition,
  );
  TestValidator.equals("retrieved filter matches created")(fetched.is_public)(
    createBody.is_public,
  );
  TestValidator.equals("retrieved filter ID matches")(fetched.id)(created.id);
  TestValidator.equals("not soft-deleted")(fetched.deleted_at)(null);

  // 3. Attempt to fetch a nonexistent filterId
  await TestValidator.error("nonexistent filterId returns not found")(
    async () => {
      await api.functional.prefix.member.filters.at(connection, {
        filterId: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );

  // 4. (Skipped: Permission error for accessing another user's filter as user switch API not available)

  // 5. Soft-delete: create a filter with deleted_at set, then try to fetch
  const softDeletedBody: IDiscussionboardFilter.ICreate = {
    name: RandomGenerator.alphabets(8),
    definition: JSON.stringify({ q: RandomGenerator.alphabets(6) }),
    is_public: true,
    deleted_at: new Date().toISOString(),
  };
  const softDeleted: IDiscussionboardFilter =
    await api.functional.prefix.member.filters.create(connection, {
      body: softDeletedBody,
    });
  typia.assert(softDeleted);
  await TestValidator.error("soft-deleted filter is inaccessible")(async () => {
    await api.functional.prefix.member.filters.at(connection, {
      filterId: softDeleted.id,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardFilter } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFilter";

/**
 * Validate creation of discussion board filters (saved search) including
 * success, conflict, and error conditions.
 *
 * This test ensures:
 *
 * - Authenticated members can create filters with valid schema fields only.
 * - Filters are owned by and attributed to the creating member only (ownership
 *   cannot be spoofed).
 * - Duplicate name/definition pairs are tested to see if uniqueness per user is
 *   enforced.
 * - All required fields must be present and valid.
 * - Invalid data and schema violations are rejected.
 * - Out-of-schema property injection is prohibited.
 *
 * Steps:
 *
 * 1. Create a filter with valid fields (minimal required)
 * 2. Verify response structure and owner assignment
 * 3. Attempt to create a filter with the same name/definition (check for business
 *    rule enforcement)
 * 4. Negative test: omit name (expect error)
 * 5. Negative test: omit definition (expect error)
 * 6. Negative test: use non-boolean for is_public (expect error)
 * 7. Negative test: try to pass discussionboard_member_id (should fail or be
 *    ignored)
 * 8. Negative test: inject out-of-schema property (should fail)
 */
export async function test_api_prefix_member_filters_test_create_saved_filter_with_valid_and_conflicting_data(
  connection: api.IConnection,
) {
  // 1. Successful creation with valid fields
  const filterName = RandomGenerator.alphabets(10);
  const filterDefinition = '{"type":"tag","tags":["test"]}';
  const createInput = {
    name: filterName,
    definition: filterDefinition,
    is_public: true,
  } satisfies IDiscussionboardFilter.ICreate;
  const created = await api.functional.prefix.member.filters.create(
    connection,
    {
      body: createInput,
    },
  );
  typia.assert(created);
  TestValidator.equals("name")(created.name)(filterName);
  TestValidator.equals("definition")(created.definition)(filterDefinition);
  TestValidator.equals("is_public")(created.is_public)(true);
  // Owner is set and matches (should not be null)
  TestValidator.predicate("owner assigned")(
    typeof created.discussionboard_member_id === "string" &&
      created.discussionboard_member_id.length > 0,
  );
  // id is set
  TestValidator.predicate("id is uuid")(created.id.length === 36);

  // 2. Attempt duplicate (same name/definition)
  const duplicate = await api.functional.prefix.member.filters.create(
    connection,
    {
      body: createInput,
    },
  );
  typia.assert(duplicate);
  TestValidator.equals("name")(duplicate.name)(filterName);
  TestValidator.equals("definition")(duplicate.definition)(filterDefinition);
  // Depending on system logic, either allowed or error. If allowed, id must differ
  TestValidator.notEquals("different id for duplicate")(duplicate.id)(
    created.id,
  );
  // Owner must still be same
  TestValidator.equals("duplicate owner")(duplicate.discussionboard_member_id)(
    created.discussionboard_member_id,
  );

  // 3. Negative: missing name
  TestValidator.error("missing name should fail")(async () => {
    await api.functional.prefix.member.filters.create(connection, {
      body: {
        definition: filterDefinition,
        is_public: false,
      } as any, // type system won't let us omit required so use as any for runtime error
    });
  });

  // 4. Negative: missing definition
  TestValidator.error("missing definition should fail")(async () => {
    await api.functional.prefix.member.filters.create(connection, {
      body: {
        name: "MissingDef",
        is_public: false,
      } as any,
    });
  });

  // 5. Negative: is_public non-boolean
  TestValidator.error("is_public as non-boolean should fail")(async () => {
    await api.functional.prefix.member.filters.create(connection, {
      body: {
        name: "badBool",
        definition: filterDefinition,
        is_public: 123 as any,
      } as any,
    });
  });

  // 6. Negative: try to assign discussionboard_member_id (should fail or be ignored)
  TestValidator.error("cannot spoof owner discussionboard_member_id")(
    async () => {
