/**
 * Test successful creation of a new poll in a discussion thread for a member.
 *
 * This test covers the scenario of a member registering, creating a thread, and
 * then creating a poll attached to that thread. It verifies that:
 *
 * - The poll references the correct thread.
 * - The poll is linked to the correct creator (member ID).
 * - All required poll fields are returned and have correct values.
 * - Business logic (thread linkage, creator, config, and prompt) is properly
 *   enforced.
 *
 * Process:
 *
 * 1. Register a discussionboard member via actors/members.create
 * 2. Create a thread for the member (with random category) via
 *    threadsPosts.threads.create
 * 3. Create a poll linked to the thread via polls.create
 * 4. Assert poll fields for correct linkage and config, using typia.assert and
 *    TestValidator checks
 */
export async function test_api_prefix_member_polls_test_create_poll_with_valid_data(
  connection: api.IConnection,
) {
  // 1. Register a new discussion board member
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const createdAt = new Date().toISOString() as string &
    tags.Format<"date-time">;
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId,
        created_at: createdAt,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member);
  TestValidator.equals("memberId matches")(member.id)(memberId);

  // 2. Create a thread as this member
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const threadInput: IDiscussionboardThreads.ICreate = {
    discussionboard_category_id: categoryId,
    title: RandomGenerator.paragraph()(),
    status: "active",
    is_pinned: false,
    is_locked: false,
    archived: false,
    created_at: createdAt,
    updated_at: createdAt,
  };
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: threadInput,
    },
  );
  typia.assert(thread);
  TestValidator.equals("thread.category_id")(
    thread.discussionboard_category_id,
  )(categoryId);
  const threadId = thread.id;

  // 3. Create poll referencing this thread
  const pollPrompt = RandomGenerator.paragraph()();
  const expiresAt = new Date(
    Date.now() + 60 * 60 * 1000,
  ).toISOString() as string & tags.Format<"date-time">;
  const pollInput = {
    discussionboard_thread_id: threadId,
    prompt: pollPrompt,
    allow_multiple_choices: true,
    is_anonymous: false,
    expires_at: expiresAt,
  } satisfies IPoll.ICreate;
  const poll = await api.functional.prefix.member.polls.create(connection, {
    body: pollInput,
  });
