 * allow_multiple_choices, is_anonymous, expires_at).
 *
 * This scenario verifies that a member can update their own poll's editable
 * fields and receive a response reflecting the changes, with ownership enforced
 * by the API.
 *
 * Steps:
 *
 * 1. Register a new member (using IDiscussionboardMembers.ICreate).
 * 2. Create a thread to associate the poll with (using
 *    IDiscussionboardThreads.ICreate).
 * 3. Create a poll as the member for the thread (using IPoll.ICreate), then verify
 *    ownership.
 * 4. Update the poll's mutable fields (prompt, allow_multiple_choices,
 *    is_anonymous, expires_at) via the "PUT /prefix/member//my/polls/{id}"
 *    endpoint.
 * 5. Verify the update response returns the poll with new data and correct owner
 *    ID.
 */
export async function test_api_polls_test_update_own_poll_with_valid_fields(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberInput: IDiscussionboardMembers.ICreate = {
    id: typia.random<string & tags.Format<"uuid">>(),
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    { body: memberInput },
  );
  typia.assert(member);

  // 2. Create a thread (associate to fake a category)
  const threadInput: IDiscussionboardThreads.ICreate = {
    // discussionboard_member_id is optional per schema (set by backend)
    discussionboard_category_id: typia.random<string & tags.Format<"uuid">>(),
    title: "Poll Test Thread",
    status: "active",
    is_pinned: false,
    is_locked: false,
    archived: false,
    created_at: new Date().toISOString() as string & tags.Format<"date-time">,
    updated_at: new Date().toISOString() as string & tags.Format<"date-time">,
  };
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    { body: threadInput },
  );
  typia.assert(thread);

  // 3. Create a poll for the thread
  const pollInput: IPoll.ICreate = {
    discussionboard_thread_id: thread.id,
    prompt: "What is your favorite color?",
    allow_multiple_choices: true,
    is_anonymous: false,
