import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";
import type { IPollVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPollVote";
import type { IPageIPollVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPollVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing poll votes with filter and pagination.
 *
 * 시나리오:
 *
 * 1. 투표를 담당할 회원 여러 명 등록
 * 2. 연관 Poll을 위한 토론 스레드 생성
 * 3. 해당 스레드에 Poll 생성
 * 4. 각 회원이 Poll에 투표 (selected_option 임의 설정)
 * 5. PollVotes 목록을 다양한 필터로 조회 및 검증: a. Poll ID로만 필터 (해당 poll에 속한 투표만 반환되는지) b. 특정
 *    회원 ID로만 필터 (그 회원의 투표만 반환되는지) c. Poll+Member ID 동시 필터 (해당 조합에 투표 있다면 한 개,
 *    없다면 0) d. 필터 없이 전체 조회 (투표 모두 반환되는지, pagination info 확인)
 * 6. 결과 스키마, 조건 필터링, pagination 정보 일치 여부 검증
 *
 * - DTO/엔드포인트 설명에 따라 member/poll/thread/vote 생성은 실제 프로덕션 정의와 일치함
 * - 모든 단계에서 typia.assert로 반환값 스키마 검증, business/paging predicate로 로직점검
 * - Pagination(in response.pagination) 검증은 backend 구현에 따라 범위 내에서 점검
 */
export async function test_api_pollVotes_test_list_poll_votes_with_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. 여러 명 회원 등록 (투표자)
  const memberCount = 5;
  const members = await ArrayUtil.asyncRepeat(memberCount)(async () => {
    const member = await api.functional.prefix.member.actors.members.create(
      connection,
      {
        body: {
          id: typia.random<string & tags.Format<"uuid">>(),
          created_at: new Date().toISOString() as string &
            tags.Format<"date-time">,
        },
      },
    );
    typia.assert(member);
    return member;
  });

  // 2. Thread 생성 (첫 멤버 소유, 카테고리는 별도 생성 API 없으므로 uuid 랜덤)
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: RandomGenerator.paragraph()(10),
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
        updated_at: new Date().toISOString() as string &
          tags.Format<"date-time">,
      },
    },
  );
  typia.assert(thread);

  // 3. Poll 생성 (thread에 대해)
  const poll = await api.functional.prefix.member.polls.create(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      prompt: "어떤 옵션을 선호하십니까?",
      allow_multiple_choices: false,
      is_anonymous: false,
      expires_at: undefined, // 옵션
    },
  });
  typia.assert(poll);

  // 4. 각 회원이 투표 (selected_option "A", "B", "C" 중에서 선택)
  const options = ["A", "B", "C"];
  const votes: IPollVote[] = [];
  for (const member of members) {
    // Note: 실제론 멤버별 로그인 context로 request 해야 하나, 샘플에선 순차 호출 가정
    const vote = await api.functional.prefix.member.pollVotes.create(
      connection,
      {
        body: {
          discussionboard_poll_id: poll.id,
          selected_option: RandomGenerator.pick(options),
        },
      },
    );
    typia.assert(vote);
    votes.push(vote);
  }

  // 5a. poll ID로만 필터 (해당 poll의 투표만 반환)
  const resPoll = await api.functional.prefix.member.pollVotes.index(
    connection,
    {
      body: {
        discussionboard_poll_id: poll.id,
      },
    },
  );
  typia.assert(resPoll);
  TestValidator.predicate("모든 투표가 해당 poll id와 일치하는지")(
    resPoll.data.every((v) => v.discussionboard_poll_id === poll.id),
  );

  // 5b. 특정 회원 투표만 필터
  const firstVote = votes[0];
  const resMember = await api.functional.prefix.member.pollVotes.index(
    connection,
    {
      body: {
        voting_member_id: firstVote.voting_member_id,
      },
    },
  );
  typia.assert(resMember);
  TestValidator.predicate("모든 투표가 해당 member id와 일치하는지")(
    resMember.data.every(
      (v) => v.voting_member_id === firstVote.voting_member_id,
    ),
  );

  // 5c. poll+member 동시 필터 (최대 한 개, 없다면 0)
  const resBoth = await api.functional.prefix.member.pollVotes.index(
    connection,
    {
      body: {
        discussionboard_poll_id: poll.id,
        voting_member_id: firstVote.voting_member_id,
      },
    },
  );
  typia.assert(resBoth);
  TestValidator.predicate("poll+member 조합 결과가 최대 1개")(
    resBoth.data.length <= 1,
  );
  if (resBoth.data.length === 1) {
    const [vote] = resBoth.data;
    TestValidator.equals("poll id")(vote.discussionboard_poll_id)(poll.id);
    TestValidator.equals("member id")(vote.voting_member_id)(
      firstVote.voting_member_id,
    );
  }

  // 5d. 전체 투표 조회 (필터 없음)
  const resAll = await api.functional.prefix.member.pollVotes.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(resAll);
  TestValidator.predicate("테스트 내 votes 모두 존재해야 함")(
    votes.every((vote) => resAll.data.some((d) => d.id === vote.id)),
  );

  // 6. pagination 확인 (lim<voteCount 시 2page 이상 가정, 여기선 단순 페이지meta 확인)
  TestValidator.predicate("응답에 pagination 메타 존재")(
    !!resAll.pagination && typeof resAll.pagination.current === "number",
  );
}

