import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IPoll } from "@ORGANIZATION/PROJECT-api/lib/structures/IPoll";
import type { IPollVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPollVote";
import type { IPageIPollVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIPollVote";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate that a moderator can retrieve all poll votes for a specific poll,
 * using search and pagination features.
 *
 * This end-to-end scenario covers the full business workflow of poll voting
 * analytics and moderation review, as required for forum/poll compliance use
 * cases, and demonstrates that role-based access is correctly respected. The
 * flow also checks that data returned respects filtering by poll ID and that
 * unauthorized roles are blocked from accessing the moderation endpoint.
 *
 * Steps:
 *
 * 1. Register a discussion board member (using a random id and current time).
 * 2. Create a discussion thread as the registered member, specifying required
 *    thread/category info and timestamps.
 * 3. Create a poll attached to that thread (using member context), with a
 *    configurable prompt/question and multi/single select enabled, set to
 *    expire in the future.
 * 4. Simulate multiple members and have them submit poll votes (on the poll
 *    created), so there are several votes to be listed. Ensure votes have
 *    different selected_options to cover search features.
 * 5. Assign moderator role to a member via admin endpoint.
 * 6. From the perspective of this moderator, use the moderator endpoint to fetch
 *    all poll votes for the created poll (using search body with
 *    discussionboard_poll_id filter and reasonable pagination params) and
 *    verify:
 *
 *    - All votes for this poll appear (IDs and options match those submitted).
 *    - Pagination/limit fields are included, and data completeness is maintained.
 *    - Filtering by selected_option or voting_member_id works as expected.
 *    - Only a moderator can successfully access this endpoint; a normal member
 *         attempting this should see a permission error.
 */
export async function test_api_moderator_test_moderator_can_retrieve_all_poll_votes(
  connection: api.IConnection,
) {
  // 1. Register a member
  const memberId1 = typia.random<string & tags.Format<"uuid">>();
  const member1 = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: { id: memberId1, created_at: new Date().toISOString() },
    },
  );
  typia.assert(member1);

  // 2. Create a discussion thread
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const now = new Date();
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: categoryId,
        title: "Poll thread - voting test",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: now.toISOString(),
        updated_at: now.toISOString(),
      },
    },
  );
  typia.assert(thread);

  // 3. Create a poll attached to the thread
  const poll = await api.functional.prefix.member.polls.create(connection, {
    body: {
      discussionboard_thread_id: thread.id,
      prompt: "Choose your favorite color",
      allow_multiple_choices: false,
      is_anonymous: false,
      expires_at: new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString(),
    },
  });
  typia.assert(poll);

  // 4. Register additional members and submit votes for the poll
  const memberId2 = typia.random<string & tags.Format<"uuid">>();
  const member2 = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: { id: memberId2, created_at: new Date().toISOString() },
    },
  );
  typia.assert(member2);

  const memberId3 = typia.random<string & tags.Format<"uuid">>();
  const member3 = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: { id: memberId3, created_at: new Date().toISOString() },
    },
  );
  typia.assert(member3);

  // Each member votes for different options
  const option1 = "red",
    option2 = "blue",
    option3 = "green";

  // Member1 votes 'red'
  // Assume connection simulates acting as member1
  const vote1 = await api.functional.prefix.member.pollVotes.create(
    connection,
    {
      body: {
        discussionboard_poll_id: poll.id,
        selected_option: option1,
      },
    },
  );
  typia.assert(vote1);

  // Member2 votes 'blue'
  // To simulate: would require session-switch if API supported, here just repeat logic
  const vote2 = await api.functional.prefix.member.pollVotes.create(
    connection,
    {
      body: {
        discussionboard_poll_id: poll.id,
        selected_option: option2,
      },
    },
  );
  typia.assert(vote2);

  // Member3 votes 'green'
  const vote3 = await api.functional.prefix.member.pollVotes.create(
    connection,
    {
      body: {
        discussionboard_poll_id: poll.id,
        selected_option: option3,
      },
    },
  );
  typia.assert(vote3);

  // 5. Assign moderator role to member1
  const moderator = await api.functional.prefix.admin.actors.moderators.create(
    connection,
    {
      body: {
        id: member1.id,
        created_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(moderator);

  // 6. As moderator, list/search all votes for this poll
  const pollVotesPage = await api.functional.prefix.moderator.pollVotes.index(
    connection,
    {
      body: { discussionboard_poll_id: poll.id },
    },
  );
  typia.assert(pollVotesPage);
  // Assert that all created votes are present
  const voteIds = pollVotesPage.data.map((v) => v.id);
  TestValidator.predicate("all votes appear")(
    voteIds.includes(vote1.id) &&
      voteIds.includes(vote2.id) &&
      voteIds.includes(vote3.id),
  );
  // Check count
  TestValidator.equals("vote count matches")(pollVotesPage.data.length)(3);
  // Verify filter by selected_option (e.g., 'red')
  const filteredVotes = await api.functional.prefix.moderator.pollVotes.index(
    connection,
    {
      body: { discussionboard_poll_id: poll.id, selected_option: option1 },
    },
  );
  typia.assert(filteredVotes);
  TestValidator.equals("single vote by option")(filteredVotes.data.length)(1);
  TestValidator.equals("correct selected_option")(
    filteredVotes.data[0].selected_option,
  )(option1);
  // Verify pagination meta exists
  TestValidator.predicate("pagination present")(!!pollVotesPage.pagination);

  // 7. As a normal member (not a moderator), access to /moderator/pollVotes should be forbidden (simulate permission error)
  // (Behavior depends on project error handling; here assert error is thrown)
  await TestValidator.error("permission denied for non-moderator")(async () => {
    await api.functional.prefix.moderator.pollVotes.index(connection, {
      body: { discussionboard_poll_id: poll.id },
    });
  });
}

