import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardFilter } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardFilter";
import type { IVoid } from "@ORGANIZATION/PROJECT-api/lib/structures/IVoid";

/**
 * Validates soft-deletion of a user-owned saved filter.
 *
 * This test ensures that, when an authenticated member requests to soft-delete
 * their own filter configuration (by ID), the system sets the filter's
 * deleted_at and excludes it from active listings.
 *
 * Business context:
 *
 * - Members can save (and delete) their own filter configurations (e.g., search
 *   presets) per discussionboard_filters.
 * - Name must be unique per owner while active (deleted_at === null), but
 *   deletion should allow reuse.
 * - Filtering, listing, and actual DB content are out-of-scope for E2E unless
 *   explicit endpoints exist.
 *
 * Steps:
 *
 * 1. Register a new member (minimal fields: id, created_at)
 * 2. [Authentication: If not available as endpoint, assume create is sufficient]
 * 3. As the member, create a saved filter (ICreate): name, definition, is_public
 * 4. Soft-delete (erase) this filter via its ID
 * 5. Re-create a filter using the same name, to confirm soft-deletion excludes
 *    prior record from uniqueness constraint (i.e., old filter is not
 *    considered active)
 * 6. Confirm object identity (new filter.id !== old), i.e., a true new filter is
 *    created and the old one is not blocking
 */
export async function test_api_prefix_member_my_filters_test_soft_delete_owned_filter_with_valid_filter_id(
  connection: api.IConnection,
) {
  // 1. Register a new member
  const memberId: string = typia.random<string & tags.Format<"uuid">>();
  const memberCreatedAt: string = new Date().toISOString();
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId,
        created_at: memberCreatedAt,
      },
    },
  );
  typia.assert(member);

  // 2. Create a saved filter (name must be unique per member, per active record)
  const filterName = `test-filter-${memberId}`;
  const filterToCreate = {
    name: filterName,
    definition: JSON.stringify({ topics: ["economy"], show: "all" }),
    is_public: false,
  } satisfies IDiscussionboardFilter.ICreate;
  const filter = await api.functional.prefix.member.my.filters.create(
    connection,
    {
      body: filterToCreate,
    },
  );
  typia.assert(filter);

  // 3. Soft-delete this filter (by ID)
  await api.functional.prefix.member.my.filters.erase(connection, {
    filterId: filter.id,
  });

  // 4. Re-create a filter with the same name – should succeed, as prior is soft deleted
  const filterAfterDeletion =
    await api.functional.prefix.member.my.filters.create(connection, {
      body: filterToCreate,
    });
  typia.assert(filterAfterDeletion);
  TestValidator.notEquals("filterId changes after soft-delete")(
    filterAfterDeletion.id,
  )(filter.id);
}

