/**
 * Test uniqueness constraint on updating business rule code.
 *
 * Business Context: Business rules (`discussionboard_business_rules`) must have
 * unique `rule_code` values at all times—no two rules may share the same code.
 * This ensures policies are always uniquely addressable and logic cannot be
 * ambiguously mapped.
 *
 * Test Purpose: To verify that when attempting to change one rule's `rule_code`
 * to a value already used by another rule, the API correctly rejects the update
 * with a conflict or validation error, enforcing unique codes as required by
 * business logic.
 *
 * Step-by-step Scenario:
 *
 * 1. Create a first business rule with unique rule_code_1
 * 2. Create a second business rule with unique rule_code_2
 * 3. Attempt to update the second rule's rule_code to rule_code_1
 *
 *    - Confirm API throws a conflict/validation error and does not permit update
 */
export async function test_api_prefix_admin_policyAudit_businessRules_test_update_policy_audit_business_rule_with_duplicate_rule_code(
  connection: api.IConnection,
) {
  // 1. Create a first business rule with a fresh, unique rule_code
  const rule_code_1 = `AUTO_UNIQUE_${RandomGenerator.alphaNumeric(8)}`;
  const ruleOne =
    await api.functional.prefix.admin.policyAudit.businessRules.create(
      connection,
      {
        body: {
          rule_code: rule_code_1,
          title: RandomGenerator.paragraph()(2),
          description: RandomGenerator.content()()(2),
          is_active: true,
        } satisfies IDiscussionboardBusinessRule.ICreate,
      },
    );
  typia.assert(ruleOne);

  // 2. Create a second business rule with a different unique rule_code
  const rule_code_2 = `AUTO_UNIQUE_${RandomGenerator.alphaNumeric(8)}`;
  const ruleTwo =
    await api.functional.prefix.admin.policyAudit.businessRules.create(
      connection,
      {
        body: {
          rule_code: rule_code_2,
          title: RandomGenerator.paragraph()(2),
          description: RandomGenerator.content()()(2),
          is_active: true,
        } satisfies IDiscussionboardBusinessRule.ICreate,
      },
    );
  typia.assert(ruleTwo);

  // 3. Attempt to update the second rule to use the first rule's code (should fail)
  await TestValidator.error("updating with duplicate rule_code should fail")(
    () =>
      api.functional.prefix.admin.policyAudit.businessRules.update(connection, {
        businessRuleId: ruleTwo.id,
        body: {
          rule_code: rule_code_1,
        } satisfies IDiscussionboardBusinessRule.IUpdate,
