/**
 * Verify that a member cannot update their content report after it has been
 * processed by a moderator.
 *
 * This test ensures audit trail and workflow integrity, enforcing that once a
 * moderator reviews or resolves a report, the original member cannot make
 * further amendments. This prevents improper revision of complaints
 * post-decision.
 *
 * Steps:
 *
 * 1. Register a member (reporter) with a unique UUID and current timestamp.
 * 2. Create a thread and post (the content to be reported) as the member. (Use a
 *    mock thread UUID and member's id; member_id not included in ICreate, but
 *    it will be bound by auth context.)
 * 3. File a report on the created post with status 'pending' and include the
 *    reporter's member id, post id, and a report reason.
 * 4. Simulate moderator processing by updating the moderation action for this
 *    report (stub: direct API call as moderator, transitions status away from
 *    'pending' to 'action_taken'/'dismissed'). Use the returned moderation
 *    action's id and populate required fields for update.
 * 5. Attempt to update the content report as the original reporter after
 *    moderation processing. Expect the operation to fail (access denied or
 *    similar error), validating that further edits are forbidden once the
 *    report has entered a terminal, reviewed state.
 *
 * Edge case: Ensure failure is due to workflow state, not missing
 * ownership/auth, network, or other problems.
 */
export async function test_api_contentReports_test_update_content_report_after_moderator_resolution_forbidden(
  connection: api.IConnection,
) {
  // Step 1: Register a member (reporter)
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId,
        created_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(member);

  // Step 2: Create content (a post) to be reported
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: threadId,
        body: "Test content to report",
      },
    },
  );
  typia.assert(post);

  // Step 3: File a content report as the member
  const report = await api.functional.prefix.member.contentReports.create(
    connection,
    {
      body: {
        reported_post_id: post.id,
        reporter_member_id: memberId,
        report_reason: "Offensive or spam content",
        status: "pending",
        reported_at: new Date().toISOString(),
      },
    },
  );
  typia.assert(report);

  // Step 4: Simulate moderator processing - by updating moderation action on the report
  const moderationActionId = typia.random<string & tags.Format<"uuid">>();
  await api.functional.prefix.moderator.my.moderationActions.update(
    connection,
    {
      id: moderationActionId,
      body: {
        report_id: report.id,
        affected_post_id: post.id,
        affected_member_id: memberId,
        action_type: "action_taken",
        action_description: "Report reviewed and content handled",
        action_timestamp: new Date().toISOString(),
      },
    },
  );

  // Step 5: Attempt to update the (now reviewed/processed) report - should fail
  await TestValidator.error(
    "Should not allow updating a report after moderator resolution",
  )(async () => {
    await api.functional.prefix.member.my.contentReports.update(connection, {
      id: report.id,
      body: {
        report_reason: "Trying to add more reason after moderation",
        status: "pending",
      },
