import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardGuests } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardGuests";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IContentReport";

/**
 * 게스트 B가 게스트 A가 작성한 콘텐츠 신고를 수정할 수 없는지 검증하는 테스트입니다.
 *
 * 본 테스트는 방문자(게스트) 소유권 검증 정책이 올바르게 적용되는지 확인합니다.
 *
 * Step-by-step 프로세스:
 *
 * 1. 게스트 A와 게스트 B 두 개의 익명 게스트 세션을 생성합니다.
 * 2. 신고 대상이 될 게시글(포스트)을 만듭니다.
 * 3. 게스트 A 세션으로 해당 게시글에 대해 콘텐츠 신고를 제출합니다.
 * 4. 게스트 B 세션으로 게스트 A가 생성한 신고의 ID를 조회해 동일 신고를 수정 시도합니다.
 * 5. 이때 게스트 B의 수정 요청은 반드시 권한 오류(Authorization Error)로 거절되어야 하며, 서버는 콘텐츠 신고 소유자인
 *    게스트 A만 해당 신고를 수정 가능함을 보장해야 합니다.
 */
export async function test_api_guest_test_guest_cannot_update_other_guests_report(
  connection: api.IConnection,
) {
  // 1. 게스트 A 세션 생성
  const guestA: IDiscussionboardGuests =
    await api.functional.prefix.member.actors.guests.create(connection, {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      },
    });
  typia.assert(guestA);

  // 2. 게스트 B 세션 생성
  const guestB: IDiscussionboardGuests =
    await api.functional.prefix.member.actors.guests.create(connection, {
      body: {
        id: typia.random<string & tags.Format<"uuid">>(),
        created_at: new Date().toISOString(),
      },
    });
  typia.assert(guestB);

  // 3. 신고 대상 게시글 생성
  const post: IDiscussionboardPosts =
    await api.functional.prefix.member.threadsPosts.posts.create(connection, {
      body: {
        discussionboard_thread_id: typia.random<string & tags.Format<"uuid">>(),
        body: "신고 테스트용 게시글 내용입니다.",
      },
    });
  typia.assert(post);

  // 4. 게스트 A를 위한 connection 생성 (headers에 X-Guest-Id)
  const guestAConnection: api.IConnection = {
    ...connection,
    headers: { ...(connection.headers ?? {}), "X-Guest-Id": guestA.id },
  };

  const report: IContentReport =
    await api.functional.prefix.guest.contentReports.create(guestAConnection, {
      body: {
        reported_post_id: post.id,
        reporter_member_id: null,
        reporter_guest_id: guestA.id,
        report_reason: "비방성 글 신고",
        status: "pending",
        reported_at: new Date().toISOString(),
      },
    });
  typia.assert(report);

  // 5. 게스트 B를 위한 connection 생성 (headers에 X-Guest-Id)
  const guestBConnection: api.IConnection = {
    ...connection,
    headers: { ...(connection.headers ?? {}), "X-Guest-Id": guestB.id },
  };

  await TestValidator.error("게스트 B가 게스트 A의 신고를 수정하면 안 됨")(
    async () => {
      await api.functional.prefix.guest.my.contentReports.update(
        guestBConnection,
        {
          id: report.id,
          body: {
            report_reason: "임의 수정시도",
            status: "in_review",
          },
        },
      );
    },
  );
}

