import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardMembers } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardMembers";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IContentReport";

/**
 * Validate that a member can permanently delete their own content report before
 * moderation.
 *
 * This test covers the entire flow:
 *
 * 1. Register a new member (to act as the report owner)
 * 2. Create a post (so there is content to report)
 * 3. File a content report as the member
 * 4. Before any moderation, delete the report using the "erase" endpoint
 * 5. Assert that the report is no longer retrievable and is hard deleted
 */
export async function test_api_contentReports_test_delete_own_content_report_before_moderation(
  connection: api.IConnection,
) {
  // 1. Register a new member (report owner)
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const createdAt = new Date().toISOString();
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId,
        created_at: createdAt,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a post (target for report)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: threadId,
        body: RandomGenerator.paragraph()(),
        is_edited: false,
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(post);

  // 3. File a content report (report by member, status 'pending')
  const report = await api.functional.prefix.member.contentReports.create(
    connection,
    {
      body: {
        reported_post_id: post.id,
        reporter_member_id: member.id,
        reporter_guest_id: null,
        report_reason: RandomGenerator.paragraph()(),
        status: "pending",
        reported_at: new Date().toISOString(),
        moderator_note: null,
      } satisfies IContentReport.ICreate,
    },
  );
  typia.assert(report);
  TestValidator.equals("status is pending")(report.status)("pending");

  // 4. Delete the report (before any moderator action)
  await api.functional.prefix.member.my.contentReports.erase(connection, {
    id: report.id,
  });

  // 5. Confirm the report is hard deleted (second delete should fail)
  await TestValidator.error("report should be permanently removed")(
    async () => {
      await api.functional.prefix.member.my.contentReports.erase(connection, {
        id: report.id,
      });
    },
  );
}

