 */
export async function test_api_member_test_member_cannot_delete_others_report(
  connection: api.IConnection,
) {
  // 1. Register memberA
  const memberAId = typia.random<string & tags.Format<"uuid">>();
  const memberA = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberAId,
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(memberA);

  // 2. Register memberB
