/**
 * Validate that once a member's content report has been reviewed or acted upon
 * by a moderator, the reporting member is forbidden from deleting the report.
 *
 * Scenario process:
 *
 * 1. Register a new member (simulate authenticated context)
 * 2. Create a new discussion post (target for the content report)
 * 3. File a content report as the member on the created post (status: 'pending')
 * 4. Simulate a moderator 'action' (e.g., set status/action via an update using a
 *    moderation action record)
 * 5. Have the original member attempt to delete their own content report (should
 *    be forbidden)
 * 6. Assert that deletion is rejected with error (runtime error thrown)
 *
 * Rationale: Compliance/audit policy demands that reports with moderator
 * actions are preserved.
 */
export async function test_api_contentReports_test_delete_content_report_after_moderator_action_forbidden(
  connection: api.IConnection,
) {
  // 1. Register a new member (system profile only; no credentials required by schema)
  const memberId = typia.random<string & tags.Format<"uuid">>();
  const memberCreatedAt = new Date().toISOString();
  const member = await api.functional.prefix.member.actors.members.create(
    connection,
    {
      body: {
        id: memberId,
        created_at: memberCreatedAt,
      } satisfies IDiscussionboardMembers.ICreate,
    },
  );
  typia.assert(member);

  // 2. Create a post (the content that will be reported)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: threadId,
        parent_post_id: null,
        body: "Reported post body " + RandomGenerator.content()()(),
        is_edited: false,
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(post);

  // 3. Member files a content report (status: 'pending')
  const contentReport =
    await api.functional.prefix.member.contentReports.create(connection, {
      body: {
        reported_post_id: post.id,
        reporter_member_id: memberId,
        reporter_guest_id: null,
        report_reason: "Spam or inappropriate content",
        status: "pending",
        reported_at: new Date().toISOString(),
        moderator_note: null,
      } satisfies IContentReport.ICreate,
    });
  typia.assert(contentReport);

  // 4. Simulate moderator updates (create a moderation action record to lock report)
  //   - For this test, we just need an IModerationAction.IUpdate and a dummy moderationActionId.
  //   - The link is report_id === contentReport.id
  const moderationActionId = typia.random<string & tags.Format<"uuid">>();
  const actionTimestamp = new Date().toISOString();
  const moderationAction =
    await api.functional.prefix.moderator.my.moderationActions.update(
      connection,
