        id: moderationActionId,
        body: {
          report_id: contentReport.id,
          affected_post_id: post.id,
          affected_member_id: memberId,
          action_type: "action_taken",
          action_description: "Moderator acted upon report (locking it)",
          action_timestamp: actionTimestamp,
        } satisfies IModerationAction.IUpdate,
      },
    );
  typia.assert(moderationAction);

  // 5. Member attempts to delete the now-locked report (must fail)
  await TestValidator.error("delete forbidden after moderator action")(
    async () => {
      await api.functional.prefix.member.my.contentReports.erase(connection, {
        id: contentReport.id,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

