  // 5. Guest B attempts to delete Guest A's report
  //    In a full E2E, connection/session would reflect Guest B context (session ID, cookie, etc.)
  //    Here, we attempt deletion and expect an error because Guest B does not own the report.
  await TestValidator.error("Guest B cannot delete Guest A's content report")(
    async () => {
      // Ideally, simulate Guest B's session here
      await api.functional.prefix.guest.my.contentReports.erase(connection, {
        id: contentReport.id,
      });
    },
