import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { IModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationAction";
import type { IPageIModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIModerationAction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 다양한 필터로 모더레이션(중재) 액션 목록을 조회하는 기능을 검증합니다.
 *
 * 1. 여러 명의 모더레이터 계정(권한자, actor)을 생성합니다.
 * 2. 여러 종류의 moderation action (report/affected_post/affected_member/action_type/시간
 *    등 조합)을 생성합니다.
 * 3. 아래 조합별로 PATCH /prefix/moderator//moderationActions API로 목록을 조회하고 결과가 입력 조건과
 *    부합하는지 검증합니다.
 *
 *    - ① 모더레이터 id별 필터
 *    - ② action_type별 필터
 *    - ③ affected_post_id/affected_member_id 별 필터
 *    - ④ action_timestamp 범위 필터
 *    - ⑤ 전체 목록 (페이징 포함) 필터 없이 조회 (목록/페이지네이션 구조 및 카운트 검증)
 *
 * - 각 필터 조합 시, 응답 목록(각 moderation action)의 데이터가 조건을 정확히 반영하며, 부정확한 값이 한 건도 혼입되지
 *   않는지, pagination 구조와 전체 카운트, 페이지 크기, 페이지별 분할이 명확히 동작하는지 TestValidator 기반으로
 *   모두 검증합니다.
 */
export async function test_api_moderationActions_test_list_moderation_actions_with_various_filters(
  connection: api.IConnection,
) {
  // 1. 여러 명의 모더레이터 계정(3명) 생성
  const modCount = 3;
  const moderators: IDiscussionboardModerator[] = [];
  for (let i = 0; i < modCount; ++i) {
    const mod: IDiscussionboardModerator =
      await api.functional.prefix.admin.actors.moderators.create(connection, {
        body: {
          id: typia.random<string & tags.Format<"uuid">>(),
          created_at: new Date(
            Date.now() - (modCount - i) * 60 * 60 * 1000,
          ).toISOString() as string & tags.Format<"date-time">,
        } satisfies IDiscussionboardModerator.ICreate,
      });
    typia.assert(mod);
    moderators.push(mod);
  }

  // 2. moderation actions 다양한 조합으로 여러 개(12개) 생성
  // 일부는 report_id, 일부는 affected_post_id, 일부는 affected_member_id를 다르게 설정
  // action_type/anction_description/action_timestamp도 서로 다르게 분산
  const reports = ArrayUtil.repeat(4)(() =>
    typia.random<string & tags.Format<"uuid">>(),
  );
  const posts = ArrayUtil.repeat(4)(() =>
    typia.random<string & tags.Format<"uuid">>(),
  );
  const members = ArrayUtil.repeat(4)(() =>
    typia.random<string & tags.Format<"uuid">>(),
  );
  const types = ["warned", "deleted_post", "suspended_user", "archived_thread"];
  const now = Date.now();
  const moderationActions: IModerationAction[] = [];
  for (let i = 0; i < 12; ++i) {
    const mod = moderators[i % 3];
    const action_type = types[i % types.length];
    const report_id = i % 2 === 0 ? reports[i % reports.length] : null;
    const affected_post_id = i % 3 === 0 ? posts[i % posts.length] : null;
    const affected_member_id = i % 4 === 0 ? members[i % members.length] : null;
    const action_timestamp = new Date(
      now - i * 30 * 60 * 1000,
    ).toISOString() as string & tags.Format<"date-time">;

    const created: IModerationAction =
      await api.functional.prefix.moderator.moderationActions.create(
        connection,
        {
          body: {
            moderator_id: mod.id,
            report_id,
            affected_post_id,
            affected_member_id,
            action_type,
            action_description: `테스트 중재 액션(${i})`,
            action_timestamp,
          } satisfies IModerationAction.ICreate,
        },
      );
    typia.assert(created);
    moderationActions.push(created);
  }

  // 3-1) 모더레이터 id로 필터
  for (const mod of moderators) {
    const resp = await api.functional.prefix.moderator.moderationActions.index(
      connection,
      {
        body: { moderator_id: mod.id },
      },
    );
    typia.assert(resp);
    for (const m of resp.data) {
      TestValidator.equals("moderator_id 필터")(m.moderator_id)(mod.id);
    }
  }

  // 3-2) action_type별 필터
  for (const action_type of types) {
    const resp = await api.functional.prefix.moderator.moderationActions.index(
      connection,
      {
        body: { action_type },
      },
    );
    typia.assert(resp);
    for (const m of resp.data) {
      TestValidator.equals("action_type 필터")(m.action_type)(action_type);
    }
  }

  // 3-3) affected_post_id, affected_member_id 별
  for (const post_id of posts) {
    const resp = await api.functional.prefix.moderator.moderationActions.index(
      connection,
      {
        body: { affected_post_id: post_id },
      },
    );
    typia.assert(resp);
    for (const m of resp.data) {
      TestValidator.equals("affected_post_id 필터")(m.affected_post_id)(
        post_id,
      );
    }
  }
  for (const member_id of members) {
    const resp = await api.functional.prefix.moderator.moderationActions.index(
      connection,
      {
        body: { affected_member_id: member_id },
      },
    );
    typia.assert(resp);
    for (const m of resp.data) {
      TestValidator.equals("affected_member_id 필터")(m.affected_member_id)(
        member_id,
      );
    }
  }

  // 3-4) action_timestamp 범위 (가장 최근 2시간 내 것만)
  const from = new Date(now - 2 * 60 * 60 * 1000).toISOString() as string &
    tags.Format<"date-time">;
  const to = new Date(now + 3 * 60 * 1000).toISOString() as string &
    tags.Format<"date-time">; // 약간 미래 포함
  const respRange =
    await api.functional.prefix.moderator.moderationActions.index(connection, {
      body: {
        action_timestamp_from: from,
        action_timestamp_to: to,
      },
    });
  typia.assert(respRange);
  for (const m of respRange.data) {
    TestValidator.predicate("action_timestamp 범위 필터")(
      m.action_timestamp >= from && m.action_timestamp <= to,
    );
  }

  // 3-5) 전체 목록 필터 없이 (페이지네이션 포함)
  // limit=5, page=1,2로 나누어 조회
  const respAllPage1 =
    await api.functional.prefix.moderator.moderationActions.index(connection, {
      body: {
        limit: 5 as number &
          tags.Type<"int32"> &
          tags.Minimum<1> &
          tags.Maximum<200>,
        page: 1 as number & tags.Type<"int32"> & tags.Minimum<1>,
      },
    });
  typia.assert(respAllPage1);

  const respAllPage2 =
    await api.functional.prefix.moderator.moderationActions.index(connection, {
      body: {
        limit: 5 as number &
          tags.Type<"int32"> &
          tags.Minimum<1> &
          tags.Maximum<200>,
        page: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
      },
    });
  typia.assert(respAllPage2);

  // 모든 moderationActions 개수와 일치하는지, 페이지 합계 및 분할 구조 검증
  const totalCount = moderationActions.length;
  const page1Count = respAllPage1.data.length;
  const page2Count = respAllPage2.data.length;
  TestValidator.equals("전체 카운트는 전체 moderationActions 수와 일치")(
    respAllPage1.pagination.records + respAllPage2.pagination.records,
  )(2 * totalCount);
  TestValidator.predicate("페이지별 record 분할 합")(
    page1Count + page2Count <= totalCount,
  );
  TestValidator.equals("limit 설정 적용")(respAllPage1.pagination.limit)(5);
  TestValidator.equals("limit 설정 적용")(respAllPage2.pagination.limit)(5);
  TestValidator.equals("페이지네이션 구조")(respAllPage1.pagination.pages >= 2)(
    true,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationAction";
import type { IPageIModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIModerationAction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * 올바르지 않거나 잘못된 쿼리 필터를 PATCH 요청 바디로 전달했을 때, 서비스가 400 Bad Request 등 적절한 오류로 거부하고
 * 클라이언트에 명확한 피드백을 주는지 테스트합니다.
 *
 * - 각 필터 필드에 대해 유효하지 않은 데이터 타입(예: string이어야 하는데 number, 잘못된 date 포맷 등)으로 요청 시
 *   실패하는지 검증합니다.
 * - 허용되지 않은/정의되지 않은 필드가 포함된 경우 명확히 거부하는지 확인합니다.
 * - 구조적으로 잘못된 바디(배열이나 null 등)가 전달될 때도 400 오류 등으로 명확하게 실패하는지 체크합니다.
 * - 성공 케이스는 필요하지 않으며, 오직 실패(의도된 예외) 상황만 TestValidator.error로 검증합니다.
 *
 * 테스트 시나리오:
 *
 * 1. Moderator_id에 잘못된 타입(숫자) 전달
 * 2. 스키마에 없는 필드(removal_reason) 포함
 * 3. 전체 바디가 배열로 전달되는 경우
 * 4. 바디가 null인 경우
 * 5. Action_timestamp_from에 잘못된 날짜 포맷 전달
 */
export async function test_api_moderationActions_test_list_moderation_actions_invalid_query_fails_gracefully(
  connection: api.IConnection,
) {
  // 1. moderator_id에 잘못된 타입(숫자)
  await TestValidator.error("moderator_id 잘못된 타입 400 오류")(() =>
    api.functional.prefix.moderator.moderationActions.index(connection, {
      body: {
        moderator_id: 42 as any, // number → uuid여야 하므로 실패
      },
    }),
  );

  // 2. 스키마 외 필드(removal_reason) 포함
  await TestValidator.error("허용되지 않은 필드 400 오류")(() =>
    api.functional.prefix.moderator.moderationActions.index(connection, {
      body: {
        removal_reason: "스팸",
      } as any, // 스키마에 없는 속성
    }),
  );

  // 3. body가 배열로 전달
  await TestValidator.error("body가 배열이면 400 오류")(() =>
    api.functional.prefix.moderator.moderationActions.index(connection, {
      body: [] as any,
    }),
  );

  // 4. body가 null로 전달
  await TestValidator.error("body가 null이면 400 오류")(() =>
    api.functional.prefix.moderator.moderationActions.index(connection, {
      body: null as any,
    }),
  );

  // 5. action_timestamp_from에 잘못된 날짜 포맷
  await TestValidator.error("action_timestamp_from 잘못된 포맷 400 오류")(() =>
    api.functional.prefix.moderator.moderationActions.index(connection, {
      body: {
        action_timestamp_from: "not-a-date",
      } as any,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardModerator";
import type { IModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IModerationAction";
import type { IPageIModerationAction } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIModerationAction";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test the correct implementation of pagination and sorting in moderation
 * actions listing.
 *
 * This test verifies API paging for moderation actions: with a deterministic
 * moderator and a bulk set of actions with strictly ascending timestamps, it
 * ensures paginated results are correct by `limit` and `page`, and that result
 * lists are in the requested order by `action_timestamp`.
 *
 * Steps:
 *
 * 1. Setup: Create a moderator (admin context) for whom actions will be generated.
 * 2. Bulk create: Create a sequence of moderation actions for this moderator, each
 *    with a unique, ascending timestamp. All required fields are set, and
 *    nullable ones use `null`.
 * 3. Paginate ascending: Query pages in order, checking the IDs and order of each
 *    result page against our local sequence; verify full record count,
 *    completeness, and no duplication across pages.
 * 4. Descending order: (API does not provide sort param) — explain/test design
 *    with local sort for completeness, noting the limitation.
 * 5. Edge: Fetch the last page and verify length is correct (not always full
 *    page).
 */
export async function test_api_moderationActions_test_list_moderation_actions_pagination_and_sorting(
  connection: api.IConnection,
) {
  // 1. Setup moderator via admin API
  const moderatorId: string = typia.random<string & tags.Format<"uuid">>();
  const moderatorCreatedAt: string = new Date().toISOString();
  const moderator = await api.functional.prefix.admin.actors.moderators.create(
    connection,
    {
      body: {
        id: moderatorId,
        created_at: moderatorCreatedAt,
      },
    },
  );
  typia.assert(moderator);

  // 2. Bulk-create moderation actions at unique timestamps
  const baseTime = new Date();
  const moderationActions: IModerationAction[] = [];
  for (let i = 0; i < 17; ++i) {
    // Ensure unique, monotonic timestamps
    const actionTimestamp = new Date(
      baseTime.getTime() + i * 60000,
    ).toISOString();
    const created =
      await api.functional.prefix.moderator.moderationActions.create(
        connection,
        {
          body: {
            moderator_id: moderator.id,
            report_id: null,
            affected_post_id: null,
            affected_member_id: null,
            action_type: `test_type_${i}`,
            action_description: `Bulk moderation action #${i}`,
            action_timestamp: actionTimestamp,
          },
        },
      );
    typia.assert(created);
    moderationActions.push(created);
  }

  // Sort expected actions ascending by timestamp
  const limit = 5;
  const total = moderationActions.length;
  const totalPages = Math.ceil(total / limit);
  const ascSorted = moderationActions
    .slice()
    .sort((a, b) => a.action_timestamp.localeCompare(b.action_timestamp));
  // To track uniqueness across all returned results
  const seenIds = new Set<string>();
  for (let page = 1; page <= totalPages; ++page) {
    const output =
      await api.functional.prefix.moderator.moderationActions.index(
        connection,
        {
          body: {
            moderator_id: moderator.id,
            limit,
            page,
          },
        },
      );
    typia.assert(output);
    // IDs in API result must match expected for this page
    const expected = ascSorted.slice((page - 1) * limit, page * limit);
    TestValidator.equals(`page ${page} moderation action ids`)(
      output.data.map((x) => x.id),
    )(expected.map((x) => x.id));
    // Pagination fields must be correct
    TestValidator.equals(`pagination record count`)(output.pagination.records)(
      total,
    );
    TestValidator.equals(`pagination page num`)(output.pagination.current)(
      page,
    );
    TestValidator.equals(`pagination page size`)(output.pagination.limit)(
      limit,
    );
    // Check global uniqueness: no overlap
    for (const x of output.data) {
      if (seenIds.has(x.id))
        throw new Error(
          `Duplicate moderation action id in paged results: ${x.id}`,
        );
      seenIds.add(x.id);
    }
  }

  // 4. Descending test (no API sort order param). For design completeness only:
  // If API later adds sort order, could test reverse order here.
  // const descSorted = moderationActions.slice().sort((a, b) => b.action_timestamp.localeCompare(a.action_timestamp));
  // ...

  // 5. Edge: Last page may not be full, check item count
  const lastPage = totalPages;
  const finalPage =
    await api.functional.prefix.moderator.moderationActions.index(connection, {
      body: {
        moderator_id: moderator.id,
        limit,
        page: lastPage,
      },
    });
  typia.assert(finalPage);
