import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardConfiguration";
import type { IPageIDiscussionboardConfiguration } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionboardConfiguration";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test admin paginated and filtered retrieval of discussion board
 * configurations
 *
 * This test ensures that an admin can successfully retrieve a paginated and
 * filtered list of discussion board configurations. It verifies that filtering
 * by key fields works, that pagination and sorting behave as expected, and that
 * the response matches the configurations actually created.
 *
 * Process:
 *
 * 1. Create several discussion board configurations with distinct names and
 *    descriptions.
 * 2. Use the PATCH endpoint to request a page of configurations filtered by name
 *    (containing 'config'), sorted ascending, with page=1 and limit=2.
 * 3. Check that only the correct configurations are returned in the correct order,
 *    with pagination metadata accurate.
 * 4. Assert that every returned configuration in the response exactly matches the
 *    created data.
 */
export async function test_api_discussionboardconfiguration_test_list_configurations_with_pagination_and_filters(
  connection: api.IConnection,
) {
  // 1. Create three configurations with unique names/descriptions
  const configs = await Promise.all([
    api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      {
        body: {
          name: "alpha-config",
          settings_json: JSON.stringify({ polls: true, mod: "A" }),
          description: "For alpha module tests.",
        } satisfies IDiscussionboardConfiguration.ICreate,
      },
    ),
    api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      {
        body: {
          name: "beta-config",
          settings_json: JSON.stringify({ polls: false, mod: "B" }),
          description: "Beta features section.",
        } satisfies IDiscussionboardConfiguration.ICreate,
      },
    ),
    api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      {
        body: {
          name: "gamma-policy",
          settings_json: JSON.stringify({ polls: true, mod: "C" }),
          description: "Experimental gamma policies.",
        } satisfies IDiscussionboardConfiguration.ICreate,
      },
    ),
  ]);
  configs.forEach((config) => typia.assert(config));

  // 2. Query with name filter, pagination = page 1, limit 2, and sorting by name ascending
  const page =
    await api.functional.prefix.admin.discussionboardConfigurations.index(
      connection,
      {
        body: {
          filters: { name: { contains: "config" } },
          sort: ["name:asc"],
          page: 1,
          limit: 2,
        } satisfies IDiscussionboardConfiguration.IRequest,
      },
    );
  typia.assert(page);

  // 3. Validate the response: only configs with 'config' in the name and correct sort
  TestValidator.equals("page current")(page.pagination.current)(1);
  TestValidator.equals("page limit")(page.pagination.limit)(2);
  TestValidator.predicate("all config names contain 'config'")(
    page.data.every((row) => row.name.includes("config")),
  );
  TestValidator.equals("configs returned in order")(
    page.data.map((row) => row.name),
  )(["alpha-config", "beta-config"]);

  // 4. Each config should match those originally created
  for (const config of page.data) {
    const orig = configs.find((c) => c.id === config.id);
    TestValidator.equals("id")(config.id)(orig?.id);
    TestValidator.equals("name")(config.name)(orig?.name);
    TestValidator.equals("settings_json")(config.settings_json)(
      orig?.settings_json,
    );
    TestValidator.equals("description")(config.description)(orig?.description);
  }
}

