/**
 * Validate applying a nonexistent-name filter to discussion board
 * configurations returns empty results with correct pagination.
 *
 * This test ensures the endpoint returns zero items (with properly structured
 * pagination metadata) when filtering by a unique configuration name that does
 * not exist. The test process is:
 *
 * 1. Create at least one configuration to guarantee the database is non-empty.
 * 2. List configurations using a filter on a name that is guaranteed distinct (not
 *    in DB).
 * 3. Assert response data array is empty and pagination.records is zero.
 * 4. Assert other pagination metadata is correct (current page, page size, total
 *    pages).
 */
export async function test_api_discussionboardConfigurations_test_list_configurations_no_results_for_nonexistent_filter(
  connection: api.IConnection,
) {
  // 1. Create at least one configuration to ensure non-empty database
  const config: IDiscussionboardConfiguration =
    await api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      {
        body: {
          name: `autotest_config_${Date.now()}_${Math.random()}`,
          settings_json: JSON.stringify({
            enabled: true,
            moderation: "strict",
          }),
          description: "Autotest configuration for no-result filter case.",
        } satisfies IDiscussionboardConfiguration.ICreate,
      },
    );
  typia.assert(config);

  // 2. Compose a unique, guaranteed-unused name for the filter
  const uniqueName = `nonexistent_name_filter_${Date.now()}_${Math.random()}`;

  // 3. List configurations filtering by that uniquely unused name
  const result =
    await api.functional.prefix.admin.discussionboardConfigurations.index(
      connection,
      {
        body: {
          filters: { name: uniqueName },
          page: 1,
          limit: 20,
        } satisfies IDiscussionboardConfiguration.IRequest,
      },
    );
