 * retrieved after creation, by its unique identifier. It simulates a real admin
 * workflow: the admin creates a new configuration (with unique content),
 * receives the generated UUID, then fetches the configuration by that UUID. The
 * test strictly checks that all fields in the retrieved record match the ones
 * provided during creation (including description/nullability), ensuring
 * round-trip data integrity and API contract.
 *
 * Steps:
 *
 * 1. Create a new discussion board configuration (POST
 *    /prefix/admin//discussionboardConfigurations) with clearly identifiable
 *    data
 * 2. Retrieve the configuration by returned id (GET
 *    /prefix/admin//discussionboardConfigurations/{configurationId})
 * 3. Assert HTTP 200 OK and validate that all returned fields match creation input
 *    and output conforms to IDiscussionboardConfiguration schema
 */
export async function test_api_discussionboardConfigurations_test_get_existing_configuration_by_id(
  connection: api.IConnection,
) {
  // 1. Create a new configuration
  const createInput: IDiscussionboardConfiguration.ICreate = {
    name: `config_${RandomGenerator.alphaNumeric(8)}`,
    settings_json: JSON.stringify({ enabled: true, maxPollOptions: 4 }),
    description: RandomGenerator.paragraph()(),
  };
  const created: IDiscussionboardConfiguration =
    await api.functional.prefix.admin.discussionboardConfigurations.create(
      connection,
      {
        body: createInput,
      },
    );
  typia.assert(created);

  // 2. Retrieve configuration by ID
  const retrieved: IDiscussionboardConfiguration =
    await api.functional.prefix.admin.discussionboardConfigurations.at(
      connection,
