        >(),
        title: "Ownership check thread",
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: now,
        updated_at: now,
      } satisfies IDiscussionboardThreads.ICreate,
    },
  );
  typia.assert(thread);

  // 2. 아카이브 수행(소프트 삭제) → 아카이브 레코드 생성
  await api.functional.prefix.member.my.threadsPosts.threads.erase(connection, {
    id: thread.id,
  });

  // 3. (아카이브 레코드의 ID 획득: 테스트 시스템에서 thread.id와 1:1 매핑 적용 가정)
  const archiveId = thread.id as string & tags.Format<"uuid">;

  // 4. 타 회원(B) 전환 – 실제 로그인/토큰 등은 테스트 인프라가 보장한다고 가정
  // 이 connection은 Member B로 변환되었음이 전제.

  // 5. 타 회원(B)이 아카이브 레코드 수정 시도 → 금지(403)/없음(404) 오류 검증
  await TestValidator.error("비소유자 회원의 스레드 아카이브 수정 불가")(
    async () => {
      await api.functional.prefix.member.my.threadsPosts.threadArchives.update(
        connection,
        {
          id: archiveId,
          body: {
            archive_reason: "Attempted update by non-owner",
