files.test/features/api/moderator/test_list_co:
import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardPosts } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardPosts";
import type { IContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IContentReport";
import type { IPageIContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIContentReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate moderator content report listing with comprehensive filter, search,
 * and pagination behaviors.
 *
 * This test creates a post, then generates several content reports targetting
 * that post, with variant statuses, reasons, and reporter identities. It checks
 * all filter and pagination logic for the moderator's listing API, including
 * single and combined filter fields, as well as pagination. Negative testing is
 * covered by TypeScript type safety: the API cannot be called with fields not
 * permitted by the filter schema.
 */
export async function test_api_prefix_moderator_test_list_content_reports_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create a post to be reported
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.prefix.member.threadsPosts.posts.create(
    connection,
    {
      body: {
        discussionboard_thread_id: threadId,
        body: "Post to be reported",
        is_edited: false,
      } satisfies IDiscussionboardPosts.ICreate,
    },
  );
  typia.assert(post);

  // 2. Register content reports with various reporters, reasons, statuses
  const reporter_member1 = typia.random<string & tags.Format<"uuid">>();
  const reporter_member2 = typia.random<string & tags.Format<"uuid">>();
  // Timestamps (latest-first)
  const timestamps = [
    new Date(Date.now() - 1000 * 60 * 60 * 4).toISOString(),
    new Date(Date.now() - 1000 * 60 * 60 * 3).toISOString(),
    new Date(Date.now() - 1000 * 60 * 60 * 2).toISOString(),
    new Date(Date.now() - 1000 * 60 * 60 * 1).toISOString(),
  ];

  const reportsData = [
    {
      reporter_member_id: reporter_member1,
      reason: "spam",
      status: "pending",
      at: timestamps[0],
    },
    {
      reporter_member_id: reporter_member2,
      reason: "harassment",
      status: "in_review",
      at: timestamps[1],
    },
    {
      reporter_member_id: reporter_member1,
      reason: "offtopic",
      status: "action_taken",
      at: timestamps[2],
    },
    {
      reporter_member_id: reporter_member2,
      reason: "other",
      status: "dismissed",
      at: timestamps[3],
    },
  ];

  const createdReports: IContentReport[] = [];
  for (const r of reportsData) {
    const report = await api.functional.prefix.member.contentReports.create(
      connection,
      {
        body: {
          reported_post_id: post.id,
          reporter_member_id: r.reporter_member_id,
          report_reason: r.reason,
          status: r.status as
            | "pending"
            | "in_review"
            | "action_taken"
            | "dismissed",
          reported_at: r.at,
        } satisfies IContentReport.ICreate,
      },
    );
    typia.assert(report);
    createdReports.push(report);
  }

  // 3a. Filter by status
  let output = await api.functional.prefix.moderator.contentReports.index(
    connection,
    { body: { status: "pending" } },
  );
  typia.assert(output);
  TestValidator.equals("status filter")(
    output.data.every((r) => r.status === "pending"),
  )(true);

  // 3b. Filter by report_reason
  output = await api.functional.prefix.moderator.contentReports.index(
    connection,
    { body: { report_reason: "spam" } },
  );
  typia.assert(output);
  TestValidator.equals("reason filter")(
    output.data.every((r) => r.report_reason === "spam"),
  )(true);

  // 3c. Filter by reporter_member_id
  output = await api.functional.prefix.moderator.contentReports.index(
    connection,
    { body: { reporter_member_id: reporter_member1 } },
  );
  typia.assert(output);
  TestValidator.equals("reporter filter")(
    output.data.every((r) => r.reporter_member_id === reporter_member1),
  )(true);

  // 3d. Pagination
  output = await api.functional.prefix.moderator.contentReports.index(
    connection,
    { body: { limit: 2, page: 2 } },
  );
  typia.assert(output);
  TestValidator.equals("pagination limit")(output.pagination.limit)(2);
  TestValidator.equals("pagination page")(output.pagination.current)(2);

  // 3e. Combined filters
  output = await api.functional.prefix.moderator.contentReports.index(
    connection,
    {
      body: {
        status: "action_taken",
        report_reason: "offtopic",
        reporter_member_id: reporter_member1,
      },
    },
  );
  typia.assert(output);
  TestValidator.equals("combined filter result count")(output.data.length)(
    createdReports.filter(
      (r) =>
        r.status === "action_taken" &&
        r.report_reason === "offtopic" &&
        r.reporter_member_id === reporter_member1,
    ).length,
  );

  // 4. Negative test: TypeScript type checking prevents non-schema fields in the filter;
  // it is not possible to call the API with an unsupported field (enforced at compile time).
}

