import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IContentReport";
import type { IPageIContentReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIContentReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test that when a moderator lists content reports but no reports exist or the
 * filters yield no matches, the API correctly returns an empty dataset and
 * accurate pagination metadata.
 *
 * Business case: This ensures moderation tooling gracefully handles zero-result
 * scenarios, returning consistent, predictable API structures regardless of
 * dataset contents or filter criteria.
 *
 * Steps:
 *
 * 1. List content reports with no filters (expecting empty if the database is
 *    empty).
 * 2. List content reports with an impossible filter (UUIDs not found, nonsense
 *    status, future-from/past-to time window, out-of-bounds page).
 * 3. After each, assert the data array is empty and pagination info shows zero
 *    records/pages.
 */
export async function test_api_prefix_moderator_contentReports_test_list_content_reports_empty_result(
  connection: api.IConnection,
) {
  // 1. List with no filters (should yield empty if there are no reports)
  const respEmpty = await api.functional.prefix.moderator.contentReports.index(
    connection,
    {
      body: {},
    },
  );
  typia.assert(respEmpty);
  TestValidator.equals("empty data array for no reports")(respEmpty.data)([]);
  TestValidator.equals("no records in pagination")(
    respEmpty.pagination.records,
  )(0);
  TestValidator.equals("no pages in pagination")(respEmpty.pagination.pages)(0);

  // 2. List with an impossible filter (guaranteed non-match)
  const impossibleFilter = {
    reporter_member_id: typia.random<string & tags.Format<"uuid">>(),
    reporter_guest_id: typia.random<string & tags.Format<"uuid">>(),
    status: "no_such_status",
    reported_from: "2099-01-01T00:00:00Z",
    reported_to: "2000-01-01T00:00:00Z",
    page: 9999,
    limit: 100,
  };
  const respNoMatch =
    await api.functional.prefix.moderator.contentReports.index(connection, {
      body: impossibleFilter,
    });
  typia.assert(respNoMatch);
  TestValidator.equals("empty data array for impossible filter")(
    respNoMatch.data,
  )([]);
  TestValidator.equals("no records in pagination")(
    respNoMatch.pagination.records,
  )(0);
  TestValidator.equals("no pages in pagination")(respNoMatch.pagination.pages)(
    0,
  );
}

