import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionboardThreads } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardThreads";
import type { IThreadTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IThreadTag";
import type { IDiscussionboardTaggedThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionboardTaggedThread";

/**
 * 토론 스레드-태그 연결(association) 레코드의 정상 삭제 검증 E2E 테스트입니다.
 *
 * 비즈니스 시나리오:
 *
 * 1. 회원이 직접 토론 스레드를 생성
 * 2. 회원이 직접 스레드 태그를 생성
 * 3. 방금 생성한 thread와 tag를 연결하는 taggedThread 레코드 생성
 * 4. 해당 연결을 삭제(erase) API로 정상 삭제
 *
 * 삭제 후, 해당 id의 단건 상세조회 엔드포인트가 미제공되어 API를 통한 직접적 존재 검증은 불가. 일반적으로 목록 조회로 받는
 * data에 포함되지 않아야 하나, 이 코드는 지정 요구 범위 내에서 정상적으로 삭제 API만 검증
 */
export async function test_api_taggedThreads_test_delete_tagged_thread_association_success(
  connection: api.IConnection,
) {
  // 1. 토론 스레드 생성
  const thread = await api.functional.prefix.member.threadsPosts.threads.create(
    connection,
    {
      body: {
        discussionboard_category_id: typia.random<
          string & tags.Format<"uuid">
        >(),
        title: RandomGenerator.paragraph()(6, 20),
        status: "active",
        is_pinned: false,
        is_locked: false,
        archived: false,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      } satisfies IDiscussionboardThreads.ICreate,
    },
  );
  typia.assert(thread);

  // 2. 스레드 태그 생성
  const tag = await api.functional.prefix.member.threadTags.create(connection, {
    body: {
      code: RandomGenerator.alphaNumeric(8).toLowerCase(),
      display_name: RandomGenerator.paragraph()(2, 8),
      description: RandomGenerator.paragraph()(2, 8),
      is_restricted: false,
      is_hidden: false,
      created_at: new Date().toISOString(),
    } satisfies IThreadTag.ICreate,
  });
  typia.assert(tag);

  // 3. thread-tag 연결 생성
  const taggedThread = await api.functional.prefix.member.taggedThreads.create(
    connection,
    {
      body: {
        discussionboard_thread_id: thread.id,
        discussionboard_thread_tag_id: tag.id,
        created_at: new Date().toISOString(),
      } satisfies IDiscussionboardTaggedThread.ICreate,
    },
  );
  typia.assert(taggedThread);

  // 4. 연결 삭제
  await api.functional.prefix.member.taggedThreads.erase(connection, {
    taggedThreadId: taggedThread.id,
  });
}

